D.Strings[67]="快……逃命吧……"
D.Strings[68]="我们不能再犹豫了！"
D.Strings[69]="让这些小鬼离我远点！"
D.Strings[70]=S[11528]
D.Strings[71]="必须终止军团的入侵。"
D.Strings[72]="绝不留情。欺诈者必须死。"
D.Strings[73]="<阿坎恩语无伦次地自言自语。>"
