D.Strings[77]="攻击还在继续。"
D.Strings[78]="救命啊！我动不了了！"
D.Strings[79]="全队……立正！……集合！"
D.Strings[80]="前进……前进！"
D.Strings[81]="来，让我们击掌为盟，就像文明人那样。"
D.Strings[82]="太感谢你了！"
D.Strings[83]="跟着我，$n。我会把你带到迪菲亚兄弟会的老巢里。但是你最好能保护我，不然我就死定了。"
D.Strings[84]="入口就隐藏在月溪镇里。注意那些盗贼，他们想要我的命。"
D.Strings[85]="你可以去告诉斯托曼，这里就是迪菲亚盗贼的藏身之处，$n。"
D.Strings[86]="干活，你们这帮废物！"
D.Strings[87]="啊啊啊啊！白痴！"
D.Strings[88]="毫无价值的废物！"
D.Strings[89]="好了，伙计们，振作些！"
D.Strings[90]="弟兄们，该起床了！"
D.Strings[91]="嘿，跟着我！"
D.Strings[92]="又弄来了一头！"
D.Strings[93]="我来了，我准备重新加入……"
D.Strings[94]="索尔森，你没机会加入任何组织了…"
D.Strings[95]="我伤得很重。很抱歉我不能走得更快一些。"
D.Strings[96]="啊，新鲜的空气！我要休息一下。"
D.Strings[97]="黑石氏族的兽人在这一带部署了不少兵力，我会尽我所能跟上你。我们出发吧！"
D.Strings[98]="离湖畔镇很近了。以圣光的名义，让我坚持到那里吧！"
D.Strings[99]="马瑞斯大人！第12军团的基沙恩下士从战场返回，前来报到！"
D.Strings[100]="勇敢的冒险者，谢谢你救了我！我保证马瑞斯大人会重赏你的。"
D.Strings[101]="出售安东尼奥·皮雷利的万能药！"
D.Strings[102]="来看看吧！皮雷利的万能药会让你看得眼花缭乱的！"
D.Strings[103]="石匠……呃，迪菲亚兄弟会的成员们请注意：今晚抛锚。"
D.Strings[104]="首领要求大家提高警惕。今晚抛锚。"
D.Strings[105]="我是来拿金子的。"
D.Strings[106]="这里到处都是盗贼。我们人民军必须把他们占据的土地还给农夫们。"
D.Strings[107]="我们必须解放这些农田。暴风城已经抛弃了这些人，但如果我们也这样做，那我会感到羞耻。"
D.Strings[108]="据报告，迪菲亚兄弟会正在海岸附近活动。哨兵岭警报解除。"
D.Strings[109]="据报告，有大量豺狼人在金海岸矿洞和詹戈洛德矿洞地区活动。"
D.Strings[110]="斯托曼大人，哨兵岭的警报已经解除。但有报告称月溪镇地区出现了大量的迪菲亚盗贼。"
D.Strings[111]="暴风城背信弃义的行为永远也无法得到西部荒野人民的原谅。"
D.Strings[112]="没有鱼上钩……"
D.Strings[113]="小鱼小鱼快上钩……"
D.Strings[114]="来这里坐坐，喝一杯！"
D.Strings[115]="瓶子表面布满了灰尘，但是里面的酒却很纯净！"
D.Strings[116]="希望暴风城的增援快点到来……"
D.Strings[117]="快点，伙计们，我们要尽快重建这座桥。"
D.Strings[118]="暴风城的增援在哪里？东边那些黑石兽人的活动越来越频繁了。"
D.Strings[119]="仍然没有暴风城第二军团会赶来增援的迹象，而东北方的暗皮豺狼人又在蠢蠢欲动。"
D.Strings[120]="马瑞斯大人无时无刻不在期待着暴风城的增援……"
D.Strings[121]="不要担心，布兰契，我们很快就有东西给你吃了……"
D.Strings[122]="我从来就没想过有一天我会离开西部荒野，离开我的家……"
D.Strings[123]="这辆该死的马车居然坏了。倒霉啊……"
D.Strings[124]="当我把这辆马车修好后，咱们就马上离开这里……"
D.Strings[125]="我怎么才能把这些机械怪物赶出我的农田啊？"
D.Strings[126]="就凭你们这些歹徒和盗贼是不可能把我从自己的土地上赶走的！"
D.Strings[127]="他们也许能赶走其他的农夫，但是萨丁一家是永远也不会离开西部荒野的。"
D.Strings[128]="不要离开大路。森林里到处都是亡灵。"
D.Strings[129]="不要害怕。守夜人很快就会把这里的邪恶力量完全清除的。"
D.Strings[130]="亡灵在这里四处横行！但暴风城的军队在哪里？"
D.Strings[131]="仅仅依靠守夜人并不能永远地保护我们。我们需要暴风城军队的援助。"
D.Strings[132]="我们决不向邪恶的势力屈服。守夜人一定会胜利的！"
D.Strings[133]="森林里到处都是狼人和食尸鬼。我们必须有所行动！"
D.Strings[134]="我们需要暴风城更积极的反应和更多的支援，我们的家园正在遭到亡灵的进攻。"
D.Strings[135]="暮色森林的议会必须行动起来了。这里已经充满了邪恶。"
D.Strings[136]="夜色镇的人民对议会充满了期望。我们不能让他们受到邪恶的伤害。"
D.Strings[137]="争吵不休对我们一点用都没有。我们需要的是实际行动。"
D.Strings[138]="从暴风城来的消息似乎不太妙……"
D.Strings[139]="看来我们已经被暴风城完全抛弃了。"
D.Strings[140]="我感到邪恶的力量正在滋生……"
D.Strings[141]="星星告诉我，今晚会发生一些恐怖的事情。"
D.Strings[142]="未来充满了死亡和不确定性，和过去并无多少不同。"
D.Strings[143]="幽魂在我耳边细语，他们显得如此地焦躁不安。"
D.Strings[144]="今晚的星星会很美！"
D.Strings[145]="仰望夜空，你能感觉到一些比魔法还要神奇的东西。总有一天它们会听我的声音……"
D.Strings[146]="安静一些……月光洒进来了……"
D.Strings[147]="向上方走，吹吹口哨。"
D.Strings[148]="这股黑暗而邪恶的势力显然会碍我们的事。"
D.Strings[149]="欢迎来到血鸦旅店。这种时候，你最好一直呆在屋子里。"
D.Strings[150]="再来满饮一杯！"
D.Strings[151]="欢迎来到狮王之傲旅店。您会在这里找到家的感觉！"
D.Strings[152]="事情太多，时间太少！"
D.Strings[153]="我要找的关于暗夜精灵习俗的书在哪里……"
D.Strings[154]="哦，我的天啊！看看这一堆书！是谁把这些书没归类就胡乱地放回书架上的？"
D.Strings[155]="夜色镇的居民们，拿起你们的武器！一只亡灵憎恶正沿着大道走过来，妄图进犯我们的家园！"
D.Strings[156]="那个憎恶已经毁灭了我们守夜人的营地！快点，我们必须在它到达城镇之前阻止它！"
D.Strings[157]="快一点！勇敢的卫士们，快到镇中心集合！我们要并肩击退亡灵！"
D.Strings[158]="憎恶来了！冲啊！"
D.Strings[159]="憎恶被杀死了！夜色镇安全了！"
D.Strings[160]="我不知道他已经结婚了！我甚至不知道他的年龄！这太可怕了！他再也不能在晚上工作了！"
D.Strings[161]="好的！你说服了我，你是机械方面的专家！随你在哪里安装这个门！"
D.Strings[162]="是的，我们很愚蠢。和狐狸一样愚蠢！"
D.Strings[163]="我的熏肉在哪里？"
D.Strings[164]="你们已经毁掉了自己的土地，别想再毁掉我的。"
D.Strings[165]="谢谢你救了我！"
D.Strings[166]="去死吧！"
D.Strings[167]="轮到我巡逻了。我很快就会回来的。"
D.Strings[168]="现在海岸清晰可见……"
D.Strings[169]="谁在那儿？"
D.Strings[170]="我已经离开很久了……最好动身回去。"
D.Strings[171]="列兵索尔森巡逻归来。没有新的情况要报告——今天特别地平静……"
D.Strings[172]="妄图阻止我们的家伙必将付出惨痛的代价！"
D.Strings[173]="很好，你脱险了。休息一下，但不要太放松。库尔森的人随时可能出现。"
D.Strings[174]="这里发生了什么事情？不要碰那些东西！"
D.Strings[175]="亚伯？是你吗？啊……我很饿，亚伯！我饿啊！！"
D.Strings[176]="等等……你不是我的丈夫。但肯定是他派你来的。你看起来……很可口！"
D.Strings[177]="让我们看看这次我是否能正中靶心！"
D.Strings[178]="看来我还需要更多的练习！"
D.Strings[179]="给我多点时间进行练习。"
D.Strings[180]="嘿，伙计，我可没有时间喝酒。"
D.Strings[181]="嘿，伙计，给我来杯酒！"
D.Strings[182]="嘿！给我回去工作！多谢你，贝尔姆。"
D.Strings[183]="嘿，伙计，你的酒。"
D.Strings[184]="告诉你的朋友，如果他不把他的债处理掉，我就和老钢手一起去找他麻烦！"
D.Strings[185]="贝尔姆叫你赶快付账，否则他就会揍扁你。"
D.Strings[186]="好啊！让那老家伙试试看啊！"
D.Strings[187]="随便给我点什么吃的，外加一瓶酒！"
D.Strings[188]="贝尔姆，嘿！给我一杯雷酒，再给我的好朋友$n来一杯。"
D.Strings[189]="看管酒桶的工作怎样了啊……？"
D.Strings[190]="啊，真妙！我想要再来两杯……你能帮我照看一下这些桶吗，$n？"
D.Strings[191]="好吧，我要回去干活了。休息一下的感觉果然很不错，喝上一杯雷酒的感觉就更好了！"
D.Strings[192]="我又回到原点了。"
D.Strings[193]="我现在离得太远了……所以我看不见桶。"
D.Strings[194]="想想这里会有鱼吗？"
D.Strings[195]="我上个星期抓到一个大家伙，它居然有三只眼！"
D.Strings[196]="我爸爸说在大海里有一种很大很大的鱼，可以一口吞下一整条船。"
D.Strings[197]="我爸爸能比你爸爸捕更多的鱼！"
D.Strings[198]="快看！快看！我抓到鱼了！呃……这是谁的臭鞋？"
D.Strings[199]="哼哼。"
D.Strings[200]="骗子！"
D.Strings[201]="我听说有种巨大的鱼会上岸吃人！"
D.Strings[202]="有一次，在野营的时候，我抓住了一条比我还大的鱼！"
D.Strings[203]="我听说如果你抓住一条金鱼，那么你就会得到三个许愿的机会！"
D.Strings[204]="如果你的钓鱼技术真的像你说的那么好，那么整个海里的鱼早就被你全钓光了。"
D.Strings[205]="嘘！别把鱼给吓跑了。"
D.Strings[206]="你要把它拉起来。"
D.Strings[207]="如果你的钓鱼水平有你说的那么好，那我们就不会在这里饿肚子了。"
D.Strings[208]="也许我们应该到桥那边去钓鱼。"
D.Strings[209]="洛萨就那样空手杀死了三十六个兽人！"
D.Strings[210]="当数以千计的狂暴兽人涌入山谷的时候，骑士们紧握手中的武器，巍然面对部落的冲锋。"
D.Strings[211]="他们说他有时会变成乌鸦。"
D.Strings[212]="你知道为什么兽人的眼睛闪着红光？因为他们喝的是血！"
D.Strings[213]="勺子并不存在。"
D.Strings[214]="我发誓，真的有人看到过他们。熊猫人是确实存在的！"
D.Strings[215]="然后那兔子就一下子咬掉了他的头……事情就是这样，我发誓。"
D.Strings[216]="我跟你说啊，运河里有鳄鱼。它们原本是沼泽地带的动物，但是被人当作宠物带了回来，然后又被抛弃在运河里了。"
D.Strings[217]="哇！"
D.Strings[218]="是啊是啊，我听说过。"
D.Strings[219]="快回来，小兔子！"
D.Strings[220]="小兔子，别跑啊！"
D.Strings[221]="过来，小兔子！我只是要给你洗澡！"
D.Strings[222]="小兔子！小兔子，别跑了！"
D.Strings[223]="如果你停下来，那我就每天喂你吃胡萝卜！"
D.Strings[224]="不要逼我叫我爸爸来抓你！他喜欢用步枪打兔子！"
D.Strings[225]="嘿，得了吧，那不是真的。"
D.Strings[226]="很好很好。"
D.Strings[227]="我父亲说那只是一个故事。"
D.Strings[228]="你能想象吗？"
D.Strings[229]="对我来说，这听起来就像是比利的那些关于钓鱼的故事。"
D.Strings[230]="我好像看到了什么。"
D.Strings[231]="呃……这不是鱼！"
D.Strings[232]="我把蚯蚓弄到鞋子上了。"
D.Strings[233]="有很奇怪的味道啊。"
D.Strings[234]="我希望那是一条鱼！"
D.Strings[235]="我想运河里是不会有鱼的。"
D.Strings[236]="把蚯蚓放在鱼钩上，把鱼钩放到水里，这样我们就能钓到水里的鱼了。"
D.Strings[237]="救济一下穷人吧？"
D.Strings[238]="帮帮我这个穷人吧？"
D.Strings[239]="给我这个可怜的瞎子一点零钱吧？……你说我不是瞎子？……我真的不瞎了！我能看见了！！这真是一个奇迹！"
D.Strings[240]="擦一件装甲只收一个铜板咯！"
D.Strings[241]="这都是他们的错，愚蠢的联盟军队。居然在我的农场背后修建他们的哨塔。"
D.Strings[242]="这都是他们的错，愚蠢的兽人。居然放火烧我的农场。"
D.Strings[243]="你听见了吗？我想他们正在靠近……"
D.Strings[244]="又是警戒任务，我讨厌警戒任务。"
D.Strings[245]="有很多狗头人都去过那里……他们都死了。"
D.Strings[246]="对不起，胡达尔……但是似乎我骗了你。"
D.Strings[247]="黑铁矮人的活动越发频繁，甚至已经开始掠夺我们的货物——"
D.Strings[248]="我相信这只是一些工人的疏忽。"
D.Strings[249]="为$n欢呼吧！人民的守护者！"
D.Strings[250]="西部荒野的人民向勇敢的$n致敬！"
D.Strings[251]="让我们为$n祝酒三杯！这块土地又回到我们手里了！"
D.Strings[252]="谢谢你的这箱酒，$n。我现在就想打开一瓶尝尝！"
D.Strings[253]="如果我们改变魔法精华的流向，也许我们就可以改变其极性。"
D.Strings[254]="然后，预设的魔法序列将产生链式反应，并最终使能量开始从正极输入。"
D.Strings[255]="传送门将会产生轻微的变化，此时如果你施展一个固化咒语，那么你就可以把它的变化固定下来。"
D.Strings[256]="当正极能量与负极能量相碰的时候，它们互不相容。"
D.Strings[257]="玛吉诺曾指出，改变正极能量的流量会使其更加稳定。"
D.Strings[258]="该点的魔法屏障应该得到足够的能量支持，这样才能保持其稳定性。"
D.Strings[259]="为什么我们不能通过改变魔法阵列的方法去补偿流量的变化呢？"
D.Strings[260]="加入十二个聚焦核心可以使魔法能量变得更加稳固。"
D.Strings[261]="但是如果频率转换的结果是将魔法流反馈回去，那会怎么样呢？"
D.Strings[262]="难道那不会使得法术程序在被激活之前就崩溃吗？"
D.Strings[263]="你是说交叉魔法流？那就太糟糕了。"
D.Strings[264]="那样能量流会崩溃，其魔法扰动的结果是让你在至少一周内都觉得浑身不舒服。"
D.Strings[265]="那不就是让萨蕾莉亚的魔法方程出问题的原因么？"
D.Strings[266]="我不这么认为，我不想再被炸出实验室了。"
D.Strings[267]="可是，那会使魔法聚焦失去平衡，并引起扭曲虚空中的异常波动。"
D.Strings[268]="我想如果有二十个人用魔法能量支持它，应该还是可以的。"
D.Strings[269]="如果我们在泰里安方程式中使用三个聚焦器会发生什么事呢？应该可以解决这个问题吧？"
D.Strings[270]="但是如果我们在恰当的能量点使用定位魔法来稳定它，那么它就可以正常运作了。"
D.Strings[271]="别扯了，你那种方法成功的或然率小过零啊。"
D.Strings[272]="如果我们按照正确的次序进行操作，那就应该不会有任何问题。所以我们在开始之前应该好好地研究一下。"
D.Strings[273]="呵呵，所有的这一切都是为了一瓶爱情药水。希望他别辜负了那姑娘。"
D.Strings[274]="如果根据苏瑞亚的理论，那就是没错了，不过这样一来我们就必须采用伊瑟亚的魔法启动流程理论。"
D.Strings[275]="至少我们不用费神去打扫现场……"
D.Strings[276]="除非我们没有按照正确的初始步骤进行操作。"
D.Strings[277]="我想你是对的。"
D.Strings[278]="这是我的清单，凯德雷克。都是些常用的原料。"
D.Strings[279]="谢谢你，凯德雷克。再见。"
D.Strings[280]="我要诅咒你，$n！总有一天我会复仇的。"
D.Strings[281]="好了，我们刚得到消息，有一个商队已经从塞尔萨玛出发了。该行动了！出发！"
D.Strings[282]="我们已经接近挖掘场了，注意小心行事。现在准备好你的水下呼吸装备……"
D.Strings[283]="嘿，伙计，你知道新的蒸汽坦克已经可以开出去了吗？"
D.Strings[284]="嗯，我已经听到过关于那新东西的消息了。他们去掉了防弹装甲来减轻重量，简直是疯了！"
D.Strings[285]="你除了打架还知道什么？我轻而易举就可以把你骗得团团转！"
D.Strings[286]="哈！只要你一进入我的射程，包你马上粉身碎骨！"
D.Strings[287]="啊哈！你没戏了！"
D.Strings[288]="嘿，我说，我有没有跟你说过，那天当我骑马穿过运河的时候，有一些驾驶着伐木机的地精想要伏击我？"
D.Strings[289]="嗯，让我看看。我敢打赌，足有一百次了！"
D.Strings[290]="啊哈哈哈哈哈！我用枪指着他们鼻子的时候，那些家伙脸上的表情别提有多搞笑了！他们的锯子甚至都没能碰到我！"
D.Strings[291]="我应该往我的坦克里扔几瓶艾沃沙酒，然后在他们发现我之前赶紧回家！"
D.Strings[292]="呸！这一点都不好笑！"
D.Strings[293]="嘿，咱们来赛坦克吧。多跑几圈，看看谁会赢？"
D.Strings[294]="没问题，过一会咱们就去比一比！"
D.Strings[295]="这世上根本就没有任何可以跟蒸汽坦克叫板的东西！"
D.Strings[296]="哈！你害怕我会弄伤你那小不点赛车手？"
D.Strings[297]="哈！我更加担心你那破烂不堪的东西会炸成一千块！"
D.Strings[298]="哈哈！看看这些在战斗中留下的伤痕！"
D.Strings[299]="没有什么声音能比双缸蒸汽坦克开动时的动静更大了！"
D.Strings[300]="哈！跟XT型火炮的声音比起来，那简直是蚊子叫！"
D.Strings[301]="呸！你这没开过蒸汽坦克的乡巴佬懂什么！"
D.Strings[302]="也许吧，但不管是什么型号的坦克，我都能用XT型火炮把它炸得稀巴烂！"
D.Strings[303]="亲爱的科贝特，哈兰要我们尽快给他送些衬衣和短裤过去。"
D.Strings[304]="科贝特，你在吗？哈兰还需要一些针织品。你能给他带一些过去吗？"
D.Strings[305]="啊，我很荣幸，小甜心。我很快就回来……"
D.Strings[306]="他的生意似乎挺火爆的！我马上就给他补充货物！"
D.Strings[307]="嗯……等搞定这些，我就要去奶酪店吃点东西。"
D.Strings[308]="卖完这些东西我也就能稍微挣点钱了，中午吃什么呢……"
D.Strings[309]="嘿，哈兰，这是你要的衣服。"
D.Strings[310]="哈兰！这些是你要的另一批衣服，今天你生意真不错啊！"
D.Strings[311]="太感谢你了，科贝特。我马上就把这些货物放到柜上出售。"
D.Strings[312]="好的，马上发货。很高兴和你做生意，科贝特。"
D.Strings[313]="好的，那我走了。多多保重，哈兰。"
D.Strings[314]="很高兴看到你干得这么好，哈兰。希望我们很快能再见面……"
D.Strings[315]="大人！我们的卫兵报告说西边有一些异常的情况。"
D.Strings[316]="艾尔罗大人！我们派去墓地的探子带来了一些坏消息……"
D.Strings[317]="从那个老隐士的小屋里传出了可怕的咆哮声！"
D.Strings[318]="狼群都在朝这边跑，好像是为了躲避……躲避什么东西……"
D.Strings[319]="遵命，大人。"
D.Strings[320]="这是一个可怕的消息，我担心这与$n为那个老隐士做的事情有关。"
D.Strings[321]="快派人去告诉阿尔泰娅，我们的小镇面临着巨大的危险。我们必须做好准备！"
D.Strings[322]="阿尔泰娅，有报告说墓地里有异常情况。艾尔罗认为这是夜色镇即将遭到攻击的前兆。"
D.Strings[323]="这不是个好兆头。马上派人去继续侦查，其他人保持警戒。"
D.Strings[324]="注意！注意！夜色镇面临巨大的威胁！守夜人，保持警戒！"
D.Strings[325]="夜色镇……我饿了！！"
D.Strings[326]="呼啊啊啊啊啊啊啊啊！！"
D.Strings[327]="……九……十……准备好了没有？我来了！"
D.Strings[328]="嘿！你最好不要走太远！"
D.Strings[329]="妈妈说过不许再爬那个。我要去告诉妈妈！"
D.Strings[330]="谢谢你，$n。愿圣光保佑你，我的$G兄弟:姐妹;，愿它指引你前进的道路。"
D.Strings[331]="现在可以吃了……"
D.Strings[332]="你好，埃林！你好啊，艾莱尼！我要来点奶酪。"
D.Strings[333]="你好啊，提亚斯！我要买些奶酪。"
D.Strings[334]="你好，科贝特。这是今天早上刚做好的奶酪！你的商店生意还好么？"
D.Strings[335]="你好啊，科贝特！拿着吧！你服装店的生意一定很不错吧？"
D.Strings[336]="再见，科贝特，代我向你妻子问好！"
D.Strings[337]="保重，代我向你家人问好。"
D.Strings[338]="没问题，非常感谢你！"
D.Strings[339]="我会的，谢谢你的奶酪！"
D.Strings[340]="我得在雷玛开始担心之前回去……"
D.Strings[341]="该回商店了……"
D.Strings[342]="我回来了！"
D.Strings[343]="是啊是啊，生意很忙！"
D.Strings[344]="我又出来了。现在我要向下一个地点进发……"
D.Strings[345]="我在房屋之间移动"
D.Strings[346]="我终于到了最后一个目标地点了。好耶！"
D.Strings[347]="妈妈，杰希又爬到那座塔上去了。"
D.Strings[348]="你最好不要说我的闲话！"
D.Strings[349]="我下不来了，我怕。"
D.Strings[350]="哇……啊！"
D.Strings[351]="赶快干活，你们这些狗一样的家伙！干活！"
D.Strings[352]="给我下来！你以后不许再去那里爬上爬下的，太危险了！"
D.Strings[353]="高兴了吧？马上给我回去。"
D.Strings[354]="喝之前一定要热一热才带劲！你刚刚说什么了？"
D.Strings[355]="看这边！！！"
D.Strings[356]="兄弟们，各就各位！那些野兽就要过来了。等我的信号！"
D.Strings[357]="我们必须把这片土地上所有邪恶堕落的东西驱逐出去！"
D.Strings[358]="彻底消灭这些亡灵！"
D.Strings[359]="血色十字军战无不胜！"
D.Strings[360]="波涛汹涌的海洋……看来海之精灵是永不疲倦的……嗝儿！"
D.Strings[361]="我曾经看到过一个海巨人。再看到它们一次也没什么了不起，嗝儿！"
D.Strings[362]="我要出去干掉几个豺狼人，但是这条腿刚好点，我担心这样冒冒失失地出去的话不会有好结果。"
D.Strings[363]="在那里要千万小心，许多探险者都没能活着从沼泽地回来。嗝！"
D.Strings[364]="我要一个人静一静，请离开吧。"
D.Strings[365]="你来啦，西部荒野那边有什么消息吗？"
D.Strings[366]="范克里夫告诉我计划正在进行中。但是他也听说有一些人正在四处打探相关的消息。"
D.Strings[367]="很好，那么我回去了。"
D.Strings[368]="嗯，可能就是那个爱管闲事的肖尔，我要去看看能找到些什么。回头再联系吧。"
D.Strings[369]="唉，又是到墓地去巡逻的时间了——我很快就回来。"
D.Strings[370]="我们应该快点把那个篱笆修好。"
D.Strings[371]="维罗克说格鲁姆拉好像打中了什么东西，我想我应该去看看。"
D.Strings[372]="该死！我没有击中目标！那个愚蠢的矮人可能又把枪当锤使了。"
D.Strings[373]="嗯……格鲁姆拉说对了，准心好像是有些偏，不过很容易就能修好。"
D.Strings[374]="完美的射击！格鲁姆拉根本就没这个准头，他就是用枪顶着目标也不一定能打中！"
D.Strings[375]="可笑！那个该死的矮人根本不知道他在说什么，格鲁姆拉的准头太差了。"
D.Strings[376]="瓦格，你准备好吃饭了吗？我要开吃啦。"
D.Strings[377]="卡拉一边煮东西，一边哼着一首矮人的老歌。"
D.Strings[378]="饭准备好了，快洗洗手过来吃吧。"
D.Strings[379]="嗯，不错。但是，该回去工作了！"
D.Strings[380]="啊哈，正好！我的肚子已经开始叽里咕噜乱叫了。"
D.Strings[381]="嗯……闻起来真香啊，卡拉。"
D.Strings[382]="吃饱了！真好吃。你不仅是个钓鱼高手，烧菜的手艺也很不错嘛。"
D.Strings[383]="呃！我想我吃得太多了，得松松皮带……"
D.Strings[384]="亲爱的，谢谢你的大餐，我要出去了。"
D.Strings[385]="又是一个钓鱼的好日子，卡拉。我马上就出发。"
D.Strings[386]="这种天气最适合钓鱼了！"
D.Strings[387]="瓦格注视着水面，不知道他今天的运气会如何。"
D.Strings[388]="唉，看来是钓不到鱼了，我看我还是回去刮鱼鳞吧。"
D.Strings[389]="我想我最好现在就回去，卡拉也一定盼着我快点回去。明天见啦。"
D.Strings[390]="看看水面那些波纹……水里可真热闹，今天我一定能钓很多鱼。"
D.Strings[391]="恩……水面上虽然看不出什么动静，但是今天天气不错，我的运气也应该不错。"
D.Strings[392]="今天估计没戏。太阳早早地到了正中，而且阳光太耀眼了，水里也没有什么动静。"
D.Strings[393]="唉！今天看来真的不适合钓鱼。不过什么都钓不上也比干一天活要好。"
D.Strings[394]="波尔特！伊瓦琳！天黑了，快回屋里来。"
D.Strings[395]="明天再玩吧，现在快回屋里来。"
D.Strings[396]="好吧。你们两个可以去玩，但不许跑出镇子去。不要偷偷溜出去打扰水边的瓦格和卡拉。"
D.Strings[397]="哈！达瑞尔，你应该看看你自己的表情！你已经脸色发青了！"
D.Strings[398]="他们会好好招待你的，小子！"
D.Strings[399]="给我闭嘴。"
D.Strings[400]="啊，妈妈！天还没黑！我们可以多玩一会吗？"
D.Strings[401]="我们必须时刻警惕才能消除这场灾难！"
D.Strings[402]="坚持下去，一切都会变好的！"
D.Strings[403]="血色十字军将彻底净化这片土地！"
D.Strings[404]="彻底清除任何被污染的东西！"
D.Strings[405]="妈妈！我们可以去玩吗？可以吗？好不好？妈妈？"
D.Strings[406]="小孩充满活力地跳上跳下。"
D.Strings[407]="耶~~~谢谢妈妈！"
D.Strings[408]="谢谢叔叔！"
D.Strings[409]="这里有点冷啊，我要烤烤火再喝点酒取暖。"
D.Strings[410]="喝着啤酒和好朋友围坐在火堆旁边可真是一件乐事。"
D.Strings[411]="布洛克，托瑞恩，我要进去喝杯麦酒，烤烤火暖暖身子。"
D.Strings[412]="嗯……围着火炉喝点麦酒，这个主意听上去很不错。我当然会和你一起去的，吉恩。"
D.Strings[413]="干杯！"
D.Strings[414]="什么？有人说到麦酒了？没有托瑞恩在场，哪能喝得爽快！"
D.Strings[415]="有什么就上什么！"
D.Strings[416]="诺玛已经快把中饭准备好了。也许最好还是head in。"
D.Strings[417]="啊，好来劲的酒啊！"
D.Strings[418]="我感到……头晕目眩。这里太热了……"
D.Strings[419]="其他人在哪里？"
D.Strings[420]="每个人都正在赶来……"
D.Strings[421]="他真的帮不上忙……"
D.Strings[422]="没有人能长生不老……"
D.Strings[423]="吉姆洛克！吉姆洛克！马上进来！"
D.Strings[424]="那小子去哪儿了？"
D.Strings[425]="吉姆洛克，不要动，你把衣服全弄脏了。"
D.Strings[426]="快点……快点……"
D.Strings[427]="我总有一天会成为卫兵的！"
D.Strings[428]="你还记得当年达纳斯聚集了暴风城的所有雇佣兵，然后开到守望堡去跟兽人大战的事情吗？"
D.Strings[429]="我跟你说，我参加了整场大战。我还记得当时我们在达隆米尔战斗的情景。整个晚上都是雾，我们就躺在满是泥泞的战壕里。"
D.Strings[430]="我真的很怀念洛丹伦的那个旅馆里的矮人麦酒。还记得我们在那里开始的战斗吗？"
D.Strings[431]="我们不足百人，兽人却有上千个。区区百人怎么能够战胜他们？"
D.Strings[432]="在我们的部队开到匹瑞诺德家门口的时候，你真该看看他的脸色。真是一场恶战！"
D.Strings[433]="与沼泽中的暮光之锤信徒战斗，那感觉真是糟透了。"
D.Strings[434]="啊，对，现在我记起来了，是在你的新婚之夜吧？"
D.Strings[435]="啊啊！"
D.Strings[436]="那晚的伤痕依然留在我身上。"
D.Strings[437]="那天晚上我断了两条腿。我怎么会忘记呢？"
D.Strings[438]="三个星期之后，我在北郡醒来。但是我已经想不起任何事了。"
D.Strings[439]="是啊，那天晚上我们不得不捡起我的手指，然后把它放进你的烟袋里带了回来。"
D.Strings[440]="我的后背里还有一小块铁片，这会让我永远记得那个晚上。"
D.Strings[441]="我当然记得那晚的情形。你就在我左边两英尺左右的地方，一直和那个名叫莫里斯的精灵在喝酒。那晚我还穿着我最好的衬衫哪。"
D.Strings[442]="那是我第三次还是第四次呕吐了？你那些疯狂的烈酒……"
D.Strings[443]="嗯，谢谢你那天晚上让我能把自己的手捡回去。"
D.Strings[444]="呵呵，废物。"
D.Strings[445]="你像个小女孩一般地尖叫，这真是我见过的最好笑的事。"
D.Strings[446]="最后终于全搞定了。"
D.Strings[447]="让我们不要再比较身上的伤痕了，朋友。"
D.Strings[448]="我从来没看到过有人逃得这么快。"
D.Strings[449]="你真的令我感到非常惊讶，你居然活了下来。"
D.Strings[450]="好吧，你还好端端地坐在这里。我想说这里还是有些东西值得我们举杯庆贺的。"
D.Strings[451]="你可以在任何时候感谢我，因为我令你的生活更加有趣。"
D.Strings[452]="我……我……感到有些不对劲……"
D.Strings[453]="%s向$n挥了挥手"
D.Strings[454]="你打扰了我的休息，$c。现在我很生气！"
D.Strings[455]="我的思想……我的血肉……我在腐烂……！"
D.Strings[456]="再来一杯，朗斯顿。"
D.Strings[457]="暴风城最好的麦酒，朗斯顿。多谢。"
D.Strings[458]="嘿，瑞斯，给我和克里斯托弗再来一杯。"
D.Strings[459]="暖和的旅店，冰爽的麦酒。我们还能要求什么呢？"
D.Strings[460]="%s将枪柄靠在肩膀上，瞄准目标开了一枪。"
D.Strings[461]="以拉格纳罗斯的名义，去死吧！"
D.Strings[462]="以拉格纳罗斯之名，萨多尔大桥已经被摧毁了，接下来就是巨石水坝！"
D.Strings[463]="麦格尼·铜须是个白痴加吹牛大王！"
D.Strings[464]="这个$C在扰乱我们的工作！死吧！蠢货！"
D.Strings[465]="看看这是谁？$c$n？干掉$g他:她;！"
D.Strings[466]="背叛拉格纳罗斯的人都得死！"
D.Strings[467]="干掉那些肮脏的$R！"
D.Strings[468]="巨石水坝将会被摧毁！拉格纳罗斯万岁！"
D.Strings[469]="没用的$C！你无法对抗碎石怪部族！"
D.Strings[470]="一个$r$c？你应该是一顿不错的早餐！"
D.Strings[471]="碎石部族会消灭你们！"
D.Strings[472]="去死吧，$R！这些土地属于碎石部族！"
D.Strings[473]="好的$r是死掉的$R！"
D.Strings[474]="洛克湖现在属于碎石部族了，$n！去死吧！"
D.Strings[475]="$n！拉格纳罗斯的背叛者！"
D.Strings[476]="黑铁矮人将会收复属于他们自己的土地！"
D.Strings[477]="愚蠢的$C！你无法对抗拉格纳罗斯的部下！"
D.Strings[478]="像你这样没用的$c是无权在这里生存的！"
D.Strings[479]="$n！准备迎接你的死亡吧！"
D.Strings[480]="哪个愚蠢的$C在挑战我的权威？去死吧，蠢货！"
D.Strings[481]="这些土地属于黑铁矮人。准备后事吧，$C！"
D.Strings[482]="我是巴尔加拉斯。$n，你将会变成灰烬！"
D.Strings[483]="$n，挑战迪菲亚兄弟会的下场只有死路一条！"
D.Strings[484]="一个小小的$C还想要挑战我？准备后事吧！"
D.Strings[485]="死亡矿井将是你的坟墓，$n！"
D.Strings[486]="以兄弟会的名义，去死吧！"
D.Strings[487]="迫害我们石匠协会的人都该死！"
D.Strings[488]="议员们的堕落已经影响了你。让我的剑来帮你解脱吧！"
D.Strings[489]="去死吧，$n！只有死亡才是你的归宿。"
D.Strings[490]="这个没用$R到底是谁？愚蠢的入侵者。去死吧，蠢货！"
D.Strings[491]="愚蠢的$R！黑石氏族会在你的坟墓上跳舞！"
D.Strings[492]="愚蠢的$C！你根本无法与我对抗！"
D.Strings[493]="我是加塞尔佐格！而你是个注定要死在这里的$R！"
D.Strings[494]="干掉$n！黑石氏族万岁！"
D.Strings[495]="谁敢侵犯黑石氏族？死吧！$R！"
D.Strings[496]="无能的$C！你怎敢与黑石氏族对抗！"
D.Strings[497]="愚蠢的$C！我要把你的骨头一根根捏碎！"
D.Strings[498]="伟大的黑石氏族万岁！"
D.Strings[499]="为艾德温·范克里夫而战！"
D.Strings[500]="谁敢妨碍迪菲亚兄弟会的行动？死吧，$C！"
D.Strings[501]="任何胆敢阻止我的$R都得死！"
D.Strings[502]="谁敢阻挡艾德温·范克里夫的信使？去死吧，$c！"
D.Strings[503]="我要捎信给$n吗？当然！你的死期到了！"
D.Strings[504]="让我送你一程吧，没用$C！你可以准备后事了！"
D.Strings[505]="我有一个特别的消息要交给一个名叫$n的家伙。那就是：你死定了！"
D.Strings[506]="我有一首歌送给$n：玫瑰是红色，紫罗兰是蓝色，我要杀死所有的$R，包括你在内！"
D.Strings[507]="我们出发吧，小心外面的那些狼……"
D.Strings[508]="小心，$n。那些狼喜欢隐藏在树林里。"
D.Strings[509]="我们快到了！"
D.Strings[510]="我们终于到了！谢谢你，$n。没有你我是找不到这里的。"
D.Strings[511]="我被发现了！$n杀过来了！快来帮忙！"
D.Strings[512]="去死吧！你这没用的$n！"
D.Strings[513]="我需要一点帮助，那个$n看到我了。"
D.Strings[514]="$n冲过来了！准备战斗！"
D.Strings[515]="那个$n要杀我！救命！"
D.Strings[516]="我闻到了一个$R的气味……"
D.Strings[517]="救命！我们遭到了攻击！是黑铁矮人！"
D.Strings[518]="我们被包围了！准备战斗！干掉这个$n！"
D.Strings[519]="哈，终于到这里了！摆脱了那些木桶的感觉真好。"
D.Strings[520]="%s咆哮着发起了挑战！"
D.Strings[521]="我会准时回来的……"
D.Strings[522]="阿鲁高的子孙们将会惩罚那些胆敢挑战月怒权威的蠢货！"
D.Strings[523]="让斯塔文的传说就此埋藏在历史中吧！"
D.Strings[524]="是哪个$r在这里多管闲事？让斯塔文的传说和你一起消亡吧！"
D.Strings[525]="不要多管闲事，$n！"
D.Strings[526]="%s发出了尖锐的叫声，寻求同伴的帮助。"
D.Strings[527]="蒂罗亚……是你吗？为什么不是我的蒂罗亚！只是一个肮脏的$R！"
D.Strings[528]="谁敢打扰我？去死吧，$n！"
D.Strings[529]="我会放干你的血，$C！"
D.Strings[530]="救命！救命啊！"
D.Strings[531]="把它们赶走！坚守阵线！"
D.Strings[532]="%s开始咏唱魔法咒语……"
D.Strings[533]="不！这不可能……"
D.Strings[534]="难以置信！我知道是谁施展了这些魔法……"
D.Strings[535]="这怎么可能……我对施展这个魔法的家伙太了解了……"
D.Strings[536]="$n，我有一些你想要知道的消息……"
D.Strings[537]="我的仆从们……"
D.Strings[538]="我们征服一切的时刻即将降临！"
D.Strings[539]="你毁灭一切的欲望很快就会消失……"
D.Strings[540]="你满腔的愤怒很快就可以倾泻在我们的敌人身上。"
D.Strings[541]="我有一些新的情报……关于我们与那些游荡的亡灵之间的战事。"
D.Strings[542]="洛丹伦的叛军相当弱小，而且他们居然不愿意效忠于巫妖王。"
D.Strings[543]="黑暗女王的追随者们都瞎了眼，竟然自以为他们能和我们对抗。"
D.Strings[544]="我们越来越强大，而我们的敌人陷入了多线作战的困境，并且在持续的战事中变得越来越弱。"
D.Strings[545]="准备战斗！"
D.Strings[546]="做好准备，我们马上就要对那些自称为被遗忘者的家伙发动一次进攻。"
D.Strings[547]="准备作战吧，我的孩子们。"
D.Strings[548]="我们是他的意志的实施者，我们会把他的敌人送入坟墓！"
D.Strings[549]="这些亡灵垃圾会和他们那死掉的精灵女王一起被毁灭！"
D.Strings[550]="我们要把敌人驱赶出银松森林，把战火烧到他们的首都！"
D.Strings[551]="为了巫妖王的荣耀而战！"
D.Strings[552]="埃兰德，很高兴又见到你。有什么要报告的？"
D.Strings[553]="大量的狼都在往东边迁徙，而住在玛尔丁果园里的人也都跑光了。"
D.Strings[554]="如果你没事的话，我要去看看奎恩……"
D.Strings[555]="你好，奎恩。你的伤势怎么样了？"
D.Strings[556]="好好保重，奎恩。这次你真的很幸运。"
D.Strings[557]="我好一些了。但伊瓦这个笨蛋过得比我还好……"
D.Strings[558]="那些叛徒是不可能阻止我把炸药运到铁环挖掘场的！"
D.Strings[559]="小心！有$n过来了！"
D.Strings[560]="准备好，$n。议员们就要回来了，准备进行伏击！"
D.Strings[561]="一个$n正在向我们进攻！"
D.Strings[562]="小心！我遭到了攻击！"
D.Strings[563]="干得好。这无疑是对阿鲁高的一次沉痛打击！"
D.Strings[564]="巨石水坝得救了！为$n欢呼吧！"
D.Strings[565]="一切都完了！"
D.Strings[566]="让一让！让一让！"
D.Strings[567]="%s从第一台投石车跳到第二台上！"
D.Strings[568]="我真倒霉！先是船沉了，现在……又没酒喝了！"
D.Strings[569]="哈林多尔，我诅咒你！你把厄运带给了我们！"
D.Strings[570]="别介意我的气味……连我自己都不介意！"
D.Strings[571]="啊，美丽的米奈希尔港，还有铁炉堡这边最好的蜂蜜酒！"
D.Strings[572]="唉，我的弟兄们！希望你们能够在潮湿的坟墓中得到安息！"
D.Strings[573]="%s看上去快要吐出来了！"
D.Strings[574]="%s脚步沉重的挪着步。"
D.Strings[575]="%s语无伦次的喃喃自语。"
D.Strings[576]="%s高高地举起了酒杯，皱了皱眉。"
D.Strings[577]="%s挑衅地环顾四周，咆哮着。"
D.Strings[578]="%s开始翻译……"
D.Strings[579]="$n，翻译完成了！"
D.Strings[580]="这真是危险的营生！$B$B米兰刚刚去送东西了，他应该会马上回来。"
D.Strings[581]="他们居然认为我很弱小。哈哈！！"
D.Strings[582]="我才是家族的首领。是我，是我！！"
D.Strings[583]="我很冷，大人。你什么时候才能兑现你的诺言？"
D.Strings[584]="我的家族非常恨我。胆小的白痴，他们都是胆小的白痴！"
D.Strings[585]="父亲？你现在为我感到骄傲了？哈哈！"
D.Strings[586]="妈妈，哦，妈妈。你早就应该听我的话……"
D.Strings[587]="萨尔曼，我的兄弟，看看谁笑到了最后？哈哈哈哈！"
D.Strings[588]="你是来这里拜访我的家族的吗？去死吧，蠢货！"
D.Strings[589]="阿加曼德磨坊由亡灵天灾控制着，$C。加入我们吧！"
D.Strings[590]="让我们为了你这种家伙早点死掉而干杯！为了你这个恶棍，$n！"
D.Strings[591]="滚开，可恶的东西！"
D.Strings[592]="呱呱！"
D.Strings[593]="%s嗅到了药剂的气味，兴奋地把它喝了下去。"
D.Strings[594]="最后他们终于表现出一丝仁慈！给了我们一些喝的东西！"
D.Strings[595]="还有美酒！感谢圣光！我几乎都要被烤干了！"
D.Strings[596]="这并不是你生命的结束，而是新的开始。现在是由你来决定自己命运的时候了。"
D.Strings[597]="你摆脱了他的控制。虽然你会被一些低贱的生物指责，但你至少有亡灵天灾所没有的机会。"
D.Strings[598]="恐惧，黑暗，还有力量？被遗忘者并不渴望这些东西，被遗忘者就是这些东西。"
D.Strings[599]="我的骨骼十分虚弱，我的双眼只能看到黑暗，我的身体只能感受到痛楚……但这一切都算不了什么，因为我的意志还是我的。"
D.Strings[600]="你好，查瑞斯。这是我需要的货单，你能帮我弄到这些东西吗？尤其是最后一种材料。"
D.Strings[601]="妈妈，我能养菲尔吗？"
D.Strings[602]="当然，派格。记得要表现得绅士一点。"
D.Strings[603]="谢谢你，查瑞斯。派格，小甜心，快过来。"
D.Strings[604]="%s用古老的语言开始吟唱魔法，召唤某种邪恶的东西。"
D.Strings[605]="哈，自由了，感觉真好！托格萨也被救出来了吗？在我们被俘后，人类就把我们给分开关押了。"
D.Strings[606]="你救出德鲁尔了吗？我不知道他被关在什么地方。"
D.Strings[607]="别管我，赶快去！我会自己走到塔伦米尔的。"
D.Strings[608]="粉皮肤的人类也许可以夺走我的生命，但他们不能夺走我的自由！"
D.Strings[609]="在这块碎石下搜索。"
D.Strings[610]="给我找点吃的来，你们这些废物！"
D.Strings[611]="在那里！在那间屋子里。你找到钥匙了吗？就在那个叫博胡恩的人类那里。"
D.Strings[612]="我从墓地里爬出来的唯一目的就是复仇！"
D.Strings[613]="以黑暗女王的名义，你去死吧，$n！"
D.Strings[614]="亡灵将会以你的灵魂为食，$n。"
D.Strings[615]="我重生了！"
D.Strings[616]="我终于可以复仇了！"
D.Strings[617]="南海镇将会付出血的代价！"
D.Strings[618]="嗯……我喜欢南海镇的美酒。"
D.Strings[619]="你知道我多么喜欢南海镇的美酒吗？让我告诉你……"
D.Strings[620]="不惜一切代价，保护工头邦德斯！"
D.Strings[621]="卫兵！卫兵！"
D.Strings[622]="你要为此付出代价！来人啊!"
D.Strings[623]="各就各位！不要让敌人进入南海镇！"
D.Strings[624]="任何可疑的人都要迅速拿下。各就各位！"
D.Strings[625]="全力保卫镇长！敌人可能会从任何一个方向突入！"
D.Strings[626]="我的树……它们正在枯萎而死，就像我一样。"
D.Strings[627]="这座果园现在死气沉沉。这些树木曾经结满了果实，但是现在只剩下干枯的树枝。"
D.Strings[628]="我耗尽毕生心血去照看这些树木，修剪它们，养育它们……能让它们给我陪葬也不错。"
D.Strings[629]="干得好！形势在朝对我们有利的方向发展，苦难终将结束！"
D.Strings[630]="救命啊！山上有刺客！帮帮我！帮帮我！"
D.Strings[631]="注意啦！注意啦！*喘息声*南海镇的居民们，有许多刺客正在向我们这里进发！"
D.Strings[632]="坚守阵地！他们一定又是想要刺杀镇长，我们一定要保护他！刺客可能从任何方向发起攻击！"
D.Strings[633]="累死我了……*喘气声*"
D.Strings[634]="南海镇公告员挠着后脑勺，瞪圆了双眼。"
D.Strings[635]="有刺客……去救……镇长……"
D.Strings[636]="他们在这里！他们过来了！救命啊！"
D.Strings[637]="刺客来了！快点阻止他们，在他们找到镇长之前干掉他们！"
D.Strings[638]="我敢打赌还会有更多辛迪加的刺客跑来送死！你们永远也不可能得到奥特兰克和南海镇！"
D.Strings[639]="成功了！镇长已经被干掉了！弟兄们，撤退！"
D.Strings[640]="镇长已经死了！快撤，弟兄们！"
D.Strings[641]="哈哈！奥特兰和希尔斯布莱德将再次被我们捏在手心里，镇长已经死了，撤退！"
D.Strings[642]="这就是多管闲事的下场！撤退！"
D.Strings[643]="镇长身边戒备森严，撤退！"
D.Strings[644]="虽然你们这次成功地阻止了我们，但我们还会回来的——走着瞧吧！"
D.Strings[645]="%s取出一只盛着绿色液体的瓶子，喝了一大口。"
D.Strings[646]="%s的眼睛变得通红，他狂笑着点燃了炸药！"
D.Strings[647]="哇哈哈哈哈哈！我要和你同归于尽！"
D.Strings[648]="好了，你们这些懒虫，该起床干活了。桥是不会自己造好的。"
D.Strings[649]="你得花几分钟时间才能起床，但是我们马上就要出发了。"
D.Strings[650]="嗨呦，嗨呦……加油干啊！"
D.Strings[651]="休息一下，伙计们！休息半小时后回去工作。"
D.Strings[652]="进度不错。只要我们继续保持现在的速度，那么第一支北上的军队就可以顺利通过它了！"
D.Strings[653]="好了，午饭时间结束了，伙计们。开始干活吧。如果今天接下来一切顺利的话，那么我们就可以早点收工。"
D.Strings[654]="好，好。继续这么干，这座桥不久就会完工。"
D.Strings[655]="收工了，伙计们！"
D.Strings[656]="时间不早了，走吧。"
D.Strings[657]="晚安，兄弟们。睡个好觉。"
D.Strings[658]="早安，我的朋友。"
D.Strings[659]="啊……该吃饭了。"
D.Strings[660]="今天的天气真不错！努力地工作之后有丰盛的食物等着我们——在这么美好的一天，我们应该能做得更好！"
D.Strings[661]="*迪米特里放下工具，擦了擦前额的汗水*"
D.Strings[662]="又是个好日子。"
D.Strings[663]="晚安，我的朋友。明天见。"
D.Strings[664]="我们就不能多睡一会儿吗？"
D.Strings[665]="好吧好吧……我起床了。"
D.Strings[666]="差不多该吃饭了吧……我一个多小时前就饿了。"
D.Strings[667]="终于可以躺下好好睡一觉了！"
D.Strings[668]="啊！整日闲逛是没有前途的，我当年应该去学裁缝……"
D.Strings[669]="我喜欢清晨！今天天气真好，不是吗？好好呼吸新鲜空气吧！"
D.Strings[670]="以圣光的名义，我今天真的很饿。你们今天看到达希了吗？她看上去精神不错。"
D.Strings[671]="你知道，那座桥工程量很大，但只有我们六个人在工作。你应该雇用更多的工人来。"
D.Strings[672]="你们看见达希了吗？我没看到她，不知道她今晚去哪里了。"
D.Strings[673]="%s仔细搜查着码头。"
D.Strings[674]="哦，好吧，我相信她会回来的。"
D.Strings[675]="诸位，晚上好。我要在这里坐一会。达希可能会过来的。"
D.Strings[676]="啊！午饭！我睡过头了！"
D.Strings[677]="%s喘着气向其他的造桥工跑去。"
D.Strings[678]="对不起，我来晚了。"
D.Strings[679]="这座桥永远也建成不了吗？"
D.Strings[680]="今天我的后背痛得几乎要了我的命。"
D.Strings[681]="现在能吃点东西的话该有多好啊。"
D.Strings[682]="嗯，不错，继续工作吧。"
D.Strings[683]="又一天过去了……"
D.Strings[684]="晚安，晚安。"
D.Strings[685]="%s被灵魂宝石的力量震慑了！"
D.Strings[686]="%s的灵魂自由了……"
D.Strings[687]="%s深深地叹了口气。"
D.Strings[688]="我讨厌我的这份工作。啊，暮色森林啊，你就不能可怜可怜我么？"
D.Strings[689]="古董，武器，装甲，还有很多别的稀罕的好东西！走过路过不要错过！"
D.Strings[690]="这一周可能有蝾螈的眼睛出售，下一周又可能是一张藏宝图。除非你亲眼看到，否则你永远都不会知道安东尼奥在卖什么！赶快来看看吧！"
D.Strings[691]="世界各地的冒险家都会给安东尼奥供货——快来看看本周的特价商品啦！"
D.Strings[692]="旅游者和冒险家们，快到城镇中心来抢购吧！安东尼奥的货物实在是物美价廉！来吧，大家都来看看啊！"
D.Strings[693]="暮色森林的旅行者们，大家好！现在我的商品全面特价，走过路过不要错过啦！"
D.Strings[694]="走一走看一看啦，来看看我的货啦！我不会在夜色镇待很久……好机会不要错过！"
D.Strings[695]="再见啦，夜色镇的居民们。希望大家不要错过下一次的机会……"
D.Strings[696]="呼，终于可以到赤脊山去了。离开这黑暗阴冷的暮色森林可真让人心情愉快。"
D.Strings[697]="哈哈！我找到伊丽莎白了！"
D.Strings[698]="把我的洋娃娃还给我！！"
D.Strings[699]="伊丽莎白！把我的伊丽莎白还给我！"
D.Strings[700]="不要伤害伊丽莎白，你这个坏蛋！"
D.Strings[701]="我要告诉妈妈！"
D.Strings[702]="不要拉她的头发！"
D.Strings[703]="她都哭了！"
D.Strings[704]="住手！你将会把她的头都扯掉的！"
D.Strings[705]="您好啊，艾米小姐。很高兴能回湖畔镇，很高兴还能看到您的芳容，亲爱的小姐。"
D.Strings[706]="你好，安东尼奥。很高兴能看到你平安无事地来到这里。如果有什么需要帮忙的话尽管说。"
D.Strings[707]="大家听着！大家听着！我会在湖畔镇暂住一段时间来出售我的东西。快点到市政厅来啊！"
D.Strings[708]="你的洋娃娃会不会游泳啊？哈哈！"
D.Strings[709]="我拿到你的洋娃娃了！哈哈！"
D.Strings[710]="你猜我这么弄的话，她会怎么样？"
D.Strings[711]="如果你想把她要回去，那你就得求我！"
D.Strings[712]="娇气包！娇气包！"
D.Strings[713]="把洋娃娃还给她！"
D.Strings[714]="啊！"
D.Strings[715]="我终于到湖畔镇了——大家都来啊，安东尼奥·皮雷利卖的可都是价廉物美的好东西啊。"
D.Strings[716]="安东尼奥·皮雷利卖的东西足以让你顺利在暮色森林旅行，湖畔镇现在就有卖了啊。"
D.Strings[717]="艾米，能再看到你真的很高兴。要小心，亲爱的。我现在要去闪金镇了。"
D.Strings[718]="安东尼奥，你自己要保重。我们以后会再见面的。"
D.Strings[719]="你好，我的朋友。很高兴又能见到你。看来你依然在守卫着我们的边境，安东尼奥对你的辛勤工作表示敬意。"
D.Strings[720]="非常感谢！我要上路了……大家都要多加小心啊！"
D.Strings[721]="你好，安东尼奥。再次感谢你卖给我妻子的帽子，她非常喜欢。"
D.Strings[722]="路上小心，安东尼奥。"
D.Strings[723]="哦，我的朋友，我会的，我会保重的。你们自己也千万要保重！"
D.Strings[724]="大甩卖啦！大甩卖啦！闪金镇的居民们快来看看啊，安东尼奥马上就要走了，好机会不要错过啊。"
D.Strings[725]="大家都过来看啊！安东尼奥又开始卖他的宝贝啦。下次我再来就可能是很久之后的事情了，大家都过来看看啊。"
D.Strings[726]="闪金镇的父老乡亲们，过来看看我这些价廉物美的好东西吧。我可能会有一段时间不再回来了！"
D.Strings[727]="再见了，闪金镇。我很快就会回来的——也许就只要一个星期。"
D.Strings[728]="又回到家了，又回到家了。"
D.Strings[729]="世界闻名的安东尼奥·皮雷利现在要在哨兵岭出售他的货物了！"
D.Strings[730]="哨兵岭附近有耐用的好东西在卖啊！都过来看看吧！时间不多了，大家赶快啊。"
D.Strings[731]="走过路过不要错过啊，我这里卖的都是价廉物美的好东西！大家都过来看看啊！"
D.Strings[732]="谢谢大家。我会在一周后回来。"
D.Strings[733]="我想接下来该去夜色镇了。"
D.Strings[734]="嗯……我闻到食物的味道了！"
D.Strings[735]="%s在搜寻……"
D.Strings[736]="%s继续搜寻着，找到后就扔进箱子里。"
D.Strings[737]="我检查完了，$n，我放心了。耶尼库不在这里面……"
D.Strings[738]="啊，好样的，$n。现在来看看这些会告诉我们什么……"
D.Strings[739]="%s开始咏唱……"
D.Strings[740]="那些该死的货物在什么地方？！我们已经等了好几天了！"
D.Strings[741]="笨蛋！我周围的这帮家伙全是笨蛋！"
D.Strings[742]="兽人都比这些家伙聪明！他们到底在哪里？"
D.Strings[743]="嘿，$n。你现在可以去找血顶巨魔的首领和他的巫医谈话了。"
D.Strings[744]="%s开始呼唤增援！"
D.Strings[745]="%s拿出了精神之眼和歌唱水晶……"
D.Strings[746]="我已经对耶尼库的灵魂宝石进行了加工，$n……"
D.Strings[747]="%s试着掰开玛雷的畸形足……"
D.Strings[748]="啊！它打开了！比我想象中要容易得多。谢谢你的帮助，$n！"
D.Strings[749]="好好好，我知道了！别喊了！"
D.Strings[750]="这最好是最后一个！"
D.Strings[751]="你最好帮帮我！"
D.Strings[752]="为什么我必须得接受一个术士的这种古怪的借口？"
D.Strings[753]="别那么没用，帮帮我的忙！"
D.Strings[754]="让我回去吧！我受够你了！"
D.Strings[755]="什么？你说你干不掉这个东西？"
D.Strings[756]="如果你再敢碰我一下，你就别想再碰别的什么东西了！"
D.Strings[757]="%s噼啪一声裂开了。"
D.Strings[758]="%s的力量随着石块剥落而迅速衰减。"
D.Strings[759]="%s身负重伤，但仍然继续战斗。"
D.Strings[760]="真有趣……这石头拥有巨大的魔法潜能，但却是完全天然的……"
D.Strings[761]="啊，太棒了！谁把这个留在这里的……？"
D.Strings[762]="斯莫特！嘿，斯莫特！出来玩玩吧！"
D.Strings[763]="再次感谢你的帮助。祝你一路顺风。"
D.Strings[764]="你已经完成了任务！"
D.Strings[765]="那些野兽来了！"
D.Strings[766]="你没能保护我免受那些猿人的伤害！"
D.Strings[767]="怎么了？是什么力量把我带到了这座海潮祭坛上？"
D.Strings[768]="野兽越来越多了！"
D.Strings[769]="肮脏的野兽！它们来了！"
D.Strings[770]="你上次给我带来不少乐子哪……出来吧！"
D.Strings[771]="斯莫特！"
D.Strings[772]="我保证这次我不会杀死你的船员，哈哈！但是我的兄弟可能会吃了他们！"
D.Strings[773]="出来，到加尼罗哨站来。我等着你，斯莫特……"
D.Strings[774]="斯莫特，你不想战斗吗？"
D.Strings[775]="你一艘船都没有了吗？你的勇气去哪里了？"
D.Strings[776]="我可不想整天陪着这座雕像玩。过来较量较量吧！"
D.Strings[777]="%s绝望地扔掉了他的毒瓶！"
D.Strings[778]="%s取出遥控器，掷出一辆模型蒸汽坦克！"
D.Strings[779]="%s开始发热冒烟！"
D.Strings[780]="依然没有最后一批炸药的任何消息。"
D.Strings[781]="还是没有最后一批炸药的消息。那些东西究竟在哪里？"
D.Strings[782]="这座桥早就该被摧毁了。那些懒东西从高地走到这里居然花了这么长时间！"
D.Strings[783]="救命！救命！不要让它们吃了我！"
D.Strings[784]="请救救我！"
D.Strings[785]="我不想成为食人魔的盘中餐！请救救我！"
D.Strings[786]="救~~命~~啊~~~~！！！"
D.Strings[787]="我听厌了这些废话！准备受死吧！"
D.Strings[788]="已经很久很久都没有人替我干这个苦差事了。"
D.Strings[789]="完了，我睡过头了！"
D.Strings[790]="%s逐页翻看着苏利的信。"
D.Strings[791]="这不公平！我最亲爱的苏利！回到我的身边吧！不，$n！为什么你带给我这样的消息！"
D.Strings[792]="嗝儿！"
D.Strings[793]="这些碎片让我毛骨悚然。嘿，格雷比，你找到别的碎片了吗？"
D.Strings[794]="即使我找到了也不会告诉你！因为告诉你的话……我就弄不到水晶了……"
D.Strings[795]="当然，如果密斯莱尔醒来的话，我才不愿意待在这里。他们说她脾气很不好……"
D.Strings[796]="比我想象中的要简单……索拉丁封印又变成完整的了。"
D.Strings[797]="请永远庇护我吧！"
D.Strings[798]="主人，您的英明举世无双！"
D.Strings[799]="如果我能从您的每次大买卖中提成一个铜币，那么我将会马上变成一个富有的狗头人！"
D.Strings[800]="没错，您一定能保护我们不受那个恶妇的伤害！"
D.Strings[801]="哦！太棒了！您的努力将使密斯莱尔长眠于地下！"
D.Strings[802]="我唯一的愿望只是希望能够服侍伟大的您，我愿为您赴汤蹈火！"
D.Strings[803]="您犹如高山一般强壮，而气质却又如微风一般优雅！"
D.Strings[804]="我的脚有些疼……"
D.Strings[805]="去死吧！你不该放走密斯莱尔的！"
D.Strings[806]="你会被碾成粉末的！"
D.Strings[807]="您是不是有点太矮了？"
D.Strings[808]="我的性命并不重要！重要的是一定要完成我们神圣的使命！"
D.Strings[809]="如果你想要释放密斯莱尔，那么你一定会后悔的！"
D.Strings[810]="站直了，弟兄们！不要怕！我们这里有大个的！"
D.Strings[811]="拿下那里！枯须狗头人必胜！"
D.Strings[812]="不！快走开！我们绝对不能失败！"
D.Strings[813]="那么就尽快开始吧。我们在这里待得越久，亡灵重回希尔斯布莱德作恶的可能性就越大。"
D.Strings[814]="好了，我们要在这儿真刀真枪地干一场。准备好！"
D.Strings[815]="替我断后！我要看看在这些垃圾里能找到什么……"
D.Strings[816]="%s开始翻找药剂师的东西。"
D.Strings[817]="我想我找到了一些东西……"
D.Strings[818]="我猜奎艾会认为这个很重要。她应该对这些东西相当熟悉——虽然她不是这方面的专家，但也算得上是知识渊博。"
D.Strings[819]="好，让我们赶快离开这里吧！你们继续跑。我要停一下。"
D.Strings[820]="你们成功了？！我很惊讶基恩洛并没有让你慢下来。那么，给我看看你们找到的东西。"
D.Strings[821]="%s研究着这圈石头，寻找着被碾压的痕迹。"
D.Strings[822]="你永远无法击败我们！"
D.Strings[823]="我的死微不足道……你们必将血债血还!"
D.Strings[824]="为了我们的主人们！欢呼吧！"
D.Strings[825]="诅咒你！"
D.Strings[826]="荣耀和鲜血全归上古之神！"
D.Strings[827]="主人！我听从你们的召唤！"
D.Strings[828]="你在这里的胜利只会加速你的灭亡！"
D.Strings[829]="入侵者！杀死他们！"
D.Strings[830]="为了我们的主人！"
D.Strings[831]="主人，这个$r就是我献给您的祭品！"
D.Strings[832]="杀啊！我要以他的名义奋勇作战！"
D.Strings[833]="杀啊！我能感受到你的恐惧，$c！"
D.Strings[834]="死亡降临了！欢呼吧！"
D.Strings[835]="入侵者！来得正好，我正无聊呢……"
D.Strings[836]="住手！愚蠢的$c，我们不能让你召唤密斯莱尔！"
D.Strings[837]="什么？$n，你做得很好，但……"
D.Strings[838]="你为什么这样急于召唤了我？我还没恢复我所有的力量！"
D.Strings[839]="不过没关系。你真是个笨蛋，居然帮助了我，现在是该让你付出代价的时候了！"
D.Strings[840]="好了，$n。跟我到那个洞里去一趟，我会试着把符石的能量注入到护目镜上。"
D.Strings[841]="我第一天来这里的时候就发现了这个洞穴。我相信这块石头里的能量对我们大有用处。"
D.Strings[842]="我要开始将石头中的能量提取出来。$n，你的工作就是保护我。这个地方是被诅咒过的……相信我。"
D.Strings[843]="%s开始在石头前修补护目镜。"
D.Strings[844]="快完成了！再给我一点点时间！"
D.Strings[845]="我完成了！我把石头的能量注入了护目镜！咱们赶快从这里出去吧！"
D.Strings[846]="呼……终于可以离开那个阴暗的洞穴了！"
D.Strings[847]="啊！又失败了！"
D.Strings[848]="%s被撕裂了，消逝得无影无踪。"
D.Strings[849]="一直以来你都在掠夺我们的财宝。这次准备葬身鱼腹吧！"
D.Strings[850]="没有什么可以阻止我们的！你死定了！"
D.Strings[851]="%s急躁地向沙克斯·奥布里耳语着什么。"
D.Strings[852]="等等，$n！！！看来我们有麻烦了……"
D.Strings[853]="救命啊！！我告诉过你这个地方是被诅咒过的！"
D.Strings[854]="赶快！只有干掉这些东西，我才能完成我的工作！"
D.Strings[855]="%s仔细翻看着萨拉·巴鲁的信，满怀忧郁地叹了口气。"
D.Strings[856]="这……这是什么？难道这就是托尔甘所说的萨满力量？"
D.Strings[857]="太神奇了！我感觉就如同获得了重生一般。我的力量又回来了！"
D.Strings[858]="只要我们现在能控制住他们，那就肯定能搞明白这件事情。"
D.Strings[859]="我去看看下面。"
D.Strings[860]="船长死了。"
D.Strings[861]="我们获救了！"
D.Strings[862]="%s心照不宣地向$n眨了眨眼。"
D.Strings[863]="%s向$n点了点头，若有所思地叹了口气。"
D.Strings[864]="%s开始检查他的包裹……"
D.Strings[865]="哈！就是这些！现在让我们把卷轴的碎片拼起来吧。"
D.Strings[866]="搞定了，$n。卷轴已经修复了！万岁！"
D.Strings[867]="%s开始在激流堡卫兵的尸体上搜寻徽章……"
D.Strings[868]="马库斯，特雷曼，奥斯古，拉普雷特……"
D.Strings[869]="弗塔恩，马克杜加，维尔考特……"
D.Strings[870]="塞欧里克，基特林，布莱塔，阿格蒙德……"
D.Strings[871]="赫鲁斯，提林，洛克威尔……"
D.Strings[872]="……萨普森，尤瑞克，查姆雷……"
D.Strings[873]="克雷门斯，巴索雷姆，恩德曼，维勒斯……"
D.Strings[874]="托米尔，加姆罗，谢菲尔德，考维恩……"
D.Strings[875]="马特斯，雷布洛克，艾迪亚特，尼克森……"
D.Strings[876]="%s叹了口气……"
D.Strings[877]="已经有这么多勇敢的战士失去了生命，在这场战役结束之前，我们可能还会失去更多……"
D.Strings[878]="谢谢你帮忙找回这些徽章，$n。我将通知阵亡者的家属。"
D.Strings[879]="%s为$n配制了一瓶药剂。"
D.Strings[880]="呱呱！不！！这不可能……呱呱！你骗了我……呱呱……你这个骗子！呱呱！"
D.Strings[881]="%s为$n烹制了美味的烤秃鹰翅膀。"
D.Strings[882]="乌萨尔的噩梦终结了！我们自由了！"
D.Strings[883]="%s把护目镜交给了德拉克里格博士。"
D.Strings[884]="德拉克里格博士将会给你进一步的指示，$n。很感谢你的帮助！"
D.Strings[885]="%s把她的包交给了奎艾。"
D.Strings[886]="我们成功了！奎艾，我们成功了！"
D.Strings[887]="呀，这里的鱼好像不咬钩。也许我该去水晶湖那边试试运气！"
D.Strings[888]="该死！这里的鱼也不上钩。我要回到原来的地方去。"
D.Strings[889]="你无法阻止被遗忘者，$r。黑暗女王将会让你感受到痛苦和恐惧。"
D.Strings[890]="你听好了，在我杀死你之后，你的身体将为我所用，$r。"
D.Strings[891]="你可以攻击我，但是你依然无法阻止我回到奎艾那里去。"
D.Strings[892]="我精通超过4门的语言。"
D.Strings[893]="啪嗒……咔咔……"
D.Strings[894]="主人，树都去哪里了？"
D.Strings[895]="我们能让它变得更好，更强，更快。我们不仅拥有技术，而且拥有强大的魔法。"
D.Strings[896]="总有一天我要成为一个真正的男孩。"
D.Strings[897]="荒芜之地真的很热，但至少还不潮湿。"
D.Strings[898]="检查完毕，一切正常。"
D.Strings[899]="主人，这里很危险。但我要去帮你站岗放哨。"
D.Strings[900]="%s疯狂地扑打着翅膀，发出刺耳的尖叫。你感到今天是劫数难逃了。"
D.Strings[901]="%s吃掉了$n的遗骸，因此它看上去平静了许多。"
D.Strings[902]="森林的精魂们感到相当不安……"
D.Strings[903]="黑木部族正在侵犯我们神圣的领土。"
D.Strings[904]="我们必须采取行动来对付黑木部族。"
D.Strings[905]="一股堕落的力量正在玷污我们神圣的森林。"
D.Strings[906]="我们绝不能允许黑木部族破坏神圣的大自然。"
D.Strings[907]="我感到树林中隐藏着极大的危险……"
D.Strings[908]="%s读着$n交给他的古书……"
D.Strings[909]="哈！就是它了！"
D.Strings[910]="卡尼克，我的朋友，我真希望能活着再见你一次，但是我们需要讨论一下拉格纳罗斯的问题。他的影响力正在不断扩大。"
D.Strings[911]="铁趾，无论生死，你都表现得一样坦然自若。你能告诉我些什么吗，老朋友？"
D.Strings[912]="我会尽快地告诉你更多内容，卡尼克。但是首先，请你让这位旅行者去找贝尔格拉姆——还有很多事情没做完呢。"
D.Strings[913]="%s把$n给他的物品一一放好。"
D.Strings[914]="感谢你，$n。我知道谁可以妥善地使用这个……"
D.Strings[915]="%s从$n手中接过古代遗物。"
D.Strings[916]="请接受我的谢意，$n。雅格因的笔记是你的了。"
D.Strings[917]="%s盘腿坐下，开始阅读雅格因的笔记……"
D.Strings[918]="%s被魔法击中了！"
D.Strings[919]="好吧，$n，让我们去找找看我到底把那神秘的化石留在哪里了。跟着我！"
D.Strings[920]="我到底把那个神秘的化石放在哪里了？啊，也许在那上面……"
D.Strings[921]="唉！上面什么都没有。"
D.Strings[922]="这里没有那块神秘的化石……啊，但是有《荆棘谷的青山》的手抄本。多好的一本书啊！"
D.Strings[923]="我敢和你打赌，我把那个东西留在帐篷里了！"
D.Strings[924]="哦，等等，那是霍莉的帐篷……但它是空的。"
D.Strings[925]="真有趣……之前我一直没有注意到这个……"
D.Strings[926]="%s端详着那块长满苔藓的石头。"
D.Strings[927]="哦，不对！我是来寻找那块化石的！"
D.Strings[928]="啊，真劲……"
D.Strings[929]="不，我没有把化石留在这里！"
D.Strings[930]="啊！现在我记起来了！我把那块神秘的化石交给霍莉了！去问问她吧。"
D.Strings[931]="%s重拾工作，将周围的一切都抛诸脑后。"
D.Strings[932]="哦，天呀！这是什么？快来帮忙！"
D.Strings[933]="看来我们发现了这个名叫$n的家伙。帮我把它干掉！"
D.Strings[934]="帮帮我！我甩不掉这个$n！"
D.Strings[935]="我感觉这个$n也想要这块神秘的化石。快来帮忙！"
D.Strings[936]="$n！帮帮我！"
D.Strings[937]="你能不能帮我搞定这个$n？"
D.Strings[938]="%s开始从地下吸收能量"
D.Strings[939]="%s盯着西北方，发出了一声怒吼。"
D.Strings[940]="%s发出震撼人心的怒吼。"
D.Strings[941]="我一直在等着你，$n。"
D.Strings[942]="现在来实地检测一下我的设计吧！"
D.Strings[943]="啊啊啊！它失控了！快跑！"
D.Strings[944]="我想我最好想点办法！"
D.Strings[945]="保护主人！"
D.Strings[946]="%s开始进行一个仪式……"
D.Strings[947]="完成了。"
D.Strings[948]="图腾做好了，$n。"
D.Strings[949]="%s高高地举起$n交给他的东西……"
D.Strings[950]="拉格纳罗斯？这真是个可怕的消息……"
D.Strings[951]="快跑……<咳嗽>去找……<咳嗽>雷杜尔……"
D.Strings[952]="你听说过他的，旅行者。当你准备好去找贝尔格拉姆谈谈的时候再来找我。"
D.Strings[953]="%s不安地盯着鲁特维尔。"
D.Strings[954]="你好，我是来参加训练的。"
D.Strings[955]="什么时候才会有人来对付这些亡灵？"
D.Strings[956]="人都去哪里了？"
D.Strings[957]="我甚至都不能够安静地祭拜我父亲的墓地。"
D.Strings[958]="为什么暴风城的卫兵还没有来？"
D.Strings[959]="恐怕黑暗正在向我们逼近。"
D.Strings[960]="圣光似乎遗弃了我们。"
D.Strings[961]="祝你在藏宝海湾玩得开心，$n！"
D.Strings[962]="祝你的棘齿城之旅一路顺风，$n！"
D.Strings[963]="祝你的奥格瑞玛之旅一路顺风，$n。代我向萨尔问好！"
D.Strings[964]="祝你的幽暗城之旅一路顺风，$n！小心不要摔跤……"
D.Strings[965]="祝你的格罗姆高之旅一路顺风，$n！"
D.Strings[966]="祝你的奥格瑞玛之旅一路顺风，$n！"
D.Strings[967]="祝你的幽暗城之旅一路顺风，$n！"
D.Strings[968]="%s开始在他的包里寻找合适的施法材料。"
D.Strings[969]="谁敢如此大胆？！你死定了！"
D.Strings[970]="你们好啊！"
D.Strings[971]="咕哝 咕哝……"
D.Strings[972]="%s倒在地上。在咽下最后一口气后，他的灵魂得以解脱。"
D.Strings[973]="不要碰中尉的东西！"
D.Strings[974]="%s听着$n的报告……"
D.Strings[975]="什么？？火刃氏族也许正在不断扩张！我们必须马上进行调查！"
D.Strings[976]="谢谢你，$n。我的兄弟也很感谢你。"
D.Strings[977]="%s击碎了那毫无生气的扭曲的爪子。"
D.Strings[978]="我们怎能忍受有恶魔的爪牙在这片土地上肆虐横行！"
D.Strings[979]="%s开始变得神情恍惚……"
D.Strings[980]="%s被魔法的火焰吞噬了！"
D.Strings[981]="$n，以我的能力还无法揭开项圈的秘密……"
D.Strings[982]="%s仔细观察着灼热项圈……"
D.Strings[983]="有趣，非常有趣。你是在杜隆塔尔找到这个的，$n？"
D.Strings[984]="这个项圈被注入了恶魔的力量，$n。它将会给我们的人民带来灾难。"
D.Strings[985]="嗯……很感谢你能把这个东西交给我，$n。"
D.Strings[986]="这是一个危险的东西，$n。我很高兴你能把它带来。"
D.Strings[987]="新鲜的面包！刚出炉的新鲜面包！"
D.Strings[988]="赶快来买啊！新鲜的大面包啦！"
D.Strings[989]="各种各样的面包！都是新鲜出炉的啊，走过路过不要错过！"
D.Strings[990]="面包，卖面包啦！保证新鲜！快来买啊！"
D.Strings[991]="%s在仪式中使用$n提供的祭品……"
D.Strings[992]="%s从$n手中接过东西，开始咏唱咒语……"
D.Strings[993]="%s不断地吸取能量……"
D.Strings[994]="%s用$n给他的材料制成了净化图腾……"
D.Strings[995]="%s开始制造新的图腾……"
D.Strings[996]="净化图腾已经完成了，$n。"
D.Strings[997]="图腾做好了，现在你可以去净化水井了。"
D.Strings[998]="$n，净化图腾已经做好了。"
D.Strings[999]="图腾做好了。"
D.Strings[1000]="图腾已经做好了。$n，现在就去净化水井吧。"
D.Strings[1001]="你提供的材料非常纯净，$n。这根新的净化图腾相当强大。"
D.Strings[1002]="%s站在部族之火前，把井石与琥珀颗粒混合起来，然后开始咏唱咒语。"
D.Strings[1003]="先知之水已经为你准备好了，$n。"
D.Strings[1004]="从箱子里拿一根诱灵蜡烛，$n。"
D.Strings[1005]="我的佩剑阿契厄斯伴随了我一生，但是现在我的灵魂已经脱离了痛苦，我已经不再需要它了。"
D.Strings[1006]="我希望能得到我女儿的爱，也希望我犯下的罪恶能够得到宽恕。"
D.Strings[1007]="%s变得头昏眼花"
D.Strings[1008]="我被杀死了！召唤维罗戈！"
D.Strings[1009]="厄运的深渊"
D.Strings[1010]="%s的血液开始涌动，迅猛龙的力量流遍了他的全身。"
D.Strings[1011]="%s碾碎了$n交给他的珍珠……"
D.Strings[1012]="小心！我们正在被一个$n攻击！"
D.Strings[1013]="搞定了。一批新的闪光弹！"
D.Strings[1014]="接招吧，畜牲！"
D.Strings[1015]="%s扔出炸弹，那炸弹落在他前方不远处。"
D.Strings[1016]="众月之泪的魔力是我的！我的！我的宝贝！"
D.Strings[1017]="%s开始擦拭众月之泪。"
D.Strings[1018]="力量！显赫的力量！"
D.Strings[1019]="%s开始发出奇怪的咕噜声。众月之泪掉到地上，摔得粉碎。"
D.Strings[1020]="哇！……哇！……啊啊啊！真受不了。哎哟！……啊呀！你想杀了我么？！"
D.Strings[1021]="好吧好吧！我想我能找出操作这个东西的办法……"
D.Strings[1022]="嗯，我想我知道该怎么做了。跟我来，$n！"
D.Strings[1023]="我们好像走出森林了？这到底是怎么一回事……"
D.Strings[1024]="我要把这个带到棘齿城去，没有什么东西能阻止我！"
D.Strings[1025]="帮帮我！等等！这个东西好像有自己的思维！"
D.Strings[1026]="尝尝这个！"
D.Strings[1027]="我快要死了，我心里很清楚！"
D.Strings[1028]="拿着那个！哦……我肯定是按错了键……等等，试试这个！"
D.Strings[1029]="啊啊啊！不对！"
D.Strings[1030]="这个就是被盗的伐木机！把它给解决掉，不然鲁格维兹会扒了我们的皮！"
D.Strings[1031]="真玄啊！继续前进吧，我们就要到了。"
D.Strings[1032]="快点，不要停！"
D.Strings[1033]="嗯……我不认为那个红色的闪光是个好兆头……"
D.Strings[1034]="哦，小子，你觉得，如果伐木机有一点……不正常，斯布特瓦夫会介意吗？"
D.Strings[1035]="我会努力让它重新动起来。你先回去吧，我随后会自己回来。"
D.Strings[1036]="%s发出微光，闪烁着……然后就没了！"
D.Strings[1037]="%s从阴影中召唤出更多的同伙。"
D.Strings[1038]="%s爆发出强大的怒气，他变得异常狂怒！"
D.Strings[1039]="护卫舰！这一定是兽人的船！开火！"
D.Strings[1040]="海平线那边是什么东西？肯定是敌人的船！开火！"
D.Strings[1041]="在东边的海平线上发现有船只在航行！那肯定是入侵者！开火！"
D.Strings[1042]="那是什么奇怪的东西？注意警戒！"
D.Strings[1043]="那是什么？海巨人？为了保险起见，开火！"
D.Strings[1044]="是敌人！开火！"
D.Strings[1045]="敌人在那边！开火！"
D.Strings[1046]="北边发现敌人！开火！"
D.Strings[1047]="陆地上有敌人！开火！"
D.Strings[1048]="发现敌人！开火！"
D.Strings[1049]="敌人从西北方攻过来了！开火！"
D.Strings[1050]="在那边！开火！"
D.Strings[1051]="%s听到呼救声后立刻做好了战斗准备！"
D.Strings[1052]="%s大声呼救！"
D.Strings[1053]="靠紧点，$n。我们必须全力以赴才能冲出包围圈。出发吧！"
D.Strings[1054]="终于从北方城堡出来了！给我一点时间，让我好好呼吸一下这自由的空气……"
D.Strings[1055]="现在我感觉好多了。让我们返回棘齿城吧，$n。"
D.Strings[1056]="好像有南海海盗在这附近出没，这样事情就有点麻烦了。"
D.Strings[1057]="就快回到棘齿城了！再加把劲……"
D.Strings[1058]="啊，棘齿城！清新的海风！我回来了！"
D.Strings[1059]="沙罗萨斯船长，这位$n帮助我重获了自由！$n，我相信船长会因你的勇敢而奖励你的。"
D.Strings[1060]="$n正往我们这边过来！"
D.Strings[1061]="把这个$n给干掉！"
D.Strings[1062]="救命啊！$n在攻击我！"
D.Strings[1063]="$n朝这边来了！杀啊！"
D.Strings[1064]="%s把孢子放进了他的炼金容器里……"
D.Strings[1065]="啊，很好。这些孢子相当不错。谢谢你，$n。"
D.Strings[1066]="谢谢你收集的这些孢子，$n。"
D.Strings[1067]="我来了！入侵者们，你们的末日到了！"
D.Strings[1068]="%s从沙土中钻出，想要保护它的卵。"
D.Strings[1069]="谢谢，$n。我会立刻出售这些饮料！"
D.Strings[1070]="太感谢你了，$n。这些角会给我带来好运的！"
D.Strings[1071]="这些牛角会给我带来好运的，$n。太感谢你了！"
D.Strings[1072]="万分感谢！另外……请不要告诉别人我的酒是用什么酿的！"
D.Strings[1073]="%s仔细检查着那些钳嘴龟的壳……"
D.Strings[1074]="我们到别的地方去试试吧。"
D.Strings[1075]="奇怪。非常奇怪……"
D.Strings[1076]="$n。这些甲壳告诉了我很多事情，但同时也带来了更多谜团……"
D.Strings[1077]="伙计们，咱们去另一边试试吧。"
D.Strings[1078]="比利说费索曾是个伟大的巫师。但是当他的某一个法术失败了之后，他就被变成了一只兔子。"
D.Strings[1079]="我们为什么要走这条路？"
D.Strings[1080]="我们要去哪里？"
D.Strings[1081]="我要上厕所。"
D.Strings[1082]="我要去看法师塔。"
D.Strings[1083]="真的吗？运河里真的有鳄鱼吗？"
D.Strings[1084]="我腿疼！"
D.Strings[1085]="你说，为什么咱们总是沿着这条路线跑？"
D.Strings[1086]="新鲜的面包啦！"
D.Strings[1087]="热乎乎的新鲜面包啦！"
D.Strings[1088]="长面包，圆面包，各种各样的面包，都是新鲜出炉的啊！"
D.Strings[1089]="新鲜出炉的面包！"
D.Strings[1090]="有水吗，艾玛？去弄点水，艾玛？你要是再不去打水，我都快忘了水是什么样的了……"
D.Strings[1091]="我这么多年来好像都没干过比打水更有意义的事情似的！"
D.Strings[1092]="我一天要走好多趟到水井那边去打水，现在的年轻人啊……"
D.Strings[1093]="我只是在自言自语罢了，和这里的其他人说话的时候，我总是得不到应有的尊重。"
D.Strings[1094]="我总有一天要把他用那件蓝色的长袍裹起来，和他的扫帚一起扔到河里去。"
D.Strings[1095]="每天都要累死我！"
D.Strings[1096]="我要上路了。"
D.Strings[1097]="有那么一小会儿，我以为自己回家了……在亡灵天灾到来之前的那个家……"
D.Strings[1098]="你彻底地激怒了我！我要让你好好见识一下海潮之石的真正力量！"
D.Strings[1099]="%s跟$n轻声说着什么，然后塞给$g他:她;一件小东西。"
D.Strings[1100]="从桌上拿一块石头，$n。你会需要它的。"
D.Strings[1101]="以大地和风暴的力量，以及……"
D.Strings[1102]="啊~~~！"
D.Strings[1103]="发生什么事情了，大地母亲？为什么我的法术失败了？"
D.Strings[1104]="嗯，我来了，快过来买我的东西吧！你们不买，另一边那些家伙就要买了！"
D.Strings[1105]="瑟格拉神情恍惚地发了会儿呆，然后看着天空。"
D.Strings[1106]="我明白了，大地母亲。"
D.Strings[1107]="别在这儿浪费更多的时间了。鬼魂都是穷鬼！"
D.Strings[1108]="你终于还是做了。我原以为你比南海镇的那帮家伙要好得多。他们会买走我所有的东西！可惜他们都死了。"
D.Strings[1109]="大地母亲，请赐予我恢复自然平衡的力量吧！"
D.Strings[1110]="平衡已经恢复了！"
D.Strings[1111]="%s仔细检查着徽记……"
D.Strings[1112]="$n，看苔藓下面，这徽记看上去好像一颗种子！"
D.Strings[1113]="让我来把它种在我特制的土壤里……"
D.Strings[1114]="现在大家看到的是光明大教堂，暴风城的精神和宗教中心。"
D.Strings[1115]="我们为什么一定要了解这些东西呢？"
D.Strings[1116]="这比光看历史书上的图片要好多了。"
D.Strings[1117]="我要去大图书馆看龙骨。"
D.Strings[1118]="老师，我们什么时候去看那个闪光的法师塔呀？"
D.Strings[1119]="我听说这里还埋着些兽人。"
D.Strings[1120]="老师，我要上厕所！"
D.Strings[1121]="老师，暴风城里有暗夜精灵吗？我以前从来没见过暗夜精灵。"
D.Strings[1122]="老师，他一直在戳我！"
D.Strings[1123]="现在我们看到的是暴风要塞。在第一次兽人战争中，暴风城堡被部落夷为平地，后来人们在废墟上重建了暴风要塞。"
D.Strings[1124]="你们这些废物快给我干活去！这艘船必须马上建好。"
D.Strings[1125]="入侵者！杀死他们！不要让他们进入房间！"
D.Strings[1126]="再让我看到有人偷懒，我就剁了他的头！"
D.Strings[1127]="火炮必须马上完工。"
D.Strings[1128]="把这些东西搬到船上去！"
D.Strings[1129]="谁说要休息？想都别想！赶快去干活，你们这些蠢货！"
D.Strings[1130]="你们几个！去看看那边是怎么回事！"
D.Strings[1131]="我们被攻击了！把他们都干掉！"
D.Strings[1132]="%s充满恐惧地想要转身逃跑！"
D.Strings[1133]="%s看到朋友在战斗中倒下，变得非常愤怒！"
D.Strings[1134]="%s种下了布满苔藓的徽记……"
D.Strings[1135]="圣骑士是在这儿接受训练的吗？"
D.Strings[1136]="没错，的确是这样的。圣骑士和牧师们就在大教堂里接受真知的洗礼。"
D.Strings[1137]="孩子们，跟上，我们马上就能看到安度因·乌瑞恩国王陛下和他的王座了。"
D.Strings[1138]="%s从发光的水果中取出种子……"
D.Strings[1139]="让我们看看这些种子是如何在我准备的土壤里生长的……"
D.Strings[1140]="%s种下了水果种子。"
D.Strings[1141]="%s快步来到培养槽前。"
D.Strings[1142]="我希望这种植物可以顺利生根……"
D.Strings[1143]="部落被击败之后，人们回到这里重建这座伟大的城市，纪念那些为保卫我们而献出生命的勇士。"
D.Strings[1144]="好了……现在我们去英雄谷参观那儿的纪念碑，悼念在两次兽人战争中牺牲的英雄们。跟着我，孩子们。"
D.Strings[1145]="孩子们，这里是不是十分壮观？所有人都要在这些伟大的英雄的注视下进入暴风城。"
D.Strings[1146]="多么震撼人心啊！孩子们，回到学校以后，你们都要谈谈对这些英雄人物的看法。"
D.Strings[1147]="接下来，我们要去教堂广场看看光明大教堂。"
D.Strings[1148]="天哪……密斯特……发生了什么事情……？"
D.Strings[1149]="%s破土而出了！"
D.Strings[1150]="杀！！！"
D.Strings[1151]="%s象幼兽追随父母般快乐地跟在$n身后。"
D.Strings[1152]="我会保护你的！"
D.Strings[1153]="%s开始摆弄两块化石上的雷鲁之石。"
D.Strings[1154]="以群星的名义！"
D.Strings[1155]="过去的事情谁也说不清，但重要的是我们的未来！"
D.Strings[1156]="谁召唤了阿曼？"
D.Strings[1157]="啊，你终于带着那些古物回来了。"
D.Strings[1158]="注意，即使是创物之神也可能犯错。"
D.Strings[1159]="对你的过去了解得越多，你的未来就越危险。"
D.Strings[1160]="%s躲藏在灌木丛中。"
D.Strings[1161]="%s在你眼前突然消失。"
D.Strings[1162]="我可以自己想办法回去了，$n。谢谢你！"
D.Strings[1163]="好的，我们走吧！"
D.Strings[1164]="%s消失在森林中。"
D.Strings[1165]="快来问我怎样才能在蓝色隐士获得免费的饮料吧！"
D.Strings[1166]="在蓝色隐士有免费的饮料！"
D.Strings[1167]="到蓝色隐士去，那里每个人都知道你的名字！"
D.Strings[1168]="过来喝杯啤酒，享受一下这里的欢乐气氛！"
D.Strings[1169]="繁重的魔法研究让你身心疲惫吗？到蓝色隐士放松一下！"
D.Strings[1170]="到蓝色隐士来吧，暴风城唯一一个魔法和精神完美结合的地方！"
D.Strings[1171]="感到忧郁了？来蓝色隐士放松一下吧！"
D.Strings[1172]="天气太热吗？在猪和哨声旅店喝点东西凉快一下吧！"
D.Strings[1173]="在猪和哨声旅店享受夜晚的喧闹和最好的啤酒！"
D.Strings[1174]="猪和哨声旅店有免费的啤酒供应！"
D.Strings[1175]="要想得到猪和哨声旅店的免费啤酒券的话，就赶快来找我！"
D.Strings[1176]="比精灵更聪慧！比兽人更强壮！暴风城没有比这更好的酒了！"
D.Strings[1177]="你厌倦了那些娘娘腔的法师才喜欢喝的水了？来猪和哨声旅店享受一下真正的男人该喝的酒！"
D.Strings[1178]="刚刚长途旅行归来？在猪和哨声旅店休息放松一下吧！"
D.Strings[1179]="%s饿了……"
D.Strings[1180]="峭壁之泉在东边和北边的山脉之间。"
D.Strings[1181]="谢谢你，$n。祝你好运。"
D.Strings[1182]="贫瘠之地最好的武器！"
D.Strings[1183]="快来看看！这里有灰谷最好的武器供你选择！"
D.Strings[1184]="里扎雷克斯这里有利刃，里扎雷克斯这里有铁锤，里扎雷克斯这里有你需要的所有武器！"
D.Strings[1185]="快点行动！限量发售，不要错过了！快来选购你的武器！"
D.Strings[1186]="%s研究着从暮光之书上撕下来的羊皮纸……"
D.Strings[1187]="%s陷入了沉思……"
D.Strings[1188]="%s弯下身子仔细察看他的枪。"
D.Strings[1189]="阿瑟罗克展示货物"
D.Strings[1190]="埃瑟里克斯指着你大声咆哮，言语实在是不堪入耳。这是你听到的最后的话。"
D.Strings[1191]="我的灵魂终于可以安息了……哦，亲爱的塞瑞利恩……"
D.Strings[1192]="%s面朝东南方呜咽了几声后，转过来看着你。"
D.Strings[1193]="%s朝特伦希斯咆哮着，希望引起他的注意。"
D.Strings[1194]="锐爪？！放松点，我的朋友……你的主人沃科尔在哪里？"
D.Strings[1195]="%s朝特伦希斯发出悲鸣，咆哮着用力地刨着地面。"
D.Strings[1196]="放松，放松，我的朋友。等一下……"
D.Strings[1197]="很好。现在告诉我发生了什么，锐爪。"
D.Strings[1198]="%s继续朝特伦希斯咆哮着，这次德鲁伊似乎理解了这头熊的意思。"
D.Strings[1199]="我明白，朋友。我会找人去帮助你的主人。现在你要回到他那边去，至少离他近一点。"
D.Strings[1200]="%s向特伦希斯发出感激的咆哮。"
D.Strings[1201]="%s对你咆哮，然后伸出鼻子嗅了嗅你。"
D.Strings[1202]="我就知道弗拉冈特最后会派人去寻找化石的。"
D.Strings[1203]="再次感谢你，$n。我现在要上路了。如果可以的话，请你去找特伦希斯，告诉他我已经安全逃脱了。"
D.Strings[1204]="现在不走更待何时！记住，一旦我们安全地回到大路上，你就回特伦希斯那儿去，让他知道我们已经顺利逃脱了。"
D.Strings[1205]="%s大声咆哮着，变形跑了出去。"
D.Strings[1206]="现在把这些稀土放到我的培养槽里去……"
D.Strings[1207]="再次感谢你，$n。这些稀土对我的实验帮助很大。"
D.Strings[1208]="%s激动地大声咆哮，快步奔向沃科尔。一跑到主人面前，它就迫不及待地伸出舌头去舔主人的脸。"
D.Strings[1209]="解散，$n。"
D.Strings[1210]="我们成功了，朋友。请找到特伦希斯，告诉他我们安全了。再次感谢你。"
D.Strings[1211]="锐爪，我也很高兴能见到你！看来并非所有陌生人都是有敌意的，对吧？特伦希斯一定会好好地奖赏这位冒险者的。"
D.Strings[1212]="那是什么声音？听起来像什么动物的吼叫声。"
D.Strings[1213]="%s开始对锐爪施放法术。"
D.Strings[1214]="我马上就出发，$n。"
D.Strings[1215]="嗯……我的针线在哪里？啊！在这里……"
D.Strings[1216]="%s在你取走披风的同时开始施放法术。"
D.Strings[1217]="他们来了！"
D.Strings[1218]="我们一定可以战胜这些邪恶的生物！"
D.Strings[1219]="即便是死，也要死得轰轰烈烈！"
D.Strings[1220]="不要放弃！誓死奋战！"
D.Strings[1221]="在唤醒仪式开始前我必须做好必要的准备。你要保护我！"
D.Strings[1222]="这些洞穴曾经是一座神殿，是贫瘠之地万物生长的保证。现在那里简直就是个地狱。"
D.Strings[1223]="过来，我们一定要继续下去。在我们把纳拉雷克斯从噩梦中拯救出来之前还有很多事情要做。"
D.Strings[1224]="我必须在这个火焰法阵中使用法术来驱逐那些德鲁伊的灵魂。"
D.Strings[1225]="这些洞穴已经被净化了，现在我们得赶去纳拉雷克斯的藏身之地！"
D.Strings[1226]="这边走。小心点，朋友。我感觉到纳拉雷克斯正在被噩梦折磨……"
D.Strings[1227]="我要从这里的喷泉中收集圣水，把它与那些堕落德鲁伊的血液混合起来。"
D.Strings[1228]="现在我有了必需的东西，继续进行下一步吧。"
D.Strings[1229]="纳拉雷克斯就在这个走廊的尽头沉睡着。我们要赶快唤醒他，否则就太晚了。"
D.Strings[1230]="在我进入翡翠梦境拯救纳拉雷克斯的时候，你一定要保护好我！"
D.Strings[1231]="%s开始进行唤醒纳拉雷克斯的仪式。"
D.Strings[1232]="[PH]这是一个占位符动作，直到我取消我的咒符。"
D.Strings[1233]="纳拉雷克斯终于从噩梦中醒过来了！"
D.Strings[1234]="%s在噩梦中辗转反侧。"
D.Strings[1235]="%s痛苦地挣扎着。信徒们似乎快要打进来了。"
D.Strings[1236]="%s梦见了可怕的场景，一些东西在黑暗的水下搅动着。"
D.Strings[1237]="我终于醒来了！"
D.Strings[1238]="啊，我终于从可怖的噩梦中被拉回来了！谢谢你，我忠诚的信徒，还有你勇敢的同伴。"
D.Strings[1239]="上啊！帮我把这个$n干掉！"
D.Strings[1240]="干掉这个该死的$n！我要准备唤醒纳拉雷克斯了！"
D.Strings[1241]="我一个人解决不了这个$n！救命啊！"
D.Strings[1242]="毫无疑问，这个$n是从纳拉雷克斯的噩梦里跑出来的！"
D.Strings[1243]="安娜雅……？我的双眼没有欺骗我吗？真的是你吗？"
D.Strings[1244]="岁月对我和你都很残酷，我的爱人……但最后我们还是重逢了。"
D.Strings[1245]="命运是如此残酷，它让我们在分别了数千年之后才能重逢……"
D.Strings[1246]="我的爱人，你恨我吗？我在万般无奈之下摧毁了你的躯壳，因为只有这样才能让你从痛苦中永久地解脱。"
D.Strings[1247]="亲爱的，不要为此而感到内疚。你使我从无尽的苦楚和折磨中解脱了出来，我只会为此而更加爱你。"
D.Strings[1248]="但是，即使是这经过数千年的分离才换来的重逢也是如此短暂……我和这个世界的联结正在逐渐减弱，我正在慢慢地离开它……离开你……"
D.Strings[1249]="再见了，塞瑞利恩，我的爱人。我们终能再见……"
D.Strings[1250]="%s柔和的声音在薄雾中轻轻回响，“我永远爱你……”"
D.Strings[1251]="不！安娜雅……安娜雅！请不要离开我！不……"
D.Strings[1252]="怎么办，我的爱人？没有你，我怎么办……没有你……我如何有勇气在这个世界上生存……"
D.Strings[1253]="%s向$n挥了挥手。"
D.Strings[1254]="现在出发，$n。去找沃科尔……记着，除了交谈以外，与任何人交流都会使你身上的魔法保护失效。"
D.Strings[1255]="%s仔细检查着营地的参观者。"
D.Strings[1256]="啊，欢迎您，$g先生:我亲爱的女士;！"
D.Strings[1257]="我们必须赶快行动。奥伯丁离这里不远，但是有很多敌人潜伏在森林里。"
D.Strings[1258]="准备去死吧，废物圣骑士！"
D.Strings[1259]="刺客……最好在他们找到我们之前快点离开这里。"
D.Strings[1260]="埃其亚基的灵魂之力在你身上流动，$n。"
D.Strings[1261]="%s伸了个懒腰，打了一个长长的哈欠。"
D.Strings[1262]="伊沙姆哈尔的愤怒流经你的身体，$n。"
D.Strings[1263]="拉克塔曼尼的力量与你同在，$n。"
D.Strings[1264]="你具有了奥瓦坦卡的速度，$n。"
D.Strings[1265]="你将会坚定不移，$n，因为你已经具有了瓦希塔帕恩的决心。"
D.Strings[1266]="依沙瓦克的精神给了你力量，$n。"
D.Strings[1267]="特伦希斯和莱恩派我来找你。灰谷的哨兵需要帮助。"
D.Strings[1268]="谢谢你，特伦希斯。我会尽可能留在这里帮忙的。"
D.Strings[1269]="希望我能派一些人来帮助灰谷的哨兵部队。"
D.Strings[1270]="你好，塞拉伊。很遗憾此时我不能帮助你，但是在灰谷的一些探险者可能会……"
D.Strings[1271]="再次感谢你，特伦希斯。如果你需要帮助，我会再次回来。在此之前，请派遣更多的冒险者到灰谷去。"
D.Strings[1272]="%s将巴斯兰的头发混合在一起……"
D.Strings[1273]="混合物完成了，$n。现在我们要去救那个孩子。"
D.Strings[1274]="一个圣骑士！杀死他的话，主人会很高兴的。进攻！"
D.Strings[1275]="我们继续前进吧，否则会碰到更多想要我命的东西。"
D.Strings[1276]="你躲不了的，小圣骑士！"
D.Strings[1277]="净化者德尔格伦不在的时候你好像不太自信，不是吗？"
D.Strings[1278]="今晚，你的血将会染红我们祭坛的圣石。"
D.Strings[1279]="干得好！我应该可以自己离开这里了。记着到灰谷的梅伊瑟娜岗哨去和净化者德尔格伦谈谈。"
D.Strings[1280]="啊……这种疾病相当厉害。它会影响人的心智……"
D.Strings[1281]="我必须……抵抗！"
D.Strings[1282]="我险些就被那些亡灵的毒药所害，$n，现在我知道必须要做什么了。"
D.Strings[1283]="终于从这个肮脏的房间逃了出来！让我带你到院子里去……"
D.Strings[1284]="你居然想要对付这扇门后的那些怪物，你真的很勇敢。"
D.Strings[1285]="%s在院子的门上摸索那把生锈的锁。"
D.Strings[1286]="希望你能解决掉阿鲁高。我必须赶快回到哈德瑞克那里。"
D.Strings[1287]="这些雕像一定有暗格……"
D.Strings[1288]="它被锁住了！不！！"
D.Strings[1289]="%s从阴影中跳了出来！"
D.Strings[1290]="有人杀死了那个可怜的家伙。"
D.Strings[1291]="就这一次我同意你的意见……垃圾。"
D.Strings[1292]="密斯特！我担心再也看不到你了！嗯，我很好，不用担心我。你必须好好休息，恢复健康。"
D.Strings[1293]="跟着我，我将会为你打开庭院的门。"
D.Strings[1294]="我能打开这扇门。但是为什么正好我就没法打开监牢的门呢？"
D.Strings[1295]="搞定了！祝你们好运。我必须马上回去向肯瑞托报告！"
D.Strings[1296]="给你，蕾拉。喝下这个……"
D.Strings[1297]="%s喝下了$n带来的药水。"
D.Strings[1298]="啊……爸爸……？你在那边吗？我很饿……我能吃点炖肉吗？"
D.Strings[1299]="你醒了？？药水起作用了！谢谢你，$n。"
D.Strings[1300]="%s在进入森林之前大声咆哮着以示感谢。"
D.Strings[1301]="赶快去，$n。我的命运掌握在你手中。"
D.Strings[1302]="%s施放魔法保护自己。"
D.Strings[1303]="%s消失了。"
D.Strings[1304]="你们这些旱鸭子比我想象的要厉害多了！看来我要认真一些了！"
D.Strings[1305]="啊！我要发火了！"
D.Strings[1306]="%s碾碎了月亮石，放入一杯茶水中。"
D.Strings[1307]="蕾拉，喝了它 ……"
D.Strings[1308]="%s扔掉武器，点燃了一捆炸药！"
D.Strings[1309]="嗯……我现在不想睡了，爸爸，我们可以出去玩吗？"
D.Strings[1310]="蕾拉……你醒了？"
D.Strings[1311]="现在你需要休息，我的女儿。"
D.Strings[1312]="%s盯着$n，喜极而泣。"
D.Strings[1313]="蕾拉获救了，$n。太感谢你了。"
D.Strings[1314]="%s开始检查这些古老的小雕像。"
D.Strings[1315]="$n，现在我又需要你的帮助了。"
D.Strings[1316]="女神啊，我同伴的数量正在不断地减少，我的力量很快就不足以阻止费伍德森林的恶魔了。"
D.Strings[1317]="女神啊，赐予我战胜敌人的力量吧！女神啊，请听我说，我现在要拼死一搏了，我所做的一切都是为了正义！"
D.Strings[1318]="什么……这是什么？这就是女神对我祈祷的回应？艾露恩赐予我一件武器，一把镰刀，去打败那些恶魔！"
D.Strings[1319]="我失败了……我最终还是失败了……我愧对我的同胞……狼人肆虐，而女神赐予我的镰刀也丢失了。"
D.Strings[1320]="我引来了这些邪恶的生物……当初女神赐予我的圣物到底在哪里……究竟是谁在主导这一切？"
D.Strings[1321]="%s开始召唤守卫！"
D.Strings[1322]="$n，如果你想要去十字路口，先沿着路向东然后朝北走。"
D.Strings[1323]="悉尼迟到了。我原本以为现在他该到家了。"
D.Strings[1324]="女士，他是你的丈夫，不是我的。你问我他在哪里干什么？"
D.Strings[1325]="他一定被修道院的工作拖住了。但是不管怎么样，他现在也该回来了。"
D.Strings[1326]="净化这个世界上的污秽并不是一件容易的事，南希。但是总是要有人去做这样的事情的。"
D.Strings[1327]="好吧，我要出去检查一下。似乎有些不对劲。"
D.Strings[1328]="哦，好吧……"
D.Strings[1329]="似乎我们遇到麻烦了。打起精神来，他们来了！"
D.Strings[1330]="小心！我感到附近有邪恶的存在……亡灵！"
D.Strings[1331]="又是这三个？"
D.Strings[1332]="这个混蛋终于得到了应有的报应。"
D.Strings[1333]="%s揭开安东的信上的封印，开始仔细阅读信件。"
D.Strings[1334]="以圣光的名义！这绝不是个好消息。有些东西你可能不能理解，$n。"
D.Strings[1335]="%s把安东的信扔在桌上。"
D.Strings[1336]="这根杖的设计很简单。达图尔在制造它的时候没有使用他的奥术知识……蕴含在其中的主要是德鲁伊的魔法。"
D.Strings[1337]="呵呵……我语带双关，不是吗？都是德鲁伊的东西……我很幽默吧。"
D.Strings[1338]="嗯，现在我们可以把节杖组合起来了……要试试吗？"
D.Strings[1339]="啊！这还不坏。你和莱恩打算拿这东西去做什么来着？这东西可真强力！"
D.Strings[1340]="如果你有时间，锐爪和他的主人沃科尔需要你的帮助。要是你感兴趣的话，就继续和我谈谈吧……"
D.Strings[1341]="%s伸手去抓住他的毒匕首！"
D.Strings[1342]="嗯？看看这是什么？"
D.Strings[1343]="欢迎来到监狱！"
D.Strings[1344]="外来者！杀掉他们！"
D.Strings[1345]="又来了几个典狱官的狗腿子！"
D.Strings[1346]="告诉典狱官，这座监狱现在是我们的地盘了！"
D.Strings[1347]="我会很快解决你，而且会让你感到无比的痛苦！"
D.Strings[1348]="我要把你彻底击败！"
D.Strings[1349]="杀死典狱官的手下！"
D.Strings[1350]="我们必须快点。"
D.Strings[1351]="森林中的小精灵不断出现，响应自然的召唤！"
D.Strings[1352]="森林之灵，现在我需要你们的帮助！快点去焦炭谷！"
D.Strings[1353]="%s面无表情，不为所动。"
D.Strings[1354]="你太过分了，$n。"
D.Strings[1355]="别让我对你动武。"
D.Strings[1356]="小心我狠狠地收拾你一顿。"
D.Strings[1357]="%s把肉块扔到沸腾的大锅里。"
D.Strings[1358]="啊，感受渗入洞穴的魔法之力吧，我的小精灵……木哈哈哈！"
D.Strings[1359]="自然的力量是如此强大……哈哈哈。"
D.Strings[1360]="%s下了一颗蛋！"
D.Strings[1361]="%s裂开了……"
D.Strings[1362]="%s裂开了！"
D.Strings[1363]="%s看到她的孩子遭到攻击，变得无比愤怒！"
D.Strings[1364]="%s把信交给了药剂师扎玛。"
D.Strings[1365]="%s孵化了！"
D.Strings[1366]="%s啾啾地叫着寻求帮助……"
D.Strings[1367]="%s到了！"
D.Strings[1368]="%s聆听着$n的请求。"
D.Strings[1369]="你来对了。我将把我的智慧分享给你。"
D.Strings[1370]="去吧，我的仆人。把石爪山的消息带给药剂师扎玛。"
D.Strings[1371]="%s召唤出一个信使……"
D.Strings[1372]="%s开始制造他的毒药……"
D.Strings[1373]="搞定了，$n。毒素已经准备好了。"
D.Strings[1374]="%s把毒素装进了容器。"
D.Strings[1375]="毒素准备好了，$n。"
D.Strings[1376]="石爪山的自然之灵依然十分愤怒，$n。"
D.Strings[1377]="我担心无法使他们平静下来……"
D.Strings[1378]="嗯，我帮你采矿的时候，你要帮我望风。"
D.Strings[1379]="嘿！你不应该在这里的！快来！"
D.Strings[1380]="我猜声音是从这里发出的。我们最好去看看。"
D.Strings[1381]="小心！听起来他们数量众多！"
D.Strings[1382]="再坚持一会，我快要得到它了！"
D.Strings[1383]="这里怎么了？匹兹尼克！我就知道我们不应该把你留在这里！"
D.Strings[1384]="哈哈，我知道了！"
D.Strings[1385]="谁敢打扰阿鲁高的仆人？准备面对你的末日吧！"
D.Strings[1386]="你毁了我的工作成果！准备堕入虚空之中吧！"
D.Strings[1387]="%s将艾露恩之泪放入一碗炖菜中。"
D.Strings[1388]="吃吧，女儿。这会让你感觉好点。"
D.Strings[1389]="给……"
D.Strings[1390]="%s摆脱了疯癫的状态。"
D.Strings[1391]="嗯……"
D.Strings[1392]="%s将药膏敷在蕾拉的前额上。"
D.Strings[1393]="%s如释重负地叹了口气。"
D.Strings[1394]="我们会割开你的喉咙，放干你的血！"
D.Strings[1395]="你逃不掉了！"
D.Strings[1396]="为了暗滩教派！"
D.Strings[1397]="我的……我的力量在减弱……你要为你的傲慢付出代价！"
D.Strings[1398]="不！你们不可能打败我！"
D.Strings[1399]="比赛将在一分钟内开始！"
D.Strings[1400]="%s转身逃开，去寻求支援！"
D.Strings[1401]="%s听到崇拜者的欢呼声，他的速度一下子就爆发了出来！"
D.Strings[1402]="我改变了主意，忠诚的仆人们。你们不必把囚犯带到我面前来供我研究了，我现在就开始。"
D.Strings[1403]="击碎这块灵魂石简直是小事一桩！"
D.Strings[1404]="%s猛然打开！"
D.Strings[1405]="%s吟唱道：“尽你所能地帮助他，这项任务绝不能失败。”"
D.Strings[1406]="%s被碾成了灰。"
D.Strings[1407]="%s贪婪地呼吸着，空气中飘来新鲜的狮子肉香……"
D.Strings[1408]="%s狼吞虎咽地吃着肉！"
D.Strings[1409]="%s消失在茫茫大雪中。"
D.Strings[1410]="新鲜的肉被放在尤基尔之焰上面。"
D.Strings[1411]="%s四处查看……"
D.Strings[1412]="嗯……如果你注意到这些细节问题，$n，那么隐藏在赞吉尔僵尸背后的秘密也许就是元凶！"
D.Strings[1413]="谢谢你，$n。"
D.Strings[1414]="我相信我能找到这种混合剂的用途……"
D.Strings[1415]="在大灾变时，亚米萨兰正在大陆崩裂的边界，几乎没有什么幸存者逃过那次劫难。"
D.Strings[1416]="埃瑟里克斯来到我们面前，他声称能把我们从痛苦中解救出来。他给我们施了魔法，让我们免受伤害。"
D.Strings[1417]="我们该与埃瑟里克斯·纳拉辛有个了断了。自然之灵啊，告诉我，去哪里才能找到其它的灵魂宝石来解除他的魔法？"
D.Strings[1418]="当震动停下来的时候，他的真实目的暴露出来了。我们都被困住了，而他在慢慢地汲取我们的能量。"
D.Strings[1419]="他的副官，伊克鲁德·玛格苏尔有一本书，里面也许记载着其它灵魂宝石的所在地。"
D.Strings[1420]="%s消失在迷雾之中……"
D.Strings[1421]="%s抓了一个零件，把它放进口袋中……"
D.Strings[1422]="那里，应该就是那里……"
D.Strings[1423]="%s把箱子放在地上。"
D.Strings[1424]="%s开始跳舞。"
D.Strings[1425]="哈哈！$n，你真是一个好舞伴！"
D.Strings[1426]="喔，喔！终于出来了。不过接下来还有危险，所以要保持警惕。"
D.Strings[1427]="那上面就是卡尔加·刺肋的住处。那个该死的又干又瘪的老太婆。"
D.Strings[1428]="这个沟里就有蓝叶薯！它们可都是唾手可得的金子啊！"
D.Strings[1429]="这里到处都潜伏着危险。"
D.Strings[1430]="我不明白这些愚蠢的动物是怎么在这种地方生存的……闻起来真臭！"
D.Strings[1431]="我想我看到了一条可以走出这片荆棘林的路。"
D.Strings[1432]="能走出这条臭沟真好，尽管出去了也好不了多少。"
D.Strings[1433]="这酒闻起来真带劲！"
D.Strings[1434]="终于！我终于能走出这个地方了。"
D.Strings[1435]="让我们来尝一小口……"
D.Strings[1436]="等等！我到底在想什么！有正事要干哪。"
D.Strings[1437]="我想在回到棘齿城之前休息一下。谢谢你的帮助！"
D.Strings[1438]="好了，现在我要起身去棘齿城了！祝你好运！"
D.Strings[1439]="%s听$n讲述$g他:她;在荒芜之地的冒险经历。"
D.Strings[1440]="难以想象！看来精铁才是关键！"
D.Strings[1441]="曾经有数百人被他的法术困住。现在只有一小部分还被囚禁着。他有时也会和我们交谈。"
D.Strings[1442]="他担心他的法力会减弱，那块宝贵的灵魂宝石也会消失和死亡。"
D.Strings[1443]="这次我会把你彻底干掉！"
D.Strings[1444]="%s把精铁碎片拿到锻炉前。"
D.Strings[1445]="现在让我们加热这些碎片……"
D.Strings[1446]="到目前为止它们还没有被融化。让我们把温度继续调高……"
D.Strings[1447]="我的天啊！精铁居然可以承受如此高的温度！"
D.Strings[1448]="试验很成功！$n，精铁真是一种神奇的原料。"
D.Strings[1449]="再次感谢你，$n。现在我要用精铁来加固我的战车！"
D.Strings[1450]="哐！哐！哐！我正在加固我的战车！"
D.Strings[1451]="都完成了！"
D.Strings[1452]="在下一次比赛中，这辆车将会比以前更快！"
D.Strings[1453]="开始下注啦！地精的车看上去很酷，它肯定能赢！趁比赛还没有开始赶快下注啦！"
D.Strings[1454]="明智的人绝对会赌侏儒获胜的！快下注啦，比赛马上就要开始了！"
D.Strings[1455]="%s开始施法。"
D.Strings[1456]="奥妮克希亚的血脉！"
D.Strings[1457]="%s灰飞烟灭。"
D.Strings[1458]="我依然是食人魔的首领。哈！"
D.Strings[1459]="弱小的$r要和莫格穆洛克大王决战？干掉你！我是这里的老大！"
D.Strings[1460]="$n驶过来了，第一个进入弯角！"
D.Strings[1461]="侏儒的赛车冲线了！侏儒获胜！"
D.Strings[1462]="%s对$n作了个粗鲁的手势。"
D.Strings[1463]="地精赢了！地精赢了！"
D.Strings[1464]="我怕怕！我要逃走！"
D.Strings[1465]="嗯，这次你拿来的骨头很合适，普兹克。"
D.Strings[1466]="搞定！这次改装将会提高我们的速度，但我不认为她能经得起过多的冲撞。"
D.Strings[1467]="好的，弟兄们。开工了，去把这些零件装好。"
D.Strings[1468]="谢谢你的头盔，$n。你这下能帮我们减少很多医疗帐单的开销了……"
D.Strings[1469]="%s指了指井边的水罐。"
D.Strings[1470]="有什么可以帮忙的吗，$G先生:小姐;？"
D.Strings[1471]="你好，$n，我能为你做些什么吗？"
D.Strings[1472]="劳累了一整天？上好的啤酒可以为您解除疲劳。"
D.Strings[1473]="嗨，你想要什么？"
D.Strings[1474]="你好，$c。你想要什么？"
D.Strings[1475]="看看谁来了……我能为你做点什么吗，$n？"
D.Strings[1476]="你觉得我的资格还不够？"
D.Strings[1477]="短程加速赛的冠军是……地精车队！干得好，兄弟们！"
D.Strings[1478]="地精赢了短程加速赛！祝你们下次好运，侏儒车队。"
D.Strings[1479]="%s吸食着梦境之尘。"
D.Strings[1480]="呵呵呵！万物皆要爆炸！"
D.Strings[1481]="那是什么？"
D.Strings[1482]="该死的……一定是地精干的……让我们去看看损失有多大。"
D.Strings[1483]="看起来没什么我们可以做的了……该死！"
D.Strings[1484]="呃！$n正朝着我们过来了！"
D.Strings[1485]="啊啊啊！$n朝我冲过来了！"
D.Strings[1486]="$n正在向这里冲来！做好战斗准备！"
D.Strings[1487]="救命！快帮我把这$n搞定！"
D.Strings[1488]="%s将梦境之尘猛吸入鼻中……"
D.Strings[1489]="%s有些头晕眼花……"
D.Strings[1490]="啊啾！"
D.Strings[1491]="喔！$n，这梦境之尘真棒啊！"
D.Strings[1492]="什么？你把照明弹留在那里了？！"
D.Strings[1493]="爆炸很强烈！你看到那有多厉害了吗？"
D.Strings[1494]="绝不是我！我发誓！"
D.Strings[1495]="开始吧！找出到底是谁干的，然后让他们求生不得求死不能！"
D.Strings[1496]="这要花费一大笔金币，当然我是不会出这笔钱的。"
D.Strings[1497]="有没有人看到了什么？到底发生了什么事情？"
D.Strings[1498]="猛烈地打着喷嚏！"
D.Strings[1499]="我们会再见的，勇敢的$c。"
D.Strings[1500]="%s在$n面前捻动胡须。"
D.Strings[1501]="%s贴着地面嗅来嗅去……"
D.Strings[1502]="%s找到一块蓝叶薯。"
D.Strings[1503]="你做得很好，$n。继续学习新的知识，牢记你所学到的历史。"
D.Strings[1504]="%s被发现了！"
D.Strings[1505]="好的，我们开始吧。"
D.Strings[1506]="现在让我们去寻找药草吧。"
D.Strings[1507]="不，不在这里……"
D.Strings[1508]="这一带肯定有我们要的草药……"
D.Strings[1509]="哈，那里就有一个！"
D.Strings[1510]="过来，$n！让我们到那里仔细找找看！"
D.Strings[1511]="%s从地上捡起药草。"
D.Strings[1512]="好了，我们离开这里！"
D.Strings[1513]="接下来我可以自己应付了。谢谢，$n！去向我的老板要酬金吧！"
D.Strings[1514]="%s转身消失在沼泽地里。"
D.Strings[1515]="小心！$n发起了攻击！"
D.Strings[1516]="救命！我遭到攻击了！"
D.Strings[1517]="救命！那野兽过来了！"
D.Strings[1518]="我很高兴你在这里！我需要你的帮助！！"
D.Strings[1519]="他给你蜂蜜酒，他给你啤酒……"
D.Strings[1520]="一张充满了笑意的脸……"
D.Strings[1521]="这么多年他为我们每个人都服务过……"
D.Strings[1522]="我们叫他微笑的吉姆……"
D.Strings[1523]="停！回到你们各自的位置上！你们两个表现得都很好。"
D.Strings[1524]="%s神色慌张地从箱子中爬了出来。"
D.Strings[1525]="%s回到$n身边。"
D.Strings[1526]="%s开始挖掘……"
D.Strings[1527]="各就各位……开始作战！"
D.Strings[1528]="现在$n领先！"
D.Strings[1529]="好了，我要获得一次漂亮的胜利。准备好你们的剑和盾牌。"
D.Strings[1530]="%s停了下来。"
D.Strings[1531]="去树荫旅店，然后沿着足迹追踪。看看它们是到哪里去的，然后回来向我报告。"
D.Strings[1532]="明白。我马上就回来。"
D.Strings[1533]="%s消失在薄雾中。"
D.Strings[1534]="伙计们，给他们一点教训！没有人能阻挡我！"
D.Strings[1535]="在米奈希尔好好地休息一下，不久之后你就会精力充沛了。"
D.Strings[1536]="你认为自己能在这里来去自如？"
D.Strings[1537]="你绝不可能活着离开这里！"
D.Strings[1538]="没时间喝啤酒了！比赛马上就要开始了。"
D.Strings[1539]="车被撞了一下！我们得快点把它修好，准备下一场比赛。"
D.Strings[1540]="啊，亨德尔下士。很高兴能与一个为了自尊而背叛了自己的国家的人见面。"
D.Strings[1541]="我要去干什么来着？"
D.Strings[1542]="如果被上尉发现，我就死定了。"
D.Strings[1543]="突然之间，到处都是那帮家伙了。"
D.Strings[1544]="他们一定是得到了某些人的帮助。"
D.Strings[1545]="为什么我们不现在解决呢，亨德尔？普罗德摩尔女士将会很乐意在塔里接见你的。"
D.Strings[1546]="我想知道这个愤怒的兽人想要说些什么……"
D.Strings[1547]="%s把东西放进了锅里。"
D.Strings[1548]="仔细看着锅，$n。他似乎有话要说……"
D.Strings[1549]="听到了吗？$n，他说可能是人类的背叛者帕瓦尔·雷瑟放火烧了那座旅店！"
D.Strings[1550]="我希望奥格隆能找到那个粉皮肤的家伙，并且打断他的腿。我倒想看看他如何在沼泽地里活下去！"
D.Strings[1551]="我注意到岛那边有一些火光。还有一个人。让我们去那边看看，$n。"
D.Strings[1552]="那是帕瓦尔·雷瑟。让我们过去看看他会说什么，如何？"
D.Strings[1553]="%s把卷轴放到桌上，开始阅读……"
D.Strings[1554]="以圣光的名义！这个该死的间谍的确厉害！我很高兴他死了！"
D.Strings[1555]="谢谢你的报告，$n。很明显，我们要加强在塞拉摩附近的巡逻。"
D.Strings[1556]="你……你要干什么？离我远一点……"
D.Strings[1557]="我发誓，我没有偷你的任何东西！我的东西你可以随便拿，但是请快点离开！"
D.Strings[1558]="%s痛苦地呻吟着。"
D.Strings[1559]="援军终于到了……"
D.Strings[1560]="感觉好多了。"
D.Strings[1561]="把这个喝了，它对你有好处。"
D.Strings[1562]="这能帮你减轻痛苦。"
D.Strings[1563]="这些药会有作用的。"
D.Strings[1564]="你会好起来的。"
D.Strings[1565]="拿着，喝掉它。"
D.Strings[1566]="你的手指和脚趾将会完好无缺的，不要担心。"
D.Strings[1567]="让我帮帮你吧。"
D.Strings[1568]="护士。"
D.Strings[1569]="我的人怎么了？"
D.Strings[1570]="先生，他们的情况都很好，他们会痊愈的。"
D.Strings[1571]="谢谢你。希望这种事情不要再发生。"
D.Strings[1572]="自由！"
D.Strings[1573]="干掉典狱官！"
D.Strings[1574]="杀死卫兵，活捉典狱官！"
D.Strings[1575]="我们会在你尸骨上跳舞！"
D.Strings[1576]="你的监狱是我们的了！"
D.Strings[1577]="坚守阵地！"
D.Strings[1578]="不要让任何人通过！"
D.Strings[1579]="以洛萨的名义，你们这些迪菲亚渣子会付出代价的！"
D.Strings[1580]="又攻过来了，坚持住！"
D.Strings[1581]="囚犯越来越多了！"
D.Strings[1582]="不要让他们逃走！"
D.Strings[1583]="和我们讲讲你对树荫旅店的事情有什么了解，放心，我不会打你的。"
D.Strings[1584]="我……好吧，我也许从旅店里拿了一些东西……但是为什么食人魔要关心这个？"
D.Strings[1585]="看看这里，如果你不告诉我有关那次火灾的事情的话——"
D.Strings[1586]="不要过来，食人魔！"
D.Strings[1587]="我对你的这些火并不了解……"
D.Strings[1588]="好了，好了！不要再打了！不要再有人受伤了。"
D.Strings[1589]="好了，伙计们，退后。你们做得够多了。我们以后再见！"
D.Strings[1590]="帕瓦尔·雷瑟！终于找到你了。你现在和食人魔混在一起了？不要害怕，即便是背叛者也会得到宽恕。"
D.Strings[1591]="好了，老板。没问题。"
D.Strings[1592]="好罢，老大。不过你确定吗？浪费了一个挺好的练习机会……"
D.Strings[1593]="为$n欢呼吧，$g他:她;是一个如此出色的$c！"
D.Strings[1594]="注意！蓝色隐士旅店正在举行一次聚会！"
D.Strings[1595]="士兵，别对雷瑟中尉太狠了。"
D.Strings[1596]="愿意效劳，长官。"
D.Strings[1597]="啊……哈兰，我没有想到……"
D.Strings[1598]="现在让我们把剩下的垃圾清理干净！"
D.Strings[1599]="该死！你最好不要死在我手上！"
D.Strings[1600]="今天一定是你幸运的一天。好吧，我会说的。先让我一个人呆一会。瞧，你还不相信我，但它……哦，天哪……"
D.Strings[1601]="雷瑟，你在干什么？"
D.Strings[1602]="入侵者！"
D.Strings[1603]="他们在这里！"
D.Strings[1604]="好像是挂了，你最好回去告诉克罗格这里发生了什么。"
D.Strings[1605]="顺便说一下，谢谢你帮我望风。"
D.Strings[1606]="那是什么？你听到什么了吗？"
D.Strings[1607]="%s被箭射中了胸膛，摇摇晃晃地向后退了几步。"
D.Strings[1608]="干得好，$n！"
D.Strings[1609]="为$n欢呼！"
D.Strings[1610]="耶！"
D.Strings[1611]="$n万岁！"
D.Strings[1612]="现在，我会找一些人去检查这个坠饰，看看其中有什么隐藏的东西……"
D.Strings[1613]="我不知道这里面有什么。Pat Nagle和Michael Backus需要先就这个讨论一下……"
D.Strings[1614]="等他们完成再说吧……再见！"
D.Strings[1615]="够了！我会说的。收起你的武器，你不必用它来跟我争论……"
D.Strings[1616]="好了，好了！不要动粗。我会说的，我会说的！"
D.Strings[1617]="我要回去拿点东西，然后再去旅店里见你。"
D.Strings[1618]="把那个可怜人留在这里，你不应该为此浪费时间。"
D.Strings[1619]="去忙你自己的事情吧，这边的事情不需要你操心。"
D.Strings[1620]="小心！"
D.Strings[1621]="一路顺风，愿吉安娜女士的魔法保护你。"
D.Strings[1622]="法格兰·哈斯迪尔前来报告，长官。我将会找出蹄印前往的地方，然后再回来向你报告。"
D.Strings[1623]="泰索兰！我需要一些人，最好是法格兰·哈斯迪尔，到树荫旅店附近去调查一下$n发现的那些蹄印。"
D.Strings[1624]="卡古隆，过来！"
D.Strings[1625]="好了，好了！我们投降……不过请放下你的武器，我会合作的！"
D.Strings[1626]="你也许可以杀了我，但迪菲亚兄弟会必定夺回暴风城！"
D.Strings[1627]="啊……这太糟糕了。"
D.Strings[1628]="求求你了……普罗德摩尔小姐。我并不是想要……"
D.Strings[1629]="贾拉德，你在战斗中表现得十分英勇。让我们看看卡希尔是否能搞定他们。"
D.Strings[1630]="真对不起，我花了这么多时间才到这里。我希望普罗德摩尔女士现在就能接见我。"
D.Strings[1631]="卡希尔，你干得很好。回来休息一下。娜里莎会帮我们清理这里的。"
D.Strings[1632]="娜里莎战斗得很勇敢。我们下次肯定能打败你们红队！"
D.Strings[1633]="你们在战斗中都表现得很勇敢。这令我十分骄傲，你们都已经成为了真正的战士。"
D.Strings[1634]="我们这次输了，但大家不要气馁。专心攻击，把盾牌举高点，然后慢慢靠近对手。这样我们下次就可以取得胜利！"
D.Strings[1635]="贾拉德，下回把盾牌举高点。兰纳！你上！"
D.Strings[1636]="兰纳，我感觉你比以前更出色了！你下次会打赢的！塔克，过来，让他们见识见识！"
D.Strings[1637]="塔克，怎么回事？你应该知道你比他们要厉害！蓝队，加油！"
D.Strings[1638]="干得漂亮！你们让一个老人感到骄傲。好好干，今晚我请大家喝啤酒来犒劳你们。"
D.Strings[1639]="看看你们的比赛都打成什么样子了？你们这帮废物，我要把你们统统踢出队伍！"
D.Strings[1640]="队长，派出你的第一名队员吧。"
D.Strings[1641]="再见，多保重。"
D.Strings[1642]="红队赢了！祝贺红队！"
D.Strings[1643]="蓝队赢了！祝贺蓝队！"
D.Strings[1644]="贾拉德，你先上！"
D.Strings[1645]="爱德华，开始了。上！"
D.Strings[1646]="蓝队加油！"
D.Strings[1647]="红队加油！"
D.Strings[1648]="嘿，$n！不要忘了去拿一只箱子，还有操作手册和指挥棒！"
D.Strings[1649]="射得不错……但还不够完美。稍微往左偏了点。"
D.Strings[1650]="这次几乎射中目标了。嗯……也许我该再往右边瞄瞄。"
D.Strings[1651]="喔！正中靶心！"
D.Strings[1652]="啊！有一点偏。我甚至没有射中靶子！"
D.Strings[1653]="如你所愿，长官。"
D.Strings[1654]="红队赢了！"
D.Strings[1655]="蓝队赢了！"
D.Strings[1656]="我们马上就要回塔里去了。如果你有话想要和我们说，可以在那里找到我们。"
D.Strings[1657]="那不是我的错，马森大人！"
D.Strings[1658]="这是一个简单的错误。你只是转错弯了！"
D.Strings[1659]="沼泽地很恐怖！我很……很……害怕！"
D.Strings[1660]="我还活着简直是个奇迹！"
D.Strings[1661]="感谢圣光，你终于来了！拔出你的剑，有几个半人马在追杀我！"
D.Strings[1662]="现在没有人能救你了！"
D.Strings[1663]="祈祷吧！"
D.Strings[1664]="我想那是最后一个。你来得真是时候……我不知道我还能躲多久。"
D.Strings[1665]="血清只要再过一会儿就能准备好了，$n。"
D.Strings[1666]="快完成了……"
D.Strings[1667]="哈，血清完成了，$n。过来，靠近点，我们得谈一谈。"
D.Strings[1668]="这不会花很长时间……"
D.Strings[1669]="隐形药水已经准备好了，$n。"
D.Strings[1670]="让我们离开这个地方吧。"
D.Strings[1671]="谢谢你，$n。我将会永远记住你。你可以在斯通纳德北部的营地里找到那个大箱子。"
D.Strings[1672]="%s消失在沼泽地里。"
D.Strings[1673]="%s痛快地喝了一口啤酒。"
D.Strings[1674]="真爽快。现在我有些事情要宣布……"
D.Strings[1675]="我确信被遗忘者正在误导部落联盟……等等……我感到头很晕……"
D.Strings[1676]="%s痛苦地翻来覆去。"
D.Strings[1677]="啊~~~~~~~~~~~！"
D.Strings[1678]="这里什么人都没有……"
D.Strings[1679]="不要杀我！不要杀我！"
D.Strings[1680]="呀呀呀！我要逃走！"
D.Strings[1681]="哈，有机会试试我这把利刃了。"
D.Strings[1682]="兄弟会不能容忍你的行为。"
D.Strings[1683]="感受兄弟会的力量吧！"
D.Strings[1684]="啊啊啊……新鲜的肉！"
D.Strings[1685]="我们走吧，伙计们，路上要格外小心……"
D.Strings[1686]="感受黑石兽人的力量吧！"
D.Strings[1687]="你不配与黑石兽人较量！"
D.Strings[1688]="我们通过了关口！现在是沼泽地……"
D.Strings[1689]="我们终于到守望堡了！"
D.Strings[1690]="开张了！"
D.Strings[1691]="我要关门了，要买东西就赶快啊！"
D.Strings[1692]="我要关门了……"
D.Strings[1693]="他死了。"
D.Strings[1694]="哦，好吧。"
D.Strings[1695]="让我们把协动齿轮组和动力均衡模块装上去，然后就可以启动净化装置了。"
D.Strings[1696]="这样应该就可以了。"
D.Strings[1697]="现在是拯救整个侏儒种族的时候了！"
D.Strings[1698]="哦，太好了。"
D.Strings[1699]="也许多一点点润滑油就可以了。"
D.Strings[1700]="那次真是就差那么一点，我想我们快要成功了。"
D.Strings[1701]="净化装置一切正常。只要再调整一下就可以了！"
D.Strings[1702]="非常精确。"
D.Strings[1703]="在我看来，已经非常完美了。"
D.Strings[1704]="基本确定了。"
D.Strings[1705]="我也在想这个问题。"
D.Strings[1706]="那家伙喜欢在旅店里花天酒地，让我们去拜访他一下，$n。"
D.Strings[1707]="摩卡，顶替我一下！我有些事要处理。"
D.Strings[1708]="又来？快点，库马克，我讨厌这个。"
D.Strings[1709]="女人啊……"
D.Strings[1710]="我在这里！有种你就过来！"
D.Strings[1711]="是库马克……最好不要挡他的路。"
D.Strings[1712]="我渴望战斗！"
D.Strings[1713]="杀死你简直是易如反掌。"
D.Strings[1714]="尝尝霜鬃魔法的滋味。"
D.Strings[1715]="你们这些$R要的只是我的烟草。"
D.Strings[1716]="我要杀了你！"
D.Strings[1717]="我闻到了$R的气味"
D.Strings[1718]="该出击了！"
D.Strings[1719]="你们居然胆敢侵犯霜鬃巨魔的要塞，那就准备受死吧！"
D.Strings[1720]="哦，我们将会相处得很融洽，$n。"
D.Strings[1721]="呀呀！杀啊！"
D.Strings[1722]="我不怕你这样的$c！"
D.Strings[1723]="你今天想要做什么？"
D.Strings[1724]="我不知道。你想要做什么？"
D.Strings[1725]="去钓鱼听起来不错。"
D.Strings[1726]="我要撕碎你！"
D.Strings[1727]="你去死吧！"
D.Strings[1728]="啊！！！我要干掉$r！"
D.Strings[1729]="这个$R看上去很好吃！"
D.Strings[1730]="扁它！"
D.Strings[1731]="我要捏碎你！"
D.Strings[1732]="呃？那是什么？"
D.Strings[1733]="入侵者！不要让他们逃走！"
D.Strings[1734]="杀死入侵者！"
D.Strings[1735]="不要穿过黑铁矮人的地盘，$C。"
D.Strings[1736]="去死吧，$C。"
D.Strings[1737]="感受一下黑铁矮人的力量吧！"
D.Strings[1738]="为了龙喉氏族而战！"
D.Strings[1739]="龙喉氏族万岁！去死吧，没用的$c！"
D.Strings[1740]="食物……"
D.Strings[1741]="一个活着的$R……不久就会变成一个像我这样的亡灵。"
D.Strings[1742]="加入我们吧，$C。"
D.Strings[1743]="库马克！我发誓我会变得有钱的！只要多给我点时间！"
D.Strings[1744]="一杯酒给我的朋友萨洛克，另一杯给我自己。"
D.Strings[1745]="我不想惹麻烦，库马克。"
D.Strings[1746]="萨洛克，我们为什么不谈谈生意？"
D.Strings[1747]="库马克，你想要什么？"
D.Strings[1748]="我必须摧毁这些恶魔的工具！为了部落！"
D.Strings[1749]="来一杯卡利姆多鸡尾酒！嗝儿！"
D.Strings[1750]="真棒！嗝儿！"
D.Strings[1751]="%s咕隆一口全喝了下去。"
D.Strings[1752]="嗯，谁把我推下去了？是你吗，$n？谁去把灯开一下啊？嗝儿！"
D.Strings[1753]="再喝一口酒，我就可以发言了。嗝儿！干杯！"
D.Strings[1754]="那么，$n，我来告诉你在悲伤沼泽发生了什么。嗝儿！"
D.Strings[1755]="战斗！"
D.Strings[1756]="红队赢了！准备好下一轮。"
D.Strings[1757]="蓝队赢了！准备好下一轮。"
D.Strings[1758]="现在你要好好了解一下了，$n！"
D.Strings[1759]="很生气吗，萨洛克？你不应该喝这么多……告诉我们，你对莫萨恩了解多少。"
D.Strings[1760]="好了，你这堆可怜的烂骨头。让我们看看你有什么本事。攻击你的对手，我说停的时候你才能停止。"
D.Strings[1761]="停！你们把这个叫做战斗？真可怜！现在用心去战斗，好吧，你们其实已经没那东西了。"
D.Strings[1762]="你们知道自己看起来有多烂吗？这是我见过的最可笑的战斗！"
D.Strings[1763]="你们不再是只为了自己而战斗，蠢货！你们现在是为希尔瓦娜斯女王而战，所以快点表现出你们的价值来！"
D.Strings[1764]="你们是死了，但不是被埋了。现在让我看看你们的实力吧！"
D.Strings[1765]="木头和稻草会显示出怜悯之心，但巫妖王不会！"
D.Strings[1766]="你们最好现在就能证明自己不是个废物！"
D.Strings[1767]="剑不是工具，它是你的延伸。我希望你们能做得更好！"
D.Strings[1768]="你那也叫作战？如果那也叫战斗，那我就是战神了！"
D.Strings[1769]="好了，士兵们，休息一下！"
D.Strings[1770]="比索，我的朋友，好久不见啊。"
D.Strings[1771]="如果时间允许的话，我们得好好谈一下。因为我们有很多事情要讨论。"
D.Strings[1772]="谢谢你，$n。没有你的帮助，我永远无法成为被遗忘者的一员。"
D.Strings[1773]="保重，我的朋友。"
D.Strings[1774]="利斯塔，把战俘带过来。"
D.Strings[1775]="爱德华，泰勒尔出来。准备接受你们的第一轮挑战。"
D.Strings[1776]="看来你们应付第一轮还是非常轻松的嘛。让我们看看你是怎样对付第二轮测试的。利斯塔，把巫妖王的爪牙带上来。"
D.Strings[1777]="现在是证明你们的价值的时候了！"
D.Strings[1778]="你们证明了自己的能力。看来利斯塔为我们带来了一些惊喜。"
D.Strings[1779]="年轻的战士，面对你们最后一轮挑战吧！"
D.Strings[1780]="干得很好。现在站到旁边去，让其他的兄弟来试试。"
D.Strings[1781]="谁胆敢召唤了虚空的力量？"
D.Strings[1782]="你将会因此永远生活在痛苦之中，可怜的术士。"
D.Strings[1783]="这是达林·弗治维特。当疾病开始流行的时候，他带着自己的爱人从洛丹伦逃了出来。"
D.Strings[1784]="这位是科马·韦拉德。结婚不到两个星期，他的妻子就为了米奈希尔港的安全而献出了生命。"
D.Strings[1785]="蠢货。"
D.Strings[1786]="真有趣……现在比我所期望的还要好……"
D.Strings[1787]="当他在格雷迈恩之墙碰到那些难民的时候，他想要帮助他们，于是就把他的女人送到了希尔斯布莱德。"
D.Strings[1788]="十年过去了，虽然她不是个美丽的女人，而且有很多女人可以取代她的位置，但是他还是在苦苦地找寻她。"
D.Strings[1789]="你觉得我的新玩具怎么样？"
D.Strings[1790]="瑟里莎，把这个交给兰克斯特神父。"
D.Strings[1791]="我的主人阿博纳斯大人让我把这个交给你。"
D.Strings[1792]="大人，这是兰克斯特神父给您的。"
D.Strings[1793]="你喜欢我的宠物吗？"
D.Strings[1794]="她难道不是最让人惊奇的小东西吗？"
D.Strings[1795]="我不是告诉你新的控制技术会成功的吗？"
D.Strings[1796]="和我告诉你的一样棒，是吗？"
D.Strings[1797]="摧毁她的精神对我来说很容易。"
D.Strings[1798]="你不是想要让我把所有的秘密都告诉你吧？"
D.Strings[1799]="一个小小的仪式就够你受的了。"
D.Strings[1800]="一点点小魔法，她当然非常关心这些……"
D.Strings[1801]="每个人都有弱点，关键是如何要找到它。"
D.Strings[1802]="经过努力，我发现大脑中有这样一个特定的部位，如果你将其切除或者施加特定的刺激，就可以使得该生物变得更加温顺。"
D.Strings[1803]="谢谢你，我的宝贝。"
D.Strings[1804]="真是让人惊讶，杰勒德。你是怎么办到的？"
D.Strings[1805]="真让人感到惊讶！你是怎么实现恒定控制的呢？"
D.Strings[1806]="杰勒德，我不赞成你的试验，但是我承认结果是令人印象深刻的。你到底对她作了什么？"
D.Strings[1807]="真令人惊讶。你在控制她，但她还能保持自己的意识。你是怎么做到的？"
D.Strings[1808]="她保留了她的知识和语言能力，同时还能为你出色地完成任务。你到底做了些什么？"
D.Strings[1809]="我从来没见过这样的情况。一个生物居然能够在没有失去自己意识的情况下被控制。你对她作了什么？"
D.Strings[1810]="妙极了，杰勒德，你们超越了自己，再来一次。"
D.Strings[1811]="杰勒德，你给我留下了深刻的印象。我原本以为你只会夸夸其谈，但事实证明我错了。"
D.Strings[1812]="太不可思议了。这里面到底有什么诀窍？"
D.Strings[1813]="很好，杰勒德。接下来，你要负责培养出更多这样的生物。"
D.Strings[1814]="这绝对是一个令人惊讶的发现。我很想看看你失败了的那些试验品。"
D.Strings[1815]="我不同意你用炼金术去解决这些问题，但我对结果感到满意。你干得很好。"
D.Strings[1816]="你的宠物很不错，杰勒德，但我想她需要一个带着铃铛的项圈。"
D.Strings[1817]="杰勒德，你有训练她的场地吗？"
D.Strings[1818]="啊！那个无赖派他的人来找我吗？在我动手杀了你之前滚出我的视线，还有，拿上这个。"
D.Strings[1819]="啊，在这里。"
D.Strings[1820]="《不可思议的魔法流动及它是如何影响这个世界的》，玛吉诺·仲马著。我在一直寻找这本书。"
D.Strings[1821]="看来我真的需要一个更好的图书分类系统了。啊，就是这本！"
D.Strings[1822]="《卡德加的魔法日记，第八卷》，我要的是这一本。"
D.Strings[1823]="哈，《达拉然大法师的神秘咒术》，太棒了。"
D.Strings[1824]="不知道我能不能找到《魔法和能量的守则》这本书。啊哈，在这里，它怎么会在这里？"
D.Strings[1825]="《魔法致病学》，不对不对。《魔法矩阵》，也不对。啊，就是这个，《魔法神秘学》。"
D.Strings[1826]="这就是我要寻找的魔法书。"
D.Strings[1827]="没错。嗯，这本书参考了另外一本书的内容。看来我还要去找那一本书。"
D.Strings[1828]="这一本不是很有用。让我看一下另外一本。"
D.Strings[1829]="那就是我想要知道的东西。现在我要知道书中的哪个章节讨论的是魔法流量的变化问题。"
D.Strings[1830]="非常有趣。但如果确实是这样的话，那我的理论就是错误的。我要重新去读另一部分，看看我究竟错过了什么。"
D.Strings[1831]="看来我对于能量的理解是正确的。让我们去看看另一本书讲了些什么。"
D.Strings[1832]="如果这个理论是正确的，那我就得做很多研究了。"
D.Strings[1833]="但这个肯定不对。我把那本大书放哪里去了？"
D.Strings[1834]="哈！让我们看看这个木头人！"
D.Strings[1835]="哈哈！真有趣！真有趣！"
D.Strings[1836]="站住，$n！我在看守这些桶，所以……不要碰它们！"
D.Strings[1837]="如果你在这里，那就表明你已经准备好去研究召唤恶魔的方法了。我们将从最低级的生物召唤开始，然后再慢慢进阶。让我们开始吧。"
D.Strings[1838]="最容易召唤的是小鬼。你的能力也许已经远远超过召唤小鬼的水平，但是我们为了保证召唤教学的完整性，所以还是从召唤它开始吧。"
D.Strings[1839]="这些邪恶的小家伙就是小鬼。它很小而且很瘦弱，显然是不能做为肉盾使用的，而它的威力也不大。这种召唤生物最好是在多人组队的时候作为支援力量使用。"
D.Strings[1840]="现在你已经了解了小鬼的特性，那么让我们继续研究下一种你可以召唤的生物：虚空行者。"
D.Strings[1841]="这种恶魔被称为虚空行者。它的力量和耐力都非常惊人，可以出色地胜任防御任务。首先控制它来攻击你的敌人，这样就能保证你在有肉盾保护的情况下安全地使用法术和技能。"
D.Strings[1842]="如果你还没有看见过虚空行者，那你一定要去看看。这种生物看上去就极具气势，而且在战场上也能发挥很强的作用。接下来，让我们看看所有男性学员都在热切期盼的召唤生物：魅魔。"
D.Strings[1843]="好了。除了和前面那两种召唤生物的外形有着明显的差异之外，魅魔的攻击能力也非常可观。然而，她的防御力很差，所有很难作为肉盾来使用。"
D.Strings[1844]="努力学习，总有一天你们也可以召唤魅魔的，但现在我们要继续课程了，下一讲是地狱猎犬。"
D.Strings[1845]="现在你们看到的就是地狱猎犬。这种生物拥有法力燃烧等多种技能，这些技能在对付施法型的敌人时是十分有用的。"
D.Strings[1846]="当遇见施法者的时候，这种恶魔是你最好的朋友。现在，让我们进行一下讲的课程。这种召唤生物主要被用来帮助你更快地旅行。它就是地狱战马，有时也被称为梦魇。"
D.Strings[1847]="我怀疑你已经看过很多次这个生物了。这些恶魔马能让你的旅行速度加快，只要你召唤出它们来，就可以把它们当作自己的坐骑。但是地狱战马是非常难以驯服的，所以在尝试之前，你最好确定自己准备充足。"
D.Strings[1848]="所有的召唤生物都介绍完毕了。召唤课程已经结束。新的课程将会很快开始，如果你要想要得到进一步的提高，那就请不要走远，先在周围转转。"
D.Strings[1849]="嗯，看来基佛需要一个新的项目。如果那个笨蛋阿博纳斯继续从基佛手里抢项目，基佛肯定会对他有意见的。"
D.Strings[1850]="嗯，搞定了。现在让基佛试试看。"
D.Strings[1851]="不是基佛想要的结果。基佛可能加了太多的地根草。我们来看一下第二份药水是不是基佛所需要的。"
D.Strings[1852]="%s戳了戳那只小蛤蟆。"
D.Strings[1853]="%s给蛤蟆喂了一些奇怪的液体。"
D.Strings[1854]="%s失望地戳了戳那只小松鼠。"
D.Strings[1855]="好吧，失败了。这种生物太小了。让我们看看基佛的第三批药剂效果如何。"
D.Strings[1856]="%s给松鼠喂了一些粘粘的液体。"
D.Strings[1857]="%s戳了戳那只野兔。"
D.Strings[1858]="基佛对这个结果不太满意。也许如果基佛尝试一下大剂量的话，效果会好一些。"
D.Strings[1859]="%s抓住野兔，把那瓶液体全数灌入野兔腹中，然后把它塞回笼子。"
D.Strings[1860]="这是什么？基佛要的是一只绵羊？基佛想要一件强力的武器，但他现在得到的就是这只绵羊。基佛非常失望。"
D.Strings[1861]="%s反复地戳那只绵羊。"
D.Strings[1862]="基佛很高兴。"
D.Strings[1863]="%s强行把液体灌进了那个疲惫不堪的人的口中。"
D.Strings[1864]="%s轻声告诉$n开启保险箱的秘诀。"
D.Strings[1865]="$n！此地区严禁入内！"
D.Strings[1866]="现在让我们来试一试……"
D.Strings[1867]="啊！太恐怖了！"
D.Strings[1868]="%s跟着$n。"
D.Strings[1869]="%s大喊救命！"
D.Strings[1870]="%s开始自我复制！"
D.Strings[1871]="不要惹怒矮人！"
D.Strings[1872]="为了铁炉堡的荣耀！"
D.Strings[1873]="我简直不敢相信！面对我的愤怒吧！"
D.Strings[1874]="你的真名叫阿兹雷索克。让我看看你的真正面貌！"
D.Strings[1875]="你不值得我浪费时间。干掉他们！"
D.Strings[1876]="可怜的懦弱者。你想见我的主人？那就放马过来吧。"
D.Strings[1877]="谁敢挑战我？"
D.Strings[1878]="渣滓！"
D.Strings[1879]="来吧！你是在自寻死路！"
D.Strings[1880]="过来吧，我和主人都在等你。"
D.Strings[1881]="事情发生了有趣的转变。"
D.Strings[1882]="终于可以唤醒纳拉雷克斯了！过来帮帮我，勇敢的冒险者！"
D.Strings[1883]="有入侵者。提高警惕！"
D.Strings[1884]="我们必须去和其他的信徒会合。在我重建贫瘠之地前，有许多工作要做。再见，勇敢的灵魂！"
D.Strings[1885]="回手一拳结结实实地打在$n的脸上。"
D.Strings[1886]="蹲下来，蠢货！"
D.Strings[1887]="%s发出怒吼，警告周围的敌人！"
D.Strings[1888]="嘿，这里有一个！"
D.Strings[1889]="哦，这个正合适！让我们把它挖出来……"
D.Strings[1890]="我从来没见过像这样的东西！看看额骨的延伸处……"
D.Strings[1891]="他们出发了！"
D.Strings[1892]="%s变得狂怒了！"
D.Strings[1893]="必须多加小心，不要弄坏标本……"
D.Strings[1894]="在那里！就是那个吗？"
D.Strings[1895]="这如果不是科多兽骨化石，那我就去配一副眼镜！"
D.Strings[1896]="哦，有戏了……"
D.Strings[1897]="我从来没见过这么大个的！我要赶快把它送回去进行研究……"
D.Strings[1898]="让我来把它标记起来，以后再挖。"
D.Strings[1899]="必须非常小心……这东西很精密。"
D.Strings[1900]="我从来没想过居然能找到如此符合我要求的东西。"
D.Strings[1901]="虽然有点破损，但我还是能从其中获得一些有用的信息。"
D.Strings[1902]="你们真是帮了我的大忙！这些骨头包含了很多新的信息，这对我将来的研究有很大的帮助！"
D.Strings[1903]="我会跟着你回到营地，然后你就可以去向我的助手霍恩尼兹要报酬啦。"
D.Strings[1904]="我亲爱的托尔塔！我终于回来了。"
D.Strings[1905]="你知不知道我在这里等了很久？晚饭在哪里？那么晚了还没有晚饭的影子？"
D.Strings[1906]="亲爱的托尔塔，在别离那么长时间之后我们终于再次相见了。我们之间的爱还会更加热烈。"
D.Strings[1907]="少废话，我肚子饿了！现在去海里给我找点吃的来！"
D.Strings[1908]="好吧，托尔塔。你要什么我就给你找什么……"
D.Strings[1909]="我是永不熄灭的。我永生不老，我在寒冷中给你带来温暖。"
D.Strings[1910]="月神与我们同在！让我们赶快逃出这座魔堡。"
D.Strings[1911]="我会尽快返回瓦拉里尔那里去。干掉那些你能对付得了的敌人，我自己过去应该没什么问题。"
D.Strings[1912]="这次不要再迷路了……"
D.Strings[1913]="霍恩尼兹，我得到了一些样本。我要开始研究它们了，你能去研究剩余的那些吗？"
D.Strings[1914]="啊！我的工具用完了。我们不得不重新开始……"
D.Strings[1915]="愿你永远精神抖擞，$n。"
D.Strings[1916]="你的灵魂很纯洁，$n。"
D.Strings[1917]="力量和忍耐，耐心和智慧——永远记住这些，$n。"
D.Strings[1918]="愿安宁和耐心永远与你同在，$n。"
D.Strings[1919]="好吧，够了！我放弃！"
D.Strings[1920]="祝你下次好运，$n。"
D.Strings[1921]="你赢了，$n。你赢了！"
D.Strings[1922]="我们还要走更远吗？"
D.Strings[1923]="我很渴。"
D.Strings[1924]="沙子灌进鞋里了……"
D.Strings[1925]="要走多远？"
D.Strings[1926]="你能背我走一段吗？"
D.Strings[1927]="你听说过食人魔、地精和深渊领主的故事吗？"
D.Strings[1928]="托尔塔肯定很担心。"
D.Strings[1929]="这是个很好的战利品，$c。"
D.Strings[1930]="我的爪子将把你撕得粉碎，$R。"
D.Strings[1931]="你死定了，$C。"
D.Strings[1932]="阿库麦尔需要更多的祭品。"
D.Strings[1933]="只有无辜者的鲜血才能平息阿库麦尔的愤怒。"
D.Strings[1934]="不久我们就可以迎回上古之神了。"
D.Strings[1935]="阿库麦尔肯定会为我们召唤上古之神的，只要我们能够提供足够多的祭品！"
D.Strings[1936]="你穿得真不错。"
D.Strings[1937]="祝你好运，$n！"
D.Strings[1938]="谢谢你，$G小伙子:姑娘;。非常感谢。"
D.Strings[1939]="哈姆霍克有麻烦了！哈姆霍克需要帮助！"
D.Strings[1940]="愿圣光与你同在，$n。"
D.Strings[1941]="祝福你，$n。谢谢你。"
D.Strings[1942]="$n，准备战斗！"
D.Strings[1943]="再见，$n。记住，一名真正的战士是永远不会逃跑的！"
D.Strings[1944]="%s开始工作……"
D.Strings[1945]="$n！我搞定了！"
D.Strings[1946]="谢谢你，$n。祝你好运！"
D.Strings[1947]="%s开始打造……"
D.Strings[1948]="你的武器做好了，$n。"
D.Strings[1949]="$n成功了！为$n欢呼三声！"
D.Strings[1950]="一，二——三！"
D.Strings[1951]="一千年以前，不朽的暗夜精灵、森林中的半神和巨龙曾并肩在海加尔山上对抗燃烧军团。"
D.Strings[1952]="在战斗最激烈的时候，安娜瑟拉和拉瑟里安背靠背地战斗着。两个恋人决心在这场战争中一起活下来。"
D.Strings[1953]="但事实却是残酷的。在与敌人作战时，安娜瑟拉的护甲被恶魔的利刃穿透了。在如此激烈的战争中，没有什么能拯救她。"
D.Strings[1954]="安娜瑟拉！"
D.Strings[1955]="拉瑟里安不顾正在进行的激烈战斗，放下了自己的武器，紧紧地抱着他死去的爱人。但是恶魔没有停止攻击，很快就将他无情地杀死了。"
D.Strings[1956]="安娜瑟拉……没有你，我怎么能独自忍受永生的煎熬……如果你就此离去，那么就让我也魂归大地吧……"
D.Strings[1957]="就这样结束了……我的爱人……"
D.Strings[1958]="在他们倒下去的地方长出了一棵树，暗夜精灵将其称为同心树。它就是你要寻找的东西。"
D.Strings[1959]="你！快加入战斗！"
D.Strings[1960]="第一阶段结束了。比格维尔……该你上了！"
D.Strings[1961]="战斗结束了！"
D.Strings[1962]="%s眼见监工死去，便害怕地逃走了！"
D.Strings[1963]="结束了！结果真是令人惊讶。我必须把它们转达给我的同伙格瑞曼德、玛希尔和科劳莫特！"
D.Strings[1964]="你的护甲已经准备好了，$n。"
D.Strings[1965]="万岁！$n！完成了！"
D.Strings[1966]="太令人惊讶了！成功了！$n，你的护甲做好了。"
D.Strings[1967]="完成了。$n，你的护甲准备好了。"
D.Strings[1968]="祝你好运，$n。记住，完成任务之后就去找穆里顿。"
D.Strings[1969]="祝你好运，$n。不要忘记……找到手稿之后就去找贾森。"
D.Strings[1970]="为$n欢呼！新的冠军诞生了！"
D.Strings[1971]="挑战者输了！"
D.Strings[1972]="%s士气受挫，转身逃走了！"
D.Strings[1973]="啊，我的爱人！不！让我临死之前再见你一面吧……"
D.Strings[1974]="我们成功了！我们赢了！"
D.Strings[1975]="别想毁了我的地盘，你这个人渣！"
D.Strings[1976]="到房子那边去！无论如何都要紧跟着我！那里有枪和弹药！"
D.Strings[1977]="这个地方对迪菲亚兄弟会来说很安全！叫其他兄弟过来。"
D.Strings[1978]="首先西部荒野，然后是整个暴风城！"
D.Strings[1979]="一个小小的农妇是无法对抗迪菲亚的！"
D.Strings[1980]="我们成功了！我们成功了！我们把他们赶走了！"
D.Strings[1981]="杀了她！占领农场！"
D.Strings[1982]="%s的身体僵直地倒在了地上。"
D.Strings[1983]="不要走得太远。我相信他们大部分人都在那里。"
D.Strings[1984]="有人挂啦！"
D.Strings[1985]="我希望你已经做好了准备，$n。跟着我。"
D.Strings[1986]="圣光与我们同在！"
D.Strings[1987]="上回他们只发动了一轮攻击，如果这次他们进行多次攻击，我并不会感到惊讶。"
D.Strings[1988]="过来，我的侍僧。拿好法杖，准备创建召唤法阵。"
D.Strings[1989]="地狱猎犬来了！做好准备！"
D.Strings[1990]="%s开始吟唱召唤法术……"
D.Strings[1991]="集中精神，$n。我马上要开始召唤仪式了……"
D.Strings[1992]="请不要忘记暴风城的孤儿！"
D.Strings[1993]="帮帮暴风城的孩子们吧……他们是战争的受害者！"
D.Strings[1994]="请多捐助点东西给慈善机构吧，我们必须帮助那些无依无靠的人！"
D.Strings[1995]="献出您的爱心和金钱吧！帮助失去双亲的暴风城孤儿们！"
D.Strings[1996]="阿库麦尔需要更多的祭品！"
D.Strings[1997]="入侵者！你死定了！"
D.Strings[1998]="上古之神将会重生，你别想阻止这一切！"
D.Strings[1999]="你的血将加速上古之神的回归！"
D.Strings[2000]="在你们的保护下，我觉得很安全！"
D.Strings[2001]="我要把你打得稀巴烂！"
D.Strings[2002]="你的眼睛用来当饰品应该不错！"
D.Strings[2003]="战士，做好准备。"
D.Strings[2004]="我们不能放弃任何一个侏儒！"
D.Strings[2005]="穴居人……好像永远也杀不光。该死的穴居人！去死吧！"
D.Strings[2006]="疾病让我的视觉受损，但我知道你一定是穴居人。去死吧，该死的入侵者！"
D.Strings[2007]="又是穴居人，去死吧！"
D.Strings[2008]="耐心点，轮到你的时候我们会叫你的。我们会依照屏幕显示的顺序帮助你们的。"
D.Strings[2009]="记住，如果你骚扰机器人或者在频道里传播垃圾信息，那你的人物将被踢出服务器，被暂时封锁或者遭受更严厉的处罚。"
D.Strings[2010]="我是机器人。我有很多资料。如果您想要知道我都知道些什么，那就和我谈谈。"
D.Strings[2011]="不客气，祝您今天过得愉快。"
D.Strings[2012]="没有奶牛关啦……真的！我再说一遍：没有奶牛关。好吧，也许有……"
D.Strings[2013]="尖端机器人都很敏感，刚才您说的那些话有些刺耳:( 请对我好点。\n我只是想要帮忙。"
D.Strings[2014]="人们都认为我喜欢玉米热狗，但实际上玉米热狗让我消化不良！！！"
D.Strings[2015]="当机器人和您说话时，他的每句话都会以您的名字开始。如果您没看到自己的名字，那么说明他还没有和您说话。"
D.Strings[2016]="我能向您提供帮助的主题包括：| 驱动 | 命令 | 延迟 | 机器人……嗞嗞嗞！"
D.Strings[2017]="请耐心一点，轮到您的时候我们会通知您的。谢谢您的支持，$n！"
D.Strings[2018]="我也爱你 ^-^"
D.Strings[2019]="如果您被禁言或者有关于禁言/开启禁言的疑问，请访问……嗞嗞嗞！"
D.Strings[2020]="%s大声呼叫，寻求帮助！"
D.Strings[2021]="能当自己的老板实在是件好事！$B$B嘿，你能给我几个铜板，让我买个三明治吗？我快饿死了。"
D.Strings[2022]="看看，风险投资公司的新伐木机比我的要好多啦，从可拆换的机械臂到控制把手，都是那么棒！我的老板给我下了死命令，但我们却拿不出任何东西。$b$b现在我们自己的设计研制工作已经完全停止了，所以我决定向他们“借”一个。我派维兹克兰克去淤泥沼泽偷一个回来，但他到现在还没音讯！"
D.Strings[2023]="我曾经负责管理热砂港的伐木机开发工作。但上个月，我自己出来单干了。现在我的全部供应商都把我列入了黑名单。更糟糕的是，我的开发工作至今都没有实际成效。所以我非常需要你的帮助，$n！"
D.Strings[2024]="我想，我应该强化一下我的研究效率。嗯，我要从风险投资公司那里“借用”一些技术。看看，风险投资公司的新伐木机真是出类拔萃，从可拆换的机械臂到控制把手，都是那么棒！$b$b为此，我派我的合伙人维兹克兰克去西边的淤泥沼泽进行一些“实地调查”，但他到现在还没音讯！"
D.Strings[2025]="年轻的$c，靠近一点。我年轻的时候耳朵可好使了，但现在你必须大声说话我才能听到。"
D.Strings[2026]="跟我讲讲故事，斯考恩。"
D.Strings[2027]="你杀了鬼嚎。你这个傻瓜！"
D.Strings[2028]="我在这片平原上生活了很多很多年，我捕猎过许多凶猛的野兽，从来没有失败过……直到我遇见了鬼嚎。$B$B很久以前，这只巨狼曾经是牛头人的盟友，还和燃烧军团英勇作战。不过后来它被一个恶魔所伤，身上的伤口一直没有治愈。最后……这道伤口把它逼疯了。$B$B现在它总是痛苦地在平原上游荡，寻找终止它的痛苦的方法。我很惭愧，因为我无力把他杀掉……"
D.Strings[2029]="%s高声尖叫，寻求帮助！"
D.Strings[2030]="不！迪菲亚兄弟会一定要夺取这个农场！"
D.Strings[2031]="让我们开始工作吧，$n！"
D.Strings[2032]="你好啊，法师。我能在魔法知识的学习上为你提供什么帮助吗？"
D.Strings[2033]="给你，$n。"
D.Strings[2034]="你好。我是一个女法师训练师，你是一个法师。"
D.Strings[2035]="我感谢圣光赐予我的祝福。愿它维护正义，保护所有善良的灵魂。"
D.Strings[2036]="我对法师的相关训练感兴趣。"
D.Strings[2037]="你好。我是一个侏儒法师训练师，而你是一个法师。"
D.Strings[2038]="你好，$c。你想要一些建议？好吧，找个法师当朋友就对了！我们的袖口里藏着一些小把戏……"
D.Strings[2039]="你好。我是一个亡灵法师训练师，而你是一个法师。"
D.Strings[2040]="你好，$C。你是来学习神秘的手艺的吗？"
D.Strings[2041]="你好，$c。我怜悯你，因为魔法的真正秘密是你永远也无法企及的……"
D.Strings[2042]="你好。我是一个术士训练师，而你是一个术士。"
D.Strings[2043]="你好。我是一个术士训练师，而你不是术士！"
D.Strings[2044]="我对术士的相关训练感兴趣。"
D.Strings[2045]="现在还不是让你长眠的时候。我会帮你起死回生……但你也要为此付出一些代价。"
D.Strings[2046]="经希尔瓦娜斯女王批准，亡灵哨兵的数量增加了。在敌人料想不到的时候派出更多的人手实施打击。"
D.Strings[2047]="让我复活吧。"
D.Strings[2048]="我要接受训练。"
D.Strings[2049]="这里还有！"
D.Strings[2050]="%s把一堆木材砰的一声扔了出去。"
D.Strings[2051]="好，就把它放到那里，我会去取它的。"
D.Strings[2052]="%s把圆木切割成了光滑的厚木板。"
D.Strings[2053]="%s被锁进了保险箱！"
D.Strings[2054]="银行选项"
D.Strings[2055]="商人选项"
D.Strings[2056]="出租服务"
D.Strings[2057]="%s逃入了扭曲虚空！"
D.Strings[2058]="%s被魔法拉住了！"
D.Strings[2059]="阿斯托？你来一趟真不容易啊，那我们就不要浪费时间了，好吧？"
D.Strings[2060]="我刚才把哪个放进去了……"
D.Strings[2061]="哈，就是它了。"
D.Strings[2062]="你终究是要说的，还不如现在就说了。"
D.Strings[2063]="坦白交待了，我们就放你走。"
D.Strings[2064]="什么？哦，好吧，我不在乎你说什么。我只是喜欢这样。"
D.Strings[2065]="我是亡灵卖布商人，这是我的见面打招呼的话。"
D.Strings[2066]="欢迎你，请随意看看。除了味道有些诡异之外，我卖的东西都是最棒的。"
D.Strings[2067]="我对裁缝技能的训练感兴趣。"
D.Strings[2068]="我是巨魔裁缝，这是我默认的见面打招呼的话。"
D.Strings[2069]="你要做什么，$c？我要迟到了，而我的雇主不喜欢拖沓。"
D.Strings[2070]="你是阿斯托·哈德恩，对吗？"
D.Strings[2071]="是的，我是阿斯托·哈德恩。你是？"
D.Strings[2072]="你有我所要的东西，阿斯托。我现在要拿走它。"
D.Strings[2073]="准备好，$n。我要打开裂隙了……"
D.Strings[2074]="啊！那是什么？它不应该像这样运作的！"
D.Strings[2075]="碎手氏族将会见证部落重铸荣耀。"
D.Strings[2076]="我想要接受训练。"
D.Strings[2077]="米奈特说我应该向你要一套盗贼工具。"
D.Strings[2078]="等一下，我去给你拿一套工具，$n。"
D.Strings[2079]="哈，这里有一个。"
D.Strings[2080]="祝你好运，$n。"
D.Strings[2081]="你受到了天灾军团的污染。准备进入扭曲虚空吧。"
D.Strings[2082]="你无处可逃。十字军将消灭所有携带天灾病毒的人。"
D.Strings[2083]="圣光将会惩罚所有心怀不轨的人。你死定了！"
D.Strings[2084]="血色十字军将会消灭一切邪恶的力量，把它们彻底赶出这片领地！"
D.Strings[2085]="别轻举妄动，$n，这颗宝珠中的恶魔是个相当可怕的野兽。"
D.Strings[2086]="我还需要一套工具。"
D.Strings[2087]="哈！被诅咒的阿加曼德家族变成了亡灵！"
D.Strings[2088]="谢谢你，$n。你平息了我心中的怒火。"
D.Strings[2089]="如果被诺恩知道了，我会被活活扒皮的！"
D.Strings[2090]="你的头盔已经制作完成了，$n。"
D.Strings[2091]="看啊，竟然有个年轻的$c来看像我这样的老农夫？"
D.Strings[2092]="如果是瑟祖克派你来的，那么告诉他死了这条心吧。我是不会回去为他工作的，不管他怎么求我。"
D.Strings[2093]="我还需要一套盗贼工具。"
D.Strings[2094]="%s开始铸造……"
D.Strings[2095]="我已经完成了你的护腿，$n。"
D.Strings[2096]="搞定了。你的护甲已经准备好了，$n。"
D.Strings[2097]="这些材料真不错，$n。让我们开始为你制作长袍吧。"
D.Strings[2098]="就是它了！全做好了，$n。"
D.Strings[2099]="好的，让我们开始工作吧！"
D.Strings[2100]="啊哈！搞定了。"
D.Strings[2101]="我把银线放在哪里了……"
D.Strings[2102]="哈洛克，给$n一个工具盒。"
D.Strings[2103]="快点，哈洛克。"
D.Strings[2104]="就这样吧。我要回去工作了，否则哈洛克又要埋怨我偷懒了。"
D.Strings[2105]="只剩一个环节要检查了……"
D.Strings[2106]="就是它了！成功了！"
D.Strings[2107]="谢谢你的耐心，$n。"
D.Strings[2108]="我会一直把它留在这里，直到我们需要它……"
D.Strings[2109]="纳拉雷克斯又陷入了沉睡！$b$b很久以前，纳拉雷克斯曾满怀着进入翡翠梦境、让贫瘠之地重新变成茂密森林的伟大理想而来到了这处洞穴中。但他的执着却逐渐消退了，而他的思想也被脑海蜿蜒的影象所侵染。$b$b现在，那些奇怪的爬虫正从他的梦境中爬到这片土地上来，我们必须把他从梦魇中唤醒过来，否则他就将永远失落于其中，并继续给这片大地带来邪恶的力量！$b$b不过，只有杀死他那些堕落的仆人——毒牙之王，我才能开始进行唤醒仪式。"
D.Strings[2110]="毒牙之王死了！我们还有希望！$b$b然而，整个唤醒仪式是非常复杂的，我无法独自完成它。$b$b我现在就开始着手完成所有必要的准备工作，但与此同时，我需要你保护好我。从纳拉雷克斯的噩梦中召唤出的怪物确实非常难缠。如果没有你的帮助，这个任务对我来说会非常可怕。$b$b当你准备好要保护我的时候，就过来跟我说一声，我会带你到纳拉雷克斯的房间去。"
D.Strings[2111]="活动开始了！"
D.Strings[2112]="好的，让我们来制作这颗宝珠吧……"
D.Strings[2113]="好了。搞定了！"
D.Strings[2114]="我现在就开始制作长袍……"
D.Strings[2115]="你的长袍做好了，$n。"
D.Strings[2116]="过来，$n。拿一根显形卷轴以及一盒封灵箱。你需要使用这些东西才能完成任务。"
D.Strings[2117]="%s把精制的厚木板放了下来。"
D.Strings[2118]="机器转过来面对着你。$B$B它的背后有一个奇怪的凹槽，上面刻着一行字：“基尔卡克·旋杆的财产”"
D.Strings[2119]="转动钥匙，启动了机器。"
D.Strings[2120]="啊呀！你都干了些什么？他疯了！快关上舱门！把操纵杆往上拉！啊啊啊啊啊！赶快！"
D.Strings[2121]="我是勇敢的强森，这是我默认见面打招呼的话。"
D.Strings[2122]="嘿！你在为提尔斯干活吗？如果我是你的话，我会离他远远的！酒精把他的大脑麻痹了，但是他的魔法还是和以前一样厉害！"
D.Strings[2123]="告诉我提尔斯保险箱的密码。"
D.Strings[2124]="往后站一点……摒住呼吸。我很久没这么做过了。"
D.Strings[2125]="成功了！真让人惊讶……"
D.Strings[2126]="当然了，我会告诉你密码的。只要你不让提尔斯抓到我就行了！"
D.Strings[2127]="不要告诉提尔斯我还在这里。如果他发现我还没离开闪光平原，我就要永远帮他洗衣服了！"
D.Strings[2128]="基尔卡克的钥匙滑到了缝隙中。"
D.Strings[2129]="当我因为绑着这个大铁球而不能保护自己的时候，你会嘲笑我吗？"
D.Strings[2130]="我怎样才能释放你？"
D.Strings[2131]="有个人类手中有能打开这个装置的钥匙。我想他的名字叫埃斯顿。"
D.Strings[2132]="从这里离开，$c，不然他们也会把你锁住的。"
D.Strings[2133]="这把锁的钥匙呢？"
D.Strings[2134]="玛尔根……他是一个狱卒。他应该有那把钥匙。"
D.Strings[2135]="你好，我能帮你什么忙吗？"
D.Strings[2136]="暴风城银行"
D.Strings[2137]="银行坐落在贸易区，就在城门的西北面。来，让我在地图上指给你看。"
D.Strings[2138]="我希望雪融化掉。它总是把我的长袍弄湿，把一切都搞得乱糟糟的！"
D.Strings[2139]="该死的雪……哦，你是……$n，是吗？刚刚还有人跟我打听你的事情呢。"
D.Strings[2140]="什么消息？"
D.Strings[2141]="铁炉堡的术士拉戈·黑钳在找你，你要立刻到他那里向他报告。你可以在铁炉堡的荒弃的洞穴里找到他。"
D.Strings[2142]="你好，$c，我是萨纳瑞恩·绿树。"
D.Strings[2143]="这只动物看上去有点困惑。"
D.Strings[2144]="稍等片刻，我要把这些缝在一起……"
D.Strings[2145]="嗯，你的长袍做完了，$n。"
D.Strings[2146]="%s对$n窃窃私语。"
D.Strings[2147]="如果你问我，那我要说，地精的科技更加先进。我们有工具，我们还有天赋！"
D.Strings[2148]="要不是侏儒的狗屎运，他们就永远不会赢！"
D.Strings[2149]="如果我是你，我就赌地精赢。压其他车队都是在浪费时间。"
D.Strings[2150]="我已经把钱压在地精身上了！如果你够聪明的话也应该赌地精获胜！"
D.Strings[2151]="我听说下一场比赛的时候他们要把地精的车炸掉！不管是真是假，我会待在安全的地方。"
D.Strings[2152]="提尔斯的助手在哪里？"
D.Strings[2153]="哦，你说的是约翰森？我听说他躲起来了。"
D.Strings[2154]="要不是地精的狗屎运，他们每次都会把车撞进山里去！"
D.Strings[2155]="这种车赛是展现我们高新科技的大好机会！"
D.Strings[2156]="我给我们的车里安装了新的矩阵式调节器，它可以使赛车的引擎转速提高至少百分之十五！"
D.Strings[2157]="我那两岁的儿子设计的赛车都比那些可笑的地精造出来的破烂跑得更快！"
D.Strings[2158]="我的数据分析师认为这次我们会比上次的纪录提高二十秒！"
D.Strings[2159]="这些天提尔斯和他的助手都变得怪怪的。"
D.Strings[2160]="约翰森？我认为他在附近的某个地方……"
D.Strings[2161]="哈！提尔斯这段时间以来都在找他，但是他不想被找到。他是一只小鸡。"
D.Strings[2162]="熊？？"
D.Strings[2163]="终于！终于从这破牢房里逃出来了！$b$b肯瑞托将我从达拉然派到这个银松森林里来，要我调查阿鲁高和他的亡灵仆从们的活动，可我们却一点也不知道那个巫师已经完全失去了理智。$b$b我必须立刻把这个消息汇报上去！可在我离开之前，让我先把庭院门上的魔法锁给打开。$b$b既然你能击败雷希戈尔，或许也能从前面的层层埋伏中杀出一条血路……"
D.Strings[2164]="请打开庭院的大门。"
D.Strings[2165]="终于！终于有人把我从这破牢房里给救出来了！$b$b高级执行官哈德瑞克大人派我们来这儿收集这座要塞里的信息，以便制定一个能永久消灭铲除阿鲁高的计划。$b$b但那个老不死的巫师还真有点能耐，我们很快就被他的魔法结界给发现了。我被抓来关在这里，不过文森特可就没这么走运了。$b$b我得马上回去向哈德瑞克大人汇报。首先我会把庭院里的锁给你打开，或许你这么强悍的$c能从前面的一大堆伏兵里杀出一条血路……"
D.Strings[2166]="治疗法术失败了。不幸的是，注入那只野兽血管中的血清不久之后就会要了它的命。"
D.Strings[2167]="把狂暴蓟熊交给萨纳瑞恩接管。"
D.Strings[2168]="干得好。让我接管这头熊，然后我就可以施展治疗法术了。"
D.Strings[2169]="我以前曾经追寻过墓光之锤的道路。为了找到复活上古之神的方法，我只身深入这座巢穴，想要找到从那个该死的恶魔阿库麦尔身上抽取能量的方法。$B$B在看到无数无辜人白白地牺牲之后，我慢慢恢复了理智。$B$B我被困住了一段时间，但是现在我自由了！不幸的是，这里离我的家乡卡兹莫丹太远了！$B$B勇敢的冒险者，我现在可以将你传送到一个特别的地方，然后回来干掉阿库麦尔。如果你愿意的话，我现在就送你到达纳苏斯去。"
D.Strings[2170]="放松一下自己疲倦的身心。"
D.Strings[2171]="我们欢迎你随时来访，就像我们欢迎平原上吹过的风。"
D.Strings[2172]="满上一杯啤酒，拉一张凳子过来坐坐。我们要畅饮一番，同时还要分享我们的故事。"
D.Strings[2173]="你看上去很疲惫。在我们的屋里休息一会儿吧，让艾露恩引领你进入甜美的梦乡。"
D.Strings[2174]="请进，请进！不要坐得离火炉太近。它今天还没爆炸，但是为了安全起见，我想你还是坐在别的地方比较好。"
D.Strings[2175]="%s开始冒泡！"
D.Strings[2176]="旅店是供你在冒险后休息的地方。如果你不待在旅店中，那么当你重新开始冒险时候就得不到很好的休息。$B$B你可以在任何一家旅馆中免费得到一块炉石，当你准备休息时，就可以使用炉石传送回你所绑定的旅店中。"
D.Strings[2177]="主人倒下了！我们要为他复仇！"
D.Strings[2178]="你好，$c，很高兴认识你。"
D.Strings[2179]="我的陆行鸟需要接受训练。"
D.Strings[2180]="你好，$n。你对野外生存感兴趣吗？和大自然间的动植物共同生活！$B$B如果你感兴趣的话，你可以从我这里学到一些东西。"
D.Strings[2181]="请把我传送到达纳苏斯。"
D.Strings[2182]="异教徒， 净化他们！"
D.Strings[2183]="阿库麦尔死了！我终于可以离开这块伤心地了。"
D.Strings[2184]="跟我谈谈，听听我的故事吧。"
D.Strings[2185]="你好啊，你想要些什么？"
D.Strings[2186]="看看谁来了……有什么要我帮你的吗，$c？"
D.Strings[2187]="科瑞恩，我需要接受一些训练。"
D.Strings[2188]="你可以在英雄谷东北边的那个城堡平台上找到狮鹫管理员。"
D.Strings[2189]="那个声音是什么？"
D.Strings[2190]="我闻到了入侵者的味道……"
D.Strings[2191]="兄弟会是不可能被你这种微不足道的$c所阻拦的。"
D.Strings[2192]="你看上去迷路了。需要我帮忙吗？"
D.Strings[2193]="打起精神来，你们这帮蠢货！我们还有任务要执行！"
D.Strings[2194]="啊，你在找杜加尔·朗德瑞克。他那里有卡兹莫丹飞得最快的狮鹫！你可以在贸易区的外墙上找到他。"
D.Strings[2195]="你需要租用一只狮鹫进行飞行，是吗？杜加尔就在贸易区的城墙上，他那里有很多狮鹫，记着飞行的时候要抓紧哦！"
D.Strings[2196]="狮鹫？你是要使用空中旅行服务吧，到贸易区的城墙上去找到杜加尔·朗德瑞克就可以了。"
D.Strings[2197]="你可以在贸易区的暴风城接待中心里找到奥德文·拉弗林。"
D.Strings[2198]="你想要成立一个公会，对吗？祝你好运！\n\n和暴风城接待中心的奥德文·拉弗林谈谈吧。你从英雄谷进入贸易区之后就可以看到暴风城接待中心了。"
D.Strings[2199]="哈，你要找的是暴风城访客中心。从英雄谷走到贸易区后左手边的第一座建筑就是了。"
D.Strings[2200]="你要寻找哪种职业的训练师？"
D.Strings[2201]="法师们都聚集在法师区的巫师圣殿里，那里有一座高塔。和它相比，我们的兵营就好像是一座农舍。"
D.Strings[2202]="哦，你正在学习魔法？那没有什么地方会比法师区的巫师圣殿更好了。"
D.Strings[2203]="听起来你得去跟玛吉诺·仲马谈谈！你可以在法师区的巫师圣殿找到他。当然，那些法师总是来去无踪……"
D.Strings[2204]="你应该和奥斯伯谈谈。暴风城没有比他更擅长潜行艺术了，那家伙就在旧城区里。"
D.Strings[2205]="哎，潜行者只会影响我们在暴风城的工作。我真希望能把奥斯伯和马迪亚斯直接送到暴风城监狱去。"
D.Strings[2206]="如果你要找潜行者的话，就应该去旧城区。它坐落在暴风城的东部。"
D.Strings[2207]="战士"
D.Strings[2208]="战士们通常都待在猪和哨声旅店或者旧城区的兵营里。但是我建议你还是去旅店看看。"
D.Strings[2209]="想要接受训练？我可以把你训练成暴风城最好的战士，但是守卫是不能这么做的。我想你得去兵营或者猪和哨声旅店，找些合适的人来对你进行训练。"
D.Strings[2210]="去兵营或者猪和哨声旅店逛逛吧。如果你去旅店的话，别忘了尝尝那里的好酒，那些酒绝对能让矮人的酒相形见拙。"
D.Strings[2211]="你可以在花园区的月亮井旁边找到塞瑞德兰或者玛尔德利恩。到法师区的北边，教堂广场的西边就可以找到花园区了。"
D.Strings[2212]="如果你要寻找德鲁伊训练师，那就去花园区。塞瑞德兰或者玛尔德利恩一般都在那里的月亮井旁边。"
D.Strings[2213]="我们是大自然的孩子？那你该到花园区的月亮井去。"
D.Strings[2214]="教堂广场的光明大教堂是暴风城神职人员的住所，你可以在那里找到高阶牧师劳瑞娜。"
D.Strings[2215]="劳瑞娜是暴风城的高阶牧师，你可以在教堂广场上的光明大教堂里找到她。"
D.Strings[2216]="我建议你去教堂广场上的光明大教堂里找一找。"
D.Strings[2217]="如果你想变成强大的圣骑士，那么格雷森·沙东布瑞克公爵是你最好的导师。你可以在教堂广场上的光明大教堂中找到他。"
D.Strings[2218]="索尔芬·石盾从铁炉堡而来，让我们见识到了什么叫真正的狩猎艺术。如果你不介意被烟熏得泪流满面，就到矮人区去找他吧。他的屋子就在那个区域的东北部。"
D.Strings[2219]="什么？我不认为暴风城里有术士训练师。\n\n不过……在法师区的那家名叫“已宰的羔羊”的旅店中有一些与恶魔有关的活动，我想你应该去那里看看。"
D.Strings[2220]="是什么把你带到这个地方的，$c？"
D.Strings[2221]="霍格拉尔，你好！我要接受训练。"
D.Strings[2222]="他变得越来越胖而且越来越堕落，你可以闻到他身上发出臭味，他很脏所以我觉得他要去洗洗。$B$B好吧，不说这些奇怪的东西了。你从哪里来，我能帮你什么忙吗，$c？"
D.Strings[2223]="霍夫丹，你好，我要接受训练。"
D.Strings[2224]="开锁"
D.Strings[2225]="如果你要学习炼金术，暴风城只有一个地方值得你去……那就是炼金材料店。你可以沿着法师区的外围找到这家店铺。"
D.Strings[2226]="你应该去找瑟鲁姆·深炉谈谈，他是我见过的最好的矮人铁匠。你可以在矮人区的中心地带找到他。"
D.Strings[2227]="如果你想要成为一名好厨师，那就去旧城区的猪和哨声旅店，找斯蒂芬·雷百克谈谈。那家伙知道怎样才能做出与众不同的肋排大餐来。\n\n啊……说到他那著名的肋骨大餐，我都感到有些饿了。你可不要指望他会把那道菜的做法传授给你！"
D.Strings[2228]="暴风城有一个天才侏儒名叫利廉姆·火轴，他是这里最好的工程学训练师。你可以在矮人区的后面找到他。"
D.Strings[2229]="光明大教堂是暴风城所有治疗相关技能的训练中心。你可以去那里找安吉拉·雷菲德学习急救技能。"
D.Strings[2230]="你可以在法师区的炼金材料店外面找到塔尼莎。"
D.Strings[2231]="你想要学习制皮？西蒙·坦纳尔可以教你。你可以在旧城区的“护体皮甲”店里找到他。"
D.Strings[2232]="不知道你为什么要学习这样的技巧？只有不诚实的家伙才会去学习如何开锁。\n\n如果你真的想要学习这种伎俩，那最好到旧城区那边去，可能就在那些小巷里面。"
D.Strings[2233]="你可以去找吉尔曼·石手谈谈。我知道他在矮人区有一栋房子，但我不知道确切的地方。如果我是你的话，我就会去那边看看。"
D.Strings[2234]="如果你要去学剥皮术，可以到旧城区的“护体皮甲”店里看看。"
D.Strings[2235]="邓肯雇佣了暴风城最好的裁缝，乔吉奥·波利罗。他的店就坐落在法师区里。"
D.Strings[2236]="约翰森不想让提尔斯知道他还在闪光平原，所以他把自己变成了一只小鸡！$B$B如果你找到约翰森，就冲他招招手。没准他会跑过来的。"
D.Strings[2237]="我希望你已经准备开工了。"
D.Strings[2238]="欢迎来观看赛车！希望你喜欢这里，但请记得不要把钱都压在一支车队上。"
D.Strings[2239]="你好，$c！欢迎来闪光平原观看赛车！"
D.Strings[2240]="哪个车队的赛车最快？天知道！"
D.Strings[2241]="地精的赛车马力强劲，但侏儒的赛车也有不少独到之处……"
D.Strings[2242]="%s腾起青烟，紧跟着火苗也蹿了起来！你觉得你应该赶紧逃跑！"
D.Strings[2243]="你们要为背叛付出代价！"
D.Strings[2244]="你需要帮助吗？"
D.Strings[2245]="你能帮我指一下路吗？"
D.Strings[2246]="如果你跟着我的话，就请多加小心。黑海岸的野兽不会伤害我，但是可能会伤害到你，冒险者。"
D.Strings[2247]="像只猫一样在雨里爬行，你抓着刨着，一遍又一遍……稍后继续……$B$B哦，我没看见你进来，$n！我能为你做什么吗？"
D.Strings[2248]="你好！我是一个潜行者，我需要接受训练。"
D.Strings[2249]="森林里到处都是奇怪的野兽和被污染的空气。"
D.Strings[2250]="塞尤娜，你好。我要需要接受训练。"
D.Strings[2251]="我知道你在那里，潜行者。离开我的家，不然你就惨了。"
D.Strings[2252]="世界末日就要降临了！让大地吞噬我们的血肉吧！"
D.Strings[2253]="我们活着只是为了效忠上古之神。去死吧，入侵者！"
D.Strings[2254]="邪恶！到处都是邪恶的气息！这片森林必须得到清理！"
D.Strings[2255]="我感到绝望。杀死一个，还会出现更多。"
D.Strings[2256]="如果我们要成为这块新地区的主人，那么我们就必须要找个地方好好休息。把你的斧子放在火边，让大家分享你英勇战斗的故事吧。"
D.Strings[2257]="如果沿着这条路前进就会碰到那些元素生物，所以还是走那边吧。祝你好运, $n。"
D.Strings[2258]="生存技能"
D.Strings[2259]="生存技能是一项很有用的技能。\n\n去找凯尔布鲁斯吧，他在花园区的月亮井附近。"
D.Strings[2260]="没有什么能比在水晶湖钓一天的鱼更惬意的事情了。阿诺德·利兰教我学会了钓鱼。你可以在运河区的码头找到他。\n\n哦，不要相信他告诉你的任何关于运河里有怪物之类的故事。"
D.Strings[2261]="鲁坎·考迪尔在监狱附近的运河边上有一家小店。我相信他可以教你附魔的技巧。"
D.Strings[2262]="我独自走在路上，为了捍卫荣誉和清除这片大陆上的敌人而战。$B$B我能为你做什么，$n？"
D.Strings[2263]="*机械打手4100型做好了跟随你的准备*"
D.Strings[2264]="是的，我看到你要寻找的萨满祭司了。上次我见到她的时候是在这里的西边，她隐居在钢鬃部族旁的小山上。如果你够聪明的话，就可以找到一条通往小屋的山路，就在北边不远的地方，那条路可以让你避开野猪人，直接找到她。"
D.Strings[2265]="你好，艾瑞安，我需要接受训练！"
D.Strings[2266]="在这里，黑暗和阴影是随你的意志而变化的工具。"
D.Strings[2267]="又一个笨蛋在迪菲亚兄弟会面前倒下了。"
D.Strings[2268]="好吧，好吧……让我休息一下。你把我打得够呛。"
D.Strings[2269]="*你可以分辨出这些词* 停下……观察……阴影……"
D.Strings[2270]="%s细细察看着磨坊"
D.Strings[2271]="附近的味道真难闻。你身上真臭。"
D.Strings[2272]="你去前面看看！"
D.Strings[2273]="对妄图侵占黑石氏族领地的蠢货来说，今天就是他们的末日！"
D.Strings[2274]="混乱印记属于拉文霍德！你永远也不会得到它的能量！"
D.Strings[2275]="躲到暗处去。在这些野兽搞明白为什么我会被称为混乱之手阿兰提尔之后，我们还有些事情要谈谈。"
D.Strings[2276]="和提夫到神庙去。我们将在那里施展灵契魔法。"
D.Strings[2277]="好吧，我的$g兄弟:姐妹;，现在开始灵契仪式……你要靠我近一点。"
D.Strings[2278]="我会把东西放到火盆里，你只需要在自然之灵出现的时候和他们交谈就可以了。"
D.Strings[2279]="这样应该可以了……"
D.Strings[2280]="完成了，我的$g兄弟:姐妹;，接下来就是你的事情了。我要去休息一会儿。"
D.Strings[2281]="%s变得愤怒起来，发起了攻击！"
D.Strings[2282]="神器属于黑石氏族！我们要取回它！"
D.Strings[2283]="杀，杀啊！夺回神器！把它拿回去交给卡塔克！"
D.Strings[2284]="现在我们需要讨论怎么让这东西重新开始工作。"
D.Strings[2285]="也许我能把它修好，让我研究一下。"
D.Strings[2286]="三明治？什么？你给我做了一个三明治？"
D.Strings[2287]="伙计，没有人教你的话，你是不会知道该如何处理这块三明治的。"
D.Strings[2288]="玛尔顿，你这个蠢货！"
D.Strings[2289]="让我拿点东西……"
D.Strings[2290]="现在先看一下这些宝石。"
D.Strings[2291]="就是它了。现在开始行动！"
D.Strings[2292]="搞定了。日记已经翻译完毕。"
D.Strings[2293]="迪菲亚兄弟会的胜利！"
D.Strings[2294]="还有人想要挑战迪菲亚兄弟会吗？"
D.Strings[2295]="没错，你会像狗一样死去。"
D.Strings[2296]="啦啦啦……"
D.Strings[2297]="到果园去和我碰头——我现在要去把我的枪放好。"
D.Strings[2298]="正如我所想的那样，宝石和项链没有问题，问题在于能量之源。"
D.Strings[2299]="我会找到你的，潜行者。我已经感觉到你的恐惧了。"
D.Strings[2300]="倒下一个，还会来更多！"
D.Strings[2301]="%s疯狂地翻阅着那本厚厚的书册。"
D.Strings[2302]="真是讽刺——暴风城在紧缩防御，仅仅是为了对付小小的迪菲亚兄弟会。"
D.Strings[2303]="这是我要告诉玩家最重要的事。Huzzah！"
D.Strings[2304]="%s胡乱地翻弄着书。"
D.Strings[2305]="我把风险投资公司的文件放哪里去了？"
D.Strings[2306]="问题1，系列1？"
D.Strings[2307]="问题1，系列2"
D.Strings[2308]="这是第一系列第一个问题的答案。"
D.Strings[2309]="问题2，系列2？"
D.Strings[2310]="第二系列，第一答案。PWNED~"
D.Strings[2311]="第一系列另一个问题的另一个回答！"
D.Strings[2312]="让我在我的房子里施展一个法术，然后我们就开始！"
D.Strings[2313]="唉，它不在这里。我到底把那个东西丢在哪里了？"
D.Strings[2314]="终于找到了，它就在床上。呵呵，对不起！"
D.Strings[2315]="很好！让我来把这个东西修好！"
D.Strings[2316]="成功了！哈哈！项链的能量恢复了！"
D.Strings[2317]="嘿，我说……"
D.Strings[2318]="我们能休息一下吗？我的脚很痛……"
D.Strings[2319]="我不知道，吉尔。如果克拉文看到我们在休息，他一定会杀了我们的！"
D.Strings[2320]="唉，也许你是对的，我这就回去巡逻……"
D.Strings[2321]="%s的血喷了出来！"
D.Strings[2322]="卢修斯是拉文霍德庄园的老朋友了——我和他有很多事情要说。如果你需要我的帮助，那就去湖畔镇的码头找我。"
D.Strings[2323]="什么？兽人已经来了？"
D.Strings[2324]="干得漂亮，年轻的潜行者。干得漂亮……"
D.Strings[2325]="闭上你们的眼睛，孩子们。一场血腥的战斗就在眼前……"
D.Strings[2326]="%s自爆了！"
D.Strings[2327]="无论萨尔是否存在，碎手氏族的秩序都将延续下去。"
D.Strings[2328]="我需要接受训练，长官！"
D.Strings[2329]="碎手氏族的赞杜沙。赞杜沙怎么会帮你？他不能！也绝对不会！"
D.Strings[2330]="你好，赞杜沙，我想要学习开锁技能。"
D.Strings[2331]="你是来接受训练，还是来浪费一个战士的时间的？"
D.Strings[2332]="我需要进行战士技能的训练。"
D.Strings[2333]="这台机器开始运转了。"
D.Strings[2334]="按下贴着“盗贼工具”标签的黄色按钮。"
D.Strings[2335]="他给你蜂蜜酒$b$b他给你啤酒$b$b他总是过着快乐的生活$b$b这么多年他为我们每个人都服务过$b我们叫他微笑的吉姆。"
D.Strings[2336]="这是一种非常奇怪的植物，你从未在泰达希尔的其它地方见过。"
D.Strings[2337]="这个植物矗立在泰达希尔的普通植物之间，散发着奇异的紫色光芒。"
D.Strings[2338]="哇！波利要捏碎你！"
D.Strings[2339]="哇！哇哇！哇！"
D.Strings[2340]="按下贴着“大饼干”标签的红色按钮。"
D.Strings[2341]="嗯……大量的化学变化……"
D.Strings[2342]="%s血肉模糊。"
D.Strings[2343]="%s中除了一些碎屑和一根巨大的绿色羽毛之外别无他物。"
D.Strings[2344]="别忘了在我的机械设备中拿取一份大饼干和盗贼工具，你的任务需要使用这两件东西！"
D.Strings[2345]="你好。我的职责在得到允许的情况下，根据艾泽拉斯的造物者对于土灵的分析，向来访者提供相关的信息。我随时都可以与你分享这些信息。"
D.Strings[2346]="土灵是造物者设计的综合产物，并作为艾泽拉斯开始的几个种族之一。土灵被用于帮助造物者改善这个世界。$B$B他们是造物者在其它世界中设计的标准地下生物的改良型态。在最初的结构得以确定之后，这种原型产生了很多的变化。"
D.Strings[2347]="它是造物者在开创世界的时候创建的最早的一个物种。造物者所创建的每种生物都肩负了一定的使命。对于艾泽拉斯来说，必须改造原有的标准地下生物构造，使其适应地下深处的生活，土灵就是这种改造的产品。$B$B在土灵被创造出来之后，由于巨大的环境压力，它们出现了许多事先无法预见的变化。"
D.Strings[2348]="在正确回答这个问题之前，需要向你介绍更多关于土灵的背景资料。$B$B资料处理中。$B$B为了理解土灵的变化，首先要了解土灵的设计特征。创世者的目的是要提高标准地下生物母体的存活性，因此他们把与整个世界相联系的弹性构造基础整合在其中，土灵的出现正是为了达到这一目的。"
D.Strings[2349]="所谓弹性构造基础就是指用于种族合成的基本材料。造物者在创造土灵的时候放弃了以前创造世界时一直使用的基础材料，转而使用这种常见于艾泽拉斯的材料。$B$B通过对世界组成成分的分析，造物者认为可以合成一种加强型的生物，将它作为世界本质的缩影。造物者最终通过混合艾泽拉斯大陆上各种不同的石头成分，最后组成了这样一种生物的构造基础。"
D.Strings[2350]="简单地说，事实确实如此。$B$B虽然土灵的外表看上去像是一个小型的人型生物，但它们包含了艾泽拉斯大陆上各种石头的成分。它们在得到了力量和耐力最大化的同时也没有牺牲敏锐的感觉。它们的皮肤和肌肉的设计使其几乎完全免疫物理伤害，而且只需进行非常小的改动，土灵就可以展现出惊人的魔法抗性。"
D.Strings[2351]="以上这些内容是用来帮助你理解创世者的动机。他们创造出土灵这样一个物种是为了在他们离开之后，土灵可以成为这个世界中的一个重要部分，并保障创世者在艾泽拉斯世界的宏大计划得以继续实施。$B$B创世者对于“土灵”这个名字十分满意，因为它很好地体现了这个种族的基本特性。"
D.Strings[2352]="土灵唯一的异常变化是在高压环境下对于母体扰动的趋向。$B$B附录：设计的目的是让该物种能够适合地下深处的生活，从而无法满足高压环境下的适应性要求。$B$B这种扰动直到土灵按照计划进入世界的主循环之后才被发现。造物者并没有将土灵召回再重新进行改造，而是直接对其进行了实时的改造。"
D.Strings[2353]="[当你问了这个问题之后，它明显地停顿了一会儿]$B$B你需要的信息无法在该数据库中获取。对此我表示歉意。$B$B你可以在数据更新之后再次查询该信息，或者从艾泽拉斯的其它信息数据库处获得更多信息。"
D.Strings[2354]="当土灵的合成母体不稳定的时候，产生了两个变种。一号教程图像正在初始化。$B$B第一类变种被称为“穴居人”。这个变种保留了土灵的力量和耐力，但是它的感知力量完全丧失。欲望和狡诈成为了穴居人的本能。"
D.Strings[2355]="抱歉，我无法将现有记录数据按照时间顺序进行排序。$B$B虽然穴居人仍然包含了艾泽拉斯的各种石头的核心成分，但是它们感知能力的丧失是造物者无法接受的。$B$B穴居人可以进行单体繁殖。它们会把所有的东西当作食物，包括石头，甚至是另外一个穴居人。这样的同类相残是造物者极度反感的。"
D.Strings[2356]="二号教程图像正在初始化。$B$B土灵母体的第二个变种和标准的地下生物母体相比较而言，保留了很多必要的元素。这个种族被称作“矮人”。$B$B这个变种同样保留了土灵的力量和耐力。在某些方面，矮人甚至超过了土灵母体所具有的感知能力。但是，矮人这个变种的身体结构中已经完全没有了石质成分的踪迹。"
D.Strings[2357]="你的问题在数据库中有相关联接。$B$B矮人依然和艾泽拉斯的各种石头有着密切的关系，但是由于土灵在高压环境下的变异，矮人的结构与标准地下生物母体的结构保持了一致。$B$B因此，正如你所猜想的那样，矮人确实是从母体中变异出来的。"
D.Strings[2358]="抱歉，我无法将现有记录数据按照时间顺序进行排序。$B$B虽然矮人还是和艾泽拉斯的各种石头有着某种联系，但是他们更多的是向普通的地下物种发展。矮人的生活习性和繁衍方式都和其它的标准生物完全一致。$B$B造物者认为矮人是一种可以接受的变种，可以让其继续发展下去。"
D.Strings[2359]="造物者就是……造物者。$B$B他们根据自己的设计来创造和改变这个世界。他们是这个世界出现的原因，他们是艾泽拉斯的创造者。"
D.Strings[2360]="造物者也知道这个数据库中汇集了大量的信息。所以，如果你拥有诺甘农圆盘的话，便可以得到一份所有信息的拷贝。$B$B请确认你现在没有关于这方面信息的问题了。当你找到诺甘农圆盘之后，可以随时过来制作拷贝。"
D.Strings[2361]="土灵到底是什么？"
D.Strings[2362]="什么是“地下生物母体”？"
D.Strings[2363]="你所说的变化是什么？"
D.Strings[2364]="什么是“弹性构造基础”？"
D.Strings[2365]="难道……土灵是用石头做出来的？"
D.Strings[2366]="还有关于土灵的其它信息吗？"
D.Strings[2367]="我想我现在明白造物者设计土灵的意图了。你之前说的土灵的变化是指什么？"
D.Strings[2368]="为什么高压环境会引起土灵的不稳定性？"
D.Strings[2369]="土灵不稳定时会发生什么？"
D.Strings[2370]="穴居人？！你说的穴居人难道就是现在的那种穴居人？"
D.Strings[2371]="你提到当土灵不稳定的时候出现了两个变种。那第二个是什么？"
D.Strings[2372]="矮人！！难道矮人是起源于土灵的？！"
D.Strings[2373]="这些矮人和现在的矮人是同一种生物吗？矮人还和土灵有其它的联系吗？"
D.Strings[2374]="造物者是谁？"
D.Strings[2375]="有许多东西需要思考……"
D.Strings[2376]="%s指了指他的机械设备。"
D.Strings[2377]="%s发生爆炸，绚丽的焰火表演照亮了整个天空！这场景真是令人侧目啊，潜行者。"
D.Strings[2378]="%s打开了，一股刺激性的恶臭扑鼻而来，你发现里面装着大量的鸟粪和鲜血。"
D.Strings[2379]="%s满是死老鼠。嗯……"
D.Strings[2380]="%s是空的。"
D.Strings[2381]="我现在就去找那张碟片。"
D.Strings[2382]="军情七处保险箱被打开了，顿时响起了警报声。"
D.Strings[2383]="军情七处保险箱开始振动，发出嗡嗡声。从北边传来了一声巨响。"
D.Strings[2384]="军情七处保险箱被打开了。从很远处就能听到这巨大的响动。"
D.Strings[2385]="军情七处保险箱被打开了。一阵隆隆的巨响传入你的耳际。你只能听清几个字：“去……搜查……阴影……”"
D.Strings[2386]="嗨这是我的文书。"
D.Strings[2387]="没人可以窃取造物者的秘密！"
D.Strings[2388]="你怎敢亵渎这个神圣的地方？"
D.Strings[2389]="%s裂成了碎片！"
D.Strings[2390]="$n，你一定要读读我的日记。里面的内容对于你攻破那座塔的防御体系非常有帮助。"
D.Strings[2391]="那么说来你想要成为一名铁匠？$g小伙子:小姑娘;，扎好围裙，拿上铁锤，让我们开始吧。"
D.Strings[2392]="请让我接受训练。"
D.Strings[2393]="请传授我更多关于锻造护甲的知识。"
D.Strings[2394]="$n，我已经许久没有看见过有上好的护甲被锻造出来了。我以前曾经在大锻炉的格鲁努斯·削钢那里接受过训练。我相信如果你去他那里的话，肯定可以学到很多东西。"
D.Strings[2395]="你能帮我指指路吗？"
D.Strings[2396]="如果你想要找格鲁努斯的话，那么首先要到铁炉堡去，然后去城市中心的大锻炉，在那里你就可以找到格鲁努斯。"
D.Strings[2397]="请传授我更多关于锻造武器的知识。"
D.Strings[2398]="$n，你已经拥有了惊人的锻造技能。我不得不承认你锻造出的武器已经超过了我的水平。我所认识的水平高过你的铁匠只有博古斯·钢拳，我相信你可以从他那里学到不少东西。"
D.Strings[2399]="你想要接受博古斯的训练？当然，我可以告诉你在什么地方能够找到他。往西北方向穿过广场，然后再顺着西面的路走，在右手边的第二座建筑??可以找到他。"
D.Strings[2400]="$g小伙子:小姑娘;，你已经具备了相当高超的武器锻造水平，这让我非常吃惊。现在拿起铁锤，让我们看看你是否能够锻造出一把真正的武器吧。"
D.Strings[2401]="碎手氏族的影响遍布这一地区。我们已经统治了整个卡利姆多——法律，政治，军事，一切的一切。我们无所不知，我们目及一切。$B$B你现在已经成长到能够为我们效力的时候了，$n。是时候让你投入战斗了。$B$B你做好接受下一个任务的准备了吗？"
D.Strings[2402]="难道你看不出我现在很忙吗？有什么事？"
D.Strings[2403]="你真的那么笨吗？你锻造出来的是什么东西？那最多算得上是一把水果刀罢了。我可不会花时间来训练一个菜鸟。"
D.Strings[2404]="$n，仔细看我是怎么做的，然后严格按照我的指示办事。否则你只有死路一条，费苏勒可是非常出色的战士和刺客。"
D.Strings[2405]="如果你在塔的周围活动的话，一定会引起他的注意，这时你就可以实施碎手军礼了。让我们来练习一下……"
D.Strings[2406]="%s准备进行碎手军礼！*注意！*"
D.Strings[2407]="看到我是怎么做的了吗？如果你对如何使用碎手军礼还不太明白的话，那么就按照我的方式进行练习吧。如果你正确地实施了碎手军礼（使用/Salute指令），我就会给出相应的回应。"
D.Strings[2408]="欢迎来到大锻炉，$g小伙子:姑娘;。外面虽然非常寒冷，但是这里确实热火朝天。拿起锤子开工吧，让我看看你到底有些什么能耐！"
D.Strings[2409]="干得好，$n，我打赌你做的东西和布鲁克的酒一样正点。你应该去和米洛尔·怒斩谈谈，他会给你更多指引的。"
D.Strings[2410]="当然，我会告诉你怎么才能找到米洛尔的。他就在大锻炉的铁砧旁。仔细聆听他的教导吧，米洛尔绝对是名不虚传！"
D.Strings[2411]="$n，你已经得到了我的认可，你是我这些年来带过的最好的徒弟。如果你想要铸造一把真正的武器，那么你一定要去和米洛尔·怒斩谈谈。那个矮人能够教你铸造出一把真真正正的绝世好剑。"
D.Strings[2412]="你要找米洛尔·怒斩？他就在那儿，你瞧，就在你身后！呃，好吧，也许在你前面！反正就在大锻炉附近！"
D.Strings[2413]="厄运袭击了这座塔。这附近的所有风险投资公司雇员，包括我，都病倒了。$B$B就在上个星期，我们巡逻队的两个人死掉了，然后就变成了两具没有思想的行尸！$B$B我感到自己的生命力正在慢慢地被抽干……我已经渐渐丧失对自己的控制力。快让这样的痛苦结束吧……求求你了……*费苏勒重重地拍打着自己的脸*我还没有死……听着……作为风险投资公司的高级成员，我知道很多敏感的信息。"
D.Strings[2414]="你打扰我就是为了这个？你穿得真是跟垃圾一样，你还不如背着个死兔子到巨魔的洞里去跑一圈哪！"
D.Strings[2415]="$n，这真是你做的吗？真是一件精美的作品。我会继续训练你的，相信总有一天你可以达到皇家铸甲匠的水准。"
D.Strings[2416]="厄运袭击了这座塔。这附近的所有风险投资公司雇员，包括我，都病倒了。$B$B就在上个星期，我们巡逻队的两个人死掉了，然后就变成了两具没有思想的行尸！$B$B我感到自己的生命力正在慢慢地被抽干……我已经渐渐丧失对自己的控制力。快让这样的痛苦结束吧……求求你了……*费苏勒开始重重地抽打自己的脸*我还没有死……听着……作为风险投资公司的高级成员，我知道很多敏感的信息。"
D.Strings[2417]="大约五个月之前，风险投资公司荆棘谷分公司从藏宝海湾的一个名叫克兰克·菲兹巴布的神秘商人那里买了一瓶特别的毒药。显然，那是从赞吉尔手中偷来的！$B$B没错，我说的就是那个被流放的赞吉尔，他因为研究亡灵巫术而被他的部族赶了出去。$B$B那帮荆棘谷分公司的家伙拿到毒药之后就开始互相实验，结果可想而知。"
D.Strings[2418]="请继续，这个故事听上去很有意思。"
D.Strings[2419]="大工头普兹克·加里维克斯在那件事情发生之后就把剩余的毒药带到了他在淤泥沼泽的塔中继续进行研究，主要是想要解决毒药的不稳定性。最后他决定和迪菲亚兄弟会达成协议，共同研制开发这种毒药，代价是由迪菲亚兄弟会提供批量的成品毒药。$B$B迪菲亚兄弟会的克拉文·摩特维克负责对赞吉尔的毒药进行改良。"
D.Strings[2420]="接下来就是你看到的情况了：毒药发挥了预期的作用，喝下毒药的人都变成了被人控制的行尸走人，然而，这种毒药非常不稳定。$B$B加里维克斯，还有这座塔里里外外的人都已经感染了这种毒药。我们的意志和身体都在不断被侵袭。我们的器官变得越来越脆弱。$n，我已经无力去拯救这里的人了，而且我感觉自己马上要变成他们的一份子了。"
D.Strings[2421]="迪菲亚兄弟会？这可不是个好消息。简直是太糟了！请继续说下去。"
D.Strings[2422]="坚强一点，费苏勒！"
D.Strings[2423]="现在，这座塔的防御力量正处于最薄弱的时刻。包括加里维克斯在内的所有人都感染了疾病，你的攻击一定可以对他们造成致命打击！$B$B我想让你进塔拿到大工头普兹克·加里维克斯的徽记，还有最后一瓶药，把这些东西都交给申苏尔。他会知道接下来该怎么办的……我希望如此。"
D.Strings[2424]="你撞破了蘑菇丛，并且被孢子感染了!"
D.Strings[2425]="你好，凡人！我已被诺甘农圆盘激活，愿意为你提供帮助！"
D.Strings[2426]="*咳嗽* 谁在那儿？ *咳嗽*"
D.Strings[2427]="哪个蠢货胆敢闯入大工头的塔？"
D.Strings[2428]="那些嘲笑简直让我没法忍。如果林度恩再发出那种愚蠢的“哈哈哈”的声音，我就把他炸上天。"
D.Strings[2429]="瑟尔格，我要学习炼金术。"
D.Strings[2430]="呵呵！这里是个不错的藏身之地。"
D.Strings[2431]="那是什么声音？"
D.Strings[2432]="我感觉有盗贼在附近。"
D.Strings[2433]="$g先生:女士;，我能帮你什么忙吗？"
D.Strings[2434]="欢迎来到我的商店，很高兴在暴风城又遇见有人想要学附魔的了。你来这里是想要学点东西的吗？"
D.Strings[2435]="关于炼金术，嗯……我认为你现在和我的水平已经差不多了，也许我只能在个别细节上给你一些点拨。"
D.Strings[2436]="我希望你是因为好事才打断我的，我正在做一些重要的工作。"
D.Strings[2437]="关于草药学，嗯……我认为你现在和我的水平已经差不多了，也许我只能在个别细节上给你一些点拨。"
D.Strings[2438]="欢迎来到我的商店，很高兴在暴风城又遇见有人想要学裁缝的了。你来这里是想要学点东西的吗？"
D.Strings[2439]="啊，一个渔夫。你想要接受训练吗？也许我能教你些东西？"
D.Strings[2440]="欢迎来暴风城。我们可是花了很长时间才将它重建起来的，但是这些工作都很值得。那么，你是来参观的还是有任务在身？"
D.Strings[2441]="找我学习烹饪的学徒并不多，如果你准备好了的话，我马上就可以教你一些烹饪技巧。"
D.Strings[2442]="我看上去像是那种闲得可以招待每个旅行者的人吗？快点告诉我你需要什么，我可没有时间和你慢慢磨蹭。"
D.Strings[2443]="找我学习制皮的学徒并不多，如果你准备好了，我马上就可以教你一些东西。"
D.Strings[2444]="找我学习剥皮的学徒并不多，如果你准备好了，我马上就可以教你一些东西。"
D.Strings[2445]="大多数人似乎都对开锁技巧有一些偏见。让我给你露两手看看吧。"
D.Strings[2446]="你需要什么？有话快说。"
D.Strings[2447]="你要接受炼金术训练，是吗？"
D.Strings[2448]="我希望接受炼金术训练。"
D.Strings[2449]="虽然现在是和平时期，但是我们可不能荒废了我们的战斗技能！"
D.Strings[2450]="暴风城是人类的支柱，它是建立在钢铁的意志和锋利的刀刃上的。"
D.Strings[2451]="你好。你想要学一些战斗技巧吗？"
D.Strings[2452]="活到老，学到老。"
D.Strings[2453]="战士的任务之一就是保护。正如我们在战场上保护自己的同伴一样，我们要时刻保护被遗忘者的利益。"
D.Strings[2454]="哦，一个医师。我愿意传授给你一些能够在你旅途中对你有所帮助的东西。"
D.Strings[2455]="怎么了，$g小伙子:姑娘;？我能帮你什么忙吗？"
D.Strings[2456]="另一个生存技能专家，嗯……我认为你的水平已经和我差不多了，也许我只能在个别细节上给你一些点拨。"
D.Strings[2457]="又一个追踪者，嗯……我认为你的水平已经和我差不多了，也许我只能在个别细节上给你一些点拨。"
D.Strings[2458]="我从铁炉堡来到这里协助进行重建工作。我希望能向你传授尽可能多的本领，然后我就能回家去，把这堆事情丢给你来做。"
D.Strings[2459]="什么？你打扰我了，你最好赶快找到一个说得过去的理由。"
D.Strings[2460]="许多人也许会告诉你把陆行鸟作为宠物是一件可笑的事情。但是它的智力和忠诚度使其可以成为你最好的伙伴。如果你对它感兴趣的话，我可以向你和你的宠物传授一些技能。"
D.Strings[2461]="他不是一只鸡，所以你不能把他当作宠物。该干什么干什么去，不然我就给你点颜色看看。"
D.Strings[2462]="锋利的牙齿，坚实的肌肉，还有钢铁般的意志。这可是难得的宠物啊。如果你有兴趣，我可以告诉你如何把最弱的迅猛龙变成你在战斗中最好的伙伴。"
D.Strings[2463]="你最好离远点，$g小伙子:姑娘;。我的宠物肚子饿了，显然它对你垂涎欲滴。"
D.Strings[2464]="%s浑身是血，变得异常狂暴！"
D.Strings[2465]="在达拉然陷落和奎尔萨拉斯被摧毁之后，这样的东西就很难在世面上看到了。但是鲁坎·考迪尔和我的其他一些商业伙伴很好的完成了我的订单。"
D.Strings[2466]="我这里卖的可都是由暴风城最好的工匠和法师制作东西，世上最好的魔法装备！"
D.Strings[2467]="我想要看看你卖的货物。"
D.Strings[2468]="为了增进暗夜精灵和人类的联盟关系，我千里迢迢带来了由泰达希尔最好的工匠制作的东西。我这里的东西应有尽有，请随意挑选。"
D.Strings[2469]="暴风城最好的货物啊，朋友，你绝对不应该错过。看看有什么你需要的东西吗？"
D.Strings[2470]="看看我卖的东西吧，有什么你想要的吗？"
D.Strings[2471]="我这里只卖最好的东西，而且绝无二价。你想要讨价还价的话，就去找个地精商人。"
D.Strings[2472]="让圣光保佑你一路平安。如果你需要需要任何帮助，就来找我吧。"
D.Strings[2473]="不要让市场上的人类愚弄了你，$g小伙子:姑娘;。有了侏儒建造的那条地铁运输线，你可以很轻松地把货物从铁炉堡运送过来。如果那些家伙要收你运费的话，那么就告诉他们你要到我这里来买东西。"
D.Strings[2474]="我们这里特别提供一些限量的魔法物品。你有没有什么特别需要的？"
D.Strings[2475]="你所需要的东西很多都可以在普通商人那里找到。对于一些很难找到的东西，我可以为你限量提供，而且价格公道。"
D.Strings[2476]="你好，$g先生:女士;。我建议你在这里走动的时候小心一些，我刚刚弄丢了一个炸弹，而且现在怎么都找不到了。"
D.Strings[2477]="原来是同道中人！嘿，我正好可以向你展示一下我的一些新发明！"
D.Strings[2478]="如果你把A标签插到B槽中，那么当然会爆炸！来，看看我有些什么，然后你可以问利廉姆怎样组合才不会爆炸。"
D.Strings[2479]="没有人能够从这里偷走东西。从来没有人……从来！"
D.Strings[2480]="我想要查看一下我的储物箱。"
D.Strings[2481]="%s从他的岩石外壳中解脱了出来！"
D.Strings[2482]="谁胆敢唤醒阿扎达斯？谁胆敢触怒造物之神？"
D.Strings[2483]="欢迎来到蓝色隐士，这里是魔法汇集的地方。$g先生:女士;，我能帮你什么忙吗？"
D.Strings[2484]="我建议你最好不要坐得靠近阴影。"
D.Strings[2485]="欢迎来到猪和哨声旅店！和朋友在这里举杯畅饮，不亦乐乎！"
D.Strings[2486]="欢迎来到暴风城银行。我们竭诚为您提供最优质的服务，包括金融账户和绝对安全的储物箱。$g先生:女士;，您是否已经拥有了本银行的账户呢？"
D.Strings[2487]="我们是整个暴风城中唯一提供鲜花的地方。你可以在我们店里购买到各种美丽的花儿。"
D.Strings[2488]="$g先生:女士;，你想去哪里？只需要花几个小钱，你就可以搭乘狮鹫快速到达目的地。"
D.Strings[2489]="这些巨兽比你更会寻找道路，它们能让你更快地到达目的地，而且还可轻松欣赏沿途的美景。"
D.Strings[2490]="我需要空运服务。"
D.Strings[2491]="在这里说话你要小心点，一不小心就可能招来杀身之祸。现在，你有什么需要我帮助的事情吗？"
D.Strings[2492]="欢迎来到暴风城公会注册办公室。有什么需要我帮忙的吗？"
D.Strings[2493]="我如何才能建立一个公会？"
D.Strings[2494]="我要设计一件公会战袍。"
D.Strings[2495]="我希望你千里迢迢来到大煅炉不只是为了取暖。$g小伙子:小姑娘;，我能帮你什么忙吗？"
D.Strings[2496]="你看上去就是一个天生的铁匠。你的指甲缝中都是煤灰，双手充满了钢铁般的力量。啊，我甚至可以感觉到铁匠的血液在你的血管中奔流。你应该是来这里学东西的，好吧，$g小伙子:小姑娘;，拿起锤子，让我看看我能教你些什么吧。"
D.Strings[2497]="你似乎需要帮助，我能帮你些什么忙吗？"
D.Strings[2498]="我能帮你些什么？"
D.Strings[2499]="银行"
D.Strings[2500]=S[4786]
D.Strings[2501]="%s释放出无瑕的德莱尼水晶球，让它飘浮在空中。"
D.Strings[2502]="%s开始用一种你无法理解的语言吟唱。"
D.Strings[2503]="去找克拉姆吧。你可以在中心高地上的雷霆崖咨询处里找到他。"
D.Strings[2504]="你可以在中心高地上找到雷霆崖银行。"
D.Strings[2505]="双足飞龙巢穴就在城镇中心的图腾柱顶部。"
D.Strings[2506]="去长者高地的长者大厅找图拉克·符文图腾吧。"
D.Strings[2507]="啊，那你就要去猎人高地上的猎手大厅了。你可以在那里找到像浩特·雷角那样伟大的猎人。"
D.Strings[2508]="你是魔法的研习者？嗯，好吧……你可以在灵魂高地下的预见之池中找到他们。"
D.Strings[2509]="你应该找柯布神父谈谈，到灵魂高地下的预见之池去找他吧。"
D.Strings[2510]="灵魂大厅是萨满祭司的家园，它坐落在灵魂高地上。愿你的先祖保佑你。"
D.Strings[2511]="想要加入我们的行列？萨尔克·暴怒图腾可以指引你，他就在猎手大厅里。"
D.Strings[2512]="哪一项专业？"
D.Strings[2513]="追踪"
D.Strings[2514]="真有趣……我总是听到人类和兽人互相抱怨对方的名声是多么的差。对我来说，世界上所有种族都是一样的：他们都是笨蛋，而且脑子里只有贪婪两个字。$B$B你觉得我在胡言乱语？你难道没有发现你的生命只是为了满足贪婪的欲望而度过的吗？$B$B所有人都是这样。贪婪让我离开了家园，贪婪也会让我重新回去。"
D.Strings[2515]="$r，你是回来帮助库米沙的吗？不用担心，你腹中的剧痛只是说明你的意志力在崩溃。$B$B幸好这项收集任务不需要你的意志力。我相信当你给我拿来我需要的东西时，也一定会对我给你的报酬满意的。"
D.Strings[2516]="成功了，裂隙被打开了！！兄弟们，振作起来，我们要回家了！外域在等待着我们！"
D.Strings[2517]="快一点，兄弟们！我们一定要行动迅速！我不知道裂隙可以维持多久！"
D.Strings[2518]="现在你应该知道我为什么住在这里了。"
D.Strings[2519]="战争是血腥混乱的行为，你只能从中感受到痛苦、折磨和死亡。但是那些从战争中存活下来的勇士对于生活会有全新的认识，另外他们也都经历过许多生死关头的抉择。$g小伙子:姑娘;，你有什么故事可以告诉大家的？或者你是来这里听我的故事的？"
D.Strings[2520]="我要战斗！"
D.Strings[2521]="到中部高地的“本娜的炼金店”去找本娜，她可以指导你学习配制药剂的方法。"
D.Strings[2522]="你想知道如何用铁砧和锤子制作东西吗？卡恩·石蹄可以教你这些。他是个铁匠，就在中部高地的水池旁。"
D.Strings[2523]="在雷霆崖，你肯定找不到比阿丝卡·迷雾行者更好的厨师。嗯……我在这里都可以闻到他正在烹制的美味佳肴。你可以在中部高地的厨房里找到她。\n\n呃……我又饿了。"
D.Strings[2524]="到中部高地的附魔店去看看吧。泰戈会很乐意帮助你的。"
D.Strings[2525]="急救是一项很有用的技能。在战斗中，它常常能救人一命。如果你想要学习这项技能的话，就去灵魂高地的“精神治疗”小店里面找找潘德·缚石，他可是这方面最好的训练师。"
D.Strings[2526]="我不会因为你想学钓鱼而责怪你的。莫高雷有卡利姆多大陆上最好的钓鱼胜地，而在山顶渔具店中，你可以找到钓鱼所需的一切装备。\n\n告诉卡尔·迷雾行者是我让你去的！"
D.Strings[2527]="如果你想要学习草药学的话，就应该去找克米恩·冰蹄谈谈。他在中部高地那里。"
D.Strings[2528]="去雷霆崖中部高地的雷霆崖防具店找犹纳吧。"
D.Strings[2529]="去中部高地的石蹄地质学会找布瑞克·石蹄，他会教你如何采集矿石和宝石。"
D.Strings[2530]="坦帕以她制作的衣物而闻名，你可以在中部高地的雷霆崖防具店找到她。"
D.Strings[2531]="你应该找不到比德拉伊更好的追踪训练师了。他一般都在猎人高地一带出没。"
D.Strings[2532]="莫兰塔可以教你如何剥皮。你可以在中部高地的卡恩铁匠铺旁找到她。"
D.Strings[2533]="拜尔可以教你学习生存技能，到猎手大厅去找他吧。"
D.Strings[2534]="%s又恢复了平静。"
D.Strings[2535]="我马上就要开始工作了，$n！"
D.Strings[2536]="很好！我保证国王一定会为此感到满意的。"
D.Strings[2537]="国王的卫兵会去搬运那座纪念碑。至于你，请上台阶来，让我们好好谈谈，$n。"
D.Strings[2538]="这块被诅咒的土地上的野兽拥有超自然的能力。$B$B我们的研究表明，在黑暗之门打开的时候泄漏出了特别的能量，这种能量注入了那些野兽的体内，并把它们变成了现在的样子。$B$B毫无疑问，这些野兽非常危险，但是我们也认为它们能够在我们的研究中发挥很大的作用。$B$B$n，也许你有兴趣帮助我们研究这些野兽？"
D.Strings[2539]="%s将在10秒内安装完毕！"
D.Strings[2540]="%s将在5秒内安装完毕！"
D.Strings[2541]="%s已经安装完毕！"
D.Strings[2542]="我的兄弟德拉吉亚专注于研究诅咒之地上的这些野兽的生理特点，而我则倾向于研究它们的精神特点。$B$B那些野兽确实具有相当惊人的力量、敏捷和耐力，而且还拥有惊人的智力和重生能力，这和它们的外表显得不太符合。$B$B$n，你是不是有兴趣来协助我进行研究呢？"
D.Strings[2543]="哦！我差点忘记了！我会给你一套盗贼工具。它会对你有很大帮助的。"
D.Strings[2544]="%s准备着注射器。"
D.Strings[2545]="%s检验瓶中的血液。"
D.Strings[2546]="非常有趣！"
D.Strings[2547]="%s好像在对松鼠和石像说话，还不时地向你这个方向指指点点。"
D.Strings[2548]="$n，随便找个什么地方躺下。我保证你不会受到伤害的！"
D.Strings[2549]="看上去不太妙！"
D.Strings[2550]="很难想象如此多的死亡和恐惧会汇集在那么小的一块地区中。在这些门后是一块充斥着混乱和毁灭的大陆。$B$B冒险者，你要非常小心谨慎才行。诅咒之地中到处都是可以让你丧命的强大生物。"
D.Strings[2551]="作为萨尔手下最强大的二十名战士，我们被称为萨尔近卫军。$B$B在等待奥格瑞玛的命令时，我要求在诅咒之地边境建立一座营地。但是数星期过去了，酋长那里还是没有任何消息传来，我们开始变得有些焦躁不安了。$B$B$n，那是个错误的决定。我曾经年轻而又雄心勃勃，无所畏惧。这支部队在我的指挥下开进了诅咒之地。$B$B不久之后我就开始后悔了。"
D.Strings[2552]="请继续你的故事。"
D.Strings[2553]="后悔。这就是现在我所能感受到的一切。一个错误的决定导致了如此灾难性的后果。我多么希望当时能多等几天，直到命令传来。也许那样我们就能事先知道这片被诅咒的土地上到底有多少恐怖的东西等着我们！也许这一条命令就能指引我们去另外一个方向！无论怎么样，这都是我的错。所有的一切都是我造成的。"
D.Strings[2554]="过来，我的孩子们！"
D.Strings[2555]="你们怎敢侵入我的圣地！"
D.Strings[2556]="自~~~~~~由~~~~~~！"
D.Strings[2557]="%s的实体形态变得越来越虚幻。你注意到这个仆从身边的禁锢之石开始闪闪发光！赶快攻击它！"
D.Strings[2558]="%s四分五裂，释放了被它禁锢的灵魂。"
D.Strings[2559]="坐好了，等我把一切都准备妥当！"
D.Strings[2560]="最近在沙漠中有发现什么奇怪的东西吗？"
D.Strings[2561]="替我向特雷博指挥官问好。"
D.Strings[2562]="污染者……必须马上去通知萨尔……"
D.Strings[2563]="告诉他，这不是他的错……"
D.Strings[2564]="终于从他的诅咒中解脱出来了。父亲，我来了……"
D.Strings[2565]="干掉他们……还有他们的走狗！"
D.Strings[2566]="哈！我的宠物要吃了你！"
D.Strings[2567]="现在我要亲自解决你！"
D.Strings[2568]="让混沌之火将你吞噬吧！"
D.Strings[2569]="伊利法尔，你的主人在召唤你！"
D.Strings[2570]="面对我的勇士吧，凡人！"
D.Strings[2571]="准备坠入无限的痛苦深渊吧……我要复仇……"
D.Strings[2572]="你能相信作为精英战士的我居然失败了吗？$B$B我们的部队被无法抗拒的力量彻底摧毁，我所记得的一切就是不顾一切地逃跑，我所听到的一切只有我的战友撕心裂肺的惨叫和我自己的心跳。$B$B过了不久，我又回到了诅咒之地，希望能拯救我的伙伴。但是我被抓住了，最后被活活打死。$B$B这段日子中，我所能感受到的只有恐惧。"
D.Strings[2573]="请继续，英雄……"
D.Strings[2574]="我被抓之后遭受了非人的虐待，$n。他们轮番拷打我和基利斯中尉，而且在虐待一方的同时让另外一个在旁边看着。我们不断被折磨，直到有一天基利斯把战友们的遭遇告诉了我，还有他的拯救计划。$B$B他们所遭受的痛苦比我和基利斯所遭受的还要多，他们真的是生不如死。"
D.Strings[2575]="有什么比死亡还要痛苦？"
D.Strings[2576]="你和我都无法想象当他们的灵魂被强行从躯体中剥离出来的时候有多么痛苦。他们没有死，但是他们也不是活着的。他们成为了一具具行尸，只会听从主人发号施令。$B$B干出这些惨绝人寰的事情的就是这里的恶魔首领拉瑟莱克，他把我的战友都变成了奴隶。其中的九个被他绑定在黑暗之门附近，其余的九个则被他的爪牙们瓜分。"
D.Strings[2577]="手下？"
D.Strings[2578]="大法师奥利斯塔，术士瑟温妮，还有食人魔戈洛尔，他们各自分配到了三个。$B$B$n，你要知道，如果没有灵魂，我的战友是无法被杀死的。他们现在都处于一种无敌的状态。幸好的是，他们不能离开禁锢之石太远的距离。"
D.Strings[2579]="禁锢之石是什么？"
D.Strings[2580]="那些禁锢之石就是你要去摧毁的东西！正如我刚刚所说的，基利斯有一个完整的计划。$B$B每个被奴役的战士都有一个弱点，你必须尽量攻击他们，直到他们的实体形态几近瓦解。这时禁锢之石就会变得非常脆弱。你一定要抓紧时间摧毁禁锢之石，否则不久之后，那些奴隶又将获得新的力量，并再次变得刀枪不入了。"
D.Strings[2581]="英雄，你可以信赖我。"
D.Strings[2582]="我想你真的可以帮我，$n，但是单凭你的力量是无法和拉瑟莱克以及他的爪牙抗衡的。$B$B你一定要找到一支足够强大的队伍来解救我的战友，让他们脱离无尽的痛苦！你总共要摧毁十八块石头。$B$B努力地去战斗吧，$n。"
D.Strings[2583]="在我们继续之前，你必须先听一下我的故事，$n。这会对你很有帮助。"
D.Strings[2584]="%s准备拼尽全力刺它的敌人！"
D.Strings[2585]="%s等待卫兵消失在视野中。"
D.Strings[2586]="%s指了指西方。"
D.Strings[2587]="需要一些炼金术的材料吗？或者你有别的什么事情？"
D.Strings[2588]="你已经得到圆盘了！再次插入诺甘农圆盘来获取资料！"
D.Strings[2589]="啊，注意！"
D.Strings[2590]="前进！"
D.Strings[2591]="$n，等在这里。间谍机器人会尽快让他们出来的。准备好！在听完他们的对话之后再发起攻击。"
D.Strings[2592]="大人，您的客人到了。他正在等你。"
D.Strings[2593]="英雄，我有紧急的事情要和桑德·裂蹄商讨。"
D.Strings[2594]="$n，桑德·裂蹄已经来了。"
D.Strings[2595]="你们好。我要找莱斯科瓦公爵谈谈。"
D.Strings[2596]="谢谢，愿圣光与你们同在。"
D.Strings[2597]="当然，他在图书馆等您。"
D.Strings[2598]="啊，非常感谢。当我料理好这件小事之后就去图书馆。"
D.Strings[2599]="好了，我这就去！"
D.Strings[2600]="滚远点，渺小的$r。我看见你就烦。"
D.Strings[2601]="林吉自由了！"
D.Strings[2602]="在夜色的掩护下。"
D.Strings[2603]="我骑乘着死亡的双翼。"
D.Strings[2604]="林吉现在可以看到路了，$n。林吉认识回家的路。"
D.Strings[2605]="阁下，我会善用时间的。谢谢您。"
D.Strings[2606]="这沙漠可真不是人呆的地方！在这种高温下还得站在外面，我都快渴死啦！"
D.Strings[2607]="嗯！我还想买一些诺格弗格药剂！"
D.Strings[2608]="侦测到威胁！实施躲避动作！咯咯嗒！"
D.Strings[2609]="威胁分析！启动二号战斗计划！咯咯嗒！"
D.Strings[2610]="咯咯嗒！探测到空间异常——危险临近！咯咯嗒！"
D.Strings[2611]="停止！沃姆什来了！"
D.Strings[2612]="不要听那个傻瓜的话，孩子。他对所有人都这样。我一直都在观察你，你是一个真正的天才。过来和我谈谈。"
D.Strings[2613]="救命！$B$B如果你能帮我离开这里，我就帮你炸开通向祖尔法拉克酋长所在地的那扇门！"
D.Strings[2614]="Zul'Farrak——Weegli Blastfuse——默认问候语。"
D.Strings[2615]="我们要杀掉更多的巨魔！杀了足够的巨魔，我就炸开巨魔酋长的门！"
D.Strings[2616]="谢谢你，$n。你出现的真是时候，我差一点就死于非命了！现在我们只差打破这扇门就能面对巨魔酋长了……"
D.Strings[2617]="你现在可以炸开那扇门了吗？"
D.Strings[2618]="救命啊！我的队伍被巨魔俘虏了，他们准备杀了我们！$B$B只要你能救我们出去，我会答应你的任何条件！"
D.Strings[2619]="没有时间聊天了！我们必须马上想办法对付那些巨魔！"
D.Strings[2620]="$n，非常感谢你。没有你，我们绝对没办法逃离魔爪。哦，如果我刚才说过要报答你之类的话……忘掉它吧！"
D.Strings[2621]="嘿，布莱！比格维兹想要要回他的探水棒！"
D.Strings[2622]="Zul'Farrak——Sergernt Bly——默认问候语。"
D.Strings[2623]="没人敢挑战废土强盗团——机械小鸡也不行！进攻！"
D.Strings[2624]="你好！如果你想要接受一些挑战的话，我这里有个建议给你！$B$B我正在利用我发明的超级测蛋器帮助暗夜精灵的德鲁伊们拯救鹰角兽。由于菲拉斯废墟中的戈杜尼食人魔，这种生物的数量正在迅速减少。$B$B我收集各种不同类型的蛋。"
D.Strings[2625]="请告诉我更多关于角鹰兽的信息。"
D.Strings[2626]="这里西边有一处叫做菲拉斯的地方，那一带的鹰角兽正处于危险的境地中。$B$B我需要你从菲拉斯南部的伊斯迪尔废墟中给我带回鹰角兽的蛋，超级测蛋器会分析你带回来的蛋，并判断它是否可以孵化。然后我可以把蛋送到达纳苏斯去孵化，避免它们受到戈杜尼食人魔的黑暗魔法的影响！$B$B$n，你要知道，有些蛋即使完整无缺也是不可能孵化出来的。"
D.Strings[2627]="飞行系统启动！咯咯嗒！发动火箭并准备传送到藏宝海湾！"
D.Strings[2628]="林吉现在可以告诉你我的秘密了……$n应该去望海崖。林吉在那里的小岛上藏了一点东西。"
D.Strings[2629]="你找到它，它就是你的了！不要把林吉告诉你的秘密告诉任何人！"
D.Strings[2630]="$n，我马上就要完成了。只需再调整一下！"
D.Strings[2631]="搞定了！"
D.Strings[2632]="进攻，我的姐妹们！一个巨魔都不要放过！"
D.Strings[2633]="$n，准备行动！"
D.Strings[2634]="啊啊啊！离逃跑就差那么一点点！"
D.Strings[2635]="真是悲惨啊……"
D.Strings[2636]="我会的。"
D.Strings[2637]="林吉被攻击了！"
D.Strings[2638]="林吉需要帮助！"
D.Strings[2639]="什么？你怎么敢这么对我说话？！"
D.Strings[2640]="你好，$n。你准备接受训练了吗？"
D.Strings[2641]="我们就此结束了？好吧，我一点都不喜欢你！！"
D.Strings[2642]="你好，诺格！我需要接受训练。"
D.Strings[2643]="你好，$n！如果你需要的东西在我店里找不到，那么我可以专门去帮你找一下！"
D.Strings[2644]="你好，索维克，我想要看看你的货物。"
D.Strings[2645]="$n，如果你想去诺莫瑞根，那就和我谈谈。"
D.Strings[2646]="$n，给我点时间来根据你的身高体重调整传送器。"
D.Strings[2647]="好了，$n，你的传送器已经准备好了！"
D.Strings[2648]="哦，你在这里啊！"
D.Strings[2649]="啊，那朵花多漂亮啊……"
D.Strings[2650]="这些树多么壮丽啊，难道不是吗？"
D.Strings[2651]="你确定这条路正确吗？也许我们该走那条路……"
D.Strings[2652]="嗯……我想知道这条路能通到什么地方？"
D.Strings[2653]="我们走的是观光路线吗？"
D.Strings[2654]="哦，我又迷路了，抱歉。"
D.Strings[2655]="这真是一段有趣的旅程！"
D.Strings[2656]="我有点情不自禁了，这真是个漂亮的地方。"
D.Strings[2657]="又听到铃声了，真好听。"
D.Strings[2658]="啊，你在这里啊，罗克比特！对不起，我知道我不该到处乱跑。"
D.Strings[2659]="%s开始到处乱跑。"
D.Strings[2660]="$c，你好，我是达纳苏斯的制皮训练师。我能帮你什么忙吗？"
D.Strings[2661]="$c，你好，我是达纳苏斯的制皮训练师。我能帮你什么吗？"
D.Strings[2662]="不要忘了从箱子里拿上我的铃铛。记住，如果我迷路了，你就摇响铃铛，这样我就能找到你了。"
D.Strings[2663]="很高兴你回来了，沙恩。以后请不要再这样了！如果你真的不见了，我怎么向你父母交待？"
D.Strings[2664]="请告诉我更多关于戈杜尼食人魔的信息。"
D.Strings[2665]="庞大的戈杜尼食人魔部落控制了菲拉斯森林的很大一块区域。他们的黑暗魔法已经渗透了周围的环境，从而直接对那里的其它生物造成了毁灭性的打击。$B$B如果你去菲拉斯的话，可得小心那些食人魔——他们非常肮脏，而且很多都会使用强大的黑暗魔法。"
D.Strings[2666]="你们这些笨蛋，快点工作！"
D.Strings[2667]="%s活动起来！"
D.Strings[2668]="自毁系统程序启动。"
D.Strings[2669]="感谢你救了我！你的事迹一定会被广为流传的。"
D.Strings[2670]="%s向所有人挥手道别。"
D.Strings[2671]="嘿！离我们的财宝远一点！"
D.Strings[2672]="别以为你可以拿走我们的财宝！"
D.Strings[2673]="什么？！大胆！"
D.Strings[2674]="铁匠？真少见啊。我能为你做什么吗？"
D.Strings[2675]="迪菲亚兄弟会必胜！没有人能阻止我们！"
D.Strings[2676]="如果不住在有大理石天花板的房间里，我就浑身不舒服。天上的星星让我觉得很烦燥……"
D.Strings[2677]="这确实是一件上好的护甲，它给我留下了深刻的印象。我只知道谁可以打造出同样品质的护甲，他叫格鲁努斯·削钢，就在铁炉堡的大煅炉那里。我相信那位锻造大师一定可以教你不少东西。"
D.Strings[2678]="大煅炉在铁炉堡的最中心。他就在那里和其他的铸造大师一起工作。"
D.Strings[2679]="自从跟随普罗德摩尔以及她的人民一起离开洛丹伦以来，我就没有见过铸造得如此精良的武器。看来我没有什么可以教你的了，但是如果你去找博古斯·钢拳的话，他一定会向你展示一些华丽的技艺，他是我遇见过的最好的铁匠。"
D.Strings[2680]="博古斯以前据说是在大煅炉旁边工作的，但是当暴风城的重建工作完成之后，他就搬到了暴风城。有传言说他和一个叫卡斯鲁姆·斧拳的家伙一起在暴风城的矮人区开了一家店。"
D.Strings[2681]="嘿，难道你的眼睛不好使吗？莎伊斯就站在外面啊。"
D.Strings[2682]="你的锻造技术非常高超。你应该去找我的妻子莎伊斯·钢怒，她锻造盔甲的技术天下无双，即便是我也比不上她。"
D.Strings[2683]="欢迎你，铁匠。让我和你分享一些秘密吧。在这世界上，你不能相信任何人。任何人……你能相信的只有钢铁。"
D.Strings[2684]="你有什么事？你是来接受训练的吗？你是来寻找钢铁的秘密的吗？还是要学习锻造的技巧？快说！"
D.Strings[2685]="他在哪里？去隔壁的“传说中的装备”店里找他吧，他在那里为伟大的英雄铸造武器。向他证明你的能力，然后他才会给你展示他那神乎其技的手艺。"
D.Strings[2686]="多么锋利的刀刃啊，这绝对是一把精品战斧。$n，在武器锻造方面我已经没有什么可以教你的了。去向克尔格鲁克·血斧展示你的勇气和荣耀吧，他会帮你将这些融入你的技巧中，使你获得更大的提升。"
D.Strings[2687]="我看到出口了！快点，快点！"
D.Strings[2688]="反逃脱系统激活。自毁系统将在20秒后启动……"
D.Strings[2689]="警报炸弹2600型失效。自毁系统过载[激活]。冷却中[激活]。"
D.Strings[2690]="到奥格瑞玛的荣誉谷去找她。她和她的丈夫还有两个孩子都住在那里。他们都是出色的铁匠，而她将会是你最好的导师。"
D.Strings[2691]="你已经在锻造方面有了相当的造诣，可以把钢铁变成护身的铠甲。你的技艺已经超过了我，我必须让你去更好的锻造训练师那里深造。$n，你应该去奥格瑞玛找莎伊斯·钢怒，她是我所知道的最好的铸甲师，她应该能教你很多东西。"
D.Strings[2692]="啊呀……"
D.Strings[2693]="所有东西都有灵魂，如果学会聆听它们的声音，你就可以随心所欲地使用它们的力量。锻造并不是击打金属并将其改变成自己想要的形状那么简单，你必须倾听钢铁的声音，然后指引它，让它为你所用。"
D.Strings[2694]="你似乎正在寻求知识。也许你在找寻锻造之道，也许我能在这条道路上指引你。但是一旦你决定从事铁匠这个职业，你就应该学会聆听钢铁中的那些灵魂的呼喊。"
D.Strings[2695]="到奥格瑞玛的荣誉谷去找他。他在那里有一家名叫“传说中的装备”的小店。"
D.Strings[2696]="$n，你制作的这件武器确实很不错。你对指引钢铁灵魂的方法也已经非常精通了。聆听它们的呼声，它们就会像你指引它们一样指引你。去吧，去找那个名叫克尔格鲁克·血斧的兽人。他没有和钢铁的灵魂交谈过，但是他很善于倾听，他制作的武器是我见过的最好的武器。"
D.Strings[2697]="到奥格瑞玛去，你可以在荣誉谷找到她和她的家人。"
D.Strings[2698]="你所锻造的护甲能够抵挡最锋利的刀刃。$n你给我留下了深刻的印象，这可不容易。去找一个名叫莎伊斯·钢怒的兽人吧，她是除了那些该死的矮人之外最好的铸甲匠。"
D.Strings[2699]="你铸造的武器怎么样？你认为它能轻易击败敌人吗？让我来告诉你如何把它变得更加锋利吧。"
D.Strings[2700]="想要成为一名铁匠？想要锻造出最好的武器？我可以帮你，希望你能对这门手艺投入最大的热情。"
D.Strings[2701]="到兽人城市奥格瑞玛去，他就在荣誉谷的“传说中的装备”那家店里。"
D.Strings[2702]="$n，你铸造的武器很不错，已经达到切金断玉的水准了。但是我还认识比你的技艺更加精湛的铁匠，那是一个名叫克尔格鲁克·血斧的兽人，去找他继续学习吧！"
D.Strings[2703]="$n！真高兴再见到你！让我看看自从上次见面到现在你都学了点什么本事，没准我还能再教你些东西。"
D.Strings[2704]="$n，欢迎回到大锻炉。你是来拜访我的，还是准备进行下一阶段的训练？"
D.Strings[2705]="$n，这些金属真不错。拿把铁锤过来，让我指导你如何锻造一把绝世的利器。"
D.Strings[2706]="$n，你是回来学更多东西的吗？那么当你准备好的时候，我们就继续吧。"
D.Strings[2707]="什么事？你没有看到我很忙吗？"
D.Strings[2708]="$n，你的旅行怎么样？$g苏米和图米都很想念你，在你结束训练之后应该去拜访他们:我听说了一些关于你的故事，你似乎一直都很忙;。现在让我们来看看在你离开的这段时间里，你都学了些什么。"
D.Strings[2709]="什么事？我正好在制作一件护胸甲，没要紧事就别打扰我。"
D.Strings[2710]="$n，我已经看到了你的潜力。现在拿上锤子准备开工吧，你需要大量的练习才能提高自己的水平。"
D.Strings[2711]="我不会训练一点水平都没有的铁匠，等你觉得自己达到我的要求之后再回来找我。"
D.Strings[2712]="你好，$c！欢迎来到光明大教堂！"
D.Strings[2713]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-A，这是一台一级机密等级的终端。$B$B你必须拥有一张白色穿孔卡片才能够使用该终端的功能。\n\n01000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 01100101 00100001"
D.Strings[2714]="白色穿孔卡片读取成功……$B$B正在分配二级机密等级权限。\n\n01010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 01100001 01111001 01101001 01101110 01100111 00100000 01100111 01100001 01101101 01100101"
D.Strings[2715]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-B，这是一台二级机密等级的终端。$B$B你必须拥有一张黄色穿孔卡片才能够使用该终端的功能。\n\n01000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001"
D.Strings[2716]="黄色穿孔卡片读取成功……$B$B正在分配三级机密等级权限。\n\n01010100 01101000 01100101 00100000 01001100 01101001 01100011 01101000 00100000 01001011 01101001 01101110 01100111 00100000 01101100 01101001 01110110 01100101 01110011 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001 00100001"
D.Strings[2717]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-C，这是一台三级机密等级的终端。$B$B你必须拥有一张蓝色穿孔卡片才能够使用该终端的功能。\n\n01010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 00100000 01000011 01101000 01101001 01100011 01101011 01100101 01101110 00100000 01010011 01101111 01110101 01110000"
D.Strings[2718]="蓝色穿孔卡片读取成功……$B$B正在分配四级机密等级权限。\n\n01010000 01101100 01100001 01111001 00100000 01001101 01101111 01110010 01100101 00100000 01010111 01101111 01010111"
D.Strings[2719]="一言不发……"
D.Strings[2720]="%s歇斯底里地笑着。"
D.Strings[2721]="哈哈！丑恶的穴居人，准备受死吧！！"
D.Strings[2722]="获取更高等级的权限卡"
D.Strings[2723]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-D，这是一台四级机密等级级终端。$B$B你必须拥有一张红色穿孔卡片才能够使用该终端的功能。\n\n01010011 01101000 01101111 01110010 01110100 00100000 01100001 01101110 01100100 00100000 01110011 01110111 01100101 01100101 01110100"
D.Strings[2724]="获取更高等级的数据卡。"
D.Strings[2725]="红色穿孔卡片读取成功……$B$B正在分配四级机密等级权限。\n\n00111100 01101001 01101110 01110011 01100101 01110010 01110100 00100000 01100110 01110101 01101110 01101110 01111001 00100000 01101101 01100101 01110011 01110011 01100001 01100111 01100101 00100000 01101000 01100101 01110010 01100101 00111110"
D.Strings[2726]="吉布尔-埃拉卡$B猛虎之神，万兽之王$B$B缪萨拉-安泰恩$B死亡之神，时间之子，睡眠之父，夜晚之友"
D.Strings[2727]="继续读下去……"
D.Strings[2728]="沙德拉-艾罗萨$B蜘蛛之神，剧毒之母，蛛丝舞者，死亡之吻。"
D.Strings[2729]="使用工程学技能获得秘密结构图！"
D.Strings[2730]="矩阵式科技知识检测器探测到了你所具备的工程学天赋。你可以从以下选项中进行选择：\n\n01000111 01101111 00100000 01100111 01101111 00100000 01100111 01101111 00100001 00100001"
D.Strings[2731]="获得：自动净化装置"
D.Strings[2732]="访问中……\n\n工程学<#技能等级 == 菜鸟>\n \n01000111 01100001 01101101 01100101 00100000 01001111 01110110 01100101 01110010\n\n拒绝访问！"
D.Strings[2733]="数据访问授权。祝你开心！\n\n01001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011"
D.Strings[2734]="新鲜的面包，今天早上刚刚出炉的啊。"
D.Strings[2735]="快来买新鲜的面包啦！"
D.Strings[2736]="克拉文付我的钱可不够让我卖命去对付僵尸之类的东西。"
D.Strings[2737]="卖新鲜的水果啦！"
D.Strings[2738]="快来买这些苹果啊，又甜又脆的新鲜苹果！"
D.Strings[2739]="产自茂密的艾尔文森林的新鲜水果，快来尝尝啊！"
D.Strings[2740]="《菲拉斯的历史》……嗯……让我仔细看看这个。"
D.Strings[2741]="%s翻开书页。"
D.Strings[2742]="太不可思议了！就是它了，$n！"
D.Strings[2743]="去四周看看，$n。也许你能找到一些我忽略掉的东西。"
D.Strings[2744]="%s指向一大堆书。"
D.Strings[2745]="请等一下，$n。辛达尔在想办法把精灵龙从恐怖图腾营地中救出来。我们正巧路过这里，谁知道那些邪恶的牛头人对它们做了些什么。"
D.Strings[2746]="啊！那些精灵龙没能逃脱，我们该怎么办？"
D.Strings[2747]="太好了！精灵龙都逃脱了！我们成功了！"
D.Strings[2748]="主要交互完成。图像将在十分钟内消失。"
D.Strings[2749]="向你致敬！我是这个入口的守卫。请使用正确的圆盘进入奥丹姆。"
D.Strings[2750]="有了你的帮助，我就可以测量这些通道了。"
D.Strings[2751]="让我们看看能否发现这些穴居人是从哪里来的……然后想办法阻止他们！"
D.Strings[2752]="太混乱了……简直一团糟……"
D.Strings[2753]="向你致敬。我是这个入口的守卫。除非你的圆盘中包括奥丹姆圆盘，否则我是不会让你进入奥丹姆的。"
D.Strings[2754]="你的职责是什么？"
D.Strings[2755]="我的职责是为造物者守卫奥丹姆的入口。只有拥有正确的圆盘才能进入其中。$B$B你的圆盘中没有包含奥丹姆圆盘，所以你不具备进入奥丹姆的基本条件。除非奥丹姆圆盘存在，否则你无法进入。"
D.Strings[2756]="什么是奥丹姆圆盘？"
D.Strings[2757]="奥丹姆圆盘在哪里？"
D.Strings[2758]="什么？我们的世界“被安排了新的探访计划”？这是什么意思？！"
D.Strings[2759]="那么……奥丹姆里面到底有些什么？"
D.Strings[2760]="我找到奥丹姆圆盘之后会回来的。"
D.Strings[2761]="拥有奥丹姆圆盘才能够进入奥丹姆。这些圆盘中储存了造物者在这里的所有活动的纪录。$B$B从组成上来看，这些圆盘各不相同。它们的标注则只和奥丹姆信息相关，与奥达曼圆盘截然不同。"
D.Strings[2762]="造物者制造了若干张奥丹姆圆盘以供使用。他们控制着向整个世界分配奥丹姆圆盘的工作。同样，艾泽拉斯已经被安排了新的探访计划，到那时，未来的奥丹姆圆盘也许会重新开始流通。$B$B现有的奥丹姆圆盘已经被全部分给了具有一定忠诚度的种族。"
D.Strings[2763]="当外部势力和内部势力相互冲突，以至于扰乱整个世界的时候，造物者将探访计划作为重新控制世界的手段，不过执行这样的策略并不容易。$B$B关于预先安排的探访计划的更多信息，请查询所有与造物者相关的数据库。"
D.Strings[2764]="奥丹姆是一座为维系艾泽拉斯的自然体系而建造的研究工厂。只有那些拥有奥丹姆圆盘的人知道创世者在奥丹姆所进行的研究工作的详细情况。$B$B奥丹姆中的数据库被用于进行特殊的试验和数据编辑，更多详细信息，请查询数据库。"
D.Strings[2765]="当你再次触碰底座的时候，圆盘会重新回到你的手中。"
D.Strings[2766]="$n，我准备好了。带路吧！"
D.Strings[2767]="我们成功了！到恐怖图腾营地外面去跟我和耶尔卡会合吧。"
D.Strings[2768]="不！精灵龙没能逃脱出来，$n！我必须回到耶尔卡那里去，以确保她没有被发现。愿艾露恩与你同在。"
D.Strings[2769]="感谢圣光！现在情况十分紧急，即使有一个双头食人魔愿意施以援手，我也会欣然接受的。\n\n这座城市里到处都是穴居人！为了把它们赶出这里，我们采取了一些行动，但是却导致这一地区遭受了大面积的污染。幸好我们还有希望！\n\n我们疏散到铁炉堡的科学家正在研究对付辐射疾病的方法。同时，如果你能帮我阻止穴居人的入侵，那也许我们就能够夺回我们的城市！"
D.Strings[2770]="我准备好了。"
D.Strings[2771]="$n，给我几分钟时间。这里刚刚发生了一些事情，我要去确定一切都已经搞定了。我会马上会来继续和你谈谈的。"
D.Strings[2772]="快点！$n来了！"
D.Strings[2773]="去死吧，$n。月神不会容忍你再伤害那些她庇护着的生物！"
D.Strings[2774]="去死吧，$n。你怎敢进入我的射程！"
D.Strings[2775]="你惹怒了我！！"
D.Strings[2776]="在仪式上要小心谨慎。一不小心就可能导致全盘皆错……"
D.Strings[2777]="现在，看好了……"
D.Strings[2778]="这里很安静……"
D.Strings[2779]="……太安静了。"
D.Strings[2780]="看！在隧道那边！"
D.Strings[2781]="穴居人过来了！保护我，我要把这个洞炸掉！"
D.Strings[2782]="一发炸弹还搞不定，继续保护我！"
D.Strings[2783]="炸弹安放好了。向后撤，炸弹马上要爆炸了！"
D.Strings[2784]="炸弹将在10秒内爆炸！"
D.Strings[2785]="炸弹将在5秒内爆炸。清理通道！向后撤！"
D.Strings[2786]="%s向$n开心地道别。"
D.Strings[2787]="欢迎你，$c。如果你有什么问题，尽管来问我。"
D.Strings[2788]="警报！警报！入侵警报！入侵警报！"
D.Strings[2789]="长官？"
D.Strings[2790]="保持阵形——入侵者正在靠近。"
D.Strings[2791]="就这么办吧！我实在是厌倦了事事都帮你。我们到战场上去解决问题吧！"
D.Strings[2792]="你们的午饭来了，孩子们。把它们全部吃光吧！"
D.Strings[2793]="获得：退化射线"
D.Strings[2794]="我很高兴看到骚乱被平息了下去。"
D.Strings[2795]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-A，这是一台一级机密等级的终端。$B$B检测到白色穿孔卡片。权限开放。\n\n01010100 01100101 01101100 01101100 00100000 01111001 01101111 01110101 01110010 00100000 01100110 01110010 01101001 01100101 01101110 01100100 01110011 00100000 01110100 01101111 00100000 01110000 01101100 01100001 01111001 00100000 01010111 01101111 01010111"
D.Strings[2796]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-B，这是一台二级机密等级的终端。$B$B检测到黄色穿孔卡片。权限开放。\n\n01001011 01101001 01110011 01110011 00100000 01101101 01100101 00101100 00100000 01001001 00100111 01101101 00100000 01100111 01101110 01101111 01101101 01101001 01110011 01101000 00100001"
D.Strings[2797]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-C，这是一台三级机密等级的终端。$B$B检测到蓝色穿孔卡片。权限开放。\n\n01000111 01101110 01101111 01101101 01100101 01110010 01100101 01100111 01100001 01101110 00100000 01100110 01101111 01110010 01100101 01110110 01100101 01110010 00100001"
D.Strings[2798]="吱吱！$B$B欢迎使用矩阵式打孔计算机3005-D，这是一台四级机密等级的终端。$B$B检测到红色穿孔卡片。权限开放。\n\n01001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111"
D.Strings[2799]="%s收集好材料，开始工作。"
D.Strings[2800]="$n，我已经把武器制作完成了。"
D.Strings[2801]="保护你们的主人！"
D.Strings[2802]="苏利萨斯的子嗣会保护他们的主人……"
D.Strings[2803]="和我们战斗的那些生物的灵魂，或者说“灵魂精华”中存在着不可思议的力量。$B$B看清你的内心；学着驾驭你的灵魂之力吧，你将获得超乎想象的强大力量。"
D.Strings[2804]="灵魂精华容器已经准备好了，$n。"
D.Strings[2805]="%s开始进行仪式。"
D.Strings[2806]="苏萨斯……第一次听到这个词的时候，我还和你一样大。那个时候这个词对我来说没有什么意义，就好像现在它对你没有什么意义一样。但是当一群巨魔从祖尔法拉克来到这里肆意妄为之后，这个词就变成了恐惧的代名词。$B$B这里的人都会告诉你痛苦双刃并不存在，那只是一个神话，一个用来吓唬小孩子的故事。但是，$r，请相信我，它确实存在。$B$B<说到这里，特伦顿不禁开始用手抚摸自己脸上累累的伤疤。>"
D.Strings[2807]="请继续说下去，特伦顿。"
D.Strings[2808]="分久必合，合久必分。那两把剑被隐藏在祖尔法拉克城中。$B$B苏萨斯会在两把剑都被发现时重生。"
D.Strings[2809]="我是不会放过你的！"
D.Strings[2810]="快点痊愈吧，我的宠物！"
D.Strings[2811]="干得好！没有你的帮助，我是无法抵挡穴居人的！"
D.Strings[2812]="我听到那里有点动静。"
D.Strings[2813]="穴居人！挡住它们，我要准备爆破了！"
D.Strings[2814]="你永远也不会发现苏萨斯双剑。"
D.Strings[2815]="去死吧，凡人！"
D.Strings[2816]="苏萨斯的奴仆会将你生吞活剥。"
D.Strings[2817]="死亡是通往重生的途径，现在，让这个循环开始吧。"
D.Strings[2818]="塞拉摩的卫兵都是原本驻扎在卡利姆多的联盟精英力量。即使远离了家园，但我们还是会努力维护联盟的律法。"
D.Strings[2819]="我们对于树荫旅店被焚烧以及詹姆斯·海厄尔的妻子和孩子没能及时逃脱这些事情了解得并不多。$B$B我们想要找到詹姆斯的尸体，但是他却根本不在那堆废墟中。$B$B我们有一些线索，但是证据仍然很缺乏。我们希望能通过卫兵和塞拉摩人民的帮助让这件惨案得以大白天下。$B$B如果你也想帮忙的话，可以到贫瘠之地的边境那里调查一下旅店的废墟。"
D.Strings[2820]="关于树荫旅店，你都听说过些什么？"
D.Strings[2821]="你终于帮助基利斯解脱了？真是难以想象——现在特雷博派你来到我这里，想要学习关于恶魔的知识？$B$B<洛拉姆斯大笑了起来。>$B$B魔法所带来的痛苦最终还是消散了。"
D.Strings[2822]="你看到他们了吗？当然没有……我认为你是看不到的。以你的资质，即使有眼睛也和瞎了没有什么区别。"
D.Strings[2823]="嘿，洛拉姆斯，我从诅咒之地给你带来了一些消息。"
D.Strings[2824]="你能帮个忙吗？"
D.Strings[2825]="在抵抗燃烧军团时期，污染者拉瑟莱克是卡扎克麾下最强大的将领之一。当燃烧军团被击退，卡扎克的势力被压制之后，拉瑟莱克接受了诅咒之地的事务。$B$B当联盟和部落在诅咒之地以外的地方打得天昏地暗的时候，拉瑟莱克则在召集阴影议会的教徒，以及野蛮的巨槌食人魔。"
D.Strings[2826]="请继续说下去。"
D.Strings[2827]="可悲的是，正是因为萨尔的智慧才导致了恶魔之王和其它势力联合起来，特雷博的军队促成了恶魔之王、阴影议会和巨槌食人魔之间的联合。对于力量的无尽渴求使得他们签下了血契，对恶魔效忠。"
D.Strings[2828]="我不明白。"
D.Strings[2829]="瑟温妮、奥利斯塔和戈洛尔都没有意识到，其实他们和那些奴仆一样，都被永远禁锢在这片土地上了。他们所获得的不朽之力其实就是要永远为拉瑟莱克卖命。狡猾的拉瑟莱克又一次获得了胜利。"
D.Strings[2830]="$n，他们的意识已经被污染了。是的，情况越来越严重。他们现在只会为拉瑟莱克而活。他们手中的护符碎片就是召唤恶魔之王的钥匙。但问题是，他们已经对于常规的攻击方式完全免疫了。"
D.Strings[2831]="洛拉姆斯，无论你是否帮忙，我都会去做的。"
D.Strings[2832]="那么让我们假设你即将开始这段漫长而又艰辛的任务，你要做的是就是想办法摧毁这三个家伙的防御结界。然后呢？去污染者拉瑟莱克的巢穴挑战他？$B$B<洛拉姆斯大笑着。>"
D.Strings[2833]="我想要听听你的故事。"
D.Strings[2834]="人类宣称尘泥沼泽是他们的领地，但是石槌部族在我们的帮助下将他们赶了回去。"
D.Strings[2835]="烧毁的旅店。"
D.Strings[2836]="人类在贫瘠之地的边界处建了一座旅店，他们叫它树荫旅店。几个星期前，这家旅店被烧掉了。$b$b为什么我会在意这种事？当然，我并不关心人类的死活。但我在那家旅店里安插了一名间谍。我不会让他就这样白白死掉。我要知道这是谁干的。$B$B如果你想帮忙的话，就去查看一下树荫旅店的废墟，把你能找到的线索都给我带回来。"
D.Strings[2837]="寻找帕瓦尔·雷瑟。"
D.Strings[2838]="如果雷瑟和树荫旅店被烧毁的事有某种联系的话，你就得找到他，问个清楚。$b$b我派了奥格隆去追他，应该是朝东南方向去了。去跟奥格隆会合，然后一起去找雷瑟吧。"
D.Strings[2839]="$n，我不介意听到这个。不，你绝不能进入灼热峡谷，决不可能。我告诉你多少次了——我绝对不会让你进去的！你难道听不懂吗？你难道是兽人假扮成的？看我口型，不！$B$B如果我让你进去，那么每个人都会想要进去。不久之后，你最好的朋友，你的远房亲戚，然后你远房亲戚的朋友，然后所有的人就会来我这里想要进去。以前发生过这样的事情……好吧，我们不谈以前的事情。"
D.Strings[2840]="会发生什么糟糕的事情？"
D.Strings[2841]="你疯了吗？你难道不知道那里都是些凶残无比的野兽？我们可能得使用铲子才能挖出你的尸体。我们已经在那里损失了太多生命了。$B$B我的答案是，不行。如果你想要去灼热峡谷，那么我只能说抱歉了，此路不通。"
D.Strings[2842]="此路不通？那还有别的路吗……"
D.Strings[2843]="我原本不想告诉你的：如果你能够穿过荒芜之地的话，那么你也许可以找到通往灼热峡谷的另外一条路。$B$B没错，我说的是荒芜之地。在卡加斯营地那里，兽人铺了一条通向灼热峡谷的小路。你说说他们有多蠢吧！那帮家伙居然造了一条通向地狱的道路？他们到底在想什么啊？"
D.Strings[2844]="兽人？荒芜之地？小意思！"
D.Strings[2845]="小意思？"
D.Strings[2846]="不听我的劝告，你就等着有人来给你收尸吧！别以为你自己无所不能，小心使得万年船！"
D.Strings[2847]="对不起，贝波蒂。"
D.Strings[2848]="你猜怎么着，既然你觉得自己是个英雄，那么就穿过荒芜之地到灼热峡谷去，拿回一些能证明你的实力的东西，这样我也许能想办法帮你搞到一把钥匙。$B$B在灼热峡谷的最西南角有一个强壮的女士，嗯，几乎跟我一样强壮，她的名字叫狂暴的玛尔戈。也许你应该先去找她谈谈……"
D.Strings[2849]="完成了，全部完成了。"
D.Strings[2850]="%s抹去神器底座上的灰尘。"
D.Strings[2851]="%s小心翼翼地查看着大花瓶。"
D.Strings[2852]="可怜的杜里奥斯。那些黑铁矮人真是该死，帮帮我吧……"
D.Strings[2853]="这里正好有个地方可以摆放这支角！"
D.Strings[2854]="我一直把这个地方空着，希望有一些特殊的东西能放在这里。我不认为能有什么比这个更特殊了，$n。"
D.Strings[2855]="就是这样，全部搞定了！"
D.Strings[2856]="当你待在旅店里的时候，你就可以好好地休息。因此,你可以比留在野外更快地恢复到精力充沛的状态，这样就可以获得更多的经验值。$B$B另外你还可以通过和旅店老板交谈来获得一块炉石，以后就可以使用这块炉石快速回到你绑定的旅店里了。"
D.Strings[2857]="全部准备就绪。后退！"
D.Strings[2858]="10秒钟后爆炸！退后！"
D.Strings[2859]="5秒钟后爆炸！！！！"
D.Strings[2860]="我们从地底而来！你们无法阻止我们！"
D.Strings[2861]="干得漂亮！我会组织人手发动进攻，以防止更多穴居人到达地表。"
D.Strings[2862]="停下来……我要喘……喘口气……"
D.Strings[2863]="苏塔拉的秘密将永远留在这片土地上。"
D.Strings[2864]="拉格纳罗斯无所不知，凡人。"
D.Strings[2865]="我们现在去哪里，乔恩？"
D.Strings[2866]="你现在进展顺利，$n。但是你还有很多东西要学的，南贫瘠之地将是你获得进一步发展的地方。"
D.Strings[2867]="虽然我们把这块土地称作贫瘠之地，但对于睿智者来说，这里到处都是生命。"
D.Strings[2868]="我要让这个$n头上开天窗！"
D.Strings[2869]="你难道要让一个受伤的矮人把一切都给你搞定么？"
D.Strings[2870]="去死吧！$n，尝尝我的拳头！"
D.Strings[2871]="就是这里了，$c，大熔炉！把它标在你的地图上或者做些别的事情来保证你不会忘记这个地方。如果我出了什么意外的话，那我的队伍会永远被困在矿洞里面。"
D.Strings[2872]="继续前进！现在开始要加倍小心！我不想再进行任何战斗了。"
D.Strings[2873]="我真该戒烟了！稍等片刻，让我喘口气……"
D.Strings[2874]="我们基本安全了。从这里开始，我们要加速跑出去。不要落在后面了！出发！"
D.Strings[2875]="他是我的……"
D.Strings[2876]="啊~~~！他打败我了！"
D.Strings[2877]="%s深深吸了一口气……"
D.Strings[2878]="%s狼吞虎咽起来！"
D.Strings[2879]="%s在云雾中消失。"
D.Strings[2880]="大门就在眼前！我们就要成功了！但是首先，我真想要个呼吸器……"
D.Strings[2881]="你不知道你干了什么！我们要为了你的利益而毁灭你。"
D.Strings[2882]="听着，塔纳利斯的居民！我宣布$n已经成为秘银会的成员之一。他是一个光荣而且极具耐心的铁匠。为$n欢呼吧！"
D.Strings[2883]="它在洞里！它在洞里！"
D.Strings[2884]="他百发百中！"
D.Strings[2885]="从通往城中心的路出发！"
D.Strings[2886]="情况似乎不错！"
D.Strings[2887]="他把石头丢进了洞里！"
D.Strings[2888]="精神抖擞一些！快一点！"
D.Strings[2889]="成功了！！！！"
D.Strings[2890]="五个五个地来！"
D.Strings[2891]="啊，今天好冷啊，但是无论多么寒冷的天气都无法驱散我款待你的热情！"
D.Strings[2892]="我出售山谷这一边最好的布料和皮革服饰！"
D.Strings[2893]="在丹莫罗寒冷的日子里，没有什么比热酒更好的东西了！"
D.Strings[2894]="哦，热啊热！如果这样的热度都不能让你跳起来，那你简直就是块石头了！"
D.Strings[2895]="我在这里已经待够了，$n。我相信我们会再见的。祝你好运！"
D.Strings[2896]="异教徒！"
D.Strings[2897]="你敢打断我们的祈祷？处决他们！"
D.Strings[2898]="你的死将是对拉格纳罗斯的一次献祭。"
D.Strings[2899]="太好了，终于有新鲜的血了。"
D.Strings[2900]="告诉我关于发光的碎片的事情。"
D.Strings[2901]="你已经比许多人都走得更远了，$n。敬畏大自然的力量，你就会取得比大多数人都要伟大的成就。"
D.Strings[2902]="你回来了？<拉索里克笑了起来。>奥比斯顿，消灭他们！"
D.Strings[2903]="你的任务完成了。准备受死吧。"
D.Strings[2904]="出来吧，奥比斯顿，保护你的主人！"
D.Strings[2905]="太好了！太棒了！完美的演出。你说什么？你以为我死了？"
D.Strings[2906]="笨蛋，如果我拿我兄弟脆弱的感情开玩笑，他会被送去急救的。"
D.Strings[2907]="我轻松地让你从暮光之锤的那群笨蛋手里得到了最后一块苏塔拉之石。"
D.Strings[2908]="当我偶然发现苏塔拉之石的时候，拉格纳罗斯的力量从我身体中澎湃而过。正是拉格纳罗斯给了我方向。"
D.Strings[2909]="拉格纳罗斯按照自己的意愿创造了奥比斯顿。奥比斯顿会毁掉黑石塔的黑石兽人，将我们和那些处于火热深渊中的兄弟们联合起来。"
D.Strings[2910]="最终，是拉格纳罗斯在我重生的时候为我命名，我是火焰的侍奉者，黑衣拉索里克。"
D.Strings[2911]="%s的笑声渐渐远去……"
D.Strings[2912]="祭坛似乎在召唤你，好像它具有生命一样。"
D.Strings[2913]="触摸苏塔拉之石，召唤黑衣拉索里克和他的守卫者奥比斯顿。"
D.Strings[2914]="我认识一个住在哀嚎洞穴山顶的德鲁伊，$n。她也许告诉你更多关于这块碎片的信息。"
D.Strings[2915]="卫兵！救救我！"
D.Strings[2916]="你好，$n。愿月神的智慧指引你的心灵。我能帮你做些什么吗？"
D.Strings[2917]="向你致敬，阿斯塔利。我需要接受训练。"
D.Strings[2918]="我一直在等你，$n。很高兴看到你。你把货带来了吗？"
D.Strings[2919]="赞美艾露恩！好些年都没有人来拜访我了。"
D.Strings[2920]="作为黑海岸的一名年轻的暗夜精灵，我遇到了一队暮光之锤的成员。他们待我如同亲人，因此我背叛了对艾露恩的信仰，听信了他们的蛊惑之言。$B$B直到艾露恩的幻影从我眼前闪过，我才幡然醒悟。$B$B我满怀悔恨，开始向艾露恩祈祷。"
D.Strings[2921]="萨麦尔，请继续。"
D.Strings[2922]="我的自责、羞愧、懊悔和悲伤全都刻在这块纯金石板上。不幸的是，暮光之锤找到了石板，并认定我是诅咒者。我被立即处死，而那时我对艾露恩的祷告还没有做完。现在我已经成为了一个游荡的幽灵，无法降入扭曲虚空；我被关在笼子里，用来警告那些试图背叛暮光之锤的人。"
D.Strings[2923]="让我考虑一下，萨麦尔。"
D.Strings[2924]="拆毁者现在要回家了。再见，$c。"
D.Strings[2925]="当你靠近暗影蛛丝偷猎者的时候，对拆毁者使用命令法杖，这些盗贼会为自己的行为感到后悔的。"
D.Strings[2926]="再见，小$c。拆毁者现在就要走了。"
D.Strings[2927]="古老的哈卡祭坛静静地矗立在房间的入口处。$B$B你注意到阳台上有一尊巨大的毒蛇雕像立在那儿。它看上去跟祭坛上的雕像非常相似。它们之间一定有什么联系……"
D.Strings[2928]="祭坛和雕像会有什么联系？"
D.Strings[2929]="我想着手解开雕像之谜。"
D.Strings[2930]="告诉我更多关于灵魂精华的东西。"
D.Strings[2931]="这个地区有许多生物都是暗夜精灵的同盟。精灵们可以借助这些生物的能量来为自己效劳。部落也应该拥有这种能力。我想到一个方法，可以捕捉到这种能量并为我们所用。$B$B不要怀疑我告诉你的事情，$n。帮助我，你就会知道我所说的都是实话。"
D.Strings[2932]="我们会对你的尸体上进行妥善处理的，$n。我们称其为“分尸”。"
D.Strings[2933]="他们所做的一切只是打打猎，收集些东西。他们究竟做错了什么？？"
D.Strings[2934]="如果你是个裁缝，维兹格里克肯定有你想要的东西！随便看看，$n，想要买什么东西就和我说！"
D.Strings[2935]="收拾你的行装，$n！我从灼热峡谷那边的尼莉丝·洛克拉夫收到消息说，有个被称作“黑市组织”的团体正在大熔炉一带运作。到灼热峡谷去找到尼莉丝·洛克拉夫，然后把那个黑市组织连窝端掉。"
D.Strings[2936]="房间中出现一道明亮的光束，随即消失了。然后你注意到了另一道光束……又一道光束。$B$B它们似乎拼接出了某种图案。"
D.Strings[2937]="所有的雕像都已经就位，你可以开始解谜了。"
D.Strings[2938]="我要复仇。"
D.Strings[2939]="可以告诉我究竟是什么在驱使你去复仇吗？"
D.Strings[2940]="我父亲被大熔炉中的恶棍杀害了。我恳求暴风城给予援助，但是他们根本没有理睬。不仅如此，他们甚至不愿意承认这个地区的存在，更不要说派遣军队来匡扶正义了。$B$B我要报仇，$c。这世界上还有比这更强烈的理由吗？"
D.Strings[2941]="正如你所见的一样，我只不过是单枪匹马。黑铁矮人和拉格纳罗斯的爪牙可以轻松把我摆平，但是我对于像你这样勇敢的冒险者充满了信心，你一定可以把大熔炉里的那些东西全部搞定的。如果你愿意帮助我，我会给予你丰富的奖励，那些奖励将是你做梦也想不到的。"
D.Strings[2942]="让我跟同伴交换一下意见。"
D.Strings[2943]="我们要奴役野猪人！"
D.Strings[2944]="我们要统治这片贫瘠之地！"
D.Strings[2945]="亡灵天灾很快就将统治世界！"
D.Strings[2946]="我的眼睛！它在燃烧……它在燃烧……"
D.Strings[2947]="不要再烦我了！放了我吧，凡人！悲伤沼泽……凡人……求你了……"
D.Strings[2948]="愚蠢的凡人，只要我被释放出来，我就要撕碎你的灵魂！"
D.Strings[2949]="你是邪恶之神的奴仆，愚蠢的家伙。我要见证你的毁灭！"
D.Strings[2950]="我的灵魂不是用来当装饰品的！凡人，你必须将我从枷锁中释放出来！"
D.Strings[2951]="这对我的伤害太深了……伊萨里奥斯，我的老朋友……请帮帮我……"
D.Strings[2952]="什么时候噩梦才能结束？！我不能强迫自己醒过来！"
D.Strings[2953]="我没能守护好神殿……我堕落的灵魂将永远无法平静……"
D.Strings[2954]="太棒了！在你的帮助下，我们又有机会夺回我们挚爱的城市了。让我们为你大声为你喝彩吧！"
D.Strings[2955]="耐心一点，$n。火炬就要完成了。"
D.Strings[2956]="%s跪倒在地。他看上去已经精疲力尽了。"
D.Strings[2957]="完成了……"
D.Strings[2958]="哦，$n，等一下！还有一件事！快回来！"
D.Strings[2959]="制作惩戒火炬吧，卡拉然。"
D.Strings[2960]="%s被释放了，现在它与你是一体的，$n。"
D.Strings[2961]="%s吞噬了整个哨岗。哨岗着火了！"
D.Strings[2962]="我热烈欢迎你的到来，$c。你远道而来仅仅是为了找一个住在洞里的家伙，我相信你的这次旅程一定是有重要的事情，对吗？"
D.Strings[2963]="确实很不错，玛特拉克。看起来我的计划运行良好。你说是吗，$c？"
D.Strings[2964]="如果黑石军团要求你帮忙的话，你是不会帮助他们的，对吗？"
D.Strings[2965]="%s露出卑鄙的笑容……至少你认为他在发笑。"
D.Strings[2966]="我们该怎么处置他们？他们现在对我们没有什么用了。"
D.Strings[2967]="闭嘴，笨蛋！"
D.Strings[2968]="让他们活着，这样他们就可以看到他们都做了些什么——在黑石军团入侵灼热峡谷之后，毁灭和混乱将接踵而至。"
D.Strings[2969]="我饶了你们的性命，你得活着，拿好这些饰品！玛特拉克，把饰品交给他们！"
D.Strings[2970]="哦，当然，龙皮——可别弄丢了。我们家族的一些成员所制造的东西必须用黑龙皮来强化。"
D.Strings[2971]="%s开始扇动他巨大的翅膀，速度越来越快。他准备起飞了。"
D.Strings[2972]="黑石军团就要来了！我们要夷平这片土地，让熊熊大火直冲云霄。没有人可以活下来……"
D.Strings[2973]="将这间房间里的雕像全部重置。"
D.Strings[2974]="所有的雕像都已经回归了原来的位置。$B$B你必须重新对它们进行排列。"
D.Strings[2975]="马上，主人！"
D.Strings[2976]="你好，$G先生:小姐;。我是克希雷姆大人的学徒尼瑞尔。如果你们有任何问题，请随意向主人询问。$B$B当你准备下山的时候，就过来找我吧。"
D.Strings[2977]="我知道你是谁，$n。由于某种原因，命运将你带到我面前，而且我对此并不感到高兴。在未来的日子里，你将做出很多抉择，我希望你拥有足够的智慧来做出正确的抉择。$B$B相信我吧，$c——总有正确的抉择。"
D.Strings[2978]="像你这样的精灵待在这种洞穴里干什么？"
D.Strings[2979]="你很好奇，这种好奇掩饰了你在理解能力上的缺乏。我说这些是因为，如果你来此有一个确定的目的，你要提的问题就会显得毫无意义。$B$B因为这个原因，我只好对你说再见。"
D.Strings[2980]="你知道有关伊兰尼库斯的事吗？"
D.Strings[2981]="你很清楚我知道这些，$r。我们坦率地说吧。$B$B很明显你来这里是因为你知道自己拿着什么样的东西，你在哈卡的神庙中得到的这件东西使你身负着一件使命来到我面前。这个使命就是让我的伙伴……我的兄弟，得到安息。他被困在翡翠梦境的噩梦中，他自己无法解脱出来。"
D.Strings[2982]="他究竟怎么了？当我……当我遇到他的时候，他显得非常邪恶。"
D.Strings[2983]="阿塔莱巨魔所崇拜的神灵曾经受到惩罚。我们毁掉了他的肉身并把神庙沉入水中，但是他比我们预料中的要强大得多。堕落的种子散播开来，腐化了它所接触的一切。$B$B伊兰尼库斯负责看守沉没的神庙，以确保阿塔莱巨魔或是阿塔莱神灵都不会再死灰复燃。他是个无辜的受害者，我们低估了堕落的力量。"
D.Strings[2984]="我拥有一部分伊兰尼库斯的精华。你想用它来做什么……或者要我做什么？"
D.Strings[2985]="你来到此地仅仅是第一步……如果你想帮助伊瑟拉的绿龙军团，这是个正确的选择。$B$B你到这儿来也许只是受到个人利益的驱使，也许是受到良心的谴责。什么缘由并不重要，重要的是结果：伊兰尼库斯所经受的痛苦令我从梦中惊醒，现在我要终止他的痛苦。我想请你帮助我完成这项任务。"
D.Strings[2986]="我会认真考虑你所告诉我的事情。"
D.Strings[2987]="我已经把一块伊瑟拉巨龙军团的誓言石交给你了，$n。如果你决定帮助我们，就使用它，然后我们就可以开始了。"
D.Strings[2988]="祝你好运。很抱歉我不能和你一起去！"
D.Strings[2989]="%s开始从冰冷的空气中召唤鬼魂！"
D.Strings[2990]="入侵者！攻击入侵者！"
D.Strings[2991]="我的流放生涯结束了！让鲜血尽情流淌吧！"
D.Strings[2992]="有趣，真有趣……我知道有个德鲁伊居住在哀嚎洞穴上方的山顶，$n。她也许能告诉你有关这块碎片的更多信息。$B$B现在，我必须工作了！"
D.Strings[2993]="%s步履蹒跚。"
D.Strings[2994]="防御结界被摧毁了！醒来吧，阿塔莱！醒来吧！"
D.Strings[2995]="夫人！他们正在毁掉你的心血！"
D.Strings[2996]="哈！现在你死定了！"
D.Strings[2997]="准备好，靠近点。要是你放松戒备的话，那些恶魔会从暗处跳出来偷袭你的。"
D.Strings[2998]="大胆！让我的愤怒将你淹没吧！"
D.Strings[2999]="我们在艾萨拉度过的这段日子并不是辉煌而又灿烂的，但是我们仍然年轻而且热血沸腾——我们最终会获得胜利，这只是一个时间问题。"
D.Strings[3000]="贝尔戈洛姆派我们从奥格瑞玛到这里来帮助他，不过如果他成功了，那样整个部落就有了希望。$B$B虽然由于他一直以来都喜欢取悦女人，无数的兽人已经因此而丧生，但是他仍然是我们的指挥官，为了荣耀，我们只能尽力去做好。"
D.Strings[3001]="我不是为了荣耀而来这里的，$n。我来这里是为了兽人的骄傲。$B$B如果我没有拒绝贝尔戈洛姆的提议，那我肯定现在还在奥格瑞玛料理真正的生意。$B$B他对女人的渴望在杜隆塔尔的女性战士中尽人皆知，但是那仍然没有影响他成为大众情人。$B$B很幸运他并没有骚扰我太长时间——否则他会被砍成肉酱的。"
D.Strings[3002]="你好，$n。你是从奥格瑞玛来帮助我们的吧？很高兴见到你。我想尽快离开这片亡灵的森林，回到奥格瑞玛去喝酒度日。$B$B不过，我很想知道贝尔戈洛姆是如何说服你来这儿的。"
D.Strings[3003]="你成功了，$n！<这奇怪而熟悉的声音似乎是从瓶子中传出来的！>快回来！辐射尘的稳定期只有三十分钟。"
D.Strings[3004]="嗯，我大约需要5分钟的时间来完成关闭它的仪式。在我开始之后，你一定要好好保护我，否则我们都会没命的！"
D.Strings[3005]="谁这么大胆？！我要毁灭你！"
D.Strings[3006]="还剩三分钟——我感觉到能量正在不断汇集！继续保护我！"
D.Strings[3007]="只有两分钟时间了！我们只完成了一半，不要放松警惕！"
D.Strings[3008]="再坚持一分钟！坚持住，仪式就要完成了！"
D.Strings[3009]="很好——我们成功了！雕像中的火焰即将永远熄灭！我就知道你能行的！"
D.Strings[3010]="%s急速甩动着你收集的瓶子。绿色的光芒照耀着你。你看上去挺不寻常的，朋友。"
D.Strings[3011]="你找塞纳里奥议会有什么事，$n？"
D.Strings[3012]="我知道，我知道，我知道我根本不知道自己在哪里！$B$B我的家在棘齿城，不过既然我的飞艇在这儿坠落了，那我不如现在就开始进行我的研究项目了！"
D.Strings[3013]="灵魂还在尸体旁徘徊。它那可怕的眼睛死死地盯着你……"
D.Strings[3014]="%s感到饥饿难耐！"
D.Strings[3015]="%s饥饿难耐！"
D.Strings[3016]="菲拉斯的土地经历了岁月的洗礼，$r。大地、树木和生物，它们改变着菲拉斯的现状和未来。$B$B跟这儿所发生的一切相比，双塔山可以算是亘古不变的了……"
D.Strings[3017]="为了让上来观光的旅行者安全地下去，我可以为你提供翅膀。"
D.Strings[3018]="你能帮我下去吗？"
D.Strings[3019]="嗯，既然你提及了这一点，不错，昨天下午我确实看见了奇怪的事情！$B$B当我从东南方的巨魔废墟处跑过时……好吧，我其实不是跑过去的，应该说是跳过去的……沙地真是太烫了！$B$B总之，当我从废墟旁跳过的时候，我注意到那儿有一座营帐。我不得不说，在那儿设立营帐是件可笑的事儿……我本来要到那里去看看的，但是一只疯狂的大秃鹫把我赶走了。"
D.Strings[3020]="拆毁者跟着$n！把偷猎者碾成粉！毁灭他们！告诉拆毁者什么时候出击！碾碎一切！"
D.Strings[3021]="嘿，搞定了。"
D.Strings[3022]="不要担心，我会给你找个好心人的。"
D.Strings[3023]="谁能收养我可爱的小猫咪啊？"
D.Strings[3024]="我不敢相信我爸爸居然不让我养它。"
D.Strings[3025]="卖猫咪啦，我要给它找个好人家。"
D.Strings[3026]="过敏症究竟意味着什么？这对我的两只小猫有什么影响？"
D.Strings[3027]="有没有人愿意给我的小猫一个温暖的家?"
D.Strings[3028]="不！我们决不能让你召唤哈卡！"
D.Strings[3029]="你不能召唤我们的神！"
D.Strings[3030]="不！你不能这样做！"
D.Strings[3031]="住手！异教徒！"
D.Strings[3032]="发……发生了什么事？"
D.Strings[3033]="谢谢你救了我！$B$B我是一名来自暴风城的厨师兼炼金师。我到这儿来是要帮我叔叔安古斯寻找草药和食物的，但是这些野猪人将我抓了起来。要不是你赶过来的话，我想我已经被它们煮着吃了。"
D.Strings[3034]="你会烹饪？我也会！你有什么独门菜谱可以传授给我吗？"
D.Strings[3035]="嗯……对，我这里确实有一些挺有用的菜谱。让我来教你吧！"
D.Strings[3036]="你是个炼金师？我也是。也许你可以教我些东西……"
D.Strings[3037]="不错，我确实知道一种罕见的炼金术配方。让我来教你吧！"
D.Strings[3038]="%s的力量明显被削弱了。恶魔诅咒起作用了！"
D.Strings[3039]="%s渐渐招架不住你的攻势，恶魔诅咒生效了！"
D.Strings[3040]="%s似乎再也不能施放法术了。恶魔诅咒起作用了！"
D.Strings[3041]="你的武器完成了，$n。"
D.Strings[3042]="我接近这个世界了！"
D.Strings[3043]="%s开始施放一个反制法术……"
D.Strings[3044]="我要小心地配制这种——啊！……嗯，洒了一些出来，但是已经做好了！"
D.Strings[3045]="你好！如果你是来购买地精工程学图纸的，那你一定要知道，我们只为注册地精工程师服务。"
D.Strings[3046]="获取秘密的地精工程学结构图！"
D.Strings[3047]="你好！欢迎你来购买侏儒工程学图纸。我们的扫描仪已经确认，你是注册侏儒工程师！"
D.Strings[3048]="获取秘密的侏儒工程学结构图！"
D.Strings[3049]="你好，$g小伙子:姑娘;……我是奥格索普，你拥有的某件侏儒设备很可能就是我发明的！如果它爆炸了，那它就不是我发明的；如果它给你带来了财富，那我们可以讨论一下版权金的问题！$B$B哦，对了，如果你来自诺莫瑞根，那你可以走了。我没有什么跟你好说的。"
D.Strings[3050]="哦，这不是$n嘛！很高兴再见到你，我无法表达我对你的感激之情，你帮我及时完成了发明。$B$B我能为你做什么事吗？"
D.Strings[3051]="我是大工匠欧沃斯巴克，现代侏儒工程学领域的顶级设计师。我的工作就是用我们的闪亮崭新的扳手确保新的发明能够付诸实施！$B$B要是你碰巧懂得制造消除辐射污染的装置，那你算是来对地方啦……"
D.Strings[3052]="宝贝，让我来教你一个简单的加法守则：“地精”+“工程学”=“万事通”。告诉你其它算法的家伙肯定数学不及格。"
D.Strings[3053]="步兵！进攻！"
D.Strings[3054]="卫兵！保护森金！"
D.Strings[3055]="你不能玷污我们的圣地！"
D.Strings[3056]="卫兵！"
D.Strings[3057]="哨兵部队，来保护我！"
D.Strings[3058]="通过研究，我发现在哈卡的化身被击败之后，他的力量也会随之减弱。但是哈卡的大部分力量仍保留在扭曲虚空的深处。$B$B你曾经击败过哈卡的化身，$n。或许再次击败他的话就可以进一步削弱他的力量，也许有一天我们就将面对他的真身。$B$B我为你准备了一张卷轴，你可以用它在堕神圣地中再次召唤哈卡的化身。你敢再次迎接哈卡的挑战吗？"
D.Strings[3059]="你好，$c。虽然长期饮用烈酒已经让我的感觉变得迟钝了，但我的心灵之眼依然十分强大。"
D.Strings[3060]="好的，请教我召唤哈卡化身的法术。"
D.Strings[3061]="%s搜寻着魔法能量的源头。"
D.Strings[3062]="%s咆哮着。"
D.Strings[3063]="你好，$n。我在这里训练和照料年轻的角鹰兽，你可以随意看看。"
D.Strings[3064]="请告诉我更多关于角鹰兽的事情。"
D.Strings[3065]="德鲁伊对世界上所有生物的生存状况都非常敏感。当我们知道这些鸟处于危险之中时，便设立了一套营救系统，防止它们遭受菲拉斯的堕落气息的影响。$B$B一个名叫克格尔·曲藤的侏儒负责这项工作，她收集鸟蛋并将其交给我照顾。$B$B我们总是在寻求更多的帮助，$n。或许你该前往加基森找克格尔谈一谈。"
D.Strings[3066]="$n，我要再次对你表示感谢。现在我会留在这里，等安全了再离开。"
D.Strings[3067]="你必须打开地狱寻踪犬工具箱，并阅读一下使用说明书。当你接近南面那个满是峭壁巨人的半岛时，就开始召唤地狱寻踪犬吧。"
D.Strings[3068]="谢谢你，小$c！"
D.Strings[3069]="你的烹饪水平实在是太低了。再去训练一段时间，也许我就可以教你一些我所知道的东西。"
D.Strings[3070]="你的炼金技能还不足以理解我所传授的知识。也许你应该晚些时候再来找我谈谈……"
D.Strings[3071]="船长，他们来了！纳迦来了！"
D.Strings[3072]="魔法只会腐蚀那些意志薄弱的人。即便你不是术士，最好也牢记这一点。"
D.Strings[3073]="这是我的荣幸，$n。我能为你做些什么吗？"
D.Strings[3074]="要是你想去污染者高地的话，只管找我就行了。"
D.Strings[3075]="我想要挑战污染者。"
D.Strings[3076]="离开这儿。<废墟中冒出了一道白热的拱形火焰。你的脑海中浮现出一段过去的回忆：七具尸体环绕着一个孤单的黑铁矮人，他在一团巨大的火焰面前跪了下来。>"
D.Strings[3077]="你会葬身于此。<你的脑海中浮现出混乱和毁灭的情景。>"
D.Strings[3078]="凡人，不要玷污这些遗迹。<你全身笼罩在炫目的光芒中。你只记得自己看到了一只完全由火焰组成的生物。>"
D.Strings[3079]="陌生人，帮帮我们……<古物化为乌有。你脑海中浮现出八个黑铁矮人进行仪式的画面。>"
D.Strings[3080]="他是无法被打败的。<古物燃烧起来，化为灰烬。你获悉了古物中蕴藏的秘密：这座城市是被一个不属于这个世界的生物摧毁的。>"
D.Strings[3081]="我们都知道你的到来。<古物化为灰烬。你的头脑中充斥着新生的智慧。某种邪恶的东西潜藏在山脉的深处。>"
D.Strings[3082]="污染者……你会因贸然入侵而遭受惩罚。<一团火焰印记从古物里放射出来，然后消失在大地之中。>"
D.Strings[3083]="你好，$n 。你是来学习铁炉堡的历史的？"
D.Strings[3084]="当你准备听我讲述故事的时候就告诉我。"
D.Strings[3085]="我准备好了，阿克瑟努斯。"
D.Strings[3086]="数百年前，伟大的索瑞森城骄傲地矗立在富饶的大地之上，那里现在已经变成了荒芜的燃烧平原。$B$B索瑞森城是黑铁矮人的家乡，它那时正处于一场矮人的内战中。$B$B你知道，那片土地曾是赤脊山的一部分——直到有一天，索瑞森被一场大爆炸吞噬。城市变成一片废墟，周围的地区也被夷为平地。"
D.Strings[3087]="真惨。这是怎么发生的？"
D.Strings[3088]="我们不知道。$B$B活下来的黑铁矮人们躲入深山，并开始重建他们的城市。$B$B索瑞森的废墟上又出现了黑石塔和新的黑铁王国。他们在灼热峡谷内建立了新的防御工事，就在众所周知的大熔炉地区。$B$B一个关于远古邪恶力量控制黑铁王国的故事开始流传。"
D.Strings[3089]="很有意思，请继续。"
D.Strings[3090]="最近，黑铁矮人更加频繁地出现在地表上。他们在荒芜之地建造了堡垒，并派遣了庞大的探险队到奥达曼深处寻找古代的知识，他们甚至侵入了我们的祖国，攻击我们的巨石水坝。"
D.Strings[3091]="不可思议！他们怎么如此大胆？？"
D.Strings[3092]="我们需要一些冒险者的帮助，$n。你能帮我吗？"
D.Strings[3093]="我当然会帮忙的！"
D.Strings[3094]="你干得很好，间谍机器人！很高兴你回到我这里！"
D.Strings[3095]="很好！这就是你等待的机会！杀了他们！"
D.Strings[3096]="嗯，你好！如果你是来征收费用或者投递传票的，那你一定是将我认作别人了。非常抱歉！"
D.Strings[3097]="我想我的项链掉到湖里去了。那是我爸爸送给我的，他要是知道我弄丢了项链，肯定会气疯的。"
D.Strings[3098]="谢谢你，$g先生:小姐;，你找到了我的项链！你是最棒的！"
D.Strings[3099]="先不说外面的那些卫兵，我和我的兄弟们可都参加过海加尔山之战。谁想要在银行里面行窃，那就先过我们这一关。"
D.Strings[3100]="你好，$g先生:夫人;……你能花点时间帮帮我吗？求你了。"
D.Strings[3101]="我会用我的鲜血来保证这座银行的安全，你觉得很放心吧？"
D.Strings[3102]="再次感谢你帮助希拉里，$g先生:小姐;！我长大了也要成为你这样的英雄！"
D.Strings[3103]="你宁愿把你的货物交给一个地精吗?"
D.Strings[3104]="告诉我你要什么，别磨磨蹭蹭的。"
D.Strings[3105]="我活着的目的就是为主人服务。"
D.Strings[3106]="呈上饰物，玛特拉克。"
D.Strings[3107]="喵！"
D.Strings[3108]="我知道怎么跟小猫说话，喵喵说谢谢你。"
D.Strings[3109]="嗯，我可以训练你，但费用并不便宜。"
D.Strings[3110]="你好，$n！我是一名熟练的技师，我叫斯库提。"
D.Strings[3111]="如果你准备好了，我会向你传授附魔的知识。"
D.Strings[3112]="我的传送器被我弄丢了，现在我需要另外一个传送器，斯库提。"
D.Strings[3113]="大地中蕴藏着许多秘密，$c。保护这些秘密是我们永远的职责。"
D.Strings[3114]="如果你是来浪费我的时间，那你就是在浪费整个塞纳里奥议会的时间。为你自己着想，希望你不至于那么蠢。"
D.Strings[3115]="在我们的家园面临重重危机的情况下……暴风城的官员们竟然将大批军队派往别处，我真不敢相信！$B$B来自西部荒野的盗贼和来自东西两面的豺狼人蜂拥而至，暴风城没有受到围攻可真是个奇迹。"
D.Strings[3116]="你好，$C。希望你是来支持我们的。野兽和盗贼在艾尔文森林肆意妄为，我们的人手不够，无法维持治安！$B$B如果你没有做过这样的工作，就去看看关于霍格的告示。他是森林中的一只野兽，我们一定要干掉他！"
D.Strings[3117]="你好，$n。欢迎来到塞尔萨玛，别忘了去本地的酿酒厂看看！"
D.Strings[3118]="欢迎来到塞尔萨玛，这儿是你在洛克莫丹的家！$B$B塞尔萨玛是个好地方，但是对那些相应召唤来到这儿的勇士来说，这里可不是个吃喝玩乐的地方！如果你想以联盟的名义挑战危险的话，就去读读贴在探险者协会塞尔萨玛分部外面的海报吧。"
D.Strings[3119]="嘿，$n！这场景不甚美观，是吧？地平线轻帆号沉在海底，我的手下狼狈不堪，我们的货物和乘客如同碎片一般到处都是，你也许会认为暴风城曾在这儿举办过节日庆典。$B$B麻烦事儿还不止这么点……"
D.Strings[3120]="%s发出了一声怒吼！"
D.Strings[3121]="我感觉到处都是阴谋。还有那些对我所做的事情缺乏理解的家伙，他们想要把我关起来！$B$B你最好不要牵扯进来。"
D.Strings[3122]="什么？我在干什么？你眼睛不好使吗？我是一个梦想家，亲爱的$g先生:女士;，我梦想我们的将来会更加美好。很明显，我充满远见。$B$B然而，有些人却在想尽办法把我们困在平庸的泥沼里。我告诉过他，我是一个梦想家，而大德鲁伊鹿盔却回答说，“哦，我们似乎还缺一些挖水沟的。”$B$B我会帮助塞纳里奥议会弄走周围的泥堆，直到平庸的枷锁从我们身上卸下的那一天。"
D.Strings[3123]="你好，$r。我是弗兰克罗恩·铸铁。你是来了解黑石塔和黑铁矮人的吗？"
D.Strings[3124]="我没有选择，至少我是这么认为的。我会忍受索瑞森的毁灭并与我的国王和同胞站在一起。$B$B在拉格纳罗斯的统治下，达格兰·索瑞森国王开凿了山脉的中央，并建立了黑石塔。我们不知疲倦地工作着，发誓要建立一座比以前的任何城市或堡垒都要坚固的矮人城堡……甚至将来也不会有能与之媲美的建筑。"
D.Strings[3125]="我眼睁睁地看着拉格纳罗斯的堕落渗透了整个黑铁矮人社会，使这个曾经荣耀的民族变得疯狂……变得邪恶。$B$B当黑石塔建造完毕时，我与同胞们共同生存下去的意愿也消失殆尽了。我作为新的黑铁矮人的英雄而死去。这座坟墓就在我亲手建造的城门处，作为对我的成就的敬意。"
D.Strings[3126]="请继续。"
D.Strings[3127]="我那柄巨大的战锤——铁胆之锤，被交给了新的建筑大师弗诺斯·达克维尔。这个家伙人品低劣，才疏学浅。$B$B这点就是你需要知道的，$n。我想阻止他。他无法将铁胆之锤的力量发挥到极致，但是如果他的后续者有这个能力的话，他们就会毁掉一切的，而这必将带来灾难性的后果。"
D.Strings[3128]="弗兰克罗恩，告诉我该怎么做。"
D.Strings[3129]="你可以在秩序竞技场外侧的工艺之厅里找到弗诺斯·达克维尔。杀死那无耻的杂种，找回铁胆之锤。$B$B把铁胆之锤带到索瑞森神殿去，放在适当的地方——就放在我的雕像的手中。$B$B然后，我存放钥匙的小隔间就会打开。更重要的是，铁胆之锤将会永远都掌握在我手中。如果他们试图拿走战锤，雕塑和战锤就都会粉碎，并永远消失。"
D.Strings[3130]="没错，但是如果你精通草药学的话，你会发现它非常有用！你要做的是用特别的种子来细心培育药草——而不是一遇到风吹草动就挥斧乱砍。虽然你即将得到的常青袋能让最没有经验的新手轻松进行种植工作，但那些对草药学有天资的冒险者将会得到更丰硕的成果。"
D.Strings[3131]="做好准备！若是纳迦知道我们还活着，他们就会马上进攻的。"
D.Strings[3132]="考虑清楚，$g小子:姑娘;，我可没心情顺着你的想法哄你。我在这里的工作是确认大德鲁伊的研究工作正在按计划进行，而不是跟那些不愿为塞纳里奥议会效劳的家伙聊天。"
D.Strings[3133]="您好，尊贵的$c。我这个塞纳里奥议会的谦卑的仆从愿祝福与您同在。"
D.Strings[3134]="阿玛卡尔，你认为高图斯会把我们派到哪儿去？我可不想再去燃烧平原了。"
D.Strings[3135]="别那么孩子气，拉扎布雷德。现在你要以酋长的精英部队的身份参与战斗了。你不想像加戈尔那样死掉，对吧？"
D.Strings[3136]="%s似乎忽略了周围的一切。"
D.Strings[3137]="萨特拉克！"
D.Strings[3138]="不，加戈尔。不可能。"
D.Strings[3139]="嘘！闭嘴。高图斯来了！"
D.Strings[3140]="小心一点，$c，我有一个为你准备的变形术……"
D.Strings[3141]="集合完毕，长官！"
D.Strings[3142]="集合！"
D.Strings[3143]="我喜欢馅饼。"
D.Strings[3144]="奶奶总是说世界上没有比一块自制的、鲜美的樱桃馅饼更好的东西了。"
D.Strings[3145]="那么，这次新的瘟疫是怎么回事？"
D.Strings[3146]="这馅饼真好吃，你要尝尝吗？"
D.Strings[3147]="今天不太开心？尝尝这些樱桃馅饼吧。"
D.Strings[3148]="哦，这真可怕，真是太可怕了！薇薇安，你也许刚看到它就会死掉。"
D.Strings[3149]="这块美味的樱桃馅饼能让小侏儒喜极而泣。"
D.Strings[3150]="尝尝樱桃馅饼吧，它会令你开怀大笑的。"
D.Strings[3151]="新鲜的樱桃馅饼！香味扑鼻，让你的眼睛发直！"
D.Strings[3152]="哦，快说吧！这悬念本身就足以让一个女孩尖叫了！"
D.Strings[3153]="樱桃馅饼是我在整个艾泽拉斯最喜欢的食物。"
D.Strings[3154]="哦，据我所知，这次的新瘟疫有着上次瘟疫的全部风味，但是却不包含上次瘟疫的卡路里或是碳水化合物！"
D.Strings[3155]="哦，多么欢欣鼓舞！"
D.Strings[3156]="%s兴奋地鼓掌。"
D.Strings[3157]="很好，萨特拉克，你可以出发了。"
D.Strings[3158]="那边的女士们，你们好。你们听说最近的新闻了吗？"
D.Strings[3159]="你们听到督军的话了，废物！前进！"
D.Strings[3160]="士兵们，干得好！轻松一下吧！"
D.Strings[3161]="%s脸红了。"
D.Strings[3162]="呃……除非你是卡利姆多大陆上的最后一个兽人，隆克。"
D.Strings[3163]="啊，看看时间！我必须返回那边的哨岗去了……"
D.Strings[3164]="请原谅，我必须得走了。再见，女士们。"
D.Strings[3165]="这些墙的另一面存在着巨大的危险，$n。等你的战斗经验更丰富之后再回来吧。"
D.Strings[3166]="你的恐怖统治现在结束了！面对你的末日吧！"
D.Strings[3167]="你在这荒芜之地到处游荡，一定是因为缺钱花了，$c。一定是像我一样缺钱。$B$B要么就是因为你疯了。疯了，像我一样。"
D.Strings[3168]="%s没命地逃开了！"
D.Strings[3169]="%s在贝迪斯掉下去之前伸手拉住了他。"
D.Strings[3170]="绝不能让邪恶力量侵袭这个世界！来吧，孩子们！"
D.Strings[3171]="嗯，如果我能用树枝做掩护的话，那些守卫是看不见我的。"
D.Strings[3172]="你必须耐心一些，$n。我的间谍机器人正在进行非常精密的操作，马上就帮你搞定。$B$B哦，帮我个忙，尽量不要让莱斯科瓦看到你……我们要伏击他。"
D.Strings[3173]="戈泰什死了？？！"
D.Strings[3174]="快跑！快离开这座山！"
D.Strings[3175]="谁杀了戈泰什！？！？谁干的？！"
D.Strings[3176]="艰难时期，嗯，$n？谁都需要帮助，我和我妻子也不例外。"
D.Strings[3177]="$n杀的！$G他:她;现在就要杀了你！快跑！快跑！"
D.Strings[3178]="跑到小山那边去！等等！我们已经在山里了！"
D.Strings[3179]="我想看看你出售的货物。"
D.Strings[3180]="%s疑惑地看着你。或许你该仔细看看？"
D.Strings[3181]="开始吧！"
D.Strings[3182]="你确实很强大，$n。如果你想要找活干，就来找我吧。"
D.Strings[3183]="我的眼睛从不欺骗我，$r。你身上蕴涵着巨大的能量——足够的能量，或许能对我们有所帮助。来塔顶找我吧。"
D.Strings[3184]="我亲眼看见的！你这辈子所见过最巨大的Makura，比高山巨人的拳头还要大。那时它正在攀爬双塔山。我不知道你想怎么上去，但如果你成功了，一定不会空手而归。"
D.Strings[3185]="我想买点东西，行吗？"
D.Strings[3186]="你能告诉我怎样才能得到一份视灵药剂吗？"
D.Strings[3187]="当然，$n。看起来你是个值得信任的$r！我在一里开外就发现了……$B$B总之，说正经事。我需要一株灵根草才能制作视灵药剂。药剂所需的其它成分都是小菜一碟，但是灵根草就不是那么容易得到了。"
D.Strings[3188]="钥匙……拿到钥匙……格斯塔恩有……钥匙。"
D.Strings[3189]="你就不能有点出息么，$c？带我离开这儿！钥匙在审讯官那儿。"
D.Strings[3190]="嘿！嘿！叫你呢！$c！帮我离开这儿！"
D.Strings[3191]="%s呻吟着。"
D.Strings[3192]="好吧，让我好好看看这东西……"
D.Strings[3193]="哦，该死……"
D.Strings[3194]="好了！让我们开始吧！"
D.Strings[3195]="……啊。"
D.Strings[3196]="快动手吧，肮脏的$r。$B$B<卡兰低下头，露出他粗壮的脖子。>"
D.Strings[3197]="我不是来伤害你的，卡兰。哥沙克派我来找你。他说你会告诉我关于公主的事情。"
D.Strings[3198]="一切都完了……"
D.Strings[3199]="我们还没有失去一切，卡兰！"
D.Strings[3200]="你看我像个傻子吗，$r？我可以签署她的死亡证明书！我为什么要信任你呢？"
D.Strings[3201]="因为你还活着，我的手也没有卡在你结实的短脖子上。"
D.Strings[3202]="<卡兰叹了口气。>$B$B我想……我想你是对的。$B$B哥沙克告诉我你的酋长有个大计划，一个可能会改变联盟和部落关系的计划。关于这点你知道些什么？"
D.Strings[3203]="没什么。我的任务是跟你谈谈，然后回去找萨尔。萨尔对营救公主的事情很有兴趣。"
D.Strings[3204]="那么听好了，$c。$B$B几个月前，湖畔镇的镇长派遣特使来到铁炉堡，恳求国王一同抵抗入侵赤脊山的黑石兽人。$B$B铁炉堡公主茉艾拉自愿前去援助，于是国王就指派了20个精英守卫，确保公主由洛克湖前往湖畔镇的途中一路平安，我也在卫队中。"
D.Strings[3205]="这就解释了你被关在黑石山下的囚房里的原因，是吧，矮人？"
D.Strings[3206]="<卡兰清了清喉咙。>$B$B我们艰难地穿过灼热峡谷的隧道，进入了这片饱经蹂躏的荒地。现在回想起来，这事情十分蹊跷。我们所遇到的危险只不过是在这个地区生存的一些野生动物，我们很容易就赶走了它们。$B$B我们轻松地抵达了黑石山，并毫不费力地穿过了这座由巨石砌成的堡垒。"
D.Strings[3207]="在我们穿越燃烧平原时遭到了敌人的伏击，有上百个黑铁矮人！他们从城墙内、平原上的岩石后面、还有岩石的裂缝中突然出现。他们包围了我们，很快就解决了那些答应帮助我们完成任务的英雄和守卫。$B$B很明显：这是一次早有预谋的伏击。他们似乎知道我们的每一步计划……"
D.Strings[3208]="你怀疑某个内部人员与此有关？向敌方泄密？"
D.Strings[3209]="还会有别的原因导致这种结果吗？一定是有人向黑铁矮人告密了。$B$B<卡兰在你面前挥舞着拳头。>$B$B帮帮我吧，如果我能离开这里，我发誓一定会把那个叛徒抓出来的。"
D.Strings[3210]="请继续讲你的故事。"
D.Strings[3211]="我说到哪里了？哦，对，我们被抓住了。我的伙伴被当场处死。他们没有杀我，但用山羊把公主带走了。我被带到了熔渣之池的拘留所，然后又被转送到了这座监狱里。$B$B也许他们是想用我这条可怜的小命勒索一笔赎金。或者他们只是想让我永远回忆那些缭绕在我脑海里的残酷事件。悔恨是最残忍的狱卒，$c。"
D.Strings[3212]="她现在就在索瑞森大帝身边。他对她施加了某种可以改变思维的强大法术……而我只能待在这儿，束手无策。"
D.Strings[3213]="我会把门开着的，你怎么逃出去是你的问题。再见，卡兰。"
D.Strings[3214]="%s在她面前握紧逃脱符文。"
D.Strings[3215]="只有傻子才敢侵犯我的巢穴。"
D.Strings[3216]="我让你看看我的能力的证明，塞勒斯。"
D.Strings[3217]="塞勒斯，我没有任何证据。"
D.Strings[3218]="<塞勒斯的眼睛熠熠生辉>$B$B我是囫囵吞了你呢，还是放你一条生路？$B$B或许你还有些用处……$B$B向我的奴仆发出挑战吧，$c。生存下来，并把你获胜的证据交给我。"
D.Strings[3219]="一个卫士倒下了！"
D.Strings[3220]="保持警惕，你们这些没用的东西！"
D.Strings[3221]="我准备好了！"
D.Strings[3222]="咕噜……咕噜……"
D.Strings[3223]="去大树以西的暗巷区中心寻找耶尔玛克药剂店。"
D.Strings[3224]="如果耶尔玛克认为你有能耐的话，他会教你配制药水的。去暗巷区中心的商店找他吧。"
D.Strings[3225]="跟燃烧的铁砧的萨鲁·钢怒谈谈。沿着红石谷矿业工会右边的道路走到尽头，去那的荣誉谷找他吧。"
D.Strings[3226]="或许有一天萨鲁·钢怒会教你学会制作一把质地精良的斧头。沿着红石谷矿业工会右边的道路，到荣誉谷的“燃烧的铁砧”店里去找他吧。"
D.Strings[3227]="扎姆沙在暗巷区上层的博斯坦的火坑。当你从力量谷进入暗巷区时走左边的楼梯。"
D.Strings[3228]="咕噜……"
D.Strings[3229]="你肯定会想从扎姆沙那里学些什么的。当你从力量谷进来的时候走左边的楼梯到暗巷区上层的博斯坦的火坑去。"
D.Strings[3230]="%s闻了闻诱饵。"
D.Strings[3231]="古丹的符文工艺店就是你要去的地方。到暗巷区的西端可以找到，就在智慧谷的旁边。"
D.Strings[3232]="你能给我的斧头附魔吗？我需要永久性的。或许晚些。到智慧谷附近的暗巷区西端找到古丹的符文工艺店。"
D.Strings[3233]="%s开始贪婪地吞嚼诱饵。"
D.Strings[3234]="阿诺克能制作很好的绷带。他住在精神山谷灵魂归宿旁边的湖畔，就在适者生存小屋。沿着力量山谷向西走便可抵达。"
D.Strings[3235]="我猜有人在战斗结束后需要帮我们这些战士包扎伤口。到精神谷的灵魂小屋旁边的适者生存小屋找阿诺克。往上走去力量谷的西边找到一个湖。那就是他呆的地方。"
D.Strings[3236]="鲁玛克……总是在荣誉谷的湖边钓鱼。你找到他后，顺便帮我向山吉斯问好。"
D.Strings[3237]="钓鱼是那些没有在战斗中死去的老人的运动！到荣誉谷的湖边可以找到鲁玛克。"
D.Strings[3238]="草药……你需要前往暗巷区，去加迪的植物园找她谈谈。在智慧谷阿索兰的市场后面有木制的阶梯。沿着阶梯可以到达暗巷区的上层。"
D.Strings[3239]="到暗巷区的科多兽皮工店那里去。问问卡洛雷克。"
D.Strings[3240]="你要找科多兽皮工店是吧。去暗巷区中心吧。"
D.Strings[3241]="到暗影裂口去找赞杜沙。有许多隧道直通那个洞窟，有一个就在智慧谷的南面而另一个在暗巷区。"
D.Strings[3242]="你有一个宝箱？让我看看！好吧，在暗影裂口找到赞杜沙。找到通往暗巷区的通道然后就可以找到他。"
D.Strings[3243]="到荣誉谷的湖泊的东北方找红石谷矿业工会。与那里的马卡鲁谈谈。"
D.Strings[3244]="马卡鲁整天都在荣誉谷的红石谷矿业工会，就在湖边。"
D.Strings[3245]="苏尔德将教你如何练习技能。去暗巷区的科多兽皮工店找他吧。"
D.Strings[3246]="你希望利用这些尸体以表示对它们的尊敬，这很好。去暗巷区中心的 科多兽皮工店找苏尔德吧。"
D.Strings[3247]="我喜欢吃生食，但是要是你想吃熟食，德尼卡可以教你如何生火。去适者生存小屋，就是灵魂小屋附近湖畔边的那件房间里可以找到她。先往上然后往力量谷的西边走就可以到了。"
D.Strings[3248]="德尼卡能教你如何保持温暖。去适者生存小屋，就是灵魂小屋附近湖畔边的那件房间里可以找到她。先往上然后往力量谷的西边走就可以到了。"
D.Strings[3249]="玛加尔的玛加尔布品店在暗巷区里。去科多兽皮工店旁边的大树南边就可以找到他。"
D.Strings[3250]="布衣！？那不会帮你抵挡住好钢做成的武器的！哈，如果你确定你想当个裁缝的话到暗巷区的玛加尔布品店那儿去吧。"
D.Strings[3251]="在荣誉谷的猎人大厅南出口可以找到西姆拉。"
D.Strings[3252]="幸运的是这里有人会使用跟踪！到荣誉谷的猎人大厅可以找到西姆拉。"
D.Strings[3253]="我们有自己的职责，$c。对部落应尽的职责。"
D.Strings[3254]="督军克罗姆扎在哪里？"
D.Strings[3255]="我听到他来了！朝西看！"
D.Strings[3256]="奥格瑞玛银行在力量谷那里。去主城门以北的地方找找吧。"
D.Strings[3257]="到力量谷去，在飞行塔的南面就是奥格瑞玛银行。"
D.Strings[3258]="到力量谷的飞行塔顶部可以找到双足飞龙管理员。多拉斯会确保你到达你想要战斗的地方。"
D.Strings[3259]="你认为双足飞龙管理员会在哪儿？到力量谷的飞行塔的顶部去！"
D.Strings[3260]="你在寻找部落大使馆里的乌特伦。在力量谷的西边你可以找到他。"
D.Strings[3261]="部落大使馆位于西边的力量谷。"
D.Strings[3262]="旅馆位于主城入口以北，力量谷右边的第二幢建筑物。和旅店老板格雷什卡谈谈。"
D.Strings[3263]="去力量谷寻找旅店老板格雷什卡。她的旅馆主城门以北东侧的地方。"
D.Strings[3264]="你会在力量谷中央的奥格瑞玛银行外面找到它们中的一个。"
D.Strings[3265]="你可以在力量谷中部的银行外面找到接收你情书的地方。"
D.Strings[3266]="到荣誉谷的猎人大厅去，它就位于就在大剧场的西边。与那里的奥玛克谈谈。"
D.Strings[3267]="你的目标位于荣誉谷西北角。你会在那儿发现猎人大厅的。"
D.Strings[3268]="往上走去力量谷以西，去精神谷的黑石南小屋找皮菲瑞多谈谈。"
D.Strings[3269]="什么，你找不到那里？到精神谷湖里的黑石南小屋去，就在力量谷往上靠西的地方。"
D.Strings[3270]="萨尤斯与他的牧师在精神谷那的灵魂小屋里。去力量谷上方西侧的湖泊那里可以找到他。"
D.Strings[3271]="治疗技能是给那些无法忍受痛苦的人学习的。如果你一定想学习的话，就去力量山谷上面以西的精神谷找灵魂归宿吧。"
D.Strings[3272]="你想找的是卡德里斯。她和其余的萨满正在智慧谷萨尔的要塞的入口房间那里。"
D.Strings[3273]="你的搜寻基本结束了。到智慧谷的萨尔的要塞入口房间里找寻真知吧。"
D.Strings[3274]="想找迅影兄弟会的申苏尔，是吗？去暗巷区，过了杜佛斯回收店之后就可以找到通往暗影裂口的通道。"
D.Strings[3275]="别让我发现你盗窃了任何东西！去暗影裂口地下寻找申苏尔以及他的 迅影兄弟会。在智慧谷以南能找到通向那儿的通道。"
D.Strings[3276]="你在寻找格罗达尔和暗火营地？在被称作暗影裂口的地下洞穴里找到他们。有两条通道可以进入洞穴，一条在智慧谷的南面，另一条在暗巷区里面。"
D.Strings[3277]="去荣誉谷的勇者大厅找格雷兹·怒拳谈谈。并代我向他问好！"
D.Strings[3278]="到荣耀谷去找到勇者大厅并与格雷兹·怒拳谈谈。告诉他们我在这里的轮岗结束后就会去向他们汇报。"
D.Strings[3279]="你迷路了？"
D.Strings[3280]="什么！？"
D.Strings[3281]="请不要打扰古老的灵魂。"
D.Strings[3282]="很少有人能找到我……我能为你做什么吗？"
D.Strings[3283]="我已经把我所有的知识都教给你了，$n。祝你好运。"
D.Strings[3284]="我要怎样才能得到灵根草呢？"
D.Strings[3285]="呵呵呵呵……你是个相当好奇的家伙，不是吗，$n？嗯，我来告诉你该怎么做。$B$B在此地以北的古老废墟中居住着一个名叫米布隆·乱齿的令人厌恶的豺狼人。他日夜守护着灵根草，好像从不睡觉似的！$B$B你必须把他引开才行。我可以卖给你一些他喜欢吃的东西——把食物放在他附近，引他过来，然后你就可以趁机拿走灵根草啦。祝你好运！"
D.Strings[3286]="来试试看吧！"
D.Strings[3287]="沃弗克"
D.Strings[3288]="贝瑟克"
D.Strings[3289]="尤格尔"
D.Strings[3290]="希姆雷尔"
D.Strings[3291]="奥弗加特"
D.Strings[3292]="佩沃尔"
D.Strings[3293]="%s丝毫不理会门口的障碍物，眼睛直勾勾地盯着诱饵。"
D.Strings[3294]="%s击打自己的胸口，大声呼救！"
D.Strings[3295]="%s爆裂，喷发出大块的酸性粘土！"
D.Strings[3296]="我就知道这次能成功……"
D.Strings[3297]="这将会是我最成功的试验！"
D.Strings[3298]="现在，要是我加入这些黄色的……"
D.Strings[3299]="我知道这次会成功的……我以前的13次尝试只不过是练习罢了！"
D.Strings[3300]="啊……我的实验似乎从来没有成功过。或许我该从头再来。"
D.Strings[3301]="我想购买更多的萨伦迪斯种子。"
D.Strings[3302]="%s开始把不同颜色的水晶拼凑起来。"
D.Strings[3303]="我想……我想这次起作用了！"
D.Strings[3304]="没错，但是如果你精通草药学的话，你会发现它更有用！你可以培育出特别的草药来。虽然常青袋是个连新手都能轻松使用的工具，但那些对草药学有天资的冒险者将会得到更丰硕的报酬。"
D.Strings[3305]="你好，$c。我这个羽月要塞的仆人可以为你做些什么呢？"
D.Strings[3306]="啊，又错了！"
D.Strings[3307]="哦，好吧……或许下次可以。"
D.Strings[3308]="站直了！你的软弱令我恶心！"
D.Strings[3309]="保持警惕！兽人和他们的同伙过来了！"
D.Strings[3310]="表现得凶猛一些！你是科卡尔部族的成员，就得有科卡尔部族成员的样子！"
D.Strings[3311]="我们肉体的死亡标志着我们灵魂和神圣使命的重生。"
D.Strings[3312]="我是七贤中的一个，而守护这里是我们永远的诅咒。永远。"
D.Strings[3313]="去找我们的领袖杜姆雷尔发出挑战吧。"
D.Strings[3314]="我永远都不能再触摸石头了。我永远都无法再体会钢铁的荣誉了……"
D.Strings[3315]="你不能通过。你不是我们的人，也没有发出过挑战。"
D.Strings[3316]="挑战炎魔之王的下场就是我们现在的样子。"
D.Strings[3317]="我们的惩罚也是我们的祝福。"
D.Strings[3318]="你的奴役结束了，杜姆雷尔。我向你挑战！"
D.Strings[3319]="旅店"
D.Strings[3320]="你对七贤发出了挑战，死吧！"
D.Strings[3321]="杜姆雷尔，告诉我你的秘密！"
D.Strings[3322]="你想要学习这项古老的手艺？你希望冶炼黑铁？$B$B给我一样祭品我就会考虑的！"
D.Strings[3323]="你的意志很坚强，而且你的意图很明显。$B$B可能你的确有资格……"
D.Strings[3324]="我已经把你要的都给你了，格鲁雷尔。现在，告诉我你的秘密！"
D.Strings[3325]="你表明了自己的愿望，也支付了珍贵的石头。我会教你的……"
D.Strings[3326]="我知道怎么走，蠢货，你没必要像赶牛那样鞭打我吧？"
D.Strings[3327]="你显然很明白自己无法从这场袭击中逃生。他们是冲我而来的，你将为自己的傲慢付出代价。"
D.Strings[3328]="兄弟们，超过他们！"
D.Strings[3329]="我想下次你遇到我的兄弟时可能就没这么幸运啦。"
D.Strings[3330]="他们是冲你而来的，蠢货！"
D.Strings[3331]="蠢货，你们还以为自己成功了吗？即使在现在，黑石军队也在准备着摧毁你们的世界。"
D.Strings[3332]="黑龙来了，准备受死吧！"
D.Strings[3333]="最可怕的噩梦还没降临呢！"
D.Strings[3334]="蠢货，等死吧。"
D.Strings[3335]="科卡尔部族将统治世界！"
D.Strings[3336]="你们$r对于科卡尔部族来说什么都不是！"
D.Strings[3337]="颤抖吧！我来了！"
D.Strings[3338]="科卡尔部族是最强大的！"
D.Strings[3339]="%s屈服了。"
D.Strings[3340]="你们这些两条腿的蠢货！我的孩子都可以打败你们！"
D.Strings[3341]="我在这儿！你对这片大地的统治已经结束了！"
D.Strings[3342]="保卫碉堡！"
D.Strings[3343]="入侵者在这儿！"
D.Strings[3344]="小心！科卡尔半人马开始攻击了！"
D.Strings[3345]="我们的敌人必将败北！"
D.Strings[3346]="小心，$n！看西边！"
D.Strings[3347]="你想玩玩吗？那就来吧！"
D.Strings[3348]="跪下，格拉克。"
D.Strings[3349]="格拉克·洛克鲁布，你被判对部落犯有叛国罪。你如何辩护并不重要。大执行官努兹拉克，站出来。"
D.Strings[3350]="%s对着格拉克扬起巨大的斧头。"
D.Strings[3351]="了结他……"
D.Strings[3352]="%s举起斧头砍了下去。"
D.Strings[3353]="你，立刻去卡加斯报告！"
D.Strings[3354]="离那些酒桶远一点！"
D.Strings[3355]="我……我真的不知道自己是怎么到那儿的……$B$B我依稀记得用的是……木筏……$B$B"
D.Strings[3356]="你会为此付出代价的！"
D.Strings[3357]="付钱给我，我就说……$B$B哦，是你，$n！别介意……"
D.Strings[3358]="你听说过我的名字吗？或许我们俩很早就相识了……$B$B我认为我得名于某个重要人物……"
D.Strings[3359]="嗨！很高兴你回来啦，$n。告诉我，你完成我给你的第一项任务了吗？如果完成了，我会给你第二项任务的……"
D.Strings[3360]="我在火山口游荡了许久，后来我想起曾有人告诉我……“继续往前，到山上去。”这个声音在我的脑海中出现。$B$B听了这话之后我就来到了这里，$n！"
D.Strings[3361]="很久之前，在我的旅途之中，我遇到了一个人，他告诉我：“掌握它的使用方法，你就可以拥有它。”$B$B你觉得那是什么意思？那时我还不知道，而且现在我还是不知道，真的……"
D.Strings[3362]="对任何人而言……包括我，这都是一个秘密！$B$B很高兴你找到了我——我没躲藏在树丛中或是岩石下，挺幸运的，是吧？"
D.Strings[3363]="谢谢你，$n！你是安戈洛环形山的英雄！"
D.Strings[3364]="拉格纳罗斯将拥有至高无上的统治权！"
D.Strings[3365]="喝点东西吧，$c。这可能是你最后一次喝东西啦！"
D.Strings[3366]="要不是因为这酒吧，我的空闲时间就只能用来剥龙鳞啦。"
D.Strings[3367]="水元素正在跟火元素交战，也就是说他们也在跟我们作战。他们的领袖之一的海达克希斯正在召集士兵……"
D.Strings[3368]="啊，真悬，我以为自己这次铁定玩完了。呃……还是有点晕……"
D.Strings[3369]="我听说水元素中的贵族海达克希斯发动了对火元素的战争。真希望他战败！"
D.Strings[3370]="海达克西斯公爵躲到了艾萨拉风暴海湾的某个岛屿上。那些家伙能有什么威胁？"
D.Strings[3371]="我喜欢你思考的方式！我们走吧！"
D.Strings[3372]="要是海达克西斯招募了新兵，就可能使双方的力量对比发生变化……"
D.Strings[3373]="枪炮与硝烟弥漫，直到某一方被摧毁。"
D.Strings[3374]="好吧，我想我自己可以照顾自己了。我不认识你……但是我欠你一个人情。谢谢你！"
D.Strings[3375]="我父亲告诉我：有一天，会有一个陌生人跟我交谈，我必须控制住自己，不能杀了$g他:她;。"
D.Strings[3376]="勇敢的$c，欢迎来到石槌要塞。我能帮助你吗？"
D.Strings[3377]="你好，$c。如果你在寻找皮革制品和制皮物资的话，来问我这个半退休的圣骑士就算是找对人了。"
D.Strings[3378]="看来你需要通过无尽之海的通道。那你算来对地方了，这儿就是少女之爱号的停泊处，她是这片水域上最好的客船。当船到达后，你就登上甲板，然后用不了多久你就可以躺在荆棘谷的沙滩上晒太阳了。"
D.Strings[3379]="我必须承认，藏宝海湾有南海最好的杂烩蚌肉。哦，对烹饪不感兴趣？那么欢迎你投宿少女之爱号——在东部王国和卡利姆多之间航行的最好的客船。很快她将驰往棘齿城，在她到达之前好好享受吧。"
D.Strings[3380]="入侵者！！"
D.Strings[3381]="你在干什么？你这个入侵者！！"
D.Strings[3382]="氦弹点火和爆炸的过程是没有危险的。跟船只相比，这宝贝能更为快速安全地将你送达幽暗城，途中的景色真是惊心动魄。说到这，在地精飞艇上是不允许吸烟的，旅途中也不允许使用火的法术。"
D.Strings[3383]="你好！你正是我要找的人。坐下来听我说，我有个可以让咱们两个都发家致富的计划！"
D.Strings[3384]="我兄弟说我们能在这条商贸路线上赚到更多的钱的，但是他没告诉我要独自应对。要是你乘坐地精飞艇沿着这条路返回的话，你能帮我带点吃的吗？在奥格瑞玛，有人出售最好的肉类，当然我还能以那些苟延残喘的动物为食的。"
D.Strings[3385]="希望这能起作用！"
D.Strings[3386]="%s把薄雾喷到了血瓣花的萌芽上。"
D.Strings[3387]="看着他们离开！"
D.Strings[3388]="%s看到那些家伙仓惶逃走，大笑起来。"
D.Strings[3389]="到出发的时间了！来吧！<替换这个>"
D.Strings[3390]="你的族人问了声好，雷布里。他们想要你彻底失败！"
D.Strings[3391]="你干什么都不成，雷布里。现在该为你的邪恶付出代价了！"
D.Strings[3392]="不！滚开！帮帮我！！"
D.Strings[3393]="去红石谷矿业工会东北部的荣誉谷找诺格机械店。"
D.Strings[3394]="你会在荣誉谷找到那个地精和他的玩具商店的。"
D.Strings[3395]="帮我挑选一下吧。"
D.Strings[3396]="我是一名拥有强大力量的法师，一直以来，我都潜心研究精神和记忆，这有利于学习知识和保持学会的知识。要不是我在夜晚听到一个巨大的声音说需要我的帮助，我的研究一定已经完成啦。我只在这儿呆一会儿，免费为你重修天赋。接着我就得离开，而你也要选择自己的道路。"
D.Strings[3397]="没问题！"
D.Strings[3398]="马上就来了！"
D.Strings[3399]="宝贝，我马上就过来……"
D.Strings[3400]="好的，$g先生:女士;。"
D.Strings[3401]="嘿，娜玛拉！来一杯黑铁啤酒怎么样？"
D.Strings[3402]="娜玛拉！还有羊肉吗？"
D.Strings[3403]="小姐，请你告诉普拉格，我想要更多的啤酒。这些远远不够！"
D.Strings[3404]="嘿，我说，娜玛拉，你能切给我一块吗……"
D.Strings[3405]="我想进行烹饪训练。"
D.Strings[3406]="你好，$n。如果你想学习烹饪技巧的话，可以随时来找我。"
D.Strings[3407]="<普瑞斯托女士怒视着你。>"
D.Strings[3408]="普瑞斯托女士，请原谅我的冒昧，但是伯瓦尔·弗塔根公爵让我来寻求您的建议。"
D.Strings[3409]="我就站在你旁边，笨蛋。我知道你在找什么。"
D.Strings[3410]="很抱歉，普瑞斯托女士。"
D.Strings[3411]="你是说为了满足一个妄想狂的地方官和一群没准正在遭受中暑之苦的乌合之众的愿望，我们就得把世界各地的部队都调回来，然后给他派过去吗？"
D.Strings[3412]="普瑞斯托女士，请你原谅。这并非我的本意。"
D.Strings[3413]="当然不是，亲爱的$g小伙子:姑娘;。你这种“冒险者”类型的$c经常成为政治的牺牲品，被政治家玩弄于股掌之间而毫无察觉。$B$B我给你的建议，就是去做一些更加具体的事情：找份新工作。$B$B这个世界已经有太多的英雄了。"
D.Strings[3414]="普瑞斯托女士您费时了，谢谢你。"
D.Strings[3415]="%s变得晕乎乎的！"
D.Strings[3416]="%s喝醉了酒，射偏了一发暗影箭！"
D.Strings[3417]="嗨，罗克诺特！"
D.Strings[3418]="我们走吧，宝贝。"
D.Strings[3419]="%s吻着她的情人。"
D.Strings[3420]="%s亲吻着娜玛拉小姐"
D.Strings[3421]="请帮助我穿越这片被诅咒的森林，$r。"
D.Strings[3422]="这个地区的堕落使得森林中的所有生物都受到了影响，$n。请做好战斗准备。"
D.Strings[3423]="你想要什么？*嗝儿*"
D.Strings[3424]="约翰，我有公务在身。我需要一切有关温德索尔元帅的信息。你最后一次见他是什么时候？"
D.Strings[3425]="我必须跟同族作战，这令我非常伤心。"
D.Strings[3426]="温德索尔那天特别爱跟人争吵——相信我，对温德索尔来说，那是一个有纪念意义的伟大成就。他一直在跟我说“感觉有些怪异”。他不是在开玩笑！$B$B当那些肮脏的野兽出击时，我们还在黑石山脉的中央。当然，我指的是兽人。你别分神，好吗？一时之间，叫喊声和铁器的敲击声四起。"
D.Strings[3427]="我单挑50个兽人？我可不是傻子，$n。我爸爸常说“卑鄙是卑鄙者的通行证”这类的话，我突然之间就明白了那是什么意思。"
D.Strings[3428]="矮人，脑子放清醒点。我可没问你什么老爹啊名誉啊之类的事儿。"
D.Strings[3429]="好吧，好吧。总之，从某种意义上说，我退到了一个不起眼的角落里。$B$B温德索尔似乎并不安分，看看他那歇斯底里的样儿。他拿着反对者战锤没命地乱挥，像发了疯一样对兽人咆哮着。"
D.Strings[3430]="反对者？"
D.Strings[3431]="嗯。你从来没有听说过反对者？那把传说中的令兽人闻风丧胆的战锤？对，对，那是温德索尔的锤子。他说是弗兰克罗恩·铸铁亲自为他伟大的父亲制造了那把锤。弗兰克罗恩·铸铁，就是那个建造了巨石水坝之类的……黑铁矮人。他还说有一把与反对者一起铸造出来的战锤被弗兰克罗恩自己留着用了。他好像叫它铁胆之锤什么的。"
D.Strings[3432]="真有趣……继续。"
D.Strings[3433]="我说到哪里了？哦，兽人突袭了温德索尔，温德索尔呢？他是山崩于前而面不改色，从容应对。只见反对者击起冲天血光，鲜血四溅，持续了数个小时，没准是数天。我记不得了。但是最终，杀戮停止了。"
D.Strings[3434]="温德索尔就那样死了……"
D.Strings[3435]="死了？你在开玩笑吧，$n？搞清楚，$n$g先生:小姐;！温德索尔绝对不会死于区区50个兽人之手，这就跟塞尔萨玛血肠是世界上最美味的食物一样不容置疑，他被兽人层层包围，但是他确实还活着……而且他非常非常愤怒。"
D.Strings[3436]="他是怎么死的？"
D.Strings[3437]="你为什么总说他死了？谁告诉你他死了？我从来都没那么说过。$B$B他只是不知去向而已。$B$B你看，很明显，我们已经卷入了某个兽人对抗黑铁矮人的战争中。兽人是一群肮脏又卑劣的杂种，他们设计了一些圈套和你可能永远搞不明白的邪恶装置！"
D.Strings[3438]="我现在能看到了，$n。灰谷就在前方！"
D.Strings[3439]="好吧，他到底在哪儿？等一会！你喝醉了吗？"
D.Strings[3440]="矮人可不会喝醉，$g先生:小姐;。我只是有些邋遢。$B$B无论如何，温德索尔？我猜他在黑石深渊的某处。对你们这些未受教化的家伙来说，就是一座黑铁矮人的城市。"
D.Strings[3441]="我觉得……有些奇怪……"
D.Strings[3442]="他为什么在黑石深渊？"
D.Strings[3443]="放慢速度！就快接近了！$B$B他在那儿，全身血肉模糊，连内脏都流出来了，是谁把他弄成这样的？$B$B黑铁矮人！你记得我说过的话吗？？$B$B嗯，黑铁矮人比黑石兽人更为狡猾。他们是有备而来的。人数有300之多……*嗝尔*。"
D.Strings[3444]="$n，我的体形改变了！我的灵魂力量正在回到我的体内……这座森林的诅咒正在从我身上消失……"
D.Strings[3445]="300？那么说黑铁矮人杀死了他，并把他拖到了深渊里？"
D.Strings[3446]="$n$g先生:女士;，如果我不是很了解你的话，我就会以为你也是那些穴居人中的一员。$B$B黑铁矮人没有把温德索尔怎么样，毕竟他的老祖父的最好最好的朋友就是一个黑铁矮人，这可能也就是黑铁军队到现在还没把他干掉的原因。"
D.Strings[3447]="你的知识太缺乏了。当你熔炼技术更成熟些时再来找我！"
D.Strings[3448]="你可以走了……我希望在我生命的最后一刻独自待着。"
D.Strings[3449]="啊……反对者。"
D.Strings[3450]="最后！用手指堵住你的耳朵，你的脑子有可能会变得有五倍大，事实上，我甚至担心你的脑子会泄出来。$B$B那么，黑铁矮人们饶了他的性命，但把他囚禁了起来。他们的首领，某个叫做索什么森的妄自尊大的，愚蠢的，自负的家伙，把反对者留作己用。那是我最后一次见到温德索尔了……*嗝儿*"
D.Strings[3451]="谢谢你，$n。我的灵魂终于得到了安宁。"
D.Strings[3452]="费伍德森林的堕落禁锢了我的灵魂……我也许永远都得不到安宁……"
D.Strings[3453]="谢谢你，约翰。你的故事振奋人心，使我受益匪浅。"
D.Strings[3454]="欢迎来到我们的酒店！"
D.Strings[3455]="为什么你跟罗克诺特不去找个二人天地呢……"
D.Strings[3456]="好主意！"
D.Strings[3457]="再次感谢你，$n。罗克诺特和我非常合得来！"
D.Strings[3458]="如果你要到黑石深渊去，就来找我谈谈。或许我会有些工作要交给你。"
D.Strings[3459]="%s看上去很疲倦。他打着哈欠，躺在A-Me 01旁边。"
D.Strings[3460]="%s在A-Me 01旁边蜷缩着睡去，大声打鼾。"
D.Strings[3461]="你见过安戈洛环形山的所有奇景了吗，$n？真是令人惊讶。虽然它们没有我制造出的东西那样精密，但这里所有的东西都是天然而成的……这就真是太奇特了。$B$B我的叔叔雷塔维就喜欢这样的地方。我正沿着他的脚步前进——我还想从灭绝的文明中找到新的知识！"
D.Strings[3462]="嗯，我没有任何秘银外壳。我尽力了。只要有那个就可以修理A-Me 01了吗？哦，太好了！$B$B秘银外壳并不是很难找到。只需请一个技艺高超的技师为你制造一个就可以了。我想那可能需要几块秘银，但是如果你能帮我，我保证你会得到丰厚奖赏的！"
D.Strings[3463]="你有秘银外壳吗？"
D.Strings[3464]="你一定要尝一下我们的黑铁啤酒。我听说附近的矮人总是有多少喝多少。"
D.Strings[3465]="我的主人普拉格是个不错的老板，而且他赚了很多钱。他的钱包都快要被撑破了！"
D.Strings[3466]="这是用钱能够建造出的最好最先进的交通工具。什么？矿道地铁？侏儒？听着，朋友，如果你相信那种废物的话，我就把荆棘谷中的那尊雕像卖给你。那么，你到底是要走着去格罗姆高营地，还是乘坐这架精美的飞行机器？你选吧。"
D.Strings[3467]="你在那儿做什么？"
D.Strings[3468]="不许偷盗货物！"
D.Strings[3469]="嘿！住手！"
D.Strings[3470]="法拉克斯，我想你需要好好教训一下这些家伙。"
D.Strings[3471]="你是一个威胁！"
D.Strings[3472]="我会重生的！伊森迪奥斯会从这些灰烬中将我复活的！"
D.Strings[3473]="你完了！"
D.Strings[3474]="我不会死掉！以拉格纳罗斯的意愿为名，我会重生的！"
D.Strings[3475]="A-Me操作。A-Me回家。你对A-Me说，要他改变运动设置。"
D.Strings[3476]="好……很好，A-Me。A-Me好。家。找到家。"
D.Strings[3477]="帮帮我！$n过来了！"
D.Strings[3478]="帮我对付这个$n！"
D.Strings[3479]="你喝过雷霆啤酒吗？那可是好东西！"
D.Strings[3480]="我一个小时以后还要去值班，但在那之前……干杯！"
D.Strings[3481]="你在看我吗，$g小伙子:姑娘;？"
D.Strings[3482]="我要来一杯黑铁啤酒。哦，你不是侍者？"
D.Strings[3483]="我认为普拉格把桶装得太满了。你瞧，简直都要炸开了！"
D.Strings[3484]="在我参加聚会时别骚扰我……"
D.Strings[3485]="你需要指引吗，$g小伙子:姑娘;？"
D.Strings[3486]="我喜欢清晨的铁炉堡的气息！嗯？你需要什么吗，$c？"
D.Strings[3487]="假如他们说……假如！对铁炉堡来说没有假如！嗯？现在情况如何？"
D.Strings[3488]="铁炉堡银行"
D.Strings[3489]="你有需要保管的财宝吗？去找铁炉堡银行的石衣兄弟吧。\n\n从铁炉堡的入口往东北方向走，银行就在那边。"
D.Strings[3490]="银行？哦，你是说银行！说到存储贵重物品的话，没有什么比银行更安全的地方了。它就在铁炉堡大门的东北方。"
D.Strings[3491]=S[16599]
D.Strings[3492]="想要乘坐狮鹫，是吗？你得去找格莱斯·瑟登。\n\n你可以在铁炉堡中心的大锻炉东边找到他。"
D.Strings[3493]="啊，没有什么比狮鹫更好的坐骑了。暗夜精灵偏爱可笑的角鹰兽，而我只需一头狮鹫就可以穿梭在云端！\n\n好吧，我不跟你唠叨了，到大锻炉东边的格莱斯·瑟登那儿去吧，他会向你出租狮鹫的。"
D.Strings[3494]="要是你想组建公会的话，那你首先需要通过铁炉堡访客中心的乔多·钢眉的认同。穿过铁炉堡大门往东南方向走，你就能找到他。"
D.Strings[3495]="旅馆？啊，你是来寻找铁炉堡出产的美酒的？你该去石火旅店。$B$B如果你在铁炉堡之外，它就在铁炉堡大门的左边；反之，则在大门右边。"
D.Strings[3496]="要是你要找旅馆的话，石火旅店是个不错的选择。若是你前往铁炉堡的话，会在城门的左边找到这个旅馆；要是在铁炉堡里面的话，它就在城门的右边。$B$B哦，要是你现在就去那里的话，告诉他们为我准备好啤酒吧。"
D.Strings[3497]="你会在那边的石火旅店旁边找到一个邮箱。那就在铁炉堡大门的北面。"
D.Strings[3498]="几天前，我无意中听雷格努斯·雷石在武器大厅中吹嘘他兽穴中的一件新饰品。要是你想成为一名技艺纯熟的猎人，就去找他吧。"
D.Strings[3499]="秘法大厅的法师彬克也许能帮忙解决你的一些魔法需求。\n\n秘法大厅就在铁炉堡的北部。"
D.Strings[3500]="去铁炉堡大门以北的神秘大厅，你会在那儿受到魔法训练的。朱莉·雷线总是在那儿埋头苦读。"
D.Strings[3501]="啊，布莱纳·火崖。她能使用魔法。她主管牧师事务。\n\n你要穿过铁炉堡大门，向北走，前往神秘大厅。她就在那里。"
D.Strings[3502]="布兰度尔·铁锤就是你想找的人。你可以去铁炉堡大门以北的神秘大厅找他。"
D.Strings[3503]="啊，布兰度尔·铁锤。毫无疑问，他能为你提供指导，$g小伙子:姑娘;。在铁炉堡大门以北的神秘大厅中能找到他。"
D.Strings[3504]="为什么我们需要这样的服务？荒弃的洞穴的潜行者霍夫丹·黑须已经给我们惹了一大堆麻烦，我是不是还要留意你一下？"
D.Strings[3505]="所有的潜行者都居住在铁炉堡以北的荒弃的洞穴。我敢打赌芬斯维克也在那儿，正在数着偷来的钱包中的硬币呢。我总有一天会抓住他的！\n\n同时，我也会好好看着你的，$g小伙子:姑娘;。"
D.Strings[3506]="没有什么地方比铁炉堡最黑暗的荒弃的洞穴更适合寻找那些阴暗的家伙了。你在那里肯定会找到瑟斯哈特，就象是召唤一个行径卑劣的动物去照他的吩咐办事。"
D.Strings[3507]="哦！你想接受战士的训练，是吗？克斯塔姆·碎石会帮你实现梦想的！去铁炉堡大门东边的武器大厅吧。"
D.Strings[3508]="你想要炼金训练者吗？嗯，我刚从那儿过来呢，真的。你可以在侏儒的聚集地侏儒区找浆泡小姐。"
D.Strings[3509]="你在寻找一个炼金术老师是不是？我也刚从那里回来。你会在侏儒集会的工匠区找到浆泡小姐的。\n\n：：叹气：：……为什么我没有服下蓝色药剂呢。"
D.Strings[3510]="你算来对地方了，$g小伙子:姑娘;！人们从世界各地来此学习成为一名铁匠。你会看到本古斯·深炉在我们漂亮的城市中央的大熔炉的铁砧上埋头工作。"
D.Strings[3511]="一个烹饪培训师？那好吧，你到大熔炉东北方的铜壶铁罐店去。达瑞尔·瑞克努索会教你制作极好的菜肴，那肯定会让你获得新生的！"
D.Strings[3512]="啊，要是你想成为一名附魔师的话，我想你需要找吉布·草须。他在 大熔炉狮鹫管理人右边的商店草须魔法用品店里。"
D.Strings[3513]="你想学习工匠的手艺吗？那你就得去工匠区找宾斯匹德。\n\n从铁炉堡大门一直往正东方向走，或者朝着传来爆炸声的方向走。"
D.Strings[3514]="急救是一种有价值的技能。我们的常住的培训师，尼莎·火石，会教你该怎么做。到大熔炉南边的铁炉堡医师协会可以找到她。"
D.Strings[3515]="格瑞诺尔·石印会告诉你说他曾经碰到许多脱钩的超级大鱼，但他仍是附近最好的渔夫之一。他在荒弃的洞穴开有一家叫做旅行渔具店的商店。"
D.Strings[3516]="花和种子以及类似的东西？那是雷纳·石枝的专业领域。你能在大熔炉南面的铁炉堡医师协会处看到她料理她的植物。"
D.Strings[3517]="哦，你想学习采摘雏菊是吧？哈哈！我只是开个玩笑，$g小伙子:姑娘;。\n\n这是个很好的职业，雷纳·石枝会教你的。她在大熔炉南边的 铁炉堡医师协会工作。"
D.Strings[3518]="费布·钢轴在大熔炉西北面开了一家商店。我打赌他能教你学会制作精良的装甲。"
D.Strings[3519]="荒弃的洞穴的杜尔萨姆·格雷顿能教你开锁的种种技能。要是你明白我的意思，就别在铁炉堡练习这些技能。"
D.Strings[3520]="这儿有采矿训练者吗？你认为你在哪儿！？\n\n你将在大熔炉北边深山珠宝矿业协会找到丹莫罗地区最好的矿工。吉尔弗拉姆·石趾将为你展示真正的采矿艺术。"
D.Strings[3521]="巴尔萨斯·裂石是一名剥皮师，他会教你如何剥皮的。去大熔炉北边的皮甲用品店找他吧。"
D.Strings[3522]="特瑞莎·远山同样碰上了严峻的气候，但是她运用生存技能，以顽强的意志度过危机。\n\n如果你想找她谈谈，就去铁炉堡以南的军事区吧。"
D.Strings[3523]="约莫德·石眉对缝纫有独到之处，真的。如果你想接受训练的话，就去大熔炉北边的石眉布衣店找他吧。"
D.Strings[3524]="追踪？那么你得去拜访丹穆尔·远山。只有他能教你追踪的诀窍。\n\n出了铁炉堡大门往南走，去军事区找他吧。"
D.Strings[3525]="我要将我的精力集中在这把刀上。这样就能捕获与刀关联的更强的精神印象。"
D.Strings[3526]="我……我觉得我看够了……我已经筋疲力尽……"
D.Strings[3527]="我经受过痛苦，但是现在我能感觉到它正从我身上消退。我感到……自由了。"
D.Strings[3528]="安戈洛的水晶塔相当神秘。对这里少数的居住者来说，它们代表某种传奇，而其建造目的则更值得深思了。"
D.Strings[3529]="检查这座水晶塔。"
D.Strings[3530]="这座水晶塔似乎正在向另外某个地方传输数据。$b$b仔细地检查了这座塔之后，你发现了一个由蓝色、黄色和绿色水晶组成的图样，它们以一种特殊的形态排列着。$B$B一大圈蓝色水晶两侧分别有一小圈黄色水晶和另一圈绿色水晶。$B$B你仔细观察水晶的颜色，一定会有人对你的发现很感兴趣。"
D.Strings[3531]="这座水晶塔似乎正在向另外某个地方传输数据。$b$b仔细地检查了这座塔之后，你发现了一个由黄色、红色和绿色水晶组成的图样，它们以一种特殊的形态排列着。$B$B一大圈黄色水晶两侧分别有一小圈红色水晶和另一圈绿色水晶。$B$B你仔细观察水晶的颜色，一定会有人对你的发现很感兴趣。"
D.Strings[3532]="这座水晶塔似乎正在向另外某个地方传输数据。$b$b仔细地检查了这座塔之后，你发现了一个由红色、蓝色和绿色水晶组成的图样，它们以一种特殊的形态排列着。$B$B一大圈红色水晶两侧分别有一小圈蓝色水晶和另一圈绿色水晶。$B$B你仔细观察水晶的颜色，一定会有人对你的发现很感兴趣。"
D.Strings[3533]="A-Me回家！A-Me，好！回家。回家。回家。"
D.Strings[3534]="坏，$n。$n，坏！"
D.Strings[3535]="$n，不要伤害A-Me。A-Me，好。"
D.Strings[3536]="危险。危险！$n要伤害A-Me。"
D.Strings[3537]="A-Me，回家。A-Me，回家！$n，别阻止A-Me。"
D.Strings[3538]="把这个$n弄走！"
D.Strings[3539]="我需要帮助！"
D.Strings[3540]="$n在攻击我！救命啊！"
D.Strings[3541]="我想喝更多的啤酒！给我更多的啤酒！"
D.Strings[3542]="喝空的！！"
D.Strings[3543]="啊，又空了！"
D.Strings[3544]="啤酒！"
D.Strings[3545]="%s充满期待地看着你。"
D.Strings[3546]="我叫科琳，我实在没法告诉你我是怎么到这儿来的，但是我可以告诉你，这个营地现在就是我家了！$B$B我在这儿研究环形山里随处可见的奇怪水晶。你在来这里的路上一定已经看见不少这样的水晶了。你有没有拾取一些水晶？"
D.Strings[3547]="啊，太棒了！"
D.Strings[3548]="亲爱的艾露恩，感谢你让我摆脱了……那个！"
D.Strings[3549]="燃烧平原 - 七贤石板"
D.Strings[3550]="拓下石板上的文字。"
D.Strings[3551]="石板上的符号被小心翼翼地拓了下来……"
D.Strings[3552]="你好，$c。对于某些人来说，猎人是一种生活方式，是一种选定的职业。对于其他人来说，它是某种消遣，是勇气的象征，或是为了通过狩猎部族的仪式。$B$B对于我来说，种族和职业并不重要--我尊重的是你的灵魂和心智，而正是它们将要接受考验。当一个人独自面对自然的力量，竭力发挥其毕生所学之时，荣誉才会留下它真正的印记。$B$B如果你希望考验自己并赢得我的尊敬，那就跟我多谈谈。"
D.Strings[3553]="你正行进在一条光荣的道路上，$n。我的祖先尊敬你的意愿，但你在完成我所交付的任务之前我不会对你有任何认可的。$B$B如果你希望证明在精神层面是一个猎手的话你该知道你必须做什么。"
D.Strings[3554]="我和碎手都向你致敬，$c。$B$B别这么惊讶，$n。连奥格瑞玛最高的地方也会有阴影——一定有什么东西隐藏在那儿。碎手欣然接受了那项任务。萨尔也承认要确保兽人和巨魔的安全，他是不可缺少的。$B$B但是你到这儿来不是谈论我的事儿吧，你一定另有目的。"
D.Strings[3555]="安戈洛环形山在卡利姆多南部，位于塔纳利斯沙漠的西面。去寻找巨大的浮空石……它们是环形山入口的标志。但是要小心，那里可是很危险的，迅猛龙就在入口附近徘徊。"
D.Strings[3556]="安戈洛环形山在哪儿？"
D.Strings[3557]="谢谢你，现在我们能解开水晶和神秘的水晶塔的秘密了，$n。要是你需要更多信息，请随时回来找我！"
D.Strings[3558]="请告诉我关于东部水晶塔的事情。"
D.Strings[3559]="你所说的这个拉克维是谁？"
D.Strings[3560]="请告诉我关于北部水晶塔的事情。"
D.Strings[3561]="安戈洛的暴掠龙看起来与贫瘠之地的迅猛龙有些共同点--非常聪明，十分灵活，并且似乎具有着某种程度的行为智能，或者说遵循着某种行为准则。其中我所遇到的最强大的是拉克维。他是我所见过的最危险的动物之一。在牛头人语里，拉克维的意思是“锋利的爪子”，但这个名字并不足以恰如其分的描述他的可怕。$B$B如果你计划猎杀拉克维的话，千万不要低估他，但如果你决定要这样做，无论如何我都会帮你的。"
D.Strings[3562]="请告诉我关于西部水晶塔的事情。"
D.Strings[3563]="我把水晶塔使用手册弄丢了，能再给我一份吗？"
D.Strings[3564]="东方的水晶塔接受蓝色，黄色，还有绿色的水晶。$B$B它专注于使用蓝色水晶作为主要力量之源而产生的能量。有两种可能的效果：一种对精神有益，而另一种产生一种破坏性的护盾。$B$B精神水晶需要蓝色和绿色的水晶。这将会增加你的勇气。$B$B尖刺水晶需要蓝色和黄色的水晶。这会产生一个对攻击者造成伤害的护盾。"
D.Strings[3565]="北方的水晶塔接受黄红绿三种颜色的水晶构成。$B$B而关键是使用黄水晶所产生的能量作为主要的力量来源。有两种可能的效果：一种会制造破坏，一种会消除破坏。$B$B爆炸水晶需要红水晶和黄水晶。这将产生剧烈爆炸，足以震慑你的敌人。$B$B恢复水晶需要黄水晶和绿水晶。这将给你提供治疗光环。"
D.Strings[3566]="西方的水晶塔接受红色，绿色和蓝色的水晶。$B$B塔门关键是要用红色水晶作为力量源泉而产生的能量。可能有两种结果：一种能提高你的防御力，而另一种则是削弱敌人的防御。$B$B防御水晶需要红色和绿色的水晶。这将会使你的装甲更完备。$B$B破甲水晶需要蓝色和红色的水晶。这将会削弱即定目标的装甲防御。"
D.Strings[3567]="当然的事情，$n。还有一个给你。"
D.Strings[3568]="你在虫茧里看到了模糊的人体轮廓，你现在知道这就是你要找的地方了。虽然你认为自己可以打开虫茧，但即使你用尽全力，它还是紧紧地关着。"
D.Strings[3569]="%s攻击新的目标！"
D.Strings[3570]="拿你做个新帽子肯定不错，$r！"
D.Strings[3571]="奥格拉比斯需要新的帽子！"
D.Strings[3572]="谁胆敢进入我的房间！？"
D.Strings[3573]="啊，刚好赶上你的净化仪式，$c。我将清除你灵魂中的杂质。"
D.Strings[3574]="我亲爱的图比亚斯，是你吗？"
D.Strings[3575]="当我厌倦你时，或许奥格拉比斯会拿你的脑袋做一顶小帽子。"
D.Strings[3576]="这片美丽的森林受到了可怕的诅咒！腐化的力量将这儿变成了一片恐惧之地。如果你跟他们不是一伙的，或许你能帮助我夺回费伍德森林。"
D.Strings[3577]="我们行动吧。我的装备应该在这条路上的某个储物间里。"
D.Strings[3578]="“牛头人语？”$B$B牛头人德鲁伊满怀期望地看着你，但是你显然无法跟她沟通。她微笑着指向自己，然后指着你。最后她向南面的道路指了几下。$B$B或许她是在说那里有能跟你进行交谈的德鲁伊？"
D.Strings[3579]="检查那间牢房，$n。如果那里还有人活着，我们就得把他们救出来。"
D.Strings[3580]="“达纳苏斯语？”$B$B暗夜精灵德鲁伊满怀期望地看着你，但是你显然无法跟她沟通。她微笑着指向自己，然后指着你。最后她向北面的道路指了几下。$B$B或许她是在说那边有能跟你进行交谈的德鲁伊？"
D.Strings[3581]="谢谢你，$n！我自由了！！！"
D.Strings[3582]="救命！！！！"
D.Strings[3583]="你自由了，杜格哈尔！快出去！"
D.Strings[3584]="干得好！我们差不多成功了！这边走。"
D.Strings[3585]="没错，$n，我的东西都在那个房间里。保护我，我准备冲进去了！"
D.Strings[3586]="啊，它在那儿！"
D.Strings[3587]="你能感受到这力量吗，$n？让我们舞动起来吧！"
D.Strings[3588]="我们只需解放图比亚斯，然后就能离开这儿了。这边走！"
D.Strings[3589]="我终于可以离开这个垃圾场了！！"
D.Strings[3590]="是谁派你来的？"
D.Strings[3591]="出去吧，图比亚斯，你自由了！"
D.Strings[3592]="干得很好，$n。让我们去找出口吧。我想我知道该怎么走，跟着我！"
D.Strings[3593]="我从未喜欢过那两个家伙。我们继续前进吧。"
D.Strings[3594]="打开它，这次小心点！"
D.Strings[3595]="那个愚蠢的家伙真是罪有应得！"
D.Strings[3596]="好吧，我们走。"
D.Strings[3597]="打开它。我们要抓紧时间。我已经可以闻到黑铁军团的气味了，我可以告诉你，他们就要来了！"
D.Strings[3598]="他应该在最后一间牢房里。除非……除非他们已经把他给杀了。"
D.Strings[3599]="把他从那里弄出去！"
D.Strings[3600]="我们成功了！"
D.Strings[3601]="到麦克斯韦尔的营地碰面吧。我们将在那儿开始下一阶段的计划，在没有译码戒指的情况下找出破解石板上的文字的方法。"
D.Strings[3602]="格鲁尔克很快就打开，然后我们就分财宝。"
D.Strings[3603]="愚蠢的箱子！愚蠢！打开！格鲁尔克要你快点打开！"
D.Strings[3604]="让我试试！你太蠢了！"
D.Strings[3605]="格鲁尔克很蠢？你试试试看！难道你像侏儒一样聪明？"
D.Strings[3606]="拉穆尔克轻易打开了箱子！"
D.Strings[3607]="箱子真蠢。拉穆尔克要睡觉。"
D.Strings[3608]="费伍德的某些植物或许能因为塞纳里奥植物药膏的效用而避免堕落。我知道如何从几种不同的东西中获取这种药膏，凭借你的能力，你会发现有多种方法可以协助我制造药膏。$B$B首先，你需要一盏塞纳里奥信标，它是一种能让你看到肉眼所看不到的堕落和腐烂力量的装置。"
D.Strings[3609]="我需要塞纳里奥信标。"
D.Strings[3610]="给你一盏塞纳里奥信标，$n。如果你想要找到我们所需的堕落的物品，你就必须留着它。"
D.Strings[3611]="残骸上满是苍蝇和蛆虫。"
D.Strings[3612]="我召唤你，沙妮·长齿！"
D.Strings[3613]="%s看上去似乎受到了重创。他花了好一会儿才恢复过来。"
D.Strings[3614]="狠狠地打$n！"
D.Strings[3615]="你最好抓牢我，否则$n就有苦头吃了！"
D.Strings[3616]="看招！"
D.Strings[3617]="我敢打赌你现在感到遗憾了，不是吗$n！？！"
D.Strings[3618]="你关错元帅了，$n。准备受死吧！"
D.Strings[3619]="数年前居住在此地的暗夜精灵修建了这座神殿。$B$B它隐藏着什么秘密吗？"
D.Strings[3620]="我还需要一块闪光的石头。"
D.Strings[3621]="继续……"
D.Strings[3622]="卡兰，门开了。你自由了。"
D.Strings[3623]="在我所在的地方，你会因为打开其他牢友的门而受惩罚的！"
D.Strings[3624]="你不会敲门吗？？！"
D.Strings[3625]="我弄坏了我的艾萨莱特水晶武器！我需要你的帮助来打败那三个恶魔。"
D.Strings[3626]="我对不得不和$n交战而感到十分遗憾。"
D.Strings[3627]="嗨！最近怎么样？"
D.Strings[3628]="嘿，我的东西被偷了！"
D.Strings[3629]="好了！把这儿收拾好才能喝酒！"
D.Strings[3630]="哈！哈！哈！谢谢你们这些笨蛋放了我。现在让我吃掉你们的肉来报答你们吧。"
D.Strings[3631]="干得好！"
D.Strings[3632]="安戈洛环形山水晶塔的秘密现在已经被你破解了。你可以随时造访水晶塔，获取它们的力量。"
D.Strings[3633]="你别想再躲着我们了。准备去死吧！"
D.Strings[3634]="欢迎来到塔纳利斯，$n。我能为你提供什么服务？你看起来可不像铁匠，但是我知道，人不可貌相。"
D.Strings[3635]="啊呀！我要离开这儿！"
D.Strings[3636]="我要离开这儿了！"
D.Strings[3637]="%s开始召唤熔岩怪！"
D.Strings[3638]="我不喜欢交谈。"
D.Strings[3639]="啊，糟糕！我们没时间了。"
D.Strings[3640]="%s大声喊叫，发出警报！"
D.Strings[3641]="现在，我们来看看……如果我是正确的，那么……嗯……"
D.Strings[3642]="蓝色加红色……我觉得……"
D.Strings[3643]="$n，就是它！我终于想到了！"
D.Strings[3644]="它们都失踪了，$r。在亡灵天灾入侵奎尔萨拉斯的时候，精灵族的圣契散落到世界各地。$B$B现在我们得搜寻这些圣契。寻找其中的秘密——并恢复其中蕴含的力量。$B$B我在寻找由卡里尔·温萨鲁斯书写的圣契。如果你找到了圣契，请允许我吸收它的魔法力量，而为你我可以制作一种力量的融合物……当然，所有的事情都是有代价的。这项任务的风险极大，但是我给予的回报也是相当丰厚的。"
D.Strings[3645]="看看吧，这就是沉思圣契。"
D.Strings[3646]="啊，这么说……你已经找到了。$B$B<玛瑟迪斯指着你手中的书。>$B$B你收集到所需要的材料了吗？$B$B那些材料都已经在书中列出来了，笨蛋！"
D.Strings[3647]="<玛瑟迪斯目不转睛地盯着圣契。>$B$B你来寻求融合物的？你按照圣契的指示做了吗？"
D.Strings[3648]="给我奥术力量，然后我就会进行融合，凡人。"
D.Strings[3649]="确实是一项难得的发现。$B$B<玛瑟迪斯点了点头。>$B$B如果你希望继续的话，我会需要相应的材料。"
D.Strings[3650]="贪婪又把你带回给我了。$B$B<玛瑟迪斯笑了。>$B$B从前有个叫聪明的德莱尼人告诉我，婪是这个世界上所有的种族共有的唯一品质。我不得不同意。$B$B你找到圣契上所列出的材料了吗？"
D.Strings[3651]="有入侵者闯入制造厂？我的傀儡要毁掉你们！"
D.Strings[3652]="愿光明保佑你。"
D.Strings[3653]="我想接受更多的关于圣光的训练。"
D.Strings[3654]="攻击！财产损害！没人能通过！！"
D.Strings[3655]="你必须离开酒吧！"
D.Strings[3656]="你已经不受欢迎了！"
D.Strings[3657]="停止服务！"
D.Strings[3658]="你想让拆毁者干什么？"
D.Strings[3659]="你好，$n。如果你在完成任务时需要帮助，你只需开口就行了。我的卫兵，拆毁者可以帮你打败暗影蛛丝偷猎者。用这个命令法杖在战斗中指挥拆毁者。他受训只攻击暗影蛛丝偷猎者。"
D.Strings[3660]="我需要帮助来击败暗影蛛丝偷猎者。"
D.Strings[3661]="喝光它！我们还有很多酒！"
D.Strings[3662]="尽情享受吧！你找不到比这更好的啤酒了！"
D.Strings[3663]="你喝过黑铁啤酒吗？那可是最好的啤酒！"
D.Strings[3664]="尝尝野猪肉吧！这是我的新作！"
D.Strings[3665]="感谢你清除了这些愚蠢的议员。去面对拉格纳罗斯最强大的仆人吧，看看你的命运如何。"
D.Strings[3666]="你们所做的一切都没有意义，蠢货！你们永远都无法打败我！"
D.Strings[3667]="他们只是阻碍了一下。"
D.Strings[3668]="哈！你甚至不能想象你的努力全都白费了。"
D.Strings[3669]="那就是你的最好表现吗？你真的期望自己能打败一个象我这样令人畏惧的人吗？"
D.Strings[3670]="拍卖行"
D.Strings[3671]="拍卖行在哪儿？当你进入我们美丽的城市时它就在铁炉堡大门旁边。你会在银行的正对面找到它。"
D.Strings[3672]="Anu therador mali，$c。你需要什么指引吗？"
D.Strings[3673]="达纳苏斯有无数令人惊异的地方，你想去哪儿？"
D.Strings[3674]="你可以在达纳苏斯银行找到你存放财物的地方，它就在我们神奇的城市中央。"
D.Strings[3675]=S[19311]
D.Strings[3676]="维斯派塔斯的角鹰兽会送你到达目的地的。穿过达纳苏斯西部入口，去鲁瑟兰村找他吧。"
D.Strings[3677]="要是你想要组建公会的话，你必须去见公会管理人琳沙娜。她在达纳苏斯东北部的工匠区。"
D.Strings[3678]="尽管我可以将覆盖着整个泰达希尔的草坪当作很好的床铺，但是工匠区中塞琳尼经营的旅馆对那些享受一下奢华生活的人来说再合适不过了。"
D.Strings[3679]="在达纳苏斯的东北部，也就是工匠区，你会在旅馆外面找到邮箱的。"
D.Strings[3680]="职业训练师"
D.Strings[3681]="你很幸运来到达纳苏斯，因为你遇到了像祖卡斯特这样多才多艺的猎人作为你的培训师。我建议你到塞纳里奥区拜访她并寻求她的指导。"
D.Strings[3682]="在灰色年代，德鲁伊对周遭的人都很友好。你随便问塞纳里奥区的任何一个德鲁伊，他们会给出相同的说法的。"
D.Strings[3683]="月神殿是艾露恩的祭司们的家园。你会在那儿找到贾德莉亚和拉瑞亚，她们会对你的牧师生涯做出进一步的指导。"
D.Strings[3684]="月神的力量支配着你！月神的力量支配着你！\n\n出发吧！去达纳苏斯东部的月神殿中央大厅找贾德莉亚！"
D.Strings[3685]="要是你想做潜行者的话，就该去找塞尤娜。她居住在西部森林盘旋山道下的塞纳里奥区。"
D.Strings[3686]="很多人都试图追随潜行者的脚步，但是只有暗夜精灵能真正被黑夜接受。如果你想在阴暗的道路上前行的话，就去塞纳里奥区找塞尤娜吧。"
D.Strings[3687]="你会在战士区的护卫队中找到希达奈尔，她敏锐的眼睛扫视着森林，寻找着胆敢进入我们美丽的城市的敌人。"
D.Strings[3688]="达纳苏斯的工匠中传承着数千年的手艺知识，一定会对你有所助益的。告诉我，你对哪种工艺最好奇？"
D.Strings[3689]="如果你真的想做这个职业，就去达纳苏斯北部的工匠区找一个技艺纯熟的炼金士：安尼希尔。"
D.Strings[3690]="阿雷贡是一名技艺精湛的厨师，数个世纪以来，他都在完善着自己的厨艺。要是他愿意教你的话，你就得谢天谢地了。要是你相信自己的实力的话，就去工匠区找他吧。"
D.Strings[3691]="阿雷贡做的食物很受欢迎。他总是在工匠区忙于制作新的美食。要是有塞纳里奥绿色烹饪的话，你一定要尝尝。\n\n如果你不介意的话，我必须先去调查一下接二连三的鹿群失踪事件。"
D.Strings[3692]="没有具备天赋的附魔师，刀刃不可能如此锋利，护甲也不可能如此坚固。塔兰丹就是这样的附魔师，他可以教你如何给武器和护甲附魔。去工匠区找他吧。"
D.Strings[3693]="哦！$g小伙子:姑娘;，当你选择附魔时，你得非常小心。我让自己的杯子附魔，使杯中的水不洒出一滴，但是我也不能喝到里面的水了！这真是个悲剧。\n\n当你看到格瑞姆比时，必须记得我的叮嘱。他在大熔炉狮鹫管理人右边的商店中。"
D.Strings[3694]="当你没有医师来料理你的伤口时，急救知识可以救你的性命。我会请教工匠区的丹纳罗尔关于这门技艺的问题。"
D.Strings[3695]="它是一项耗时，但是会很有收获的技能。与贸易区的阿斯坦娅谈谈或许你能学到一些有用的东西。"
D.Strings[3696]="泰龙尼斯制作武器的技能无与伦比。他不会收学生的钱，你该为此感到庆幸。去吧，去达纳苏斯东北部的工匠区找他吧。"
D.Strings[3697]="我们种植蔬菜。野兔吃我们的蔬菜。狼群以野兔为食。我们捕杀狼群，从它们身上获得肉和兽皮。这就是神奇的生物链，或许你用别的什么词语来描述它。\n\n去塞纳里奥区找泰龙尼斯吧，我得继续执行自己的职责了。"
D.Strings[3698]="“一门可以让你度过重重难关的技能。”菲琳萨就是这样描述她的那套本事的。\n\n如果你相信她所说的，那么就到达纳苏斯北部的塞纳里奥区去吧，她在那里传授她的课程。"
D.Strings[3699]="世间动物死时会将它们的生命和兽皮赐予我们。要是你能尊重它们的牺牲，或许剥皮者这个职业会适合你的。去达纳苏斯北部的工匠区，找艾拉迪尔谈谈，学习更多知识。"
D.Strings[3700]="如果你想要在森林中生存，最好别远离城墙。但是，如果你真的计划在森林中闲逛的话，那么就去找塞纳里奥区的玛里甘谈谈，你会学到如何生营火的。"
D.Strings[3701]="如果你有希望学成一位裁缝的话你当然应该去找迈里恩。她住在达纳苏斯东北方的工匠区。"
D.Strings[3702]="科兰德善于追踪，森林中的任何生物都没法从他手中逃脱。如果你想达到他的一半能耐，最好认真他教学。\n\n我会解除你费力寻找他的麻烦，为你标识出他的位置，他就在塞纳里奥区。"
D.Strings[3703]="费伍德森林有什么植物可能被污染了？"
D.Strings[3704]="我已经观测到有四种植物受到了腐蚀术的影响：轻歌花、迎风花、鞭根草和夜龙植物。轻歌花和迎风花是费伍德森林中常见的植物，而鞭根草和夜龙植物就不那么常见了。所有这些都是费伍德森林生态系统的重要组成部分。"
D.Strings[3705]="这儿就是那场声势浩大的战争的遗址。那些伟大的战争啊。"
D.Strings[3706]="和雷戈萨谈谈。他非常聪明，能帮你寻找东西。"
D.Strings[3707]="停下！有……一场……关于……骚乱的……报告。"
D.Strings[3708]="我……我们……在调查。"
D.Strings[3709]="嗯，我不知道自己还能撑多久……我感到有些乏力……"
D.Strings[3710]="记住，如果我迷糊了，就抽我的耳光。如果我晕厥的话，就用这个水壶。现在，我们走吧！"
D.Strings[3711]="啊啊啊啊……"
D.Strings[3712]="我有些不适……"
D.Strings[3713]="热……我受不了了……"
D.Strings[3714]="你……能不能背我一程？"
D.Strings[3715]="嗯，继续！"
D.Strings[3716]="我现在感觉好些了，谢谢你。"
D.Strings[3717]="我感觉怎么样？简直湿透了，谢谢你。"
D.Strings[3718]="斯普拉格！我简直不敢相信自己居然能活着回来！"
D.Strings[3719]="啊……有点晕……"
D.Strings[3720]="林格！你没事了！"
D.Strings[3721]="林格？快醒醒！不要担心，我会照顾你的。"
D.Strings[3722]="啊！太感谢你了，$n！我自由了！终于自由了！"
D.Strings[3723]="你照顾好你自己！我要离开这儿了。"
D.Strings[3724]="嗯……很抱歉打扰你，如果你现在没有在用古德斯迪尔的账本……能让我再看看吗？"
D.Strings[3725]="啊，没问题，$n！对不起……我还以为你已经搞定了。"
D.Strings[3726]="你必须给我一点时间，$c，纳迦正在攻击我们。搞定他们之后再来找我！"
D.Strings[3727]="约翰，给我讲个故事吧。"
D.Strings[3728]="好吧*嗝儿*……嗯，你看起来很眼熟*嗝儿*。我有跟你说过我和温德索尔一起跟，呃，一，一百万个兽人战斗的事儿吗？$B$B哦，坐下来吧，朋友，这个故事非常棒的！"
D.Strings[3729]="阁下，让我拿些玉米仁吧。"
D.Strings[3730]="这是给你的体质圣契。"
D.Strings[3731]="这是给你的坚韧圣契。"
D.Strings[3732]="这是给你的恢复圣契。"
D.Strings[3733]="这是给你的贪婪圣契。"
D.Strings[3734]="在你把诱饵涂抹到水晶上之后，%s立刻冲进了孵卵所！"
D.Strings[3735]="奥格瑞玛拍卖所位于力量谷。去火枪进口公司东面找它吧。"
D.Strings[3736]="你的嗓子喊哑了是吗？在力量谷就可以找到奥格瑞玛拍卖行。"
D.Strings[3737]="欢迎来到达纳苏斯银行。我们提供金融帐户和存储贵重物品的保险箱。你要开户吗$g先生:女士;？"
D.Strings[3738]="不可思议，不是吗？所有这些神器和残骸。$B$B我不清楚是什么给我留下了更为深刻的印象，它们的规模，还是它们背后的故事。要学习的东西还很多。我们能找到其中的关联……$B$B你知道那个传闻吗，听说许多种族与暗夜精灵有着相同的遗产。"
D.Strings[3739]="影像将在一分钟内消散。"
D.Strings[3740]="%s开始施放法术。"
D.Strings[3741]="%s将这些物品转换成一个图腾。"
D.Strings[3742]="%s显然对索瑞森大帝的死亡感到震惊。"
D.Strings[3743]="索瑞森大帝不希望有人打扰他！滚回去面对自己的命运吧，你们这些懦弱的人！"
D.Strings[3744]="为国王欢呼吧，宝贝！"
D.Strings[3745]="嗨，我是派提亚。在我右边是科多兽达丹加。我们曾跟马歇尔探险队在一起——那已经是数年前的事儿了，那时达丹加还是只幼兽呢。$B$B要是你带有火炬或是任何火种，请尽可能地把它们藏起来。达丹加不喜欢烟。"
D.Strings[3746]="为了所有神圣高贵的爱，请告诉我你是来把我们从这片被遗忘之地带走的。虽然我是与马绍尔探险队一起的，我愿给你我口中的金牙，只要你让我爬进你的背包并离开这个地方。"
D.Strings[3747]="哦，你好！我是霍莱伊，马绍尔探险队的首席科学家和生物学家。我的兄弟和我，还有我们的同伴，一起到艾泽拉斯去探索荒野和未被驯化的雄伟景象。真是太激动人心了……但是，嗯……我想这次我们陷入了太多激动中了！"
D.Strings[3748]="你好，陌生人。欢迎你来到遍布丛莽的安戈洛环形山！$B$B我叫威利德·马绍尔。我、我的姐妹以及同伴组成了马绍尔探险队——致力于探索艾泽拉斯荒野和未知之地的科学家和探险家们。"
D.Strings[3749]="事情变得有趣起来。我的计划是沿着左侧的山前进。这样我们就不会在丛林中迷路，还能避开敌人。你准备好了吗？"
D.Strings[3750]="这是东部的山墙！我现在正向南推进；跟紧了。我们还不会从最危险的地方撤离！"
D.Strings[3751]="这就是离开安戈洛的路！我们做到了！现在我们所担心的就是塔纳利斯沙漠了。"
D.Strings[3752]="就是这儿——塔纳利斯沙漠。这样荒凉的地方比难以走出的绿色丛林看起来好多了，这可真有意思。"
D.Strings[3753]="你因为反对黑铁王国的罪行而被宣判死罪！"
D.Strings[3754]="索瑞森的臣民将在秩序竞技场中看着你死去！"
D.Strings[3755]="释放你的怒气吧！"
D.Strings[3756]="哈！我敢打赌你以为自己能获胜！"
D.Strings[3757]="但是真正的惩戒还在后面呢。"
D.Strings[3758]="难以置信！太令我惊讶了！我甚至根本不知道这意味着什么！"
D.Strings[3759]="看看这些样本！这意味着什么？这意味着什么？我需要时间来解读这些信息。我还需要更多我无法获得的信息……该死！好好想想，拉里斯，好好想想！$B$B你要做什么？什么？！$B$B必须得有解决的方法！"
D.Strings[3760]="在艾泽拉斯，一定有未被亡灵天灾侵蚀的软泥怪。但是在哪儿呢？"
D.Strings[3761]="软泥怪和泥浆怪有何不同？"
D.Strings[3762]="不，我并不清楚。似乎那主要与地域有关。有些种类称为泥浆怪，有些称为软泥怪。似乎这属于个人偏好。$B$B每次我遇到软泥怪、淤泥怪或泥浆怪时，它们从根本上都是一种生物。不同之处在于它们的环境，这也是我们需要一份纯净的样本的原因。"
D.Strings[3763]="你说的“纯净”是什么意思？"
D.Strings[3764]="一个纯净的样品就是在非故意情况下未被腐蚀的样品。我们需要尽可能在最基本，最正常的环境中找到这样的生物。$B$B这意味着某个全无文明痕迹或是未受艾泽拉斯某个种族所影响的地方。某块……处女地。"
D.Strings[3765]="你认为还有这样一块处女地吗？"
D.Strings[3766]="那绝不是东部王国的任何一个地方。$B$B一定是在卡利姆多大陆的某处，但是距离部落和其他种族仍有相当遥远的距离。还没有受到分裂影响的某个地方——远离暗夜精灵文明的地方。$B$B我猜有人守护在那儿……就像守护山谷或是环形山一样；我不确定。我只是猜测。很抱歉我不能提供更多的帮助了。"
D.Strings[3767]="欢迎你，$c。炼金房区很少有访客……当然，除非有人对这儿的某些东西感兴趣。$B$B<炼金师克林笑起来。>$B$B我能帮助你吗？"
D.Strings[3768]="我要把你打成碎片！"
D.Strings[3769]="%s抽泣着，那模样令人同情。"
D.Strings[3770]="%s发出痛苦的呻吟。"
D.Strings[3771]="好吧，不要再靠近了，就站在这儿。快些，达丹加！"
D.Strings[3772]="加把劲，达丹加！快一点，小女孩！"
D.Strings[3773]="$n，你打扰我休息了！"
D.Strings[3774]="让我安静一下。我必须休息。"
D.Strings[3775]="谁敢唤醒亚奎门塔斯？"
D.Strings[3776]="离我的科多兽远些，你这个怪物！"
D.Strings[3777]="达丹加！进攻！"
D.Strings[3778]="这一定是我所见过的最大的$n……而它正向我们冲过来！"
D.Strings[3779]="小心$n！"
D.Strings[3780]="草药的收集和与之相关的知识是菲罗迪恩·唤月的专长。去达纳苏斯西南部的神殿花园找他吧。"
D.Strings[3781]="一个新手采药师？那你该找神殿花园的菲罗迪恩·唤月聊聊。他或许有些专业诀窍要传授给你。"
D.Strings[3782]="我不知道你为什么想要离开这阳光灿烂的沙滩和蓝色晶莹的水域。这里就象是天堂。但是不要告诉我的哥哥萨匹塔这些，他整天被困在提瑞斯法已经够难过的了。这里的地精飞艇目的地是奥格瑞玛，所以你不用担心得听他发牢骚。但是如果你到了提瑞斯法，要留意我的警告并且不要让他开始抱怨。"
D.Strings[3783]="我感觉$n散发着堕落的气息。帮我毁掉它！"
D.Strings[3784]="这个生物受着毒药的折磨……我们必须终止它的痛苦。"
D.Strings[3785]="$n已经被堕落力量逼疯了。"
D.Strings[3786]="好好利用自然界的草药，它会成为你有力的助手的。去本娜的炼金店找她吧，接受更多训练。"
D.Strings[3787]="你可以到中部高地的底层的雷霆崖银行存放你的财物。"
D.Strings[3788]="和其他所有事物一样，金属应该被平衡的使用。卡恩·石蹄在中部高地的底层的池塘边设立了一处铁匠铺。去寻求他的指引吧。"
D.Strings[3789]="你没有浪费那些你必须杀死的动物，因此你赐予了这些动物的灵魂以荣誉。阿丝卡·迷雾行者将会给你演示怎么处理。她在高地上有个厨房。"
D.Strings[3790]="你好尊贵的客人。图拉克·符文图腾和其余的德鲁伊正在长者高地上的长者大厅等你。"
D.Strings[3791]="附魔体现了毁灭和新生的循环，这正是自然界的基本准则。晨行者附魔师将为你展示这一切。"
D.Strings[3792]="生活是一场竞争，“大难不死必有后福”这句俗语并不是始终正确的。有时伤口愈合得很慢，这就是我们需要绑带的原因。灵魂高地的潘德·缚石能教你急救的技能。"
D.Strings[3793]="山顶渔具店的卡尔·迷雾行者将为你指明如何实现内心平静的同时还能通过钓鱼为自己准备好下一餐。"
D.Strings[3794]="一个志趣相投的团体可以成为一支非常强大的力量。克拉姆会帮助你们达到这个目的。你可以在雷霆崖升降梯旁边中部高地的底层的公民信息中心找到他。"
D.Strings[3795]="自然会提供我们所需的一切。跟中部高地中层克米恩·冰蹄谈谈草药学吧。"
D.Strings[3796]="动物的朋友就是我的朋友。你要找的猎人大厅就在猎人高地的顶部。"
D.Strings[3797]="利用敌人的兽皮来保护自己这一想法运用了拟态学的知识。要进一步提高制皮技能，你得去雷霆崖防具店找库纳。"
D.Strings[3798]="想到这些可怜的亡灵灵魂的遭遇，我感到非常悲伤。你可以去灵魂高地之下的预见之池附近找大法师山姆。"
D.Strings[3799]="大地之母有许多秘密，布瑞克·石蹄能帮助你发现一些秘密。你会在 石蹄地质学会的中部高地的底层那找到他的。"
D.Strings[3800]="虽然亡灵受到重创，但是他们还是赶来帮助我们。我只希望我们也能对他们有所帮助。去灵魂高地下面的预见之池附近寻找柯布神父。"
D.Strings[3801]="大地之母发出召唤，你得做出应答。你可以在灵魂高地找到灵魂大厅。"
D.Strings[3802]="充分利用每块碎片会让我们更加节约并会拉近我们和大地母亲的距离。莫兰塔会教给你方法。到中部高地上的雷霆崖兵器库外面可以找到她。"
D.Strings[3803]="你，与自然和谐相处，而只有靠你的技能才能生存。这就是大地母亲想要的方式。你会在猎人高地找到拜尔的。"
D.Strings[3804]="给部落做衣服与其余的工作同样重要。你该到雷霆崖防具店里面寻找坦帕。她对针线活有自己的天赋。"
D.Strings[3805]="啊，猎人的真正标志！在永无止境的生命游戏中追踪猎物。去猎人高地寻找德拉伊吧。"
D.Strings[3806]="强壮的身体和精神。没有比这更强大的组合了！去猎人大厅跟萨尔克·暴怒图腾找寻自己的命运吧。"
D.Strings[3807]="啊，和天空中的巨鸟一同翱翔。去双足飞龙巢穴顶端找塔尔吧。他会指引你完成你的梦想的。"
D.Strings[3808]="去中部高地的底层的雷霆崖银行以南的建筑物中可以找到旅店老板帕拉。"
D.Strings[3809]="旅店老板帕拉能帮助你得到身心的休息。他就在中部高地的底层的雷霆崖银行以南的建筑物中。"
D.Strings[3810]="你能在中部高地的底层的雷霆崖银行外面找到一个邮筒。"
D.Strings[3811]="我记得不久之前我有新邮件寄出。你可以在中部高地的底层雷霆崖银行外找到邮箱。"
D.Strings[3812]="你可以在雷霆崖的最低处寻找，就在离银行不远的地方。"
D.Strings[3813]="你可以在雷霆崖的中央高地找到拍卖行。在双足飞龙飞行点下方附近找找吧，愿你的先祖保佑你。"
D.Strings[3814]="或许这会令你震惊，但是近来的事情不是那么顺利……"
D.Strings[3815]="欢迎你来到塞拉摩，$n。$B$B我没时间跟你寒暄，我为自己的唐突向你道歉，但是我必须以城市为首。我们的生活和联盟的尊严受到了严重的威胁。要想使我的人民平安幸福，我就必须对不在我们控制之外的力量保持警惕。$B$B或许稍后我们能找时间谈谈。"
D.Strings[3816]="亨德尔已经被我们逮捕了，$n。谢谢你。$B$B尽管审讯的进展会比较缓慢，但我向你保证，他会告诉我们他所知道的一切。$B$B眼下还请你耐心等待。如果我需要你的帮助，就会马上联系你。$B$B在那之前，请享受塞拉摩之旅，我邀请你作为联盟的朋友来到我们城市，要待多久随便你。"
D.Strings[3817]="要是你准备就绪，我和达丹加也整装待发了。我们出发吧！"
D.Strings[3818]="是的$g兄弟:姐妹;，我可以帮你吗？"
D.Strings[3819]="好吧……我知道如何往返加基森。但我需要你驱赶沿路的野兽。我已经对 达丹加进行了良好的自我保护训练，但是我们无法应对那儿过于疯狂的野兽。你准备好了就告诉我吧，$n。"
D.Strings[3820]="你认为达丹加如何？"
D.Strings[3821]="在城市的大门外有一处路标指向西部地精塔。"
D.Strings[3822]="去城外东南方找东部飞艇塔。"
D.Strings[3823]="飞艇管理员"
D.Strings[3824]="我和我的兄弟效忠于希尔瓦娜斯。在最黑暗的时代，她是我们的指路明灯。我们日复一日地奉献着，希望使种族避免遭受厄运。$B$B我们不会一直软弱下去的。我们会取回自己应得的。我们将报复敌人，让他们尝到十倍于我们的痛苦。并且，我们将面带微笑报复敌人。"
D.Strings[3825]="希尔瓦娜斯女王已经下令对艾泽拉斯的某些自然现象进行调查。她觉得能从艾泽拉斯神秘的历史中学到更多的知识。$B$B我不知道要如何才能学到这些知识，但是我完全相信她，因此我会尽力而为的。所有的生物看起来很相似，但是周围的环境对它们的影响是不容忽略的。$B$B我需要你帮我收集生物样本。"
D.Strings[3826]="%s目睹死去的幼兽，变得极为愤怒！"
D.Strings[3827]="为血帆海军的上将——$n欢呼吧！"
D.Strings[3828]="嗨！嗨！……啊……"
D.Strings[3829]="<你靠近沃科尔时，他一点都不理睬你。他好象集中精力关注他的绷带以防脱落。过了一会儿，他抬头看你，有一点惊诧。>$B$B噢，对不起，$c。现在不太合适。我希望你能理解。"
D.Strings[3830]="嗯，依我看来，$n，要离开这个洞穴有两种选择。$B$B我们可以秘密潜逃——我利用你给我的披风，你用你自己的办法；或者，我们一起杀出去，但是我受伤了，这个方法或许比较困难。$B$B你更了解自己的实力，因此我让你来做选择。"
D.Strings[3831]="你好，$g小伙子:姑娘;，如果你想要在铁炉堡之外找到最好的交易地点，那么你就算找对地方了。"
D.Strings[3832]="你看到我们湖中污浊的水元素了吗，$n？这个场景令人感到伤感，但是我不知道它们是从哪里来的。$B$B在我过去的谈话中似乎有人提起过你的名字，或许你可以帮我。$B$B我们必须了解的第一件事就是谁控制着这些元素。"
D.Strings[3833]="你好。我是古博·布拉普。"
D.Strings[3834]="古博，我不知道怎么钓鱼。"
D.Strings[3835]="古博, 我没有钓鱼竿。"
D.Strings[3836]="钓鱼真的很简单。就是拿着一根杆子带着一条线，或许再放些鱼饵，然后扔到水里去，然后那些鱼就会开始咬饵了。"
D.Strings[3837]="我这里还有多余的，如果你付给我成本钱，我就可以给你一个。另外我还有一些诱饵。"
D.Strings[3838]="……油煎，油炸，还有爆炒……"
D.Strings[3839]="注意我的后面，这有可能非常混乱。"
D.Strings[3840]="当你靠近时，那些液体和混合物剧烈地翻腾起来。设备旁边是一把巨大的钳子，似乎很适合用来夹起淤泥样本。$B$B还有安全齿轮装备，但是上面布满灰尘，似乎很久没有使用过了。$B$B你觉得什么东西都不碰为好。"
D.Strings[3841]="设计图就在那儿！"
D.Strings[3842]="入侵者正在破坏我们的蛋！住手！！"
D.Strings[3843]="哇！*咳**咳*我要戒烟！"
D.Strings[3844]="问问基布雷尔关于宝藏的事情！哇！"
D.Strings[3845]="比修失败了！啊！*咳嗽*"
D.Strings[3846]="比修知道宝藏被藏在哪儿了。"
D.Strings[3847]="奥普斯想要一些科尔戈的黄金……和一些虫子。"
D.Strings[3848]="他们都去了黑石塔，但是跟比修一样……没有人活着回来。"
D.Strings[3849]="基布雷尔正在接受地精工程学协会的调查。"
D.Strings[3850]="龙控制着兽人！？不会吧！"
D.Strings[3851]="我在这儿！可悲的渣滓，你们会为侵入这里付出代价的！"
D.Strings[3852]="%s发出凄惨的低啸，轰然倒地。黑石塔大厅中紧接着传来令人毛骨悚然的咆哮声。看来有什么生物受到了刺激，变得异常愤怒。"
D.Strings[3853]="你好，$n。"
D.Strings[3854]="别担心斯奎尔图，$n。他不想这么粗鲁的，他只是非常繁忙。我们不如趁着等他完成侦察任务的时候做些更有用的事情？"
D.Strings[3855]="你好$n！$B$B我必须继续研究我的装置了，但是最终……我需要有人给我带来龙蛋！"
D.Strings[3856]="燃烧平原是个危险的地方，但是我这样的学者将不惜一切代价来获取新知识。"
D.Strings[3857]="我要返回龙蛋房了，丁奇。我需要一个龙蛋冷冻器！"
D.Strings[3858]="愿你能得心应手地应用熔炼黑铁的技能，$n。但是不要让你的知识使你堕落……就像我们一样堕落了。"
D.Strings[3859]="终于……终于有人值得学到我的知识了。别担心——我已经了解你的想法，我不会伤害你的。"
D.Strings[3860]="听仔细了，要是你没有准备好的话，黑石统领会杀死你的。"
D.Strings[3861]="你好，$n。你看上去是个强壮的$c——你应该能够在这个地区有所作为。你可以去接触一下你不了解的东西，否则对你的长辈表现出失礼的行为将招致惩罚。$B$B你可以不尊重我或者我的同伴，但是如果你真的那么愚蠢的话，你就必然会学会尊重我们的力量。$B$B现在，闲聊够了，有什么事情我可以帮忙的？"
D.Strings[3862]="啊，一个术士同伴已经在某种程度上证明了$g他的:她的;价值。$B$B很高兴认识你。我的名字是梅纳拉·沃伦德……那是有原因的。$B$B你看上去强大并博学，其他的工具……你是更强大的工具……会很受欢迎而不是愚蠢地泄密。如果事实确实如此，那再与我更深入地谈谈。如果不是，那么你知道你该怎么回到码头然后回到海洋的另一边。"
D.Strings[3863]="人类左边第4和第5根肋骨之间的部位最脆弱。让我们来练习一下攻击这个部位……"
D.Strings[3864]="你来试试看。"
D.Strings[3865]="暗夜精灵在施法时喜欢单腿站立。你可以这样来攻击那条站立的腿……"
D.Strings[3866]="有时，矮人会在把武器抡圆的过程中将背部暴露出来。利用这个机会像这样打下去……"
D.Strings[3867]="很好。你有希望加入精英的行列。现在，你需要更多的训练。"
D.Strings[3868]="%s开始恢复力量！"
D.Strings[3869]="%s几乎完全恢复了力量！"
D.Strings[3870]="%s恢复力量，摆脱了镣铐的束缚！"
D.Strings[3871]="很久以前——我们的种族经历了无数战乱和冲突，几乎到了灭绝的边缘。我们承受了太多灾难，$c。$B$B燃烧军团的进攻，恶魔之魂，巨龙军团的分裂，死亡之翼的崛起，我们的女王阿莱克丝塔萨受到龙喉氏族的奴役。$B$B经过种种磨难，我们拥有了不可动摇的意志——那是努力生存的大无畏力量。"
D.Strings[3872]="你们的种族？"
D.Strings[3873]="我以你所能接受的形态站在你面前。显然，你无法接受一条名叫瓦拉斯塔兹的龙。$B$B<维埃兰笑了起来。>$B$B我可以继续吗？"
D.Strings[3874]="拜托。"
D.Strings[3875]="或许我应该告诉你为什么我会在这儿。$B$B你知道死亡之翼或者他的后裔，奈法利安和奥妮克希亚吗？"
D.Strings[3876]="不，维埃兰，我不清楚。"
D.Strings[3877]="死亡之翼，曾被称为奈萨里奥，它是代表世界的力量的守护巨龙——世界的缔造者卡兹格罗斯赋予了他无尽的力量，让他保护这个世界。$B$B但是这个卑鄙的家伙欺骗了其他四条守护巨龙，让他们使用自己的力量制造了恶魔之魂——这使得他们的力量大为减弱，巨龙军团于是就分裂了。"
D.Strings[3878]="恶魔之魂？"
D.Strings[3879]="是的。最终恶魔之魂被摧毁了，剩余的四条守护巨龙联合起来，几乎取了死亡之翼的性命。没人知道死亡之翼现在到底在哪里。但是，我们知道他的一名后裔奈法利安正统治着这座要塞，希望能继续他父亲未竟的事业。"
D.Strings[3880]="未竟的事业？"
D.Strings[3881]="在被放逐之前，死亡之翼曾试图产下混血的后代。混血的龙不仅无法获得守护巨龙天生的力量，也无法被死亡之翼控制。$B$B似乎奈法利安在他父亲失败了的事情上取得了成功——至少是一些进展。$B$B梦境之神伊瑟拉预见到了这种混血龙类的存在，我们必须杀死那些“彩色”的龙。"
D.Strings[3882]="为什么巨龙们不联合起来消灭它们？"
D.Strings[3883]="这不是我们做事的方法，也不可能是。奈法利安受到远古结界的保护，这些结界与守护巨龙本身一样古老。正是它们阻止我进入这座要塞的内部。除非……除非得到授权，否则黑暗魔法会永远把我们挡在外面。"
D.Strings[3884]="除非？"
D.Strings[3885]="除龙族之外的任何人都可能获得晋升印章并通过那层保护屏障，但是这样的东西肯定会要了我的性命，或许你能使用它，想办法破除屏障。"
D.Strings[3886]="我很乐意尝试，但是我需要指导。"
D.Strings[3887]="你必须在这座要塞下层部分的那些邪恶生物里找到一个拥有原始晋升印章的家伙。对于那些劣等生物来说，得到这枚物品是一个至高无上的荣誉，这是迈入堡垒上层，进入奈法利安的精英军团——黑手军团的第一步。找到这么一件东西，把它交给我，让我来检查一下它，然后我就会知道下一步该怎么做了。"
D.Strings[3888]="我会尽力做到最好的，维埃兰。"
D.Strings[3889]="你要知道，这样的物品是非常罕见的。你可能需要进行数年的搜索才能找到一枚印章。我建议你对这些邪恶的生物毫不留情，把他们全都杀掉。"
D.Strings[3890]="我们会完成这个任务的。"
D.Strings[3891]="别再靠近我了，$n。我已经可以感觉到印章中流淌着的邪恶力量了。$B$B给我一点时间，让我来检查检查——你要紧紧地握住它。"
D.Strings[3892]="如你所愿，维埃兰。"
D.Strings[3893]="%s被反魔法屏障包围着。"
D.Strings[3894]="我已经看清了你要走的路。你准备好了吗？"
D.Strings[3895]="走开，凡人！你不配获得我的知识。"
D.Strings[3896]="啊，$r，你回来了！"
D.Strings[3897]="%s的意志开始动摇。"
D.Strings[3898]="我终于能够与你抗衡了，奈法利安。你认为自己能躲过其他守护巨龙的力量吗？"
D.Strings[3899]="够了！娱乐时间已经过了！"
D.Strings[3900]="你说自己不知道如何使用斧头是什么意思？"
D.Strings[3901]="它很小，但是如果你明白自己在做什么的话，还是能使它发挥效用的。让我来向你说明该怎么用它。"
D.Strings[3902]="像这样拿着刀，然后掷出去。把手腕放松一些，只需要一两下，你就可以把你的午饭搞定了。"
D.Strings[3903]="我们很早以前就开始使用弓箭了。它们坚实可靠，能迅速杀死敌人。我不认为我们该使用地精和牛头人们爱不释手的火枪。"
D.Strings[3904]="你是来学习的吗，伙计？"
D.Strings[3905]="兽人的拳头已经是一种强大的武器了，所以为什么不给它们再加上用坚硬的钢铁做成的刀刃或是大头钉呢？我以前用来驯服野狼的拳头现在足以用来击碎敌人的装甲。"
D.Strings[3906]="你也许会认为这是我的手杖。这是我正希望你所想的。"
D.Strings[3907]="弓很重要,我的朋友。你只需照顾它，而它就会照顾你。"
D.Strings[3908]="这不是个游戏，伙计。你想使用斧子，就必须说那句话。说什么？“跟我的小朋友打个招呼。”"
D.Strings[3909]="弓箭的用途向来不大，但是地精制造的这些来复枪在狩猎时非常有用。虽然我仍然无法习惯这气味。"
D.Strings[3910]="$n，我已经查明魔苔在整个黑海岸的影响有多么的猖獗。泰达希尔和我们周围大地的堕落的确引起了塞纳里奥议会德鲁伊以及所有的暗夜精灵的关注。$B$B我的目标就是查出为什么会发生这样的事并将其制止。"
D.Strings[3911]="这看起来或许很简单，无非是一根前端极重的大棍。但是当强壮的牛头人挥动起来时，这根棍子可以击穿石墙。"
D.Strings[3912]="只是一根手杖吗？你想让我看看一根手杖能做什么？"
D.Strings[3913]="%s开始召唤黑铁恐法师！"
D.Strings[3914]="%s召唤出黑铁恐法师来帮助他！"
D.Strings[3915]="%s开始召唤黑铁老兵！"
D.Strings[3916]="%s召唤出黑铁老兵来帮助他！"
D.Strings[3917]="过奖了，但我真的不感兴趣……什么？你想知道在哪儿能学习附魔知识吗？哦，真令人为难！呃，你应该……我想你应该……去找那个，嗯……塔兰丹！对，去工匠区找塔兰丹！"
D.Strings[3918]="什么……没有人可以在我的营地里净化熊怪！准备体验萨巴克希斯的愤怒吧！"
D.Strings[3919]="%s被已净化的食物的香味所吸引。"
D.Strings[3920]="%s开始狼吞虎咽地进食。"
D.Strings[3921]="范克里夫出高价悬赏你！"
D.Strings[3922]="没什么可怕的。来吧。"
D.Strings[3923]="武器就是用来杀人的，它们被制造出来的目的就是杀人。它们都很漂亮，不是吗？"
D.Strings[3924]="让你的敌人走投无路，同时将他们撕成碎末。唯一的问题是我手拿着东西而无法大开杀戒。"
D.Strings[3925]="敏捷而自信。这里切断一条肌腱，那里割断一根动脉。我要教你如何把任何一把刀子变成一种完美的杀人机器。"
D.Strings[3926]="长时间重装弹药需要时间来适应，但是没有什么比战争更锻炼人了。"
D.Strings[3927]="欢迎来到我的商店，$c。古斯提兄弟能为你做什么吗？"
D.Strings[3928]="啊，我最喜爱的顾客之一。你似乎是个有能力的术士，$n。很高兴认识你。要是我能帮上什么忙，请尽管开口。$B$B我和我的兄弟都认为你这样的人才能领导我们进入新纪元。一个拥有力量……和控制力的人……让军团臣服于你只是时间问题。$B$B我有些羡慕你了。"
D.Strings[3929]="联盟怎么样，雷德？"
D.Strings[3930]="阁下，他们释放了温德索尔。奥妮克希亚的伪装被揭穿也是迟早的事情了。"
D.Strings[3931]="我们不能再浪费时间了。多彩龙人准备好了吗？"
D.Strings[3932]="阁下，下一个时间点就要来临。我们已经准备在周末发动攻击。"
D.Strings[3933]="我能教你使用短刃的绝招或双手武器威力巨大的劈砍招式。或者我们疯狂些，我两样都教给你，这样当情况有变时就能派得上用场。"
D.Strings[3934]="我肯定会教你挥舞长柄武器的艺术，但你要交费。"
D.Strings[3935]="很好……看起来好像这些爱管闲事的小人物来得正是时候。欢迎，凡人！！"
D.Strings[3936]="要重新装弹显然要花费较长时间，但是有了这个家伙，我可以在任何护甲上弄一个拳头大的洞来。"
D.Strings[3937]="我看过拿着棍棒的农夫抵挡训练有素的士兵。绝不要低估正确挥舞棍棒所需要的力量和技巧。"
D.Strings[3938]="如果你认为我很棒，那你该看看我的丈夫如何打斗。"
D.Strings[3939]="我的孩子，让他们的鲜血在地板上一滴也不要留下了。享受他们的灵魂大餐吧！"
D.Strings[3940]="你手中的一把锤头让这个世界感觉安全了许多。有一块巨大的金属抓在你的手中，你感觉能够对付即使是最强大的敌人。"
D.Strings[3941]="我将教你如何杀敌，让他们像小树苗一样倒下。"
D.Strings[3942]="地平线上的猎犬以每秒三十英尺的速度移动。现在唯一的问题是，右眼还是左眼。那就对了$g小伙子:姑娘;，我就是那么棒。"
D.Strings[3943]="看到这个了吗？这是我的钓竿！这就对了，这个甜美的宝贝在卡兹莫丹的铁炉堡制造。零售价一百零九块金币，九十五块铜币。它的柄是胡桃木做的，钍合金的钢铁做的竿身，还有一个灵敏的浮标。"
D.Strings[3944]="啊，我想好好干一架，但是有时你的敌人的骨头比瑟银护甲还坚硬。这时你就需要一些帮助了。"
D.Strings[3945]="多彩龙人会对付这些入侵者的。我们谈谈更为紧迫的事情吧。"
D.Strings[3946]="现代化是关键。利用手柄和杠杆，你只需用食人魔拉弓的力量就能使这个小孩弹出去。"
D.Strings[3947]="走吧$n，前往白沙岗哨。"
D.Strings[3948]="嗵，嗖，哐！他或许有一把用船锚改装的巨大的双手刀，但当我用餐刀巧妙地切了几刀后，他就是那个要倒下去的人！"
D.Strings[3949]="袖子里藏着刀片意味着要么你躺在小巷里死去，要么你的对手卧在他自己的鲜血里。"
D.Strings[3950]="钝刀穿透了盾牌。"
D.Strings[3951]="刀的秘密在于，在你挥刀之前，其刀锋是隐藏的。"
D.Strings[3952]="那么，你想多学些我们精灵族的武器？我们开始上第一节课吧。"
D.Strings[3953]="这看上去很眼熟，要是我们一直朝东走的话，我想我们能做到的。啊！双足飞龙，备战吧！"
D.Strings[3954]="你想要一种武器可以作为你的拳头的延伸？好的，我相信可以给你看看某样东西。"
D.Strings[3955]="我不太清楚老虎眼睛的用途，但是我可以教你如何使用老虎爪子。"
D.Strings[3956]="许多人认为法杖是一种下等的武器。我向所有这么认为的人发出挑战，让他们挑战我的法杖以证明他们的实力。"
D.Strings[3957]="不只是对猎人，掌握弓箭的使用技能对每个人来说都相当有用。你可以在猎物眨眼之前快速，悄无声息地出击……还没等反应过来，它们就已经死了。"
D.Strings[3958]="啊，$r……我了解很多关于这个世界的知识，以及如何制造巨大能量的符咒的方法。"
D.Strings[3959]="好几次我仅用刀就吓退了试图靠近袭击我的敌人。秘密就在于手腕的动作。"
D.Strings[3960]="玛艾里知道你为什么找她……$B$B带给我你找到的魂精，我就会为你转换它。"
D.Strings[3961]="我要如何使用玛艾里的容器？"
D.Strings[3962]="妙极了……让我的孩子们将这些凡人撕成碎片吧。"
D.Strings[3963]="使用冰冻喷吐，你这蠢货！"
D.Strings[3964]="蠢货……杀死穿那件衣服的人！"
D.Strings[3965]="孩子，别推我的手！我将用你的兽皮装饰我的靴子。"
D.Strings[3966]="你的努力都是白费心机。没有什么会阻止我们的！"
D.Strings[3967]="你将为自己的失败受到惩罚，永远在这儿清扫粪便！"
D.Strings[3968]="诅咒你，凡人。"
D.Strings[3969]="集中攻击那个医疗者！"
D.Strings[3970]="阁下，让我参战吧！我将赤手空拳地把他们的脊椎撕碎！"
D.Strings[3971]="趁你们还有机会的时候，赶快逃走吧，凡人。如果我进入竞技场，你们就会祈求速死的。"
D.Strings[3972]="你会了解只有死亡才是唯一的避难所……"
D.Strings[3973]="似乎我不得不插手这件事，亲自来解决你。"
D.Strings[3974]="我要撕裂你，用你的肢体打败你！"
D.Strings[3975]="污染者！"
D.Strings[3976]="我再也不能忍受啦！"
D.Strings[3977]="文森特！你和你可怜的家族跟肯瑞托那些贫穷的幸存者一样，是不可能打败我和我儿子的。"
D.Strings[3978]="如果你不愿为我的主人服务，不愿提供敌人的消息的话……"
D.Strings[3979]="你腐烂的尸体将会成为我的奴仆，让别人知道如果有哪个蠢货胆敢入侵我的地盘，他会有什么样的后果！"
D.Strings[3980]="非常感谢你……从这里我能找到回白沙岗哨的路。记得跟莫特加·火鬃谈谈，也许你能阻止他送我回家。"
D.Strings[3981]="%s发现你在破坏营地的水果储藏，开始攻击你！"
D.Strings[3982]="%s从木屋中出来就发现你在粮仓捣鬼！"
D.Strings[3983]="越来越多的卡利姆多的生物正开始变得疯狂，而栖息其中的小动物并不友善。你走路时要多加小心。"
D.Strings[3984]="该死的……兽人。我忘记这些小丑了。跟他们打交道可不容易，所以做好战斗准备。赶快！"
D.Strings[3985]="快点达丹加！女孩快跑，快跑！"
D.Strings[3986]="就在那里——加基森！我们现在处于冲刺阶段！"
D.Strings[3987]="我们终于到了，多谢你，$n！没有你的帮助，我们没准已经被那些巨大的蜥蜴当作午餐了！"
D.Strings[3988]="货物非常多，但现在我可以再装载一些返回环形山了。我还可以卸载一不需要的部分货物。"
D.Strings[3989]="当心，敌人来了！"
D.Strings[3990]="我需要$n的一些帮助！"
D.Strings[3991]="是的是的，我知道达丹加不喜欢烟。但从它身上的气味来看，达丹加好像还不喜欢洗澡。"
D.Strings[3992]="你在附近见过皮塔斯或达丹加吗？"
D.Strings[3993]="他们动身去了加基森，帮我们取回一些物资。坦白地说，我原本有很多机会可以爬进达丹加的包裹中，离开这片不毛之地。"
D.Strings[3994]="魂精是什么?"
D.Strings[3995]="玛艾里的容器有很多秘密……用来制作它的碎片是可以反光的，你可以使用它的反光面从其它事物身上吸取能量然后反射到自己身上。$B$B将护符放在你的背包里可以让你聚集魂精，也就是与你战斗的野兽的灵魂力量。一旦你找到魂精，你把它带给玛艾里。"
D.Strings[3996]="魂精是每个生物都有的能量。我为你做的护符使你能以物理形态来抓到它。$B$B我知道一个可以转换你发现的魂精的咒语，并把它转换成魂能。$B$B你然后可以得到玛艾里的容器，并使用它把魂能的能量转换到自己身上。$B$B来吧，试一下。把玛艾里的魂精带来我们开心一下。"
D.Strings[3997]="虽然加基森跟安戈洛相比还不错，我有些伙计还指望我们给他们带来些补给。如果你准备好出发了，那达丹加和我也是。我们上马吧！"
D.Strings[3998]="塔纳利斯沙漠遍布巨大的骨头，就像我右边这个一样。我讨厌碰到那些东西。"
D.Strings[3999]="哦，哦，停下，达丹加，我的女孩。"
D.Strings[4000]="%s停下来时大声地喷着鼻息。"
D.Strings[4001]="这看起来不太……对头。沙漠实在是太陌生了！从这里通过可能是一个巨大的错误。"
D.Strings[4002]="什么……那些向我们爬过来的东西是什么？我们……我们正将遭受袭击！"
D.Strings[4003]="那不是我所说的“和平地护卫”。我会想办法绕开这些东西。我们朝南移动，向那块岩石走去。或许我们能从中穿过去并同时避开兽人。"
D.Strings[4004]="这会起作用的——继续穿越这条沟壑。一旦我们绕过这些地狱昆虫，通往安戈洛的道路就在这里正西边。"
D.Strings[4005]="这不可能！！！雷德，解决掉这些家伙。"
D.Strings[4006]="凡人战败了！黑石军团的新时代即将来临！"
D.Strings[4007]="%s从他的座龙身上摔了下来！"
D.Strings[4008]="这的确能省不少力。"
D.Strings[4009]="我想要这些靴子！都别碰那具尸体！"
D.Strings[4010]="你已经算幸运的了，凡人。至少你的尸体还比较完整。"
D.Strings[4011]="孩子，别把整个尸体都吃了！留着肚子吃些甜点吧！"
D.Strings[4012]="你真的以为你还有机会？"
D.Strings[4013]="黑手军团会将你们的皮制成饰品！"
D.Strings[4014]="酋长会除掉你的，凡人。做好准备吧！"
D.Strings[4015]="%s焦急地踱来踱去，等待着进行战斗。"
D.Strings[4016]="很荣幸……"
D.Strings[4017]="你好，$g小伙子:姑娘;。我可以帮你什么忙吗？"
D.Strings[4018]="你是来接受训练的吗？我也是刚刚开始学习这方面的知识，但是我很乐意把我所知道的教给你。"
D.Strings[4019]="你学得很快，$g小伙子:姑娘;，快得我已经远远跟不上你了。如果你想继续学习的话，我建议你去见见我的导师。他的名字叫洛特加斯，嗯，洛特加斯·石须。你可以在铁炉堡的大锻炉那里找到他。"
D.Strings[4020]="尝尝我的力量吧！"
D.Strings[4021]="嗯？我没时间聊天，我父亲要我完成这个使命。"
D.Strings[4022]="你确实有点本事。我打赌你的技术足够让你学些东西了，我们来看看我有什么能教给你的，好吗？"
D.Strings[4023]="你知道的比我还多，这一点很肯定。我告诉你接下来该怎么办，去和我的爸爸谈谈。他是个好的老师，但是他会要求你证明自己的实力。他的名字叫洛特加斯，你可以在本古斯的铁砧旁边找到他。"
D.Strings[4024]="我的朋友，你所掌握的技艺远胜于我。你为什么不去找我的老朋友洛特加斯·石须继续深造呢？我离开铁炉堡加入了吉安娜的军队，而他留了下来。我想他能教你点什么，至少他会知道谁能教你。如果他还待在铁炉堡的话，我想他一定在大锻炉附近。"
D.Strings[4025]="我该到哪里去寻找魂精？"
D.Strings[4026]="从冬泉谷的生物开始应该不错。$B$B然而，或许还有别的地方你可以看看……"
D.Strings[4027]="当然，我可以帮你进行训练。我也只是一个新手，但是我想我还是能对你有所帮助的。"
D.Strings[4028]="我不会轻易承认这一点的，不过你的确是个比我出色得多的铁匠。如果你想要学习更多高级的技能，我建议你去暴风城的矮人区找一个名叫瑟鲁姆·深炉的矮人。"
D.Strings[4029]="很抱歉，我现在有些忙，我要为湖畔镇的弗纳·奥斯古打造马蹄。"
D.Strings[4030]="我看上去像是有时间和你闲谈的样子吗？"
D.Strings[4031]="你还不坏，但让我耍耍几个小把戏，你可能会觉得很方便实用的。"
D.Strings[4032]="你已经是一个比我好得多的铁匠，那是肯定的。尽管如果你告诉其他人这点我会否认我曾说过。你该去找瑟鲁姆·深炉谈谈。如果有人能教你，那就是他。"
D.Strings[4033]="再让我听到一句关于水鸟的废话，我就把你打得生活不能自理。"
D.Strings[4034]="仅仅会挥动铁锤是无法成为铁匠的。把铁锤给我，在你让大家感到窘迫之前让我教教你好了。"
D.Strings[4035]="还行。去跟斯纳尔谈谈，他刚前往奥格瑞玛向萨鲁求学。去萨鲁的铁匠铺附近的战士区找他吧。他会对你进行测试，你最好做好准备。"
D.Strings[4036]="斯纳尔因为我动作慢了所以叫我。我只是想做好工作罢了，这得花时间的。"
D.Strings[4037]="我可以告诉你你想知道的一切，但是你必须要有耐心。去练习打铁吧，摸索用锤的力度。当你熟练后，自然也就掌握啦。"
D.Strings[4038]="你学得很快，这是件好事。但要注意按照工作的要求适当地完成工作。现在，我恐怕必须要把你送到斯纳尔那里多学些东西。你要学会所有他能教的，但不要听他的气话。当萨鲁的女儿笑话他时他就变成那样了。"
D.Strings[4039]="我在听，我在听，但是听不见卡恩所说的那些灵魂的声音。"
D.Strings[4040]="卡恩说我们需要聆听熔炉和钢铁的灵魂之声，它们会指引我们的。我只听见一阵铃声。拿起铁锤，让我们一起试着听它们在说什么。"
D.Strings[4041]="我猜那些灵魂更加喜欢你，我还没有听到他们的召唤但是你看起来已经上过他们好多课程了。去找卡恩谈谈，他会很高兴看到一个像他一样听到它们声音的人。"
D.Strings[4042]="我们并未丧失一切！毫无恐惧地跟这些野兽交战吧。我能为你医治伤口的，安抚痛苦。英雄们，振作起来吧！"
D.Strings[4043]="你的打扰在占用我的宝贵时间，你最好带来的是好消息。"
D.Strings[4044]="啊是的，另一个要烧炉火并锻造战斗武器的人。我当然会教你怎么操作。"
D.Strings[4045]="我的孩子，你学得很好。去幽暗城找一个名叫詹姆斯·范·布朗特的铁匠。他能传授给你更多的知识。我想他应该在战士训练大厅附近铸造武器。"
D.Strings[4046]="我希望有一天能用敌人的骨头制作武器。"
D.Strings[4047]="你不要用锤子傻乎乎地敲打铁砧，你应该是在制造一种可以杀死你的敌人的武器。让我给你演示一下你哪里做错了。"
D.Strings[4048]="你已经学得很多，我没什么能教你了。去找詹姆斯·范·布朗特，他会教给你我所不能的。"
D.Strings[4049]="你必须继续！他们的决心正在减弱。从我的身体中汲取力量并再次获得重生！"
D.Strings[4050]="魂能是什么?"
D.Strings[4051]="魂精是超自然力量的一种尚未汇聚起来的形态，而魂能则是浓缩的精华。通过使用一种强大的咒语，我可以把魂精变成魂能。一旦它变成魂能，你就可以使用玛艾里的容器把能量反射到你自己身上。"
D.Strings[4052]="我把玛艾里的容器弄丢了。我该怎么办？"
D.Strings[4053]="我很惊讶一个如此粗心的人竟然能走到这里……$B$B是的，你可能还有一个符咒，但是玛艾里对你的行为很生气！$B$B现在赶紧离开。"
D.Strings[4054]="你已经走了太远了，你将注定失败。后退，凡人。"
D.Strings[4055]="你会遭受失败的痛苦的，奈法利安！"
D.Strings[4056]="这东西应该管用的！至少它看上去管用！"
D.Strings[4057]="天哪！现在的温度是428,000克氏度！"
D.Strings[4058]="温度是9280克氏度！真热！"
D.Strings[4059]="温度是564克氏度。"
D.Strings[4060]="温度是122克氏度。"
D.Strings[4061]="温度是12克氏度。真令人激动。"
D.Strings[4062]="嗯，奥齐……那个似乎不太安全。"
D.Strings[4063]="奥齐！！天哪！"
D.Strings[4064]="连他的靴子都没留下……"
D.Strings[4065]="%s耸了耸肩。"
D.Strings[4066]="%s倒下了，但是它那破碎的躯体又挣扎着站了起来！"
D.Strings[4067]="这儿有活人！"
D.Strings[4068]="嗷！好吧，我回去工作，$n！"
D.Strings[4069]="当我饱受惊吓时，你将听到我大声喊叫……"
D.Strings[4070]="瓦拉斯塔兹，当黑龙统治世界的时候，你们这些龙就准备受死吧。"
D.Strings[4071]="但是现在，你必须死……"
D.Strings[4072]="你只不过消灭了一副幻象，蠢蛋。我会追踪你到天涯海角的。"
D.Strings[4073]="是的，似乎你已经学到了很多知识，你给我留下了深刻的印象。但是你知道想做我学生的人有多少吗？这样吧，帮我完成一项任务，我就教你。"
D.Strings[4074]="你掌握一些关于锤头和铁砧的技艺，但还不够。去找丹恩·林德雷谈谈，他会让你做好准备学习我教给你的知识。"
D.Strings[4075]="我说过你有铁匠的血统，看来我是对的。去铁炉堡大熔炉找一个名叫本古斯·深炉的矮人铁匠。他是我的老师，是我知道的最伟大的铁匠之一。"
D.Strings[4076]="铁匠的生活可不轻松，但是它能让你体格健壮，充满热情。我的父亲是一名铁匠，我的祖父曾经在格瑞姆巴托的炼铁炉工作。现在，我的儿子也跟随着我们的脚步，他让我倍感自豪。"
D.Strings[4077]="很抱歉，$g小伙子:姑娘;，你还不够资格在我这儿求学。去找我的儿子 格鲁姆，他会收你做学生的。"
D.Strings[4078]="你的技艺不是一无是处，但我在接纳你之前还需进行最后一次测试。"
D.Strings[4079]="是的，很高兴能教你如何锻造。系上围裙，拿起铁锤，看看我们能锻造出什么来？"
D.Strings[4080]="你是个有天分的学生，而且还是个有潜质的铁匠。我可以在本周任何时候宣布你可以从我这里毕业了。但是我觉得你还有东西要学。去找本古斯·深炉谈谈，他是个严厉的人，但他也是最出色的。"
D.Strings[4081]="%s高声喊叫。"
D.Strings[4082]="不要那样从阴暗中走出来。下次你要先给女生一点警示。"
D.Strings[4083]="自从阴影占据了暮色森林我就一直无法入睡。我总是被风中传来的可怕尖叫声惊醒。那听起来好像羔羊的叫声，而且声音从不会停止。"
D.Strings[4084]="呣，你的工作还可以，但是离我期盼的学生素质还差太远。去找闪金镇的铁匠阿古斯谈谈，我敢肯定他能教你一些基础知识。当你学完后再来找我，我会给你一次小测试以确定你准备好了。"
D.Strings[4085]="是的，我曾听到传言说我迟早会见到你的。但我不会随便接纳任何人的，我需要首先确定你的水准。你愿接受我的测试吗？"
D.Strings[4086]="你干得很漂亮，但是刀口还有些粗糙。不要担心，多加练习就会好的。说到这里，我们看看你一直以来的工作怎么样？"
D.Strings[4087]="现在我真是力不从心了，我说实话真是没什么可教你的了。但你知道谁可以吗？铁炉堡的本古斯·深炉，现在有一个矮人很了解他。到铁炉堡的大铁炉去找他，看看他是否想收个新学徒。"
D.Strings[4088]="要是我向萨鲁证明了自己的实力，他将别无选择，只能让我为他的一个女儿而战。让我们看看谁是失败的那个吧。"
D.Strings[4089]="离苏米和图米远点。他们会……极力推销他们的东西的。"
D.Strings[4090]="再次给我带来这种劣质货我就把你装在用山羊尿回过火的小铁盒里送回家。现在去见见那个傻瓜乌格索克，他更加适合你的需要。"
D.Strings[4091]="你认为自己够资格向我学习吗？你不过是我脚下的一名卑微的小人物罢了。但是，收纳一名下属或许能增加我对苏米和图米的吸引力。让我看看你拥有什么技能。"
D.Strings[4092]="嗯？啊是的，如果你期望的话我可以教你一些东西。但是要离苏米和图米远些，她们不喜欢像你这样的人。萨鲁只让那些技艺高超的人接近他的女儿。"
D.Strings[4093]="我没有什么东西可以教你了，现在你可以走了。不要想接近萨鲁，因为像你一样卑微的家伙，他只会用你们的血来炼钢。"
D.Strings[4094]="灵魂将你带到我这儿来，感谢他们。"
D.Strings[4095]="你需要多加留心灵魂的指引。你的道路取决于另一个人，雷霆崖的瑟拉格·石蹄。或许你们可以互相学习。"
D.Strings[4096]="告诉你，你准备好接受我为你安排的挑战了吗？幽灵告诉我你会通过的，但是你相信他们抑或是相信自己？"
D.Strings[4097]="一起来吧，我们将调整熔炉的火力，找出金属的真正形态。"
D.Strings[4098]="我们的人生之路只是暂时相交，现在是我们分道扬镳的时候啦。很荣幸能传授你知识，现在我送你上路，去找下一个导师吧。去奥格瑞玛找萨鲁·钢怒，他会教你你想学的知识。"
D.Strings[4099]="你有巨大的潜能，但你首先要理解，你必须接受精灵们并听从他们的召唤。只有那时你才会准备好走你要走的路。去找瑟拉格谈谈，我想你们可能会互相学习很多东西。"
D.Strings[4100]="你现在准备好把你我的命运联系在一起了，即使只有一小段时间。然而我们必须确定你明白精灵们所说的话。"
D.Strings[4101]="你已经学了很多，但我觉得精灵们还有很多要教给你。我可以给你引路但不能替你走路。去找到奥格瑞玛的萨鲁·钢怒，你的旅程的下一段从那里开始。"
D.Strings[4102]="你在浪费我的时间，去找我的学生巴兹尔谈谈吧。"
D.Strings[4103]="或许你明白这意味着什么，或许你不明白。如果你懂的话，我会传授知识给你。如果你不懂……嗯，那就这样吧。"
D.Strings[4104]="你制造的装备很不错，真的。去兽人的家园奥格瑞玛找一个名叫萨鲁·钢怒的铁匠吧。你必须给那些制造美丽的死亡器具的兽人一样东西。"
D.Strings[4105]="很抱歉$g小伙子:姑娘;，但是你基础不足，我不能教你。但是别烦恼，跟我的学生洛特加斯谈谈，他会帮助你的。"
D.Strings[4106]="看来你具有成为一名优秀铁匠的潜质。但是在我教你之前，我得知道你是否明白自己在做什么。"
D.Strings[4107]="我不能对你进行什么指导啦，你能用铁锤和铁砧做出如此令人称奇的东西。我建议你去找一个名叫布里克·基克拉夫的地精，你可别告诉别人,我最后一次听说他在藏宝海湾经营一家商店。"
D.Strings[4108]="这可不是一个年轻人玩的游戏！去外面找斯纳尔谈谈。他看上去或许有些阴险，但是他确实是使铁砧的好手。"
D.Strings[4109]="有些软弱、缺乏平衡性、缺乏自信。我不是说你所做的工作，年轻人，而是说你！你准备好学习如何成为一名真正的铁匠了吗？"
D.Strings[4110]="我发现你所掌握的炼钢知识已经比我多了。这很好，本该如此。现在你必须去人类领土南部的丛林，去地精城市藏宝海湾。你将在那儿找到一个名为布里克·基克拉夫的地精。我不喜欢地精，但他所掌握的炼钢知识却是无与伦比的。"
D.Strings[4111]="什么？我当然是一个铁匠。什么，你认为矮人是打铁最有效率的种族？好吧，可能是那样。去找一个矮人来帮你！"
D.Strings[4112]="你是在开玩笑吧？你一定是在开玩笑！你认为我是个取悦于你的小丑，是吗？我是小丑？嗯，是的！你认为我是小丑，是吧！"
D.Strings[4113]="好像这是我所见过的最好的垃圾。当然它还过得去，但我每天都看到这类‘还行’的东西。告诉你吧，你若能想办法让我叫好，我就会教给你能让矮人们在睡梦里都会笑的东西。"
D.Strings[4114]="我的朋友，你缺乏想象力，要是你能明白锻造它的方法，那么你就能生产、装送、配送给全世界的零售商。当然，那时你就得学做贸易了。现在，我们就先关注锻造这块吧，好吗？"
D.Strings[4115]="你的胜利不会长久。联盟和部落的日子都不长了！下次我们见面就是最后一次了。"
D.Strings[4116]="格里芬对首领说了什么？？格里芬可没说谎！她在那儿，试图窃取战役计划！"
D.Strings[4117]="格里芬做他的工作！格里芬现在离开！！！"
D.Strings[4118]="哦，开始起作用了！我敢打赌你觉得我会孤单，是吧？！"
D.Strings[4119]="哦！这比我预料的要多得多了，你随便吧，干柴！"
D.Strings[4120]="尽管我不愿承认，但是熊确实打败了我。我的天，那是一只体型庞大的熊！$b$b但是，如果你能打败那只熊的话，那可是一件值得骄傲的事儿！既便是我们中最好的猎人，也为此头痛不已。$b$b<他拍着你的背。>$b$b打败熊吧，你将成为旅行者营地中一名合格的成员的。"
D.Strings[4121]="在旅行者营地，我们最推崇狩猎技能。想获得我的赏识吗？你得靠行动来证明。$B$B面对挑战吧，$G小伙子:姑娘;！"
D.Strings[4122]="你已经成为一个出色的猎手了，$n！你不但证明了你的技能，你还胜过了达瑞尔，这是你在我的名册中得到了额外的分数！$B$B欢迎你随时来到这里。"
D.Strings[4123]="是你召唤我来的，愚蠢的东西！现在受死吧！"
D.Strings[4124]="挤“奶”吧，约翰。"
D.Strings[4125]="很愿意……只是让我再多回味一下这一刻。"
D.Strings[4126]="做吧……现在就做。"
D.Strings[4127]="他们在魔法区。去那幢恐怖的骷髅楼中找他们吧。"
D.Strings[4128]="我们知道他们在哪儿！他们就在城市外环魔法区的骷髅建筑物中。"
D.Strings[4129]="银行就在贸易区中心的塔中。你不会找不到的。"
D.Strings[4130]="我们只有一只眼睛，但看得比你远！银行就在幽暗城中心！"
D.Strings[4131]="贸易区上层的蝙蝠管理员。"
D.Strings[4132]="噢，你在寻找贸易区的克里斯托弗·德库尔。他在东部的平台上。"
D.Strings[4133]="我们加入公会了？没有？好吧，去贸易区的东平台找公会注册员吧。"
D.Strings[4134]="你得去贸易区找旅店老板诺曼谈谈。"
D.Strings[4135]="不能让邪恶势力有喘息的机会，但是我想你还是需要一些休息。去贸易区的上层找旅店老板诺曼吧。"
D.Strings[4136]="在交易区中心就有的邮箱……就在旅馆旁边。"
D.Strings[4137]="我们得确认一下是否碎……碎……碎灵斧是不是卖掉了。去贸易区上层的旅馆旁找邮箱吧。"
D.Strings[4138]="中央地带有拍卖行，就在南边。"
D.Strings[4139]="中部区域，南侧。去吧！"
D.Strings[4140]="洛丹伦废墟北面的飞艇塔楼上有个叫萨匹塔的小个子地精。离开幽暗城以后去找他，就可以去奥格瑞玛了。"
D.Strings[4141]="我们经常会看到一个兴登堡运营的气球停在废墟北面靠右的那座塔楼边上。它可以把你带到遥远的地方去，比如荆棘谷格罗姆高的丛林。"
D.Strings[4142]="牧师训练者？去军事区的外圈找找看。"
D.Strings[4143]="哼。军事区的邪恶的生物站在城市外圈的主建筑物周围。"
D.Strings[4144]="这肯定会让达瑞尔大吃一惊。是他活该，这个傲慢又该死的混蛋。但是哈！把这个给他瞧瞧，我迫不及待地想看看他脸上的表情。"
D.Strings[4145]="欢迎来到旅行者营地，$n！"
D.Strings[4146]="潜行者都在盗贼区外环的建筑物中。"
D.Strings[4147]="他们教我如何“妙手空空顺手牵羊”。你可以在幽暗城外围的盗贼区找到他们。"
D.Strings[4148]="你在这里永远都受欢迎，$n。谢谢你带来的欢笑--还有不要担心达瑞尔，他就是这样一个人！"
D.Strings[4149]="术士训练者在法师区外环中的建筑物中，他们跟法师呆在一起。"
D.Strings[4150]="我们想让地狱犬成为宠物。我们喂养它、善待它并教它学会去拣我丢出去的木棒。去城市外环的法师区找术士吧。"
D.Strings[4151]="在城市外围军事区建筑中。"
D.Strings[4152]="战士训练师都是作战高手。你可以去幽暗城外环的军事区找他们。"
D.Strings[4153]="你可以去炼金房看看。那是赫伯特·哈尔希医生和马尔什医生练习的地方。"
D.Strings[4154]="在我们出生之地炼金房的赫伯特·哈尔希医生的医术高于我们，他会医好你的背部的。"
D.Strings[4155]="内环军事区的詹姆斯·范·布朗特。"
D.Strings[4156]="詹姆斯·范·布朗特的工作地点在军事区内环。他能为我们打造很好的锁链。"
D.Strings[4157]="贸易区的那个尤奈斯·伯奇。"
D.Strings[4158]="尤奈斯·伯奇卖剩下的零部件。你可以到贸易区找她。"
D.Strings[4159]="到炼金房的内环去。拉文尼亚就在那儿。"
D.Strings[4160]="拉文尼亚女士教你制作魔法物品。她就在炼金房的内环。"
D.Strings[4161]="幽暗城外环盗贼区的弗兰克林·洛伊德。"
D.Strings[4162]="嗨，炸弹，我们喜欢炸弹。格拉哈姆·范·塔伦会教你如何制造炸弹的。他居住在盗贼区的外层。"
D.Strings[4163]="我们很了解玛丽·艾塔斯。她就在盗贼区的内环。"
D.Strings[4164]="当我们受伤时，她总为我们医治。你可以在盗贼区找到她。"
D.Strings[4165]="你在魔法区不会找不到阿曼德·克伦威尔的。他就站在码头上。"
D.Strings[4166]="阿曼德·克伦威尔在魔法区的码头附近垂钓。试试去那儿找他。"
D.Strings[4167]="你寻找的是马尔萨·奥列斯塔。她在炼金房的内环上。"
D.Strings[4168]="你需要去内环的炼金房。那就是马尔萨·奥列斯塔教你如何摘花的地方。"
D.Strings[4169]="他居住在盗贼区内环。"
D.Strings[4170]="盗贼区内环的亚瑟·摩尔能教你制革技能。"
D.Strings[4171]="到军事区的内环去。布罗姆·基里安在那里。"
D.Strings[4172]="布罗姆·基里安教你如何为挖掘出闪光的东西。他在军事区的内环。"
D.Strings[4173]="基里安·哈根在盗贼区传授剥皮的技能。"
D.Strings[4174]="你寻找乔瑟夫·格里高利。他在绿色运河的内环边上的魔法区里。"
D.Strings[4175]="嗯，那是个好主意。或许我们该到那儿去换一下我们身上的线？他的针线活做得很好。你可以在魔法区的内环里找到乔瑟夫·格里高利。"
D.Strings[4176]="哦，好的！给你，$n。我只能这么报答你了！"
D.Strings[4177]=S[18722]
D.Strings[4178]="其他大陆"
D.Strings[4179]="我们认为你需要帮助。"
D.Strings[4180]="我们帮助你找到他们。"
D.Strings[4181]="你似乎迷路了。"
D.Strings[4182]="我们听从命令。"
D.Strings[4183]="听一听长者的故事吧，$n。我有许多话要说……"
D.Strings[4184]="欢迎来到避难所，$n。有些人来这里是有目的，其余的是凑巧路过……但是每个到这里的人好像都有一个奇特的故事要讲。"
D.Strings[4185]="警惕些……阿纳克对恐怖图腾有一种奇怪的能力……他们看到我逃跑了是不会开心的。"
D.Strings[4186]="当心，恐怖图腾的成员快要过来了！"
D.Strings[4187]="他们来了。"
D.Strings[4188]="更多恐怖图腾的成员正在朝这边冲过来！"
D.Strings[4189]="终于自由了……我现在必须走了，谢谢你帮我逃脱。我自己会回到乱风岗去的。"
D.Strings[4190]="$n！你终于回来了！"
D.Strings[4191]="你好，$n。不要难过，好吗？"
D.Strings[4192]="我带来了狂暴的蓟熊，萨纳瑞恩。"
D.Strings[4193]="我想将堕落的猫交给温娜。"
D.Strings[4194]="净化吧！"
D.Strings[4195]="%s重新施放了净化法术。"
D.Strings[4196]="%s跳入月亮井中，潜入水底……"
D.Strings[4197]="%s顺从地跟随着$n。"
D.Strings[4198]="%s狂野地咆哮着。"
D.Strings[4199]="如果我们拒绝维护正义，那部落的存在还有什么意义？在我急需援助的时候，那些懦夫却不理不睬，$c。在十字路口，他们说怒火遮蔽了我的双眼，让我做出了不计后果的草率行动。$B$B<曼科里克向地上啐了一口。>$B$B他们看不到我能清晰看见的东西，也从不曾失去过我失去的东西。不报仇雪恨，我绝不罢休。"
D.Strings[4200]="谢谢你，$n。你安抚了我死去的妻子的灵魂，我将永远无法报答你的恩情。$B$B我想我会永远仇视野猪人，但是现在我已经得到了满足。$B$B我必须开始重建生活。"
D.Strings[4201]="%s指了指地上的羊皮纸。"
D.Strings[4202]="我很想看看这份水的样本有什么作用！"
D.Strings[4203]="%s把腐化的水泼到猫身上。"
D.Strings[4204]="哈哈！太完美了！"
D.Strings[4205]="%s被囚禁起来。"
D.Strings[4206]="使用手杖，告诉拆毁者怎么做！指出偷猎者！出击！"
D.Strings[4207]="看看这东西不牢靠的结构。你一定要念完咒语，否则你就只能召唤出这样的东西来。"
D.Strings[4208]="这个比上一个稍微好那么一点。但是它的骨架结构还是很脆弱。你能召唤出这样的东西，证明你还是在不断进步的。"
D.Strings[4209]="噢，这东西简直毫无用处。让我再试一次。"
D.Strings[4210]="嗯，这东西看起来做成风铃更合适。做好笔记，学生们……冲锋厮杀时你们可不能召唤出这样的玩意儿来。"
D.Strings[4211]="什么事情让你花了这么长的时间？"
D.Strings[4212]="挖掘一把野草需要多长时间？"
D.Strings[4213]="照这样的速度，我自己都能收集到足够的数量！"
D.Strings[4214]="如果你想要做什么事，就去做吧！"
D.Strings[4215]="好像我已经获得永生一样。"
D.Strings[4216]="啊，一定是他……不是？呸！"
D.Strings[4217]="或许我应该就从法鲁萨那儿购买一些？"
D.Strings[4218]="我必须去申请一个憎恶……一个憎恶！"
D.Strings[4219]="这具尸体属于一个女性兽人战士。$B$B很明显她是在战斗中死去的，或许是在对付这片地区的野猪人时死亡的。"
D.Strings[4220]="我将进一步检查尸体。"
D.Strings[4221]="你把尸体翻过来然后看到她武器上的标志——她的护甲已经都损毁了，她的头发披散在她的脸上。$B$B根据曼科里克对于她的描述，你可以确定这就是她的妻子。$B$B他一定会为这个消息而感到悲伤，但是你相信他还是希望知道真相的。"
D.Strings[4222]="快跑！"
D.Strings[4223]="别惹恼了我，否则我会用角刺穿你的！"
D.Strings[4224]="欢迎来到十字路口，$c。我叫索克——以酋长的名义，我负责在这儿进行防御。$B$B请你在这里随意一些。在你处理生意的时候，没人会对你占用空间有所异议的。$B$B我们的安全存在许多威胁。如果你想熟悉周围的情况的话，就跟其他人谈谈吧——或许他们会派给你一些任务的。"
D.Strings[4225]="<高图斯啐了一口唾沫。>$B$B我是部落的勇士，$n。让我愤怒的是得知我们的敌人正坐在离卡加斯不到一天路程的堡垒中，密谋着要对我们发起攻击。$B$B我渴望摆脱责任的束缚，以酋长的名义将他们消灭。$B$B但是，我们都有各自必须承担的职责。"
D.Strings[4226]="什么职责？"
D.Strings[4227]="你能以部落的名义冲锋陷阵，我可真羡慕你。我的职责是指挥部落的军队，而不是亲自上阵。$B$B当然，我年轻时也曾梦想着能安度晚年。现在，我痴迷于胜利的荣耀和失败的苦楚——这些都取决于我所指挥的士兵们。"
D.Strings[4228]="是梦境吗？"
D.Strings[4229]="我做梦了，$n……对，我做梦了。在梦中，我以上千种不同的方式死去。有人会认为这是噩梦，但我不这样想！在梦中，我在战场上死去。每次死亡之前我都会让一万名部落的敌人倒在我的脚下。这是无上的荣耀！"
D.Strings[4230]="我祈求能得到这样的经历。"
D.Strings[4231]="是的，看到你我就想起来了，$n。你让我想起往日的时光，我曾是部落的一名年轻的战士。$B$B毫无疑问，你将在你的一生中游历四方，征战沙场。$B$B<高图斯向你敬礼致意。>"
D.Strings[4232]="这样的赞扬我可承受不起，高图斯。"
D.Strings[4233]="谦虚点吧……或许现在是时候了，$n。你做好进入黑石要塞的准备了吗？你做好发动一场战争，摧毁他们大本营的准备了吗？"
D.Strings[4234]="长官！我将不惜一切代价来完成任务！"
D.Strings[4235]="我绝不会怀疑你的，$n。$B$B这些是给你的命令，$n。我知道你是不会让我失望的。"
D.Strings[4236]="是，长官！谢谢你，长官！"
D.Strings[4237]="%s向克朗·石蹄鞠躬"
D.Strings[4238]="%s攻击长矛！"
D.Strings[4239]="%s毁掉了长矛！"
D.Strings[4240]="%s和狼骑兵科尔让狼群停下来歇息饮水……"
D.Strings[4241]="%s和狼骑兵科尔冲向战场……"
D.Strings[4242]="%s瞄准目标……"
D.Strings[4243]="你好，年轻的$c。"
D.Strings[4244]="你好，伊崔格。我从黑石塔为你带来消息。"
D.Strings[4245]="雷德，是黑手的儿子，他是黑石氏族的酋长。他是一个十足的恶棍。$B$B当第二次大战结束时，雷德和他的兄弟麦姆逃往黑石塔要塞避难。雷德正是在那儿宣称自己为黑石氏族的酋长的。"
D.Strings[4246]="只有一个酋长，伊崔格！"
D.Strings[4247]="是的，年轻人，你不需要让我相信这些事情，酋长和我有很多过去的故事要说。然而你所做的贡献是众所周知的。$B$B就象我说的那样，雷德已经为他的人民找到了新的家园，我也是那些不知疲倦跟随他的人中的一员。$B$B那一次冲突激起了其它……其它无数的冲突。就是在黑石氏族和黑铁矮人为了黑石塔的战斗中我的两个儿子被杀害了。就在那时我意识到了我在黑石氏族的日子结束了。"
D.Strings[4248]="我走了。我不属于黑石。不，我的孩子不能白白死去。我不会在雷德这样无能、热衷于权利的疯子手下做事的。$B$B我隐居在壁炉谷附近洛丹伦的森林中。"
D.Strings[4249]="壁炉谷？？但是……"
D.Strings[4250]="<伊崔格笑了。>$B$B年轻人，世界不总是这么混乱不堪的。那只是亡灵天灾笼罩大地前的一段时间。在洛丹伦的那些地方在成为瘟疫之地之前。$B$B就是在那里萨尔从死亡之中拯救了我，也是在那里我加入了新的部落…但是我跑题了。这是另外一个时期的事。是的,另外一个时期……或许…"
D.Strings[4251]="伊崔格，我会帮你的忙的。"
D.Strings[4252]="我想你会的。或许有一天你能将消息传给我的一个老朋友。我听说他还在那片森林中。$B$B<伊崔格低下头，好像在做祈祷。>$B$B雷德，是的……雷德和他的兄弟麦姆统治了黑石塔，与黑铁矮人经常发生冲突。他们试图将黑铁矮人完全赶出城市的上层部分，但是只有在飞龙来到和麦姆死掉之后它才真正实现。"
D.Strings[4253]="啊，他们就是这样将黑铁驱逐到黑石塔下部的。"
D.Strings[4254]="事实上。奈法利安，死亡之翼的子嗣现在正统治着黑石塔。雷德受到龙的支配。$B$B只要你能设法穿过晋升大厅。$B$B<伊崔格叹息着。>$B$B此外，只有受到黑龙尊敬的人才有特权进入。"
D.Strings[4255]="或许还有别的方法进入？"
D.Strings[4256]="或许吧。年轻人，现在就出发吧。去找酋长，他肯定会乐意知道你的发现的。"
D.Strings[4257]="如你所愿，伊崔格。"
D.Strings[4258]="哈夫纳！托泰克! 站住，跟我谈谈。"
D.Strings[4259]="428,000克氏度……怎么回事，这么热？"
D.Strings[4260]="叮当！428,000克氏度！精确数值！好吧，近似数值。差不多吧。大概是这个数……"
D.Strings[4261]="要是按照克氏度计算的话，有428,000度！"
D.Strings[4262]="18克氏度。实际上有些冷……"
D.Strings[4263]="40克氏度。你觉得热吗？不觉得？我也不觉得。"
D.Strings[4264]="啧啧，现在是3克氏度。继续找吧。"
D.Strings[4265]="这里满是这些愚蠢的家伙的尸骸，这令酋长非常愤怒。"
D.Strings[4266]="为你们的英雄而欢庆！就在今天，他们给了我们最可恨的一个敌人一次重击！那个假的酋长，雷德·黑手，已经倒下了！"
D.Strings[4267]="沐浴在我的力量中吧！吸取我的力量！为了部落的荣耀而战！"
D.Strings[4268]="沐浴在酋长的力量中吧！吸取他的力量！为了部落的荣耀而战！"
D.Strings[4269]="试炼谷能将最软弱的新兵锻炼成一名合格的部落战士。无法通过试炼者将被抛弃，独自忍受骄阳的煎烤。"
D.Strings[4270]="将雷德的徽记放到树桩上。"
D.Strings[4271]="你好，$n。我是克罗诺姆，但是你可以叫我克罗米。我喜欢这种亲密感。$B$B现在——你问我是怎么知道你的名字的？我是青铜龙军团的一员，永远与时间的消长相合。你可以认为我们以前遇到过。从这个角度说，我们还会再见面。"
D.Strings[4272]="嗨，又见面了，$n。我感觉时间流仍处在强大力量的威胁之下。青铜龙始终欢迎你不断地提供帮助。$B$B虽然过去的事情已无法改变，但是将来却变化莫测。你此刻做出的决定将改变未来。"
D.Strings[4273]="我想让你们俩在更年轻的学生面前展示我教给你们的种种技能。准备……开始！"
D.Strings[4274]="这是我出发的地方，傻子！"
D.Strings[4275]="告诉雷克斯洛特如果他想得到情报，他就必须付钱！不幸的是，那意味着他如果想要情报就不能杀我——因为我已经烧掉了战斗计划和所有的东西……"
D.Strings[4276]="听你的长辈的话，$n。要是你拥有强大的意志和热情，就没有不能控制的力量。"
D.Strings[4277]="并不是所有的被遗忘者都屈从于希尔瓦娜斯的意志，$n。我们中的某些人是被真正的力量驱动的——我们为自己赢得的力量。"
D.Strings[4278]="你们俩说够了没！战斗开始了！"
D.Strings[4279]="现在不是时候，$n。$B$B你疯了吗？！"
D.Strings[4280]="现在……不……是……最好的……时候，$n。我必须集中……精力。"
D.Strings[4281]="你的使命一定意义非凡，$c，它需要你深入沼泽……"
D.Strings[4282]="地狱火是术士在$G他:她;在战斗中所能使用最强大的恶魔。这个怪物很强大，护甲很厚，并能给任何敌人造成极大的伤害。如果你想把地狱火的灵魂加到你的武器上，你就会得到那些好处——更多的生命值和更快的生命恢复速度。$B$B如果你想了解更多关于地狱犬的事，那你就该与我对面的温图拉谈谈。"
D.Strings[4283]="地狱犬……确实是一个邪恶的生物。它不像地狱火那样强壮，但是聪明的术士知道蛮力不总是解决的办法——如果是，你就会选择战士了，不是吗？$B$B地狱犬利用敌人的法力，用它和它的迅速来战胜敌人。它的力量来自奥术并利用那种奥术能量为自己谋利。$B$B如果你想得知更多关于地狱火的事，那么你该找我对面的玛迦兹谈谈。"
D.Strings[4284]="%s从时间裂隙中钻了出来！"
D.Strings[4285]="你跟塔里的侍僧说过话了吗，$n？除非你能完成他们之中某个人的任务，否则我们就无法为你制作宝珠。如果你准备好了的话，就去跟他们谈谈吧。"
D.Strings[4286]="帮我杀死N！"
D.Strings[4287]="别让这个$n伤害我！我必须平安返回家园。"
D.Strings[4288]="别让我丧命！"
D.Strings[4289]="%s痛苦地呼唤着恋人的名字，冲了出去！"
D.Strings[4290]="%s响应着希洛塔姆的呼唤。"
D.Strings[4291]="我的$g兄弟:姐妹;帮帮我吧……$B$B我很快就将离开这个世界了，虽然我饱受苦楚，但是我知道死了之后所有痛苦都将解除。但是，那些野生生物，我的$g兄弟:姐妹;……也历经折磨，永无止境。在我生命的最后一刻，我请求你的帮助。"
D.Strings[4292]="是的，我讲的语言你听得懂$r。我们不是动物，然而你们中大多数却仍然把我们像动物一样对待！可是我们的分歧比起降临到这片土地上的悲剧来显得微不足道。恳请你们把与我们存在的分歧搁置一边，倾听一下我临死前的请求。$B$B我来到这片土地尽我所能改善状况，而现在除非你能帮我，否则那即将要化为泡影。我用我生命的最后一息请你帮这个忙。"
D.Strings[4293]="“……”$B$B牛头人德鲁伊的尸体静静地躺着，看起来他好像终于离开了这个世界。"
D.Strings[4294]="你们都是些不值一提的渣滓！"
D.Strings[4295]="蠢货！我们的事业是正义的！"
D.Strings[4296]="胜利属于兄弟会！"
D.Strings[4297]="这些讨厌的侏儒！我被困在这儿好几个月了。谢谢你。"
D.Strings[4298]="谁敢踏入我的领地！来！来被消灭吧！"
D.Strings[4299]="居住于塞纳里奥区的德鲁伊一直在大德鲁伊鹿盔的领导下警惕地保卫着自然界。你可以在达那苏斯北部找到他和别的德鲁伊训练师。"
D.Strings[4300]="我是这座城市的官员，从事幽暗城的人口普查工作。自从我们从亡灵天灾中解脱出来以后，我们就尽力对我们的城市人口做出精确的记录。通过一些奥术方式和聪明的方法，我才得以弄到这些记录。如果你需要有事找我的话，请继续。你应该知道你是否有事需要我的帮助。"
D.Strings[4301]="酋长指示我学习各种武器和护甲知识。他把我派遣到这兽人和牛头人文明的集合之地，接触尽可能多的旅行者，学习整个贫瘠之地的文明。$B$B他认为即使是最未开化的文明也有值得学习的地方——比如野猪人和半人马。"
D.Strings[4302]="你投降了。我赢了。"
D.Strings[4303]="现在来个战争践踏！干得好！"
D.Strings[4304]="那就是完成的方法！你最好认真听讲！"
D.Strings[4305]="现在放下你的蹄子！"
D.Strings[4306]="你！$R！过来。<喷鼻声>$B$B时间短暂，而我的末日<喷鼻声>就要来临了。碎牙会赢；你会看到的。<喷鼻声>$B$B我的战利品还可以帮助<喷鼻声>我的人民。钢鬃部落要比刺背野猪人更加强大！$B$B部落正期望找出由谁来带领人民发动袭击。你<喷鼻声>作为回报要援助碎牙，告诉他只有我才知道的信息。碎牙能帮你！<喷鼻声>但你必须帮助碎牙。"
D.Strings[4307]="欢迎来到暴风城！我是城市的一名长官，帮助城市的人口调查局登记居民。如果你想找人的话，我也许能帮上你。我能运用奥术和智慧拿到这些记录。$B$B如果你找我有事的话，那就开口吧！"
D.Strings[4308]="我怀着深深的仇恨<哼>，但是是时候告诉你了，$r。$B$B很久之前，众神之间爆发了一场战争。我们伟大的野猪神阿迦玛甘在史前战争中战败，鲜血四溅，骨肉横飞。<哼>$B$B当他的鲜血流到地面上时，巨大的荆棘破土而出，他的徽记装饰着此地以南的洞穴。"
D.Strings[4309]="吆……我需要一根烟和找个好看的侏儒女人摸几下--倒不必非要按那个顺序！$B$B我被困在那个东西的肚子里已经有几个月了。今天几号了？啊，不要紧。重要的是我终于出来了。$B$B呜呼！"
D.Strings[4310]="你究竟是怎么进去的？"
D.Strings[4311]="怎么进去的？？嗯，这故事真长。"
D.Strings[4312]="好吧！我在熔岩大桥的熔岩坑测试熔岩服。一切进展顺利。我甚至能在熔岩中毫发无损地游泳！$B$B我在那儿做自己的事，有时仰泳一会，突然之间它把我一口吞没！若不是有了熔岩服和便携式食物机，我一定会就此交待了！"
D.Strings[4313]="让我搞搞清楚。你穿着这件……这件熔岩服，在火红的岩浆里面游泳，不，仰泳？而且在毫无察觉的情况下，被这只野兽吞下了肚？"
D.Strings[4314]="我说，我感觉你对此充满怀疑——但是，那就是事情的经过。"
D.Strings[4315]="我才从这野兽的肚腹之中出来还不到两分钟，就有人问起我如厕的问题？？？$G先生:小姐;，如果你不是救我的那个人，我一定早就把你敲傻掉了！$B$B无论如何！我很感谢你的帮助。或许我能回报你？"
D.Strings[4316]="哦？"
D.Strings[4317]="嗯，或许报酬这个词不是最合适的说法。当我在那东西的肚腹之中时，我在想：$B$B这家伙生活在灼热的岩浆中，火焰却不能伤害它一丝一毫！$B$B如果我能找到这样一块兽皮的话，我就把它交给我在永望镇的朋友玛雷弗斯·暗锤。如果说有人能处理这种兽皮的话，那个人就是他。"
D.Strings[4318]="下次再遇到这种事情的时候我会好好考虑一下的。"
D.Strings[4319]="帮我送个信怎么样？"
D.Strings[4320]="Ish nu！够了！"
D.Strings[4321]="我想，你应该去玛雷弗斯那里。"
D.Strings[4322]="想买蟑螂吗？"
D.Strings[4323]="你不能唤醒沉睡者！"
D.Strings[4324]="死亡的纠缠会让你彻底湮灭！"
D.Strings[4325]="我是毒蛇之王！我无所不能！"
D.Strings[4326]="没有人能对抗毒蛇之王！"
D.Strings[4327]="很好，很好。现在互相鞠躬。"
D.Strings[4328]="向我鞠躬。"
D.Strings[4329]="干得好。现在请坐吧。"
D.Strings[4330]="哈！我复仇了！"
D.Strings[4331]="%s小心地瞄准目标……"
D.Strings[4332]="%s选择了兽人目标……"
D.Strings[4333]="%s再次瞄准目标……"
D.Strings[4334]="%s最后一次瞄准目标……"
D.Strings[4335]="我的时间不多了……我们的时间都不多了……"
D.Strings[4336]="我有很多要做的……在瘟疫来之前有很多……"
D.Strings[4337]="约翰，亲爱的，你在哪里？"
D.Strings[4338]="每个人都是怎么了？我感到……很冷……"
D.Strings[4339]="精灵用一种从前没有过的审视感觉看着你。$B$B“我感到一个大负担从我的灵魂中消除。很快我就可以永远平静的休息了。我现在知道这一点，而且我耐心的等待着这一时刻。$B$B谢谢你，陌生人。”"
D.Strings[4340]="又倒下了一个！"
D.Strings[4341]="你对<猪哼声>碎牙的帮助比我想象的要大得多，$r。$B$B谢谢你。$B$B只要我还是这里的俘虏，你就可以从刺背野猪人那里给我拿血岩碎片来换取阿迦玛甘的力量。"
D.Strings[4342]="%s心不在焉地瞄准兽人靶子……"
D.Strings[4343]="%s吹散枪管中冒出的烟……"
D.Strings[4344]="%s瞄准了瓶子……"
D.Strings[4345]="%s再次瞄准了瓶子……"
D.Strings[4346]="%s只击中了盒子的侧面！"
D.Strings[4347]="%s迅速瞄准目标的要害并射击……"
D.Strings[4348]="啊！乌洛克死了！哈哈！！"
D.Strings[4349]="我要报仇！"
D.Strings[4350]="瑟银兄弟会是不会在蚂蚁身上浪费时间的。快滚开！"
D.Strings[4351]="告诉我关于那块皮的事情。"
D.Strings[4352]="对我这样的工匠来说，制造的流程本身是很简单的。$B$B困难之处在于获得原料。如果你能为我取回一块完美的比斯巨兽的皮，我就能用它制作出一些强大的装备。"
D.Strings[4353]="我如何才能获得比斯巨兽的皮呢？"
D.Strings[4354]="我估计获得这样一件东西的概率是百万分之一！一件让你终身受用的兽皮！即使是技艺最高超的工匠也不一定能剥出一张完美的皮来！"
D.Strings[4355]="假设我已经得到了比斯巨兽的皮，那么你还需要什么东西吗？你能用它做些什么？"
D.Strings[4356]="要是你真的带来了那张皮？嗯……让我为你展示一番吧……"
D.Strings[4357]="%s转向纸人靶子……"
D.Strings[4358]="%s迅速射击兽人模型……"
D.Strings[4359]="%s冒冒失失地朝着瓶子射击……"
D.Strings[4360]="浏览一下我的目录，$n。"
D.Strings[4361]="%s没击中……"
D.Strings[4362]="%s又没击中……"
D.Strings[4363]="%s击中了！"
D.Strings[4364]="离开战斗"
D.Strings[4365]="瑟银兄弟会的目录：$B$B你可以从中找到所有你冒险必需的最强装备！我们还将告诉你到哪儿去收集这些材料。"
D.Strings[4366]="关于磨损的憎恶缝合线的章节。"
D.Strings[4367]="关于魔化红线的章节。"
D.Strings[4368]="关于莱斯·霜语的防腐液的章节。"
D.Strings[4369]="注意！准备战斗！"
D.Strings[4370]="提米！"
D.Strings[4371]="关于奥术水晶和奥金的章节。"
D.Strings[4372]="你接受我的投降了。"
D.Strings[4373]="请跟着我。"
D.Strings[4374]="我并没有真正弄明白这是什么，但那些温泉却有些奇怪……"
D.Strings[4375]="%s把剑扔进浅水池。"
D.Strings[4376]="我发现当我把什么东西扔进水里然后再拿回它时，它已经明显变大了。"
D.Strings[4377]="好吧，不管它是什么，效果很好！"
D.Strings[4378]="而我下决心要找出更多相关的东西……如果你还需要我的帮助，你知道我会在哪里。"
D.Strings[4379]="这本书的标题是手写体：莫琳·达尔松的日记。"
D.Strings[4380]="一本打开的日记放在你的面前，发黄的书页上写着如下的文字：$B$B“哈洛德变成了这个样子，我不知道接下来会发生什么事。把他拖进我能找到的唯一可以关住他的地方之后，我已经心力憔悴了。我把钥匙藏在身上，祈祷能渡过这个难关……$B$B我希望能离开这里，但我需要钱。我想我们的东西都在那个柜橱里……现在我想起来了，哈罗德是不是把柜橱的钥匙藏在自己身上了？$B$B我要先休息一下，现在我实在是太疲倦了。”"
D.Strings[4381]="关于暗影之皮的章节。"
D.Strings[4382]="入侵者到达偏门了！赶快通知瑞文戴尔男爵！"
D.Strings[4383]="要是你想要磨损的憎恶缝合线，你就得长途跋涉去斯坦索姆。$B$B以前那儿是光明使者的家园，现在被克尔苏加德的仆从们侵占了。$B$B解除这燃烧的城市的危机，击败那些强大的憎恶吧！从他们那儿夺取磨损的憎恶缝合线！"
D.Strings[4384]="那些疯狂的信徒的最后一处圣地。他们在那制作红色制服，使用的就是魔化红线！$B$B冒险家们，向斯坦索姆城前进！"
D.Strings[4385]="人类和亡灵天灾所知的最好的肉类防腐剂——莱斯·霜语的防腐液。这种防腐剂只能在一个地方找到，人们认为这东西得名于巫妖，要去那种地方一定不是件容易的事儿。$B$B但是……如果这正是你想要的东西，就去通灵学院吧……"
D.Strings[4386]="巴罗夫家族将通灵学院所在的土地给了克尔苏加德。作为交换这块诅咒神教可以研究亡灵天灾堕落法术的地方，克尔苏加德让巴罗夫家族以亡灵的形式获得永生。$B$B在阴影拱顶房间中，你能找到暗影之皮及其拥有者伊露希亚·巴罗夫。$B$B你无法找到比暗影之皮更好反射虚无和死亡的镜子了。"
D.Strings[4387]="瑟银兄弟会。$B$B奥术水晶是从富瑟银矿脉中采集的。通过强大的炼金师的威力，奥金诞生了。$B$B找出一个矿工，如果你不是的话……还有找到一个出色的炼金术士！你两样都会需要的。"
D.Strings[4388]="%s来回焦急地踱步。"
D.Strings[4389]="你们不该来这里！杀了他们！"
D.Strings[4390]="死不足惜。"
D.Strings[4391]="谁敢打扰我的冥思？"
D.Strings[4392]="篡位者！诺莫瑞根是我的！"
D.Strings[4393]="我的机器代表未来！它们会将你们统统摧毁的！"
D.Strings[4394]="站着别动！"
D.Strings[4395]="电刑！"
D.Strings[4396]="胜利！为阿迦玛甘而战！"
D.Strings[4397]="讨厌的家伙。我会给你些颜色看看的！"
D.Strings[4398]="你们这些自不量力的家伙会为侵犯我们的领地付出代价的！"
D.Strings[4399]="哈！我的力量统治着这里！"
D.Strings[4400]="我们的新盟友会为我们复仇的！"
D.Strings[4401]="兄弟们，杀了他们！为了亡灵天灾而战！"
D.Strings[4402]="我闻到活人的臭气！"
D.Strings[4403]="我要把你们统统吃掉！"
D.Strings[4404]="你不会从这儿活着出去的。"
D.Strings[4405]="到我这儿来，仆从们！"
D.Strings[4406]="来吧，帮助你们的主人！"
D.Strings[4407]="我会用黑石的力量打碎你的头骨。"
D.Strings[4408]="我是巫妖王的得力助手！"
D.Strings[4409]="%s擦着额头。"
D.Strings[4410]="啊——给我来一次真正的挑战吧！"
D.Strings[4411]="圣光，赐予我力量吧！"
D.Strings[4412]="圣光会审判你！"
D.Strings[4413]="你不能玷污这些神迹！"
D.Strings[4414]="让正义的火焰吞噬你吧！"
D.Strings[4415]="告诉我……告诉我所有的事情！"
D.Strings[4416]="让痛苦来净化你吧！"
D.Strings[4417]="在我面前没有秘密可言！"
D.Strings[4418]="我要从你的肉体中把秘密都挖出来！"
D.Strings[4419]="看看这个，玛雷弗斯。"
D.Strings[4420]="那是什么， $n？$B$B<玛雷弗斯指着你从包裹里拿出来的未淬火的板甲护手。>"
D.Strings[4421]="别忘记从箱中的瓶子里面取出瓶中火。你必须用它来破坏他们指挥官的帐篷。"
D.Strings[4422]="以索瑞森胡子的名义！杀死他们！"
D.Strings[4423]="我，格瑞姆洛克，是国王！"
D.Strings[4424]="死吧！死吧！"
D.Strings[4425]="鲁莽的蠢货！"
D.Strings[4426]="我要吃掉你的骨头！"
D.Strings[4427]="夺灵者来了！"
D.Strings[4428]="哈卡会重生的！"
D.Strings[4429]="回去！不要唤醒沉睡者！"
D.Strings[4430]="流沙会吞噬你的！"
D.Strings[4431]="倒下吧！"
D.Strings[4432]="让裁决开始执行吧！"
D.Strings[4433]="正义得到了伸张！"
D.Strings[4434]="这片沙漠是属于我的！"
D.Strings[4435]="死吧，外来者！"
D.Strings[4436]="感受沙漠的狂怒吧！"
D.Strings[4437]="沙怒部族拥有至高无上的统治权！"
D.Strings[4438]="欢迎来到前线，$c。那些只知道策划阴谋的政客们会发现，他们的那一套在这里是行不通的。这儿是亡灵壁垒，我们必须日复一日地为生存而战斗。$B$B如果你想证明自己是个英雄的话，你会在这儿找到数不清的机遇。"
D.Strings[4439]="欢迎来到前线，$c。暴风城及其盟国派我到这儿来对抗亡灵天灾。在寒风营地，我们日复一日在抗战中求生。$B$B如果你想证明自己是个英雄的话，机会是很多的……特别是在我们向安多哈尔和控制亡灵天灾的邪恶势力进军时，你可以好好把握。"
D.Strings[4440]="你肯定自己没有被跟踪？我突然有种不祥的预感……"
D.Strings[4441]="提高警惕！"
D.Strings[4442]="我们被出卖了！"
D.Strings[4443]="很高兴看到又有人在斯坦索姆城中和亡灵天灾作战，在这里，亡灵的力量是极其强大的。$B$B$n，你好，我是奥里克斯。我曾经是白银之手骑士团的一名圣骑士，但是与其他信念发生动摇的圣骑士一样……我堕落了。亡灵天灾诱惑了我，差点使我成为一名死亡骑士！$B$B最终，我感觉到自己的危险处境，逃到了这个教堂。这是一个神圣的地方，第一圣骑士乌瑟尔·光明使者就是在这里成为了白银之手骑士团的首领。"
D.Strings[4444]="瑞文戴尔！我来挑战你！"
D.Strings[4445]="我的时间不多了，但是圣光依然照耀着这个世界，它可以帮助我完成我的宿命。当你面对瑞文戴尔男爵时，我便与你同在。"
D.Strings[4446]="别管我。我伤得很重，可能会丢掉性命。谢谢你，$n。我将死在这儿，但是因为你……我能在平静中死去。"
D.Strings[4447]="凡人，别考验我的耐性。"
D.Strings[4448]="你一定要原谅我，罗拉克斯，我没有“疯狂”地说什么。"
D.Strings[4449]="咬住你的舌头，$r，以免我把它拽下来用来擦拭我的犄角。"
D.Strings[4450]="很抱歉，我没有意识到你可以理解我说的话。你在这儿做什么？"
D.Strings[4451]="事实是我当然那样做。我思考。我哀悼。我痛恨。我谋划。当那个周期结束后，我又一次陷入沉思。你想从我这儿得到什么？我脑子里可有很多东西。"
D.Strings[4452]="是吗？或许你该告诉我是什么让你烦恼。"
D.Strings[4453]="你?$B$B<罗拉克斯笑了。>$B$B这很令人怀疑。$B$B我站在这些废墟和梦想之中。梦想着我捉住那个可怜的贼——古拉鲁克的那一天。$B$B我们达成了一项协议，他和我。但他违背了我们的协议。他背叛了我。"
D.Strings[4454]="什么交易？"
D.Strings[4455]="我将教他如何去恶魔熔炉交换他的灵魂。黑石兽人的灵魂根本不值钱，但是在眼下这个艰难时代，有总比没有好。"
D.Strings[4456]="他是怎么破坏协议的？"
D.Strings[4457]="他拿走了那块未铸造的符文胸甲，用于制造魔铸胸甲，并且没有付钱就跑掉了。我不是傻瓜，但是……没有配方的话，那块未铸造的符文胸甲一文不值。$B$B我在想……他是否安全地呆在黑石塔里，试图制造点什么出来？我知道他不敢离开！"
D.Strings[4458]="或许我能帮上忙。萨特，我们来谈笔交易吧。我去取回这块未铸造的胸甲并杀死野兽古拉鲁克。作为交换，你要教我如何制造胸甲。"
D.Strings[4459]="我品尝了生命的血液！"
D.Strings[4460]="我即将重生！"
D.Strings[4461]="哈卡重生了！"
D.Strings[4462]="%s碎了，失去了力量！"
D.Strings[4463]="当你靠近时，那些液体和混合物剧烈地翻腾起来。设备旁边是一把巨大的钳子，似乎很适合用来夹起淤泥样本。$B$B还有安全齿轮装备，但是上面布满灰尘，似乎很久没有使用过了。$B$B将一些样本放进烧杯吗？"
D.Strings[4464]="%s爆破，释放出数个绿汁软泥怪！"
D.Strings[4465]="%s喷出一股令人恶心的绿汁软泥！"
D.Strings[4466]="哈哈，$n！我永远不会忘记达瑞尔看到你时他脸上的表情！"
D.Strings[4467]="离开这儿！"
D.Strings[4468]="傻瓜，轮到我了！我要投掷了。"
D.Strings[4469]="你已经掷过最后一颗了，笨蛋。现在该我了。"
D.Strings[4470]="%s开始互相推攘起来。"
D.Strings[4471]="达丹加喜欢吃什么？"
D.Strings[4472]="从我们呆在环形山这里开始，达丹加就喜欢上了遍布这里的巨大的血瓣花苗芽。$B$B我敢肯定她会喜欢，如果你愿意带给她一大堆花苗芽的话……"
D.Strings[4473]="好，好！轮到你了！"
D.Strings[4474]="嗨，只要我手头的物资能够再多一些，我就能立刻给你修理好！"
D.Strings[4475]="在这里志愿工作就是我通过巫医学校课程的方式。既然你帮了我，我就免费帮你。需要修理什么吗？"
D.Strings[4476]="情绪低落"
D.Strings[4477]="%s不安地喘着气。"
D.Strings[4478]="%s大声呼救。"
D.Strings[4479]="我……我受了重伤……"
D.Strings[4480]="救救我……"
D.Strings[4481]="你会没事的，奥比。攻击你的人已经被杀死了。"
D.Strings[4482]="听着，$r。听好了……$B$B龙骑士骑着黑龙，趁着夜色而来。他们迅速出击，给予幼龙——像我这样经验不足的幼龙——致命而精确的攻击。$B$B我怀着极大的恐惧注视着我的兄弟姐妹被他们用在实验中。我们的精华能创造出多彩龙人。"
D.Strings[4483]="请继续……"
D.Strings[4484]="奈法利安已经下令立即杀死那些不合适的实验品，但是这些恶心的野兽在没有对我们反复摧残之前是不会这样做的。$B$B当我们被彻底折磨完了之后，他们会将我们丢给那些杀手。我们的身体将成为他们游戏的道具：被投掷到熔岩中，或是丢弃到开阔地带，等待着被嗜血如命的军团砍杀。"
D.Strings[4485]="太可怕了。"
D.Strings[4486]="就在他们要把我扔给下面的魔鬼时你来了——为此我感谢你。或许，我——更确切的说——我们，蓝龙是不是可以进一步帮你？$B$B你已经走到这一步，$r，冒了很多险。你还愿去参加抵抗奈法利安和他的黑石军团的战斗吗？"
D.Strings[4487]="你救不了他！"
D.Strings[4488]="坏的悬钉"
D.Strings[4489]="感到动力不足"
D.Strings[4490]="丛林热"
D.Strings[4491]="独眉"
D.Strings[4492]="鞭打"
D.Strings[4493]="我不想回去工作"
D.Strings[4494]="阿莎利水晶已经被摧毁了！屠宰场危险！"
D.Strings[4495]="如果你到这儿来猎龙，那你就是我的客人了。我应该去哪里表示我的哀悼？"
D.Strings[4496]="你的臭气会把数英里内的所有龙都招来的。告诉我你想要什么，快些。"
D.Strings[4497]="灵魂告诉我说你会来的，你会出于某种原因来此寻找我，但是你也许自己都不清楚这个原因。那么，你知道你为什么会在这儿吗？"
D.Strings[4498]="哦你好！我的名字是萨拉。我能为你做什么吗？"
D.Strings[4499]="森林告知我你的存在，但是没有说你为什么在这里。那么，告诉我真相吧。"
D.Strings[4500]="你做得怎么样啦！"
D.Strings[4501]="翡翠议会欢迎你，$n。$B$B希望我们能一起恢复并保护这片曾经繁茂的森林。许多势力试图从外部和……内部毁灭它。$B$B不要被这里的邪恶力量打败——它会腐蚀你，就它腐蚀这片土地一样。"
D.Strings[4502]="当格雷塔集中精力恢复加德纳尔和对付那些她认为最应该对费伍德森林的堕落负责任的人的时候，我正忙于调查堕落给这片土地带来的影响。$B$B它是如何影响地面上的生物的？该采取什么办法来结束它们所遭受的痛苦？$B$B不幸的是，堕落已经如此深入，永久的沉睡似乎是绝对的答案。"
D.Strings[4503]="他在法师区，那儿有一间名叫炼金材料店的小商店。你会在前往法师区的沿途看到各种各样奇怪的商店，但是如果你沿着外围走的话，你一定会找到它的。"
D.Strings[4504]="暴风城的暴风城会计室位于城中贸易区的前门处。当你厌烦细数你的金钱时，一定要在镶金玫瑰喝一杯。"
D.Strings[4505]="你说你不能在这儿闻到矮人煅炉的烟味？哦，如果你想学习锻造的话就该找瑟鲁姆·深炉。他就在大教堂广场北边的矮人区。"
D.Strings[4506]="%s惊骇地跳起来！"
D.Strings[4507]="你个尖酸的刻薄鬼！谁把这个给你的？"
D.Strings[4508]="是乌米，是吗？？她总是跟我开玩笑，现在也让你参与到玩笑之中了！"
D.Strings[4509]="啊！！！那是什么东西？！"
D.Strings[4510]="乌米派你来的，是吗？！她告诉我会有一个惊喜，但是我从没想到她是这个意思！"
D.Strings[4511]="有一名优秀的厨师在旧城区的猪与哨声旅店工作。我曾在他身旁看他在烹饪时使用刀具，但是我可不认为他只是一名厨师。别误会我的意思……如果你想学厨艺的话，他会是你最好的老师。"
D.Strings[4512]="啊，你是在找鲁坎·考迪尔。他在魔法区外开了一家商店，你前往监狱时会经过那儿的。"
D.Strings[4513]="%s试图寻求帮助！"
D.Strings[4514]="嗨，提醒我啦，我需要修理一下火箭靴。聪明人一点就通啦，不要把火箭靴和狮鹫混淆的。\n\n哦，让我为你指明方向……穿过矮人区，你就会找到利廉姆·火轴啦。"
D.Strings[4515]="要学急救的话，没有比光明大教堂的安吉拉·雷菲德更好的老师了。\n\n去找她吧，你只寻找黄色的屋顶或者教堂本身的尖顶就行了，在城中的任何角落都能看到这些标志。"
D.Strings[4516]="啊呀！把那东西从我这儿拿走！"
D.Strings[4517]="那个游手好闲的利兰……他整天就在贸易区外的码头边钓鱼。他在钓鱼上花费这许多时间，我想他的钓鱼技术一定很高。如果你想学的话，为什么不去跟他谈谈呢？"
D.Strings[4518]="与自然的交流沟通是其他任何事情都无可比拟的……至少暗夜精灵是这么告诉我的。我并不擅长跟花草树木交谈，但是我想塔尼莎能帮助你。她居住在法师区外侧的炼金材料店。"
D.Strings[4519]="你为什么要追我，机械雪人？！为什么？！"
D.Strings[4520]="%s迅速从乌米的机械雪人面前逃跑。"
D.Strings[4521]="一个猎人？好的，那么你会想跟矮人区的索尔芬·石盾谈谈。\n\n哦，你一定要告诉他如果我再次介入他的宠物生意，他就可以去培训那些监牢里的猎人了！"
D.Strings[4522]="我总是战战兢兢……人们还在不断吓我……但是下次，我会有所准备的！"
D.Strings[4523]="你想要穿皮革对吗？听起来你该与旧城区的西蒙·坦纳尔谈谈。他在那儿开了一家叫做护体皮甲的商店。"
D.Strings[4524]="%s看上去很轻松。"
D.Strings[4525]="让矮人从铁炉堡指派一名采矿专家来教教我们吧。使用锄头打碎岩石有多困难？嗯，只要他在这儿，你就只管问他好了。他名叫吉尔曼，居住在矮人区。"
D.Strings[4526]="你知道，我可以刺穿一个兽人或是把一个巨魔切成碎片。我甚至可以把我名字的大写字母刻在食人魔的肚子上，但我就是不能忍受给动物剥皮。想一下都让我觉得恶心。\n\n好的，如果你有这种兴趣，那就到老城的护体皮甲找马瑞斯·格兰治。"
D.Strings[4527]="一个裁缝是吗？哦，如果你在这儿呆的时间够长你就会最终听到关于乔吉奥·波利罗的谈论。他现在已经领导潮流几个月了。如果你希望跟他学习，你能在法师区的外圈找到他。"
D.Strings[4528]="术士，嗯。我先前并未对你提及，但是我听说他们聚集在法师区中一间名为已宰的羔羊的酒吧中。"
D.Strings[4529]="%s到处乱跑，大声喊叫，制造骚乱。"
D.Strings[4530]="矿道地铁"
D.Strings[4531]="你不喜欢骑狮鹫，嗯。你很幸运，我们有一个替代品可以让你稳稳地立在地上。那就是侏儒们的公共交通工具，矿道地铁。在矮人区的后面，非常方便。"
D.Strings[4532]="你听说地铁了是吗？那可真是一样不错的交通工具！你会在矮人区的后部找到它。哦，一定记得在地铁行进时把你的胳膊和腿放到地铁里面。"
D.Strings[4533]="好好看看目录吧，$n。"
D.Strings[4534]="是的，每个人都想坐矿道地铁去暴风城，那真是酷毙了。嗯，你可以去铁炉堡大门以东的侏儒区找矿道地铁。"
D.Strings[4535]="哦，地铁，地铁……每个人都想坐地铁去暴风城。那些乘坐狮鹫的好时光，那种在高空中飞翔时紧握缰绳的情景，它们到哪儿去了？\n\n啊！你还是坐地铁去吧……地铁就在侏儒区，那儿还有侏儒的其他精妙设计呢。"
D.Strings[4536]="你是问我铁匠在哪儿？你没听说过大熔炉吗？所有最好的铁匠都聚集在那儿铸造武器和护甲！\n\n在铁炉堡中心都是敲打铁器的声音，你能在那儿找到最出色的铁匠本古斯·深炉。"
D.Strings[4537]="哦！达瑞尔·瑞克努索是个技艺高超的厨师！他的红辣椒如此辛辣，几乎可以锻造钢铁了！我想他不会将菜谱传给你的，但是他肯定能帮助你成为一名好厨师。你可以在大熔炉东北角的铜壶铁罐那找到他。"
D.Strings[4538]="哦，你是在找宾斯匹德吧。为什么那个小侏儒和他的装备……让我告诉你吧，如果你想去他在侏儒区的商店，管好你的手，别去抚摸他的机械绵羊！\n\n爆炸绵羊……为什么你要做这样的事情！？"
D.Strings[4539]="急救？但你看起来不象受伤的样子。如果你真的对学习急救有兴趣，那么就去找尼莎·火石。到铁炉堡医师协会去，就在大熔炉旁边。"
D.Strings[4540]="我听格瑞诺尔说他曾经钓起过一柄剑。或者那是一条旗鱼？这该死的格瑞诺尔，他对我讲了太多的关于鱼的故事，我都分不清了。嗯，你干嘛不去荒弃的洞穴找他，让他告诉你那究竟是什么呢……"
D.Strings[4541]="要建立公会的话是需要相应文件的，乔多·钢眉能帮助你处理这些程序。如果你都准备好了的话，就去铁炉堡访客中心找他吧。"
D.Strings[4542]="你具有成为一名熟练猎人的潜质吗？嗯，$g年青人:姑娘;，时间会告诉我们一切的。在与军事区的雷格努斯交谈之前，别对着别人的眼睛射击。"
D.Strings[4543]="你确定不想做铁匠吗？嗯，如果你真心想学制皮，最好去大熔炉西北角找费布·钢轴谈谈。"
D.Strings[4544]="呸！邮箱……最近我收到的全都是垃圾邮件！\n\n增加这个的尺寸……减少那个的尺寸……现在是免费的屠龙剑。我得每隔一个月就要更改邮箱号码才行！\n\n嗯，你可别说我没警告过你。邮箱就在石火旅店外面。"
D.Strings[4545]="嗯！说到学习采矿的话，你来对地方啦，$g小伙子:姑娘;！吉尔弗拉姆·石趾居住在深山珠宝矿业协会。没有比他更好的老师了。"
D.Strings[4546]="书中说很多条龙联合起来对付一条极其强大的、名为死亡之翼的龙。按照我们掌握的信息，多彩龙人差不多全部释放。守护者已经准备就绪。"
D.Strings[4547]="啊，没有谁比牧师更擅长治疗病痛了。当然喝得酩酊大醉也能解除痛苦，但是我想布莱纳·火崖并不懂得酿酒。我认为你该在神秘大厅进行一些牧师的培训。"
D.Strings[4548]="你或许不知道，除了是一个娴熟的裁缝之外，约莫德还是一个巨人杀手！为什么说当他大喊他一拳打死了七个的时候可以断定他一定偷听到我们在一起讲的东西！\n\n你应该到大熔炉北面他的店铺去拜访他一下，并看看他是否会在跟你讲他的传奇故事！"
D.Strings[4549]="剥皮？能不能学成只有看你自己了！哈哈！你为什么不去找巴尔萨斯·裂石呢，他能教你如何剥皮。他在大熔炉北面的皮甲用品店。"
D.Strings[4550]="一个术士，嗯……好吧，如果你想在附近继续做那种事情，你最好管好你的恶魔，$g小伙子:姑娘;。我不喜欢恶魔，但是我喜欢杀死他们。你明白我的话了吗？\n\n现在你不要再烦我了，马上消失去荒弃的洞穴。你会在那里找到那个术士，瑟斯哈特。"
D.Strings[4551]="克斯塔姆是个大嗓门、爱吹嘘的人……他也是你所能见到的技艺最为纯熟的战士之一！\n\n我告诉你，如果你想成为一名战士的话，就去找他谈谈吧。他肯定在铁炉堡大门以东的军事区中。"
D.Strings[4552]="炼金师？这没什么$c。安尼希尔通过不懈地努力，成为了工匠区技艺最纯熟的炼金术士。如果我是你的话，我会马上赶去那儿的。马上！出发吧！"
D.Strings[4553]="身上又多了一种材料$g小伙子:姑娘;，是吧？嗯，如果你携带的物品过多的话，可以将它们存储在城中心的达纳苏斯银行中。"
D.Strings[4554]="阿斯坦娅在她经常垂钓的地方钓起了一些古怪的财宝。去贸易区找她吧，让她给你看看。"
D.Strings[4555]="琳沙娜能为你提供所需要的文档，她居住在达纳苏斯东北部的工匠区。愿你的伙伴为暗夜精灵带来无比的荣耀吧！"
D.Strings[4556]="你要找的是维斯派塔斯。他负责看管在泰达希尔底部往返的角鹰兽。你可在穿过达纳苏斯西部的传送门，然后在鲁瑟兰村那儿找到他。"
D.Strings[4557]="祖卡斯特是她那个时代最伟大的猎人。最近，她在塞纳里奥区教那些猎人初学者。"
D.Strings[4558]="太阳已经升起来了吗？夜晚的时间总是太短！嗯，塞琳尼会好好照顾你的。她在达纳苏斯东北面的工匠区招待客人。"
D.Strings[4559]="一个邮筒？你要发信，或者也许你要收一封信？我希望是个好消息！在达那苏斯中心银行外面就有一个邮箱。"
D.Strings[4560]="不随意浪费东西是我们的传统文化。当我们不得不杀死某种生物时，我们会加以利用，不让它白白丧命。\n\n要是你想学习剥皮的话，就去工匠区找艾拉迪尔吧。"
D.Strings[4561]="穿着迈里恩缝制的衣服，人们可能会以为她的绣花针是被月神赐福过的。除非你的针也受过同样的祝福，否则你最好去拜访她一次并聆听她的教导。你可以在达纳苏斯东北方的工匠区找到她。"
D.Strings[4562]="希达奈尔训练出许多卫戍，他们守卫着我们心爱的城市。我相信她会使你成为一名战士的。去城门附近的战士区找她吧。"
D.Strings[4563]="你想学习怎样生篝火吗？那么趁你还没有放火烧毁泰达希尔之前最好去请教一下塞纳里奥区的玛里甘。"
D.Strings[4564]="贸易区刚刚开放了一座拍卖行。如果你沿着银行东南方的路走，很容易就能找到贸易区。"
D.Strings[4565]="哦，沉迷于物质财富，这很常见呢。呃，去贸易区的拍卖行吧，财富在对你微笑。"
D.Strings[4566]="它就在贸易区靠西的部分，喷泉的北边。"
D.Strings[4567]="又一个想要靠倒买倒卖发家的？拍卖所就在贸易区，离银行不远的地方。"
D.Strings[4568]="贸易区拍卖行"
D.Strings[4569]="这不可能！"
D.Strings[4570]="所有参与作战的人都各就各位！纳迦来了！"
D.Strings[4571]="%s爆裂，喷发出有毒的粘性物质！"
D.Strings[4572]="你敢玷污这片圣地吗？"
D.Strings[4573]="让刀刃清洗你这个污秽吧！"
D.Strings[4574]="敌人已经打到门口了！坚持住！我们必须守住！"
D.Strings[4575]="后退，坚持住！我们不能失败，否则一切都会失败的！"
D.Strings[4576]="到楼梯那儿去防守！"
D.Strings[4577]="他们已经闯进了光明大厅！我们必须阻止这些入侵者！"
D.Strings[4578]="血色十字军不会就此灭亡的！你不会冲破我们的战线的！"
D.Strings[4579]="旅行者，你好。很少有人以这种方式找到我。$B$B我叫雷沃，我在冬泉谷驯化这些霜刃豹，使它们成为坐骑。$B$B这些猫科动物非常凶猛，极难驯服。只有那些最值得信赖和最受人尊敬的人才可能骑上它们。$B$B我是不会随意出售这样的坐骑的，你必须用行动来证明，让我和霜刃豹都接受你。"
D.Strings[4580]="关于多彩龙鳞的信息。"
D.Strings[4581]="关于魔光多彩鳞片的信息。"
D.Strings[4582]="关于英雄之血的信息。"
D.Strings[4583]="关于暗影之皮的信息。"
D.Strings[4584]="假设存在这种东西。只有体型更大的多彩飞龙才可能具有这样的外壳。"
D.Strings[4585]="通常在较小的多彩飞龙身上找到：幼龙，龙崽，较小的龙人。"
D.Strings[4586]="传说在战事极度激烈的地方，在现今被称为瘟疫之地的土地上；地表也许会涌出洁净而神圣的温泉。这些泉水被人们命名为‘英雄之血’——以纪念那些在对抗亡灵天灾的战争中牺牲的勇士。"
D.Strings[4587]="工匠们都热衷于寻找缝合斯坦索姆憎恶的线：特别是有弹力的——几乎不会断裂的线。"
D.Strings[4588]="通灵学院的巴罗夫家族将它作为照耀他们不复存在的灵魂的镜子。那是一件贵重的纪念品。"
D.Strings[4589]="在暴风城，有很多地方可供饮水休息，但是只有一处可以过夜。去贸易区的镶金玫瑰吧。我听说客房的费用相当合理，被单也很整洁。"
D.Strings[4590]="啊，镶金玫瑰？那柔软的床铺和温水沐浴……想想这一切吧。::打哈欠::如果你要前往那儿的话，你可真幸运。旅馆就在贸易区的西边……柔软的枕头、温暖的毛毯。::打哈欠::"
D.Strings[4591]="在暴风城银行和贸易区的镶金玫瑰旅店之间设有邮箱，非常便利。"
D.Strings[4592]="我不知道他们是怎么做到的……这些邮箱一定是传送门之类的东西。为什么人们整天都聚集在银行旁边的邮箱那儿，从小小的邮箱中不断地取出剑、盾牌和各种护甲！"
D.Strings[4593]="你想戏耍一下巫妖王创造的生物吗？拉姆斯登，好好教训这些入侵者。"
D.Strings[4594]="你好！我刚刚探索凯斯利尔废墟回来，就在西南方。现在我决定调查在这个山脉之上的枭兽，在枭翼树丛内。$B$B你与鲁瑟兰村的艾瑞拉斯·琥珀谈过话了吗？他要求我来这里，或许他还有任务给你。"
D.Strings[4595]="是我亲自动手的时候了。来吧。进入我的领域，向强大的亡灵天灾挑战吧！"
D.Strings[4596]="做这种事情才得到这么点报酬，亏大了！"
D.Strings[4597]="我可负担不起这么高的税金！"
D.Strings[4598]="嗨！你喜欢沙司吗？沙司很美味，不是吗？"
D.Strings[4599]="然后牛头人说“13先生！”"
D.Strings[4600]="我来自底层社会……我们那儿的人民倍受折磨。"
D.Strings[4601]="什么？哦，灰烬使者？没有听说过……什么？别烦我！"
D.Strings[4602]="我该服下那透明小药丸的。"
D.Strings[4603]="别动，你会听到嗝……嗝……的打嗝声，真该死！"
D.Strings[4604]="你见过守夜人巴库斯吗？很勇敢……$B$B我想他是所有守夜人中最凶猛的一个。我怀疑他是否看到我就在周围……"
D.Strings[4605]="温度的数值是……反正还不够高！"
D.Strings[4606]="*叹息* ...113克氏度。你在观光吗？"
D.Strings[4607]="越来越暖和了……7039克氏度！"
D.Strings[4608]="读数是8536克氏度……你已经开始厌烦我了吗？"
D.Strings[4609]="谁敢打扰我们的主人？"
D.Strings[4610]="万岁！我的洋娃娃！"
D.Strings[4611]="你会赶走坏人的，是吗？"
D.Strings[4612]="我们来查明历史的详情吧。这需要使用一些魔法……"
D.Strings[4613]="就这样，完成了。这本书已经被增强了……"
D.Strings[4614]="想找这些？？？？你永远都不可能得到它们的！"
D.Strings[4615]="碉堡正在倒塌！证物正在被烧毁！"
D.Strings[4616]="我要把你的皮当作便服来穿！长靴呢？你得将它们从那儿撬下来！！！！"
D.Strings[4617]="别拉下东西！"
D.Strings[4618]="在堡垒倒塌之前毁掉所有文件！"
D.Strings[4619]="拉姆斯登想吃肉了！"
D.Strings[4620]="欢迎来到风味王国！"
D.Strings[4621]="谢谢你！你让我自由了！"
D.Strings[4622]="哦，谢谢你！我已经深陷恶梦多时了……"
D.Strings[4623]="我的灵魂终于自由了。"
D.Strings[4624]="谢谢你！我注定会在达隆郡之战中身亡，但是你让我获得了自由！"
D.Strings[4625]="啊！如果你见到一个达隆郡的幸存者，请告诉他们我自由了！"
D.Strings[4626]="翡翠议会试图治愈费伍德森林受伤的大地。尽管这片大地是以腐蚀它的东西命名，我们还是希望有一天我们能从这片土地中将腐败清除。"
D.Strings[4627]="我准备好了，$n。找到我的装备离开这里。我想我知道装备在哪里。"
D.Strings[4628]="我们失败了，$n！！"
D.Strings[4629]="你好，$c。我是杰希尔·月弓。我从达纳苏斯来寻找两个朋友，他们是来寻找费伍德森林暗影议会的踪迹的。$B$B看起来那些宣称对兽人种族的苦难负大部分责任的卑鄙的生物正试图重获一些能量。$B$B我的两个朋友进入加德纳尔搜寻证据来证明有事情发生。$B$B我希望我来时他们在这里，但是他们已经晚了数天了。"
D.Strings[4630]="亡灵天灾打进堡垒了！坚守阵地！我们绝对不能失败！"
D.Strings[4631]="骷髅已经进入了光明大厅！消灭他们！"
D.Strings[4632]="我们的防线崩溃了！以圣光的名义，我们一定要战斗到底！"
D.Strings[4633]="亡灵天灾从四面八方涌入了堡垒！愿圣光击败这些邪恶的生物！我们要奋战到底！"
D.Strings[4634]="你好，勇敢的$c！我有世界上最训练有素的狼供你挑选。你到哪里都不会发现能与狼拥有同样的耐力和生存本能的动物！你亲自来看看它们吧。"
D.Strings[4635]="你们破坏了我数年的心血！我要把你们全都杀了！"
D.Strings[4636]="你们这群该死的凡人！我所有的复仇计划，我所有的仇恨……我一定会报仇……"
D.Strings[4637]="我只跟那些被奥格瑞玛的兽人当朋友的人做生意。证明自己吧，然后再来和我谈那些强大的座狼。"
D.Strings[4638]="祝你好运，勇敢的$c。我知道你在寻找一匹好战马。告诉你吧$g兄弟:姐妹;，在你所在的区域没有什么比迅猛龙更好的坐骑了！看看我的这些迅猛龙吧——他们的祖先曾经是极其凶猛的野兽。"
D.Strings[4639]="很抱歉$g兄弟:姐妹;，但是在确定买主是黑暗之矛部落的朋友之前，我不会将迅猛龙卖给他的。当你证明自己是我们的朋友之后，我才会把迅猛龙卖给你。"
D.Strings[4640]="你们这些蠢货以为可以这么容易就打败我吗？看看纳斯雷兹姆的真正力量吧！"
D.Strings[4641]="盗贼！我要毁掉你们的尸体！"
D.Strings[4642]="这些计划的报酬将从尸体中得来——你的尸体！"
D.Strings[4643]="自由了！！！"
D.Strings[4644]="诅咒结束了！"
D.Strings[4645]="赞美埃根！"
D.Strings[4646]="总有一天我们会对克尔苏加德进行报复的。"
D.Strings[4647]="瑞文戴尔必须死！"
D.Strings[4648]="啊，天哪！看看这……这些蜡烛。我敢肯定它们是被用来进行某种可怕而黑暗的仪式的。我们最好快一点！"
D.Strings[4649]="那里！在那里！"
D.Strings[4650]="我现在需要的是一副金套索。"
D.Strings[4651]="我们离开这里吧，$n。我准备好了！"
D.Strings[4652]="死吧，恶魔的爪牙！"
D.Strings[4653]="啊！终于呼吸到新鲜空气了！我从没想过还能见到天日……"
D.Strings[4654]="那是什么？！特雷? 特雷!?"
D.Strings[4655]="他们将尸体交给了我，他将尸体投进了深坑。"
D.Strings[4656]="我想买些东西。"
D.Strings[4657]="叛徒！"
D.Strings[4658]="不！他们对你做什么了！？"
D.Strings[4659]="不！我的朋友……发生什么了？都是我的错……"
D.Strings[4660]="我自己走可以更快些,$n。在灰谷附近与杰希尔·月弓会合。她应该与翡翠议会的德鲁伊在一起。她会告诉你接下来做什么。谢谢你的帮助！"
D.Strings[4661]="别把邮件给弄乱了！"
D.Strings[4662]="再试一次！"
D.Strings[4663]="当然！"
D.Strings[4664]="不可能！"
D.Strings[4665]="邮差来了！"
D.Strings[4666]="你好，$n。我是米洛尔·怒斩，大熔炉的看守者。"
D.Strings[4667]="我希望成为一名铸甲师。"
D.Strings[4668]="我希望成为一名武器铸造师。"
D.Strings[4669]="你在锻造方面的技术已经非常高超了，$n。该做出决定了。有两条路你可以选择：武器制造工匠或是装甲制造工匠。$B$B注意，当你做出决定以后，就不能回头了。每个方向的守则都不允许你三心二意。"
D.Strings[4670]="时机成熟了，我的$g兄弟:姐妹;们，武装起来，从亡灵天灾手中夺回属于我们的夜晚！"
D.Strings[4671]="唉$c，你不是达纳苏斯的臣民和泰达希尔的暗夜精灵的朋友。除非你以实际行动——不仅仅是口头上的话语——证明自己的友好态度，那样的话，我会提供坐骑让你挑选的。"
D.Strings[4672]="承蒙月神的关照，我很高兴给你在整个泰达希尔找到的最好——甚至是这世上最好的坐骑，它们就是夜刃豹。数年来，哨兵部队一直倚赖这些同伴的价值。$B$B抓紧时间，朋友，挑选一匹你满意的。我敢肯定你不会失望的。"
D.Strings[4673]="呃……很抱歉，我真的不太了解你。我是说，作为公认的机械陆行鸟经销商，我只能跟侏儒的朋友做生意。要是你能和诺莫瑞根保持友好态度，我会很高兴地为你提供服务的。"
D.Strings[4674]="如果你是为获得快速而安全的产品而来，那么这儿就是你的目的地了！今年的机械陆行鸟模型已经到了，我将为你展示其性能！"
D.Strings[4675]="跟埃隆努斯谈谈，$n。他会教你如何成为一名武器铸造师的。"
D.Strings[4676]="格鲁努斯就是你要找的人，$n。他会教授你铸甲师这门艺术。"
D.Strings[4677]="当一个铁匠达到了你这样的专业水平的时候，我会提供给他们一个选择。$B$B虽然我并没有要求你必须做出选择，但我建议你最好还是做出抉择——毕竟，你想永远当一名新手吗？是大师级的铸甲师和武器铸造师给我们的军队提供补给，让我们赢得战争的胜利并获得荣耀！$B$B注意，$n，一旦你做出了决定并完成了指定的任务，就没有回头路了。一个人只能沿一条路走到底。"
D.Strings[4678]="我是克拉索克，这些工匠的监工。"
D.Strings[4679]="伯古什！$n已经准备好接受训练啦。"
D.Strings[4680]="奥克索斯会教你的，$n。"
D.Strings[4681]="一块阿莎利水晶已经被摧毁了！杀死入侵者！"
D.Strings[4682]="阿莎利水晶已经修复！"
D.Strings[4683]="$R的肉……必须吃掉！"
D.Strings[4684]="谁敢靠近这个大熔炉？尝尝我的黑暗之刃！"
D.Strings[4685]="亡灵天灾在召唤你，愚蠢的$r。"
D.Strings[4686]="$C——我会吞噬你的光芒！"
D.Strings[4687]="嗨，$c！"
D.Strings[4688]="准备被玛罗恩干掉吧。"
D.Strings[4689]="上层精灵的灵魂，安息吧！辛玛洛水晶终于复原了！"
D.Strings[4690]="被诅咒的灵魂！忘记过去吧！辛玛洛水晶已经不再束缚你们了！"
D.Strings[4691]="上层精灵的灵魂！你们可以安息了！水晶的诅咒已经被解除了！"
D.Strings[4692]="愿圣光与你同在，$c。我能帮上忙吗？"
D.Strings[4693]="%s复活了一名亡灵仆从！"
D.Strings[4694]="%s尝试对他的仆从释放死亡契约！"
D.Strings[4695]="我想向你购买奥术催化剂。"
D.Strings[4696]="一场猛烈的风就要来了——我可以通过我裸露膝盖的疼痛判断出来。我就是希望我们不要被狂风困住。"
D.Strings[4697]="好吧，$n，让我们来看看怎么对付这些天灾之锅！如果你要收集所需的成分，就带上一个玻璃聚焦装置吧。在鉴别从亡灵天灾的爪牙身上获取的资源时，你会用得着它的。$B$B你还需要找一份奥术催化剂。这东西可不便宜，而且也非常不稳定。一旦你得到药剂，就必须在15分钟内使用它，否则药剂就失效了。所以你可得留神别乱买。"
D.Strings[4698]="费尔斯通农场的天灾之锅都需要什么？"
D.Strings[4699]="达尔松之泪的天灾之锅都需要什么？"
D.Strings[4700]="嚎哭鬼屋的天灾之锅都需要什么？"
D.Strings[4701]="盖罗恩农场的天灾之锅都需要什么？"
D.Strings[4702]="根据你提供的样本，我们认为你需要下面这些东西：一份奥术催化剂、六份骨质分离素和四块符文布。你可以使用玻璃放大镜从瘟疫之地的骸骨亡灵身上获取骨质分离素！$B$B一旦你获得了这些物品，就可以把它们放进天灾之锅里了。"
D.Strings[4703]="根据你提供的样本，我们认为你需要下面这些东西：一份奥术催化剂、五份细胞增强剂和四块符文布。你可以使用玻璃放大镜从瘟疫之地的僵尸或食尸鬼身上获取细胞增强剂！$B$B一旦你获得了这些物品，就可以把它们放进天灾之锅里了。"
D.Strings[4704]="根据你提供的样本，我们认为你需要下面这些东西：一份奥术催化剂、四份外膜震荡体和四块符文布。你可以使用玻璃放大镜从瘟疫之地的鬼魂或怨灵身上获取外膜震荡体！$B$B一旦你获得了这些物品，就可以把它们放进天灾之锅里了。"
D.Strings[4705]="这份工作明显不值16500的年薪。"
D.Strings[4706]="阿莎利水晶已经被摧毁了！我的兄弟们，忠诚于巫妖王,重新召唤它！"
D.Strings[4707]="一块阿莎利水晶已经被摧毁了！趁屠宰场处于易受攻击状态，赶快修复通灵塔！"
D.Strings[4708]="召唤已经完成！阿莎利水晶已经复原！"
D.Strings[4709]="你已经被玛罗恩搞定了！"
D.Strings[4710]="我需要玻璃放大镜。"
D.Strings[4711]="复活吧，我的勇士！"
D.Strings[4712]="为你而战，我的女士！"
D.Strings[4713]="光明之刃！"
D.Strings[4714]="发泄你的愤怒吧！"
D.Strings[4715]="醒来吧！我的奴仆！保护圆盘！"
D.Strings[4716]="兄弟们，到我这儿来！为创世者而战！"
D.Strings[4717]="加入我们吧！"
D.Strings[4718]="嘘……你闻到什么了吗？"
D.Strings[4719]="利拉迪斯一直在梅伊瑟娜岗哨等我，我们得快些，$n。"
D.Strings[4720]="%s开始打瞌睡……"
D.Strings[4721]="%s在不经意间睡着了。"
D.Strings[4722]="嗷……"
D.Strings[4723]="哦，我太累了……"
D.Strings[4724]="如果我在这里稍微呆一会儿，你不会介意吧？"
D.Strings[4725]="%s从阴影中现身保护锅炉！"
D.Strings[4726]="亡灵天灾带来的灾难还在这片区域蔓延，在扭转局面，摧毁亡灵天灾之前，我们要走的路还很长。收集必要的资源，尽力帮助我们吧！"
D.Strings[4727]="我们在确定这片区域的状况时遇到了困难；快去核对一下，或许我们能得出一个较好的结论。"
D.Strings[4728]="亡灵天灾带来的灾难就快结束；一场难以控制的颠覆行动会将我们推向顶峰！你务必要帮助我们！"
D.Strings[4729]="我们已经开始反攻亡灵天灾了，但是我们撑不了多久了！去摧毁他们的锅炉吧！"
D.Strings[4730]="我们正控制着亡灵天灾——至少还会侵扰它们一整天时间！但是我们得对此有足够的把握，因此你要尽可能地破坏锅炉。"
D.Strings[4731]="我们破坏大熔炉的战斗进行得怎么样了？"
D.Strings[4732]="%s在向空中释放反作用试剂时停止了移动。"
D.Strings[4733]="兄弟，这些契约是我的！很快你就将永远从我眼前消失了！"
D.Strings[4734]="奥蕾西娅，这些财宝是我的！你准备死吧！"
D.Strings[4735]="你是个猎人？你会发现索塔尔为了躲避太阳就藏在城镇西南角上的洞穴里。"
D.Strings[4736]="去南方的森金村，找安苏瓦谈谈。"
D.Strings[4737]="那是巨魔的事儿。去南方的森金村找安苏瓦。"
D.Strings[4738]="你应该是在寻找泰金。在城镇东面的兵营里可以找到她。"
D.Strings[4739]="她名叫泰金，你可以在剃刀岭东面的兵营中找到她。她会教你如何尊敬神灵的。作为回报，你必须向她表示尊重。"
D.Strings[4740]="到村庄西南方的洞穴顶部找到卡普拉克。"
D.Strings[4741]="你为什么想找卡普拉克谈谈？没关系。到剃刀岭西南角的洞穴顶部找他。不过你一定不要把手放错地方！"
D.Strings[4742]="你应该去找斯瓦特。到剃刀岭东边的兵营里找找看。"
D.Strings[4743]="酋长进行的变革将帮助部落取得胜利！去城镇东边的兵营找斯瓦特吧。"
D.Strings[4744]="你能在剃刀岭东面的兵营后找到杜格鲁·血怒。"
D.Strings[4745]="杜格鲁·血怒在城镇东边的兵营后面。不要让我发觉你跟燃烧军团是一伙的！"
D.Strings[4746]="去城镇东面的兵营找塔绍尔·锯痕。"
D.Strings[4747]="到剃刀岭东面的兵营里找到塔绍尔·锯痕。给部落的年轻人带去骄傲和荣誉！"
D.Strings[4748]="去南方的森金村找米奥赞。"
D.Strings[4749]="我听说森金村的巨魔中有个名叫米奥赞的药剂师。去那儿找他吧。"
D.Strings[4750]="那是杜克。去城镇西北角炙热的熔炉附近找他。"
D.Strings[4751]="沿着北边的道路去奥格瑞玛。你可以问问那儿的守卫烹饪训练师在哪儿。"
D.Strings[4752]="嗯……食物。旅途并不遥远，你需要朝北走，去奥格瑞玛，问问那儿的守卫。"
D.Strings[4753]="在奥格瑞玛有你要找的人。那儿的守卫会为你指明方向的。朝着北方的道路走，应该不会错过的。"
D.Strings[4754]="据我所知，附近没有这些训练师。你最好去北方的奥格瑞玛看看，去问问那儿的守卫。"
D.Strings[4755]="在剃刀岭居住着一名工程学训练师。他名叫穆德拉克，你在熔炉附近就能找到他。"
D.Strings[4756]="呸，那是地精的东西！在剃刀岭有一个兽人可以教你如何制作这些物品。去熔炉附近找穆德拉克吧。"
D.Strings[4757]="拉乌克就在剃刀岭东边的兵营中。"
D.Strings[4758]="因为我们经常战斗，我们当然有一个急救训练师在剃刀岭。在城镇东面的兵营里可以找到拉乌克。"
D.Strings[4759]="我曾见到一个名叫劳迪克的巨魔在暗矛海滩南部钓鱼，就在森金村的外围。"
D.Strings[4760]="你在寻找劳迪克。你会在南面的森金村外的暗矛海滩找到他。"
D.Strings[4761]="你在寻找米什基。她在森金村南面有一间小屋。"
D.Strings[4762]="花？在这片荒芜的土地上？如果有人能教你如何找到它们，那就是南方的森金村的米什基。"
D.Strings[4763]="水之精灵，我赞美你，还有我想请你帮个忙。你听到$n的请求了，而我相信$g他的:她的;用意是高尚的。你愿意帮助我们吗？"
D.Strings[4764]="为此你需要到奥格瑞玛去。只需沿着从剃刀岭出去的路穿过峡谷就会到达那里。到了那里,你可以问问步兵以得到进一步的指引。"
D.Strings[4765]="要学习如何处理皮革，你得去北面的奥格瑞玛。那儿的守卫会告诉你如何找到制皮训练师的。"
D.Strings[4766]="当然，当然。城镇中有一名采矿训练师。在旅馆旁西北角可以找到克鲁恩。"
D.Strings[4767]="我听说杜隆塔尔的采矿业极为发达。我们在剃刀岭有一个采矿训练师，你可以去城镇西北角的大熔炉附近寻找克鲁恩。"
D.Strings[4768]="在奥格瑞玛有一名剥皮训练者。出了剃刀岭往北走，当你到达奥格瑞玛时问问那儿的守卫，他们会为你指明方向的。"
D.Strings[4769]="在奥格瑞玛有你要找的人。朝着北方走，跟那儿的守卫谈谈。"
D.Strings[4770]="你得去奥格瑞玛。出了剃刀岭沿着北面的道路走，就能到那儿了。跟那儿的守卫谈谈，他们会给你指明方向的。"
D.Strings[4771]="你可以试着在奥格瑞玛解决你的问题，就在这里的北方。或许某个奥格瑞玛步兵可以帮你。"
D.Strings[4772]="呃？你可以在奥格瑞玛找到银行。沿着道路往北走，跟那儿的守卫谈谈。"
D.Strings[4773]="是的，我自己也需要放置一些东西。要找到它你需要向北沿着去奥格瑞玛的路一直走，然后找那里的步兵询问一下。"
D.Strings[4774]="你会在奥格瑞玛找到双足飞龙管理员的。沿着公路向北走到那里去，并向一个奥格瑞玛步兵询问更多指示。"
D.Strings[4775]="你没看到我很忙吗?沿着路向北走到奥格瑞玛并询问那里的步兵。你不会错过的。"
D.Strings[4776]="谢谢你，伟大的精灵。谢谢你！"
D.Strings[4777]="我可以喝点东西，稍事休息。到剃刀岭西北角，替我向旅店管理人罗斯克问声好。"
D.Strings[4778]="那是剃刀岭的一幢大建筑，而不是兵营。去跟旅店老板格罗斯克谈谈。明白了？"
D.Strings[4779]="我们听说了你的请求，我们同意……这是件好事。我们会为你净化水的。带着我们的祝福上路吧，萨满。"
D.Strings[4780]="你似乎需要帮助。"
D.Strings[4781]="快点。"
D.Strings[4782]="什么事！？"
D.Strings[4783]="因为大熔炉被打开了缺口，我们现在能够把反作用剂释放到外界。这应该能让亡灵天灾尝尝他们自己药物的滋味，可以这么说！$B$B向炼金师阿尔比顿询问一下有关在大熔炉中所需要使用的试剂这方面的信息。我会处理所有的信息报告，以便于我们决定怎样把瘟疫用来对付亡灵天灾！"
D.Strings[4784]="因为大熔炉被打开了缺口，我们现在能够把反作用剂释放到外界。这应该能让亡灵天灾尝尝他们自己药物的滋味，可以这么说！$B$B向炼金师迪瑟斯询问一下有关在大熔炉中所需要使用的试剂这方面的信息。我会处理所有的信息报告，以便于我们决定怎样把瘟疫用来对付亡灵天灾！"
D.Strings[4785]="哦，我能从这儿看见利拉迪斯……告诉她我在这儿，好吗？"
D.Strings[4786]="你好，年轻的$g主人:女主人;。我是艾瓦·萨克霍夫，这是我的丈夫卢森。很高兴认识你。"
D.Strings[4787]="我也很高兴遇见你们，女士。我能问问你在这儿干什么吗？"
D.Strings[4788]="当然，$g先生:小姐;。我们曾是巴罗夫家里的仆人：现在那里被称作通灵学院。$B$B我那时是女仆的领班而卢森是主人巴罗夫的男管家。$B$B我们为巴罗夫家族工作了数十年，直到……$B$B<艾瓦哭了。>"
D.Strings[4789]="直到什么时候，艾瓦？我必须知道这一点。"
D.Strings[4790]="啊，真是太可怕了，$g先生:小姐;。巴罗夫家族从前充满生机……充满活力。这个庄园是巴罗夫家族主要的住所。$B$B卢森和我注意到随着时间的流逝，巴罗夫家族变得低沉而沮丧。偏执妄想和暴怒笼罩着主人和小姐。在夜里，我们可以听到巴罗夫夫妇在卧房里争吵。根据我们了解，他们的贪婪毁了他们，可以这么说。"
D.Strings[4791]="我们猜想，巴罗夫家族为了保护自己的财宝以及生前死后对土地的所有权，他们与一个名叫克尔苏加德的人类法师达成协议，克尔苏加德拥有强大的法力。$B$B<艾瓦战栗起来。>$B$B协议中提及了通灵学院……这里将成为诅咒神教的地盘，变成他们的首府。$B$B随着时间的推移，巴罗夫家族变得渐渐衰老……甚至扭曲。$B$B黑暗开始笼罩整个家族……"
D.Strings[4792]="你们为什么不离开？"
D.Strings[4793]="去哪里？我们过去、现在和将来所知道的全部就是这些。$B$B最终，我们与巴罗夫失去了联系，并从房子里被赶了出来。我们不知道其他仆人出了什么事，只听到有尖叫声,痛苦的尖叫声。$B$B知道我们无路可逃，卢森和我被迫藏在了我们的住处。在白天，当学校相对安静时，卢森会溜出去弄点食物和喝的东西。"
D.Strings[4794]="我们这样持续了六个月，看到房屋经历了令人恐惧的变化。肮脏的怪物随意在庄园里漫游。随身携带着各种与仪式和祭祀相关的用具的黑暗信徒遍布在每一寸地方。我们知道我们躲不了多久了。$B$B正如所料想的那样，我们被发现并抓住了。他们剥掉了我们所有的衣服并把我们放到一滩鲜血中。我们坐在那里长达数天，赤身裸体，胆战心惊。"
D.Strings[4795]="没有任何限制？就在一圈鲜血之中？"
D.Strings[4796]="限制？这世上有些东西比栅栏和镣铐更加能够限制住人，年轻的$g主人:女主人;。亡灵包围着我们，不断恐吓我们。$B$B最终，他来了。他自我介绍叫瑟尔林·卡斯迪诺夫教授。我们都把他叫做“屠夫。”"
D.Strings[4797]="我们最后弄清喊声从哪里传来的了。屠夫让我们见识到闻所未闻的痛苦。他把我们用于无数试验中，试图研制瘟疫菌。$B$B日子过去了数星期。要不是那个残忍的混蛋用法术维系着我们的生命，我们熬不过第一天的。"
D.Strings[4798]="这真是残忍的行径。"
D.Strings[4799]="屠夫说起“无辜者的鲜血”和他的黑暗主人，“基尔图诺斯”。以及他会如何满足他主人的欲望。$B$B最后，这个怪兽完成了他的实验。我们被耗干了生命。我们的灵魂被打碎了。死亡的甜美的拥抱靠近了，我们张开双臂欢迎它。但是在他极端的残酷中，屠夫把我们从死亡之门中复活。$B$B我们要被活着扔进他贪婪的食尸鬼之中。他笑着看我们被魔鬼吞噬。"
D.Strings[4800]="我感到有些恶心。"
D.Strings[4801]="我们什么都没感觉到。我们的灵魂在这里，在地狱。在找到我们的尸体并让灵魂安息之前我们不能离开。"
D.Strings[4802]="啊，你必须去雷霆崖最高处拜访他们中的一人。沿着血蹄村北面的道路走。雷霆崖底有升降梯可达顶部。当你到达那儿时，可以询问雷霆崖守卫。"
D.Strings[4803]="村子里可没这样的地方，在高高的雷霆崖上应该有。出了血蹄村沿着北面的道路走，乘坐雷霆崖升降梯到达顶部，找那儿的守卫谈谈。愿你的祖先保佑你。"
D.Strings[4804]="在北方的雷霆崖，有一名双足飞龙管理员。乘坐升降梯到达雷霆崖顶部，问问那儿的守卫，他们会为你指明方向的。"
D.Strings[4805]="只有在天空自由翱翔时，灵魂才能得到真正的解脱。在我们伟大的部落中心雷霆崖就有这样一块地方。血蹄村外以北的道路就通往那儿。一旦你乘坐升降梯到达高处，就找雷霆崖守卫谈谈，他会做出进一步的指引。"
D.Strings[4806]="旅店老板考乌斯可以满足你的需求。你可以在村子西边的屋子中找到他。"
D.Strings[4807]="人总是要休息的。在血蹄村的西边，旅店老板考乌斯经营着一家很大的旅馆，为人们提供休息之所。你去那儿找他吧。"
D.Strings[4808]="你应该去听听根妮亚·符文图腾的忠告。她在村子东面的大营帐中。"
D.Strings[4809]="德鲁伊的生活方式跟萨满相差无几。根妮亚·符文图腾正在对此进行研究。去血蹄村东面的大营帐中找她吧。"
D.Strings[4810]="雅文·刺鬃在村庄北面等你。他能教你猎人之道。"
D.Strings[4811]="在大地之母心目中，学习如何与自然融合一体是件荣耀的事儿。如果你想成为一名猎人，你必须去血蹄村北部找雅文·刺鬃。"
D.Strings[4812]="在血蹄村的东边，有一座巨大的营帐。纳姆·逐星在那儿等着你呢。"
D.Strings[4813]="村子里居住着一位名叫纳姆·逐星的智者。他能继续训练你，使你成为一名真正的萨满。"
D.Strings[4814]="克朗·石蹄在村子东南角的训练圈里。"
D.Strings[4815]="要是你想成为一名战士，就得去找克朗·石蹄。你能在村子的东南角找到他，他通常就在那儿训练学生。"
D.Strings[4816]="虽然我们在血蹄村没有炼金术训练师，在北面的雷霆崖却有一位。沿着这条路去那儿，当你到达顶部时再向一位雷霆崖守卫询问具体方位。"
D.Strings[4817]="用大地之母的果实配制药水来帮助我们进行持久抗争是一件光荣的行为。如果你想学习配制药水，就得去北方的雷霆崖。当你到达雷霆崖顶部时，去问问那儿的守卫，他们会给你详细的指引的。"
D.Strings[4818]="在我的家乡雷霆崖，有一位铁匠训练者。如果你想成为一名铁匠的话，就朝北走，去雷霆崖，然后问问那儿的守卫吧。"
D.Strings[4819]="你希望把大地母亲的骨头设计成可以帮助部落的工具。好的，好的。沿着北边的路走出血蹄村直到一部可以上到雷霆崖顶部的升降梯那里。那里的守卫可以给你更多帮助。"
D.Strings[4820]="你可以在村庄西北角的大帐篷里找到派尔·沉默行者。他可以教给你你想要的。"
D.Strings[4821]="只是想想那美味，我就已经垂涎三尺了。派尔·沉默行者是血蹄村最好的厨师。你可以在村子西北角的大营帐里找到他。"
D.Strings[4822]="去北面的雷霆崖吧，从那儿开始你的旅程，朋友。一旦你到达雷霆崖，那儿的守卫会直接告诉你你要找的东西在哪儿。"
D.Strings[4823]="只有在雷霆崖上的神秘之地才能找到这样的智者。沿着血蹄村北面的道路一直走，直到你来到雷霆崖底的升降梯。乘坐升降梯到达顶端，询问雷霆崖守卫，您能获取到更多的帮助。"
D.Strings[4824]="维尔拉·幼蹄在村子西边的房子中进行训练。"
D.Strings[4825]="绷带、抗毒药品这些东西在草原生活中是不可缺少的必需品。维尔拉·幼蹄能教你如何制作它们。你可以在血蹄村西边的房子中找到她。"
D.Strings[4826]="你在寻找尤萨恩·静水。你可以在村子的西面找到他，他就在石牛湖钓鱼。"
D.Strings[4827]="授人以鱼不如授人以渔。尤萨恩·静水会教你如何钓鱼。到石牛湖岸边的血蹄村寻找他的智慧所在。"
D.Strings[4828]="要是你想学习草药学，就必须去雷霆崖。出了血蹄村，沿着北边的路走，然后乘坐升降梯到达山顶。你可以问问雷霆崖的守卫获取帮助。"
D.Strings[4829]="在北方的雷霆崖，你能学到草药学。沿着村外的道路走，乘坐雷霆崖升降梯到达顶部。那儿的守卫能为你指明方向。"
D.Strings[4830]="查尔·硬皮居住在村子西北角的大帐篷中。他能教你一些制皮的必要知识。"
D.Strings[4831]="当我们使用动物的皮革时我们必须热爱食物或带给我们的保护，我们给大地母亲以荣誉并尊敬动物。查尔·硬皮会教给你这些事情。你可以在血蹄村西北角的大帐篷找到他。"
D.Strings[4832]="嗯，我觉得你需要到雷霆崖去弄清楚。出了血蹄村沿着公路一直往北走。你会到达雷霆崖的底部。乘升降梯到顶部你就可以向雷霆崖的任何一个守卫寻求进一步的帮助。"
D.Strings[4833]="我听说北方的雷霆崖有个矿工训练师。沿着村外的道路前进，然后乘坐升降梯到达山顶。任何一名雷霆崖守卫都能帮助你。"
D.Strings[4834]="你可以在血蹄村西北角的大帐篷里找到姚恩·深刺。"
D.Strings[4835]="啊,是的，剥皮。没有人比姚恩·深刺还善于运用剥皮刀了。你可以在村庄西北角的大帐篷找到他。"
D.Strings[4836]="不幸的是，血蹄村中没人懂得裁缝技能，但是你可以在雷霆崖找到训练师。出了村子，沿着北面的道路走。乘坐雷霆崖升降梯到达顶部，然后问问那儿的守卫，他们会为你指明方向的。"
D.Strings[4837]="你是说裁缝？嗯。是的，当然。你得去正北方的雷霆崖。沿着村外的道路走。到达雷霆崖底后，乘坐升降梯去雷霆崖顶部，跟那儿的守卫谈谈。"
D.Strings[4838]=S[681]
D.Strings[4839]="愿大地母亲祝福你。"
D.Strings[4840]="你看起来好像迷路了。我可以帮你。"
D.Strings[4841]="你需要什么吗？"
D.Strings[4842]="布瑞尔镇没有银行，你得去幽暗城找找。在南方的洛丹伦废墟后面的升降梯能带你去幽暗城。你可以问问幽暗城守卫，他们会为你指明方向的。"
D.Strings[4843]="你需要银行做什么？好吧，你得穿越布瑞尔南部的洛丹伦废墟，乘坐升降梯到达幽暗城。当你到达那儿后，询问自称为幽暗城守卫的行动缓慢的憎恶，请求它给予更详细的指示。"
D.Strings[4844]="在幽暗城中居住着一位蝙蝠管理员。出了布瑞尔城朝南走，然后在丁字路口向西走。洛丹伦废墟就在你的右边，穿过废墟，然后进入幽暗城。你可以问问那儿的守卫，请求他们的帮助。"
D.Strings[4845]="想飞往某处？你得去幽暗城才行！沿着城镇南面的道路走，然后往西南方前进，到达洛丹伦废墟。你可以乘坐废墟后面的升降梯到幽暗城，问问幽暗城守卫，获取更详细的指示。"
D.Strings[4846]="你可以在穿过城镇的道路东南端的恐惧之末旅店里面找到旅店老板瑞尼。"
D.Strings[4847]="如果我是旅店老板瑞尼的话，我可能在哪儿？嗯？哦，也许在恐惧之末旅店中。是的，是那儿，我敢肯定。试着去布瑞尔的东南角……你认为自己能找到他吗？"
D.Strings[4848]="你可以在恐惧之末旅店楼上的平台找到法师训练师凯恩·火歌的，恐惧之末旅店就在布瑞尔的东南端。我猜你现在去的话有点晚了，他不会再登记给你房间了。"
D.Strings[4849]="你看我像个会施魔法的人吗？嗯，我确实听说 凯恩·火歌居住在城镇东南部的恐惧之末旅店的楼上。他那样站在格雷彻的房间之外可真奇怪。"
D.Strings[4850]="去镇子东南角的恐惧之末旅店，你可以在旅店楼上的阅览室中找到黑暗牧师贝里尔的。"
D.Strings[4851]="啊，你是在找黑暗牧师贝里尔。他在恐惧之末旅店楼上的阅读室。他一直在阅读、祷告，没人知道他在干嘛，也谁敢去问他啊？"
D.Strings[4852]="潜行者训练者名叫马里恩·考尔。她在城镇东南角的恐惧之末旅店的阅览室中。"
D.Strings[4853]="马里恩·考尔和黑暗牧师贝里尔一起在布瑞尔镇东南角恐惧之末旅店楼上的阅览室中。我只是想看看谁是这场对抗的胜利者。"
D.Strings[4854]="他名叫鲁伯特·鲍什。我听说他在城镇东南角的恐惧之末旅店楼上的某间房间里。"
D.Strings[4855]="你要找的是鲁伯特·鲍什。他和他的随从居住在布瑞尔东南角恐惧之末旅店的楼上。"
D.Strings[4856]="去恐惧之末旅店的主餐厅找奥斯蒂尔·德·蒙。酒馆就在布瑞尔城的东南角。"
D.Strings[4857]="是的，你应该去找奥斯蒂尔·德·蒙。他总住在城镇东南端的客栈里。它叫做恐惧之末旅店，你不会错过的。"
D.Strings[4858]="我们的炼金师名叫卡罗莱·安尼斯。她居住在布瑞尔镇西北角的房屋中。"
D.Strings[4859]="你会在城镇西北端发现卡罗莱·安尼斯正试图炸掉她的房屋。为什么你不去看看你能否帮她？"
D.Strings[4860]="很抱歉，朋友，在布瑞尔没有你想要的东西。你得前往幽暗城。幽暗城位于布瑞尔以南的洛丹伦废墟下。在废墟后面搭乘升降梯即可到达，去问问幽暗城守卫，他会为你指明方向的。"
D.Strings[4861]="铁匠？不，我们最后一名铁匠都转变成毫无头脑的亡灵天灾士卒啦。但是镇子南边的幽暗城中还居住着一名铁匠。幽暗城在洛丹伦废墟下面，好听的名字，是吗？乘坐废墟后面的升降梯抵达幽暗城，去跟那儿的守卫谈谈，他们会为你指明方向的。"
D.Strings[4862]="想要当厨师？到城镇南部的幽暗城去接受培训。你可以到洛丹伦废墟后面找到下行的升降梯。当你到达后向那些笨拙的幽暗城守卫寻求更多帮助。"
D.Strings[4863]="既然所有东西对你来说吃起来都象是灰烬，为什么还要做饭呢？如果你还有一样东西不是这样的，那很好，到布瑞尔南边的幽暗城去问一位幽暗城的守卫，以进一步了解如何找到他们的烹饪培训师。要到那里你可以从洛丹伦废墟的后方乘升降梯下去。"
D.Strings[4864]="你可以在布瑞尔东南边的恐惧之末旅店的楼上的一间房间找到范斯·安德格鲁姆。"
D.Strings[4865]="有消息说范斯·安德格鲁姆已经在城镇东南端的恐惧之末旅店楼上永久定下了一间房间。我想他刚刚离开了阅览室。"
D.Strings[4866]="虽然在布瑞尔没有工程学训练师，在幽暗城却有一位。要到那儿，朝村子的南边走，一直到洛丹伦废墟，然后坐升降梯下去。一旦你到了那里，向一位幽暗城守卫询问详细的方位。"
D.Strings[4867]="来复枪、炸药、炸弹、爆炸绵羊……这些可爱的东西。要学习如何制造这些物品以及其他工具的话，就去布瑞尔以南，洛丹伦废墟下的幽暗城吧。乘坐废墟后面的升降梯，当你到达幽暗城后，向一个幽暗城守卫询问训练者的确切位置。"
D.Strings[4868]="当人们进入城镇东南角的恐惧之末旅店时，妮拉会向这些未来的顾客致敬。"
D.Strings[4869]="你说屠夫？哦，急救训练师！一个样。当你看到护士妮拉站在城镇东南面的恐惧之末旅店里面时你就会明白为什么。"
D.Strings[4870]="克莱德·凯林，当地的钓鲈鱼高手，有他自己最喜欢的钓鱼地点，就在布瑞尔东部的澈水湖。"
D.Strings[4871]="是的，你总是能看到克莱德·凯林在布瑞尔东边的澈水湖岸钓鱼。但当你到那里后要当心那些带着面具的变态者。我们去年就被迫关掉了孩子们的夏令营。"
D.Strings[4872]="去找法鲁萨。我最后一次见到她时，她正站在马厩和西北方向的房间之间。"
D.Strings[4873]="实际上我更倾向于传统医学……水蛭，蛆，锯骨……那类东西。你可以看到我们本地的草药医学训练师，法鲁萨，就站在布瑞尔的马厩的附近。"
D.Strings[4874]="你一定是要找舍伦尼·洛巴尔特。沿着布瑞尔东南方的道路走，然后在十字路口向东走。她就居住在路边的某个营帐中。"
D.Strings[4875]="接近尸体时的感觉是独一无二的。你可以沿着城镇外东南方面的道路前进，到达十字路口后向东走，找到舍伦尼·洛巴尔特。她居住在离道路不远处的小营帐中。"
D.Strings[4876]="我听说幽暗城中有个矿工训练师。离开城镇往南走，穿过洛丹伦废墟，你就能到那儿了。然后乘坐升降梯下到幽暗城，去询问幽暗城守卫，你应该能获取更多指示信息。"
D.Strings[4877]="我猜想你最初的训练就是挖掘到幽暗城。嗨，明白吗？挖掘……没关系。要到幽暗城，你先要到布瑞尔南面的洛丹伦废墟后方，然后乘升降梯下去。向那里的一位幽暗城守卫寻求更多的帮助。"
D.Strings[4878]="兰德·洛巴尔特对制皮这样的技能相当精通。你可以在往布瑞尔东南角沿途的某个营帐中找到他。沿着城镇东南方的道路走，然后在十字路口向东转。"
D.Strings[4879]="你想成为一个标本剥制师？我不喜欢那些从我身上获得材料然后运走的人，因为他们认为我死了。难道不讨厌吗？好了！到城镇东南边的一个营地找寻兰德·洛巴尔特。要找到他需要走布瑞尔东南方的路，然后在十字路口左拐。"
D.Strings[4880]="那么你是在找博文·布里斯博埃斯了。他居住在炉灰庄园大桥另一边，布瑞尔城镇西南部。"
D.Strings[4881]="黑色、灰色和深紫色是规定的颜色。朋友，看仔细了，可别迷失方向。博文·布里斯博埃斯可以帮助你。你可以穿过镇子西南的桥梁，去炉灰庄园找他。"
D.Strings[4882]="你看起来好像迷路了。"
D.Strings[4883]="你看我像个向导吗？好极了，你需要什么？"
D.Strings[4884]="艾瓦，我的鬼灵精华不见了。我需要另外一个。"
D.Strings[4885]="真冷……我很饿。$B$B我可怜的朋友，希望你已经安息了。我不忍心去想他们会对你做什么。$B$B你！嘿，就是你！请你一定要帮我逃跑。他们之中的某个人身上肯定有钥匙，你能找到它吗？我知道他们有钥匙。如果你弄到钥匙，就可以帮我离开这里了。特雷可能已经死了，但是我还心存希望！求你了，帮帮我吧！"
D.Strings[4886]="你不能阻止我逃离这儿，$r！"
D.Strings[4887]="你把我关在牢笼里太久了！"
D.Strings[4888]="你会为你对特雷所做的事情付出代价的！"
D.Strings[4889]="你已经为我做了很多事情，$n。谢谢你。$B$B现在我至少可以告诉你，我是怎么来到这里的。我和我的好朋友特雷·莱弗治潜入加德纳尔调查暗影议会，然后就在毫无准备的情况下被他们抓住了。他们把特雷带到暗影堡的深处，并把我关在这里，他们把我们所有的装备都拿走了……我仍然可以听到他的惨叫，$n。他们……简直丧心病狂。我不知道他们都对他做了些什么，但他们会为此付出代价的。"
D.Strings[4890]="当你检查牢笼和关在里面的暗夜精灵时，你有一种奇怪的似曾相识的感觉。不知为什么原因，她的目光从未与你接触——好像你对她来说并不存在一样。"
D.Strings[4891]="准备。各就各位。出发！"
D.Strings[4892]="嘿！这不公平！"
D.Strings[4893]="我赢了！！"
D.Strings[4894]="想再比一次吗？三局两胜！"
D.Strings[4895]="你这个骗子！"
D.Strings[4896]="%s看起来非常困乏……"
D.Strings[4897]="看起来非常困乏……"
D.Strings[4898]="这儿看上去是个休憩的好地方。"
D.Strings[4899]="他们并未意识到自己已经死了，$r。他们受到诅咒，在头脑中保留了这个城镇被毁灭之前的记忆，大部分是这样，还有一部分人更为不幸。$B$B你认为是亡灵天灾所为？那时亡灵天灾还不存在呢，就算是它们的话，我们也会与它们展开一场恶战的。$B$B不，这场恐怖而极具破坏性的灾难源于通灵学院，它摧毁了整座城镇，无人生还。$B$B让我独自承受这悲伤吧。"
D.Strings[4900]="你没看到我们正在准备迎接乌瑟的访问吗？现在别妨碍我，我有许多工作要做！"
D.Strings[4901]="你尝过我们的面包吗？面包师玛斯特森是最具天才的烹饪师！"
D.Strings[4902]="陌生人，欢迎来到凯尔达隆。"
D.Strings[4903]="陌生人，我们并不是粗鲁的家伙，只是大家都忙于在乌瑟到来之前确保一切顺利。光明使者能来到我们的城镇，这可真难得。"
D.Strings[4904]="我们美丽的岛屿迎来了新的一天。"
D.Strings[4905]="小心点，陌生人。别在我们的镇子里惹事。"
D.Strings[4906]="我被你吸引住了，$r。"
D.Strings[4907]="我憋了一肚子的火，别让我朝你发火。"
D.Strings[4908]="哎呀，你看起来就像是一个普通的街头顽童！"
D.Strings[4909]="在凯尔达隆，你不能四处游荡、行乞、诅咒、斗殴，也不能随心所欲 。"
D.Strings[4910]="为巫妖王欢呼！"
D.Strings[4911]="你的灵魂注定毁灭！"
D.Strings[4912]="加入我们，否则就去死吧！"
D.Strings[4913]="没有希望了！"
D.Strings[4914]="我们的主人想要你的灵魂！"
D.Strings[4915]="达隆郡必将陷落！"
D.Strings[4916]="亡灵天灾会获胜的！"
D.Strings[4917]="所有的希望都破灭了！"
D.Strings[4918]="我们不能放弃！"
D.Strings[4919]="战斗！为了达隆郡战斗！"
D.Strings[4920]="我们的队长倒下了！"
D.Strings[4921]="联盟抛弃了我们！"
D.Strings[4922]="白银之手在哪儿？我们需要他们的帮助！"
D.Strings[4923]="为了你们的家人战斗！不要放弃！"
D.Strings[4924]="如果我们失败的话，达隆郡就完了！"
D.Strings[4925]="我们必须阻止这些邪恶的亡灵！"
D.Strings[4926]="诅咒神教正在迅速壮大。从小型村落到首都，从部落到联盟，几乎每座城镇的居民中都有诅咒神教的信徒。$B$B别惊讶，他们只在仪式和庆典上面才身穿统一的服饰。你很可能已经跟他们的信徒碰过面了，只是你不知道而已。"
D.Strings[4927]="是吗？这是他们一贯的操作手法。对克尔苏加德和快速增长的亡灵天灾军队来说，什么东西拥有更大的价值？一个能成功潜入某个组织，然后使数千人丧命的狂热追随者，还是一个普通到掉渣的亡灵士兵？很明显你不是那么愚蠢。$B$B没错，$r，他们就在你周围，生活着，工作着，密谋着。"
D.Strings[4928]="这真令人沮丧。我能做点什么来阻止这一切吗？"
D.Strings[4929]="停下来——不。放慢速度——或许这样比较好。$B$B通灵学院是他们接受初级训练和教育的地方。信徒们从那儿走出来，并最终进入我们的社会。$B$B这就是我们必须攻破通灵学院的原因。它是诅咒神教的中心！"
D.Strings[4930]="你要我去杀谁？"
D.Strings[4931]="放慢速度，$c。你要杀的人已经死了，对着尸体狂砍是无济于事的。可以真正摧毁僵尸的方法极少，而且你我也无法使用这些方法。为此，我制定了一项计划，这项计划将对诅咒神教产生巨大的影响。"
D.Strings[4932]="你有什么计划？"
D.Strings[4933]="这很简单，真的。从莱斯·霜语的身上夺走他的力量。将他变回普通的形态，然后果断地杀死他。"
D.Strings[4934]="莱斯·霜什么……？那是谁？"
D.Strings[4935]="啊，我想我说得太快了。莱斯·霜语是通灵学院的管理者，他负责训练所有的黑暗大师，他是克尔苏加德最欣赏的学生和下属。他曾经是激流堡的法师，一个从来没有接受过达拉然正规训练的流浪巫师。$B$B当克尔苏加德开设诅咒神教的时候，莱斯就是首批加入其中的人，因为他知道通过黑暗魔法可以获得不朽。"
D.Strings[4936]="他真的获得了不朽之身。他很快从众多信徒中脱颖而出，巫妖王随即授予了他永生的权力。巫妖莱斯·霜语因此而诞生。$B$B你明白吗？"
D.Strings[4937]="是的。"
D.Strings[4938]="很好。为了实现我们的计划，我们必须首先制造一块生命徽章。你准备好了吗？"
D.Strings[4939]="有人没有受到记忆的折磨。"
D.Strings[4940]="告诉我关于诅咒神教的事情。"
D.Strings[4941]="你必须拯救我们！"
D.Strings[4942]="我很抱歉。这次我不能帮你。"
D.Strings[4943]="巴罗夫家族让我忙个不停。总有一些垃圾从那儿出来。"
D.Strings[4944]="我的头衔是废物管理专家。"
D.Strings[4945]="也许你应该对着这些套在我愤怒的拳头上的扩音器讲话。"
D.Strings[4946]="啊，我心爱的白兰地，我太思念她了！"
D.Strings[4947]="保持警惕！这一带有许多黑木熊怪……"
D.Strings[4948]="真安静……太安静了……"
D.Strings[4949]="很高兴见到你，朋友。我是军官加鲁什，是银色黎明这一世界组织的光荣成员。我们的任务是毫不留情地消灭艾泽拉斯大陆上所有邪恶的势力。银色黎明不是一个政治机构，我们也从不愿意与政治沾上边儿。我们的目标只有一个，为此我们将部落和联盟都看作自己的朋友——以铲除邪恶为己任的朋友！$B$B我的$g兄弟:姐妹;，为十字军而战！"
D.Strings[4950]="你好，朋友。我是普尔哈特，隶属于银色北伐军这个世界性的组织。我们的目标非常简单——与艾泽拉斯的一切邪恶力量进行顽强而坚决的战斗。我们不是一个政治团体，也不想成为那样的团体。为了银色北伐军的伟大目标，为了剿除世界上的一切邪恶，我们将联盟和部落的成员都当作并肩作战的朋友来看待！$B$B为了黎明而战，我的$g兄弟:姐妹;！"
D.Strings[4951]="%s从地下喷涌而出！"
D.Strings[4952]="呼……"
D.Strings[4953]="嗯？你想要什么？"
D.Strings[4954]="%s被引到了开阔地带！"
D.Strings[4955]="醒醒！"
D.Strings[4956]="银色黎明向你致敬，$c。我是哈萨娜——银色黎明为数不多经过授权的装备和军品军需官之一。$B$B既然你在我们委任下作战——同时赢得我们的尊敬和信任——你会从加鲁什军官那里得到英勇勋章。它们有两个作用：在我们的队伍中赢得地位，或者作为交换得到某些特殊物品。$B$B随着你在银色黎明地位的升高，你会发现你能够得到更多物品。"
D.Strings[4957]="加入对抗邪恶的战斗中吧！今天就去获得银色黎明的委任徽章吧！"
D.Strings[4958]="我还需要一枚银色黎明委任徽章。"
D.Strings[4959]="银色北伐军向你致敬，$c！我叫莱斯巴克，是银色北伐军委派的装备和物资军需官。$B$B如果你愿意接受任命，同邪恶力量作战——以此赢得我们的尊重和信任——你就能在军官普尔哈特那儿获得勇气勋章。勋章有两个用途：提高在我们阵营内的地位，或是获取特殊物品。$B$B随着你在银色北伐军内阵营地位的提高，你会发现自己能获得更多的物品。"
D.Strings[4960]="前进，十字军！我们必须夺回考林路口！"
D.Strings[4961]="加入对抗邪恶的战斗中吧！今天就去接受银色北伐军的委任吧！"
D.Strings[4962]="你好，$c。我是军需官米兰达·布利洛克——银色军团为数不多的授权装备和军品军需官之一。$B$B既然你在我们的委任下与邪恶战斗——同时赢得我们的尊敬和信任——你会从尼古拉斯·瑟伦霍夫公爵那里得到勇气勋章。勋章有两个作用：用他们赢得在军队中更高的地位，或者作为交换得到特殊物品。$B$B随着你在军团中地位的升高，你会发现你会有更多的物品。"
D.Strings[4963]="你好，$c。$B$B那边的哨兵允许我住在他们的营地，只要我答应不会再有麻烦了——我敢肯定你能意识到对外交的需要，是吗？$B$B我来调查这片土地的紊乱状况，既然这也有助于他们的事业，他们同意我在这里 只能协助艾泽拉斯各族之间脆弱的联盟关系。如果你想帮我，那么我会很感激，但无论如何，请不要引起任何麻烦。"
D.Strings[4964]="啊，我在燃烧平原的仆从带来了龙……"
D.Strings[4965]="马杜克，把箱子放在我面前！"
D.Strings[4966]="维克图斯大人，我觉得这个容器中有一些奇怪的东西……"
D.Strings[4967]="欢迎来到钢架补给站！"
D.Strings[4968]="种族并不代表荣誉，$r。只要你呆在我的农场，就请你记住并尊重这个信条。$B$B我曾见过一些兽人，他们像最高贵的骑士那样可敬；我还见过某些人类，他们像最残忍的亡灵天灾那样邪恶。$B$B啊，我不该拿我年轻时的故事来烦你的！要做的事情还很多呢——如果你很想找些事情做的话。"
D.Strings[4969]="我们还要努力去满足木材需求量。回去做你自己的工作吧。"
D.Strings[4970]="还没天黑呢，让你的斧头砍伐更多的木头吧。"
D.Strings[4971]="我们需要在今日之内装满货车。回去做你自己的工作吧。砍，砍！"
D.Strings[4972]="%s迅速收割着阴暗草。"
D.Strings[4973]="测试——攻击$n前死去"
D.Strings[4974]="测试——攻击$n后死去"
D.Strings[4975]="你溅出的鲜血会净化人性，异教徒！"
D.Strings[4976]="弗丁永远都不会再见到他的儿子了。"
D.Strings[4977]="跟我的小朋友打声招呼吧。"
D.Strings[4978]="你好，公民。你需要指引吗？"
D.Strings[4979]="我能帮你找到你要寻找的东西吗？"
D.Strings[4980]="你看起来有些迷茫。你在找谁？"
D.Strings[4981]="你是新来的吗？嗯，告诉我你在找什么吧。"
D.Strings[4982]="我需要指引。"
D.Strings[4983]="银行？哦，这附近最近的银行就是暴风城会计室。沿着暴风城大门不远的那条路向前走就是。"
D.Strings[4984]="哦，你一定是说暴风城会计室。走进城门之后，它就在贸易区的西南部。"
D.Strings[4985]="如果你想乘坐狮鹫的话，就去找暴风城的狮鹫管理员吧。当你进入英雄谷时，应该就能看见右边的狮鹫降落台。"
D.Strings[4986]="狮鹫管理员监管着飞进飞出暴风城的所有狮鹫。如果你想乘坐狮鹫的话，就去找他吧。"
D.Strings[4987]="我相信奥德文·拉弗林仍是暴风城的常驻公会注册员。当你进入暴风城的贸易区后，你的左手边就是他的居所。"
D.Strings[4988]="这些日子以来，所有的官方事务都是在暴风城处理的。如果你想要组织公会的话，就去暴风城接待中心吧。"
D.Strings[4989]="到闪金镇的狮王之傲旅店去吧。那儿有啤酒和柔软的床铺供你尽情享用，没有比那里更好的休息场所了。"
D.Strings[4990]="闪金镇的狮王之傲旅店是这个地区中最好的旅店了。在那儿歇一歇吧，旅店老板法雷会让你感受到家的温暖。"
D.Strings[4991]="在艾尔文森林只有少数职业的训练师。你在找谁？"
D.Strings[4992]="德鲁伊？我没看到过任何德鲁伊。不过在暴风城中有一块属于暗夜精灵的区域。"
D.Strings[4993]="我听说暴风城中有个矮人因狩猎技巧高超而闻名。或许你可以找他问问看。"
D.Strings[4994]="洁塞塔经常帮助镇子里的守卫，她是圣光赐予我们的礼物。如果你想学习牧师技能的话，可以去狮王之傲旅店找她。"
D.Strings[4995]="我敢打赌洁塞塔会很乐意教你学习新法术的。她就在狮王之傲旅店的房间内。"
D.Strings[4996]="扎尔迪玛可能会教你一些新的法术。他最近喜欢待在狮王之傲旅店，你可以去那里的房间看看他在不在。"
D.Strings[4997]="我对魔法知之甚少，但是在狮王之傲有一个名叫扎尔迪玛的法师，他也许能帮助你。"
D.Strings[4998]="你通常可以在铁匠铺的后面发现威尔海姆修士和里瑞亚互相讲故事。他总是很乐意向圣骑士们传授新的技艺。"
D.Strings[4999]="威尔海姆修士经常在闪金镇的锻冶场后面培训里瑞亚·杜拉克。你可能会从他那里学到一些圣骑士的知识。"
D.Strings[5000]="一个潜行者？嗯……我曾听说过那个科瑞恩·塞尔留斯在那些阴暗的地方游荡。找她谈谈，看看你能学到点什么。"
D.Strings[5001]="我打赌科瑞恩·塞尔留斯知道你在寻找什么东西。她通常在狮王之傲旅店里。"
D.Strings[5002]="这附近很少有人像科瑞恩·塞尔留斯一样精通于刀刃的使用技巧。到铁匠铺后面找她看一下她有没有心情教你些新东西。"
D.Strings[5003]="要是你想接受训练的话，就去找科瑞恩。她通常在铁匠铺外面等着铁匠打造武器。"
D.Strings[5004]="哦……好吧，玛克西米利安是这附近唯一一个了解黑暗魔法的人。你也许可以在狮王之傲旅店那阴暗的地下室里找到他。"
D.Strings[5005]="一个术士？好吧，如果我是一个术士，我可能会待在这附近最黑暗的地方……那就是狮王之傲旅店的地下室。你应该先到那里去看看。"
D.Strings[5006]="我知道有些人在这附近练习某些专业。你想要打听哪项专业技能的训练师？"
D.Strings[5007]="听说那个隐士玛洛瑞有时会为当地居民配制药剂，他居住在暴风城和北郡之间的小山上。"
D.Strings[5008]="居住在北郡和暴风城之间的山上的一位炼金师或许能帮上忙。你为什么不去找他呢？"
D.Strings[5009]="铁匠阿古斯居住在闪金镇。我想他能教你如何做一名铁匠。"
D.Strings[5010]="你一定是在寻找铁匠阿古斯。如果你需要接受训练的话，他通常在闪金镇监督铸造工作。"
D.Strings[5011]="托马斯也许不是最好的厨师，但是他确实能做一些精美的菜肴。如果你想学习厨艺的话，就去狮王之傲旅店找他吧。"
D.Strings[5012]="你为什么不到狮王之傲看看呢？那里的厨师可能会教你几道好菜。"
D.Strings[5013]="不，我不认为在艾尔文森林中有附魔师。但是，在暴风城中有个名叫鲁坎的家伙，他开了一家商店。你可以去找他，看他是否能训练你。"
D.Strings[5014]="嗯……这附近唯一有附魔训练师的地方就是暴风城了。你为什么不问一下暴风城的守卫呢？"
D.Strings[5015]="我通常将那种事情留给侏儒去做。要是你想学习这项专业的话，我想你可以在暴风城找到一些侏儒来训练你。"
D.Strings[5016]="暴风城中的某位侏儒肯定能教你，而且我相信暴风城的守卫能为你指明方向。"
D.Strings[5017]="我最近在这里附近遭遇过一些迪菲亚盗贼，但米歇尔·贝利帮我进行了治疗。到狮王之傲与她商量一下，看看她能否教你。"
D.Strings[5018]="米歇尔·贝利对病患的态度令人钦佩！她也许无法教你如何对待病人，但是她可以教你一些急救技巧。她现在居住在狮王之傲旅店。"
D.Strings[5019]="李·布朗整天都在水晶湖钓鱼。或许他能给你讲些故事，还能教你一些技巧。"
D.Strings[5020]="李·布朗在水晶湖中抓到过很多奇怪的东西。他说他数月前钓起过一个神秘的面具。但是照实说，我想他那晚一定在狮王之傲喝多了。"
D.Strings[5021]="草药师博米洛伊为居住在北郡和暴风城之间的山上的一名炼金师收集草药。去他的住所找草药师博米洛伊，看她是否能对你有所指引。"
D.Strings[5022]="有一名草药师跟炼金师一同居住在暴风城东面的山上。完美的搭配，不是吗？"
D.Strings[5023]="水晶湖边居住着一位名叫艾德勒·费欧德的女士。她利用从当地剥皮师海伦尼那儿得来的皮革为当地的守卫制作补丁。如果你想要学习这项专业技能，她也许就是你要找的人。"
D.Strings[5024]="艾德勒·费欧德的皮革手艺在艾尔文森林已经妇孺皆知了。她的家就在水晶湖旁边。"
D.Strings[5025]="如果你想学习挖矿的话，最好前往暴风城的矮人区。那里的某个矮人肯定会教给你这门技能。"
D.Strings[5026]="我认为你在暴风城会交到好运的。去问问那儿的守卫，他们会给你指明方向。"
D.Strings[5027]="海伦尼·派特斯金纳有着数年的剥皮经验，他一直为艾德勒·费欧德提供兽皮以制造皮革制品。你可以在水晶湖旁的房间里找到她。"
D.Strings[5028]="在水晶湖畔居住着一名技艺高超的剥皮师。她可以教你这项专业的入门技能。"
D.Strings[5029]="艾尔丁是艾尔文森林中唯一称得上裁缝的人。要是你对这个专业感兴趣，就去东谷伐木场找他吧。"
D.Strings[5030]="你想学习成为一个裁缝？嗯……我相信在东谷伐木场有一个裁缝可以教你。"
D.Strings[5031]="你看起来有些迷茫。我能帮你什么忙吗？"
D.Strings[5032]="你需要我帮助你寻找什么东西吗？"
D.Strings[5033]="最近的银行就是铁炉堡银行，$g小伙子:姑娘;。"
D.Strings[5034]="铁炉堡银行是这一带最近的银行。"
D.Strings[5035]="丹莫罗一带是没有狮鹫管理员的，$g小伙子:姑娘;。如果你想骑狮鹫去什么地方的话，就必须去铁炉堡。"
D.Strings[5036]="最近的狮鹫管理员居住在铁炉堡的大锻炉附近。如果你想乘坐狮鹫的话，就前往铁炉堡吧。"
D.Strings[5037]="所有的官员都居住在铁炉堡。你得去铁炉堡访客中心领取公会登记表。"
D.Strings[5038]="要是你需要一些公会登记表的话，就前往铁炉堡，去拜访铁炉堡访客中心吧。"
D.Strings[5039]="雷酒家族在卡拉诺斯开了一家旅店，久负盛名。在那里喝杯酒休息一下吧。"
D.Strings[5040]="哦，旅店是吗？嗯，雷酒酿制厂是最棒的。你可以在那里稍事休息，但是你一定得尝尝那儿的啤酒。"
D.Strings[5041]="这附近只有一名猎人，那就是格瑞夫。他就站在卡拉诺斯的铁匠铺外。"
D.Strings[5042]="假如你问我的话，我想格瑞夫在动物身上花费的时间过多了。到目前为止，没人比他更精通于猎人之道。去卡拉诺斯的铁匠铺外面找他吧。"
D.Strings[5043]="住在雷酒酿造厂的一名法师或许能教你一些新的魔法。我想他名叫玛济斯·石衣。"
D.Strings[5044]="你肯定你不想当一名战士？那好吧，如果你真想学习动动手指的把戏，你最好去找雷酒酿制厂的玛济斯·石衣谈谈。"
D.Strings[5045]="哦……一个圣骑士？嗯，$g小伙子:姑娘;，你真走运！阿扎尔·战锤刚结束训练，他现在在卡拉诺斯的雷酒酿制厂。"
D.Strings[5046]="你需要接受些训练？好吧，阿扎尔·战锤总是愿意教给年轻的圣骑士一点东西。你为什么不去雷酒酿制厂找他呢？"
D.Strings[5047]="哦，是牧师吗？要是你想接受训练的话，就去雷酒酿制厂找马克萨恩吧，他一定在那儿喝酒呢。"
D.Strings[5048]="你肯定可以在雷酒酿制厂看到马克萨恩·安沃尔大口喝酒。为什么你不去喝一点，顺便看看他能教你点什么新鲜东西呢？"
D.Strings[5049]="那么，似乎我们都是来找霍格拉尔·巴坎的。他是个矮人，他迟早会去 雷酒酿制厂喝酒的，没准他现在已经在那儿了。"
D.Strings[5050]="你在寻找霍格拉尔？那你找过旅店吗？啊！如果你在找一个潜行者，而他同时还是一个矮人，你应该从旅店开始！先去看一下。"
D.Strings[5051]="术士……我可不在乎他们。就像那个在雷酒酿制厂外开设商店的吉姆瑞兹。都是他，那儿的啤酒可能都跑了气！术士……呸！"
D.Strings[5052]="我告诉你，掌握那种魔法可不是什么好事。我不知道为什么他们会允许吉姆瑞兹在雷酒酿制厂外面安营扎寨！离他远点！"
D.Strings[5053]="哦！这可是你说的！我敢打赌格兰尼斯·快斧会向你展示如何挥动武器的。他现在在卡拉诺斯的雷酒酿制厂。"
D.Strings[5054]="格兰尼斯·快斧能把一条鱼给喝趴下，而且还能把斧头抡得虎虎生风。如果你想接受训练的话，就去找他吧。"
D.Strings[5055]="不，在丹莫罗是没有炼金师的。你最好去铁炉堡……去工匠区找侏儒。"
D.Strings[5056]="我听说铁炉堡中有家由精通炼金术的侏儒所经营的商店。你该去看看。"
D.Strings[5057]="哦！这是一项极有价值的技能。托格努斯以你从未见过的方式敲击铁砧。为什么你不去跟他谈谈，看看他能教你什么？"
D.Strings[5058]="当你在卡拉诺斯的时候，你可能会听到托格努斯在铁砧上敲打。然而，如果你还没有把耳朵里的蜡清理掉，那你为什么不到铁匠铺去看看呢？"
D.Strings[5059]="一瓶雷霆啤酒外加格雷姆罗克做的菜就足以让你饱餐一顿。如果你想成为一名厨师的话，就该去参加他的培训。"
D.Strings[5060]="格雷姆罗克烹饪的手艺不一定是最好的，但他确实有些美味的食谱值得学习。到雷酒酿制厂找他聊聊，看看他能教给你什么。"
D.Strings[5061]="据我所知，丹莫罗是没有附魔师的。如果你想成为一名附魔师的话，就去铁炉堡吧。"
D.Strings[5062]="如果你一心想学附魔的话，你该到铁炉堡看看。我记得上次我到那里的时候曾看到狮鹫旁边有一家商店。"
D.Strings[5063]="你应该去钢架补给站找布隆克。当他不忙着修补一些奇怪装置的时候，他通常就在跟飞行员们聊些关于他们的蒸汽坦克的事。"
D.Strings[5064]="布隆克总是在敲敲打打，他擅长修理最为精密的机械。你应该到钢架补给站拜访他一趟。"
D.Strings[5065]="急救虽然不能代替牧师的治疗，但是它在紧要关头却很方便。我建议你去跟雷酒酿制厂的萨姆诺谈谈，并力所能及地学习一些东西。"
D.Strings[5066]="好心的萨姆诺前些天在我与一个肮脏的穴居人战斗后替我包扎了伤口。我现在已经完全痊愈了！我敢肯定萨姆诺会很高兴教你制作绷带的。"
D.Strings[5067]="这周围可不是钓鱼的好地方，但是你应该去找帕克斯顿问问看。他在涌冰湖钓鱼。"
D.Strings[5068]="这附近只有几处地方可以钓鱼。帕克斯顿对此了如指掌，但是他不一定都会告诉你。为什么不去涌冰湖找他谈谈呢？"
D.Strings[5069]="有些弱小的植物竟然能在丹莫罗的寒风中开花，这真令人惊奇……但是这儿没有草药师。你得去铁炉堡接受草药师的训练。"
D.Strings[5070]="不，这儿没人能教你草药学。你最好去铁炉堡碰碰运气。"
D.Strings[5071]="要是你想学习制皮的话，就去铁炉堡吧。我听说大锻炉附近有间商店，你可以那儿学到制皮的知识。"
D.Strings[5072]="铁炉堡是学习制皮的最佳场所。要是我没记错的话，你可以去大锻炉旁的商店。"
D.Strings[5073]="这么说，你以为在这个城镇里没有常驻矿工，是吗？错！在卡拉诺斯外的钢架补给站附近去找亚尔吧。"
D.Strings[5074]="矿工？你不需要问有没有，$g小伙子:姑娘;，只需问在哪里！亚尔就是你要找的家伙，我想他应该在钢架补给站那里。"
D.Strings[5075]="丹莫罗这里可没有剥皮匠，$g小伙子:姑娘;，如果你想要学习剥皮的话，就到铁炉堡去找找吧。"
D.Strings[5076]="剥皮匠通常会把所有的兽皮豆带到铁炉堡去风干。你为什么不去那儿看看是否能找人训练你呢？"
D.Strings[5077]="啊，石眉这些日子不怎么离开铁炉堡的，如果你想要学做一名裁缝的话，就去铁炉堡找他吧。"
D.Strings[5078]="嗯，似乎你在寻找裁缝时并不顺利。但是，有很多高明的裁缝都居住在铁炉堡。你为什么不去问问那里的守卫呢？"
D.Strings[5079]="泰达希尔有许多你需要去看看的地方。告诉我你在找什么。"
D.Strings[5080]="银行位于平静的达纳苏斯城。如果你想存储自己的财物的话，就得去那儿。"
D.Strings[5081]="要是你想找银行的话，就去达纳苏斯的中央地带。你可以在那儿存储自己的财宝。"
D.Strings[5082]="鲁瑟兰码头"
D.Strings[5083]="想要找到鲁瑟兰村的渡船，你得先去达纳苏斯，通过传送门进入鲁瑟兰村。"
D.Strings[5084]="狮鹫会从泰达希尔底部的鲁瑟兰村出发前往洛达内尔。达纳苏斯的传送门会让你安全抵达鲁瑟兰村。"
D.Strings[5085]="公会注册员及公会商人"
D.Strings[5086]="官方事宜只能送交达纳苏斯处理。你必须前往那儿去创建自己的公会。"
D.Strings[5087]="诸如公会登记表等文档可从达纳苏斯的公会注册员那儿获得。"
D.Strings[5088]="你可以在多兰纳尔旅店的老板凯达米尔提供的床上安稳地睡一觉。"
D.Strings[5089]="如果你需要通过休息恢复体力的话，多兰纳尔的旅店是你最佳的选择。旅店老板凯达米尔将帮你打点一切。"
D.Strings[5090]="你可以在多兰纳尔周围找到众多的训练师，他们有丰富的经验可以传授给你。你想要找哪一位？"
D.Strings[5091]="你在寻找一个德鲁伊的训练师？那么你应该到多兰纳尔旅店南面的月亮井去见见卡尔。"
D.Strings[5092]="德鲁伊训练师卡尔通常待在多兰纳尔的月亮井。我想他可以对你进行训练。"
D.Strings[5093]="要是你想找猎人的话，就去拜访达扎拉吧。他通常在多兰纳尔旅店的外面。"
D.Strings[5094]="达扎拉以他的狩猎技能在多兰纳尔小有名气。为什么不找他谈谈，看看他能教你点什么呢？"
D.Strings[5095]="一位名叫劳尔娜·晨光的女祭司住在多兰纳尔，我认为你可以在旅店北面找到她。"
D.Strings[5096]="劳尔娜·晨光为居住在多兰纳尔附近的居民们提供医疗服务。或许她能教你如何成为一名牧师。"
D.Strings[5097]="潜行者？我不习惯跟那些家伙打交道，但我相信詹诺克就是你要找的训练师。你可以在多兰纳尔的旅店找到他。"
D.Strings[5098]="你在找寻一个潜行者？我认为詹诺克很适合你的描述。你为什么不到多兰纳尔的旅馆里去找他谈谈呢？"
D.Strings[5099]="凯拉·风刃的战斗技能炉火纯青。她可以对你进行训练。到多兰纳尔的旅店中去找她吧。"
D.Strings[5100]="我以前曾有幸看到在凯拉·风刃作战，因此我相信她可以好好训练你。到多兰纳尔旅店去找她吧。"
D.Strings[5101]="从事某种专业的学习是一个长期的过程，但是回报很丰厚。你想选择什么样的专业？"
D.Strings[5102]="塞恩德拉的态度非常和蔼，她的药剂也很不错。你可以在多兰纳尔旅店的东边找到她。"
D.Strings[5103]="塞恩德拉在炼金术方面的知识有些局限，但是我相信那也足够领你入门了。她就在多兰纳尔旅店的东面。"
D.Strings[5104]="扎瑞恩看起来很了解烹饪行业。为什么你不去看看他是否会给你一些食谱呢？他通常在多兰纳尔的旅店旁边烹饪。"
D.Strings[5105]="我们当然欢迎多兰纳尔的厨师再多几个，但我并不是说扎瑞恩厨艺欠佳。你为什么不去找这个厨师看看他能教你什么？"
D.Strings[5106]="奥兰纳·鸦眼将她的天赋部分归结为与神谕林地的灵魂进行了交流。你应该能在那儿找到她的。"
D.Strings[5107]="阿兰娜大部分时间都在神谕林地练习技能。如果你想学做一名附魔师的话，就去那儿找她吧。"
D.Strings[5108]="拜恩希经常为在野外巡逻的哨兵服务。如果你想学习急救的话就该找她谈谈。"
D.Strings[5109]="拜恩希在急救方面的技巧已经很知名了。如果你想向她学习的话，你可以到多兰纳尔旅店的北面去找她。"
D.Strings[5110]="奥拉密斯湖近来遭受袭击，所有的渔夫都已经搬迁到达纳苏斯了。你应该去那儿看看。"
D.Strings[5111]="林精使渔民在多兰纳尔很难有所收获。你最好去达纳苏斯找找他们。"
D.Strings[5112]="不知道玛洛尼是如何采集到那些最为娇嫩的草药的。显然你得向他多多学习。他就住在多兰纳尔的旅店东边。"
D.Strings[5113]="要学习草药学，你得向玛洛尼好好讨教。去多兰纳尔旅馆东边找他吧。"
D.Strings[5114]="纳迪娅·织发离开自己的家园前往达纳苏斯进修去了。她精通制革，而且是一名优秀的老师。你该去向她求教。"
D.Strings[5115]="纳迪娅在数年的实践中掌握了制皮技术。沿着通往达纳苏斯的道路向西走，去拜访她，或许她能传授给你一些知识呢。"
D.Strings[5116]="拉德纳尔为纳迪娅提供大量的兽皮。如果你想学习剥皮技术的话，我建议你跟他谈谈。"
D.Strings[5117]="你可以在去达纳苏斯的路上看到拉德纳尔在他的屋外练习手艺。你应该停下来看看他有什么可以教你的。"
D.Strings[5118]="我敢肯定在达纳苏斯有一个裁缝可以对你进行训练。当你到了那里之后，就向达纳苏斯的某个哨兵询问一下裁缝住在哪里吧。"
D.Strings[5119]="裁缝所需的多数物品都是从达纳苏斯获得的。他们都在那儿工作，这并不是件奇怪的事情。要是你想成为一名裁缝的话，你最好前往达纳苏斯。"
D.Strings[5120]="帮帮我！你一定要帮帮我！"
D.Strings[5121]="你好，$c。我在亡灵壁垒设立营帐，准备进入瘟疫之地。不久之前，谣传有一位伟大的人类巫师居住在壁炉谷。血色十字军强迫他为他们的战士和猎人制造新的弓箭和枪支。据说在十字军杀死他之前，他正在铸造一件非比寻常的武器。$B$B我猜想他们对奥术越来越不信任了。"
D.Strings[5122]="你好，$c。没有多少时间谈话——我在动身去壁炉谷之前只是把冰风营地作为暂留地休息一下。我曾听到传言在他们疯掉之前，血色十字军强迫一个法师为他们工作，为他们的士兵制造强大的弓箭和枪支。我不敢肯定他成功与否……十字军在他们的成品制成之前杀死了他。或许他们杀死他为了保密……也可能他们不太信任奥术。"
D.Strings[5123]="你……你好，$n。对不起，我正从伤势中恢复过来。$B$B那些血色十字军比我料想的要凶猛的多。他们几乎在里面干掉了我。$B$B你也应该多加小心。我不愿看到他们先发制人。"
D.Strings[5124]="我的家人过去在北山伐木场工作，那里现在被称作西瘟疫之地。他们曾忠于杜马家族，而现在血色十字军把一切连同壁炉谷全都占领了！$B$B在把那些狂热分子从艾泽拉斯驱逐出去之前，我是不会停止行动的。"
D.Strings[5125]="在最后一次大战之前，我父亲经营着北山伐木场。那是他的命根子，他把所有的精力都投到了伐木场。战争爆发时，我们忍痛逃到了暴风城。$B$B那些日子里，我们失去了无数朋友，而我们的伐木场也被血色十字军占领了，我对此感到非常心痛。$B$B这就是我回来的原因。"
D.Strings[5126]="修道院的那些傻子给我们送来了鲜肉。"
D.Strings[5127]="这片土地现在属于迪菲亚兄弟会！"
D.Strings[5128]="我们是熊怪家族仅剩的成员了……木喉部落还未堕落，但是其他部落对我们怀有相同的敌意；有熊怪能免于堕落……很多人都认为这是不可能的……$B$B我的兄弟们对那么急于与我们为敌的家伙非常生气，现在他们已经开始攻击任何靠近我们的生物；他们谁都不信任。$B$B但是，如何你能努力证明想要和他们和平相处的话，他们或许会把你当作盟友的。"
D.Strings[5129]="我怎么才能向木喉的熊怪证明我自己呢？"
D.Strings[5130]="你必须想办法来证明你们两个是在同一条战线上的。尽管现在木喉可能会攻击你，但如果你够勤奋的话，你就会找到办法的。$B$B你一定要记住，任何对木喉熊怪的攻击都会大大降低你们赢得与他们结盟的机会。$B$B有个不错的着手点就是在费伍德森林的许多部分都发现的死木熊怪。这些熊怪是木喉部落的敌人，杀了他们将会大大提高你在木喉中的地位。"
D.Strings[5131]="我们能让你安全通过这儿，但是，你得证明自己值得我们给予帮助。"
D.Strings[5132]="冬泉熊怪怎么样？"
D.Strings[5133]="居住在冬泉谷的寒水熊怪曾经是我们的盟友……但是有一天，这一切都改变了。$B$B他们听从高级首领的号令，开始攻击他们接触到的任何生物，包括我们的部族。他们现在几乎不与外界接触了……"
D.Strings[5134]="请不要打扰我……你们这种人都一样……"
D.Strings[5135]="我只信任你所在种族中的少数人，$n。但是我把你当朋友。"
D.Strings[5136]="是的，是的。我看到你了。$B$B在去找你的路上。你可能已经赢得了一些人的信任，但要向我证明可并不仅仅如此！"
D.Strings[5137]="我没时间理你，$r。你还是继续走你的路吧。"
D.Strings[5138]="如果你能证明自己是个真正的盟友，我或许会考虑训练你的……"
D.Strings[5139]="欢迎你，$n！你想学作一名裁缝？"
D.Strings[5140]="我想接受训练。"
D.Strings[5141]="才这么点报酬，真亏！"
D.Strings[5142]="是清理这些垃圾的时候了！"
D.Strings[5143]="我会让你灰飞烟灭！"
D.Strings[5144]="大胆！"
D.Strings[5145]="红茶，要吗？"
D.Strings[5146]="别与圣光作对，$c，或许有一天它能拯救你。"
D.Strings[5147]="我相信圣光会与你同在，$n。我能帮忙吗？"
D.Strings[5148]="愿圣光与你同在，$n。我能为你做什么吗？"
D.Strings[5149]="你当心些，$c。尊重我们的方式，否则你和你的人们就会受到诅咒。"
D.Strings[5150]="我这个无足轻重的仆人能为你做什么，$n？需要训练吗？"
D.Strings[5151]="我的智慧就是你的智慧，我的知识也一样。我能为你做什么，$n？"
D.Strings[5152]="我在找人，$c。请不要打扰我……这对我很重要。"
D.Strings[5153]="我是来自东部王国的信使，$n。我到这儿来是确保来此的牧师已经受到正确指示。"
D.Strings[5154]="安静！你没听见主人在讲话吗？"
D.Strings[5155]="少说废话，认真听讲。"
D.Strings[5156]="如果要孵化出我们的龙的话，我们必须集中精力！"
D.Strings[5157]="肃静！我不能漏掉这次讲座任何一句话！"
D.Strings[5158]="你忘记自己的学生服了吗？你认为时尚比亡灵天灾的统治更重要吗？"
D.Strings[5159]="你完成了昨天的作业吗？要是完成了，就过来跟我坐一块吧！"
D.Strings[5160]="小心点，$g男孩:女孩;。主人能洞察一切……"
D.Strings[5161]="你带来了课本吗？我能和你一起看吗？"
D.Strings[5162]="我可以问，你在这里做什么吗？穿上你的学生服装，然后学习！"
D.Strings[5163]="肃静！你认为那些被感染的龙会自己孵蛋并哺育幼龙吗？"
D.Strings[5164]="你来自燃烧平原吗？你有黑龙蛋吗？"
D.Strings[5165]="你的精神不够集中。你对我隐瞒着什么吗?"
D.Strings[5166]="我感觉一场动乱潜伏在你周围……"
D.Strings[5167]="你的未来乌云密布。集中精力，再问一次。"
D.Strings[5168]="你看起来不像是个学生……"
D.Strings[5169]="如果你翻到34页的话，你会看见矮人被解剖的图片……"
D.Strings[5170]="看看龙食谱的精妙吧。只有恐惧之肉才能满足他们。"
D.Strings[5171]="我们在等一批来自燃烧平原的黑龙蛋。我们相信，通过研究我们能大幅度地增进知识。"
D.Strings[5172]="最早产下的龙蛋尚未成熟，但是通过耐心地研究，飞龙很快就能孵出了。"
D.Strings[5173]="从昨天的实地考察来看，马杜克表示巨龙可以食用近期被杀人类的肉，但是只有痛苦缓慢地死去人的肉才行。"
D.Strings[5174]="明天我们将开始训练这些大有前途的龙，别忘了带上你的玩具骨头。"
D.Strings[5175]="巫妖王的势力渐渐扩大。我们的时间安排必须支持他的计划。"
D.Strings[5176]="当准备龙的食物时，一定要给它找点乐子。它对饭前娱乐反应不错。"
D.Strings[5177]="这只科多兽显然不是我最初召唤的那只。我在想科多兽诱引器是否能为我所用。"
D.Strings[5178]="瘟疫之地是对付天灾亡灵绝佳的地方！"
D.Strings[5179]="贝蒂娜，我能再要一个黎明先锋吗？我想再次测试一下……"
D.Strings[5180]="我的箭用光了！如果还有来进攻的话，你们就要靠自己对付了，我的朋友。"
D.Strings[5181]="等等……你听到了吗？有东西从西面逼近了！"
D.Strings[5182]="赞美月神！要是没有你这个朋友，我不知道自己还能不能生还。"
D.Strings[5183]="我的腿现在感觉好多了，治疗肯定起作用了。请原谅我，我必须去向我的上级汇报这里发生的事情。"
D.Strings[5184]="谁敢在我的领地里向我挑战？！"
D.Strings[5185]="我刚刚射了一支箭。"
D.Strings[5186]="结束我们的痛苦吧！"
D.Strings[5187]="你必须救他！"
D.Strings[5188]="哦，达隆郡！我会为你带来无限生机的！"
D.Strings[5189]="别让我们失望！"
D.Strings[5190]="圣光力量会胜利的！"
D.Strings[5191]="马杜克，小心！否则你的力量将逐渐消弱。"
D.Strings[5192]="我被霍古斯吞食了！我还能感觉到他的牙齿噬咬我！"
D.Strings[5193]="雷德帕斯队长！你怎么能抛弃我们！"
D.Strings[5194]="%s深深地吸了一口气……"
D.Strings[5195]="很高兴见到你，$c。除非你和我的女主人玛加萨之间有直接交易关系，否则别找我说话。$B$B我帮她处理大部分的事务，让她能集中精力处理更重要的事情。或许在你拜见她之前我们可以谈谈。"
D.Strings[5196]="你随时都可以跟我交谈，$n。你对玛加萨忠心耿耿。我想将来她会召见你的。"
D.Strings[5197]="别把自己当我的同辈来跟我讲话，$c。希尔瓦娜斯是我的女王，我听从她的命令。$B$B要是你不表现出适当的尊重，我敢说我们将为你在扭曲虚空选个更为合适的位置。$B$B但是要是你愿意帮助黑暗女王的话，我们便无话可说了……"
D.Strings[5198]="在我眼中，部落的所有成员都是平等的，$n。我们的血液被恶魔玛诺洛斯污染了，人民承受着重负，如果不是为了学识和荣耀的话，我们几乎就快沦为亡灵天灾了。$B$B协助部落，让我们获得新生，这是你的职责。但是你也得明白什么时候应该对朋友同情，对敌人怜悯。$B$B好好理解。这是新生的部落，而不是缺乏自由意愿的恶魔军队。"
D.Strings[5199]="我准备好听你的故事，提里奥。"
D.Strings[5200]="由于我的身份问题，我并未对你说实话，我必须为此向你道歉。我必须确定你是值得信赖的——很少有人能无私地为一个年老的隐士提供帮助。$B$B你已经证明了自己是个正直崇高的人。"
D.Strings[5201]="谢谢你，提里奥。你的身份是什么？"
D.Strings[5202]="当我以叛国罪被放逐离开联盟过着流放的生活时，我的儿子泰兰还是个小孩。我呆在这儿就是为了看着他长大，让他成为一个可敬的人。$B$B正如我期望的那样，他接替我的位置，成为玛登霍尔德之王，但是命运是如此残酷，他加入了血色十字军的队伍。现在他成了十字军的高级统领，$r。"
D.Strings[5203]="那可真糟糕。"
D.Strings[5204]="真的。血色十字军是银手骑士团做出的错误决策。$B$B你必须相信我，$r；泰兰是个好人。他需要指导。他必须记起……记起高贵和荣耀的含义。我知道那信念就在他心中，他知道他所做的是错误的。你帮助他好吗？帮助他记起来？"
D.Strings[5205]="我会的，提里奥。"
D.Strings[5206]="为什么像地精这样的小生物总是迷恋创造大的发明呢？"
D.Strings[5207]="啊！我的伤太严重了。卫士们，我不在你们要继续战斗！"
D.Strings[5208]="你要仔细听好了，别轻易相信或怀疑你所听到的一切。因为即使是朋友也可能将自己送上死路，$c。$B$B我们伟大的酋长深知这一点，为了证明部落中有一些术士并不想从内部毁掉部落，或是为了获得权力，我自愿尽我所能帮助年轻的首领。"
D.Strings[5209]="准备被揍吧。"
D.Strings[5210]="我会将你的内脏当作项链的。"
D.Strings[5211]="我可以感觉到你的恐惧，$r。"
D.Strings[5212]="要是你现在跑的话，你也许还有机会活下去。"
D.Strings[5213]="软弱的家伙，现在是算账的时候了！"
D.Strings[5214]="你不值得我花费力气。<纳萨诺斯吐了一口唾沫。>"
D.Strings[5215]="下一次带朋友一起来。"
D.Strings[5216]="我正让你堕落……"
D.Strings[5217]="武器训练师"
D.Strings[5218]="吴平的精力真令人惊奇。我看着他连续练习了数小时技巧。他用双手击打练习用的假人，直到他的拳头沾满鲜血。我想不到还有谁比他更适合训练你的战斗技能。"
D.Strings[5219]="吴平大师几乎懂得人类所知的所有武器的用法。在徒手搏斗中，他的觉醒之拳技能具有致命的攻击力。要是你需要训练的话，就去找他吧，他一般都在维勒武器店等待新武器的运送。"
D.Strings[5220]="通过千百次的锤炼，伊琳尼雅·月火已经掌握了若干种武器的使用方法，现在她为别人提供训练。如果你想接受训练的话，就去战士区找她吧。"
D.Strings[5221]="我的大部分武器技能都是跟战士区的伊琳尼雅·月火学的。要是你想学习如何使用新武器，就去找她吧。"
D.Strings[5222]="比克斯和布里维夫的武器沾满了兽人的鲜血。如果你想学习的话，就去密林武器店找他们吧。"
D.Strings[5223]="你想学习怎样使用一种新武器是吗？那么，你就应该与那边的密林武器店武器商店的比克斯和布里维夫谈谈，$g小伙子:姑娘;。他们对从斧头到……嗯……双手武器都非常了解。"
D.Strings[5224]="想学习如何使用新武器？去荣誉谷的传说中的装备店中找塞尤克和哈纳什吧。"
D.Strings[5225]="去荣誉谷的传说中的装备店中找塞尤克和哈纳什。注意你的言行，否则塞尤克也许会将你作为喂狗的美食。"
D.Strings[5226]="武器大师"
D.Strings[5227]="啊，你是在找安塞瓦。去雷霆崖武器店中部高地的底层找他吧。"
D.Strings[5228]="在武器使用方面，没有人能胜过安塞瓦了。据说他接受过我们尊敬的祖先，最伟大的战士的灵魂的指导。去中部高地的底层寻找他，他会教你的。"
D.Strings[5229]="你要找的阿基巴德在战争区内环的武器商店外。"
D.Strings[5230]="小亡灵阿基巴德知晓所有武器。你可以在军事区内环找到他。"
D.Strings[5231]="我得向你解释，我们的敌人能安然地潜伏在我们的眼皮底下。$B$B首先要记住这一点：我们的敌人是暗影议会。无论我给你什么任务，或许无论我让你与谁对抗，你都必须明了这个事实。$B$B议会拥有许多信徒，但是其行动信息绝对不会透露给愚蠢的信徒。$B$B像火刃、阿古斯的觉醒和燃刃都是议会的工具。他们是一伙的。"
D.Strings[5232]="好，好。看来我们要展开角逐了。去吧，孩子们！"
D.Strings[5233]="啊，是我们的人。很高兴看到我们的队伍增长如此迅速，以至于我都记不清每个人的容貌了。$B$B沃金那个傻子认为我正努力改善术士的形象并为他服务呢。白痴！燃烧军团在耗尽这世界的资源后会将它化为灰烬的。"
D.Strings[5234]="天真的傻子。火刃就是暗影议会！议会拥有许多信徒和组织，但是他们都服从于议会的意愿。我或许能领导火刃，但是我无非是议会手下的一名爪牙，就像你是我的爪牙一样！$B$B看看燃刃吧——他们中的大多数人认为自己会成为下一批极具潜力的术士，并成功替代暗影议会。"
D.Strings[5235]="哈哈！除了他们的领导人——萨特, 巴扎兰, 还有术士耶戈什——是的，他们所有人。这就是我不断的派沃金的信徒到他们那儿去的原因。这样会让沃金觉得我正在铲除他伟大城市中邪恶的人。事实上胜利是双重的：杀掉萨尔的信徒并测试一下那些燃刃的力量，看看他们是否真的有资格加入我的队伍。"
D.Strings[5236]="我会让你知道这一点的。很明显，你如此迅速地成为中尉，已经证明了自己的实力。或许稍后你回到我这儿时，我会派给你任务的。委员会崇尚那些能熟练运用魔法的人，但也欢迎各种族的仆从，无论该仆从从事何种职业。"
D.Strings[5237]="你就明说吧……"
D.Strings[5238]="很高兴看到火刃接管了那些暗影议会无力接管的地方。"
D.Strings[5239]="这么说，燃刃可以牺牲了？"
D.Strings[5240]="要是你能从我这儿拿走什么的话……"
D.Strings[5241]="我被腐化了。"
D.Strings[5242]="我得救了。"
D.Strings[5243]="有人吗？提里奥我的老朋友，是你吗？你来救我们吗？"
D.Strings[5244]="他们都……死了？"
D.Strings[5245]="萨克霍夫……有时萨克霍夫他们会来。他们是好人。"
D.Strings[5246]="作为探险者协会的一员，我曾在这片区域搜寻古代器物。据说冬泉谷有许多不可思议的物品……很多物品都受到严密的保护。"
D.Strings[5247]="%s搜寻着灵魂，想要饱餐一顿！"
D.Strings[5248]="熔炉中的溶液已经可以使用了。接下来无非是处理未完成的钥匙和圣甲虫的问题。"
D.Strings[5249]="完成了$n，我想你会对结果感到满意的。"
D.Strings[5250]="巴琳达·斯通赫尔斯马上就会到位，新的战斗马上就要开始了！"
D.Strings[5251]="援军补充入了冰血要塞！加尔范上尉马上就到，新的战斗马上开始！"
D.Strings[5252]="这是奥特兰克山谷战场。双方还在交战。"
D.Strings[5253]="这是奥特兰克山谷战场。目前双方势均力敌。"
D.Strings[5254]="让我们展开新的战役，这次要击败联盟！"
D.Strings[5255]="我们的军队已准备就绪，士气高涨。巴琳达·斯通赫尔斯将很快进入前哨，战争即将开始！"
D.Strings[5256]="我们的将军范达尔·雷矛在战斗中倒下了！战斗失败了！$B$B和我们的军需官谈谈，然后帮助重建我们的部队。"
D.Strings[5257]="部落的将军被打败啦！$B$B联盟胜利啦，部落乱作一团，正忙着重建他们残弱的部队。"
D.Strings[5258]="双方的将军均未重生。"
D.Strings[5259]="德雷克塔尔被击败了！联盟胜利了……至少现在是胜利了。$B$B和我们的军需官谈谈兵帮助我们的重建。"
D.Strings[5260]="我在这儿！过来和我作战，你们这些联盟的懦夫！"
D.Strings[5261]="范达尔在这儿！来吧！给我看看你有什么能耐！"
D.Strings[5262]="部落的将军死了！"
D.Strings[5263]="联盟的将军死了！"
D.Strings[5264]="嗨，小心那头科多兽！你最好在我寄予你信任之前看好这头野兽！"
D.Strings[5265]="那只科多兽真美。等等，我的眼镜在哪儿？也许你该帮我照看这头野兽。"
D.Strings[5266]="啊……科多兽令人惊奇的声音。我喜欢它们震动地表的方式……帮我照看这些野兽。"
D.Strings[5267]="地精是如何把包裹放到这些野兽身上的，他们是怎么做到的？科多兽比他们大十倍！"
D.Strings[5268]="现在是危险时期，冒险者。多加小心。"
D.Strings[5269]="我准备好接受幻象了，麦兰达。"
D.Strings[5270]="你好！是什么吸引你来到冬泉谷？这片寒冷广袤的土地或许显得有些凄凉，但是它蕴含着无数的秘密……"
D.Strings[5271]="真让人感到悲痛……但是覆水难收……"
D.Strings[5272]="我不会忘记你所做的……$B$B请离开我……"
D.Strings[5273]="嗨，你说自己是一名保镖？那么保护我们吧……"
D.Strings[5274]="保镖先生，你是要赚钱还是干嘛？"
D.Strings[5275]="你被炒鱿鱼了！ <咳嗽...考克清了清嗓子。> 我是说，快帮忙！"
D.Strings[5276]="我将带我们穿越壁炉谷到达森林的边缘。然后你就可以把我带到我父亲那儿了。"
D.Strings[5277]="脱下你的伪装吧，以免我控制不住，挥刀伤到你。"
D.Strings[5278]="停下。"
D.Strings[5279]="%s召唤他的坐骑。"
D.Strings[5280]="%s嘶叫起来。"
D.Strings[5281]="不！！！"
D.Strings[5282]="大领主有些不对劲。采取行动！"
D.Strings[5283]="嗨，那儿发生什么事了？先生，你还好吧？先生？？"
D.Strings[5284]="大领主弗丁，你还好吧？"
D.Strings[5285]="是普罗德摩尔将军！离开这儿！"
D.Strings[5286]="我来啦，联盟！如果你行的话……放马过来吧！"
D.Strings[5287]=S[854]
D.Strings[5288]="跟灰谷梅伊瑟娜岗哨的哨兵奥奈雅谈谈，她将为你今天的勇敢行为给予相应的回报。"
D.Strings[5289]="还不够远。大道还在前面呢。"
D.Strings[5290]="呃！恶魔对科多兽垂涎欲滴！"
D.Strings[5291]="我付钱给你是为了什么？科多兽就快死了！"
D.Strings[5292]="要是我再高五英尺，我就会给这些亵渎神明的恶魔一点颜色看看！快帮帮我！"
D.Strings[5293]="啊哈！我们成功了……不明白为什么我们会认为需要像你这样的人。不管怎样，去跟斯米德·瑟卡布斯库谈谈吧；他会给你报酬的！"
D.Strings[5294]="杀死那些愚蠢的半人马！唉——嗯，似乎你信守承诺。沿着这条路走，去找斯米德·瑟卡布斯库，他会付钱给你的。"
D.Strings[5295]="你让我失望了，泰兰。原本我设计了一个规划……一个重要的计划。啊，你肮脏的血统最终表露出来只是个时间问题。"
D.Strings[5296]="就像他们说的：有其父必有其子。你就跟提里奥一样软弱……或许比他更软弱。我只希望我派出的刺客能顺利结束他令人同情的一生。"
D.Strings[5297]="测试——重启战场。"
D.Strings[5298]="离开这里!"
D.Strings[5299]="别让他们抓住你！"
D.Strings[5300]="如果我们被抓住的话，她会取我们的性命的！"
D.Strings[5301]="达隆郡，别放弃希望！我们不会失败的！"
D.Strings[5302]="戴维，圣光照亮你的内心。我要把它挖出来！"
D.Strings[5303]="戴维，你的死期到了！"
D.Strings[5304]="霍古斯，你的噩梦结束了！现在！"
D.Strings[5305]="为了达隆郡！"
D.Strings[5306]="我们的队长会救我们的！"
D.Strings[5307]="战斗！为了你的家人而战！"
D.Strings[5308]="亡灵天灾不会得逞的！"
D.Strings[5309]="不要放弃！为达隆郡而战！"
D.Strings[5310]="战斗，我们今天一定会赢！"
D.Strings[5311]="战斗直到最后一息，兄弟姐妹们！"
D.Strings[5312]="回到你的巫妖王那里去，肮脏的东西！"
D.Strings[5313]="达隆郡的守护者们！集合起来！我们必须战胜他们！"
D.Strings[5314]="达隆郡！这是命中注定的！"
D.Strings[5315]="达隆郡被击败了！很快，整个洛丹伦就会陷落！"
D.Strings[5316]="达隆郡的勇士们，拿起武器吧！亡灵天灾就要来了！"
D.Strings[5317]="大十字军命令我毁掉了你和你新交的朋友泰兰，但是你要知道：我做这事儿纯属个人兴趣，跟职责和义务无关。"
D.Strings[5318]="%s呼叫他的卫兵。"
D.Strings[5319]="弗丁，该结束了。"
D.Strings[5320]="坐下来听听我的故事吧，$r。"
D.Strings[5321]="已经过了太久了。我们必须晚些再试。"
D.Strings[5322]="好了，我们继续前进！"
D.Strings[5323]="记住，我需要你的帮助来正确进行吟唱。我在我们前进的路上会请你帮好几次忙，所以请准备好。"
D.Strings[5324]="达维·莱法尔死了！达隆郡沦陷了！"
D.Strings[5325]="达维·莱法尔死于重伤！"
D.Strings[5326]="霍古斯被杀了！振作起来，达隆郡的守卫们！"
D.Strings[5327]="雷德帕斯队长被杀了！"
D.Strings[5328]="伊森利恩！"
D.Strings[5329]="这场战斗跟你没有关系，$c。保护好你自己，当心别被红衣精英干掉。我会去挑战大检察官的。"
D.Strings[5330]="你做了什么，伊森利恩？你从前为名誉而战，为了人民的幸福而战……而现在……你杀死了我的孩子……"
D.Strings[5331]="伊森利恩，你的灵魂将痛苦地燃烧着！圣光会赋予我力量对抗这个恶魔的。"
D.Strings[5332]="看着我，胆小鬼。面对你从前也曾拥有的信念和力量。"
D.Strings[5333]="这蓝色的亮光……真奇怪。你认为它意味着什么？"
D.Strings[5334]="$g嗨，帅哥，你想去格罗姆高吗？我听说那里的丛林整日雾气腾腾的，也许我们可以一起度个短假，我让你看看真正的丛林虎怎么样？:来吧，参观一下奇妙绚丽的荆棘谷丛林。你可以在水晶般的蓝色海岸线上惬意地洗日光浴，而我却站在这难以忍受的高温下整天傻看着我的兄弟弗雷萨！尽情享受你的旅程吧！;"
D.Strings[5335]="将一枚硬币塞到首领手中，看看你会得到什么。我喜欢自己的工作。但是，如果我能设法让斯纳尔克重新分配给这个飞行点的话……那样就好了。但是我敢打赌，你到这儿来不是要帮我进行职业训练的，而是寻找地精飞艇前往幽暗城，对吧？那很好，因为它会停泊在我后面。如果你看见斯纳尔克，代我向他问好，行吗？"
D.Strings[5336]="请在我吟唱的时候点亮这个。"
D.Strings[5337]="就是这个地方。让我们点亮它。"
D.Strings[5338]="我们找到它了！"
D.Strings[5339]="够了！"
D.Strings[5340]="你真的认为自己能打败我吗？你的朋友很快就会随你去的，泰兰。"
D.Strings[5341]="%s注意到你了。"
D.Strings[5342]="现在该进行最后一步了，我们必须激活祭坛。"
D.Strings[5343]="我会阅读刻在石头上的字，而你必须想办法点亮它。"
D.Strings[5344]="它……它起作用了！"
D.Strings[5345]="发生什么了？看！"
D.Strings[5346]="已经很多年了……"
D.Strings[5347]="谁在女神的祭坛捣乱？"
D.Strings[5348]="女祭司,请原谅我们的闯入。我们不想造成任何伤害。"
D.Strings[5349]="我们只是希望知道枭兽为什么要守卫这片地区……"
D.Strings[5350]="Enu thora'serador。这是一片神圣之地。"
D.Strings[5351]="我们会给你看……"
D.Strings[5352]="你不会到达森林边缘的，弗丁。"
D.Strings[5353]="恶梦终于结束了！达隆郡，原谅我吧！"
D.Strings[5354]="帕米拉？亲爱的，你在那儿吗？"
D.Strings[5355]="爸爸！"
D.Strings[5356]="爸爸！你回来了！"
D.Strings[5357]="我们去玩吧！不，给我讲个故事，爸爸！不……我们去摘花！然后喝茶！我找到我的玩具娃娃了，我告诉过你吗？"
D.Strings[5358]="我真想你，爸爸！"
D.Strings[5359]="我也想你，亲爱的。我终于回家了……"
D.Strings[5360]="月爪枭兽逝去的灵魂专注地盯着你，就像等待发生什么事情一样。"
D.Strings[5361]="你战斗得很勇敢，精灵。我请你赐予我你身体和心灵的力量。"
D.Strings[5362]="灵魂专注地盯着你的眼睛，握紧你的双手。你感到一股热流抨击着身体，几乎无法站立。$B$B热流过后，你感觉身体中似乎充斥着熊的灵魂……让你更加坚定。"
D.Strings[5363]="亡灵天灾被打败了！达隆郡得救了！"
D.Strings[5364]="我们都亲眼目睹了无数可怕的灾难，但是我们不能由此绝望。$B$B记住这些往事，总有一天，我们会进行报复的。"
D.Strings[5365]="我还需要一个遗物包裹!"
D.Strings[5366]="我们再找下一个。"
D.Strings[5367]="我们必须继续前进。"
D.Strings[5368]="祭坛在发光！我们做到了！"
D.Strings[5369]="朝上看，Thara dormil dorah……"
D.Strings[5370]="这宝石曾允许与月神本人进行直接沟通。"
D.Strings[5371]="月神通过宝石传达着她无尽的智慧……"
D.Strings[5372]="宝石需要得到保护，于是我们就向女神求助。"
D.Strings[5373]="很快，我们眼前浮现出一种生物的幻象……它有猫头鹰的羽毛，同时也有熊的意志和力量……"
D.Strings[5374]="就在那天我们得到了枭兽。凶猛的守卫，女神派枭兽保护她所有的神圣之地。"
D.Strings[5375]="一千个像他一样的人存在着。一万个。如果一个倒下了，另一个会起来争夺权力的宝座。"
D.Strings[5376]="但是现在，枭兽已经变得更加凶猛，而且由于失去了女神的指引，它们很迷茫……"
D.Strings[5377]="看看他们对我的孩子做了什么!"
D.Strings[5378]="它们毫无目的地游荡……但是很多枭兽又回到了它们曾经发誓要保护的神圣之地。"
D.Strings[5379]="%s搂着泰兰·弗丁毫无生气的身体低声抽泣。"
D.Strings[5380]="你不会白死的，泰兰。今天产生了一种新秩序……一种致力于消灭正在折磨这个世界的邪恶势力的秩序。这种邪恶势力是不能被政治和幽默所掩盖的。"
D.Strings[5381]="枭兽天生具有魔力；这种力量是由女神赐予他们的。"
D.Strings[5382]="你要知道，无论身处何地，他们都会受他人委托，保护着某种重要的东西。"
D.Strings[5383]="我虚度了太多时光，在混沌……痛苦中度过，为或许发生过……或者应该发生而没有发生的事情感到悲伤。"
D.Strings[5384]="我承诺……我发誓……"
D.Strings[5385]="记住我们向你展示的……"
D.Strings[5386]="真悲哀。弗丁还活着……你来晚了，年老的隐士。回到你的洞穴吧，除非你想和在扭曲虚空的儿子一起。"
D.Strings[5387]="谢谢你的帮助，$n。祝你探险顺利。"
D.Strings[5388]="我想呆在这儿，思考一下所见的事情。找到艾瑞拉斯并告诉他我们学到的东西。"
D.Strings[5389]="来吧，隐士！"
D.Strings[5390]="熊平静地注视着你，但是没说一句话。"
D.Strings[5391]="熊的灵魂平和的凝视着你。你听到了一个声音在对你讲话，好象是从熊那里传来，但是没有迹象表明这个动物在说话。$B$B“你好，我年轻的朋友。如果你是来找我寻求指引的，那么或许我能帮你找到你想要的东西。”"
D.Strings[5392]="你代表什么，灵魂？"
D.Strings[5393]="我代表着使你成为一名年轻的德鲁伊的力量，是躯体和心灵的力量。你已经在训练中知晓了这一点，当你变身为熊的时候便可利用这力量了。$B$B年轻人，继续保持平衡，眼光清晰而有条理。当你需要我的时候……我会在那儿等你的。"
D.Strings[5394]="我代表着使你成为一名年轻的德鲁伊的力量。年轻人，你得向我学习这力量，我也乐于传授给你。要是你愿意听从并理解的话，我将教你如何使用熊的灵魂。$B$B为了明白利用我的灵魂的含义，你需要了解躯体和心灵的力量的重要性。"
D.Strings[5395]="我想了解躯体力量的重要性。"
D.Strings[5396]="身体的力量能使动作充满力度，行动迅速。你必须在身体上和精神上一直保持就绪状态。熊的体型造就了它的力量，使它成为危险的对手。但是，熊的体型也限制了其身体的敏捷性和头脑的灵活性。你可以好好利用这点。$B$B你必须依赖熊的力量掌握利爪的使用方法。"
D.Strings[5397]="我想了解心灵力量的重要性。"
D.Strings[5398]="心灵的力量将给你采取行动的决心……基于明确的、直接的目的行动。保持平衡并不意味着自命不凡或是平庸陈腐。$B$B你必须表现出对信仰的决心，你必须愿意为此奋斗。母熊对幼仔有极强的保护意识，年老的熊也这样保护着它的洞穴。这就是决心，心灵的力量，如果你想要掌握利爪的使用方法，你就必须知道这一点。"
D.Strings[5399]="年轻人，还要看你是否准备就绪。当最终考验来临时，即使最聪明最年老的德鲁伊也无法真正地做好准备。$B$B你已经听到我的话了，你必须继续前进。记得我的嘱咐。某个时候你的能力将经受考验。你必须像熊那样勇敢面对自己的敌人——用身体和心灵的力量。年轻人，你得从战争中学习成长。去吧……带上我的祝福。"
D.Strings[5400]="你好，$c。欢迎你来到永夜港，还有整个月光林地。塞纳里奥议会欢迎所有尊敬大自然的权威和支配力的生灵。$B$B当你在这里的时候，请一定要保持所有事物的平衡。这里不喜欢受到打扰，而我们的看守所受的训练就是无条件地停止所有的敌对行为。"
D.Strings[5401]="你需要幻象吗？$B$B要是在执行任务的过程中幻象失效，回到我这儿来，我将重新对你进行伪装。$B$B如果你尽力而为还是失败了，别放弃！回到我这儿来。我将助你完成目标。"
D.Strings[5402]="努力保持所有事情的平衡性，$c。真正的和谐便在于此。"
D.Strings[5403]="欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B重申自己在这伟大的平衡中的地位总是无伤大雅的。作为这种平衡的守护者，我们必须努力保持清醒的头脑和坚定的信念。训练能使我们做到这一点。"
D.Strings[5404]="我想接受德鲁伊技能方面的训练。"
D.Strings[5405]="战争结束了，达隆郡的人民得救了。"
D.Strings[5406]="战争结束了，达隆郡的人民得救了。$B$B他们得救了，$n，这都归功于你。你是达隆郡的英雄。"
D.Strings[5407]="我的眼睛被黑暗所蒙蔽，但是你把我从邪恶的幻想中拯救出来。你救了我，$n。$B$B现在我求你……原谅我。"
D.Strings[5408]="塞纳留斯保佑你，$c。"
D.Strings[5409]="欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。"
D.Strings[5410]="即使在冰冷的石头墙内，就像庇护这座城镇的墙一样，人们仍旧可以找到宁静与和平。事实上，你可以在你所在的任何地方找到他们……只需在你体内寻找这种平衡。"
D.Strings[5411]="你只是在拖延时间，结果是不可避免的。投降吧。她会释放你误入歧途的灵魂的。"
D.Strings[5412]="我们的工作就是保持平衡，如同塞纳留斯所教给我们的一样，$c。他就是指引我们前进的明灯，而我们必须竭尽所能保护它的光芒。"
D.Strings[5413]="欢迎你，我的$g兄弟:姐妹;。如果你是来接受训练的，那我很高兴能训练你。$B$B如塞纳留斯教导我们的一样，我们一直都是平衡的保护者。永远不要忘记这点。"
D.Strings[5414]="再次感谢你，$n！我对我们所发现的东西感到很高兴。$B$B祝你好运！"
D.Strings[5415]="我准备出发了，$n。我需要一些帮助——你愿意跟我来吗？"
D.Strings[5416]="%s开始吟唱一个奇怪的法术……"
D.Strings[5417]="你准备好了吗，孩子？"
D.Strings[5418]="%s充满期待地叫了起来。"
D.Strings[5419]="快去！！"
D.Strings[5420]="雷德帕斯！纳命来！"
D.Strings[5421]="我无法训练你。"
D.Strings[5422]="干得好！现在把它放在上面。"
D.Strings[5423]="我在寻找愿意保护基泽尔顿车队的卫兵。我们被挡在了考米克小屋东面的路上，就在科尔卡半人马村的北边。"
D.Strings[5424]="里格·基泽尔顿寻求帮助，护送我的商队穿过玛诺洛克集会所。我在葬影村东面的路上。"
D.Strings[5425]="我不能训练你。"
D.Strings[5426]="你好，年轻的潜行者。你在找什么？"
D.Strings[5427]="我不能训练你。你必须去找你的职业训练师。"
D.Strings[5428]="我帮不了你，$n。我只训练潜行者。"
D.Strings[5429]="对不起，但是我只训练盗贼。"
D.Strings[5430]="啊……一名顾客！看看我最伟大的发明，贸易机器人1000型！它拥有你所需的一切商品……其中的一些稀有物品更是在卡利姆多的其它任何市场上都找不到……更不用说它的设计不支持任何讨价还价的废话了，因此你看到的价格就是你要支付的价格。"
D.Strings[5431]="毫无疑问，你是黑暗女王派来接受训练的又一个无能的白痴。$B$B<纳萨诺斯叹息着。>$B$B我每次都得把你们的尸体运回去给她，我想这次也不会有什么例外。$B$B但是，我并不会问什么，我只按照黑暗女王的吩咐办事。"
D.Strings[5432]="让我看看你提供的东西。"
D.Strings[5433]="今天碰巧是你的幸运日；我完成了超级商人680型的维护工作，因此有大量物品以超低的价格出售。你自己去看看吧……我的兄弟考克认为他的贸易机器人1000型会胜过我的。"
D.Strings[5434]="我可以为你效劳吗，$n？"
D.Strings[5435]="我想接受潜行者的训练。"
D.Strings[5436]="你能训练我使用潜行者技能吗？"
D.Strings[5437]="你是来学习的吗？"
D.Strings[5438]="当然，我有。教给我吧。"
D.Strings[5439]="你看我像是个$c吗？在我决定用你的血洗我的刀之前，赶紧逃吧。"
D.Strings[5440]="你好，朋友。愿黎明在这个乱世之中保佑你平安无恙。"
D.Strings[5441]="现在还不行，$g小伙子:姑娘;……我是不会把强大的战羊随意卖给其他人的，你必须首先证明自己是铁炉堡矮人的忠实盟友才行。一旦我确认你在铁炉堡的声望达到友善的程度，那我会很乐意让你看看我出售的多种战羊的。"
D.Strings[5442]="我的规划是不允许减少任何项目的成本的。"
D.Strings[5443]="我很好奇这样一台机器能为我提供什么。"
D.Strings[5444]="在驾驭过一头受过良好训练的山羊之前，就别夸口说你已经拥有了真正的坐骑，我的朋友。请随意看看这些杰出的坐骑吧。它们会让你满意的，相信我。"
D.Strings[5445]="我是自动售货商的最新形态……我们总有一天会统治这个世界的……别告诉老板我从他的商品中榨取钱财……"
D.Strings[5446]="很抱歉。我们不得不动身前往别处，继续行骗。我们会回来的。再见！"
D.Strings[5447]="基泽尔顿车队出发的时间到了！我们很快就会回来的，但是如果你等不及的话，朝北方走，到考米克小屋去。我们会在一小时后开张的。"
D.Strings[5448]="很抱歉，如果你没有在暴风城达到友善的声望，我是不会将马匹卖给你的。这些战马是最好的，我们当然不会当它们落入敌人之手。$B$B想要证明自己不是敌人的话，你只需赢得暴风城的信任，这样我就可以跟你做买卖了。"
D.Strings[5449]="多年的精心饲养和细致的品种培育使我能够有机会向你展示这些良种马。请慢慢挑选，马是你长期的伙伴，朋友。不要把自己低估了——今天就在这里找到你想要的马！"
D.Strings[5450]="你并不为我的同胞所知。科多兽是强大的坐骑，它是我们的爱心和关怀的产物；所以我不能把它卖给陌生的冒险者。在你同雷霆崖的声望达到友善之前，我不能卖给你科多兽。"
D.Strings[5451]="在狩猎之前最好问问你要找什么猎物。"
D.Strings[5452]="看看这些科多兽，我的朋友！它们幼年时便开始接受训练，在莫高雷的金色平原长大，这些家伙就是我们出色的坐骑！看看它们吧，看看我们牛头人为什么会依赖于这些强大的生物！"
D.Strings[5453]="欢迎来到塞纳里奥议会，$c。"
D.Strings[5454]="让我传授你猎人的技艺吧。"
D.Strings[5455]="我需要培训。"
D.Strings[5456]="我有许多知识可以让你大开眼界，$c。你必须学会带着荣耀去狩猎。"
D.Strings[5457]="我是来接受培训的。"
D.Strings[5458]="我用祖先传下来的方法训练猎人。"
D.Strings[5459]="牛头人热衷于狩猎，这是流淌在我们血液中的灵魂。"
D.Strings[5460]="我是一名猎人，我想接受训练。"
D.Strings[5461]="皇家药剂师协会对愚蠢的家伙没有耐心，我也一样。或许下次我们谈到战马的时候，你与幽暗城的关系已经到了友善的地步。否则的话……"
D.Strings[5462]="很高兴我能代表皇家药剂师协会为你提供最好的战马。这些战马与我们一样经历过考验和磨难，现在它们已经远胜于那些血肉之躯所铸成的战马了，它们更为强壮，更易恢复精力！好好看看它们吧。"
D.Strings[5463]="来学习猎人之道吧。骄傲，荣誉，还有传统。"
D.Strings[5464]="我可以教你骑山羊的技巧，只要你有足够的金币支付学费！"
D.Strings[5465]="我按照传统一代代地训练、指导年轻猎人。"
D.Strings[5466]="我可以教你操纵机械陆行鸟的技巧，只要你有足够的金币支付学费！"
D.Strings[5467]="我可以教你骑马的技巧，只要你有足够的金币支付学费！"
D.Strings[5468]="我可以教你骑豹的技巧，只要你有足够的金币支付学费！"
D.Strings[5469]="我可以教你骑科多兽的技巧，只要你有足够的金币支付学费！"
D.Strings[5470]="我可以教你骑迅猛龙的技巧，只要你有足够的金币支付学费！"
D.Strings[5471]="我可以教你骑骸骨战马的技巧，只要你有足够的金币支付学费！"
D.Strings[5472]="我可以教你骑狼的技巧，只要你有足够的金币支付学费！"
D.Strings[5473]="在我教你骑术之前，你必须与铁炉堡的矮人达到友善关系，$c。"
D.Strings[5474]="在我教你骑术之前，你必须与奥格瑞玛的兽人达到友善关系，$c。"
D.Strings[5475]="在我教你骑术之前，你必须与暗矛部族的巨魔达到友善关系，$c。"
D.Strings[5476]="谢谢你，$n。现在让我们离开这儿！"
D.Strings[5477]="在我教你骑术之前，你必须与雷霆崖的牛头人达到友善关系，$c。"
D.Strings[5478]="在我教你骑术之前，你必须与暴风城的人类达到友善关系，$c。"
D.Strings[5479]="在我教你骑术之前，你必须与达纳苏斯的暗夜精灵达到友善关系，$c。"
D.Strings[5480]="我们成功了！再次感谢你！我先走了！"
D.Strings[5481]="在我教你如何驾驭机械陆行鸟之前，你必须与诺莫瑞根的侏儒们达到友善关系，$c。"
D.Strings[5482]="在我教你骑术之前，你必须与幽暗城的被遗忘者达到友善关系，$c。"
D.Strings[5483]="要教你学会驾驶机械陆行鸟，那简直就是在浪费我的金钱和时间，$c。你的体形太庞大了！"
D.Strings[5484]="我想接受骑术训练。"
D.Strings[5485]="请训练我吧。"
D.Strings[5486]="嗨，霍恩尼兹！我回来了！有些好心人帮我脱离了困境。"
D.Strings[5487]="我们不得不把玛洛迪半人马从我们的合作伙伴列表中划掉。他们太难共事了……"
D.Strings[5488]="好吧，我要到吉尔吉斯村去了。他们不像玛洛迪半人马一样蠢，而且他们更加通情达理。"
D.Strings[5489]="再见！祝你下次好运！"
D.Strings[5490]="那个女孩总是忙个不停。"
D.Strings[5491]="记住，所有的事物都是有关联的。如果陆地上的野兽灭绝，我们的种族将在孤独中死去，因为牛头人和野兽的命运是相通的，而艾泽拉斯的命运和所有艾泽拉斯上的生灵的命运也休戚相关。"
D.Strings[5492]="如果你是来接受狩猎技巧训练的，那你就来对地方了！"
D.Strings[5493]="嗨！?从来没有过深海潜水的经历吗？我告诉你一个小秘诀，嗯。在海洋深处有许多冒气泡的裂缝，当你在水下时可利用这些气泡进行呼吸。这个秘密只限于你我之间。对我来说，贝壳到处都是……如果你懂我的意思的话！"
D.Strings[5494]="不……不可能！等一下……我投降！我投降！"
D.Strings[5495]="老鹰翅膀的扇动，雪地里山羊的喘息，熊穿过森林的脚步……这就是猎人的生活。"
D.Strings[5496]="守护符文被摧毁了！兄弟们，杀掉这些入侵者！"
D.Strings[5497]="你们要不顾一切地揭开烈焰之子的秘密，你们会为这鲁莽的行为付出巨大的代价！"
D.Strings[5498]="我将会召唤这里真正的主人，让你们直接面对他无尽的愤怒，你们渺小的生命即将完结！不过，你们得自己进入他的房间！"
D.Strings[5499]="[PH]好吧，我离开这儿……到拉格纳罗斯的巢穴见……18"
D.Strings[5500]="%s分裂成两只熔岩爪牙！"
D.Strings[5501]="我刚结束流浪生活。"
D.Strings[5502]="你不是德鲁伊！"
D.Strings[5503]="我想飞往鲁瑟兰村。"
D.Strings[5504]="你想乘坐塞纳里奥议会的免费航线飞回鲁瑟兰村吗？"
D.Strings[5505]="要是你想要飞回雷霆崖，就该跟我的牛头人搭档布瑟恩·草风谈谈。"
D.Strings[5506]="你需要乘坐塞纳里奥议会的免费航线飞往雷霆崖吗？"
D.Strings[5507]="如果你想飞回鲁瑟兰村，就该找暗夜精灵希尔瓦·菲纳雯斯谈谈。"
D.Strings[5508]="这是你最后一次干扰我们的计划了，愚蠢的$c！"
D.Strings[5509]="%s开始倒数计时。"
D.Strings[5510]="%s削弱了鬼魂区域的力量。"
D.Strings[5511]="%s变得愤怒起来！"
D.Strings[5512]="我们所处的这个时期就像风云般变化无常，$c。大地正在痛苦中战栗，哀嚎。我们必须坚定地站稳脚跟，才能避免被这股混乱的漩涡吞噬。"
D.Strings[5513]="%s被鬼魂磁铁吸过去了……"
D.Strings[5514]="艾泽拉斯中没有哪一个种族经历过我们的人民所受的磨难，$c。面对死亡仍安之若素已经成为我们的第二天性了。"
D.Strings[5515]="准备好。今天，我们将以我们伟大的大地之母的名义，教导这些野猪人学会懊悔、悲哀和恐惧。"
D.Strings[5516]="啊，幽影谷的美景永远使我感到快乐！"
D.Strings[5517]="你看见一个穴居人，也就相当于看见了所有穴居人。"
D.Strings[5518]="你好！你看起来挺强壮的。我们这里的卫兵数量不太够，你愿意帮忙吗……"
D.Strings[5519]="艾萨拉地区。"
D.Strings[5520]="我对暗夜精灵的了解有限，但是据说很早以前——当暗夜精灵还掌握着神秘法术时——艾萨拉便是其中的佼佼者，她年轻美貌，是暗夜精灵的女王。不幸地是，正是她对魔法的痴迷才导致历史上最具破坏性事件的发生。"
D.Strings[5521]="埃达拉斯废墟。"
D.Strings[5522]="北方的魔法塔。"
D.Strings[5523]="刺客！来人啊！来人啊！"
D.Strings[5524]="我感到前方有危险。"
D.Strings[5525]="我的背部痛死了。"
D.Strings[5526]="这些命令必须传达到大将军阿比迪斯那里！"
D.Strings[5527]="要是我遇难的话，拿着我的背包。一定要将它送到大将军手上。"
D.Strings[5528]="木喉熊怪"
D.Strings[5529]="蓝龙现身"
D.Strings[5530]="你帮助了我，我会告诉我所知的这片土地和生物的情况。我所了解的并不多，但是我可以告诉你一些你可能感兴趣的事儿。"
D.Strings[5531]="上层暗夜精灵曾经统治这座城池，他们在此演练威力强大的奥术。现在他们受到诅咒，灵魂在这片土地上游荡，恶鞭军官纳迦侵占了精灵的城市。纳迦一定在废墟中搜寻那些上层精灵的神器。"
D.Strings[5532]="一个强大的人类魔法师传闻就在北部生活；他为了某种不为人知的原因一直在看守着那片大地。我自己没有亲自去过，但是据说访问者在那里很受欢迎，如果他们愿意为他办些差事的话甚至可以赢得他的好感。"
D.Strings[5533]="过去数年来，我目睹了熊怪所经历的种种可怕的事情——它们成为战场上的无辜受害者。但是我不清楚这个部落现在怎么样了。它们被席卷费伍德森林的天灾腐化了吗？或许它们对自己曾经和平的民族所遭遇的一切表示愤怒，正试图自我保护？无论如何，它们中的大多数对进入这片领域的人都会表现出敌意。"
D.Strings[5534]="蓝龙玛里苟斯不在那儿，但是他的信徒在。我不清楚这是怎么回事，但是我可以告诉你：蓝龙所在的地方都有希望找到神秘的魔法。如果说龙人在这儿保护某种东西的话，我是不会感到惊讶的……或许是上层精灵遗漏的物品。"
D.Strings[5535]="我应该寻求某些帮助；我不喜欢整天坐在这儿卖鱼。我更愿意去钓鱼，然后再卖掉。"
D.Strings[5536]="让我们看看你的钓鱼装备。"
D.Strings[5537]="你好, $c。我今天情绪很差，所以除非你能帮我，否则我更愿意自己呆着。"
D.Strings[5538]="干得好，$n！跟我谈谈以完成对你的考验。来吧，时间可不等人！"
D.Strings[5539]="可笑的凡人！在烈焰之子面前灰飞烟灭吧！"
D.Strings[5540]="我不能训练你，$c。"
D.Strings[5541]="我是奥塞斯·拉克摩尔，豪侠轮船的船长。这是最近几天轮船的航行日志。$B$B我们的船只满载货物驶向羽月要塞，纳迦袭击了船只一侧。我们赶走了他们，但是我们知道他们会回来的。我担心纳迦会毁掉我最宝贵的财物，因此我将豪侠驶向远离凄凉之地的一座小岛，岛上全是古老的暗夜精灵建筑废墟。我将自己的宝箱放在了岛上。"
D.Strings[5542]="我的箱子设计独特，需要两把钥匙来开锁，一把金钥匙和一把银钥匙。我将银钥匙给了我的大副，自己保留了金钥匙。$B$B但是我们注定会失去它们。在一次纳迦发动的袭击中，我丢了钥匙；而后，龙虾人攻击了我们，将大副推入了深渊。$B$B我想钥匙一定在纳迦和龙虾人那儿。还好这两方是敌人，不会共享钥匙的。"
D.Strings[5543]="在龙虾人的进攻后，我们知道下一次豪侠是无法幸免于难的。于是我和几个幸存的水手弃船逃生。$B$B我们现在上岸了并很快就会向尼耶尔前哨站游去，但是在到达避难所之前我们还有很多危险，而且我害怕凄凉之地会吞噬我们。$B$B我现在写下这些是希望有人能知道我们的困境，有一天能把那些带给我们灭顶之灾的水中魔鬼杀死为我们报仇。"
D.Strings[5544]="对我们这些在月光林地塞纳里奥议会的人来说，雷姆洛斯神殿是个神圣的地方……所以请你的表现符合访客的身份。$B$B我想你不愿让我用弯刀杀死你，那就是了。"
D.Strings[5545]="愿塞纳留斯庇护你，我的$g兄弟:姐妹;。$B$B我是塔加里，神殿的保卫者。能够作为这片神圣大地的看守来服侍守护者雷姆洛斯是我的荣耀。"
D.Strings[5546]="在亡灵天灾来临之前，我是一名大商贩。我出售所有商品。所有！$B$B价钱都极其便宜！$B$B你随便问问那些没死的人，看看我说的是不是真的。"
D.Strings[5547]="嗨$n！你是来购物的，还是来出售物品的？$B$B如果有比这儿更便宜的物品，我就不叫被感动的奥古斯图斯！"
D.Strings[5548]="商业！我需要它！"
D.Strings[5549]="是的，奥古斯图斯。我想做生意。"
D.Strings[5550]="这是个危险的地方，$n。要小心。"
D.Strings[5551]="你好，$c。请简要介绍肯瑞托能如何为你效力。"
D.Strings[5552]="你在任何地方都不会找到比这更低的价格的！"
D.Strings[5553]="我是奥古斯图斯，这价格太高啦！"
D.Strings[5554]="我是奥古斯图斯！我有你想要的东西！我想要你准备出售的东西！"
D.Strings[5555]="别浪费我的时间，$c。"
D.Strings[5556]="我不训练你这样的$c。在你惹恼我之前找你自己的训练师吧。"
D.Strings[5557]="放轻松点。我只训练战士。"
D.Strings[5558]="我可以为你效劳吗?"
D.Strings[5559]="由于职业的不同，因此我对你缺乏技能的现状无能为力。"
D.Strings[5560]="很好！你达到了要求的参数和规格。我可以为你做些什么吗？"
D.Strings[5561]="你为什么要唤醒我，埃克索图斯，为什么要打扰我？"
D.Strings[5562]="海格纳·重枪，愿为你效劳！"
D.Strings[5563]="虽然塞拉摩以它特有的武士培训闻名，我恐怕还是不能帮你。"
D.Strings[5564]="你与塞拉摩卫兵一起训练过吗？"
D.Strings[5565]="我的孩子，我能为你做什么？"
D.Strings[5566]="我不能训练你这样的$c。"
D.Strings[5567]="我想接受猎人技能方面的训练。"
D.Strings[5568]="我不能训练你，年轻人。"
D.Strings[5569]="炎魔之王和他的兄弟们曾经统治整个世界。作为上古之神的一名仆从，他与泰坦争夺这个星球的统治权。获胜的泰坦将我的主人和他的兄弟们放逐到元素神域——他们被关押在那儿直到时间尽头。"
D.Strings[5570]="你是喜欢枪支还是弓箭？"
D.Strings[5571]="我不具备你想学的知识。"
D.Strings[5572]="很好，$n。"
D.Strings[5573]="我可以为你做什么?"
D.Strings[5574]="我无法训练你。你该去找$c训练者。"
D.Strings[5575]="不要浪费我的时间。"
D.Strings[5576]="你这个莽撞的家伙！你简直是自寻死路！看吧，你惊动了主人！"
D.Strings[5577]="嗨，你需要继续前进，去找$c训练师。"
D.Strings[5578]="拉格纳罗斯，炎魔之王！他比这个世界本身还要古老，在他面前屈服吧！在你们的末日面前屈服吧！"
D.Strings[5579]="教我灵魂的行事方法。"
D.Strings[5580]="灵魂引导你来到我这儿。我要怎么帮你？"
D.Strings[5581]="是因为这些入侵者，我的主人！他们闯入了您的圣殿，想要窃取您的秘密！"
D.Strings[5582]="蠢货！你让这些不值一提的虫子进入了这个神圣的地方？现在你还将他们引到了我这里来？你太让我失望了，埃克索图斯，你太让我失望了！"
D.Strings[5583]="灵魂与你永在，孩子。我能为你做些什么？"
D.Strings[5584]="愿灵魂保佑你。"
D.Strings[5585]="你去哪儿？如果你想快些到那里，那就别犹豫了！"
D.Strings[5586]="我会尽量保证哨兵岭物资供给的，要维持这项行动可不容易。"
D.Strings[5587]="我需要飞骑，要快！我有一封非常重要的信要送！"
D.Strings[5588]="啊，这无尽的痛苦何时才能不再困扰我？"
D.Strings[5589]="谢谢你！谢谢你，牧师。有了你的帮助，我就能对付这些鱼人了！"
D.Strings[5590]="再见，愿光明与你同在。"
D.Strings[5591]="仅在三百年前，一个叫作索瑞森的鲁莽的矮人从他炽热的领地中召唤出了魔王。他重返这个卑微的世界吞噬了周围的田地并形成了这个火山之核。从那以后，强大的拉格纳罗斯就沉睡在了这座山下。"
D.Strings[5592]="你还想说什么？"
D.Strings[5593]="作为忠实的仆从，我们会听从他的命令，执行他的铁血政策的。没有了强大的领域实权，拉格纳罗斯不过是他自身的傀儡罢了。但是，他拥有足够的力量与你抗衡。"
D.Strings[5594]="你好，$g先生:女士;。我想握你的手，但是如你所见，我正忙着做事。我可以帮忙吗？"
D.Strings[5595]="你有了一个好的开始，但是你要学的还有很多，$n。"
D.Strings[5596]="你已经学会了我能教给你的所有东西，$n。如果你还想继续学习的话，去找暴风城法师区的暗夜精灵莉琳希亚·夜风谈话。我听说她是个好老师。"
D.Strings[5597]="虽然我被关在这间小屋里，但是我梦想着加入城墙外激烈的战斗。然而，职责迫使我为替我战斗的那些人传授知识……"
D.Strings[5598]="Ishnu-alah，$g兄弟:姐妹;。你有外面的消息吗？我希望得到泰达希尔的消息。"
D.Strings[5599]="我很荣幸能够传授给你知识，$n。看得出来你用得不错。"
D.Strings[5600]="你必须找一个更有经验的老师，因为你已经超越了我的能力了。我建议你找这里的莉琳希亚·夜风谈谈：她有更多知识可以传授给你。"
D.Strings[5601]="现在轮到你们了！你们愚蠢地追寻拉格纳罗斯的力量，现在你们即将亲眼见到它！"
D.Strings[5602]="德鲁伊们说大自然把部落从卡利姆多赶出去只是个时间问题。然而堕落继续在我们的大地上蔓延，甚至在泰达希尔这里也是。"
D.Strings[5603]="干得好！你对药剂的理解进展不错。"
D.Strings[5604]="不幸的是，对于拥有像你这样经历的人来说我没有什么可教的，我的朋友。找到暗夜精灵希尔瓦娜·林月，她住在达纳苏斯的工匠区。"
D.Strings[5605]="赞美艾露恩，我的$g兄弟:姐妹;。欢迎来到这里。"
D.Strings[5606]="人们从森林植物中制造的东西难道不令人震惊吗？说真的，月神对我们已经很慷慨了。"
D.Strings[5607]="不幸的是，对于拥有像你这样经历的人来说我没有什么可教的，我的朋友。去找暗夜精灵希尔瓦娜·林月，她住在达纳苏斯的工匠区。"
D.Strings[5608]="是我亲爱的恋人卡利派你来找我的？她可是我的宝贝。"
D.Strings[5609]="没想到你会来这儿找我的可爱的卡利谈话。很好。这是药水。有没有人说过你是个头脑简单的家伙？"
D.Strings[5610]="我教不了你，$n。去找塔雷·浆泡；她是一个侏儒，住在铁炉堡的侏儒区。哦，既然你反正要去，请把我的爱带给卡利。"
D.Strings[5611]="别被那些天真的大眼睛欺骗了。塔雷是个专家，我每天都在学习新知识。你认为我为什么会在侏儒区？你看我像个工程师吗？啊，我可不这么想。"
D.Strings[5612]="$g小伙子:姑娘;，努力吧。苦干和决心——那就是成功之道！书本知识是远远不够的。"
D.Strings[5613]="哦，我不能教给你什么，$n。跟塔雷·浆泡谈谈。她几乎够不着桌子，但是当她在配制药水时，你得看仔细了！"
D.Strings[5614]="你看起来像是个喜欢冒险的人。而我，自从我们巨魔来到这里我就受够冒险了。现在我每天都是既来之则安之，而且我为自己训练其他家伙处理冒险的经历。"
D.Strings[5615]="准备好接受下一次训练了吗？好吧。首先，你得放松。随意搅动药水就可以了。"
D.Strings[5616]="你的问题我都回答不了，$n。你需要与奥格瑞玛暗巷区的兽人耶尔玛克谈谈。他会帮你的。"
D.Strings[5617]="桌上的所有瓶子中都盛有今天配制好的药水。心急吃不到热豆腐。哈哈！"
D.Strings[5618]="他们说我愚蠢，我要证明自己的实力。我要关注所有的罐子，证明它们都能煮东西。我的好运就要来了！谁是愚蠢的人，嗯？嗯！？"
D.Strings[5619]="不能帮你。你比我更懂药剂。还有，我还要看着罐子。去找那边的Yelmak谈谈。他懂得很多药剂的知识。"
D.Strings[5620]="本娜就像着魔一样工作。她日以继夜地调制这些药剂，不吃不睡。我知道我们的亡灵盟友需要帮助，但是我担心她这样会伤身体的。"
D.Strings[5621]="在我首次开始配制药水时，我一定打碎过成百个瓶子。我笨手笨脚，瓶子在我手中极易破碎。希望你比我更为小心。"
D.Strings[5622]="你学习的能力已经超过我了。你需要找那边的本娜·冰蹄谈谈以获得更多指示。但请不要占用她太多时间。她需要休息。"
D.Strings[5623]="能看到一张友善的脸真不错。我没有跟药剂师乔汉聊过很多，除非他想要什么东西。他离开坟墓太久了。有一天我也会像他一样，我听说。真可怕。或许到那时我就不在乎了。"
D.Strings[5624]="你是来学习配制药水的？我能传授给你很多知识。虽然我已年老力衰，但脑子还是管用的。"
D.Strings[5625]="我很珍惜我们之间的友谊，但是让我们面对现实吧：你对药水的了解比我多。要是你想得到训练的话，就找亡灵马尔什医生谈谈。他居住在幽暗城的炼金房。"
D.Strings[5626]="这是真的，我曾经是人类。缺点是可能转换为我们的优势的，$n，因为我对人类的劣势了如指掌。"
D.Strings[5627]="很好。从这些标本上再切下一块肉来。让我们看看你学到了什么，我们可以由此开始。"
D.Strings[5628]="你对药剂的知识已经远胜于我，但你还有很多要学的。上楼去到东南面见见马尔什医生。他会交给你真正的苦痛——啊咳。他是一个被遗忘者，他能进一步训练你。"
D.Strings[5629]="别那样看我。我也许跟你不同，我不是个冒险家，但是这并不意味着我的力量比你小。忙碌的生活会让你的手臂变得强壮的。"
D.Strings[5630]="我没有什么可教你的了。但是，我听说有位名叫安尼希尔的暗夜精灵也许能教你。她居住在达纳苏斯的工匠区。"
D.Strings[5631]="很抱歉，$n，但是我可不在新手身上浪费时间。你得找一个跟自己技能相近的人。去达纳苏斯的工匠区找一个名叫米拉·法拉科纳的暗夜精灵。"
D.Strings[5632]="你已经花时间学习基础知识了。现在该提高了。"
D.Strings[5633]="你需要我的帮助？可以。你需要什么？"
D.Strings[5634]="别被沃萨亮晶晶的眼睛和浓密的胡须愚弄了。他是个很有才能的学徒，也是个很好的朋友，即使我在跟他谈话时颈部有些痉挛。"
D.Strings[5635]="嗯，我能教的你已经都学会了。或许你该找其他人谈谈了。试一下达纳苏斯工匠区的暗夜精灵安尼希尔。她确实很有智慧！"
D.Strings[5636]="嗨，实际上没有这么坏。好吧，那么。你想怎么为我办差呢？"
D.Strings[5637]="那很好，$n。无论那是什么，去拿给那边的沃萨看看。他会回答你的任何问题。"
D.Strings[5638]="你是谁？为什么骚扰我？哦，是啦——你是学生吧。是的。我能为你做什么吗？"
D.Strings[5639]="和平也与你同在, $n。你是来寻求知识的吗？"
D.Strings[5640]="教学不只是一项单边活动，$n。当我教你时，我自己也在学习，而我的理解也在加深。"
D.Strings[5641]="我很抱歉，$n，但是我不给新手提供培训。你应该找达纳苏斯工匠区的米拉·法拉科纳谈谈。她可以帮你弥补损失的时间。"
D.Strings[5642]="你已经学会了制作药剂的基础知识，但是要想深化学习需要更加投入。为我完成一项任务以证明你做出的贡献。"
D.Strings[5643]="虽然我很高兴听到你对我的能力充满信心，但我真的没法再教你了。你必须到达纳苏斯的工匠区去找暗夜精灵安尼希尔谈谈。她可以帮助你。"
D.Strings[5644]="即使轻微地改变药剂的成份也能使它发生根本的变化。耐心和精确，年轻人：他们会让你在所有行业都受益匪浅。"
D.Strings[5645]="我制造药剂的技能在你之下。你应该与那边的安尼希尔谈谈。她会明白你需要进一步的培训。"
D.Strings[5646]="你的技能并不是毫无可取之处的。既然你看起来经验非常丰富，有一件事情我需要你的帮助。"
D.Strings[5647]="啊，又回到年轻的时候了，还有第一次发现药剂的时候。谢谢你恢复我的记忆，$n。去跟那边的米拉·法拉科纳分享那份年轻的热情吧。"
D.Strings[5648]="我已经用多年学会了很多药剂知识，$n，而那些知识都由你支配。你只需提要求就可以。"
D.Strings[5649]="我很忙，$n。告诉伍特去处理一切。那个年轻人整天都焦虑不安的。他大部分时间都处于这种状态，像是要做些什么。"
D.Strings[5650]="见到你是我的荣幸，$n，但是你在配制药水方面比我厉害。去幽暗城 炼金房找亡灵赫伯特·哈尔希医生。他能帮助你。"
D.Strings[5651]="我曾四处寻找帮助。你已经获得了技能，要是你有勇气的话，我猜你会付诸行动的。"
D.Strings[5652]="你找错兽人了。我不训练新手。去问问那边的小伍特……谦虚一点。"
D.Strings[5653]="另一名学生，是吗？好吧。我看看有什么能帮助你的。"
D.Strings[5654]="格里克斯和我达成一项共识：他给我供货，而我给他钱。这是很认真的！那个海盗为了一小袋皱皱巴巴的皇血草收我多少钱……足够把一个成年的地精弄哭了。"
D.Strings[5655]="我有许多处方可供选择，我还可以为你打折！"
D.Strings[5656]="这是什么？你试图毁坏我的名声？我不教新手的，$g老兄:女士;。试试找奥格瑞玛暗巷区的兽人伍特谈谈。他很接近你的技术水平。还有智力水平。"
D.Strings[5657]="草药价格太高啦！我总是使用一点别的东西，如果你明白我的意思的话。帮帮我好吗？"
D.Strings[5658]="你做得比我要好！你需要一个经验比我还要多的人。那就是安尼希尔，一个在达纳苏斯工匠区生活的暗夜精灵女士。"
D.Strings[5659]="第一次看见亡灵时，我哭了，我无法想象他们的恐惧和孤寂。大地之母在我耳边吟唱，她告诉我：“拯救他们吧。”"
D.Strings[5660]="你难道感觉不到大地母亲为了她所丢失的孩子，也就是亡灵们，而出现的苦恼吗？快些说，$n。每一秒对我都很珍贵。我们必须帮他们找到回归她身边的路！"
D.Strings[5661]="当我们的盟友，也就是亡灵们，在遭受可怕苦难时候，我如果还在这里训练新手，这会让我感到良心不安。请找那边的克瑞谈谈；他目前能够帮你。"
D.Strings[5662]="你的确有些能力，这是真的，但是我花费时间教你的每一刻对亡灵来说都是承受痛苦折磨的每一刻。你必须向我证明值得让我花时间教你。"
D.Strings[5663]="你制造药剂的技术已经在我之上。去幽暗城的炼金房找亡灵赫伯特·哈尔希医生。他可以继续你的训练，而你也可以亲眼目睹他的人民所遭受的苦难。"
D.Strings[5664]="又来打扰我了。像这样我还能做什么工作么？不用回答，我看起来像是很在乎你的回答么？如果我们要把这个地方打理干净，并继续扩展我们的帝国，我就需要绝对的安静！"
D.Strings[5665]="要我训练你？别开玩笑了——我们都知道这是不可能的。我可无法胜任。你要是想接受训练的话，就去幽暗城的炼金房找亡灵赫伯特·哈尔希医生吧。"
D.Strings[5666]="如果你要占用我的时间的话，你最好证明自己的价值。毕竟，我应该从这样的安排中获得点什么。"
D.Strings[5667]="别浪费我时间。我从事研究的时间比你的年纪还要大。去跟幽暗城炼金房的亡灵马丁·费尔本谈谈。他或许能传授给你一些基础知识。"
D.Strings[5668]="又一个学生。棒极了。正因为如此，所以在林度恩进入管理阶层的时候，我仍然在坚持作一名教师。只要我再获得一枚教学奖章，我的美名便不会被人所遗忘了。"
D.Strings[5669]="我已经恢复了力量，愚蠢的人类，你浪费了一次机会。下次再会吧。"
D.Strings[5670]="有奥格诺恩提供所需的供应，我可以不用寻找一株草药就能完成在这里的任务。如果我永远都不用再次看到自然的奇迹，这就不会很快发生。"
D.Strings[5671]="我没有可传授给你的知识了。穿过拱门走下斜坡到东南方，找赫伯特·哈尔希医生谈谈。他是个被遗忘者，他能教给你更加高级的技术。"
D.Strings[5672]="如果你想成为我的学生，你需要完成一项任务。证明自己的价值，或许我会考虑好好回报你的。"
D.Strings[5673]="你如此大胆地跑来找我，想要接受训练，我对此可不高兴。穿过拱道，沿着坡道向东南方走，跟亡灵马丁·费尔本谈谈。他能教你一些基础知识。"
D.Strings[5674]="到这儿来学习的吗？很好。我想要是我教你的话，你不会对我们的联盟造成太多的伤害。只要你一心对付我们的敌人。"
D.Strings[5675]="虽然每次我都使用了相同的成分，但配制出的药水似乎都达不到预期的治疗效果。这只能得出一个结论：植物发生了变化。我还不清楚具体原因。"
D.Strings[5676]="现在你该找一位更加渊博的老师了。在菲拉斯的羽月要塞居住着暗夜精灵凯兰娜·风语。她有聪明的头脑；毫无疑问她能继续教你。"
D.Strings[5677]="这是出色的工作。你准备代表我接受这项任务吗？没人比你更能胜任了。"
D.Strings[5678]="你制造药剂的技能需要再高超一些才能当我的学生。在此期间，在那边的希尔瓦娜·林月或米拉·法拉科纳可能会帮助你。"
D.Strings[5679]="你的培训进展很好。你该为你的成就感到自豪。"
D.Strings[5680]="我和我的同伴正在收集我们所知的素材，并测试它们的效果。一旦我收集齐备，我将制造出这世界前所未有的药剂。"
D.Strings[5681]="难以置信。你配制药水的技能已经能跟我匹敌了。我不能再训练你了，去悲伤沼泽找斯通纳德的兽人罗格瓦尔谈谈。他以他的宝刀而闻名。"
D.Strings[5682]="你在配制药剂方面确实有才华和激情。然而，我还有一件事要你打理一下。"
D.Strings[5683]="你的技术太差了，还不能跟我学习。去跟那边的马丁医生谈谈，或者爬上斜坡到东南方去看看马尔什医生。他们是被遗忘者，可以给你所需的训练。"
D.Strings[5684]="准备好接受训练了？保持速度，$n。我们要走的路还长着呢。"
D.Strings[5685]="从前我欢迎过黑暗，因为它是夜晚的姐妹。现在总是漆黑一片，甚至在白天也是这样，而森林迫切需要给养。除非我们快些行动，否则这扩散的瘟疫就会遍布整个世界。"
D.Strings[5686]="你是来接受药水配制这一技能的训练的吗？要是你认为能从我这儿不费吹灰之力地学到东西的话，你就大错特错了。走吧，在你没有掌握更高技能之前别来找我。"
D.Strings[5687]="你的技能显示你一直喜爱我们的艺术，但是我想看到你所做承诺的进一步证据。我会分配给你一项任务。完成它就会令我满意。"
D.Strings[5688]="月神曾赐与我技能和经验。现在我要把它们传授给你。"
D.Strings[5689]="卡拉然，我把火炬弄丢了。给我一个新的吧。"
D.Strings[5690]="萨尔酋长派我到这儿来，我感到非常荣幸。我并不奢求能被派往比斯通纳德更好的地方，我只想找些生长在这儿的草药。"
D.Strings[5691]="别像那样搅动药水，你这个笨手笨脚的农民！不，也不要停止搅动它！算了——在你弄出火之前把杓子给我吧。我将尽力补救。现在，你得注意了。"
D.Strings[5692]="嗯，好吧，我看到你还懂一点做药剂的方法。然而，你是否配做我的学生仍有待察看。我有一项任务交给你。争取给我一个好印象。"
D.Strings[5693]="你胆敢让我培训你，你这可怜虫？你期望什么，你这个呆头呆脑的乡巴佬，一场关于如何正确使用银叶的讲演？滚出去！你浪费我的时间没把你打个半死算你走运。"
D.Strings[5694]="谢谢你！谢谢你，$g牧师:女祭司;。有了月神的庇护，我就可以对抗那些堕落的树精了！"
D.Strings[5695]="再见，愿月神与你同在。"
D.Strings[5696]="谢谢！谢谢你，$g祭司:女祭司;。有了你的力量我就可以继续作战了！"
D.Strings[5697]="再见了，愿我们的祖先永远保佑你！"
D.Strings[5698]="谢谢你！谢谢你，牧师。有了你的帮助，我就能对付这些雪怪了！"
D.Strings[5699]="谢谢你！谢谢你，牧师。有了你的帮助，我就能对付这些豺狼人了！"
D.Strings[5700]="再见，愿暗影永远保护你！"
D.Strings[5701]="只需做些小调整……搞定！"
D.Strings[5702]="要是我能的话，我是会训练你的，但是你需要找个稍微……怎么说，聪明点的人为你服务吧！去铁炉堡找特里克希吧。告诉他是布隆克派你去的！"
D.Strings[5703]="想成为工程师，是吗？嗯，穆拉丁保佑你，你来对地方了！"
D.Strings[5704]="%s变得极为狂暴！"
D.Strings[5705]="我的旋转诱饵在哪儿？我刚刚还把它放在这附近的……"
D.Strings[5706]="你目前的智能超出了我的指导能力。你该找我在铁炉堡的侏儒同伴特里克希询问一下！"
D.Strings[5707]="我很高兴能在你事业开始的时候帮上忙，！让我们抓紧纺纱机，开始吧……"
D.Strings[5708]="我听说新型的极速6000型很快就要开下生产线了。我几乎不能抑制激动的心情！"
D.Strings[5709]="呃……虽然我不愿承认，但是你要想继续训练的话就必须跟我的姐妹谈谈。目前来说……我知道的没她多！她乘坐火箭车四处巡查。"
D.Strings[5710]="我愿意教你！要让我的姐姐看看她不是唯一了解工程学的人……"
D.Strings[5711]="你好！我的名字是洁娜！你呢？"
D.Strings[5712]="哦，你还有很多东西要学。我会教给你我所学的全部知识，但是我自己也在学习！你为什么不找铁炉堡的特里克希谈谈，她会帮你进修的！"
D.Strings[5713]="你想学习？跟着我？太棒了！唯一比装配子弹和炸药装置有趣的事情就是与别人分享那种知识！我们开始吧！"
D.Strings[5714]="啊，多么美好的一天啊！真该炸点什么东西。"
D.Strings[5715]="你需要开始学习一些我的专门技术之外的东西！跟那边帐篷前面的利廉姆·火轴谈谈。他会让你步入正轨的！"
D.Strings[5716]="这种工作胆小鬼做不了的。我有个叔叔丢了一只手！可怜的老胖子……无论如何，如果你还感兴趣我或许能给你看些东西？"
D.Strings[5717]="什么？你要什么东西？"
D.Strings[5718]="我不能帮助你！你会遇到比我更精于此道的人！你是联盟的人，你得跟暴风城的利廉姆·火轴谈谈。"
D.Strings[5719]="是的，我有些东西要给你看看。我们来看一下你做得怎么样，或许你会令我吃惊的！"
D.Strings[5720]="（吸气声，吸气声）你闻到了吗？你难道不是只喜欢油脂的气味吗？"
D.Strings[5721]="恐怕你得离开我了，朋友！你该去找奥格瑞玛的诺格，他将带你进入下一阶段!"
D.Strings[5722]="一个热心的朋友，是吗？好吧，你等等，我们会立刻帮你制成一个传动头的！"
D.Strings[5723]="我希望组建队伍。当然，我更希望扩大队伍！"
D.Strings[5724]="你知道谁能真正让你开阔见识吗？诺格！去奥格瑞玛可以找到他。"
D.Strings[5725]="我知道一些。要我告诉你吗？"
D.Strings[5726]="谁说兽人不聪明？当工程师可是很费脑筋的！"
D.Strings[5727]="你知道谁是真正聪明的人吗？诺格！甚至比我还要聪明。你去告诉诺格是桑德派你来的！你可以在那边的控制台那里找到他。"
D.Strings[5728]="你认为你很聪明吗？你认为你得到了吗？让我们查明真相！"
D.Strings[5729]="黑暗女王说过，在这场战争中，知识是我们最强大的武器。"
D.Strings[5730]="你准备好迎接更大的挑战了！见见我右边的弗兰克林·洛伊德。从现在开始他会指导你。"
D.Strings[5731]="工程学能赋予你瓦解敌人的技能和知识！让我教你该如何做……"
D.Strings[5732]="我忙死了，不会跟陌生人讲话的！几乎从来不……"
D.Strings[5733]="你在努力上进……现在甚至已经超过我了！你应该与铁炉堡的宾斯匹德谈话！（他会？她会？）让你见识那些我所做不到的！"
D.Strings[5734]="我可以教你一些诀窍……如果你不介意先帮我做些事情的话。"
D.Strings[5735]="嗯……好吧，我现在还帮不到你！你必须先学习基础知识。你为什么不去见见暴风城的斯普莱特呢！"
D.Strings[5736]="太棒了！难道你不是一个勤奋的人吗？好的，让我们开始吧，行吗？"
D.Strings[5737]="让我看看……14加7，得1进2……是吗？"
D.Strings[5738]="嗯，你学得速度蛮快的！我没法教给你所有知识，但是宾斯匹德是可以的！你可以在铁炉堡中找到他。祝你好运！"
D.Strings[5739]="成交！我会将我所知的传授给你，但是你首先得执行一个小任务……"
D.Strings[5740]="你总有一天能跟我学习……但现在还不是时候！为什么不先跟站在我右边的斯普莱特聊聊呢。入门之后再来找我！"
D.Strings[5741]="你当然不会失望!现在既然我们已经把那个清除掉,你可以下达指令了!"
D.Strings[5742]="我的二十英尺高的火鸡烤肉架的计划快要完成了！现在我需要的就是一只二十英尺高的火鸡了……"
D.Strings[5743]="不要告诉任何人我说过，就当我什么都不知道！如果你还想学习，你应该与店主宾斯匹德谈谈。"
D.Strings[5744]="在我袒露秘密之前，你得证明自己的价值！我会对你进行测试的。"
D.Strings[5745]="靠近点，但是不要抽雪茄！我恐怕你必须得先跟我的妹妹洁娜谈谈。当她领你复习完基础知识再回来找我，我那时就会让你见识真正有趣的东西！"
D.Strings[5746]="对一个初学者来说还不坏！我猜给你看些东西也不会对我有什么损失……"
D.Strings[5747]="要是离天黑还有些时间的话……"
D.Strings[5748]="你赢得了到一个更高级的导师那里学习的权利。去见见我那边的朋友罗克希克。"
D.Strings[5749]="每天都是考验，这天也不例外。如果你通过这次测试，我会教你一些知识……"
D.Strings[5750]="你还没有资格接受我的培训。先去见见桑德，就在那张桌子旁边。当他说你可以了再来找我！"
D.Strings[5751]="你已经通过测试了，干得好！对你的培训可以继续了。"
D.Strings[5752]="我可没时间闲谈，我是个专业人士！"
D.Strings[5753]="你认为我能教给你什么？罗克希克比我更适合做你的老师。你可以在奥格瑞玛找到他。出发吧。"
D.Strings[5754]="让我们看看你的能力，好吗？要是你按要求完成任务，我会乐意教你的！"
D.Strings[5755]="我们彼此都在浪费时间！如果你想接受训练的话，就去找格拉哈姆·范·塔伦吧！他就站在右边。"
D.Strings[5756]="呃……你给我留下了深刻印象。我想我会花时间传授知识给你的……"
D.Strings[5757]="要是我计算正确的话，这车轮很快就会作废的！"
D.Strings[5758]="你的训练已经非常深入了，只有一个导师可以进一步地训练你。找到加基森的巴兹克·布拉斯温！"
D.Strings[5759]="我并非怀疑你的能力，但是我希望你为我执行一项任务，以此证明你的信念。"
D.Strings[5760]="我要教你的东西会让你头脑混乱的！当你学到足够的知识后再来找我吧！"
D.Strings[5761]="很好，你已经证明了你自己！现在进入下一阶段的授课……"
D.Strings[5762]="有时，连我自己都感到惊讶！"
D.Strings[5763]="我没有什么可以教你的啦！如果有人比我知道得多……等等，有啦！去加基森找巴兹克·布拉斯温吧。"
D.Strings[5764]="我认为你更能胜任这项小任务……看看我的说法是否正确！"
D.Strings[5765]="很好的尝试，但是在训练之前，你还需要进行更多的锻炼！回到战壕！"
D.Strings[5766]="很好！无论其他人怎么说，我想我对你的看法是正确的。哈哈！我是开玩笑的！好吧，开始上课……"
D.Strings[5767]="我一直在研究在大城市间通过地下通道运送石油的方法，但是每个人都认为我是在做白日梦。"
D.Strings[5768]="我的朋友，你所掌握的学识已经到了别人梦寐以求的程度。祝贺你！无需更多的仪式，开始你的最后一课吧！"
D.Strings[5769]="给你看看你得到了什么！我承诺，你不会有遗憾的！"
D.Strings[5770]="我从不拒绝那些已经准备好跟我一同训练的人。不幸的是，你不是！你还像个小孩！"
D.Strings[5771]="%s在主人遇到危险时是不会选择死亡的！"
D.Strings[5772]="%s倒在地上并开始冒烟。"
D.Strings[5773]="%s因另一只熔火恶犬的高温而复燃！"
D.Strings[5774]="欢迎，旅行者！是什么风把你吹来的？"
D.Strings[5775]="我担心对有你这样经验的人没什么可教的。但是你还有其他方法。去找那边柜台后面的鲁坎·考迪尔谈谈。他会指引你通过旅行的下一个阶段。"
D.Strings[5776]="嗯……你看起来很有能耐。如果你真想学习的话，那么没有什么能阻挡你！我会指引你通过漫长而硕果丰盛的道路上的第一步。"
D.Strings[5777]="年轻的流浪者，有比铁锤和熔炉更能使钢铁坚固的方法。想学学吗？"
D.Strings[5778]="你确实是个不错的附魔师！现在你该继续了。我想让你与楼上的吉布·草须谈谈。他人有些古怪，但是他会继续指引你！"
D.Strings[5779]="啊，你是个好奇的人，是吗？太好了！听仔细了，这也许能在恶劣的环境下保护好你的皮肤！"
D.Strings[5780]="女神已经赐予我智慧，陌生人。如果那是她的意愿，我将会把它传给你。"
D.Strings[5781]="你的技能已经非我能及。现在你该接受新的挑战了。塔兰丹会帮你准备。他就站在那里的桌子旁边。"
D.Strings[5782]="我会尽我所能教你。每一节课都是女神亲自给你的礼物。正确使用她的礼物，你就会无往不胜。"
D.Strings[5783]="月神的秘密很多，但是它们不能让任何人知道。"
D.Strings[5784]="你在魔法方面的知识真是很出色。如果你愿意的话，还有很多要学的。跟塔兰丹谈谈，他在达纳苏斯的工匠区。"
D.Strings[5785]="开阔你的视野，流浪者，我们马上开始。"
D.Strings[5786]="陌生人，我没有时间浪费啦。说说你的事儿吧，要么就离开！"
D.Strings[5787]="呃，你进展到这个程度了吗？去那边的书架找拉文尼亚·克洛文。要是你没把事情搞糟，或许你能学到更多知识。"
D.Strings[5788]="你看起来不怎么像我，但谁知道呢，可能有一个附魔师藏在那里的什么地方！"
D.Strings[5789]="我最喜欢在这样的日子里到开阔的大草原上去……但是，我的职责所在不容许我那样做。"
D.Strings[5790]="我不能再教你什么啦。但是，我父亲的知识远胜于我。进去跟他谈谈。祝你好运！"
D.Strings[5791]="只要有耐心和决心，很多秘密都是有可能解开的。现在，让我们开始吧……"
D.Strings[5792]="你好！陌生人，你在找什么？"
D.Strings[5793]="你来错地方了。去找那边的专家古丹谈谈。你可以从他那儿学到更多东西。"
D.Strings[5794]="战死沙场是件光荣的事儿！但是，若是你能利用我教你的东西，或许你不会死得那么快，嗯？"
D.Strings[5795]="你是谁？你想从我这儿得到什么？"
D.Strings[5796]="我看起来像什么，附魔师普巴尔？你的技能还需要附魔大师的指导！去阿祖拉之塔找基塔·费温德。"
D.Strings[5797]="太好了，我们开始吧……哈！你受骗了！你当然不会认为是那么简单吧。你需要像其他人一样证明你的勇气！"
D.Strings[5798]="你在开玩笑，是吗？我认为你在寻找那个矮家伙，索恩斯·火石。他就在楼下。现在快逃吧！"
D.Strings[5799]="好吧，嗯……别骄傲！既然你已经证明了自己的能力，我们可以开始了！"
D.Strings[5800]="如果你带着那东西，我会很高兴地为你指路的。"
D.Strings[5801]="一个真正的专家知道他的局限，而我并不羞于承认你的技能超越了我。我想让你到阿祖拉之塔拜访基塔·费温德。她很有声誉。"
D.Strings[5802]="你看起来很自信。我想你不会介意测试一下你的技术吧？"
D.Strings[5803]="你还没有准备好。找贝蒂·奎恩谈谈，他就站在那边的楼梯旁边。当你提高以后再来找我。"
D.Strings[5804]="旅行者，你有充分的理由让自己充满信心。现在你真正的培训开始了！"
D.Strings[5805]="如果你想猎杀纳迦，你需要所能获得的所有帮助。水底有裂缝，能产生足够的气泡供你在水下呼吸。向水面游动，就能利用这些气泡了。"
D.Strings[5806]="看，玛拉甘。我认识$g他:她;。可靠，勇敢，值得信赖。$g他:她;的名字叫$n。"
D.Strings[5807]="$n，嗯？啊！公民$n，过来。伯瓦尔·弗塔根公爵要求联盟所有体格健壮的英雄们都到暴风城要塞见他。你刚刚被征募了，下士！快去！"
D.Strings[5808]="我确实有能力对那些有价值的人进行教学。你是这样的人吗？"
D.Strings[5809]="你是一个非常棒的附魔师。我恐怕已经超出我的才能了。到阿祖拉之塔找到基塔·费温德。现在只有她才配作你的导师。"
D.Strings[5810]="我相信你能胜任这项任务……你要接受挑战吗？"
D.Strings[5811]="你还没有学会基础知识，流浪者。你找我的助手拉琳娜·夏月谈话了吗？可能你需要跟她谈谈。"
D.Strings[5812]="真是细致的工作！你完全有资格获得我将授予你的知识！"
D.Strings[5813]="如果你在寻找一种真正回报丰厚的事业，那么附魔行业正在等待着你！"
D.Strings[5814]="我知道很多事，陌生人，但是你的知识与我的不相上下。想更深入研究的附魔师要去阿祖拉之塔，那里住着一个叫做基塔·费温德的工匠。"
D.Strings[5815]="为什么不让我们见识一下你的能耐呢？如果你完成任务，我很乐意教你些更深奥的东西！"
D.Strings[5816]="当你准备好后我会很高兴教你，但是那一刻还没有来临！我敢肯定拉琳娜·夏月会一直指引你直到那一刻。你或许会在达纳苏斯的工匠区找到她。"
D.Strings[5817]="你已经竭尽全力了，陌生人，我感激你。我曾答应要继续培训你，而现在我要遵守诺言。"
D.Strings[5818]="我的家族数代都从事附魔工作。我在很小的时候就学会了这项技能，就像我儿子现在在做的一样。"
D.Strings[5819]="赫加斯掌握的知识远胜于我。你得去石爪山脉的太阳石居所找他，继续训练。"
D.Strings[5820]="我会教你……很快的。可我需要你先证明自己的忠心。"
D.Strings[5821]="明显莫特并没有派你到我这儿来。他知道得很清楚。你还无法理解我能传授给你的知识。去外面找我的儿子莫特，他会对你进行训练的。"
D.Strings[5822]="啊，很好。你是个优秀的学生，我对你非常满意。现在，我可以开始训练你了……"
D.Strings[5823]="我很少有访客。你在寻找某种特殊的东西，是吗？"
D.Strings[5824]="如果我不是天天都陷在这里，我已经得到训练你们这些人的技能了！不幸的是事实不是这样。去找石爪山脉太阳石居所的赫加斯谈谈。"
D.Strings[5825]="嗯，你若帮我，我就帮你。如果找我要求的做，并做得很漂亮，或许我们可以谈谈你训练的问题。"
D.Strings[5826]="不，不，在你准备好跟我学习之前你还需要很多训练！去跟那个保守的业余人士玛考布·维恩谈谈。他就是那个埋在书里的人。"
D.Strings[5827]="好吧，我明白些了。但是，你有潜力，这点我不会否定。多加留心你或许就能学到什么东西！"
D.Strings[5828]="你好，旅行者！介意探索一下神秘世界的秘密吗？嗯？"
D.Strings[5829]="有些冒险家认为附魔术不起作用。我发现当我向他们挑战，要与他们作战时，他们的看法就改变了！"
D.Strings[5830]="你的技艺胜过我的水平了，陌生人。与石爪山脉烈日石居的赫加斯谈谈。他会传授你比我还要多的知识。"
D.Strings[5831]="你可能拥有它所需的。让我们查明真相！"
D.Strings[5832]="你现在没有资格接受我的培训，陌生人。先到我的助手夏格那里学习一段时间。"
D.Strings[5833]="干得好！在你眼中闪动的光芒……我很熟悉，我年少时也跟你一样！让我看看能不能教你点什么。"
D.Strings[5834]="是什么使你来到塔楼的？"
D.Strings[5835]="你差不多已经达到训练的顶峰了。为了成为你能做到的最伟大的附魔师，你还需见一位导师。她的名字叫做安诺拉，而你或许能在奥达曼找到她。"
D.Strings[5836]="走到这一步很不容易，我知道。但是生活若没有挑战将会多么枯燥无味啊，你不这么认为吗？很好，因为我有一项任务要交给你……"
D.Strings[5837]="你很热心，这很好。然而，你还不够资格接受像我这样的人的培训。"
D.Strings[5838]="你的技能正变得非同寻常。现在，继续你的训练……"
D.Strings[5839]="你是来学习赫加斯部落的知识的吗？"
D.Strings[5840]="安诺拉是唯一一个在技能上胜过我的人。你得去……奥达曼找她，学习更多知识。"
D.Strings[5841]="必须获得真正的实权！现在这一切都取决于你,是现在吗？"
D.Strings[5842]="日复一日地坚持训练吧。当你熟练掌握所有技能的时候，再来找我。"
D.Strings[5843]="你在成为大师的旅途上又达到了新的高度。让我们看看能不能让你更上一层楼……"
D.Strings[5844]="向你致意，旅行者，你帮我驱散了这些可怕的生物，我将永远感激你！我还以为自己要躲藏一辈子呢！"
D.Strings[5845]="我很自豪。你真是个天才学生。现在是你的最后一课吗？"
D.Strings[5846]="你的培训快结束了。完成一项最终的任务你就可以达到你成就的顶点了？"
D.Strings[5847]="在我传授你知识之前，你还必须从其他人那里学习一些课程。勤奋些，不要放弃希望。"
D.Strings[5848]="自从我的丈夫上了前线后，海伦尼便一直保护着我。她用善良的心肠和锋利的宝剑帮助我度过了无数艰难岁月。没有她，我真不知道会发生什么事。"
D.Strings[5849]="唉，对不起。我没什么新东西可以教你了。你去暴风城的老城区找西蒙·坦纳尔谈谈怎么样？他是一个肌肉发达有一头漂亮红发的人类。"
D.Strings[5850]="它怎么样了？我喜欢皮革的味道；你不喜欢吗？"
D.Strings[5851]="我已经了解到很多关于时尚的东西。现在那不过就是掌握制革技巧罢了。西蒙能帮助学习制革的。"
D.Strings[5852]="除了对色彩和细节的鉴别能力外，我没有什么可以教你的。跟西蒙·坦纳尔谈谈；他知道很多制皮的高级技能。"
D.Strings[5853]="这套装备真的让我眼前一亮，你觉得呢？显然，我有多种技能可以使用，我可以将贸易的一些诀窍与你分享。听好了。"
D.Strings[5854]="欢迎来到我们家，$n。拉德纳尔和我没什么东西拿给你，但是我们会尽最大盛情欢迎你。"
D.Strings[5855]="我很抱歉，但你已经学会我所知的一切了。然而，暗夜精灵法多恩可以提供给你进一步的培训。你可以到达纳苏斯的工匠区找他。"
D.Strings[5856]="你要把你的针法做得更小些，$n。这样你的箭袋和弹药袋就不会有东西掉出来。还有，没有人喜欢穿着鼓鼓囊囊的外衣的。"
D.Strings[5857]="如果你对皮革缝纫感兴趣，那你算来对地方了。法多恩和泰龙尼斯都是真正的艺术家，而我希望能从他们那里多学些知识。"
D.Strings[5858]="哦，我很抱歉，但是对于皮革你知道的比我要多。如果你想多学些知识的话去找那边的法多恩谈谈。"
D.Strings[5859]="在达纳苏斯这里真是太令人兴奋了，到处都是才华横溢的人们！我这才知道我会让我的家人感到骄傲的。或许如果我幸运的话，哨兵们会请我加入他们前线的军队的！"
D.Strings[5860]="还没准备好收拾这张皮。我希望做皮革不要花太多时间。肯定有办法削减等待的时间。这对我身体不太好，你知道吗？"
D.Strings[5861]="啊，运气真坏！我的技能对你来说一无是处。呃。跟那边的费布·钢轴谈谈吧。他接触皮革的时间比我长多了。"
D.Strings[5862]="哦，好啊，在我等待时找些别的事情做！你真是救命菩萨，$n！"
D.Strings[5863]="你喜欢这地毯吗？我亲自把动物杀死并剥皮的。但愿所有的半人马能被同样容易的击倒。"
D.Strings[5864]="我没有东西可传授给你了。要是你想进一步学习制皮技能，就找卡洛雷克交谈。"
D.Strings[5865]="我们不能剥下人类及其联盟的皮，这真糟糕。这些皮都白白浪费掉了。尽管如此，谁想穿着你由此制造出的质地极差的皮革？"
D.Strings[5866]="肤质很好。它将你包裹其中。你也许已经注意到我的皮肤不是那么好。我过去常常担心自己的毛孔。这些日子我几乎不担心皮肤了。在某种程度上，它得到了解放。"
D.Strings[5867]="你已经掌握了它的用法。我没有什么要教你的了，但是找亚瑟·摩尔谈谈，他是在幽暗城盗贼区工作的一位被遗忘者。告诉他是我派你去的。"
D.Strings[5868]="在瘟疫来之前，我对皮革一无所知。现在我的知识可以传授别人了。死亡让我有了很多时间供自己支配。"
D.Strings[5869]="肉、兽皮、骨头……好的猎人是不会浪费任何东西的。每块兽皮都有利用价值，也许能用来增强盟友的武器装备。单独来看，我们每个人都很强大，但是团结在一起我们就无敌了。"
D.Strings[5870]="我已经没什么可教你了。带着大地之母的祝福离开吧。在雷霆崖的中央高原西北方的商店找到牛头人塔恩。愿你得到他智慧的指引。"
D.Strings[5871]="我们在此繁衍生息，生生死死，数年来大地却亘古不动。因此，这片土地并不属于我们，$n。我们是属于大地的。因此，我们守护着它，没有它我们就无法生存。"
D.Strings[5872]="我们脚下的洞穴中有许多奇异的兽皮，如果你想深入其中探险的话，一定要非常小心，$n。要记住你自己的性命比那些兽皮有价值得多。"
D.Strings[5873]="你对皮革的理解比我要深刻。可能你应该拜访一下贫瘠之地陶拉祖营地的牛头人克鲁姆·满月。对你这么聪明的学生他有很多知识要教给你。"
D.Strings[5874]="即使在这里的荒原里，你仍在寻求知识。你的求知欲是一种令人倾佩的品德。"
D.Strings[5875]="凯恩自己住这儿，他们说。一旦我完成了制作一件合适的礼物，我就会把他找出来。或许他会有智慧的话要对我说。"
D.Strings[5876]="你的智慧胜于我，朋友。与这里的塔恩谈话；他对皮革的知识比我要丰富得多。我肯定他会欢迎新学生的。"
D.Strings[5877]="在你开始任何工作之前都要洗净双手。皮革被血或尘土玷污了会带走它的自然美。"
D.Strings[5878]="当我从墓穴中爬出来后，我本以为我的家人会热烈地欢迎我。相反，他们把我从村里赶了出去，用一种我听不懂的语言高声尖叫着。"
D.Strings[5879]="我不能帮助你，我无法胜任。跟棺材那边的亚瑟·摩尔谈谈。他会为你提供更多的训练的。"
D.Strings[5880]="记住我说的每句话。在打败敌人之前，我们绝对不能放弃学习知识、提高自身能力的机会。增强你的实力，绝不能放松警戒。"
D.Strings[5881]="帮帮我！刺客来杀我了！"
D.Strings[5882]="我自由了！那东西再也不能折磨我了！"
D.Strings[5883]="你已经超越我有限的能力了。到达纳苏斯的工匠区寻找暗夜精灵安尼希尔。她可以教给你更多知识。我很希望我可以跟你一起去。"
D.Strings[5884]="能找到我算你聪明。我想请你帮个小忙。作为回报，我会传授给你很多知识的。"
D.Strings[5885]="对你来说，我的教学在这个阶段略显深奥了。要是你想学习有关药水的更多知识，就跟泰兰希尔谈谈。"
D.Strings[5886]="听仔细了，$n，我要传授给你的知识很多。"
D.Strings[5887]="即使我也有我的局限性！如果你想继续学习的话去找幽暗城的拉文尼亚·克洛文谈谈。"
D.Strings[5888]="还行……训练你是不成问题的。很好！我们开始吧……"
D.Strings[5889]="兰达尔打扮得有些像花花公子，但是他是个可靠的人，他比我向许多学生所说的那样更加值得信赖。尽管如此，我还是不能责备他们想要冒险的想法。"
D.Strings[5890]="很抱歉，我已经没有什么可以教给你的了。如果你还想学的话，就去达纳苏斯的工匠区找泰龙尼斯吧。我听说他相当有才能。"
D.Strings[5891]="好吧，我会教你的，但是我需要你为我做一些事情。这很重要，听仔细了。"
D.Strings[5892]="当你接受更多训练以后再回来找我。在那边的兰达尔·沃斯可以帮你。"
D.Strings[5893]="嗯，我想我可以再收一个学生。好吧，不要傻站在那里。告诉我你想学什么。"
D.Strings[5894]="达丽亚娜答应了，但是她的精力如此充沛，很难让她安静下来仔细的聆听。她气力十足又机灵敏捷，我恐怕她不久就会被叫去参加战斗。我们必须快点教她。"
D.Strings[5895]="如果你来这儿是为了得到进一步的训练，那你是高估我的能力了。跟泰龙尼斯谈谈；他应该能帮助你。"
D.Strings[5896]="这场战争夺去了很多人的性命，也耗费了大量的资源。即使是泰达希尔的人民也不能幸免于难。请原谅我做出这样的请求，你能帮我执行一项任务吗？"
D.Strings[5897]="你得及时准备好接受我的教学，$n。到那时，找达丽亚娜谈谈，他会帮助你训练的。"
D.Strings[5898]="我们可以从死去的动物身上获得原料。别无视它们的牺牲，$n。带着尊敬来处理这些皮革。"
D.Strings[5899]="要做的事情很多！自从我的兄弟不小心蒸发了诺莫瑞根所有的衣料和皮革之后，事情便多起来了。我只能保持暂时通风！啊，$n，那些日子……"
D.Strings[5900]="不，恐怕我不能帮你。你的技能远胜于我！如果你想学习更多的知识，跟达纳苏斯工匠区的暗夜精灵泰龙尼斯谈谈。他拥有令人惊异的技能！"
D.Strings[5901]="你的学习速度真快。这很好，我最近实在是太忙啦。事实上，那倒提醒了我：你能帮我办件差事吗？"
D.Strings[5902]="嗯，我声明！他是个新学生！只要你再多掌握一点技能，我会很乐意将我所知道的一切都教给你的。去跟格雷塔谈谈，好吗？她会教你如何速成技能的。"
D.Strings[5903]="你的技术在进步,很快你就会拥有一家你自己的皮革商店。我很高兴能帮你，$n。我的速度就只能这么快了，你知道吗？有那么多工作要做！"
D.Strings[5904]="我知道，这块蓝色的皮革吸引了你的目光。你看，许多热情高涨的新兵都在这附近狩猎，像失去理智般砍杀动物。你必须提高警惕。"
D.Strings[5905]="我不能再教你啦：你所掌握的技能已经超过我了。去雷霆崖中央平原西北部的商店找牛头人犹纳吧。她会为你提供更多训练的。"
D.Strings[5906]="我有一项紧急的工作，但我自己没有时间处理。我可以把它交给你吗？"
D.Strings[5907]="我不会给一个学徒训练。去贫瘠之地的哀嚎洞穴找牛头人瓦多尔吧，他会帮助你的。"
D.Strings[5908]="你来这里是为了进一步的训练？抖去你身上的尘土吧，让我们马上开始工作。"
D.Strings[5909]="我的斧头经历过多场战事，我喜欢将它带在身边。敌人曾数次入侵我们的首都，但是别怕：我们总能击退他们。"
D.Strings[5910]="我不能为你提供更多的训练啦：你的制革技能已经超过我啦。你应该去那儿找犹纳谈谈。如果需要的话我会为你担保的。"
D.Strings[5911]="你来找我寻求建议，而我也要请你帮一个忙。确保它完成，你就会得到奖赏。"
D.Strings[5912]="你的技艺不足以学会我所教授的。去找那边的玛克谈谈。他可以帮你直到你准备好学习更高级的课程。"
D.Strings[5913]="我目前对你的进步感到很满意。很显然大地母亲已经赋予你的双手以灵感了。"
D.Strings[5914]="眼下，我们在这片大陆上只有一处立足之地，但是人类是永远不可能打败我们的。他们很快就会受到报复。我们会割下他们说谎的舌头，惩戒他们的背叛行为。"
D.Strings[5915]="要是我能的话，我会教你的，但我力所不及。去跟雷霆崖中央高地西北部的商店找牛头人犹纳谈谈。她拥有真正的才能。"
D.Strings[5916]="兽人军队要做的事情还很多，而大部分的事情只有我才能做。但是，我还是能帮一下忙的。"
D.Strings[5917]="你没经过适当的训练就来找我，说明你勇气有余而智慧不足。去找个接近你的技术水平的人谈话，像兽人卡玛瑞，他住在奥格瑞玛的暗巷区。"
D.Strings[5918]="至少在部落派出更多的援军之前，这儿还不能被称为文明社会。你一定很喜欢制作皮革。"
D.Strings[5919]="我忙吗？这话什么意思？你觉得我只是成天站在这儿玩弄手指吗？如果你想买些什么的话，跟罕杜尔谈谈。"
D.Strings[5920]="你在我这里学不到新的东西了；你知道的已经很多了。如果你想得到更多培训的话，去找雷霆崖中央高原西北方商店里的牛头人尤纳谈谈。替我向她致意，怎么样？"
D.Strings[5921]="我承认，那是份体面的工作。如果你能帮我处理一些事务的话，你会给我留下更深的印象的。"
D.Strings[5922]="你在学习好基础知识之前不能学我的技艺。如果你对训练感兴趣的话就去找卡玛瑞谈谈。"
D.Strings[5923]="奥格瑞玛地形迂回曲折，能有效地阻止入侵者。你能想象这些矮小的侏儒在多么短的时间内就迷失方向吗？哈哈！如果足够幸运的话，我会追踪到他们，将他们变成我的宠物。"
D.Strings[5924]="我生前是一名图书管理员，与战争和灾难无缘。我从未想过要变成现在这样。另一方面，现在我能主宰自己，我是不会不战而降的。"
D.Strings[5925]="你的能力已经超过我了。走吧。嗯，去雷霆崖中央高地西北部的商店找牛头人犹纳。她拥有强大的力量。"
D.Strings[5926]="好的，好的，我会训练你。你没有必要大声嚷。"
D.Strings[5927]="要是我教新手的话，那会有无数的学生来拜访我，那还不得乱成一团了。去跟那儿的丹·戈萨斯谈谈。他有些过于热情了，但意图总是好的，而且他是个相当好的老师。"
D.Strings[5928]="起先，我在魔法区开设商店，但是那儿太嘈杂啦。尽管我进行了重新部署，除了有些学生坚持要向我求学之外，环境还是得到了相当的改善。"
D.Strings[5929]="月神已经赐予暗夜精灵很多礼物。作为回报，我们有职责保卫这些森林免受部落带来的恶魔的污染。"
D.Strings[5930]="继续培训你已经超越我的能力了。与达纳苏斯工匠区的泰龙尼斯谈谈。他总是很愿意帮助有才能的学生。"
D.Strings[5931]="我不能离开这里的岗位，$n，但是有一项任务必须完成。我可以把它托付给你吗？"
D.Strings[5932]="我只教那些掌握基本指示的学生。你必须在达纳苏斯工匠区找到暗夜精灵达丽亚娜。她的技能与你的是完美的互补。"
D.Strings[5933]="在你开始切割皮革之前一定要仔细检查尺寸。我们可不能浪费材料。"
D.Strings[5934]="杜加尔，我需要空运服务！我要运送重要物资！"
D.Strings[5935]="你知道在哪儿能找到水兽敏捷坠饰吗？"
D.Strings[5936]="你知道在哪儿能找到水兽耐力坠饰吗？"
D.Strings[5937]="你必须去西部荒野的海洋搜寻，向正西方——金海岸矿洞与海岸交接处往西北方向。海岸边有一只锚，看来附近一定有艘沉船。水下的压力很大；如果游得太远的话，即使是最优秀的潜水者也可能死于疲劳。$B$B去找一处适宜的自然环境吧，$n——这附近有起泡的海底裂缝，能在深海潜水时提供氧气。"
D.Strings[5938]="在银松森林北流海岸边缘，海滩上搁着一艘废弃的船。船只以西有你要找的东西；游得太远的话，你会因疲劳无法游回海岸的。海床上有一只上了锁的箱子，等着你去取呢。$B$B要是没有人帮忙的话，潜到这样的深度会受到极大的压强，要小心；海床上有一道裂缝，能释放出气泡，有助于你寻找那半块坠饰。好好利用吧。"
D.Strings[5939]="在黑海岸的北面流淌着壁泉河，发源于现今的费伍德森林。随着河流流到并汇入薄雾海，一直蜿蜒到海洋北部最深处。在那儿有你要的石头，由于这种石头的形状酷似爪状，因此被称为石爪。$B$B要当心——蛇颈龙聚集在石爪那里，他们会攻击那些贸然入侵的人。"
D.Strings[5940]="在贫瘠之地的东北部，有一处受到严重污染的水池。当地人称它为淤泥沼泽；风险投资公司将水晶般幽蓝的水域变成工业副产品和废弃品的泥潭。在沼泽的中心有你要找的东西，$n。$B$B要小心，风险投资公司绝不容许有人入侵，他们将不为其工作的人都当作入侵者。你作为自然的保护者，更是他们极力对抗的目标。"
D.Strings[5941]="草地柔软青葱。空气清新，阳光明媚，歌声飘飘。泰达希尔的梦想终成现实。但是为什么我感到有种不详的预兆？"
D.Strings[5942]="你的进步已经超越了我能教授的技艺了。现在到辛特兰的鹰巢山去找矮人德拉克·石拳谈话。他的作品太棒了，比我的好多了。"
D.Strings[5943]="你已经证明了学习我们的工艺的技巧。但你有替我完成任务的决心吗？"
D.Strings[5944]="$g尊敬的先生:女士;，在你掌握制皮的更多知识之前，我还不能帮助你，对此我感到很遗憾。跟法多恩或达丽亚娜谈谈。他们能教你所需的技能。"
D.Strings[5945]="别试图将你的意愿强加到皮革上。而是让其天然的特性显示出自身的形状和功能。这不是一场战役。与皮革协同工作，而不是与其作对。"
D.Strings[5946]="针太细，线太粗，针脚倒还不错。我们与萨尔和其他人的合约将继续有效。部落不会被驱逐出这片土地的。"
D.Strings[5947]="我的才能有限，你也已经达到了。恭喜你，$n。你的下一站应该是菲拉斯的莫沙彻营地。牛头人哈拉纳·铁皮住在那里；她的技术很有声望。"
D.Strings[5948]="作为部落的成员，我们必须为我们的社会做出贡献，以保证它的繁荣兴旺。因此，我相信你会很高兴能帮助我们完成一项小小的任务。"
D.Strings[5949]="我自己不久前也是一个新手，所以我觉得我不太适合教你。试着跟那边的塔恩或是玛克谈谈。他们之中应该有人能回答你的问题。"
D.Strings[5950]="凯恩把我们带到了一片充满希望的大地。我们很幸运，因此我们再把好运带给别人。这就是我为什么开始教学的原因，$n。"
D.Strings[5951]="我可以利用在这儿找到的材料制作有趣的东西。这些山林中有许多奇怪的生物！去杀死它们，$n。"
D.Strings[5952]="哦，我认识到自己的困惑，这真是个悲伤的日子。当我醒来时，发现自己被晒黑了，接着我生平第一次喝啤酒。那根本不算一场宿醉！从那时起——我便明白了啤酒！——明白了喝下啤酒是怎么样的状况。"
D.Strings[5953]="我喜欢机会；你不喜欢吗？啊，当然你也喜欢。这就是你要按我说的去做的原因。"
D.Strings[5954]="我不是来教那些刚离开摇篮的宝宝的。你离我对学生的要求还差远了。你不过是个年幼的$g小伙子:姑娘;，你最好别在这儿烦我了。"
D.Strings[5955]="我所有的作品都必须由买主亲自来订购。奥尔文常常要我改变这个习惯，但是我就是不改。看看你周围吧，无数战士还指望我给他们打造装甲呢。"
D.Strings[5956]="我真希望有更多像你一样的学生。很少有人会冒险深入敌境。我佩服你的勇气。"
D.Strings[5957]="我不会在这场战争中让步。我不分昼夜的制造新装甲，还把旧的装甲修补好。我没时间做其他任务。你愿帮我分担一些吗？"
D.Strings[5958]="你来找我求学是浪费了你我的时间，$n。我没时间教授基础技能。我们在这里战斗，而这里是一处前线。在你准备充分之前不要再来找我。"
D.Strings[5959]="我觉得你的服饰急需维修。"
D.Strings[5960]="我对裁缝业知之甚少，但你需要更多的帮助。我听说有个暗夜精灵精通裁缝技术。他居住在暴风城的魔法区。"
D.Strings[5961]="你想学点东西吗？我会很乐意教你的！"
D.Strings[5962]="生活就像一幅小心编织的锦缎。"
D.Strings[5963]="嗯……你需要学的东西有点超出我的能耐了。去找那边的塞拉多斯谈谈。我会的东西全是他教的！"
D.Strings[5964]="很好，开始学习裁缝吧。"
D.Strings[5965]="缝纫需要娴熟的手法，以及……也是最重要的，耐性。"
D.Strings[5966]="现在是你去达纳苏斯跟迈里恩谈谈的时候了。她将对你进行指导。"
D.Strings[5967]="很高兴能将你收入麾下。让我们开始吧。"
D.Strings[5968]="欢迎来到我的商店。我能为你做什么？"
D.Strings[5969]="等一下，我只是一个助手。如果你想学那些花哨的东西，找那边的老约莫德·石眉谈谈。"
D.Strings[5970]="很好！我一直希望收个新学生。那么就让我们立刻开始吧！"
D.Strings[5971]="我们使用动物皮毛制作物品。"
D.Strings[5972]="我知道一些，但我不是专家。祝你好远，玛加尔也是。他就站在商店后面。看看他是否能帮助你，但是小心别惹恼他。他脾气有些暴躁。"
D.Strings[5973]="我会将我所知道的传授给你的。"
D.Strings[5974]="我们没有浪费狩猎而得的动物的任何一部分。"
D.Strings[5975]="你寻求更高级的知识。坦帕拥有这种知识。她应该就站在附近……"
D.Strings[5976]="带着大地母亲的祝福，我们要开始了。"
D.Strings[5977]="去结交朋友吧。我能帮你吗？"
D.Strings[5978]="我知识渊博，但我还不是专家。你知道你该去找谁谈话吗？雷安诺！她就在不远的地方。到幽暗城打听她的下落。"
D.Strings[5979]="这么说……你想当一名裁缝？很好，让我们看看你是否具有这样的潜质。"
D.Strings[5980]="到我们这儿来的客人可不多。你对我感兴趣？"
D.Strings[5981]="我只是个学生。雷安诺才是专家。她站在那边的箱子旁。你可以从她那儿学到很多东西。"
D.Strings[5982]="是的，我认为你有潜力。或许我可以给你看看一两样东西？"
D.Strings[5983]="没有比编织更好的宁神方法了。"
D.Strings[5984]="你的教育正在继续，而你的知识已超越了我。如果你还想继续学习你就必须找迈里恩谈谈。她会指引你的。"
D.Strings[5985]="你不会失望的，旅行者。裁缝是一种充满乐趣的工作。"
D.Strings[5986]="嗨，我能为你做什么呢？"
D.Strings[5987]="你所掌握的知识已经跟我差不多啦。或许你可以去奥格瑞玛找玛加尔。他虽然不是最好的裁缝，但是他一定可以帮助你。"
D.Strings[5988]="这就对了！拿起针线让我们开始吧！"
D.Strings[5989]="恐怕我已不再是个文雅谦逊的人了。年龄和无数战争让我的皮肤和灵魂变得坚硬无比。或许这就是凯恩派我来烈日石居的原因……和煦的暖风和温暖的阳光无法减轻我的痛苦。"
D.Strings[5990]="我知道你会来的，$n。很高兴再次见到你，朋友。"
D.Strings[5991]="嗷！"
D.Strings[5992]="%s失去能量，被关闭了！"
D.Strings[5993]="%s几乎碎掉了！"
D.Strings[5994]="你好。我们的蝙蝠训练很严而且吃得不错。你不会找到比他们还快的了。"
D.Strings[5995]="我要如何效劳？"
D.Strings[5996]="你好，欢迎。我不太擅长微笑，但是相信我；我很高兴能为您服务。"
D.Strings[5997]="角鹰兽是一种高贵而迅捷的动物。这些训练有素的飞兽可以让它们的骑手以很快的速度旅行。"
D.Strings[5998]="为了与大陆保持联系，我们会定期派出角鹰兽在鲁瑟兰村和黑海岸之间传递信息的。"
D.Strings[5999]="泰达希尔海岸边的鱼儿又大又精神。有传言说那是因为我们新的世界之树的快速增长而引起的。"
D.Strings[6000]="尽管黑海岸比泰达希尔更危险，但是很多渔夫都在此谋生。"
D.Strings[6001]="为冒险家服务是我的荣幸，因为他们即将成为英雄。"
D.Strings[6002]="很抱歉我不能让你乘坐我的狮鹫。如果你确实需要飞行服务的话，就去找格林戈谈谈。"
D.Strings[6003]="我这里的狮鹫是鹰巢山以南飞得最快的。想要乘坐吗？"
D.Strings[6004]="好吧！我们出发。"
D.Strings[6005]="你可以在北边的码头搭船前往鲁瑟兰村和达纳苏斯。南边的码头是穿越无尽之海通往暴风城港口的航线。西边的那座码头通往埃索达附近的秘蓝岛。祝你一路平安！"
D.Strings[6006]="朋友，保持警惕。除非打一架，否则母龙是不会放弃的。"
D.Strings[6007]="这个码头？你可以乘船前往暗夜精灵的领地。地名？嗯，我想是奥伯丁。我不太确定，我只是一名搬运工。"
D.Strings[6008]="就像很久以前在卡拉赞注定的那样，怪物。我来了，带着公正的裁决而来！"
D.Strings[6009]="你是来帮助投递物品的吗？米兰就快准备好了。"
D.Strings[6010]="我的双足飞龙可以在贫瘠之地高速飞翔。"
D.Strings[6011]="贫瘠之地阳光灼热，那儿的居住者充满敌意，是考验你的力量和决心的最佳地点。"
D.Strings[6012]="要将这些桶运送到挖掘点非常困难，但是要获得火药，还得靠我们自己。$B$B我们必须竭尽所能地对抗黑铁！"
D.Strings[6013]="你好。如果你是来找皮件的，那么你会看到我的货品做工精细。"
D.Strings[6014]="谢谢你的帮助，$n。在你的帮助下，另一艘货船安全抵达了挖掘地。"
D.Strings[6015]="当坐在一个驭风者背上时，你就会发现它的力量和速度的确不是徒有虚名。"
D.Strings[6016]="你操纵得比我要好！你需要一个经验比我还要多的人。那就是赫?特·哈尔希医生，一个在幽暗城炼金房工作的亡灵。"
D.Strings[6017]="什么？你试图毁坏我的名声？我不教新手的，$g老兄:女士;。去找达纳苏斯工匠区的米拉·法拉科纳谈谈。"
D.Strings[6018]="抓住他！抓住这个卑鄙的罪犯和他的同伙！"
D.Strings[6019]="看看我的肉，朋友。你不会想双手空空就进入贫瘠之地吧。"
D.Strings[6020]="雷吉纳德，你知道，我是不能让你通过的。"
D.Strings[6021]="在你从驭风者背上往下俯瞰这个世界之前，不能说你真正活过。"
D.Strings[6022]="你一定要做你认为是正确的事情，马库斯。我们一起在图拉扬将军麾下服役。他使我们两个成为了今天的样子。他看错我了么？你真的相信我的目的是要破坏我们的联盟吗？我让我们的英雄们蒙羞了吗？"
D.Strings[6023]="%s似乎陷入了沉思。"
D.Strings[6024]="我很惭愧，老朋友。我不知道我该怎么办了。并不是你使那些伟大的英雄蒙羞，而是我。是我和其余堕落的政客们。他们让我们的生命中充满空洞的诺言和无尽的谎言。"
D.Strings[6025]="亲爱的朋友，你警惕的目光让英雄们以你为荣，你对联盟忠心耿耿。你会在必要的时候像那些俯瞰着你的英雄一样，为你的人民做出伟大的牺牲，我对此毫不怀疑。"
D.Strings[6026]="退后！你们没看到英雄正在与我们同行吗？"
D.Strings[6027]="让开！让他们过去！"
D.Strings[6028]="雷吉纳德·温德索尔不得受到任何伤害！让他安全地通过这里！"
D.Strings[6029]="去吧，雷吉纳德。愿光明指引着你。"
D.Strings[6030]="你可以从这个码头找到去塞拉摩的路。记住我的话，那些地方对从联盟去的人们是非常不安全的。一定要小心谨慎。"
D.Strings[6031]="我们令祖先蒙羞。我们令牺牲的同胞蒙羞……原谅我吧，雷吉纳德。"
D.Strings[6032]="把我挡在这里可不是明智的决定，马库斯。"
D.Strings[6033]="现在是结束她统治的时候了，马库斯。让开，我的朋友。"
D.Strings[6034]="你对皮革的理解比我要深刻。可能你应该拜访一下灰谷森林阿斯特兰纳的艾蒂安·花丛之风。对你这么聪明的学生,她应该有很多知识要教给你。"
D.Strings[6035]="你好。"
D.Strings[6036]="你的技艺在我的技术水平之上了。可能你该见见我们商店的老板，乔吉奥·波利罗。他就站在那边的柜台附近。"
D.Strings[6037]="我会教你的，但是首先你得证明自己的实力……"
D.Strings[6038]="跟楼梯那儿的劳伦斯·瑟尼德交谈。他善于引导初学者。"
D.Strings[6039]="都是些有用的东西。你的教导可以继续进行了。"
D.Strings[6040]="啊，这件达纳苏斯织品质量最好！"
D.Strings[6041]="嗯，你这个聪明的家伙！我可以明确地告诉你，你知道的比我多！你可别为此自负，如果你想继续学习的话，就去暴风城找乔吉奥·波利罗谈谈吧。听说他是个很好的裁缝！"
D.Strings[6042]="我不训练任何人！你需要首先完成一项任务！"
D.Strings[6043]="我可没时间跟小孩子耗！去跟我的助手阿斯拉谈谈！"
D.Strings[6044]="嗯……看来还有点希望，我会把那个给你的。那好吧，我们在哪里？"
D.Strings[6045]="看看周围，$r。你应该为今天能看到的一切而心存感激。$b$b自从我第一次走进这片森林，这里的许多东西都已经改变了。这些都是奇妙的，出乎意料的改变……"
D.Strings[6046]="我能制造你在商店里看见的若干东西。你认为如何？小心回答，这也许能决定你的命运。"
D.Strings[6047]="你需要找一个比我懂得多的人。去找幽暗城的乔瑟夫·格里高利谈谈。那么，你还在这里干吗？"
D.Strings[6048]="你认为你走到我跟前我就开始教你了？哈！你需要像其余所有人一样支付学费！"
D.Strings[6049]="什么？你为什么在烦我？哎呀，我打赌你甚至不能制造一件高质量的长袍！去找斯诺恩谈谈，等你水平提高以后再来找我！"
D.Strings[6050]="你那时给我看了某些结果！现在该我给你看看结果了！"
D.Strings[6051]="他们说小洞不补大洞……什么来着？啊，我记不得了。反正是愚蠢的说法。"
D.Strings[6052]="对一个业余者来说……这还行！你的知识量已经跟我持平了。要是你想学习更多知识，就去幽暗城找乔瑟夫·格里高利谈谈。"
D.Strings[6053]="或许你懂了，或许你没懂。我想我会设法查明真相的……"
D.Strings[6054]="哈！你仍然还没有所需的……！你学会些东西后再来找我！"
D.Strings[6055]="嗯，嗯，还不坏。或许我能让你看点什么……"
D.Strings[6056]="多好的天气！它让我有了创造新设计的灵感。"
D.Strings[6057]="你的才能出众！你真是有灵性。你要想继续追求知识的话，找暴风城的乔吉奥·波利罗谈谈。他深受众人尊敬，而且他能深化对你的指导。"
D.Strings[6058]="一个人在通向成功的路上必须克服很多困难。你的道路也不例外……"
D.Strings[6059]="必须首先学习一些基础知识。蒂安娜就站在旁边，找她谈谈然后回来找我。"
D.Strings[6060]="你干的很好，旅行者。我能收你当徒弟令感到很骄傲！"
D.Strings[6061]="欢迎来到我的帐篷。我可以帮你吗？"
D.Strings[6062]="你的知识很渊博，旅行者。你必须向一个比我更聪明的人学习。关于乔瑟夫·格里高利的智慧的故事广为流传。你可以在幽暗城找到他。"
D.Strings[6063]="在我们继续之前我想让你完成一项任务……"
D.Strings[6064]="在我开始培训你之前你还有功课要学。而在同时，或许雷霆崖的范恩能够帮你。"
D.Strings[6065]="完成得很熟练！现在，让我们继续你的教育……"
D.Strings[6066]="愿圣光与您同在，长官。"
D.Strings[6067]="这些图案难道不漂亮吗？每一个都有自己的风格。"
D.Strings[6068]="我的知识有限，尽管我还在继续学习。现在该你继续了，旅行者。在幽暗城找到乔瑟夫·格里高利并告诉他你准备好了。"
D.Strings[6069]="您对我们所有人都是一种激励，阁下。"
D.Strings[6070]="在我教给你我的本事之前我需要看到你的决心……"
D.Strings[6071]="那边走过来一位英雄。"
D.Strings[6072]="在我帮你之前你必须学会一些基础的东西。与我的徒弟范恩谈谈。他很耐心而且愿意教你所需的知识。"
D.Strings[6073]="你真是一个意志坚定的学生。我很高兴给你提供指导！"
D.Strings[6074]="让开！"
D.Strings[6075]="裁缝可以派得上大用场。我从前就不得不把我的胳膊缝上。"
D.Strings[6076]="我们不过是您脚下的尘土。"
D.Strings[6077]="你做得很好……是时候见见老板了。找到乔瑟夫并告诉他你准备好了。"
D.Strings[6078]="好的……那么说你想成为一个裁缝。你能证明这点么？"
D.Strings[6079]="我永远都会记住这一刻。"
D.Strings[6080]="我怎么能把我的秘密告诉一个初学者呢？先试着跟博文谈谈。"
D.Strings[6081]="好极了，你很有勇气！我很满意。那么，我们就出发吧！"
D.Strings[6082]="……瑟银的胆量。"
D.Strings[6083]="一个活生生的传说……"
D.Strings[6084]="是的，我现在已经经营这家店一段时间了。最近生意非常好。许多新的探险者来了……"
D.Strings[6085]="我只知道有一个人能在裁缝技能上胜过我。我最后一次听说他在塞拉摩岛。你该去找他。"
D.Strings[6086]="我要所有学生都证明他们的热情。现在轮到你了……"
D.Strings[6087]="我恐怕在我可以教授你知识之前你要需要更多的训练。"
D.Strings[6088]="太好了！我能断定我的努力不会白费！"
D.Strings[6089]="布料也可以。就我个人来说我更喜欢使用人皮。"
D.Strings[6090]="你需要一个真正大师的指导！到塔伦米尔的达瑞尔·斯塔克那儿去试试你的运气！"
D.Strings[6091]="在你开始学习之前，我得让你帮我个忙……"
D.Strings[6092]="当时机合适时，我会传授知识给你的……不是现在。你还得学习更多的知识！"
D.Strings[6093]="我给国王提供过装备。如果有正确的训练，你也可以。"
D.Strings[6094]="你已经真正成为这行中最好的裁缝之一了！恭喜你，我为曾当过你的导师而感到骄傲！"
D.Strings[6095]="你走了好远的路了，旅行者。还有一项工作要你完成……"
D.Strings[6096]="你要学习更多的基本技能，我才能帮助你。当你准备好了再来找我。"
D.Strings[6097]="我不值得，先生。"
D.Strings[6098]="这地方通风良好……但是我还在乎什么？我已经死了。"
D.Strings[6099]="干得好！你获得了裁缝的最高荣誉。去吧，好好利用自己的知识去做大事！"
D.Strings[6100]="你在缝纫艺术方面做得很好，我必须承认。现在，让我们看看你到底有多棒……"
D.Strings[6101]="谁派你来的？你还没有准备好接受我的指令！当你们准备好以后会得到通知的。"
D.Strings[6102]="我确实很喜欢坐在这里，听着大海的声音。哦，什么？是的，有一艘船会把你带到米奈希尔港。它有时会停在这里。"
D.Strings[6103]="谢谢你，老朋友。你做得好。"
D.Strings[6104]="跟着我，朋友。到暴风城要塞！"
D.Strings[6105]="朋友，勇敢些。这只爬虫会剧烈地翻滚起来。那是绝望的表现。你准备好了就跟我说一声。"
D.Strings[6106]="记得我的话！你在东部王国是找不到比塞尔萨玛狮鹫更快的狮鹫的！"
D.Strings[6107]="国王陛下，请在一切还来得及的时候赶快退避一下吧。她并非你所想象的那样……"
D.Strings[6108]="化妆舞会结束了，女伯爵普瑞斯托。或者我应该称呼你的真名……奥妮克希亚……"
D.Strings[6109]="尊贵的陛下，请到安全的大厅去。"
D.Strings[6110]="要是你问我的话，没有比矿工更好的职业了，也没有比矮人更好的矿工了！"
D.Strings[6111]="你会被监禁并因叛国罪接受审判，温德索尔。我会很高兴看到他们宣布你有罪，并把你送上绞刑架……"
D.Strings[6112]="当你瘫软的尸体在绞刑架上摇摆的时候，我会为一个疯子的性命终于得到终结而高兴。毕竟，你有什么证据呢？你难道想要到这里来挑衅一个贵族，然后毫发无伤地离开？"
D.Strings[6113]="蛮锤城堡的矮人也许有奔跑迅速的战马，但是这些鹰巢山的狮鹫能承受大熔炉的热量吗？我觉得不能！"
D.Strings[6114]="你逃脱不了你的命运，奥妮克希亚。预言早已注定了这一切——卡拉赞的大厅里浮现的幻景早已预示了你的结局。现在来做一个了结吧……"
D.Strings[6115]="听着，你这条龙。让真相大白于天下吧。"
D.Strings[6116]="最好的矿工紧握$g他:她;的铁锄，拥有一颗坚定的心，头发上还散落着一层厚厚的黑灰。"
D.Strings[6117]="那个坚固的箱子在木材厂中间，周围推满了残骸和血色十字军的狂热信徒。"
D.Strings[6118]="将装有白蚁的桶放入箱中。"
D.Strings[6119]="%s伤得太重，放弃了追逐。"
D.Strings[6120]="%s很明显被击败了，他正试图逃跑。"
D.Strings[6121]="%s打开包裹，取出密文石板。"
D.Strings[6122]="黑铁矮人认为这些石板是经过加密的。但这不是什么密码，只是古老的龙语而已。"
D.Strings[6123]="%s开始阅读石板。某种从未听过的神秘声音在你耳边回荡。"
D.Strings[6124]="你能告诉我关于那只熊——乌萨苟斯的情况吗？"
D.Strings[6125]="你能告诉我关于夜刃豹——猎影的情况吗？"
D.Strings[6126]="你能告诉我关于角鹰兽尖爪的情况吗？"
D.Strings[6127]="这只熊漫步在一条靠近石爪小径的路上，在密斯特拉湖和联盟的银风避难所正西方。虽然他是你在灰谷遇到的三个动物之中最好对付的一个，对他也不能掉以轻心。他的出现对于逗留在灰谷和石爪山脉之间的旅客来说是一个巨大的威胁。"
D.Strings[6128]="这只夜刃豹传言在暗夜精灵和他们的同盟面前很驯服，这使她成为一个更有价值的对手。猎影的猎杀路线把她从瑞恩伍德居所赶到了我们的西方，最终在那里的正西方登陆。她的皮毛是沥青一般的颜色，而她的速度也不能低估。"
D.Strings[6129]="作为灰谷猎场最强大的野兽，尖爪可以在这片大地自封的卫兵——暗夜精灵的陪伴下自由的漫步。尖爪在这里南部寻找猎物，尽情的撕裂着毫无防备的旅客。$B$B要想杀死这样一个野兽需要极大的努力，$n。我希望你在猎杀这个野兽时运气好一点！"
D.Strings[6130]="我好奇的是……温德索尔，在那个幻象中，你最终有没有活下来？我之所以这样问，是因为我可以确保你今天死定了。就是现在。"
D.Strings[6131]="龙！卫兵！卫兵！抓住这个怪物！"
D.Strings[6132]="对……卫兵们，过来帮帮你们的主人！"
D.Strings[6133]="大家请就座！比赛两分钟后开始！"
D.Strings[6134]="拉力赛将在1分钟之后开始！"
D.Strings[6135]="看$n给我们带来了什么！我们畅饮吧！"
D.Strings[6136]="你好，$c。欢迎来到我们征服灰谷的前线！如果你在找事做的话，那么你算来对地方了。我总是在寻找体格健壮的$r去为部落赢得荣誉！"
D.Strings[6137]="$n给我们带酒来了！我们狂欢吧！"
D.Strings[6138]="%s发出了嘶嘶声。"
D.Strings[6139]="这是命运吗，温德索尔？如果你是赶来赴死的，那么预言已经实现了。愿你的思想在扭曲虚空里面腐烂。干掉其余爱管闲事的家伙，我的孩子们。伯瓦尔，你是一个令人满意的傀儡。"
D.Strings[6140]="别让她逃了！"
D.Strings[6141]="你们已经失败了，凡人……再见！"
D.Strings[6142]="雷吉纳德……我……很抱歉。"
D.Strings[6143]="伯……伯瓦尔……勋章……用它……"
D.Strings[6144]="%s显得筋疲力尽！"
D.Strings[6145]="%s为拉格纳罗斯做最后一次服务……"
D.Strings[6146]="%s强迫一个火誓者爪牙爆炸！"
D.Strings[6147]="龙族用高贵的表象掩饰自己。这些石板会将她的本来面目还原的……如果我所见到的幻象都是真的，朋友，我就在这场战斗中丧命。你必须完成我没能完成的事业。你准备好了吗？我们将听你的命令前进。"
D.Strings[6148]="我准备好了，我的军队也整装待命。让我们结束这次假面舞会吧！"
D.Strings[6149]="如果你想知道碎木哨岗的商旅来往情况，我恰好就是你要找的兽人。不幸的是，我不喜欢人类。$B$B要是你想要什么的话，就快些。"
D.Strings[6150]="元素在跟我们讲话，$c。他们分享着我们必须掌握的知识以及不能泄漏的秘密。"
D.Strings[6151]="在严格的训练中，我必须除去那些学生先前所学的所有知识，以便传授新知识。我所提供的服务越来越难以完成。为此，每次训练的费用也越来越昂贵。你愿意除去你先前学习的技能吗？"
D.Strings[6152]="我该如何重置我的天赋？"
D.Strings[6153]="要是你愿意的话，除了训练之外，我还可以用自己的力量将天赋从你的头脑中抹去。我要警告你的是，你每经历一次这样的过程，执行这过程的难度就会增加一分，而且所需的费用也会随之上升。"
D.Strings[6154]="谢谢你给我自由。去碎木岗哨找我的姐妹谈谈。我……我必须找个地方休息……"
D.Strings[6155]="%s的勋章碎裂了。"
D.Strings[6156]="我没有什么可以教你的啦！无论如何，不是每个人都像你能懂这么多知识！你需要跟奥格瑞玛的诺格谈谈。"
D.Strings[6157]="狂暴者，出击！"
D.Strings[6158]="好吧，我们出去吧！"
D.Strings[6159]="谁敢攻击银翼哨站？！？"
D.Strings[6160]="银翼是我们的！"
D.Strings[6161]="去汇报说我们的前哨沦陷了。我们要留下。"
D.Strings[6162]="准备好了。银翼正在发狂呢。"
D.Strings[6163]="都准备好了吗？"
D.Strings[6164]="我不会伤害你的。我在监视野猪人并记录他们的活动。我的人民注意到了某些奇怪的事情……某种黑暗的气息从这个地区中散播出来。我是前来调查此事的，而我的发现很令人不安。$B$B似乎有一个很善于使用奥术魔法的亡灵外交官在附近。我不相信他也是被遗忘者……我认为情况比这更糟糕。"
D.Strings[6165]="真是走运。通常我必须离开窝才能找到食物。"
D.Strings[6166]="要明白你的处境，凡人！"
D.Strings[6167]="这毫无意义的行动让我很厌烦。我会从上空把你们都烧成灰！"
D.Strings[6168]="你知道的已经够危险了，但是对我来说你看起来还需要训练，$n。"
D.Strings[6169]="看起来需要再给你一次教训，凡人！"
D.Strings[6170]="你的意志不足以操纵我们控制的军队，$c。"
D.Strings[6171]="我喜欢学习更多的关于术士的知识。"
D.Strings[6172]="$n，我如何才能在大地母亲的心目中继续你的深造呢？"
D.Strings[6173]="你想学习更多的术士知识，那你还是放聪明点，在我面前表现得谦卑一些，$n。"
D.Strings[6174]="我没有时间浪费在像你这样的人身上$c。"
D.Strings[6175]="我服从安排接受进一步的训练，我的主人。"
D.Strings[6176]="从你的站姿我可以看出你不是战士。$B$B你为什么不做点安全的事，比如读书什么的。"
D.Strings[6177]="黑暗没有拥抱你这样的$c。别说废话，从我视线中消失吧！滚！"
D.Strings[6178]="恐怕你给我的份额太低了，我可不愿跟你废话了。请走吧。"
D.Strings[6179]="你不是战士……你为什么在我的训练课程中一天都坚持不下去！$B$B一个以为自己是战士的$c，哈哈！"
D.Strings[6180]="孩子，我看不出你具备战士的精神。我不会训练你这样的$c的。"
D.Strings[6181]="%s现身保护深渊之石！"
D.Strings[6182]="真可怜。如果这就是你们的最佳表现，你们俩的训练算是白费了。"
D.Strings[6183]="利斯塔，召唤亡灵俘虏。"
D.Strings[6184]="利斯塔，冲啊……憎恶！"
D.Strings[6185]="战争之王，请将你的智慧与我共享。"
D.Strings[6186]="碎手已经在黑石的大本营中安插了数名间谍。尽管信息收集的过程已经慢了下来，但是我们发现了一些不容忽略的现象。"
D.Strings[6187]="有什么发现？"
D.Strings[6188]="似乎黑龙的势力范围已经超越了燃烧平原，扩展到暴风城了！人们揭下了篡位者的面具并将他流放出境。"
D.Strings[6189]="篡位者？"
D.Strings[6190]="真的。黑龙之母运用幻象和欺诈术将自己伪装成贵族法庭的成员。更糟糕的是，眼下，她似乎已经控制了暴风城的伯瓦尔·弗塔根公爵。$B$B做出这样愚蠢的军事决定不足为奇。联盟军队最近的行动令我们头疼。现在我们知道，黑龙正试图分裂帝国——从内部分裂它。"
D.Strings[6191]="恕我直言，统帅大人--为什么不消灭他们？难道这不会巩固我们的地位吗？"
D.Strings[6192]="<萨尔笑了。>$B$B还有这么多要学的，$r。$B$B你太年轻了，记不得多年前的战争和流血。记不得我们的人民所承受的诅咒的重压。$B$B我们现在与联盟的形势很脆弱。小冲突和小规模战斗时常发生，但是仍有和平--我们的人民数千年来未有过的和平。你愿放弃这个并把我们再次投入这片混沌中去面对一个新的敌人吗？这个敌人在毁灭我们之前是不会停手的。"
D.Strings[6193]="我……我可不这样想，战争之王。"
D.Strings[6194]="不，$n，你没有。我没找你茬，但是你跟年幼的我非常相似：冲动、叛逆、思维缺乏连贯性！这些特点在我身上已经荡然无存。$B$B悲伤够了。$R，我有个任务要你完成；或许你会在执行任务过程中丧命。"
D.Strings[6195]="我活着就是为了为战争之王服务！没有你的指导，我的生活将空虚而无意义。"
D.Strings[6196]="<萨尔笑了。>$B$B注意……现在专心些，$n。黑龙的母亲，奥妮克希亚，从她在暴风城的权位上被推翻了。她已经逃到她在尘泥沼泽的窝里。$B$B她不能生活在离我们的首都这么近的地方。我们必须先发制人！$B$B我想要消灭她，$n。"
D.Strings[6197]="遵命，酋长！"
D.Strings[6198]="欢迎你，我的$g兄弟:姐妹;。如果你想接受训练，我会很乐意教你的。$B$B只要玛法里奥还在沉睡中，我们便永远是平衡的守卫者。别忘了这一点。"
D.Strings[6199]="麦兰达，你有足够的眼珠再制作一个护身符吗？我把先前那个弄丢了。"
D.Strings[6200]="我看见一些有趣的人在港口进进出出。小心，$n。你永远不清楚谁值得信任以及跟这儿发生的所有事情的缘由……"
D.Strings[6201]="你是为战歌之斧而来的吧。嗯，是时候了，$n。那箱子已经放了好长时间了。$B$B你可以随时拖走它。"
D.Strings[6202]="在他们发现我获得自由之前我们离开这儿！"
D.Strings[6203]="当心！我们正在遭受攻击！"
D.Strings[6204]="谢谢你帮助我。我知道从这里回去的路。"
D.Strings[6205]="石爪山脉在这片区域拥有许多危险的洞穴。若干冒险家愿意冒着生命的危险到这些洞穴中探险。$B$B$C，也许只要你全心全意地寻找，会找到财宝的。"
D.Strings[6206]="%s看到米莎阵亡后变得狂怒无比！"
D.Strings[6207]="我尝试把碎片复合，以使他们能再次成为一个整体，在这期间请你耐心等待。"
D.Strings[6208]="鱼肉真鲜美。你来学钓鱼的？还是来吃鱼的？呣……"
D.Strings[6209]="我需要训练，鲁玛克。"
D.Strings[6210]="对，我可以教你钓鱼。"
D.Strings[6211]="我需要训练，格瑞诺尔。"
D.Strings[6212]="是的，我能重新给遗物盖上封印，$n。"
D.Strings[6213]="请离开这个地方，$n。你对困扰我们的问题毫不知情……"
D.Strings[6214]="我到哪里可以找到魔化瑟银锭？"
D.Strings[6215]="我到哪里可以找到恢复水晶？"
D.Strings[6216]="魔化瑟银锭是一种很受欢迎的金属。你找到它的最好办法就是找个铁匠或是矿工谈谈。"
D.Strings[6217]="恢复水晶很难入手。$B$B我相信它来自安戈洛环形山，你最好去那儿看看。"
D.Strings[6218]="我们可能遇到了旱季，但是供给并不缺乏！想看看我的货物吗？"
D.Strings[6219]="我想看看你的货物，迪尔格。"
D.Strings[6220]="扎姆沙能帮你吗，$r？"
D.Strings[6221]="我需要训练，扎姆沙。"
D.Strings[6222]="我会喂养它们的，孩子。达瑞尔·瑞克努索，愿为你服务。"
D.Strings[6223]="我需要训练，达瑞尔。"
D.Strings[6224]="对污林熊怪来说，你真是个小麻烦！死吧！"
D.Strings[6225]="不！你不可能比污林熊怪更强壮的！不！！"
D.Strings[6226]="帮帮我……我的……肋骨……断啦。"
D.Strings[6227]="濒临死亡……看那光……多显赫……"
D.Strings[6228]="我……我觉得自己看见了蓝色……"
D.Strings[6229]="我得救了！谢谢你，医生！"
D.Strings[6230]="我受伤了！帮帮我！"
D.Strings[6231]="我做不到了……死亡已经迫近了……"
D.Strings[6232]="再见，残酷的世界……我今天要离开你了……再见……再见……再见……"
D.Strings[6233]="万岁！我得救了！"
D.Strings[6234]="头脑不听使唤……失去意识……死亡迫近……"
D.Strings[6235]="亲爱的，拥抱我……拥抱我……"
D.Strings[6236]="医生成功了！万岁！"
D.Strings[6237]="你没通过测试，对此我感到很遗憾。"
D.Strings[6238]="我是一个从事药学的兽人，$r。如果你是来学习的，我会尽我最大的努力教你。"
D.Strings[6239]="我需要训练，阿诺克。"
D.Strings[6240]="愿这邪恶的气息被彻底从这件神器中清除！"
D.Strings[6241]="我感觉到邪恶的气息消退了……"
D.Strings[6242]="你是来学习医疗知识的吗？"
D.Strings[6243]="我需要训练，妮萨。"
D.Strings[6244]="你为何来此，$c？"
D.Strings[6245]="我的人民，他们就像你试图修复的遗物一样支离破碎。"
D.Strings[6246]="虽说没有东西可以改变过去，时间可以治愈所有伤口。谢谢你让我看到那是可能的，$n。我祝你顺利。"
D.Strings[6247]="克尔苏加德？如果你知道这个名字，那么你肯定读过我要你去找的那本书。$B$B不幸的是，你的答案是错误的。"
D.Strings[6248]="古尔丹。这个名字在艾泽拉斯没有多少人听说过。$B$B不幸的是，答案错误。"
D.Strings[6249]="这个回答很有意思……可惜答案错误。"
D.Strings[6250]="啊， 耐奥祖。这名字不应如此轻松地说出，但是我确实要求你说出一个答案。$B$B耐奥祖是正确的答案。"
D.Strings[6251]="我的答案是克尔苏加德。"
D.Strings[6252]="我的答案是古尔丹。"
D.Strings[6253]="我的答案是基尔加丹。"
D.Strings[6254]="我的答案是耐奥祖。"
D.Strings[6255]="我的答案是伊瑟拉。"
D.Strings[6256]="啊，梦境之神伊瑟拉。"
D.Strings[6257]="我的答案是奈萨里奥。"
D.Strings[6258]="我的答案是阿莱克丝塔萨。"
D.Strings[6259]="我的答案是玛里苟斯。"
D.Strings[6260]="奈萨里奥，嗯？这是个很好的回答，是吗？"
D.Strings[6261]="阿莱克丝塔萨，生命的缚誓者。巨大的生物。"
D.Strings[6262]="玛里苟斯，是吗？"
D.Strings[6263]="你好，$c。有什么我能帮忙的吗？"
D.Strings[6264]="我想问你，$c：$B在泰坦创造的守护巨龙中，是谁后来变成了被称作死亡之翼的邪恶生物？"
D.Strings[6265]="有人找我谈话总是件高兴的事儿。事情进展如何，$c？"
D.Strings[6266]="不，回答我，$n：$B在洛丹伦天灾爆发之前，是谁变成了巫妖王？"
D.Strings[6267]="答案错误，$n。走吧。"
D.Strings[6268]="恐怕不是这样，$n。自食苦果吧。"
D.Strings[6269]="就位！"
D.Strings[6270]="为了伟大的母亲！"
D.Strings[6271]="暗夜的战士……集合！"
D.Strings[6272]="%s正在攻击旗帜！"
D.Strings[6273]="是的，你知道一些事情！如果你想学会更多的话就必须与暴风城的乔吉奥·波利罗谈谈。"
D.Strings[6274]="瑟银兄弟会懂得如何制造炎魔之王的神圣武器，但是我们缺乏人力，无法获得制造武器所需的材料。$B$B我，罗克图斯·暗契，兄弟会赋予我强大的力量，用珍贵的药方来交换从熔火之心收集的材料。$B$B给个价吧，$r。"
D.Strings[6275]="罗克图斯，哪些东西是我有权使用的。"
D.Strings[6276]="想让你的恶魔变得更强大吗？这需要花钱的，但是你来对地方啦。"
D.Strings[6277]="你不是术士而且我没时间理你。走开！"
D.Strings[6278]="让我看看你收集的魔典。"
D.Strings[6279]="你来接受训练为的是把它传递到你的宠物身上？"
D.Strings[6280]="啊朋友，我只帮助猎人和他们的宠物。"
D.Strings[6281]="将野兽的技能传授给我吧。"
D.Strings[6282]="恐惧存在于你的心中，$n。当你真正准备好面对鞭笞者沃尔沙时，就来找我谈谈。"
D.Strings[6283]="现在我们必须等待。纳迦很快就会意识到我们干了些什么。"
D.Strings[6284]="皇家药剂师协会对愚蠢的家伙可没有耐心，我也一样。或许下次我们谈到战马的时候，你会被当作是幽暗城的贵族。到那时……"
D.Strings[6285]="保持警惕，$n！"
D.Strings[6286]="或许我们能休息一下。但是在打败沃尔沙之前我绝不放弃！"
D.Strings[6287]="很抱歉$g兄弟:姐妹;，但是在确定买主是暗矛部落的贵族之前，我不会将迅猛龙卖给他的。当你证明自己是部落贵族之后，我才会把迅猛龙卖给你。"
D.Strings[6288]="你并不为我的人民所知。科多兽是强大的坐骑，它是我的人民爱心和关怀的产物；所以它不能给陌生人。在雷霆崖的长老认为你的品德高尚之前，我不能卖给你科多兽。"
D.Strings[6289]="唉$c，你不是达纳苏斯的贵族，也不是泰达希尔的上层精灵。除非你以实际行动——不仅仅是口头上的话语——证明自己的友好态度，那样的话，我会提供马匹让你挑选的。"
D.Strings[6290]="后退！小孩子不应该在这儿的！回去吧，孩子们！"
D.Strings[6291]="保持镇定。我们很快将发动奇袭。"
D.Strings[6292]="如果运气好的话，我们今天会得到几处不错的伤痕的。"
D.Strings[6293]="这些树木弄得我的长牙发痒……"
D.Strings[6294]="他们说杜瑞尔是一名勇猛的暗夜精灵。这将是一场恶战！"
D.Strings[6295]="在这之后我们会在斧头上刻下胜利的标记。"
D.Strings[6296]="保持镇静。我们不能放弃自己的阵地。"
D.Strings[6297]="胆大的约翰森？我听说塔顶的赛场主管科鲁克莱德知道他在哪儿。"
D.Strings[6298]="你在寻找约翰森？哦，我不该说太多，不过……或许你该问问塔顶的科鲁克莱德，他会告诉你……"
D.Strings[6299]="很抱歉，如果你不是暴风城中的贵族，我是不会将马匹卖给你的。这些战马是最好的，我们当然不会当它们落入敌人之手。$B$B想要证明自己不是敌人，当然……你只需赢得暴风城的信任，我就可以跟你做买卖了。"
D.Strings[6300]="现在还不行，$g小伙子:姑娘;……我是不会把强大的战羊随意卖给其他人的，你必须首先证明自己是铁炉堡矮人的忠实盟友才行。一旦我确认你在铁炉堡有着显赫的地位，那我会很乐意让你看看我出售的多种战羊的。"
D.Strings[6301]="呃……很抱歉，我真的不太了解你。我是说，作为公认的机械陆行鸟经销商，我只能跟高贵的侏儒做生意。要是你是诺莫瑞根的侏儒贵族，我会很高兴地为你提供服务的。"
D.Strings[6302]="在我教你骑术之前，你必须达到被铁炉堡的矮人所崇拜的声望才行，$c。"
D.Strings[6303]="在我教你骑术之前，你必须达到被幽暗城的被遗忘者所崇拜的声望才行，$c。"
D.Strings[6304]="在我教你骑术之前，你必须达到被诺莫瑞根逃亡侏儒所崇拜的声望才行，$c。"
D.Strings[6305]="在我教你骑术之前，你必须达到被暴风城的人类所崇拜的声望才行，$c。"
D.Strings[6306]="在我教你骑术之前，你必须达到被达纳苏斯的暗夜精灵所崇拜的声望才行，$c。"
D.Strings[6307]="在我教你骑术之前，你必须达到被奥格瑞玛的兽人所崇拜的声望才行，$c。"
D.Strings[6308]="在我教你骑术之前，你必须达到被雷霆崖的牛头人所崇拜的声望才行，$c。"
D.Strings[6309]="在我教你骑术之前，你必须达到被暗矛部族的巨魔所崇拜的声望才行，$c。"
D.Strings[6310]="走了一半路了……"
D.Strings[6311]="我不认为你具有掌握传送门魔法所必需的潜质。"
D.Strings[6312]="请教教我吧。"
D.Strings[6313]="老鼠泛滥成灾啦！朋友，帮助一个可怜的海盗离开这儿！"
D.Strings[6314]="你参与矿道地铁的保洁工作了吗？"
D.Strings[6315]="别挤我！"
D.Strings[6316]="你的力量让我更加强大，$n！"
D.Strings[6317]="伙计，伐木机就藏在这些箱子中。祝你好运！"
D.Strings[6318]="我名叫蒙提，老鼠是我的玩物。"
D.Strings[6319]="我要去寻找松鼠了，蒙提。"
D.Strings[6320]="进到盒子里来。一个接一个地进去。"
D.Strings[6321]="胜利者！我们这里将会有一个胜者！"
D.Strings[6322]="这些栖息在这片荒地上的科多兽的兽皮最为坚韧。"
D.Strings[6323]="你的技巧已经超过我了，年轻人。去找尤纳，她在雷霆崖的中央高地上有一家商店。她能给你你需要的指导。"
D.Strings[6324]="很抱歉，我不能再多收学生啦。去雷霆崖找玛克吧。他会教你一些基本技能的。"
D.Strings[6325]="你首先必须向我证明你自己，然后我就会训练你。"
D.Strings[6326]="你已经准备好学习科多兽制皮的要点。让我们开始吧……"
D.Strings[6327]="在光明与黑暗之间，还有阴影……而那些阴影有些你未曾见过的力量。"
D.Strings[6328]="你在卡兹莫丹不会找到更好的老鼠肉烧烤店的！"
D.Strings[6329]="我想做些买卖，尼普希。"
D.Strings[6330]="你看起来能用一些机件，$g小伙子:女士;。你应该上地铁去拜访我的兄弟蒙提，他在铁炉堡矿道地铁库房。我肯定他有些事情是你能做的。"
D.Strings[6331]="陌生人，小心身后。"
D.Strings[6332]="你并未得到拉文霍德公爵的认可，$c。"
D.Strings[6333]="鲁莽的家伙。拉文霍德公爵可不喜欢这样的人。"
D.Strings[6334]="你好，$c。你找法拉德谈过了吗？"
D.Strings[6335]="辛迪加工会的成员都是些平庸的家伙——缺乏组织性、技能拙劣、懒惰……"
D.Strings[6336]="你真的变得狡猾多了，$n。"
D.Strings[6337]="很荣幸再次看到你，$n。"
D.Strings[6338]="我想之前西蒙尼找过你，$n。你跟她谈过了吗？"
D.Strings[6339]="$n$g先生:女士;！康恩大人一直在打听你的事情，也许你该去见见他了！"
D.Strings[6340]="你的出现让我们精神紧张，$n。"
D.Strings[6341]="拉文霍德庄园流传着你的英雄事迹，$n。"
D.Strings[6342]="我不适合这次谈话，$G主人:女主人;。"
D.Strings[6343]="能为你服务是我的梦想，$G主人:女主人;$n。换句话说，你认为我值得得到这些东西吗……"
D.Strings[6344]="整个庄园都在议论你的到来，$G主人:女主人;$n。对你的光临，我们感到无比荣幸。"
D.Strings[6345]="你敢踏入拉文霍德庄园，可怜虫？"
D.Strings[6346]="不借助刀具或是毒药离开这儿就算完成任务。"
D.Strings[6347]="你一直进行得不错，$n。我听到好消息了……"
D.Strings[6348]="你该与温斯顿谈谈。我听说他在寻找一个与你有相同技能的潜行者。"
D.Strings[6349]="不可思议。太不可思议了。你给了我们启迪，$n。"
D.Strings[6350]="我真羡慕你，$n。你做得太出色了。"
D.Strings[6351]="你的机会来了，$n。康恩在等……"
D.Strings[6352]="想想吧，有一天你也许可以成为传说中故事的主人公！"
D.Strings[6353]="当我听到你的豪言壮语时，我像小孩子一样哭了起来。拉文霍德有你这样的学徒真好。"
D.Strings[6354]="要是我无须对拉文霍德公爵尽职的话，我将跟随你到世界的尽头，$G主人:女主人;$n。你既优雅又聪明。"
D.Strings[6355]="愿月神与你同在，$c。月神殿已经来帮助奥伯丁饱受煎熬的公民了。"
D.Strings[6356]="我是个测试用的灵魂医者。"
D.Strings[6357]="你为什么要杀我，$n？"
D.Strings[6358]="苏亚米在旅馆前面。去吧，我正忙着呢。"
D.Strings[6359]="要照料宠物吗？你得确保它的清洁！去旅馆前面找苏亚米吧。"
D.Strings[6360]="到荣誉山谷去并在马厩附近找到克苏卡。"
D.Strings[6361]="克苏卡会把你多余的宠物圈养起来的。到荣誉山谷的竞技场和猎人大厅之间的畜栏里找到他，现在走吧！"
D.Strings[6362]="只有傻子才会在不知不觉中进入贼窝。他是不可能出来的了……"
D.Strings[6363]="啊是的，你必须找到希克瓦。我记得我最后一次见她时她在旅馆前面站着。"
D.Strings[6364]="希克瓦能在你需要的时候帮你照看宠物。去旅馆前面找她吧。"
D.Strings[6365]=S[2792]
D.Strings[6366]="你需要布尔鲁格的帮助。他在旅馆和雷霆崖银行间较低的山上。"
D.Strings[6367]="你对自己的宠物伙伴表现出的关爱之情是值得赞扬的。矮山上的布尔鲁格能帮助你照看宠物。他居住在银行和旅馆之间的地方，去找他吧。"
D.Strings[6368]="说也奇怪，兽栏管理员莫加努斯就在马厩外面。"
D.Strings[6369]="你不算太聪明吧？嗯，如果我是兽栏管理员的话，我应该是在马厩附近吧？去那边找莫加努斯吧。"
D.Strings[6370]="安雅·玛尔雷在贸易区上层的旅馆中。"
D.Strings[6371]="阿拉辛是个值得信赖的人，让他来悉心照料你的任何宠物。他就住在猎人们聚集的塞纳里奥区。"
D.Strings[6372]="数百年以来阿拉辛一直很关心我们猎人视作朋友的动物。他对动物的关心被周围的猎人所追随。如果你也来向他请教，那么就到塞纳里奥区找他。"
D.Strings[6373]="我们共同构成了一个巨大的拼图，$n。跟你一样，很多人都在进行小块拼图的整合工作。$B$B或许还有更强大的人正在将这些人当作拼图来玩。"
D.Strings[6374]="啊，友善的瑟里亚迪。在她的庇护下，所有动物都很安全。你可以在多兰纳尔的旅馆外找到她。"
D.Strings[6375]="你寻找一个喜欢动物的人？那么你应该到多兰纳尔旅馆的外面寻找瑟里亚迪。她就是你找的那个人。"
D.Strings[6376]="好心的旅店老板艾玛，她现在已经照顾当地的动物好些年了。我敢肯定她会很高兴照顾你给的任何动物。你可以在狮王之傲旅店的外面找到她。"
D.Strings[6377]="旅店老板艾玛照料着这周围的所有动物。要是你需要跟她交谈的话，就去狮王之傲旅店外面找她。"
D.Strings[6378]="矮人区的耶诺瓦·石盾是你要找的人。在猎人接受她父亲的训练时，她帮着照看猎人的宠物。"
D.Strings[6379]="如果你需要将宠物关在屋内，以便训练另一只宠物的话，就去矮人区找耶诺瓦·石盾谈谈。"
D.Strings[6380]="$g小伙子:姑娘;，你可以去卡拉诺斯雷酒酿制厂外找谢尔比·石火。她会好好照顾你的宠物的。"
D.Strings[6381]="谢尔比·石火帮当地猎人看管宠物。如果你想让她帮你照看宠物的话，就去雷酒酿制厂找她吧。"
D.Strings[6382]="乌布雷克·火拳总是极其认真地照顾动物。如果你想让他帮你照看宠物的话，就去武器大厅找他吧，他通常跟那些猎人在一起。"
D.Strings[6383]="你可以在武器大厅找到我们的常驻马厩管理人乌布雷克·火拳。他将替你喂养和照料宠物。"
D.Strings[6384]="你以为你赢了？可能你需要另一堂痛苦的课程！"
D.Strings[6385]="帮帮我！守卫！就要踩到我啦！"
D.Strings[6386]="我给你带来一些东西，$n。它们看起来挺重要的。"
D.Strings[6387]="请问，我能拿走它吗？"
D.Strings[6388]="欢迎来到军情七处总部，$n。"
D.Strings[6389]="$n，这是今天早上送来给你的。"
D.Strings[6390]="拉文霍德的信使今天早上将这封信交给了我。这是写给你的，$n。"
D.Strings[6391]="振作起来！疼痛会消失的，$g女人喜欢有伤疤的男人:男人喜欢有伤疤的女人;！"
D.Strings[6392]="我需要帮助。"
D.Strings[6393]="让敌人见识见识你的力量，我们会取胜的！"
D.Strings[6394]="这将是一场艰难的战事，$n。跟我来吧！"
D.Strings[6395]="这是火盆，$n。熄灭它。沃尔沙是一头野兽，不值得任何人赞扬！"
D.Strings[6396]="呸！不在这儿。让我想想上次把它放在哪儿了……"
D.Strings[6397]="我对你表示最深的感激，谢谢你。"
D.Strings[6398]="我把勇士的资料放在哪儿了？"
D.Strings[6399]="相当引人入胜的故事。现在我知道为什么那本书上积了那么多灰尘了。"
D.Strings[6400]="这么多的书架，时间却如此紧迫……"
D.Strings[6401]="我该告诉杜威关于符号系统的一些知识，让他更好地摆放这些书。"
D.Strings[6402]="地精写的关于侏儒的军事胜利的书……而所有的纸张都是空白的。数字。"
D.Strings[6403]="我会再巡视这片地区一会儿并确保一切安全。"
D.Strings[6404]="请回到佐拉姆加前哨站，向战歌信使汇报我们的成功。"
D.Strings[6405]="你确信自己已准备就绪？要是没有你的帮助，我们一定会失败的。"
D.Strings[6406]="我感到那头巨大的野兽正在逼近……"
D.Strings[6407]="看水面！"
D.Strings[6408]="你们这些渣滓居然想要挑战我？你们会为你们的傲慢付出代价的！"
D.Strings[6409]="什么事，$c？你在汇报吗？"
D.Strings[6410]="你们不是烈焰之王的敌人！出现吧，火焰的奴仆！你们的主人在召唤你们！"
D.Strings[6411]="士兵们，干掉他们！"
D.Strings[6412]="将他们逼回基地去！将战场上的联盟士兵统统杀死！"
D.Strings[6413]="团结在中尉和指挥官身边！保护我们的基地！"
D.Strings[6414]="管理者埃克索图斯被激活。"
D.Strings[6415]="谁控制着冷齿矿洞？"
D.Strings[6416]="冷齿矿洞为狗头人所有。"
D.Strings[6417]="冷齿矿洞为联盟所有。"
D.Strings[6418]="冷齿矿洞为部落所有。"
D.Strings[6419]="部落领地中的冷齿矿洞就在霜狼墓地以北的山脉脚下。$B$B它现在被联盟控制着。"
D.Strings[6420]="部落领地中的冷齿矿洞就在霜狼墓地以北的山脉脚下。$B$B它现在被部落控制着。"
D.Strings[6421]="部落领地中的冷齿矿洞就在霜狼墓地以北的山脉脚下。$B$B它现在被狗头人控制着。"
D.Strings[6422]="谁控制着深铁矿洞？"
D.Strings[6423]="联盟领地中的深铁矿洞就在雷矛墓地北边。$B$B它现在被联盟控制着。"
D.Strings[6424]="联盟领地中的深铁矿洞就在雷矛墓地北边。$B$B它现在被部落控制着。"
D.Strings[6425]="联盟领地中的深铁矿洞就在雷矛墓地北边。$B$B它现在被穴居人控制着。"
D.Strings[6426]="这座纪念碑是用于缅怀在暴风城保卫战中牺牲的勇士。我们的人民经受了难以想象的痛苦才得以恢复自由，重新掌握自己的命运。我们将永远铭记那些在第一次兽人战争中牺牲的同胞。"
D.Strings[6427]="深铁矿洞为联盟所有。"
D.Strings[6428]="深铁矿洞为部落所有。"
D.Strings[6429]="深铁矿洞为穴居人所有。"
D.Strings[6430]="联盟占领了冷齿矿洞！矿洞中的物资可以为他们提供增援了！"
D.Strings[6431]="联盟夺取了深铁矿洞！矿洞中的物资可以为他们提供增援了！"
D.Strings[6432]="部落占领了冷齿矿洞！矿洞中的物资可以为他们提供增援了！"
D.Strings[6433]="部落占领了深铁矿洞！矿洞中的物资可以为他们提供增援了！"
D.Strings[6434]="穴居人重新占领了深铁矿洞！"
D.Strings[6435]="狗头人重新占领了冷齿矿洞！"
D.Strings[6436]="奥特兰克山谷中的作战物资总是非常缺乏。"
D.Strings[6437]="我的供给需求得到了满足。"
D.Strings[6438]="抓住我！"
D.Strings[6439]="掩护我，士兵！我必须返回基地并让空军做好战斗准备！"
D.Strings[6440]="哈哈！成功了！"
D.Strings[6441]="别浪费时间，士兵。我必须马上返回基地！掩护我！"
D.Strings[6442]="赶快！"
D.Strings[6443]="古斯？杰斯托？他们……迫降了吗？？南海镇外的海域？？"
D.Strings[6444]="我得回到基地去。摧毁那些想要阻挡我的家伙！保护我！走吧！"
D.Strings[6445]="我来啦，弱小的联盟！"
D.Strings[6446]="干得好，士兵。现在让我们发泄对他们的忿怒！"
D.Strings[6447]="%s发出威胁的叫声。"
D.Strings[6448]="霜狼的战士们，来帮助我！是时候让他们感受元素的狂怒了！"
D.Strings[6449]="这次探险将耗费大量军事物资。"
D.Strings[6450]="谁敢召唤冰雪之王洛克霍拉？"
D.Strings[6451]="就算流尽一千名联盟士兵的鲜血……也不能战胜强大的冰雪之王！"
D.Strings[6452]="让我结束你的痛苦吧。让你的精华和洛克霍拉一起冻结！"
D.Strings[6453]="我们敌人的鲜血会洒落疆场的。伟大的元素会回应我们的呼唤并碾碎所有阻挡我们前进的东西。"
D.Strings[6454]="%s发出咯咯的笑声。"
D.Strings[6455]="冰雪之王会吞噬整个的联盟军队！"
D.Strings[6456]="在扭曲虚空是听不到任何回应的。"
D.Strings[6457]="当血深入雪地时仔细看着，孩子。元素会附到我们身上的！"
D.Strings[6458]="结束了！冰雪之王来了！向部落的力量敬礼，蠢货！"
D.Strings[6459]="忘了它吧！"
D.Strings[6460]="这问题根本不值得回答。"
D.Strings[6461]="那是个玩笑吧？"
D.Strings[6462]="除非你真有问题要问，否则就别召唤我，好吗？"
D.Strings[6463]="%s被激怒了！"
D.Strings[6464]="把你的能量引导到祭坛里！"
D.Strings[6465]="太可怕了。在一次空袭中，我们的三个顶级枪手倒在了联盟的领地上，没人知道他们是生是死！$B$B这对我们的空中部队是个可怕的冲击。"
D.Strings[6466]="马丁，我需要飞离这儿。"
D.Strings[6467]="干得好，士兵。我需要回到大本营！你愿意掩护我吗？"
D.Strings[6468]="我来支援你，古斯。"
D.Strings[6469]="你来的真是时候。怎么耽搁了这么久？啊，没关系。掩护我，士兵。我必须返回基地！"
D.Strings[6470]="你可以相信我，杰斯托。"
D.Strings[6471]="你不属于这些花园。你的肉身将会滋养我们美丽的作品！"
D.Strings[6472]="花园绝不能被弄脏！你死定了！"
D.Strings[6473]="指挥官，还需要多少血？"
D.Strings[6474]="还有很多工作要做，$n！继续消灭我们的敌人！"
D.Strings[6475]="指挥官，我们必须靠拢点。我能感觉到那些元素正在骚动。"
D.Strings[6476]="是的，$n。元素很活跃。很快，我们就会将他们的能量释放到我们的敌人身上。他们会被彻底击垮的！"
D.Strings[6477]="指挥官，我感觉我们中蕴藏着一股强大的力量。准备好魔法了吗？"
D.Strings[6478]="我已经做过接触了，$n。那是冰雪之王洛克霍拉。他认为我们的事业很有价值--我们给大地的祭品十分充足。他很快就来了……做好准备。"
D.Strings[6479]="我需要一些增援来带我安全地飞离这儿，返回基地。"
D.Strings[6480]="为你效劳！"
D.Strings[6481]="离开这神圣的地方，否则你会丧命！"
D.Strings[6482]="为了军团！为了基尔加丹！"
D.Strings[6483]="卡扎克是至高无上的！"
D.Strings[6484]="抓着槲寄生放到$g他的:她的;头上"
D.Strings[6485]="日记中似乎记载了关于贸易、买主和其它商业事务的信息。"
D.Strings[6486]="绝不要直视指挥官的眼睛。"
D.Strings[6487]="我们直接受命于凯恩，$r。不要干预指挥官的工作。"
D.Strings[6488]="萨满指挥官可不能小瞧，$r。"
D.Strings[6489]="很快，洛克霍拉就会出现……很快……非常，非常快……"
D.Strings[6490]="你继续翻阅这本日志寻找任何可以帮你找到那个被盗箱子的消息。$B$B到书的最后几页, 你可以在书页的边上看到詹姆士用红色铅笔做的标记。上面写着, “石碑湖附近的老房子……豺狼人当保镖会很出色。”$B$B没理由这就是箱子的所在暗示, 但好象又没有任何其它的线索。"
D.Strings[6491]="空军部队整装待发，$n。你必须带上火炬，把它放在战场中心的东部环形山中。在空军部队进行定位时，你必须好好保护火炬！"
D.Strings[6492]="**确认目标锁定。空军单位突击。空中突袭就绪。**"
D.Strings[6493]="**收到。确认空军目标锁定。准备就绪。倒计时60秒。**"
D.Strings[6494]="**定位系统被毁。目标锁定丢失。终止行动，终止行动。**"
D.Strings[6495]="%s发出了尖锐的叫声。"
D.Strings[6496]="我是水元素公爵海达克西斯。你不是元素生物的一员，所以你不明白我们的困境，但是或许我们可以达成一项对双方都有益处的协议……"
D.Strings[6497]="$n，见到你真好。我们与其它的元素之间的战斗正酣，但是你的参与会确保我们的胜利。"
D.Strings[6498]="我需要一瓶水之精萃，海达克西斯，因为我要去熔火之心毁掉炎魔之王的符文。"
D.Strings[6499]="我将把火炬安全带到环形山，古斯。我是值得信赖的！"
D.Strings[6500]="舰队整装待命，$n。你必须带着这个信号灯并把它放置在中央战区西部的凹地里。保护信号灯不被攻击，直到舰队能够锁定它的坐标！"
D.Strings[6501]="现在是你证明自己实力的时候了，$n。带上这个信号灯，将它插在雪落墓地的正中心。在我的空军赶到之前好好保护它。$B$B<穆维里克敬礼。>"
D.Strings[6502]="我要放置火炬了，穆维。把火炬给我。"
D.Strings[6503]="啊哈！穆维里克的舰队准备好啦。所有体格健壮的部落士兵都需要一个灯塔，我们必须要尽最大努力建造一个，以便进行准确的空中袭击。"
D.Strings[6504]="战马现在准备好了！部落的战士们，我需要你们的帮助。"
D.Strings[6505]="杰斯托的骑士准备好了！部落的战士们，汇报你们的工作！"
D.Strings[6506]="%s倾巢而动，保护巢穴！"
D.Strings[6507]="大地之母日夜监视着我们。让这火焰照亮我们的身体和灵魂吧，让我们想起尊敬的祖先，他们一直都在我们身边，指导我们前行。"
D.Strings[6508]="我想重新学习制皮的技能。"
D.Strings[6509]="士兵们，别对这些野蛮的家伙抱有仁慈之心！他们是不会对你手下留情的！"
D.Strings[6510]="把你的军队撤退，修士，我答应让你速死！"
D.Strings[6511]="士兵们，团结在中尉和指挥官周围！阻止那些野蛮的家伙！"
D.Strings[6512]="士兵们，让敌人见识见识你们的决心！用武器粉碎他们！"
D.Strings[6513]="为了国王！把他们顶回去，士兵们！"
D.Strings[6514]="你们这些野蛮的家伙，投降吧，我们会留下你的小命的！放下武器！"
D.Strings[6515]="发动地面攻击需要大量军需物资！"
D.Strings[6516]="$n，你还在等什么？去征战平原找指挥官特拉瓦雷，将攻击指令交给他。一旦他得到指令，他和他的军队就能发动对部落的攻击，不留活口！"
D.Strings[6517]="给我定单！我会将它们交给征战平原的特拉瓦雷。"
D.Strings[6518]="这眼睛能看见其视线范围内的一切事物，$c。你想看什么？"
D.Strings[6519]="命令已经下达！行动，给他们点颜色瞧瞧！"
D.Strings[6520]="谢谢你，$n。我立即动员人民！"
D.Strings[6521]="我想看看我的敌人，雷松。将他们带过来。"
D.Strings[6522]="带上它！一旦眼球的力量减弱，就回到我这儿来。"
D.Strings[6523]="如果你想在塞纳里奥议会中找寻某些档案的话，我就是那个你要交谈的人。你首先要知道要寻找的确切信息，那样我才能帮你。$B$B看看那个，真是光彩夺目呀！"
D.Strings[6524]="别聆听来自世界的心声——答案就在你心中，你知道真相的。"
D.Strings[6525]="死者在这片荒地长眠，$c。我们必须小心，别惊动他们。"
D.Strings[6526]="这眼睛的力量是不容置疑的，雷松，但是它还能做什么呢？"
D.Strings[6527]="你仅仅只是开始看到眼的力量，$c。如果你想增强眼的力量，那么必须完成一项任务。"
D.Strings[6528]="这次任务是什么?"
D.Strings[6529]="带上这根火炬，前往敌人的基地。将火炬插在敌人主要据点的庭院中心。在眼球追踪到火炬的位置之前，好好保护火炬。$B$B一旦你完成这件事，我们就能看见敌人在基地之外的所有活动。$B$B你愿意接受这项任务吗？"
D.Strings[6530]="$n，你准备好完成终极任务了。刻在熔火之心地面上的炽热的符文是通向火海的导管,它们的存在既是对我们的侵犯，又是炎魔之王的力量源泉。必须把它们扑灭！$B$B要熄灭符文，拿一小瓶水之精华。把它倒在符文上,火焰就会熄灭,这会使其变得毫无用处并能削弱我们的敌人！"
D.Strings[6531]="欢迎来到幽暗城公会登记处。你需要什么帮助么？"
D.Strings[6532]="欢迎来到塞纳里奥议会，$c。我要怎么帮你呢？"
D.Strings[6533]="雷松，我需要占卜瞄准镜查看占卜之球。"
D.Strings[6534]="跟海达克西斯公爵交谈。"
D.Strings[6535]="你跟我没有关系，小家伙。"
D.Strings[6536]="闭上你的脏嘴！也只有海达克西斯公爵才受得了你。"
D.Strings[6537]="你好，小伙计。你跟水元素之王有关系吗？"
D.Strings[6538]="关于你的英雄事迹已经流传开来。我们没有听说过你的名字，$n。"
D.Strings[6539]="你已经把我们的敌人当成了你自己的敌人。我会很高兴能与你分享水的伟大。"
D.Strings[6540]="或许你能告诉我你的一些事情，$n。我非常想听听。"
D.Strings[6541]="海达克西斯公爵赞扬你。我的水就是你的水，朋友。"
D.Strings[6542]="当你下次去熔火之心时，请为我杀死一个火焰之王，行吗？"
D.Strings[6543]="升级到经验丰富的士兵！"
D.Strings[6544]="升级到老兵！"
D.Strings[6545]="你已经找到眼珠了。$B$B<指挥官雷尔松咧嘴笑着。>$B$B好吧，把它给我！"
D.Strings[6546]="带上它！跟其价值相比，这东西也许会带来更多的麻烦。"
D.Strings[6547]="必须修复全视之眼！"
D.Strings[6548]="升级到勇士！"
D.Strings[6549]="我们回到你的基地吧！"
D.Strings[6550]="我很感激你，$c。或许我对你的目标有所帮助。"
D.Strings[6551]="当这些巨魔将我击倒，并将我拖到洞穴深处时，我便开始搜寻原料，用于制作我最后一项也是最好的一项发明——便携式远程遥控伐木机。$B$B将我送到安全地带，我会帮助你的，$r。"
D.Strings[6552]="走吧，地精！"
D.Strings[6553]="这片土地被污染了。必须召唤伊弗斯。"
D.Strings[6554]="卡尔·雷矛的战士，帮助并保护我们！森林之王已经许诺要保护我们。大门现在必须被打开了！"
D.Strings[6555]="来，兄弟。"
D.Strings[6556]="如果森林之王要来，我们必须集中思想于召唤法阵！我们需要赶紧！集中精力！"
D.Strings[6557]="邪恶，太邪恶了，你们这些凡人！森?在哭泣，元素的力量在毁灭面前颤抖。伊弗斯必须把你们从这世上清除！"
D.Strings[6558]="我是来铲平你的基地的，霜狼氏族。你们的背叛将受到伊弗斯的惩罚！"
D.Strings[6559]="强大的古树，出现吧！"
D.Strings[6560]="你们的根据地已经丧失了！生命将因它化为废墟而延续！"
D.Strings[6561]="你们的根据地已经丧失了，渺小的人类！"
D.Strings[6562]="经验丰富的士兵已经离开战场。我们需要更多士兵！"
D.Strings[6563]="老兵部队已经离开战场。我们需要更多的士兵！"
D.Strings[6564]="我们的勇士军队已经离开战场。我们需要更多的军需！"
D.Strings[6565]="经验丰富的部队已经参战！"
D.Strings[6566]="作战经验丰富的老兵参战了！"
D.Strings[6567]="勇士部队正开入战斗！"
D.Strings[6568]="我们奉命从达纳苏斯来到这儿，帮助身处患难的卡尔·雷矛。"
D.Strings[6569]="大德鲁伊相信，一旦森林之王伊弗斯意识到山谷中的破坏性力量，他就会出现的。"
D.Strings[6570]="让伊弗斯来裁决这些暴行吧。"
D.Strings[6571]="我的信念指引着我的行动，$r。我知道伊弗斯会来的。"
D.Strings[6572]="老兵已经离开战场。我们需要更多的士兵！"
D.Strings[6573]="经验丰富的部队已经接管了防御工作！"
D.Strings[6574]="老兵已经离开战场！"
D.Strings[6575]="我们的勇士军队已经装备就绪！联盟，小心了！"
D.Strings[6576]="你跟大德鲁伊伊弗斯联系上了吗？"
D.Strings[6577]="我迷失在梦里了。我感觉到了他的生命力，但是我的力量还不够强大，无法进行沟通。"
D.Strings[6578]="大德鲁伊，空气中充满活力。森林之王的情况怎么样？"
D.Strings[6579]="是的。$n。我已经查到了森林之王的位置。我们必须加倍努力！需要更多的水晶！"
D.Strings[6580]="森林剧烈震动起来！飓风咆哮！森林之王要来了吗？"
D.Strings[6581]="森林之王已经知晓了这个山谷的毁灭，$n。很快我们就要到召唤法阵去了。做好准备！"
D.Strings[6582]="我被穆维里克这个鲁莽的蠢货击中了。我担心要是我无法回到基地中去的话，一切都要玩完了！必须阻止穆维里克和他的飞行中队！"
D.Strings[6583]="我来支援你，艾克曼。快走！"
D.Strings[6584]="真不敢相信……我在中央非军事区执行例行侦察任务时，事情变得一团糟。我看见部落中校穆维里克击倒了艾克曼和斯里多尔！我发怒了，冲出队伍将穆维里克打倒在地。不幸的是，他在倒下之前击中了我的狮鹫，我也随之跌下。我被这些野蛮的家伙抓住啦。$B$B我必须返回基地！帮帮我！"
D.Strings[6585]="我来掩护你，维波里。快点行动吧！"
D.Strings[6586]="当我的狮鹫坠落时，我听到了他们嘲弄的笑声，$c。$B$B“斯里多尔， 你太差劲了！”他们大声嚷道。$B$B没有人敢对斯里多尔那样说话！帮我离开这里，我会让他们知道我的厉害！"
D.Strings[6587]="我来支援你了，斯里多尔，但说实话，你真是太臭了。快冲个澡，伙计。"
D.Strings[6588]="掩护我，我在趁机逃跑！"
D.Strings[6589]="我们没时间浪费了。路途遥远！保护我！"
D.Strings[6590]="让我尽量接近基地，这样我才能使用传送技能！"
D.Strings[6591]="你走过头啦！到营地来见我！"
D.Strings[6592]="你完蛋了，穆维!"
D.Strings[6593]="我在此有命令从中场进攻联盟军队。我需要有人把它们带到攻击指挥那里。"
D.Strings[6594]="我们在奥特兰克山谷发动的战斗冷酷而血腥。太完美了。"
D.Strings[6595]="是的，我会将这些订单交给霜狼突击队队长的！"
D.Strings[6596]="这片森林容易使人迷路！要小心。"
D.Strings[6597]="储存下来的物资都给你和你的家属！"
D.Strings[6598]="这是刚从农场带来的新鲜货--这是烟林牧场的健康食品！"
D.Strings[6599]="现在是廉价货上市的时候！啦啦啦啦！"
D.Strings[6600]="尽情享受冬幕节吧！品尝来自烟林牧场的盛宴！"
D.Strings[6601]="请告诉冬天爷爷是什么秘密让你想要得到冬幕！"
D.Strings[6602]="别花钱购买那些铃当！为了你的冬幕盛宴，把烟林牧场买下吧！"
D.Strings[6603]="要是我有栗子的话，你最好相信我会将它们烤熟吃掉的。嗯！"
D.Strings[6604]="在假期里不要忘记储备包装纸！没什么能比包装精美的护甲和武器一样让你的朋友和家人感受到冬幕节的温馨快乐！"
D.Strings[6605]="让我看看你携带的食物。"
D.Strings[6606]="%s正在启动。还剩60秒。"
D.Strings[6607]="%s已启动。狮鹫准备就绪。"
D.Strings[6608]="%s被摧毁了！空军无法确认袭击点。行动中断。"
D.Strings[6609]="雷矛士兵，过来帮帮我！必须插好火炬。"
D.Strings[6610]="注意！你需要带上这根火炬，将它插在中央墓地！要好好保护它，以便我的狮鹫能进行追踪。$B$B如果我的狮鹫能准确定位的话，穆维和他的手下会感到耻辱的！"
D.Strings[6611]="我是你的人。给我火炬！"
D.Strings[6612]="我准备飞行了！士兵们，过来帮忙！"
D.Strings[6613]="$n！你总算来了！$B$B你必须带着这个信号灯并把它放置在中心战场东部的凹地中。当信号灯指示出坐标后，我的小伙子们就会进攻！"
D.Strings[6614]="给我信号灯，斯里多尔！还有，你还是很臭！"
D.Strings[6615]="他们的精神恢复了！狮鹫已经准备好作战了！来吧，战士们！到我这儿来！"
D.Strings[6616]="狮鹫准备袭击了，$n！你必须带上这根火炬，将它插在战场中心的西环形山。$B$B去吧，胜利是属于我们的！"
D.Strings[6617]="我准备好了，维波里！给我一个信号。"
D.Strings[6618]="我们掌握了冰斧的智慧，$n。如你所愿，他的力量将在短期内为你所用。"
D.Strings[6619]="赐予我冰斧的智慧！"
D.Strings[6620]="我们的军队不能升级，军需不够，无法升级。"
D.Strings[6621]="我们的军队已经升级到经验丰富的军队，但是我没有足够的军需升级到老兵。"
D.Strings[6622]="我有足够的军需将我们的军队升级到老兵。"
D.Strings[6623]="我有足够的军需将我们的军队升级到勇士。"
D.Strings[6624]="我们的军队已经升级到勇士，但是我仍需要收集更多的军需。"
D.Strings[6625]="我不能再存储物资了。我的背包都满了！"
D.Strings[6626]="到这儿是学习如何使用新武器，还是来浪费我时间的？"
D.Strings[6627]="我想进行一些武器方面的训练"
D.Strings[6628]="其他的武器大师能教给我什么呢？"
D.Strings[6629]="你想要学习哪种武器技能？"
D.Strings[6630]="谁控制着雷矛墓地？"
D.Strings[6631]="穿过丹巴达尔以东的桥梁，雷矛墓地就在群山之中。$B$B联盟控制着这片土地。"
D.Strings[6632]="穿过丹巴达尔以东的桥梁，雷矛墓地就在群山之中。$B$B部落控制着这片土地。"
D.Strings[6633]="谁控制着雪落墓地？"
D.Strings[6634]="雪落墓地就在冰斧要塞以东的征战平原的高山顶部。$B$B联盟控制着这片土地。"
D.Strings[6635]="雪落墓地就在冰斧要塞以东的征战平原的高山顶部。$B$B部落控制着这片土地。"
D.Strings[6636]="谁控制着霜狼墓地？"
D.Strings[6637]="霜狼墓地就在离霜狼村北面不远的地方。$B$B联盟控制着这片土地。"
D.Strings[6638]="霜狼墓地就在离霜狼村北面不远的地方。$B$B部落控制着这片土地。"
D.Strings[6639]="霜狼墓地为联盟所有。"
D.Strings[6640]="霜狼墓地为部落所有。"
D.Strings[6641]="雪落墓地为联盟所有。"
D.Strings[6642]="雪落墓地为部落所有。"
D.Strings[6643]="祝你过一个神奇的冬幕节，小$G伙子:姑娘;！好孩子在任何烟林牧场小卖部都有特别优惠的哦。"
D.Strings[6644]="这轮结束后冬天爷爷会做什么呢，我有一个很好的主意。我在包里有一瓶冬幕啤酒，而且我想喝光它。"
D.Strings[6645]="不……你不能坐在我的膝盖上。"
D.Strings[6646]="是的，当然，去告诉冬天爷爷你都想从这个冬幕中得到什么。$B$B赶紧些。"
D.Strings[6647]="雷矛一族不会对任何人俯首称臣的，特别是部落！"
D.Strings[6648]="你的攻击太微弱了！去找些兔子练习一下，当你强壮些后再回来找我。"
D.Strings[6649]="你这样的乌合之众是不可能打倒我的！"
D.Strings[6650]="我们一定会完成使命的！"
D.Strings[6651]="联盟会胜利的！"
D.Strings[6652]="你不能击败霜狼部落！"
D.Strings[6653]="你的精神很虚弱，你的打击更弱！"
D.Strings[6654]="我想你的进攻因为寒冷减弱了！"
D.Strings[6655]="如果你不自动离开奥特兰克山谷，霜狼会强迫你离开的！"
D.Strings[6656]="你不是部落的力量的对手！"
D.Strings[6657]="你会在今天见到你的祖先的！"
D.Strings[6658]="%s扇动翅膀的声音从远处传来。"
D.Strings[6659]="我的！我的！我的！吉兹洛克是这片领域的统治者！你绝对不能泄漏我的行踪！"
D.Strings[6660]="丹巴达尔在部落的最后一次进攻中给了我们狠狠一击！我们需要物资重建基地！"
D.Strings[6661]="他们说食物是行军的保障，这是真的。要想成功应对敌人的攻击，军队必须拥有足够的粮草和装备供应。"
D.Strings[6662]="有人说军队的成功靠的是力量和勇气。这是真的！但是军队同样需要充足的物资来维系士气，我的工作便是确保他们的物资需求。"
D.Strings[6663]="霜狼要塞被摧毁了！我们需要物资重建基地！"
D.Strings[6664]="%s温顺地低声呜咽着。"
D.Strings[6665]="士兵，你好。你是来帮我的吗？"
D.Strings[6666]="士兵，做得好。我们的马厩将塞满骑兵们的战斗坐骑！"
D.Strings[6667]="谢谢你，兽栏管理员。请牵走动物吧。"
D.Strings[6668]="嗨。你到这儿来学习如何使用新武器算是来对地方啦。"
D.Strings[6669]="啊，$n！你就是我希望见到的人！我们已经拥有足够的军备，可以对部落发动地面攻击！指挥官特拉瓦雷正在征战平原等待指令……$B$B你曾多次证明自己是一名勇敢且经验丰富的士兵。你想为特拉瓦雷传达指令吗？"
D.Strings[6670]="你对哪种武器感兴趣？"
D.Strings[6671]="$n！你在做什么？你应该出去为了部落而战！$B$B我需要一名值得信赖的人去征战平原，去找指挥官传达攻击命令。$B$B要是你的声望再高一点，我也许能派你去……"
D.Strings[6672]="如果你有能力学习的话，我是很荣幸教你如何使用武器的。"
D.Strings[6673]="$n！我们的军备正在减少，在我们获得更多的军备之前是无法发动对征战平原的地面攻击的！$B$B跟雷矛军需官谈谈，他会告诉你如何增加我们的军备。"
D.Strings[6674]="如果你想要进行更多训练，我可以告诉你该去哪里。你想要学习哪种武器呢？"
D.Strings[6675]="卡尔·雷矛，死吧！"
D.Strings[6676]="骑兵们，冲锋！"
D.Strings[6677]="士兵，你做得棒极了！骑兵们已整装待发，就听你的指令了。"
D.Strings[6678]="等待上级命令。"
D.Strings[6679]="我猜想你到这儿来是训练如何使用新武器的？快点，我很忙的！"
D.Strings[6680]="兽栏管理员，我想寄放我的宠物。"
D.Strings[6681]="$n，在战场上看到你这样经验丰富的家伙真好！很抱歉，我们军队的物资过低，无法发动对部落的大规模地面攻击。$B$B跟我们的军需官谈谈，他会给你供给任务的。"
D.Strings[6682]="你是来学习如何作战吗？"
D.Strings[6683]="我可没法教你战斗时如何保持优雅姿态，我只能教你如何使用武器。"
D.Strings[6684]="我可以告诉你该找谁进行训练。你对哪类武器感兴趣？"
D.Strings[6685]="你想学习如何使用武器，是吗？嗨，$g小伙子:姑娘;，别在站在那儿发呆啦，大声说吧！"
D.Strings[6686]="嗨！你是来这儿学习新武器的吗？"
D.Strings[6687]="你想要学习哪种武器？"
D.Strings[6688]="我们需要更多的狼！去马厩需求帮助吧！"
D.Strings[6689]="做得好，部落！马厩中有足够的霜狼可供我们的狼骑兵乘坐！"
D.Strings[6690]="狼骑兵们，去霜刀小径！"
D.Strings[6691]="告诉我乘坐什么坐骑最好。你就是我们在前线的耳目。"
D.Strings[6692]="兄弟们，是时候了。我们必须阻止敌人通过霜刀小径。我们中必然会有人在战斗中牺牲，但是你们有谁想要逃避这个职责吗？逃避这个荣耀的职责？前进吧！为了部落而战！"
D.Strings[6693]="米洛尔，我曾经是一名护甲铸造师，我想重抄旧业！教教我吧。"
D.Strings[6694]="米洛尔，我曾经是一名武器铸造师，我想重抄旧业！教教我吧。"
D.Strings[6695]="克拉索克，我曾经是一名护甲铸造师，我想重抄旧业！教教我吧。"
D.Strings[6696]="克拉索克，我曾经是一名武器铸造师，我想重抄旧业！教教我吧。"
D.Strings[6697]="去霜刀小径巡逻。别让任何人通过那儿！为荣誉而战……"
D.Strings[6698]="科卡尔入侵者们撤退了！"
D.Strings[6699]="我们已经收集到足够的狼皮。很快，骑兵们就可以上马出发啦！当我们有足够的山羊时再来跟我谈谈。"
D.Strings[6700]="马厩又满啦！我们的骑兵很快就可以乘坐啦！"
D.Strings[6701]="马厩是空的！我们必须为骑兵提供充足的坐骑。卡尔·雷矛马厩需要你的帮助！"
D.Strings[6702]="霜狼，死吧！"
D.Strings[6703]="听从你的指令！"
D.Strings[6704]="哟！呃，跟你一起去前线！"
D.Strings[6705]="等待上级命令！"
D.Strings[6706]="山羊骑兵，列队！"
D.Strings[6707]="女士们先生们，今天是个伟大的日子。因为今天，你们将为卡尔·雷矛的荣耀而战！前进吧，对敌人绝不手下留情！打倒那些野蛮的家伙！"
D.Strings[6708]="士兵们，去前线巡逻！"
D.Strings[6709]="奥特兰克本地出产的山羊对我们的骑兵至关重要！"
D.Strings[6710]="再有一些坐骑我们的马厩就满啦。士兵，让我来保管它们吧。我会从这儿牵走一些。"
D.Strings[6711]="乐意效劳。这些东西真臭！"
D.Strings[6712]="好啦，入侵者们！攻击吧！"
D.Strings[6713]="乐意效劳，$n！"
D.Strings[6714]="%s从植株中生长出来，开始进行治疗。"
D.Strings[6715]="%s发起了攻击！"
D.Strings[6716]="很高兴遇见你，$n。要做的事情还很多，我们必须抓紧时间。"
D.Strings[6717]="愿塞纳留斯指引你，$c。$B$B我和我的姊妹身负重任，从塞纳里奥议会来到这片被污染的土地。而只有那些足够强大的人才能帮助我，毕竟让能力不足的人去完成任务是愚蠢的做法。"
D.Strings[6718]="我和我的姐妹从石爪山脉来到这儿，想要终止数年来的悲剧。不幸的是，我们还不够强大，无法独立完成目标，想向你这样的人寻求帮助。$B$B如果你足够强大，我们就谈谈任务的详细情况，$c。如果你还不够强大，那么，为了你的安全着想，就到此为止吧。"
D.Strings[6719]="$n，请看看我从洞穴中取出的维雷斯塔姆藤蔓的样本，这样你就知道自己要找什么了……"
D.Strings[6720]="向你致意，$r。"
D.Strings[6721]="解放啦！我终于从镣铐中解放啦！"
D.Strings[6722]="在这世上，我已经不需要什么立足之地了，$c。部落……所有的部落成员将看见。他们相互交战，这是为了什么？遍地是秃鹫留下的骸骨……军团大肆侵犯我们的土地……呸！$B$B半人马应该为他们的遗产感到骄傲——这些遗产就跟暗夜精灵或兽人的遗产一样高贵——现在是我们效仿的时候啦！"
D.Strings[6723]="最后，我从将我禁锢在此的腐化中解脱了……"
D.Strings[6724]="感谢你所做的一切，$n。$B$B请保管好节杖，它可以帮你抵御那些入侵此地的邪恶力量。"
D.Strings[6725]="怎么会这样，$n？你认为像塞雷布拉斯节杖这样的物品是微不足道的吗？$B$B这次我可以帮助你，但是别再对这么重要的物品掉以轻心啦……"
D.Strings[6726]="塞雷布拉斯，我丢了我的节杖……"
D.Strings[6727]="我携带有节杖的两个部分。"
D.Strings[6728]="我的节杖……这么多年过去了……你终于重新得到它了！你真是这儿的救世主……$B$B请仔细听我说，$n。只有在玛拉顿之石才能将节杖的杖头和杖身结合在一起。"
D.Strings[6729]="请让我看看玛拉顿的石头。"
D.Strings[6730]="请解释一下怎么使用节杖。"
D.Strings[6731]="在繁复的色彩中出现一条小路。$B$B被光线映衬得闪闪发光。$B$B你从水底浮上来。"
D.Strings[6732]="我不太明白……"
D.Strings[6733]="在玛拉顿大门附近的橙色和紫色通道之间还有一条道路。$B$B你手中的节杖便是钥匙。"
D.Strings[6734]="不，真的，我还是不懂……"
D.Strings[6735]="我越来越疲惫了……$B$B从这儿你可以看见瀑布，$n……要是你敢再次进入玛拉顿的大门，节杖将赋予你抵达那儿的能力。$B$B在玛拉顿的入口附近，你会看见一条通往洞穴之下的通道。在远古遗址处使用节杖创造传送门，你就可以进入玛拉顿了。"
D.Strings[6736]="告诉我关于玛拉顿的更多信息。"
D.Strings[6737]="很久以前，我和我的森林女神姐妹们曾进入这些洞穴，想释放我的叔叔扎尔塔倍受折磨的灵魂。但是，已经充斥了所有洞穴的腐化力量很快击败了我们。$B$B我们注定要在此迷失方向；毒素侵蚀了我们的头脑……$B$B尽管现在我的灵魂已经安息，但是我知道我没能完成任务。我要为此承担巨大的悲伤……"
D.Strings[6738]="告诉我关于扎尔塔的更多信息。"
D.Strings[6739]="啊，扎尔塔……<塞雷布拉斯把头扭了过去。>$B$B我的父亲雷姆洛斯试图阻止他……$B$B扎尔塔太顽固了，当他爱上一位土元素公主时，我父亲就知道他们的结合将受到诅咒，但是扎尔塔拒绝听从父亲的意见。$B$B他因此变成了半人马。他们生下来就带着畸形的躯体，并充满仇恨；我的叔叔扎尔塔被自己的亲戚所杀……$B$B那个邪恶的瑟莱德丝公主，还在水晶洞穴内守护着他的遗体。"
D.Strings[6740]="这些地精应该为他们的行为感到羞耻。呸！"
D.Strings[6741]="花费金钱不是为了冬幕节！"
D.Strings[6742]="我不敢相信这些贪婪的地精能在破坏季节的精神的同时兜售他们的器皿。"
D.Strings[6743]="卑鄙的地精……什么东西都要一金币。"
D.Strings[6744]="能给我一本《冬幕节》书的副本读一读吗？"
D.Strings[6745]="或许我们可以稍后再尝试尝试。等你想好的时候再跟我谈谈。"
D.Strings[6746]="这两部分将再次合二为一。"
D.Strings[6747]="看看我放在你面前的这本卷轴，大声阅读。"
D.Strings[6748]="%s开始将他的能量引导到石头上。"
D.Strings[6749]="你想研究石头？跟我来。"
D.Strings[6750]="多年来我都在被诅咒的形态下飘泊生活。你恢复了我的自由……你会得到报答的。"
D.Strings[6751]="请按照我教你的那样做，$n。"
D.Strings[6752]="我的节杖再次合二为一啦！"
D.Strings[6753]="欢迎来到探险者联盟。如果你需要书面信息的话，我也许能帮你。"
D.Strings[6754]="我要怎么才能找到节杖的两个部分呢？"
D.Strings[6755]="潜伏在玛拉顿的毒素开始渗入我的头脑，我逐渐丧失对事实的判断力。我的树妖姐妹们担心我会被恶魔利用，她们悄悄地拿走了我的节杖，将节杖断成两截，藏在洞穴中。$B$B很快，她们也丧失了理智，两段节杖也因无人看守，成了维利塔恩的囊中之物。那个萨特将一截节杖交给邪恶的元素诺克赛恩看管，另一截则由他自己保管至今。"
D.Strings[6756]="诺克赛恩为什么不能将节杖的两部分结合到一起？"
D.Strings[6757]="没有结合节杖两部分所需的咒语，诺克赛恩是无法使用节杖的。但是，我已经从诺克赛恩的诅咒中解放啦，如果你能将节杖的两部分交给我——节杖的头部和棍身，我会帮助你的。"
D.Strings[6758]="请告诉我关于雷姆洛斯和扎尔塔的历史。"
D.Strings[6759]="你问到塞纳留斯的儿子雷姆洛斯和扎尔塔。$B$B我的父亲雷姆洛斯强壮英俊，我的叔叔扎尔塔矮小灵动。虽然两人受到大家的一致尊重，但是扎尔塔总认为自己无法得到雷姆洛斯所享受的荣耀和受到的关注。$B$B我和我的姐妹们出生后，扎尔塔在嫉妒心的驱使下，想要超越他的兄弟……他自作自受。即使事情已经过去了这么久，我心中仍悲恸不已……"
D.Strings[6760]="我的灵魂和残骸被禁锢在玛拉顿很久了，年轻的$c。我在这儿深深反思自己的错误，发现自己对雷姆洛斯的嫉妒是很愚蠢的行为。他尝试告诫我，并劝我说我和瑟莱德丝公主之间的关系只能是纯洁的——一旦关系混乱灾难就会降临。我的兄弟是对的。$B$B但是现在你释放了我，情况就不同了。"
D.Strings[6761]="尽管我被当作异教徒，我仍然坚持自己的信仰——这信仰指引着我不断前进。但是要完成我的使命，我需要他人的帮助……这人只要不是半人马就行。$B$B任务需要你进入玛拉顿神圣的大厅——我的人民守护着这座神殿，只有最虔诚的人才可以进去。$B$B如果你同意帮助我的话，就点点头吧。我会给你一张羊皮纸，上面写着我给你指示。好好看看。"
D.Strings[6762]="我会帮你的。教我怎么做。"
D.Strings[6763]="%s在你面前深深鞠躬。"
D.Strings[6764]="谢谢你，好心的$c。"
D.Strings[6765]="你好，$n。我是格里高利·维克托医生，部落的首席外科医生。"
D.Strings[6766]="很高兴再次见到你，$n医生。我看着你逐步成长，我敢说现在是你学习更高的绷带技能的时候啦。$B$B一旦你的技能得到提高，就回来找我，我会把我所知的一切都教给你的。"
D.Strings[6767]="医生，请告诉我制作厚魔纹绷带的方法。"
D.Strings[6768]="医生，请告诉我制作符文布绷带的方法。"
D.Strings[6769]="医生，请告诉我制作厚符文布绷带的方法。"
D.Strings[6770]="你好，$n。我是古斯塔夫·范沃森医生，联盟的首席外科医生。"
D.Strings[6771]="好极了！我们要保证物资的运送！"
D.Strings[6772]="感谢你提供的物资，$n！"
D.Strings[6773]="非常感谢，$n！"
D.Strings[6774]="我们已经取得了不错的进展！需要取回更多的物资来修复丹巴达尔！"
D.Strings[6775]="我们拥有足够的物资啦！我们的队长重新在征战平原占据了阵地！"
D.Strings[6776]="现在我们取得了进展！"
D.Strings[6777]="谢谢你提供的护甲碎片，$n！"
D.Strings[6778]="我们的装备储备增加啦!"
D.Strings[6779]="谢谢你提供的物资，$n。"
D.Strings[6780]="很好。我们的物资在不断增加……"
D.Strings[6781]="保持这样！我们还需要更多的物资来重建……"
D.Strings[6782]="我们可以重建啦！为了部落而战！"
D.Strings[6783]="嗨，$n！很高兴你来看我。我们正准备对征战平原发动一场规模浩大的地面攻击！等到霜狼突击队队长一声令下，他和他的部队将给予联盟致命的攻击！$B$B你想传达这些命令吗，$n？加瑞克在征战平原等着你呢……"
D.Strings[6784]="你怎么在这儿，$n？你怎么到这儿来啦？$B$B你不是带着攻击指令吗——征战平原的霜狼突击队队长还在等着发动进攻呢！去吧！"
D.Strings[6785]="能在奥特兰克山谷找到你这样经验丰富的家伙真好，$n。我们的军需不够，无法发动对奥特兰克山谷的地面攻击……跟我们的军需官谈谈——他会告诉你如何增加我们的军需储备。"
D.Strings[6786]="嗨，$c！我们的军需已经增加，现在可以对征战平原发送地面攻击啦。要是你的声望再高一点，我一定会派你传达攻击命令的。$B$B去吧，为了联盟而战！证明你是一名值得信赖的、有能力的部落成员！"
D.Strings[6787]="你！$n！你在山谷这儿游荡什么呢？在奥特兰克到处都是联盟的敌人！我们必须赶走它们！$B$B我们的军需不够，无法发动大规模的地面攻击,跟我们的军需官谈谈.他会告诉你如何增加我们的军需。"
D.Strings[6788]="在面对强大的敌人时，即使是最勇敢的士兵也必须拥有充足的装备！"
D.Strings[6789]="我刚把击杀荣誉给$n。"
D.Strings[6790]="嗨！取消你的抵抗魔法！"
D.Strings[6791]="单击此处修理装备"
D.Strings[6792]="我们拥有足够的物资来发动地面攻击啦。如果你认为自己够资格传达指令的话，就跟亚斯拉·血矛谈谈。"
D.Strings[6793]="我们拥有足够的物资来发动地面攻击啦。如果你认为自己够资格传达指令的话，就跟诺雷格·雷矛中尉谈谈。"
D.Strings[6794]="我负责霜狼氏族的军队招募工作。作为一名霜狼士兵，如果你的等级足够高的话，就来向我报到吧。$B$B在冰冷的战场上，你会获得荣誉和尊重的。"
D.Strings[6795]="队长，我把徽章弄丢了。你能再给我一枚吗？"
D.Strings[6796]="你好，$r！我是哈格丁中尉，是负责招募雷矛卫兵的官员。$B$B你在雷矛军队中获得一定的威望后再来找我吧，我会升级你的徽章的。如果你丢失了徽章，我也能再给你一枚。"
D.Strings[6797]="副官，我丢失了我的徽章。你能再给我一枚吗？"
D.Strings[6798]="我已经找到节杖的两个部分啦。"
D.Strings[6799]="啊，我需要帮助！"
D.Strings[6800]="$n来了——留神，我的朋友！"
D.Strings[6801]="你会后悔遇见我的，$n。"
D.Strings[6802]="我们的祖先教诲说，集体的力量胜过个人的力量。你想要加入公会为了雷霆崖的荣誉而战吗？"
D.Strings[6803]="是的，你看起来是个领导者。你是来这里组织公会与联盟作战吗？"
D.Strings[6804]="我不会受到引诱离开的！"
D.Strings[6805]="申苏尔，我丢了我的哨子，也没有信号枪啦。请帮帮我！"
D.Strings[6806]="你好，$c。我是罗卡鲁。"
D.Strings[6807]="罗卡鲁，我丢了龙火护符。你能再给我一个吗？"
D.Strings[6808]="你向蓝龙要求什么？"
D.Strings[6809]="哈尔琳，我把龙火护符弄丢了。你能帮我再做一个吗？"
D.Strings[6810]="奈辛瓦里要出去狩猎。我发现帮助他做丛林狩猎的准备工作比做战争准备的工作轻松多了。尽管我错过了战场上的光辉岁月。"
D.Strings[6811]="巴尼尔，我好像把第一章给弄丢了。"
D.Strings[6812]="巴尼尔，我好像把第二章给弄丢了。"
D.Strings[6813]="巴尼尔，我好像把第三章给弄丢了。"
D.Strings[6814]="巴尼尔，我好像把第四章给弄丢了。"
D.Strings[6815]="我看到你将辛辛苦苦拼好的篇章随意乱放，$n。嗯，就放在那儿！"
D.Strings[6816]="卡拉然，请为火炬附魔。"
D.Strings[6817]="我对这片森林非常熟悉，它们就像我身体的一部分……但是它们还蕴藏着很多值得学习的知识，当然也有很多危险。"
D.Strings[6818]="莱恩，我把达图尔的变形魔棒弄丢了。"
D.Strings[6819]="是的，我曾盼望你能回来。早些时候，我派科兰出去，她发现了达图尔的魔棒被遗弃在森林里。$B$B我们竭力想要找回它，$n。请你小心以后不要掉了它。"
D.Strings[6820]="你已经完成了泰洛尼斯的任务，感谢你所做的一切，$n。"
D.Strings[6821]="你好！这间工场不是我的，不是！但是终有一天当我完成训练后，我将成为一名发明家，就像我崇拜的英雄玛尔冯·瑞文斯克那样。$B$B你从来没有听说过他吗？哦，碰巧他已经离开好长一段日子啦，他去研究远古巨魔废墟啦，他是乘坐地精飞艇走的……我也不是很清楚他究竟去了哪儿……$B$B塔纳拉辛？坦克利斯？塔纳里萨尼？$B$B<莉芙摇着头。>$B$B不，名字不是这样……"
D.Strings[6822]="嗨。不，玛尔冯一定不在这儿，他还要好些时间才能回来呢。实际上，我有些担心他……$B$B我希望他能很快回来。有人寄了一只大箱子给他，我可没力气把这东西拖进去！我只能把它放在门口……"
D.Strings[6823]="你已经学会了我现在能教你的所有知识，$n医生。当你获得更多经验的时候再来找我吧，我会传授给你更多高级的医学知识的。"
D.Strings[6824]="快跑！他们来了！"
D.Strings[6825]="这地方……受到了诅咒。$B$B我刚刚设法逃脱，我可不想再进入那些地道啦。$B$B但是，我的兄弟姐妹……就没这么幸运了。他们被困在里面，恶魔花园散发的堕落烟雾令他们疯狂。$B$B你一定要帮帮他们。"
D.Strings[6826]="哦，很高兴你已经回来啦，$n。$B$B我兄弟的灵魂已经从堕落中解脱啦，但是我得留在此地表示我的哀悼。$B$B非常感谢你的帮助，$n。"
D.Strings[6827]="入侵者！入侵者！全视之眼被偷了！可耻的$n偷走了它！"
D.Strings[6828]="需要物资供给吗？"
D.Strings[6829]="你有什么要出售的东西？"
D.Strings[6830]="科尔拉克来了，懦弱的家伙！一场盛宴就要开始了。来吧！受死吧！"
D.Strings[6831]="我们还需要多少物资供给？"
D.Strings[6832]="奥特兰克山谷——联盟军需官问候默认选项"
D.Strings[6833]="指挥官被杀死啦！冲向他们的战线！为荣耀而死！"
D.Strings[6834]="我们的指挥官倒下啦！报仇的时候到啦！山羊骑士们，冲吧！！"
D.Strings[6835]="指挥官，是狼骑兵攻击敌人的时候啦。发出指令吧。"
D.Strings[6836]="等待指令。我将听从你的命令，让那些家伙命丧黄泉！"
D.Strings[6837]="命令已经下达啦！杀死雷矛！向敌人冲锋！"
D.Strings[6838]="指挥官，是攻击霜狼的时候啦！杀死他们！"
D.Strings[6839]="蘑菇！"
D.Strings[6840]="听您的命令调遣骑兵，先生！"
D.Strings[6841]="冲啊！！！杀死他们！"
D.Strings[6842]="现在是我们惩罚你们的时候啦！"
D.Strings[6843]="是用牙戳刺的时候啦……"
D.Strings[6844]="啊啊啊啊啊啊！～"
D.Strings[6845]="雷矛墓地被联盟占领了！"
D.Strings[6846]="雷矛墓地受到攻击！如果我们不尽快采取措施，联盟会占领它的！"
D.Strings[6847]="雷矛墓地被部落占领了！"
D.Strings[6848]="雷矛墓地受到攻击！如果我们不尽快采取措施，部落会占领它的！"
D.Strings[6849]="雪落墓地被联盟占领了！"
D.Strings[6850]="雪落墓地受到攻击！如果我们不尽快采取措施，联盟会占领它的！"
D.Strings[6851]="雪落墓地被部落占领了！"
D.Strings[6852]="雪落墓地受到攻击！如果我们不尽快采取措施，部落会占领它的！"
D.Strings[6853]="霜狼墓地被联盟占领了！"
D.Strings[6854]="霜狼墓地受到攻击！如果我们不尽快采取措施，联盟会占领它的！"
D.Strings[6855]="霜狼墓地被部落占领了！"
D.Strings[6856]="霜狼墓地受到攻击！如果我们不尽快采取措施，部落会占领它的！"
D.Strings[6857]="你是来学习战斗的艺术的，$r？你来错地方了。"
D.Strings[6858]="你是来学习战役案例的吧？听好了，我会为你讲解那些显赫的胜仗和耻辱的败仗的。"
D.Strings[6859]="来吧，小家伙们。面对我！"
D.Strings[6860]="我保护着这个地方。神秘的奥术不能受到亵渎。"
D.Strings[6861]="这就是好奇的代价。"
D.Strings[6862]="你好，士兵。据报道西边的冰斧巨魔抓走了一名地精工程师。或许你得去调查一下？"
D.Strings[6863]="我的斥候报告说辛迪加在东部平原一处隐秘的洞穴中居住。在你进入这片地区的时候要小心。"
D.Strings[6864]="士兵，谨慎些。雷矛在基地周围埋下了许多地雷。要是你想要进入雷区，就去跟东面了望塔里的爆破专家谈谈。"
D.Strings[6865]="提起精神，士兵！雷矛智者报告说冰斧巨魔已经抓住了一名地精工程师。霜狼正试图解救他，以便利用他的工程学制品来摧毁我们！可别让这种事情发生。"
D.Strings[6866]="据报，辛迪加工会东部平原的一处洞穴人声鼎沸。去看看那儿发生了什么事，士兵！小心霜狼的活动！"
D.Strings[6867]="进入霜狼领土时要当心，士兵。这儿到处都是陷阱！还有无数的地雷！跟前线第一座塔楼的爆破专家谈谈。我想他会教你如何处理这些情况的。"
D.Strings[6868]="是的，我有，指挥官。"
D.Strings[6869]="那么听好了，$c。$B$B你能感知到从我身上散发出的力量吗？你的士气不够？是的，对另一方来说也是这样。要破坏瓦解他们的军队并不容易，但是必须完成任务！胜利是属于我们的！"
D.Strings[6870]="要我杀死谁？指挥官，告诉我他们在哪儿。"
D.Strings[6871]="六名中尉指挥着前线的防御事务。必须迅速解决他们！我们绝不能让他们的任何一名牧师活着逃回去。$B$B要是我们能很快结果掉所有的中尉，前线的士气将大跌！战线也会很快攻破！他们的军队将落荒而逃，留守的士兵将失去后援。"
D.Strings[6872]="就这样吗？我以为你会向我挑战。"
D.Strings[6873]="不，$c，这并不是全部。敌对阵营的精英部队是由基地的四名指挥官领导的。要是你能给予他们致命的一击，快速解决掉这些指挥官，精英前线即可攻破。他们将溃不成军！$B$B但是，士兵，要小心；对指挥官和中尉可不能掉以轻心。他们可不是徒有虚名的……"
D.Strings[6874]="所有人鼓掌，所有人鼓掌！"
D.Strings[6875]="谢谢你，你是个很好的聆听者！我整周都会在这儿的！"
D.Strings[6876]="省下一些零钱？"
D.Strings[6877]="我已经拥有它啦！我已经拥有了，然后又丢失啦。丢掉了……所有的东西……就像……我的思绪。我的思绪就像……奶酪。我喜欢奶酪。"
D.Strings[6878]="看看你对艺术的欣赏能力吧，往我的帽子里扔些钱币！"
D.Strings[6879]="搜索生命体……没有发现目标"
D.Strings[6880]="发现不明生物体……判断中……"
D.Strings[6881]="目标丢失……返回搜索模式"
D.Strings[6882]="探险者报告！……棒极了！"
D.Strings[6883]="%s垂涎欲滴地盯着一只矿道鼠。"
D.Strings[6884]="嗯……你看起来味道不错。"
D.Strings[6885]="让我想想……我想我会通过的。"
D.Strings[6886]="42……42……42，什么？什么都不是！42……嗯……"
D.Strings[6887]="如你所愿……"
D.Strings[6888]="我的力量在消退，人类。我履行了承诺，清除了道路。我得回去啦。"
D.Strings[6889]="无能为力……没有力气啦……恢复……必须恢复……瑟雷姆控制着……结束这痛苦的折磨吧……"
D.Strings[6890]="谢谢你，人类。在我重回梦境之前我只能帮助你一次。$B$B通往瑟雷姆的主人奥兹恩的大门阻挡了你前进的道路。我会充当你破坏的器械。我等待你的命令，帮你打开大门。"
D.Strings[6891]="谢谢你，埃隆巴克。我们等着你打开大门。"
D.Strings[6892]="终于……从他邪恶的魔爪下逃脱了！"
D.Strings[6893]="谁控制着石炉墓地？"
D.Strings[6894]="石炉墓地就在征战平原的石炉前哨东面。$B$B联盟控制着这片土地。"
D.Strings[6895]="石炉墓地就在征战平原的石炉前哨东面。$B$B部落控制着这片土地。"
D.Strings[6896]="发动一次地面攻击还需要多少物资供给？"
D.Strings[6897]="重建基地还需要多少物资供给？"
D.Strings[6898]="我们有很多物资储备啦，但是要发动对征战平原的地面攻击，我们还需要更多的物资。"
D.Strings[6899]="我们有一些物资，但是现在有很多啦。我们还需要一些来发动对征战平原的地面攻击。"
D.Strings[6900]="我们几乎没有物资装备。想要发动对征战平原的地面攻击的话，还需要很多物资！"
D.Strings[6901]="我们拥有丰富的物资储备来修复霜狼要塞。再有一些我们就能完全修复，重新开战啦！"
D.Strings[6902]="我们的物资储备状况一般，要完全修复霜狼要塞的话，我们还需要更多的物资。"
D.Strings[6903]="我们的物资太少，不足以修复霜狼要塞。如果想要完全修复，重新开战，需要的物资就更多啦。"
D.Strings[6904]="我们几乎没有物资来修复霜狼要塞。我们需要更多的物资来重建基地，重新开战。"
D.Strings[6905]="$n，我们已经具备了足够的物资来发动对征战平原的地面攻击。如果你想要传递指令，而且你的等级足够高的话，就跟霜狼村的亚斯拉·血矛谈谈。"
D.Strings[6906]="我们有许多用于重建的物资了。再多一些我们就能修复丹巴达尔，重新开战啦！"
D.Strings[6907]="我们已经收集到很多用于重建的物资，但是还需要一些才能修复丹巴达尔。继续收集吧！"
D.Strings[6908]="我们的物资不够，无法修复。要修复丹巴达尔，还需要很多物资。"
D.Strings[6909]="丹巴达尔破坏严重，要修复的话，我们还需要大量物资供给。联盟需要你的帮助！"
D.Strings[6910]="$n，我们已经具备足够的物资来发动地面攻击。如果您在雷矛守卫的声望够高的话，就跟诺雷格·雷矛中尉谈谈吧。"
D.Strings[6911]="我们的物资储备已经很多了，但是要发动对征战平原的地面攻击，我们还需要更多的物资。"
D.Strings[6912]="我们有剩余的物资，但是不太多。我们还需要更多的物资才能发动对征战平原的地面攻击。"
D.Strings[6913]="我们几乎没有多余的物资。要发动对征战平原的另一场地面攻击，我们还需要很多物资。"
D.Strings[6914]="发动地面攻击还需要多少物资供给？"
D.Strings[6915]="再升一级还需要多少物资供给？"
D.Strings[6916]="我差不多拥有足够的物资供给来升级到精练部队了。"
D.Strings[6917]="我需要更多的物资来升级我们的军队。"
D.Strings[6918]="我差不多拥有足够的物资供给来升级部队了。"
D.Strings[6919]="升级到精练部队所需的物资还差一半呢。"
D.Strings[6920]="升级到精练部队所需的物资只有不到三分之一。"
D.Strings[6921]="我几乎没有任何可供升级的物资。"
D.Strings[6922]="啊……这些家伙让我整天都不得安宁！你看见他们了吗？$B$B我真希望自己能藏到地下，避开他们……"
D.Strings[6923]="拉瑞安，我想帮助你打败这些家伙！"
D.Strings[6924]="这是一些特殊装备！要小心对待，要是你喝了太多那种烈性酒，可别试着操纵这些装备，我听说你很喜欢饮酒的……$B$B说到酒……你没有带吧，嗯？"
D.Strings[6925]="你要走哪条路？嗯，我能给你的唯一建议是走你想走的路！$B$B我什么都记不得啦！"
D.Strings[6926]="%s仔细检查着垃圾。"
D.Strings[6927]="这都是我说的闲话。"
D.Strings[6928]="%s放下木棒，开始狂野地摇摆！"
D.Strings[6929]="你胆敢惹恼我，懦弱的家伙！"
D.Strings[6930]="到处都是老鼠。随处可见。它们那贪婪的小眼睛老是盯着我。我会给它们点颜色看看的！"
D.Strings[6931]="烤鼠肉串！在这儿取一些好吃的烤鼠肉串！尽快拿吧！"
D.Strings[6932]="我差不多拥有足够的物资供给升级到勇士部队了。"
D.Strings[6933]="升级到勇士军队所需的物资还差一半呢。"
D.Strings[6934]="我的祭坛将汲取你的生命！"
D.Strings[6935]="你的痛苦很快就可以结束了！"
D.Strings[6936]="丹巴达尔南部碉堡受到攻击！如果我们不尽快采取措施，部落会摧毁它的！"
