D.Strings[6966]="冰血哨塔被联盟摧毁了！"
D.Strings[6967]="我没什么可以教你的了。我听说藏宝海湾有个名叫海明威的老头，他在出售《鲈鱼与你》这本书，它对你提高钓鱼技能大有帮助。"
D.Strings[6968]="雷矛急救站被部落占领了！"
D.Strings[6969]="雷矛急救站受到攻击！如果我们不尽快采取措施，部落会占领它的！"
