D.Strings[6975]="霜狼急救站受到攻击！如果我们不尽快采取措施，联盟会占领它的！"
D.Strings[6976]="看到那边坏掉的陷阱了没？愚蠢的食人魔对此感到束手无策。很明显，只要略做修理就能恢复原状！要是你能修好它，我敢打赌斯里基克一定会中圈套。哈哈——食人魔卫兵掉入陷阱！"
D.Strings[6977]="石炉墓地被部落占领了！"
D.Strings[6978]="石炉墓地受到攻击！如果我们不尽快采取措施的话，部落会占领它的！"
D.Strings[6979]="石炉墓地被联盟占领了！"
D.Strings[6980]="石炉墓地受到攻击！如果我们不尽快采取措施的话，联盟会占领它的！"
D.Strings[6981]="冰血墓地被部落占领了！"
D.Strings[6982]="冰血墓地受到攻击！如果我们不尽快采取措施，部落会占领它的！"
D.Strings[6983]="冰血墓地被联盟占领了！"
D.Strings[6984]="冰血墓地受到攻击！如果我们不尽快采取措施，联盟会占领它的！"
D.Strings[6985]="告诉我关于矿洞的事儿。"
D.Strings[6986]="告诉我关于墓地的事儿。"
D.Strings[6987]="告诉我关于哨塔的事儿。"
D.Strings[6988]="在奥特兰克山谷中两处矿洞：联盟领地上的深铁矿洞和部落领地上的寒齿洞穴。两处矿洞都有丰富的矿产资源，在过去，它们用于存储过剩的物资。$B$B现在，部落、联盟和当地居民常常争夺矿洞。"
D.Strings[6989]="奥特兰克山谷的哨塔和碉堡都是至关重要的战略性据点。要是我们能控制哨塔，就能展开远程攻击啦。"
D.Strings[6990]="逝者的灵魂在奥特兰克山谷的墓地安息。如果你死了，你的灵魂将被送往最近的墓地。"
D.Strings[6991]="谁控制着雷矛急救站？"
D.Strings[6992]="谁控制着霜狼急救站？"
D.Strings[6993]="雷矛急救站在丹巴达尔，就在丹巴达尔军营外。$B$B联盟控制着这片土地。"
D.Strings[6994]="雷矛急救站在丹巴达尔，就在丹巴达尔军营外。$B$B部落控制着这片土地。"
