D.Strings[6996]="石炉墓地就在征战平原的炉石前哨东面。$B$B联盟和部落还在争夺这片土地。"
D.Strings[6997]="雷矛墓地就在丹巴达尔以东的桥梁对面的山脉中。$B$B联盟和部落还在争夺这片土地。"
D.Strings[6998]="霜狼墓地就在距离霜狼村以北不远的路面。$B$B联盟和部落还在争夺这片土地。"
D.Strings[6999]="雪落墓地就在征战平原的高山顶部，就在冰斧要塞以东。$B$B联盟和部落还在争夺这片土地。"
D.Strings[7000]="霜狼急救站在霜狼城堡中，就在霜狼哨塔以南。$B$B联盟控制着这片土地。"
D.Strings[7001]="霜狼急救站在霜狼城堡中，就在霜狼哨塔以南。$B$B部落控制着这片土地。"
