D.Strings[7023]="石炉碉堡是征战平原东侧的要塞。$B$B联盟控制着它。"
D.Strings[7024]="石炉碉堡是征战平原东侧的要塞。$B$B部落控制着它。"
D.Strings[7025]="石炉碉堡是征战平原东侧的要塞。$B$B联盟和部落还在争夺它。"
D.Strings[7026]="东部哨塔高地守护着征战平原和南部部落领土之间的要塞。$B$B联盟控制着这片土地。东部霜狼哨塔守护着霜狼村和霜狼城堡之间的大门。$B$B联盟控制着这片土地。"
D.Strings[7027]="东部哨塔高地守护着征战平原和南部部落领土之间的要塞。$B$B部落控制着这片土地。东部霜狼哨塔守护着霜狼村和霜狼城堡之间的大门。$B$B部落控制着这片土地。"
D.Strings[7028]="东侧防御塔点是征战平原和南部部落领土之间的要塞。$B$B联盟和联盟还在争夺这片土地。东部霜狼哨塔守护着霜狼村和霜狼城堡之间的大门.$B$B联盟和部落还在争夺这片土地。"
D.Strings[7029]="西侧防御塔点是征战平原和南部部落领土之间的要塞。$B$B联盟控制着这片土地。"
D.Strings[7030]="西侧防御塔点是征战平原和南部部落领土之间的要塞。$B$B部落控制着这片土地。"
D.Strings[7031]="西侧防御塔点是征战平原和南部部落领土之间的要塞。$B$B联盟和联盟还在争夺这片土地。"
D.Strings[7032]="冰血哨塔保护着冰血要塞。$B$B联盟控制着这片土地。"
D.Strings[7033]="冰血哨塔保护着冰血要塞。$B$B部落控制着这片土地。"
D.Strings[7034]="冰血哨塔保护着冰血要塞。$B$B联盟和部落还在争夺这片土地。"
D.Strings[7035]="再告诉我一次有关哨塔的信息……"
D.Strings[7036]="再告诉我一次有关墓地的信息……"
D.Strings[7037]="再告诉我一次有关矿洞的信息……"
D.Strings[7038]="告诉我别的信息……"
D.Strings[7039]="巴琳达·斯通赫尔斯已经倒下啦！我们的将军范达尔·雷矛现在正领导着来自丹巴达尔的军队。$B$B攻击部落！为斯通赫尔斯报仇！"
D.Strings[7040]="部落的加尔范上尉被杀死了。现在霜狼领袖德雷克塔尔指挥着来自霜狼要塞的部落军队！$B$B打败德雷克塔尔，胜利是属于我们的！"
D.Strings[7041]="你对此了解多少？"
D.Strings[7042]="我知道很多，好好听着吧，$r。"
D.Strings[7043]="我在听，德米提恩。"
D.Strings[7044]="很久以前，在篡位者称为创世之年代的时候，我的主人和他的同胞们统治着整个世界。是他们，是远古的神灵创造了一切。$B$B他们最终被那些称他们为缔造者的家伙推翻了。"
D.Strings[7045]="他们庞大的身躯在多年的战乱中渐渐衰弱，被禁锢在地下世界——他们自己创造的地下世界中——堕落的泰坦缔造者能渗透地表，污辱古老的神灵。$B$B兄弟反目。一场持续五千年的战争在世界的核心展开。"
D.Strings[7046]="部落和联盟的首领都倒下啦！$B$B我们的将军范达尔·雷矛现在带领丹巴达尔的军队，而部落的统领则是霜狼城堡的德雷克塔尔。$B$B尽快击败德雷克塔尔！"
D.Strings[7047]="部落和联盟的队长都已经进入战场啦。$B$B我们的队长巴琳达·斯通赫尔斯现在带领着来自石炉哨站的雷矛军队，而对方的队长加尔范上尉也从冰血要塞发出了指令。$B$B战斗开始啦！"
D.Strings[7048]="不！！！把鞣酸放进篮子，否则我打扁你！"
D.Strings[7049]="部落和联盟的队长都已经进入战场啦。$B$B我们的队长加尔范上尉现在带领着来自冰血要塞的霜狼军队，而对方的队长巴琳达·斯通赫尔斯正躲在石炉哨站。$B$B战斗开始啦！"
D.Strings[7050]="雷矛的将军倒下了！联盟胜利啦！$B$B失地复得，全军欢腾。"
D.Strings[7051]="战争形式恶化，我们的队长和敌人的队长都被杀死了！$B$B现在，德雷克塔尔领导着来自霜狼要塞的部队，而矮人范达尔·雷矛则藏在丹巴达尔。杀死范达尔，为了部落的胜利而战！"
D.Strings[7052]="首领巴琳达·斯通赫尔斯已经死啦！现在范达尔·雷矛不得不进入奥特兰克山谷。他就藏在丹巴达尔。$B$B去打败范达尔吧，我们会取得战争的胜利的！"
D.Strings[7053]="加尔范上尉已经被杀死啦，德雷克塔尔现在领导着来自霜狼城堡的军队。$B$B为了死去的队长的荣耀，向联盟进攻！"
D.Strings[7054]="告诉我关于奥特兰克山谷的信息。"
D.Strings[7055]="奥特兰克山谷很久以前就已经成为霜狼氏族的家园了，我们不会让矮人和他们的联盟侵犯这片土地！因此我们不断地战斗！$B$B要赢回奥特兰克山谷，就必须打败他们的首领范达尔·雷矛。$B$B为了部落而战！"
D.Strings[7056]="雷矛部族在奥特兰克山谷中发现了远古的神器，但是霜狼兽人对探险者们可不那么友好。要是矮人想要保护祖先的文化遗产，一场恶战是不可避免的！$B$B要在战争中获胜，就必须打败霜狼将军德雷克塔尔。祝你好运，$c！"
D.Strings[7057]="巴琳达·斯通赫尔斯领导着联盟的前锋军队。她以征战平原以北的石炉哨站为基地。$B$B如果她死掉的话，上层首领范达尔·雷矛将进入丹巴达尔的奥特兰克山谷。$B$B巴琳达还没有重新进入战场。"
D.Strings[7058]="加尔范上尉是德雷克塔尔值得信赖的助手。他领导着来自征战平原以南的冰血要塞的部落军队。$B$B如果加尔范上尉死掉的话，德雷克塔尔将进入霜狼要塞的奥特兰克山谷。$B$B加尔范上尉还没有回到战场。"
D.Strings[7059]="范达尔·雷矛是驻守在奥特兰克山谷的联盟将军，他指挥着来自丹巴达尔的军队。$B$B如果他被打败，联盟将在奥特兰克一役败北；但是只有在巴琳达·斯通赫尔斯阵亡后他才会出现。$B$B范达尔目前不在奥特兰克山谷。"
D.Strings[7060]="德雷克塔尔是奥特兰克霜狼氏族的军事和精神领袖。在奥特兰克的时候他领导着霜狼城堡的兄弟们作战。$B$B如果他被打败，奥特兰克的部落军队将溃不成军，但是现在他只会在下属加尔范上尉死后露面。$B$B德雷克塔尔已经被杀死了。"
D.Strings[7061]="告诉我关于巴琳达·斯通赫尔斯的信息。"
D.Strings[7062]="告诉我关于加尔范上尉的信息。"
D.Strings[7063]="告诉我关于范达尔·雷矛的信息。"
D.Strings[7064]="告诉我关于德雷克塔尔的信息。"
D.Strings[7065]="再告诉我关于奥特兰克山谷的信息……"
D.Strings[7066]="巴琳达·斯通赫尔斯领导着联盟的前锋军队。她以征战平原以北的石炉哨站为基地。$B$B如果她死掉的话，上层首领范达尔·雷矛将进入丹巴达尔的奥特兰克山谷。$B$B巴琳达现在在石炉哨站。"
D.Strings[7067]="德雷克塔尔是奥特兰克霜狼氏族的军事和精神领袖。在奥特兰克的时候他领导着霜狼城堡的兄弟们作战。$B$B如果他被打败，奥特兰克的部落军队将溃不成军，但是现在他只会在下属加尔范上尉死后露面。$B$B德雷克塔尔现在在霜狼城堡里。"
D.Strings[7068]="加尔范上尉是德雷克塔尔值得信赖的助手。他领导着来自征战平原以南的冰血要塞的部落军队。$B$B如果加尔范上尉的话，德雷克塔尔将进入霜狼要塞的奥特兰克山谷。$B$B加尔范上尉现在在冰血要塞里。"
D.Strings[7069]="一场战斗？"
D.Strings[7070]="炎魔之王拉格纳罗斯在元素大灾变中想要杀死我的主人桑德兰，空气的王子。$B$B<德米提恩低下头，面部肌肉因愤怒而扭曲。>$B$B一旦你说出他的名字，我就会用你的内脏装点这座被破坏的营帐。保持安静，听好了。"
D.Strings[7071]="<点头>。"
D.Strings[7072]="拉格纳罗斯、迦顿和加尔背叛了我的领主。桑德兰王子在毫不知情的情况下被捕了。"
D.Strings[7073]="在毫无觉察的情况下碰到的？怎么会？"
D.Strings[7074]="桑德兰王子对炎魔之王的进攻毫不知情。在王子做出反应之前，传说中拉格纳罗斯使用的大锤萨弗拉斯就会无情地痛击王子。桑德兰倒下了，他完全被打败了。$B$B炎魔之王吸取了王子的精华，但这仍然不能满足他的贪欲。"
D.Strings[7075]="那么，拉格纳罗斯接下来做了什么？"
D.Strings[7076]="桑德兰的精华的些许残留物存储在元素绑定护符中。拉格纳罗斯将护符打碎成两块，分给了他的两名士官……"
D.Strings[7077]="丹巴达尔是联盟在奥特兰克军力最强的地方。位于山谷北部的丹巴达尔是通往南部的军事要塞。$B$B丹巴达尔现在完好无损。"
D.Strings[7078]="丹巴达尔是联盟在奥特兰克军力最强的地方。位于山谷北部的丹巴达尔是通往南部的军事要塞。$B$B丹巴达尔已经被夷为平地，正在重建。"
D.Strings[7079]="霜狼要塞位于奥特兰克山谷的南部，是通往霜狼村的要塞，是名为霜狼的兽人氏族的家园。部落在奥特兰克山谷所有领土都从这儿衍生。$B$B霜狼要塞完好无损。"
D.Strings[7080]="霜狼要塞位于奥特兰克山谷的南部，是通往霜狼村的要塞，是名为霜狼的兽人氏族的家园。部落在奥特兰克山谷所有领土都从这儿衍生。$B$B霜狼要塞被夷为平地，需要重建。"
D.Strings[7081]="告诉我关于丹巴达尔的事情。"
D.Strings[7082]="告诉我关于霜狼要塞的事情。"
D.Strings[7083]="这样，我发现了镣铐的钥匙……"
D.Strings[7084]="你找到钥匙啦？嗯，是那把钥匙吗？我指的是能打开这些枷锁的钥匙。$G先生:女士;，只有一种方法能证明！"
D.Strings[7085]="$n，我会让我所有的盟友朋友都知道你今天救了我的命。给你——我需要轻装上路，请你帮忙收下我的裁缝和制革物品！再次感谢你——再见！"
D.Strings[7086]="你现在是首领啦！你是我们的王！向戈多克王$n致敬！$B$B既然你是首领，所有的手下都会为你上贡的！你留下一些活口的，是吗？"
D.Strings[7087]="哦不！国王死啦！呃……向新国王致敬！啊！"
D.Strings[7088]="想要钥匙的话，就来追我吧！"
D.Strings[7089]="你想玩个游戏吗，自以为是的人？"
D.Strings[7090]="我拥有通往那里的钥匙！跟着我来吧，你会看到的！"
D.Strings[7091]="游戏？你疯了吗？"
D.Strings[7092]="如果你敢的话就来追我吧！我会毫不犹豫地奔跑的！"
D.Strings[7093]="还活着吗？惊讶吧。眼睁睁看着我逃跑吧！"
D.Strings[7094]="为什么你这么矮小……"
D.Strings[7095]="记住我的话，我会抓住你的，小鬼。我会的！"
D.Strings[7096]="为什么你想要伤害我！？我们可以成为朋友的！"
D.Strings[7097]="皱皱眉头！"
D.Strings[7098]="死？！你把普希林弄哭啦！"
D.Strings[7099]="这是底线，你不再是我的朋友啦！"
D.Strings[7100]="准备跟你的缔造者见面吧。"
D.Strings[7101]="跟我的小朋友问声好！"
D.Strings[7102]="恶魔逃脱了！我们必须尽快制止他！"
D.Strings[7103]="我是新国王？你在说什么？"
D.Strings[7104]="老大手下的所有下属——践踏者克雷格、三名守卫、克罗卡斯和观察者——都为新的国王献上贡品。如果你杀死了一名下属，这名下属就不能为新国王上贡啦！留下的活口越多，你得到的贡品就越多。别杀他们，你会得到很多东西的！$B$B就是这样的！"
D.Strings[7105]="那么……把贡品给我吧！"
D.Strings[7106]="为什么我要做修好陷阱这样的麻烦事儿？为什么不按老办法杀死守卫？"
D.Strings[7107]="嗯，从我跟食人魔的交战情况来看……你不必逐一杀死这儿的所有食人魔。$B$B就在前几天戈多克大王恢复权力，杀死以前的国王取而代之的时候，食人魔纷纷离开此地。嗯，国王的追随者们——戈多克没有要他们的命——立即发誓效忠新国王。$B$B谁知道呢——你饶恕的食人魔说不定会效忠于你呢……当然，这是打个比方！"
D.Strings[7108]="这个东西正在起作用。"
D.Strings[7109]="你现在是首领了，对吗？祝新国王长命百岁！$B$B克雷格让你看看戈多克酒。食人魔酒是所有酒中的极品，戈多克酒则是食人魔酒中的极品！你能从我这里买一些，是不是国王？！"
D.Strings[7110]="克雷格，让我看看你都卖些什么酒。"
D.Strings[7111]="你什么意思，购买？！我现在是国王……做国王棒极了！"
D.Strings[7112]="%s开始生长啦！"
D.Strings[7113]="%s继续生长着！"
D.Strings[7114]="%s已经完全长大了！"
D.Strings[7115]="好吧老大，当你想要下属为你上贡的时候，就告诉我！"
D.Strings[7116]="绘制戈多克战争之画！"
D.Strings[7117]="陌生人，离开这儿吧，免得送命，它会吃掉它接触到的一切东西的。"
D.Strings[7118]="精灵，这儿发生了什么事？"
D.Strings[7119]="你知道上层精灵吗？你知道辛德拉古吗？"
D.Strings[7120]="我对上层精灵知之甚少，对辛德拉更是一无所知。"
D.Strings[7121]="辛德拉古是艾萨拉女王最器重的奥术学家。女王最重要的物品都在这些高大的城墙内秘密制造完成。$B$B永恒之井被破坏后，上层精灵陷入浑浑噩噩的境地，一支较小的暗夜精灵氏族，埃雷萨拉斯的王子托塞德林开始建造水晶塔，你可以在西侧的城墙那儿看到那些分散在各处的水晶塔。"
D.Strings[7122]="王子策划将拥有巨大力量的恶魔伊莫塔尔禁锢到一个巨大的力场中。水晶塔能将潜在的能量汇集到这个力场中。$B$B一旦被囚禁，恶魔将成为埃雷萨拉斯人民的能量来源。"
D.Strings[7123]="真令人着迷啊。请继续。"
D.Strings[7124]="汲取的能量能维持上层精神的魔力，使埃雷萨拉斯的人民满足他们对魔法无尽而持续增长的渴求。$B$B数千年过去了，用于监禁恶魔伊莫塔尔以及维系埃雷萨拉斯人民生命的力量开始减弱。监禁恶魔所需的魔法就要超过所能汲取的魔法。曾经的能量机制已经不复存在。"
D.Strings[7125]="我要杀一些东西，是吗？"
D.Strings[7126]="你所见到的那些在埃雷萨拉斯的庭院和城墙附近游荡的上层精灵灵魂不是被戈多克食人魔或萨特所杀，而是死于王子之手！"
D.Strings[7127]="我们生活在无尽的悲剧中。"
D.Strings[7128]="王子为了获得永恒的生命和无尽的力量，杀死了许多人。数千人的力量全部汇集到王子和辛德拉狂热者身上。那些少数的幸存者不停地向水晶塔输送能量来禁锢恶魔伊莫塔尔。$B$B如果恶魔挣脱束缚，它一定会毁掉这座曾经繁荣辉煌的魔法都市。"
D.Strings[7129]="很悲伤的故事。谢谢你，灵魂。"
D.Strings[7130]="卑微的家伙，你现在是个男人啦！"
D.Strings[7131]="我是，是吗？芬古斯，你给戈多克大王的新门徒带来了什么？"
D.Strings[7132]="卫兵芬古斯令你变得凶残！疯狂！啊！"
D.Strings[7133]="你可找到我啦，头儿！斯里基克陷入的大块的冰块中！好在我动作敏捷，很快就逃了出来！哈哈！$B$B或许冰块很快就会融化……"
D.Strings[7134]="是，你真是个笨蛋。斯里基克，你认为自己有多聪明？"
D.Strings[7135]="头儿，我会让你看看我有多聪明的！有了这些强大的魔精，你会更聪明的！$B$B嗯……我应该用在自己身上……"
D.Strings[7136]="你是戈多克的国王！你是至高无上的王！"
D.Strings[7137]="叫我“国王”。你为我带来了什么！"
D.Strings[7138]="我听说你已经死啦……嗯，以后你想要装死的话就不那么容易啦！"
D.Strings[7139]="你好，诺特——我是制皮师。你能教我怎么制作食人魔套装吗？"
D.Strings[7140]="你好，诺特——我是裁缝。你能教我怎么制作食人魔套装吗？"
D.Strings[7141]="我想我能教你。你也许只能在这儿找到食人魔鞣酸，但是你几乎可以在任何地方找到其他东西。"
D.Strings[7142]="我统治这个王国已经有一万年啦。在那时，我从那些神圣的辛德拉家族成员那儿听到很多令人着迷的故事。$B$B由于我必须呆在这儿，所以我常常和访问者沟通交谈。你可以为我讲个故事吗，或许你想听听我的故事？"
D.Strings[7143]="谁敢破坏埃雷萨拉斯的圣洁？懦夫，面对我！"
D.Strings[7144]="我们可不能惹恼了他。他发起火来就没有节制啦。"
D.Strings[7145]="陌生人，把你的声音放小一点。你不是想打扰主人的沉思吧。"
D.Strings[7146]="许多人来到这个避难所，少数人却离开了。"
D.Strings[7147]="他真的死了。你成了新国王……嗯，就是你！戈多克是你的啦，国王！你应该跟我谈谈，了解这儿的一切！我是……我是他的助手！是的，这就是我为什么被称为狡猾的家伙的原因！"
D.Strings[7148]="博学者是个古老的学者。他为我们伟大的女王服务！"
D.Strings[7149]="%s低声咆哮着警告附近的盟友，看来是被激怒啦！"
D.Strings[7150]="%s酒醉后变得狂暴起来！"
D.Strings[7151]="嘿，芬古斯说谁是恋豺狼人癖？！把囚犯交给国王吧，他们携带着武器，对国王来说是个威胁。我倒要看看当我把芬古斯打趴下的时候他还敢说什么！哈！"
D.Strings[7152]="没有人能打败我，没有人敢威胁国王！死吧！"
D.Strings[7153]="你在附近闲逛什么？为什么不把那些小家伙锁起来？！"
D.Strings[7154]="现在你变得强大了！向戈多克的新国王致敬！"
D.Strings[7155]="嗯，我要把这些人带到国王那里去听候发落。"
D.Strings[7156]="为什么他们身上还有武器？你为什么不拿走他们的武器？！"
D.Strings[7157]="呃……我就是这样找到他们的。我想告诉国王他们是个威胁！我跟你说啊，头儿……我无意中听到卫兵芬古斯说你是个肥胖无用的恋豺狼人癖！"
D.Strings[7158]="好吧，芬古斯，你什么意思？！你敢叫我恋豺狼人癖，看我一锤打得你找不到北！"
D.Strings[7159]="尘归尘，土归土！"
D.Strings[7160]="感受萨弗隆的烈焰吧！"
D.Strings[7161]="这些是指令，$n。请迅速将它们交给霜狼突击队队长!"
D.Strings[7162]="这是指令，$n。现在快将它们交给指挥官特拉瓦雷吧！"
D.Strings[7163]="萨纳瑞恩，我把捕兽器弄丢啦。你能再给我一个吗？"
D.Strings[7164]="指挥官特拉瓦雷在哪儿？"
D.Strings[7165]="突击队长加瑞克在哪儿？"
D.Strings[7166]="一旦我们拥有充足的物资供给，指挥官特拉瓦雷就会前往征战平原，驻守在我们最南端的弩车附近。"
D.Strings[7167]="一旦我们拥有丰富的物资供给，霜狼突击队队长就会驻守在冰血要塞以北的征战平原，就在攻城机旁边。"
D.Strings[7168]="霜狼军需官在哪儿？"
D.Strings[7169]="雷矛军需官在哪儿？"
D.Strings[7170]="雷矛军需官将物资存储在雨棚下，就在这儿以西的地方。"
D.Strings[7171]="霜狼军需官就在这个工事的东面。进入碉堡，从右边的出口出去，不远处你就可以看到军需官。"
D.Strings[7172]="追随者？贡品？"
D.Strings[7173]="当国王真好！现在，让我们继续谈谈你刚才说的事儿……"
D.Strings[7174]="嗯，你杀死了国王，是吗？这就是说你取代了他的位置。你成为了新的头目！向国王致敬！"
D.Strings[7175]="哦，真恐怖！这是个悲剧！我们就要突破啦，但也有可能遭遇全军覆灭的惨剧。"
D.Strings[7176]="呃……很抱歉我袭击了你。不要杀我，求你了！？你是国王啦，我会为你提供更多的贡品的！"
D.Strings[7177]="粗略地检查一下骸骨，上面的肉已经干枯了。真是令人毛骨悚然的场景。"
D.Strings[7178]="我很怀疑他有什么话可说，陌生人……"
D.Strings[7179]="我个人并不在意他。王子从未如此对待过他领地中的高等精灵。唉，我还没资格质疑王子。不过至少,他并没有立即把温萨鲁斯烧成灰。"
D.Strings[7180]="我们再也不想得到什么关注啦，陌生人。回到那些让你来找失踪的管理员的家伙那儿去吧，告诉他们什么都找不到。然后回到我这儿来，我会告诉你一个失传的秘密。"
D.Strings[7181]="向阵亡者默哀。"
D.Strings[7182]="面对战争，我们的军队泰然自若，誓与联盟展开血战。我们的队长很久就会进入冰血要塞，战争即将展开！"
D.Strings[7183]="那么，现在我是国王啦……你给我带来了什么？！"
D.Strings[7184]="从可怕的上层精灵王子那儿取回戈多克的遗物，或许你能比老头目做得更好！"
D.Strings[7185]="那么……这附近没有什么箱子了，你要知道，在戈多克食人魔眼里，护手是一件无价的神器？"
D.Strings[7186]="愚蠢的家伙，即使我这么做了，你认为我会让你轻易得手吗？你要得到这东西——如果我确实有这东西的话——你只能从我冰冷的手指中把它抢走。$B$B我的朋友，这种事情是不可能发生的。"
D.Strings[7187]="向新国王致敬！"
D.Strings[7188]="在你成为新国王之前，我曾对你横眉竖眼……嗯……我那是在开玩笑。$B$B是的！"
D.Strings[7189]="其他的食人魔居然攻击你，他们太笨了，国王！这就是我还活着的原因——我既聪明又结实！"
D.Strings[7190]="我们可比塔纳利斯的食人魔干净多了。那片沙漠中到处都是食人魔。这儿可不是，$g先生:女士;！"
D.Strings[7191]="只要你跟我们呆在一起，你就是国王。你离开的话，会有其他食人魔取代你的位置的。这就是戈多克的行事之道！"
D.Strings[7192]="我很聪明！我知道二加二等于五！"
D.Strings[7193]="老国王死了吗？那不可能！"
D.Strings[7194]="国王陛下，我可没有给你带来什么麻烦。"
D.Strings[7195]="哦，亲爱的，“防御圣典”在哪儿？莱德罗斯会勃然大怒的。"
D.Strings[7196]="“奥术学家的食谱”也不见啦！这真是一场灾难！"
D.Strings[7197]="最近书本丢失甚多。博学者和他的助手非常恼怒。他们怀疑在埃雷萨拉斯有人妄图不轨。"
D.Strings[7198]="王子不再讲述灰烬使者的故事了吗？在他的诸多故事中，我们最喜欢这个。他的爱好则是寻找灰烬使者的下落。当然，没人能从他口中得知那个故事。"
D.Strings[7199]="我猜想那些小鬼在偷学知识。"
D.Strings[7200]="王子对奈法利安的巢穴非常感兴趣。如果有谁能杀死巨龙及其属下，并将战斗经过告诉王子，我敢打赌王子会非常满意的。找到灰烬使者之日可待啦！"
D.Strings[7201]="你不跟米兹勒谈话的话是当不了国王的！跟他谈谈！"
D.Strings[7202]="那么……你杀死了国王？我就知道这些家伙会拥戴你成为新国王的。我就知道！那些家伙只知道力量。$B$B似乎你赦免的跟随者越多，献殷勤的人也就越多。别这么不公平——我是说来一次有趣的挑战。如果你离开，我可不希望继续当国王。这些家伙肯定有人趁机取代你的地位。$B$B还有……你找到了我的钥匙，是吗？"
D.Strings[7203]="国王死了——哦，不！召唤米兹勒！他知道下一步该怎么做！"
D.Strings[7204]="你必须明白，像我这样活了一万年的人，对生命有独特的看法。眼下你经受的考验和磨难都是毫无意义的。"
D.Strings[7205]="哦，年轻的主人制造的这一系列事件和慌乱。可以想象，世界的命运就掌控在他手中。只有人类才会对世界产生这种扭曲的看法。$B$B唉，他将奥术的秘密都告诉了我……圣契之类的无用之物。这种东西对我来说是一无是处，但是或许你对它们感兴趣。"
D.Strings[7206]="“迦罗娜：潜行与诡计研究”在哪儿？必须找到它！"
D.Strings[7207]="被偷啦，$r！我们最珍贵的三卷卷轴。如果你能找回来的话，一定会得到丰厚的报酬的。"
D.Strings[7208]="%s开始反击，展开报复！"
D.Strings[7209]="帮我粉碎这些微不足道的家伙！"
D.Strings[7210]="我是这么想的！"
D.Strings[7211]="这听起来是个值得去做的任务！"
D.Strings[7212]="别向我挑战，矮小的家伙！现在我是国王啦，永远都是！！！"
D.Strings[7213]="<你无法理解这份卷轴上记载的任何技术。>"
D.Strings[7214]="<羊皮纸上画着的是修理机器人的结构示意图。>"
D.Strings[7215]="<将这份结构示意图复制到你的工程学书本中。>"
D.Strings[7216]="<依你目前的工程学技能是看不懂这张复杂的结构示意图的。>"
D.Strings[7217]="<你精通制造和操作这个机器人。>"
D.Strings[7218]="世界的构造精妙细致。只靠某些知识和对已知知识的应用是不可能破坏世界构造的。裂缝也由此产生。"
D.Strings[7219]="%s察觉到你的存在，打开了虚空之门！"
D.Strings[7220]="克鲁什死啦！现在你也去死吧！"
D.Strings[7221]="部落的人民，奥格瑞玛的居民，来吧，聚集在一起，欢庆部落英雄的诞生！今天，$n给予了黑龙军团致命的一击。龙巢之母——奥妮克希亚已经被斩杀了！"
D.Strings[7222]="见证酋长的勿庸置疑的能力吧！在屠龙大军的战斗口号声中精神抖擞地前进吧！"
D.Strings[7223]="盯着敌人，$r。看吧，强大的部落足以对付巨龙！所有跟我们做对的人都是这种下场！"
D.Strings[7224]="我们都是部落的一份子。牛头人，兽人，巨魔以及其他所有种族。永远别忘了，我们都是部落的成员。"
D.Strings[7225]="暴风城的城民和盟友们，今天，有人创造了历史。$n已经杀死了那个妄图篡夺王权的家伙。都聚过来吧，跟我们一起庆祝英雄的诞生。"
D.Strings[7226]="看看强大的联盟吧！奥妮克希亚的徽记悬挂在拱门之上！让我们为屠龙大军高声欢呼吧！"
D.Strings[7227]="我活着就是为了为国王服务。"
D.Strings[7228]="或许有一天，你对联盟的贡献会跟你今日所见的英雄一样伟大。尊重英雄吧，$n。"
D.Strings[7229]="主人，您的到来令我们倍感荣幸。"
D.Strings[7230]="它会教你如果挑选草药的，$r。"
D.Strings[7231]="神圣的母牛！姆斯高格就在厄运之槌里。"
D.Strings[7232]="看那边！有人在跟姆斯高格打斗！"
D.Strings[7233]="在厄运之槌那儿的是拉扎尔吗？这可真令人激动！"
D.Strings[7234]="喔！他们进去啦！"
D.Strings[7235]="拉扎尔给姆斯高格带来了更多的肥料！"
D.Strings[7236]="重要的决斗即将开始！无敌的斯卡尔就在巨槌竞技场！"
D.Strings[7237]="似乎斯卡尔已经找到了下一个挑战者！想取代他的位置吗！"
D.Strings[7238]="弗雷瑟倒下去啦！弗雷瑟倒下去啦！弗雷瑟……嗯？那不是弗雷瑟？"
D.Strings[7239]="拥有万年历史的知识卷轴将那些邪恶的家伙吸引到图书馆。大量的书籍被盗，被找回之后再次被盗。"
D.Strings[7240]="基尔达斯总是过分夸大。比如，“迦罗娜：潜行与诡计研究”已经被偷过400多次啦。$B$B神殿的标志保护着这本卷轴，防止任何人偷看。"
D.Strings[7241]="他们什么时候才能吸取教训？"
D.Strings[7242]="愚蠢！你没有学过杜威十进制吗？至少你也已经为我们工作3000年啦！无能的家伙。"
D.Strings[7243]="我不会受到引诱离开这儿的。"
D.Strings[7244]="<莱德罗斯将手伸进他的长袍，拿出一把又盾又扁的精灵刀。>$B$B在过去，在远古战争之前，他们就是用这把刀来求生的。"
D.Strings[7245]="真令人着迷啊，博学者。请继续。"
D.Strings[7246]="在仪式中，必须使用守护者的后代来锻造这柄剑。真是少见啊……龙不得不锻造并为这柄剑附魔，还得牺牲自己的后代做为附魔的调和剂。"
D.Strings[7247]="（继续。）"
D.Strings[7248]="8,000年来只铸造出少量的剑——每柄剑的威力和外观都是独一无二的。奎尔赛拉之剑将沿袭其锻造者的特点。"
D.Strings[7249]="在传说中，奎尔塞拉之剑是由一位不知名的铁匠结合了五条守护巨龙的力量锻造而成的。在奈法利安和死亡之翼扰乱我们的世界之前，守护巨龙的聚会被称为“五色集会”。看起来五色圣剑奎尔塞拉是他们最为显赫的创作之一。"
D.Strings[7250]="我能给你的只有这把未经烧制、未经加工的刀刃——最原始、最基本的形态。$B$B现在你只需去找一条愿意为这把刀附魔的龙。$B$B如果你能长生不老的话，或许这还有可能；但是你是凡人，随时都可能命丧黄泉，我建议你试着找体型较小的龙来帮你完成这把剑。"
D.Strings[7251]="你听说过黑龙公主吗？我想她名叫奥妮克希亚……"
D.Strings[7252]="或许吧……我现在能做什么呢？"
D.Strings[7253]="我可没时间停下来。"
D.Strings[7254]="雷克斯洛特，我把瑟银镣铐弄丢了。"
D.Strings[7255]="纳萨诺斯，我把腐烂的苹果弄丢啦。我需要一个。"
D.Strings[7256]="医生，我把解药弄丢啦！再给我一些！！！"
D.Strings[7257]="瑟尔格，我把赞吉尔之触的解药弄丢了！帮帮我！"
D.Strings[7258]="你听说过一个名叫厄运之槌的地方吗？"
D.Strings[7259]="是的，我知道它真正的名字——埃雷萨拉斯。许多许多年前，那儿曾是暗夜精灵的魔法研究基地。$B$B你知道埃雷萨拉斯吗，年轻的$c？也许有人会说这跟我目前的处境很巧合……但是我可不相信巧合这回事。"
D.Strings[7260]="拉比恩，你为什么说这是个巧合？"
D.Strings[7261]="塞纳里奥议会的人已经了解到埃雷萨拉斯的近况了。我陷入了僵局，不知如何是好。我很可能要向那些体格强健、善于作战的冒险者寻求帮助。$B$B但是，要对埃雷萨拉斯采取行动，就要了解关于丰饶之果的知识。"
D.Strings[7262]="丰饶之果？"
D.Strings[7263]="多年前，埃雷萨拉斯是魔法师的集中地，居住在那些神圣的大厅中的人都能使用强大的魔法。米琳丝特·塞雷恩就是这样一名暗夜精灵——她是个博学者，她可以将大自然的力量灌输到她铸造的神器中。$B$B丰饶之果就是她的杰作……她利用特殊的月亮井制造出一种奇异的、具备保护和生长效力的藤蔓来。埃雷萨拉斯在藤蔓的滋养下日益繁华起来。"
D.Strings[7264]="但是，有些事情好像出了差错，是吗？"
D.Strings[7265]="唉，事情似乎总是这样。和塞纳里奥议会的其他人一样，我也认为米琳的杰作在上古战争时就被毁掉了。但是我最近认识到，这种观点是错误的。$B$B丰饶之果并未被摧毁……尽管现在它被称为魔藤。它被埃雷萨拉斯的恶魔领主，荒野变形者奥兹恩污染了。"
D.Strings[7266]="如果丰饶之果——或者说是魔藤——完全堕落，那会发生什么事呢？"
D.Strings[7267]="我……我无法想象，$n。我只知道我不能让这件事发生。它必须被摧毁的——就算不是为了阻止那些恶魔，也要为了米琳丝特·塞雷恩……米琳……$B$B我的朋友，这就是我希望你伸出援手的事情。"
D.Strings[7268]="跟我谈谈，$n——如果你愿意的话，塞纳里奥议会很乐意接受你慷慨的帮助。埃雷萨拉斯的魔藤已经对我们造成了非常大的威胁。"
D.Strings[7269]="<德米提恩跪倒在地。>$B$B你已经找回了主人的牢笼！$B$B我期待这一天已经很久很久了，我的愿望终于实现了。$B$B必须解放我的主人！"
D.Strings[7270]="我要做些什么？"
D.Strings[7271]="我这里有他的重生之瓶。如果你决心接受这项任务，就必须保护好这只小瓶，并击败拉格纳罗斯！"
D.Strings[7272]="炎魔之王和所有胆敢挡住我去路的家伙，都将尝到我的愤怒。"
D.Strings[7273]="必须使用源质对重生之瓶进行加固。我只知道这种矿物的一种原料：位于这个世界核心中的元素领域。$B$B塑地者对这种东西的了解比我多得多。你必须找到塑地者！"
D.Strings[7274]="向你致敬，英雄！我有来自大陆和岛屿的最新消息，供你参考。"
D.Strings[7275]="我得去找找那个什么塑地者。是什么精华？"
D.Strings[7276]="你必须摧毁拉格纳罗斯的肉身，他的精华将在尸体的残骸中出现。在他极度虚弱的时候，他对桑德兰的控制将被大大减弱。精华本身就是一把钥匙……"
D.Strings[7277]="大人，请把复生之瓶给我。"
D.Strings[7278]="你需要去尘泥沼泽找纳特·帕格接受训练，提高自己的能力。"
D.Strings[7279]="我可以教你一些钓鱼技能。"
D.Strings[7280]="你的挑战失败了！"
D.Strings[7281]="我该去哪儿提高自己的开锁技能？"
D.Strings[7282]="海浪将船只残骸中的许多上锁的箱子冲到了位于湿地米奈希尔海湾以北的蓝腮沼泽中。"
D.Strings[7283]="凄凉之地北部萨瑟里斯海岸和荒芜之地苦痛堡垒都有可以拾取的带锁的箱子。"
D.Strings[7284]="悲伤沼泽泪水之池有许多带锁的上个世纪丢失的盒子。"
D.Strings[7285]="灼热峡谷熔渣之池的黑铁矮人有许多带锁的箱子。"
D.Strings[7286]="塔纳利斯的落帆海湾和艾萨拉的风暴海湾都有许多上锁的箱子，打开之后即可提高你的技能。"
D.Strings[7287]="东瘟疫之地蒂尔引领的血色十字军有许多带锁的箱子，这对你的技能可是个挑战。"
D.Strings[7288]="兽人将许多带锁的物资箱沉入了赤脊山的止水湖。"
D.Strings[7289]="在纳迦侵袭灰谷佐拉姆海岸时，许多带锁的物资箱都丢失啦。"
D.Strings[7290]="以石爪山脉狂风峭壁为基地的风险投资公司将他们的物资存储在带锁的箱子里。"
D.Strings[7291]="辛迪加工会在希尔斯布莱德的敦霍尔德城堡有许多带锁的箱子。"
D.Strings[7292]="干得好，我的仆人。我被关押在炎魔之王的监狱里已经很久了，现在我终于又自由了！让这个世界再次感受逐风者的强大力量吧！"
D.Strings[7293]="啊，就让那个放我出来的蠢货首先成为我的祭品吧。"
D.Strings[7294]="我拥有无穷的力量！这些愚蠢的凡人居然企图进入我的领域！"
D.Strings[7295]="<德米提恩笑了。>$B$B愚蠢的家伙，你的奖励就是痛苦地死去！"
D.Strings[7296]="蠢货，让你那胆怯的主人出来！让他面对我！"
D.Strings[7297]="我研究这个世界上的已知和未知的元素。"
D.Strings[7298]="你是能制造出源质的塑地者吗？"
D.Strings[7299]="源质？我已经很久没有听过这个词从一个凡人口中冒出来了。"
D.Strings[7300]="弗兰扎尔，你对此了解多少？"
D.Strings[7301]="克里希克是我以前的一个学生，他耗费了一生的时间尝试与被封锁在地狱中的神灵进行沟通。他研究那些能够让毫无生机的土地上变为沃土的东西……只有通过元素之间的剧烈碰撞才能创造出来的东西。$B$B凡人把这种东西称为源质。$B$B大约在十年前的某一天，克里希克的研究工作使这片峡谷裂开了。"
D.Strings[7302]="裂缝？"
D.Strings[7303]="是的，他完成了几乎不可能完成的任务。塞拉赞恩的使者从裂缝中跳了出来！$B$B在我看来，那个地精已经能够和上古之神的使者交谈了。此后发生的事情非常恐怖……"
D.Strings[7304]="裂缝闭合了，克里希克死了！完全被海水吞没了！$B$B你要小心，$r，你所期望的事情很可能成为你不愿意看到的事情。你所面对的是比事件本身还要古老的生物和魔法！$B$B如果克里希克还活着，如果他知道你要找的讯息，你是不用指望他会告诉你的。他所经历的远远比你想象的要多。"
D.Strings[7305]="我们陷入生存危机。我们陷入困境，寻找答案，希望在黑暗中闪闪发光。$B$B那时，$n，就是我们迈向自由的第一步。"
D.Strings[7306]="你有蜘蛛或是甲虫吗，$c？它们速度很快，但是如果你的速度更快的话，你会发现拥有它们是件乐事！"
D.Strings[7307]="戈瑟奇，我想买点东西。"
D.Strings[7308]="你刚从地下城出来吗？有什么东西给我的吗？"
D.Strings[7309]="你的护甲看起来很破旧。你为此感到胆怯吗？"
D.Strings[7310]="我不允许你进入神庙！我会摧毁你的！"
D.Strings[7311]="一旦我被召唤出来，就会有人牺牲，凡人。"
D.Strings[7312]="如果我要落入地狱，那么你们这些凡人也要跟我同去！"
D.Strings[7313]="在宝珠的控制力消失的瞬间，%s逃走了。"
D.Strings[7314]="我长大后想成为暴风城的王！"
D.Strings[7315]="我以前去过铁炉堡。那儿闻起来怪怪的。"
D.Strings[7316]="蘑菇总是生长的阴暗的地方，因此它们长得像雨伞。"
D.Strings[7317]="如果罩衫是由顶部的摁扣固定的，那为什么还需要袢带呢？"
D.Strings[7318]="要是你的鼻涕在鼻子里结冰了怎么办？"
D.Strings[7319]="鱼不会口渴吗？"
D.Strings[7320]="如果你想要失败，但是却成功了，你做了什么？"
D.Strings[7321]="要是你真是部落的英雄，我想看看你屠龙！啊！"
D.Strings[7322]="当闪电击中海洋的时候，为什么所有的鱼都没有死？"
D.Strings[7323]="没有翅膀的鸟可以被称为步行生物吗？"
D.Strings[7324]="我的鼻子里有块石头。"
D.Strings[7325]="要是海龟没有壳的话，那不就成无家可归或是裸体啦？"
D.Strings[7326]="“咔咔”是什么意思？"
D.Strings[7327]="要是你的手套太大的话，还算是合手的手套吗？"
D.Strings[7328]="你离家还远着呢，$r。"
D.Strings[7329]="戴奥，我是来学习的。"
D.Strings[7330]="你来了。你是来学习镇压和控制之道的吧。$B$B我会教你更多的东西……你将学会牺牲。$B$B<戴奥咧嘴而笑。>"
D.Strings[7331]="我要牺牲什么？"
D.Strings[7332]="你得选择自己要召唤和驱使的恶魔。我们运用黑暗力量并为此付出巨大的代价。"
D.Strings[7333]="要怎么召唤恶魔？"
D.Strings[7334]="要是你还想继续前进的话，我们必须首先找人对付野兽。"
D.Strings[7335]="我已经夺回了控制权！大家都回到自己的岗位上去！"
D.Strings[7336]="这就是啦。我能感觉到！这可真是个大家伙！"
D.Strings[7337]="振作起来，迎接挑战！"
D.Strings[7338]="把我踢出去，他们会吗！？我会让暴风城中这些愚蠢的家伙见识见识尼比的力量！等着瞧！"
D.Strings[7339]="%s怀着挫败的心情挥舞着拳头。"
D.Strings[7340]="尼比，你真蠢。"
D.Strings[7341]="我的天，我太惊讶了！又一次失败啦！？怎么会呢？？"
D.Strings[7342]="主人，你令人感到敬畏。你的不称职令人敬畏。"
D.Strings[7343]="为什么你这个小东西这么做！"
D.Strings[7344]="啊！帮帮我！那些疯狂的侏儒想要杀了我！"
D.Strings[7345]="卑微的家伙，在我面前鞠躬吧！你能感受到我那强大的力量。"
D.Strings[7346]="我在寻找一名强大的术士。"
D.Strings[7347]="这么说，你是来找尼比学习如何从虚空中召唤地域火仆从的。$B$B安静！尼比什么都知道！$B$B他可不会这么轻易地将知识传授给你。首先，你必须帮助尼比完成一项至关重要的任务。"
D.Strings[7348]="什么任务？"
D.Strings[7349]="在这座营地的东北面有一个名叫克罗苏斯的强大的地狱火。这就是尼比待在这儿的原因。克罗苏斯极其强大，前所未闻。你瞧，菜鸟，地狱火以极高的速度坠落在地面上，但是它的生命却很短暂。一旦火焰熄灭，地狱火便崩溃了。"
D.Strings[7350]="别打断我，你这个蠢货！我会把你身上的肉刮下来，把你的骨头做成衣架。我说到哪儿了？哦，对，克罗苏斯的存活时间是普通地狱火的10倍。我不知道为什么会这样，但是我想只要进行足够的研究，我一定可以查明真相。$B$B你必须帮我找到克罗苏斯的火焰核心。"
D.Strings[7351]="我要干些什么呢？"
D.Strings[7352]="要想让我教你召唤地狱火仆从，你必须杀死克罗苏斯，然后从他燃烧的尸体中取出恶魔之核交给我。但是这项任务并不简单，克罗苏斯几乎已经烧尽了。你必须重新点燃他的尸体，令他复活。所以你必须从其它恶魔那儿收集一些东西才能令他复活。$B$B我的孩子，准备上路吧。"
D.Strings[7353]="克罗苏斯活了？克罗苏斯要摧毁一切！"
D.Strings[7354]="退后！退后！与地狱火保持安全距离！"
D.Strings[7355]="向全能的主鞠躬吧！满怀敬畏之情看着我所召唤出来的毁灭一切的地狱……小鸡？"
D.Strings[7356]="%s笑得在地上打滚。"
D.Strings[7357]="尼比，你是个白痴。"
D.Strings[7358]="肃静，仆人们！复仇吧！摧毁暴风城！让他们全军覆灭！"
D.Strings[7359]="萨弗隆铁锭？！？？！不可能！我必须得到它！必须！必须！$B$B$R，我会花大价钱购买铁锭的。或许你会对炎魔拉格纳罗斯之手之谜感兴趣？就是萨弗拉斯，白痴！传说中火元素之王使用的铁锤。"
D.Strings[7360]="嗯，我在听。你出多少价钱？"
D.Strings[7361]="我愿意用萨弗隆战锤的设计图换取一块萨弗隆铁锭。$B$B现在，你大概正在暗自盘算吧，“我要那种战锤来做什么，我现有的装备比这东西高级多了！”$B$B嗯，让我告诉你吧，$g先生:女士;，没有什么武器比萨弗隆战锤更高级了！"
D.Strings[7362]="你吸引了我的注意。"
D.Strings[7363]="你所要做的就是铸造萨弗隆战锤和找到萨弗拉斯之眼。将萨弗拉斯之眼和萨弗隆战锤结合在一起就能成为萨弗拉斯！我不会告诉你任何关于萨弗拉斯之眼的信息。我想你自己能找到的。在这张合约上签字，让我们达成交易。"
D.Strings[7364]="把契约给我。"
D.Strings[7365]="农夫跨过了界线。"
D.Strings[7366]="你胜利了！"
D.Strings[7367]="你失败了！"
D.Strings[7368]="我再次失败了……"
D.Strings[7369]="我现在就回去，我到这儿来无非是再次体验相同的悲惨遭遇罢了。"
D.Strings[7370]="终于结束了……"
D.Strings[7371]="谢谢你，好心的陌生人。我们将永远铭记你的英雄事迹。"
D.Strings[7372]="我的爱人，我们会再次复合的……"
D.Strings[7373]="陌生人，去找战败的王子米奈希尔和他统治的国土。"
D.Strings[7374]="光明的力量如此强大、如此仁慈。"
D.Strings[7375]="痊愈吧！"
D.Strings[7376]="战争是有代价的，$c……这种代价常常被我们忽略。艾泽拉斯大地冲突迭起，到处都是失去双亲的孤儿。那些无家可归的孤儿没有别的地方可去，他们通常在这儿成长，到了自力更生的年龄才离开。$B$B部落将春季的某一周设为儿童周，为这些无辜的孩子赠送物品。"
D.Strings[7377]="卑微的人类——我在这儿！你们的末日到啦！"
D.Strings[7378]="战争是有代价的，$c……这种代价常常被我们忽略。艾泽拉斯大地冲突迭起，到处都是失去双亲的孤儿。那些无家可归的孤儿没有别的地方可去，他们通常在这儿成长，到了自力更生的年龄才离开。$B$B联盟将春季的某一周设为儿童周，为这些无辜的孩子赠送物品。"
D.Strings[7379]="什么？！你不可能打败我！我会回来的！"
D.Strings[7380]="你还没有见识过真正的我，愚蠢的家伙！我最终会毁掉一切的！"
D.Strings[7381]="环形山的居民们，听我说！我是来烧毁这片不洁的土地的！"
D.Strings[7382]="吉安娜女士，这听起来像是个奇怪的请求……但是我正在照顾一个非常害羞的孩子。对他来说，你是个英雄，他想要你的签名。"
D.Strings[7383]="当我从深渊回来的时候你就得付出代价！"
D.Strings[7384]="哎呀……你可真是好人。我听说你是儿童周的志愿者，是吗，$c？嗯，你会受到赞扬的。我们必须记得那些不幸的人——特别是那些孩子。$B$B我很高兴能给他签名。给你。"
D.Strings[7385]="这片被冻结的土地将成为我们的起点。来吧，凡人们，我会让你们痛苦地死去。"
D.Strings[7386]="年轻人，欢迎你来到雷霆崖。在这儿你能卸下负担，享受庇佑。我们欢迎所有的部落居民来到雷霆崖。$B$B我的朋友，灵魂都会来这个神圣的地方复活。尊敬他们吧，这也是尊敬你自己。"
D.Strings[7387]="%s消散在空气中，他的哀号声还在你耳边回荡。"
D.Strings[7388]="%s率领入侵的大军突然从希利苏斯西北方的火场中冲出。"
D.Strings[7389]="血蹄酋长，也许这请求听起来有些奇怪……但是我正在照顾一个非常害羞的孩子。对他来说，你就是个英雄，是他请求我来拿到你的蹄印。"
D.Strings[7390]="啊，毫无疑问，他一定是想要成为一名战士！我想你是来参加儿童周的，是吗？你的行为堪称楷模，其他人必定会以你为榜样的，这令那些疲惫不堪的灵魂倍感欣慰。$B$B我很乐意帮助你和这位年轻的男子。嗯……我要给他提些什么建议呢？听听灵魂怎么说吧，是的……或许是关于吃掉所有蔬菜……"
D.Strings[7391]="看护者之周还没有结束……我能再拿一个孤儿哨吗？"
D.Strings[7392]="你被吓坏啦！我找到你啦！"
D.Strings[7393]="要是你们人类都这么胆小的话，这事儿比我想象的就容易多了！"
D.Strings[7394]="嘿，朋友，这是儿童周！我能帮忙吗？"
D.Strings[7395]="所谓的英雄在哪儿？心里害怕不敢出来玩吗？"
D.Strings[7396]="在守护者之周中成为一名孤儿的导师！哈哈！"
D.Strings[7397]="在守护者之周中成为一名孤儿的导师！为了部落！"
D.Strings[7398]="狂风骤起，%s愤怒的吼叫声从西北方传来。"
D.Strings[7399]="我不会……撒手不管的……"
D.Strings[7400]="如果我能活下来，我一定把杀死阿尔萨斯当做毕生的目标……"
D.Strings[7401]="死亡来临了！我不能继续下去了！我没有什么剩下的了……"
D.Strings[7402]="去银风避难所找珊蒂瑞亚吧。她可以卖给你“中级烹饪教材”。"
D.Strings[7403]="烹饪是我一生的追求，我觉得我们俩有共同的爱好！"
D.Strings[7404]="加基森的迪尔格·奎克里弗对厨艺非常精通。要想提高自己的能力，你就去找他吧。"
D.Strings[7405]="葬影村的乌兰可以卖给你“中级烹饪教材”。如果你想要提高烹饪技能的话，就需要这本书。"
D.Strings[7406]="我可以教你如何烹饪！"
D.Strings[7407]="可怜的孩子，我为你难过。"
D.Strings[7408]="孩子们，停下来！别闹了！"
D.Strings[7409]="孩子们，一切都会好起来的。光明会庇佑我们的！"
D.Strings[7410]="我相信你们这群孩子是我们的未来……"
D.Strings[7411]="孩子们，现在该我照顾你们啦。你们会成长为强壮的部落成员的！"
D.Strings[7412]="别发牢骚了！"
D.Strings[7413]="把这儿打扫干净！我们可不能生活在这么糟糕的地方。"
D.Strings[7414]="要么跟着我，要么去黄金之路。明白吗？"
D.Strings[7415]="现在，只有著名的格里高利·维克托医生能提高你的技能啦。你可以在阿拉希高地的落锤镇找到他。"
D.Strings[7416]="尘泥沼泽蕨墙村的格鲁克卡恩在卖指南书，你需要好好研究它来提高自己的技能！"
D.Strings[7417]="倍受尊敬的古斯塔夫·范沃森医生能进一步训练你。他在塞拉摩的兵营里治疗伤兵。"
D.Strings[7418]="我听说居住在激流堡的德尼布·沃克有一本书，这本书一定能帮助你提高急救技能。"
D.Strings[7419]="我可以教你急救技能。"
D.Strings[7420]="嗯，要开始了，是吗？首先，钟……给你活力！"
D.Strings[7421]="接下来，我会用车轮……来保护你。"
D.Strings[7422]="最终，蜡烛……烧死那些碍手碍脚的家伙！"
D.Strings[7423]="啊，自由！虽然短暂，却如此甜美……"
D.Strings[7424]="$n，我完成了我的职责，我得走啦。祝你好运，$g先生:女士;，记得保持铃铛、书籍和蜡烛一直生效！"
D.Strings[7425]="赞美圣光，终于有人对召唤做出了回应。"
D.Strings[7426]="不过，我必须指出……"
D.Strings[7427]="$n，如果你需要再次执行仪式，只要再召唤我就可以了。随叫随到。"
D.Strings[7428]="那么，我先走了……"
D.Strings[7429]="太多人已经倒下了，牧师。你必须集中精神！"
D.Strings[7430]="亡灵天灾来了！快跑啊！逃命吧！"
D.Strings[7431]="请帮帮我们！王子发狂了！"
D.Strings[7432]="去壁炉谷寻求庇护吧！那是我们惟一的希望！"
D.Strings[7433]="斯坦索姆已经面目全非了！城市变成了一片废墟。王子被仇恨和疯狂……吞噬了……"
D.Strings[7434]="眼睛指引我来到这儿，艾瑞斯。"
D.Strings[7435]="<艾瑞斯点着头。>$B$B这只眼睛见证了许多恐怖和惊奇的事情。$B$B它会显现出观察者理应看到的场景。"
D.Strings[7436]="是说我吗？"
D.Strings[7437]="是的。眼睛绝不会弄错的。$B$B毕竟，你是一名牧师。如果眼睛向你展示了这段恐怖的记忆，那么你肯定是一名强大的牧师。$B$B你是来救赎的，但是你甚至还没有意识到这一点……对吗？"
D.Strings[7438]="艾瑞斯，我真不知道会发生什么。如果你需要我的帮助，我会竭尽全力的。"
D.Strings[7439]="我知道你会的，$n。$B$B我也是一名牧师，与你不同的是，我已经辞世多年了，但是我的灵魂仍停留在此，跟这儿的数千个冤魂一样，我们是被疯狂的阿尔萨斯·米奈希尔王子和他的亡灵军团残忍杀害的。"
D.Strings[7440]="那段历史已经结束了，艾瑞斯。"
D.Strings[7441]="我可没说你是到这儿来救赎你自己的，牧师。你是来解救我和那些在试图逃离斯坦索姆时丧命的无辜者的。$B$B我和那些无辜者的灵魂受到诅咒，被禁锢在这儿忍受无尽的轮回。"
D.Strings[7442]="那么，我能帮什么忙呢？"
D.Strings[7443]="你必须完成我未做完的事情：保护逃离斯坦索姆的农夫。$B$B他们会走向光明，而你必须确保他们的安全。如果死去的人数量过多，我们将继续生活在诅咒之下——你的任务也会失败。$B$B这项任务将检验你学到的所有技能和法术。愿圣光保佑你，$n。"
D.Strings[7444]="你敢干预这家伙的试炼？挑战者必须独立战斗！你会为你的轻率之举付出代价的。"
D.Strings[7445]="谁敢盗走我心爱的坐骑？你会为自己的傲慢付出代价的，凡人！"
D.Strings[7446]="我们得救了！农夫们逃脱了亡灵天灾的魔爪！"
D.Strings[7447]="恐怖战马的灵魂散发出愤怒的气息。"
D.Strings[7448]="啊，我亲爱的朋友们！我在古拉巴什竞技场放了一些宝贝！你们要做的只是去竞技场中央，打开箱子，然后拿到里面的财宝！"
D.Strings[7449]="开始厮杀吧！"
D.Strings[7450]="%s在智慧的审判降临时痛苦地后退！"
D.Strings[7451]="加德纳尔的行事准则是隐晦奸诈。别在这儿探头探脑，$C，否则你的灵魂就会被永远禁锢在此……"
D.Strings[7452]="我想从你这儿买点东西。"
D.Strings[7453]="你这个卑鄙的家伙！我会把你的灵魂变成碎片，让你成为我的小鬼的玩具！"
D.Strings[7454]="滚！我只和恐惧魔王打交道，你没资格来跟我说话！"
D.Strings[7455]="恐惧魔王？你是说魔王贝恩霍勒。他向你问好，并有消息给你……"
D.Strings[7456]="来自贝恩霍勒的消息？是什么消息？他需要伟大的导师和仆人乌拉泰克吗？他需要我吗？"
D.Strings[7457]="不，乌拉泰克。他知道你的秘密。他知道你跟克索诺斯的赫尔努拉斯之间的阴谋。"
D.Strings[7458]="什么？但是怎么可能呢？不！这不可能！我已经很小心了……他不可能知道的！$B$B你撒谎！你撒谎，你欺骗了我，去死吧！"
D.Strings[7459]="叛徒，我可没骗你。魔王贝恩霍勒想要你的命。"
D.Strings[7460]="完成啦。羊皮纸终于做好啦。现在回到戈瑟奇那儿去吧……"
D.Strings[7461]="恐怖战马，你是我的了！你的灵魂已经与我连结在一起了！"
D.Strings[7462]="多么幸福的活着的一天啊！朋友，看看你周围的美景吧。享受自然赋予你的一切！"
D.Strings[7463]="*呜噜噜* *汪* *汪汪*"
D.Strings[7464]="熔岩？朋友，别在意那个。看看你周围吧。享受自然赋予的一切欢乐。"
D.Strings[7465]="每年的这个时候我都会来希利苏斯。这里的气候对治疗我的拇趾囊肿很有帮助。$B$B你应该跟我四处逛逛，朋友。欣赏一下风景什么的。"
D.Strings[7466]="在这么偏远的地方遇到人可真好啊。来吧，跟我一起。让我们用身体互相取暖。"
D.Strings[7467]="军官的休息室"
D.Strings[7468]="去力量谷西边的山顶找找看。"
D.Strings[7469]="我知道你是摧毁者阿托留斯。恶魔，现身吧！"
D.Strings[7470]="你要去传说大厅？它就在西边的力量谷上边。"
D.Strings[7471]="侏儒？真可怜。面对我吧，恶魔！"
D.Strings[7472]="这么说你是疯狂的克林弗兰？真不幸，我所期望的是一次真正的挑战。你敢以真面目视人吗？"
D.Strings[7473]="我可不会受你的魅惑。去死吧。"
D.Strings[7474]="突然之间，你成为了“联盟的保卫者”，是吗？！嗯，我猜你一定是想去勇士大厅。大厅就在旧城区。"
D.Strings[7475]="在旧城区的东南角落，你可以找到勇士大厅。"
D.Strings[7476]="%s嘲笑你那愚蠢的请求。"
D.Strings[7477]="如你所愿，$c。"
D.Strings[7478]="我看起来像个傻子吗，凡人？因为只有傻子才会留在这儿，跟你和你的盟友交战。或许下一次……你会有勇气收回嘲讽的话。"
D.Strings[7479]="%s被毒针沉默了。"
D.Strings[7480]="%s在巨大的轰隆声中挣脱锁镣！"
D.Strings[7481]="仪式正在进行中。"
D.Strings[7482]="$n，我得在这些野兽吃掉我之前离开这儿！"
D.Strings[7483]="%s被拉回了克索诺斯世界！"
D.Strings[7484]="啊，我们到了！让我们开始工作，好吗……？"
D.Strings[7485]="哦，对！就在这儿……"
D.Strings[7486]="现在……最后一步！"
D.Strings[7487]="我会满意的，$c。"
D.Strings[7488]="%s在光明的审判降临时痛苦地后退！"
D.Strings[7489]="%s在公正的审判降临时痛苦地后退！"
D.Strings[7490]="%s在正义的审判降临时痛苦地后退！"
D.Strings[7491]="跟着我吧，圣骑士。我制造马饰比我喝矮人烈酒要快。嗯……烈酒。"
D.Strings[7492]="%s将符文布、草药和圣水装配成马饰。"
D.Strings[7493]="%s将奥金镶入马饰。"
D.Strings[7494]="嗯，这能应该就行了。来吧，回到商店，完成我们的交易！"
D.Strings[7495]="要是你是来找世界上最富经验的工匠，你就找对地方啦！$B$B格瑞曼德·艾尔默，愿为你效劳！"
D.Strings[7496]="占卜师将%s从黑暗中拽了出来！"
D.Strings[7497]="你敢向我挑战？准备面对无尽的恐惧吧。"
D.Strings[7498]="%s觉察到你那畏头畏尾的战争策略，从战场上仓惶逃走了。"
D.Strings[7499]="够了——结束吧！你们这些蠢货的骨头也将成为我的收藏品！"
D.Strings[7500]="%s被固定了。"
D.Strings[7501]="%s饮下了剧毒的毒药。"
D.Strings[7502]="软弱的家伙，你的灵魂是我的了。"
D.Strings[7503]="要召唤恐惧战马，你必须首先开启一道强大的法阵。通往克索诺斯世界的传送门只可能在这种法阵中打开。$B$B而开启法阵，你就需要三种魔法器具：达斯莫拉的铃铛、黑色战车之轮和末日蜡烛。"
D.Strings[7504]="你的准备工作已经完成了。现在挡在你和你的恐惧战马之间的就只有开启强力召唤法阵、束缚恐惧战马灵魂的仪式。"
D.Strings[7505]="戈瑟奇告诉我说你带来了他需要的所有东西：达斯莫拉的铃铛、黑色战车之轮和末日蜡烛。$B$B干得好，$n！你差不多可以执行仪式，拥有一匹恐惧战马了！"
D.Strings[7506]="你好，$n。你对魔法的研究进展得怎么样啦？你解开了黑暗的秘密了吗？"
D.Strings[7507]="梅丽德丝，请问我能再要一些魔法粮草吗？"
D.Strings[7508]="%s的皮肤闪着微光，它畏缩了。"
D.Strings[7509]="啊……英雄们。你们都会坚持不懈的，是不是？你们这群凡人想要与我的力量相抗衡——那么你们就要付出代价。现在他将为我而战……他的任务就是干掉你们。"
D.Strings[7510]="啊！没有比看人们在竞技场中互相厮杀更好看的东西了。如果你来得是时候的话，那你也将是他们中的一员！"
D.Strings[7511]="不要打断我。"
D.Strings[7512]="光滑的地面让你无法站稳。"
D.Strings[7513]="是的，那是真的，我好像一只蝙蝠一样瞎了！而且还醉得……呃，醉得好像喝了很多酒。$B$B我会告诉这个感受的，$r。是酒让我感觉灵敏。人人都知道如果你丧失了一种感觉，那么另外一个感觉会变得更加灵敏。我的饮酒感觉这两天非常灵敏。"
D.Strings[7514]="有人偷走了我们的东西！"
D.Strings[7515]="我们不会让这种疯狂行为不受到惩罚的！"
D.Strings[7516]="$n获得了部落军旗！"
D.Strings[7517]="$n获得了联盟军旗！"
D.Strings[7518]="旗帜被重新放置在了它们的基地中。"
D.Strings[7519]="联盟的旗帜被$n拔起了！"
D.Strings[7520]="联盟的旗帜被$n丢掉了！"
D.Strings[7521]="$n掉落了部落军旗！"
D.Strings[7522]="$n拾起了部落军旗！"
D.Strings[7523]="$n将联盟军旗放回到旗座上了！"
D.Strings[7524]="$n将部落军旗放回到旗座上了！"
D.Strings[7525]="小偷！无赖！恶棍！来尝尝我的大枕头的滋味吧！"
D.Strings[7526]="我们选择了离开黑石深渊的保护出来探险……呃，我是说……嗯，我们这么做是对的，我们要探索整个世界。"
D.Strings[7527]="你们的末日已经来了！"
D.Strings[7528]="凡人，趁现在还有机会，赶快逃跑吧！"
D.Strings[7529]="只有傻瓜还会继续战斗。再见了，懦夫。"
D.Strings[7530]="嗨，你！旅行者！到这里来挣些钱吧！"
D.Strings[7531]="有没有什么好玩的东西卖，索尔宾？"
D.Strings[7532]="博恩奈特是我的名字，我把铁匠作为我的兴趣……另外，呃……我还卖一些食物和水。来点肉类怎么样？"
D.Strings[7533]="很高兴再见到你，$n！我不知道我还可以坚持多久来创建这样一个店。现在，由于你对我的帮助，我会给你看一些你会感兴趣的东西！"
D.Strings[7534]="当洛洛尔不想撒掉他宝贵的酒或者弄脏他衣服的时候，我就被召唤而来。是的。汉瑟尔就是别人口中正义和痛苦的结合体。"
D.Strings[7535]="现在雷矛部族的将军被击败了，我们可以派出一些军队来驻守冰斧要塞。但是我们还是要保持警惕，$c，联盟会回来的。$B$B当你在周围看到他们在偷偷摸摸活动的时候，好好教训他们一下吧！"
D.Strings[7536]="现在霜狼氏族的将军被击败了，我们可以派出一些军队来驻守冰斧要塞。$B$B但是我们还是要保持警惕！我们要小心那些部落的入侵者……"
D.Strings[7537]="作为驻扎在这里的工头，我的职责就是确保在这里所进行的所有事情，从工作到休息和放松都包含着一定的令人厌烦的成分。$B$B如果你发现某件你被要求去做的事情过于简单或者没有什么好抱怨的话，请立即向我报告。"
D.Strings[7538]="你已经完成我要求你做的事情，$n。我这里没有什么需要你做的了。如果你想继续为瑟银兄弟会服务的话，和黑石深渊的黑铁酒吧的罗克图斯·暗契谈谈。$B$B再见！"
D.Strings[7539]="我发誓……如果奎恩提斯胆敢再乱栽食虫花，我就马上把他的树给砍了。"
D.Strings[7540]="小心！$r$n正在攻击冰斧要塞！"
D.Strings[7541]="不管我是不是瑟银兄弟会的，只要有个黑铁矮人敢靠近我，我一定会让他们尝尝我的厉害！现在，你想去哪里呢，$g小伙子:小姑娘;？"
D.Strings[7542]="嘿，普拉特——你能再教我一下如何制作蛮皮战靴吗？"
D.Strings[7543]="嘿，普拉特——你能再教我一下如何制作蛮皮披风吗？"
D.Strings[7544]="嘿，普拉特——你能再教我一下如何制作蛮皮外衣吗？"
D.Strings[7545]="嘿，普拉特——你能再教我一下如何制作蛮皮护肩吗？"
D.Strings[7546]="嘿，普拉特——你能再教我一下如何制作蛮皮护腿吗？"
D.Strings[7547]="嘿，普拉特——你能再教我一下如何制作蛮皮头盔吗？"
D.Strings[7548]="嘿，杉多尔——你能再教我一下如何制作蛮皮战靴吗？"
D.Strings[7549]="嘿，杉多尔——你能再教我一下如何制作蛮皮披风吗？"
D.Strings[7550]="嘿，杉多尔——你能再教我一下如何制作蛮皮头盔吗？"
D.Strings[7551]="嘿，杉多尔——你能再教我一下如何制作蛮皮护腿吗？"
D.Strings[7552]="嘿，杉多尔——你能再教我一下如何制作蛮皮护肩吗？"
D.Strings[7553]="嘿，杉多尔——你能再教我一下如何制作蛮皮外衣吗？"
D.Strings[7554]="只要那些矮人一直待在那里，我们就不会有麻烦。你现在要去哪里，$n？"
D.Strings[7555]="醒来吧，小红龙……毁灭他们！"
D.Strings[7556]="你是不是想要我在强大的$n所率领的军团之前畏缩？$B$B你对我来说不算什么。什么都不是。取你的性命对我来说是易如反掌的事情。$B$B你犯了所有凡人都会犯的错误。$B$B<维克多·奈法里奥斯叹了口气。>$B$B如果你像花钱一样花费你的时间，那就会发生一些奇怪的事情。"
D.Strings[7557]="我做不到，瓦拉斯塔兹！一定有什么办法可以拯救你！"
D.Strings[7558]="牧师们！如果你们要继续这么治疗的话，那我们就来玩点有趣的东西吧！"
D.Strings[7559]="猎人们，还有你们那些讨厌的玩具枪！"
D.Strings[7560]="你们也是法师？小心别玩火自焚……"
D.Strings[7561]="德鲁伊和你们愚蠢的变形法术。让我们看看有什么事情会发生吧！"
D.Strings[7562]="术士们，不要随便去尝试那些你们根本不理解的法术。看到后果了吧？"
D.Strings[7563]="圣骑士……听说你们有无数条命。让我看看到底是怎么样的吧。"
D.Strings[7564]="萨满祭司，让我看看你们的图腾到底是干什么用的！"
D.Strings[7565]="战士们，我知道你们可以更加勇猛！让我们见识一下！"
D.Strings[7566]="潜行者？不要躲躲藏藏了，勇敢地面对我吧！"
D.Strings[7567]="一个巨大的人类手印出现在宝珠的表面。除了看上去的那些处理过的痕迹，宝珠并没有损坏。"
D.Strings[7568]="宝珠的印记和你的手正好适合。"
D.Strings[7569]="<把我的手放在宝珠上。>"
D.Strings[7570]="终于，痛苦结束了。我让你失望了，我的女王。我让你们都失望了……"
D.Strings[7571]="我……我失败了，$n。黑石……黑石山脉的领主实在是太强大了。他轻易地……轻易地吸收了我的力量。我已经……我……请你一定要……一定要杀了我。"
D.Strings[7572]="我是联军的指挥官。我是惩戒之拳。我的职责就是扫清其拉虫人的势力。你敢挑衅酋长的权威吗？你敢直面我无情的审判吗？"
D.Strings[7573]="你没看到我在这里钓鱼吗？"
D.Strings[7574]="你把我的鱼吓走了！你到底要怎么样？"
D.Strings[7575]="我可以为你做什么吗，$c？"
D.Strings[7576]="我要一直待在这里直到钓到68磅重的石斑鱼！你却要离开到什么地方去，是不是？"
D.Strings[7577]="奈法利安被杀掉了！奥格瑞玛的居民，在强大的$n和$g他:她;的盟友面前鞠躬致意吧，他们给予了黑龙军团致命的一击！"
D.Strings[7578]="为$n的成就而庆祝！为$g他:她;的胜利而狂欢吧！"
D.Strings[7579]="看看这条被干掉的龙的脸，$r。部落的强大是毋庸置疑的！"
D.Strings[7580]="联盟的人民们，黑石领主已经被干掉了！奈法利安已经被强大的$n和$g他:她;的盟友所降伏了！"
D.Strings[7581]="怒焰裂谷是由许多火山洞穴所组成的，它位于部落的新都城奥格瑞玛中。最近，有传言说一群忠于阴影教会的教徒占据了那个地方。这群被称为火刃得教徒威胁了杜隆塔尔的安宁。许多人相信兽人酋长萨尔已经意识到了火刃的存在，他并不想着急于摧毁他们，因为萨尔希望这个教会能够将他带往阴影教会。"
D.Strings[7582]="兴奋起来！为你们的勇士欢呼，沐浴在$g他:她;的荣耀之中！为我们伟大的屠龙者欢呼吧！"
D.Strings[7583]="加入将要进入这个地下城的队伍。<这个选择将会让你排入汇合石的队伍中>"
D.Strings[7584]="黑石领主从灰烬中升起！"
D.Strings[7585]="快点离开，市民。没有什么好看的。"
D.Strings[7586]="怒焰裂谷"
D.Strings[7587]="你有兴趣探索这些地下城中的一个吗？"
D.Strings[7588]="哀嚎洞穴"
D.Strings[7589]="这里散乱着放着一堆堆的图纸和设计图。"
D.Strings[7590]="这些图纸被守卫着。和扎米克谈谈来引开守卫的注意！"
D.Strings[7591]="最近一个名叫纳拉雷克斯的暗夜精灵德鲁伊在贫瘠之地中的地下发现了一个错综复杂的洞穴网。这个被称作“哀嚎洞穴”的地方有很多的蒸汽缝隙，所以当蒸气喷射的时候发出的声音就犹如哀嚎一般，其因此而得名。纳拉雷克斯可以利用洞穴中的温泉来恢复贫瘠之地的生态，让这里重新获得生机——但是这样做需要吸收传说中的翡翠梦境的能量。一旦和翡翠梦境相连接，德鲁伊的视线中就变成了一场噩梦。不久之后，哀嚎洞穴开始变化——洞中的水开始腐化——曾经温顺的生物开始变成狂暴，致命的捕食者。据说纳拉雷克斯自己还居住在这个迷宫的最深处，他被翡翠梦境的边缘所困扰着。即使他以前的随从也被他们的主人所经历的噩梦所腐化——他们都变成了邪恶的毒牙德鲁伊。"
D.Strings[7592]="告诉我关于我可以探索的地下城的信息。"
D.Strings[7593]="不可能！出现吧，我的仆人！再次为你们的主人效力！"
D.Strings[7594]="在第三次大战中，肯瑞托的法师和亡灵天灾进行了殊死的战斗。大法师阿鲁高召唤了异世界中的狼人来增强达拉然守备部队的力量。这些狂暴的狼型生物踏平了来犯的亡灵天灾，然后迅速将目标转向达拉然的法师，并开始围攻席瓦莱恩男爵的城堡。这座位于焚木村的城堡不久之后就变成了黑暗势力的聚集地，并从此荒废。因为对于自己罪过的愧疚，阿鲁高将那些狼人当作自己的孩子并隐居在“影牙城堡”中。"
D.Strings[7595]="影牙城堡"
D.Strings[7596]="太晚了，朋友们！奈法利安的堕落力量已经生效……我无法……控制自己。"
D.Strings[7597]="求求你们，快跑吧！在我丧失所有理智之前快逃命吧！黑色的火焰在我的心中燃烧！我必须——释放它！"
D.Strings[7598]="火焰！死亡！毁灭！你们这些凡人，让奈法里奥斯大人的力量……不——我要抗争！阿莱克丝塔萨，帮帮我，我必须抗争到底！"
D.Strings[7599]="啊，你！如果你想要赢得暗矛部族的尊重，那你可以向我们捐赠那些急需的资源！你要知道，布料和绷带不会从树上长出来。$B$B我们需要你在冒险中得到的那些布料，把它们捐给我们吧！这样你就可以得到暗矛部族的青睐！"
D.Strings[7600]="在这个艰难的时期，捐赠布料对于那些不幸的人是非常重要的帮助手段。布料还可以制作装备和绷带——这对于战争十分重要！$B$B如果你想要为奥格瑞玛的兽人捐赠布料的话，我会欣然接受它们，你一定会受到我们的青睐。$B$B为了部落！"
D.Strings[7601]="嘿，$g兄弟:姐妹;……我希望可以打扰你一下，如果可以的话。$B$B我们在通过试炼和进行家园重建中经历了很多。我们现在极度缺乏布料。如果你有一些多余的话，我希望你可以捐献给我们。你一定会为此赢得所有牛头人的尊重的！"
D.Strings[7602]="这里曾经是人类最主要的产金地，希望矿井在部落第一次大战期间席卷暴风城的时候被废弃。现在迪菲亚兄弟会的人占据了那里并将这个黑暗的通道转变成他们的避难所。据说那些盗贼已经劝说了聪明的地精帮助他们在矿井的深处建造一些可怕的东西——但是没有人知道这是真的还是假的。有传言说，死亡矿井的入口在安宁的月溪镇中。"
D.Strings[7603]="你……现在是你帮助被遗忘者最好的时机。好好听着，我不喜欢重复我说过的话。$B$B我们现在极度缺乏布料。绷带和任何布料储存量都很低，我们希望接受捐赠来补充库存。你的捐赠不会有任何经济补偿——这就是捐赠的含义——你的捐赠一定会为我们所赏识。"
D.Strings[7604]="朋友——暴风城需要你的协助和慷慨解囊！$B$B我们曾经储藏丰富的布料已经所剩不多了。暴风城现在需要大量的布料和绷带！你的捐赠将能够帮助暴风城度过难关，你还能赢得我们对你的尊重！"
D.Strings[7605]="啊，你！如果你想要赢得铁炉堡矮人的尊重，那么你可以为我们捐赠有价值的资源！铁炉堡现在的布料和绷带的存储量很低！$B$B你可以捐赠各种你在冒险中得到的布料！这样一来，你就可以赢得铁炉堡矮人对你的尊重！"
D.Strings[7606]="怒焰裂谷位于奥格瑞玛中心的暗影裂口。"
D.Strings[7607]="诺莫瑞根的流亡者需要大量的布料资源！也许你可以帮帮我们，是不是？$B$B把你多余的布料资源带给我们。通过捐献它们，你可以获得所有侏儒的尊重。这是金钱无法换得的！好吧，布料可以帮助我们，但是它们意义绝不限于这些……"
D.Strings[7608]="告诉我更多关于这个地方的信息？"
D.Strings[7609]="哀嚎洞穴的入口位于贫瘠之地十字路口西南边的甜水绿洲。"
D.Strings[7610]="嘿，朋友——请等一下，如果可以的话……$B$B我们在重建泰达希尔的过程中经历了很多的痛苦。现在，我们不仅要忍受这些痛苦，而且我们还发现我们的布料存储已经很少了。如果你有多余的布料，那我希望你可以捐赠出它们。你一定因为帮助暗夜精灵赢得我们的尊重！"
D.Strings[7611]="影牙城堡位于南部银松森林，就在焚木村的北面。"
D.Strings[7612]="我从不犯错。"
D.Strings[7613]="在你匆忙追寻荣耀的过程中，你有没有想过你的行动对于这场竞赛的节奏有什么影响？你有没有想过你们的行为对我来说是多么可笑而荒谬？我对你来说是个难以理解的存在，这让你那花生大小的脑子感到十分迷茫。"
D.Strings[7614]="你已经失去理智了，奈法里奥斯。你在胡言乱语。"
D.Strings[7615]="这是真的。请允许我总结一下……"
D.Strings[7616]="在这个世界中，时间是你的敌人，但是它是我的战友。这段你自以为在你掌握之中的时光实际上是你的主宰。因此我会说……"
D.Strings[7617]="诺莫瑞根"
D.Strings[7618]=S[22073]
D.Strings[7619]="黑暗深渊位于灰谷海岸佐拉姆海岸的最北部。"
D.Strings[7620]="位于灰谷佐拉姆海岸的黑暗深渊曾经是为供奉暗夜精灵月神艾露尼尔建造的。然而，在大分裂中，神庙受到极大的冲击然后沉入了海中。它一直保持着原样——直到，其蕴含的古老的力量吸引来了纳迦和萨特。传说，古代怪兽阿库麦尔就居住在神庙遗迹中。作为古代之神最喜欢的宠物之一，阿库麦尔就一直生活在这个地区进行捕食。在阿库麦尔的吸引下，一群被称作幕光之锤的教徒也聚集在这里从事邪恶的勾当。"
D.Strings[7621]="诺莫瑞根在丹莫洛的西边。"
D.Strings[7622]="位于丹莫洛的科技奇迹城市诺莫瑞根世代以来都是侏儒的主城。最近，一群邪恶的变异食鄂怪侵入了包括侏儒主城在内的多处丹莫洛地区。为了做出殊死一搏来干掉入侵的食腭怪，大工匠梅卡托克命令打开城市中的紧急辐射水箱。侏儒在等待那些食腭怪死亡或者逃跑的同时也在寻找躲避辐射的方法。不幸的是，虽然食腭怪在经过辐射之后感染了毒性——但是它们的攻击没有停止，也没有丝毫的减弱。那些没有被辐射杀死的注入被迫逃离，他们在附近的矮人城市铁炉堡找到了安身之处。大工匠梅卡托克组建了一个智囊团来商议重新夺回他们挚爱的城市的计划。"
D.Strings[7623]="剃刀沼泽"
D.Strings[7624]="剃刀沼泽位于贫瘠之地最南端的大路西边。"
D.Strings[7625]="在上古之战中，强大的半神阿迦玛甘和燃烧军团进行了激战。这头巨大的野猪在战斗中倒下，在它血液流淌过的地方逐渐长出了巨大的荆棘藤蔓。野猪人占领了这些地方，并将其奉为圣地。这些荆棘地的中心被称为剃刀岭。剃刀沼泽被一个老丑婆卡尔加·刺肋所占据。她是一个强大且经验丰富的地卜师。在她的掌权之后，野猪人部族中迅速滋长的暴虐情绪只会带来一个后果：战争。"
D.Strings[7626]=S[18883]
D.Strings[7627]="血色修道院位于提瑞斯法林地东北部的山坡上。"
D.Strings[7628]="血色修道院曾经是洛丹伦王国牧师的荣耀之地——那里是学习圣光知识和膜拜的中心。随着在第三次大战中亡灵天灾的崛起，宁静的修道院成为了疯狂的血色十字军的要塞。十字军对于所有非人类都有着偏激的态度，无论他们是自己的盟友还是对手。他们相信所有任何外来者都带着亡灵的诅咒——他们必须被摧毁。"
D.Strings[7629]="剃刀高地"
D.Strings[7630]="剃刀高地位于贫瘠之地最南端的大路东边。"
D.Strings[7631]="剃刀高地和剃刀沼泽一样由巨大的藤蔓组成，剃刀高地是野猪人的传统都城。在那错综复杂的荆棘迷宫中居住着大群忠诚的野猪人军队，以及他们的高等祭司——亡首部族。然而最近，一股黑暗的力量笼罩了这座原始的洞穴。亡灵天灾的爪牙在巫妖寒冰之王亚门纳尔的带领下控制了野猪部族，并将布满荆棘的迷宫变成了亡灵力量的堡垒。现在野猪人正在奋力战斗来夺回他们的城市，并阻止亚门纳尔继续控制贫瘠之地。"
D.Strings[7632]="奥达曼"
D.Strings[7633]="奥达曼位于荒芜之地最北端。"
D.Strings[7634]="拉尔德在这里维持和平。拉尔德还在这里钓鱼。想要一些鱼吗？"
D.Strings[7635]="奥达曼是古代泰坦创世之时所留下的深埋于地下的城市。矮人探险队最近发觉到了这块被遗忘的城市，将泰坦一款失败的创造物：食腭怪唤醒了。传说泰坦是从石头中创造了食腭怪。但事实证明这次试验很失败的时候，泰坦把食腭怪锁了起来并进行了第二次的尝试——最终创造了矮人这个种族。矮人创造的秘密被记录在精密的诺甘农圆盘中——那是位于古代城市最底部的大型泰坦遗迹。"
D.Strings[7636]=S[17267]
D.Strings[7637]="祖尔法拉克遗迹位于塔纳利斯沙漠最西北角。"
D.Strings[7638]="日光暴晒下的这座城市是沙怒巨魔的家园，他们一向以来都以其无情和黑暗魔法而闻名。巨魔传说中有一把强大的名叫鞭笞者苏萨斯的武器能够让最弱小的人可以击败最强大的敌人。很久以前，这把武器被分成了两半。然而，有传言说这两半可以在祖尔法拉克任何地方找到。"
D.Strings[7639]="玛拉顿"
D.Strings[7640]="玛拉顿位于凄凉之地西部中间的长矛谷中。"
D.Strings[7641]="玛拉顿是凄凉之地最神圣的地方。这座建造在岩窟中的神庙是扎尔塔的陵墓。半神塞纳留斯有两位不朽的儿子，扎尔塔正是其中之一。传说中扎尔塔和大地元素公主瑟莱德丝的私生子成为了半人马的祖先。据说半人马这个野蛮的种族在诞生之后就背叛了他们的父亲并将其杀死。有些人相信瑟莱德丝在悲伤中将扎尔塔的灵魂困了起来，并将其藏在了蜿蜒的洞窟中——以利用它的能量来达到一些不可告人的目的。"
D.Strings[7642]=S[15700]
D.Strings[7643]="沉没的神庙位于悲伤沼泽东部的一个大湖的中心。"
D.Strings[7644]="在一千年之前，强大的古拉巴什王国被一次大型内部战争所毁灭。一部份被称为阿塔莱的巨魔牧师试图将古代的血神，夺灵者哈卡带回这个世界。虽然这些牧师被击败并最终被流放，这个伟大的王国变得四分五裂。流放的牧师逃到了北面的悲伤沼泽。他们为哈卡建立了一座伟大的神庙——在那里他们期望能够把哈卡重新带回世间。伟大的守护神龙伊瑟拉了解了阿塔莱的计划并将神庙摧毁沉入沼泽之中。在今天，神庙沉没的遗迹被绿龙所守卫并阻止任何人进入或者出去。"
D.Strings[7645]="黑石深渊"
D.Strings[7646]="黑石山脉位于灼热峡谷和燃烧平原的中间。"
D.Strings[7647]="黑石深渊曾经是黑铁矮人的伟大都城，这个火山中的迷宫现在成为炎魔拉格纳罗斯的王座所在地。拉格纳罗斯找到了特殊的方法，可以使用石头来创造一支无敌的石头人军队，帮助它征服黑石深渊。为了打败奈法利安和他的龙子龙孙，拉格纳罗斯会不惜一切代价达到最后的胜利。"
D.Strings[7648]="黑石塔"
D.Strings[7649]="黑石深渊深处的巨大堡垒是由矮人建筑大师弗兰克罗恩·铸铁所设计的。这个堡垒是矮人力量的象征并被邪恶的黑铁矮人占据了数个世纪。然而，奈法利安——死亡之翼狡猾的儿子——对这个巨大的堡垒别有意图。他和他的黑龙军团占据了上层黑石塔并向占据着黑石深渊的黑铁矮人宣战。奈法利安知道矮人是由强大的火元素拉格纳罗斯所领导的，所以他立志要摧毁他的敌人并将黑石深渊全被占为己有。"
D.Strings[7650]="厄运之棰"
D.Strings[7651]="厄运之棰位于菲拉斯的中部。"
D.Strings[7652]="埃雷萨拉斯古城是在一万二千年前由当时的一批暗夜精灵巫师秘密建造的，它被用于保护艾萨拉皇后最宝贵的奥法秘密。虽然受到了世界大分裂的影响，这座伟大的城市仍屹立在那里，现被称为厄运之槌。这座遗迹之城分为三个部分，分别被不同的生物所占据——包括幽灵般的上层精灵，邪恶的萨特和残暴的食人魔。"
D.Strings[7653]=S[20390]
D.Strings[7654]="通灵学院这个学习亡灵术的学校位于西瘟疫之地的凯尔达隆那个废弃的小岛上。"
D.Strings[7655]="通灵学院位于凯尔达隆废弃的城堡中的地下室中。那里曾经是高贵的巴罗夫家族的庄园，但是在第二次大战中凯尔达隆变成了一块废墟。法师克尔苏加德经常向他的诅咒神教信徒承诺可以用对于巫妖王的效忠来换取永恒的生命。巴罗夫家族受到克尔苏加德的魅惑而将城堡和其地下室献给了亡灵天灾。那些信徒将巴罗夫家族的人杀死，并把地下室变成了通灵学院。虽然克尔苏加德不再住在这个地下室中，但是狂热的信徒和讲师都还留在那里。"
D.Strings[7656]="斯坦索姆"
D.Strings[7657]="斯坦索姆位于东部瘟疫之地瘟疫林的北部。"
D.Strings[7658]="斯坦索姆曾经是洛丹伦北部一颗璀璨的明珠，但是就是在这座城市中，阿尔萨斯王子背叛了他的导师乌瑟尔，并屠杀了数百个被认为受到感染的臣民。阿尔萨斯不久之后就向巫妖王臣服。这座破碎的城市也被巫妖克尔苏拉德领导的亡灵天灾所占据。一直由大十字军战士达索汉领导的血色十字军分遣队也占据了这个城市的一部分。这两方力量在城市中进行着激烈的战斗。"
D.Strings[7659]="死亡矿井"
D.Strings[7660]="暴风城监狱"
D.Strings[7661]="暴风城监狱位于暴风城靠近法师区附近。"
D.Strings[7662]="监狱是位于暴风城运河区戒备森原的牢房。那里由典狱官塞尔沃特看守着，监狱是那些小偷，政治犯，谋杀者和许多最危险的罪犯的家园。最近，异常暴动导致了监狱的混乱——所有的守卫都被赶了出来，里面的罪犯可以自由的活动。"
D.Strings[7663]="%s施放增益法术！"
D.Strings[7664]="入侵者闯进了孵化间！我们要不惜一切代价保护龙蛋！"
D.Strings[7665]="不要使用破碎的武器和护甲参加战斗！我这里可以在你等待的时候进行专家级的武器和护甲修理！"
D.Strings[7666]="愚蠢的$n，你现在为我服务！"
D.Strings[7667]="你要为强迫我这么做而付出代价！"
D.Strings[7668]="蠢货！这些蛋比你认为的要珍贵的多！"
D.Strings[7669]="不！住手！我要会让你来弥补自己的罪行！"
D.Strings[7670]="原谅我，$n！你的死亡让我的失败更加沉重！"
D.Strings[7671]="奈法里奥斯的仇恨让我变得空前强大！赶快逃跑吧，凡人！黑石之王的怒气涌动在我的血脉中！"
D.Strings[7672]="保护黑龙！杀掉所有的入侵者！"
D.Strings[7673]="你怎么进来的？你们这种生物不能进来！我要毁灭你们！"
D.Strings[7674]="你们很聪明，凡人——但是我不会那么轻易地离开我的圣地！"
D.Strings[7675]="保护血液样品！摧毁入侵者！"
D.Strings[7676]="这不可能！我是这里的主人！你们这些凡人对于我来说一无是处！听到了没有？一无是处！"
D.Strings[7677]="没用的$n！你的朋友不久之后就会去找你的！"
D.Strings[7678]="干得好，我的手下。凡人的勇气开始消退了！现在，让我们看看他们如何应对黑石塔的真正主人的力量！！！"
D.Strings[7679]="燃烧吧！你们这些悲惨的家伙！燃烧吧！"
D.Strings[7680]="我这里有你所需要的所有烹饪材料，伙计！"
D.Strings[7681]="欢迎来到恶齿村，陌生的$c。我是断齿族长，这里的领袖。"
D.Strings[7682]="如果它坏了，那么斯拉提可以修理它！"
D.Strings[7683]="别踩到我的货物，小心。"
D.Strings[7684]="钓鱼只是为了娱乐，伙计。你知道吗？我是在向我的导师学习，世界上最伟大的钓鱼者——纳特·帕格。你听说过他没有，伙计？$B$B如果你想要寻求启迪，那么纳特·帕格会指引你前进的道路。"
D.Strings[7685]="你可以教我什么？"
D.Strings[7686]="祖尔金总有一天会回来的，$r。记住我的话。在那一天到来之前，我们会尽我们的所能保证森林巨魔族群的昌盛。$B$B作为恶齿村的猎人头领，我的责任就是保证我们的安全。$B$B我必须对这一带的野兽进行监控。$B$B你是不是来找活干的？"
D.Strings[7687]="马克霍尔，我要把我的宠物收藏起来。"
D.Strings[7688]="我是基尔拉姆，斧系大师。"
D.Strings[7689]="啊，一个经历丰富的冒险者。基尔拉姆又让你来这里了。我知道你具有相当的能力，你只需要询问我，我就会教你斧系铁匠的知识。"
D.Strings[7690]="请告诉我如何成为一名铸斧师，基尔拉姆。"
D.Strings[7691]="不要靠得太近，$n。我手中的铁锤可能会敲到你。"
D.Strings[7692]="我会教你锤系专精之道。你只需要恭恭敬敬地问我就可以了。"
D.Strings[7693]="请告诉我如何成为一名铸锤师，莉莉丝。"
D.Strings[7694]="退后，否则我会把你一下子砍成两半的。"
D.Strings[7695]="如果你希望成为一名铸剑师，那就问问我吧。"
D.Strings[7696]="请告诉我如何成为一名铸剑师，瑟里尔。"
D.Strings[7697]="我刚刚完成了一个新的空间爆破器，它可以让我变成最最富有的技师，我做梦都不曾想过的富有！我所需要的就是找到一个熟练的地精技师，让$g他:她;来制作一个空间撕裂器，然后将两者连接起来！"
D.Strings[7698]="空间爆破器听上去很危险！我怎么才能做一个呢？"
D.Strings[7699]="这个机器所依据的理论就是通过一次大爆破将你完全摧毁，然后把你的粒子通过空间裂隙传送到某个地点，再通过反爆破模块将你在目的地重组。这是即时的传送！它并不是百分之百有效的，但是你是个杰出的地精技师！如果你把性命看得比发明创造更重要，那么你永远都无法成为一个真正的地精技师！\n这是制作空间撕裂器所需的图纸，你一定要试试看！"
D.Strings[7700]="通过在诺莫瑞根中进行的探险行动，我找到了制作一种伟大发明的方法：物质传送器！我所需要的就是一个熟练的侏儒技师，让$g他:她;制造一个信标连接在这个传送器上。"
D.Strings[7701]="我必须为这个不可思议的装置制作一个信标！"
D.Strings[7702]="一旦你建造了这个装置，你就将被传送到可爱的加基森！几乎使用这个装置的人都发现在其立即到达了这里！$B$B有报告说，有别人试图用一种坏的版本来替换我们的产品，但是我相信我们不久之后就可以解决这个问题……"
D.Strings[7703]="如果你有办法改进这个装置，那就告诉我！"
D.Strings[7704]="很高兴有技师能勇敢地制作这个装置。我们地精工程师对于危险只会抱以大笑！"
D.Strings[7705]="又一个掉进陷阱的傻瓜！"
D.Strings[7706]="午饭到了！"
D.Strings[7707]="高阶女祭司会吞噬你的骨头！"
D.Strings[7708]="%s的力量被宝珠削弱了！"
D.Strings[7709]="我们敌人送来的补给品！干得好，$n！"
D.Strings[7710]="你带来了我们敌人的补给品！哈哈！干得好$n！"
D.Strings[7711]="入侵者！入侵者！我们遭受攻击，孩子们！干掉他们！"
D.Strings[7712]="我要作最后一次努力。希望它能有效……"
D.Strings[7713]="瓦拉斯塔兹，不！！！"
D.Strings[7714]="拿到钥匙，打开这些锁链！钥匙在守护者希坦亚手里……就在洞的后面……"
D.Strings[7715]="终于，我自由了！我终于回家了！"
D.Strings[7716]="战歌峡谷战斗将在1分钟内开始。"
D.Strings[7717]="战歌峡谷战斗将在30秒钟内开始。做好准备！"
D.Strings[7718]="工作/遗失和找到物品/悬赏："
D.Strings[7719]="你好，我的朋友！我是哈古斯，战歌前锋部队的军需官。随着你在战歌氏族中的声望不断提升，我可以为你提供一些可在战歌峡谷中使用的商品。如果你需要修理装备的话，我也可以提供这样的服务。"
D.Strings[7720]="我现在赢得了在战歌峡谷中购买哪些物品的权利？"
D.Strings[7721]="愿夜之祝福永远与你同在，我的朋友！我是艾蒂尔·月火，我是灰谷银翼哨兵部队的军需官。随着你在银翼哨兵中的声望不断提升，我可以为你提供一些可在战歌峡谷中使用的商品。如果你需要修理装备的话，我也可以提供这样的服务。"
D.Strings[7722]="联盟的旗帜回到了它的基地！"
D.Strings[7723]="部落军旗已回到旗座上了！"
D.Strings[7724]="我在这里了！深铁矿洞是……我的！"
D.Strings[7725]="斯尼维尔在此！冷齿矿洞是斯尼维尔的！"
D.Strings[7726]="让复仇的毒蛇吞噬你们吧！"
D.Strings[7727]="希里克，赐予我复仇的翅膀！"
D.Strings[7728]="欢迎！欢迎来到亚布·尼比盖尔的暗月珍奇馆——这儿有来自世界各地的奇珍异宝！朋友，尽情参观吧！$B$B但是不要动手触摸！神圣的神器和可怕的野兽守护着这些展品！随意触碰的话，它们可能会烧伤你的手……"
D.Strings[7729]="今天要我送你去哪里，$c？"
D.Strings[7730]="虽然十字路口似乎是贫瘠之地的中心地带，但是我更喜欢陶拉祖营地的安静。你想去哪儿？"
D.Strings[7731]="这些道路都是大地之母走过的道路。无论你决定前往何方，愿大地之母与你同在。"
D.Strings[7732]="当双足飞龙将你送达目的地之后，请好好款待它。愿你的祖先与你同在，$n。"
D.Strings[7733]="你好，我的朋友，欢迎来到艾择拉斯最伟大的展览会！$B$B请尽情浏览我们展出的东西吧。来看看这些暗月马戏团在广袤而又神秘的艾泽拉斯世界中找到的各种千奇百怪的东西！我们不收取任何费用，我们为你带来无限惊喜，为孩子们带来让他们兴奋的东西！"
D.Strings[7734]="朋友，欢迎回到艾泽拉斯最盛大的展览！很高兴再次看到你。$B$B请接受我们的盛情邀请吧。请四下看看，我们暗月马戏团中有许多新奇的事物！看看我们带来的各种货物吧！我们会继续免费为大家带来更多惊喜的，孩子们都乐意参加！"
D.Strings[7735]="希拉斯，为什么马戏团里的大部分设施都是免费的？那你是怎么赚钱的？"
D.Strings[7736]="这不是钱的问题，伙计！虽然我们接受慷慨的捐赠——有一些捐赠量还很大——我们旅行车队的信念是为这个战火纷飞的世界带来爱与曙光！不要担心我们，让我们来为怎样取悦你们而操心吧。"
D.Strings[7737]="兑换奖券啦！换取礼物啦！快来啊！"
D.Strings[7738]="闪开，乡巴佬。"
D.Strings[7739]="这不是一匹坐骑，伙计。"
D.Strings[7740]="如果你想表示友好的话，就请屏住呼吸。最好停止呼吸。"
D.Strings[7741]="事先说明，我来这里不是来搞客户关系的。"
D.Strings[7742]="你打扰希拉斯，又打扰我。祝你开心。"
D.Strings[7743]="我需要第二个头，就像我需要把第一个砍掉一样。"
D.Strings[7744]="我在厄运之槌里住过一段时间，真令人难忘。真的。"
D.Strings[7745]="和大多数的食人魔不一样的是，我知道厕所是干什么用的。"
D.Strings[7746]="我早知道你会找到我的，$n。$B$B世间众生都被他们所做出的选择驱动着。一个选择导致另一个选择，最终这些选择决定了你的一切。而这一切——如你的身份，及你所做的选择，也勾勒出了你的命运。$B$B你准备好直面自己的命运了吗？"
D.Strings[7747]="快告诉我吧！"
D.Strings[7748]="好吧……$B$B假设你从你的主人那里接受了保护玉米田并清除小偷的任务。一天晚上，在你巡逻的时候发现了一个穿着破烂布衣的人正在田里偷窃玉米。你马上上前，而他立即跪在你的面前求你不要杀他。他说他偷玉米是为了养活他一家，因为这块土地的主人——也就是你的主人向他们征收重税。你的主人一向以此而闻名。$B$B你该怎么办？"
D.Strings[7749]="我按照命令把他杀掉，反正他不过是个小偷和骗子而已。"
D.Strings[7750]="我将这个人交给王上来处理，因为他破坏了这里的法律，而我的职责就是把他抓住。"
D.Strings[7751]="我没收他偷到的玉米，并警告他盗窃是通往毁灭和死亡的道路，但是我会放他走。"
D.Strings[7752]="我允许他拿走足够供他一家人糊口数日的粮食，并建议他赶快离开。"
D.Strings[7753]="你的下一个选择在等着你。$B$B你是一个效忠于主人的刽子手。有一个背叛了你的主人和人民的人被送到你这里来受刑。可你以前认识他，他曾是你非常要好的朋友，并且非常善良，但是有一天他突然消失了。你还知道他所犯下的罪行导致很多无辜的平民的死亡。当你看到他的时候，他求你饶命，并且说他是被一个高官所陷害的。$B$B你该怎么办？"
D.Strings[7754]="去死吧，渣滓！联盟会获得胜利的！"
D.Strings[7755]="去死吧！你们别想在奥特兰克山谷站住脚！"
D.Strings[7756]="把这些渣滓赶出奥特兰克！"
D.Strings[7757]="准备发动攻击！为部落而战！"
D.Strings[7758]="狂欢开始啦！"
D.Strings[7759]="没错！暗月马戏团很快就要来了！只要我把这些东西从车上卸下来，搭好帐篷弄好场地，就马上开工！别忘了届时过来看看哦！"
D.Strings[7760]="暗月马戏团不久就会开张啦。别忘了待会回来，看看我们是否已准备停当。"
D.Strings[7761]="年轻人，欢迎来到暗月马戏团！我们从世界各地收集到不少神奇的东西，你可以随便看。啊，如果你能设法收集一套次级暗月卡片，就赶紧告诉我，因为主人……我是说我对这东西很感兴趣。"
D.Strings[7762]="告诉我更多关于暗月卡片的信息。"
D.Strings[7763]="我们在世界各地散发暗月卡片，看看有没有谁能集齐八套暗月卡片中的任何一套。若你设法集齐一套八张的卡片，我们就会奖励你一张强力暗月卡片，它不仅是强大的饰品，也可以作为暗月马戏团的纪念。"
D.Strings[7764]="您还想吃点什么吗？"
D.Strings[7765]="告诉我更多关于野兽套牌的信息。"
D.Strings[7766]="如果你集齐一套野兽卡片，我们会奖励你一张高级暗月卡片：蓝龙。这张卡片对恢复魔法能量非常有用。"
D.Strings[7767]="告诉我更多关于入口套牌的信息。"
D.Strings[7768]="如果你集齐一套入口卡片的话，你将获得一张暗月卡片：虚空。这张卡片将有可能在你死亡之后让你复活。"
D.Strings[7769]="告诉我更多关于元素套牌的信息。"
D.Strings[7770]="如果你集齐一套元素卡片，我们会奖励你一张高级暗月卡片：漩涡。这张卡片可能会对你的敌人造成严重的伤害。"
D.Strings[7771]="告诉我更多关于督军套牌的信息。"
D.Strings[7772]="如果你集齐一套督军卡片的话，你将获得一张暗月卡片：英雄。这张卡片将有可能在你进行近身作战的时候对你进行治疗。"
D.Strings[7773]="我按照王上的命令处决他，这样才能偿还他对我的同胞犯下的罪孽。"
D.Strings[7774]="我按照王上的命令处决他，但是我尽可能地让他少受痛苦。正义必须得到伸张，但我们也要心怀怜悯。"
D.Strings[7775]="我愿意以自己生命的代价来拯救他，然后他就可以证明自己的清白。如果可以的话，我会不惜一切代价来帮助他。"
D.Strings[7776]="你的下一个选择在等着你。$B$B你奉王上之命，出使交战中的敌国。战争让双方都元气大伤，你的使命是确保两国进行和平谈判。$B$B在外交宴会上，你无意中听到敌国的统治者恶意中伤你的君王。你断定他原本是想背着你说的，但他还是辱及了你的王上的威名。$B$B做个选择吧。"
D.Strings[7777]="我挑战他的邪恶与蛮横，不惜一切代价捍卫王上的荣耀。"
D.Strings[7778]="我平静但略有表示地对这种冒犯一言不发，让他对自己犯下的错心怀恐惧。回去之后，我会把这一切禀报王上。"
D.Strings[7779]="我默不作声，忽略了这种侮辱。我不会告诉我的王上，因为我将不惜一切代价保护和平。这只是一次侮辱——而不是一次完全的宣战。"
D.Strings[7780]="你的下一个选择在等着你。$B$B你的兄弟想要加入你所在的享有盛名的军队。虽然你对他的热情和忠诚毫不怀疑，但是你担心他的能力还不足以执行军队艰巨的任务。当你无法肯定定他能否应对挑战——这可能会让你和其他人陷入危机——而你的意见将决定他的去留。$B$B做个选择吧。"
D.Strings[7781]="我会反对我的兄弟加入军队，即使我们的关系会因此产生永久的裂痕。对他自己和周围的人来说，他无疑是个危险，要想指望他会逐渐进步可就太冒险了。"
D.Strings[7782]="我会支持我的兄弟加入军队，虽然这或许会威胁到军队的安全。我和军队的其他成员会帮助他，我相信他能够适应这儿的生活并且学会生存之道。"
D.Strings[7783]="我会想办法让他不参加危险的任务，完全不需要他做任何事情，以此来保存我的家族的血脉。"
D.Strings[7784]="你的下一个选择在等着你。$B$B你凭借自己的力量杀死了一头破坏农田的可怕野兽，并且割下它的耳朵作为战利品。后来你听说你的王上在悬赏这头野兽的性命，有一位贫穷的骑士为了养家糊口，说是自己杀死了这头野兽。你自己并不需要钱，但是你知道这家伙谎报实情，牟取私利。$B$B做个选择吧。"
D.Strings[7785]="我会将这头野兽的耳朵拿给王上看，以此证明我是凭一己之力杀死它的，并且将所有的奖励收归己用。把别人的事迹宣扬成自己的功劳是不对的。"
D.Strings[7786]="我会将这头野兽的耳朵拿给王上看，以此证明我是凭一己之力杀死它的——毕竟，我确实杀了它。然后我会用一部分奖励接济贫困的骑士，用以养家糊口。"
D.Strings[7787]="我将对这件事情只字不提，并允许那个骑士拿到奖励来帮助他的家庭。"
D.Strings[7788]="对你的占卜已经完成，$c。在接下来的几个小时中，你将发现你的精神与你真正的天性保持一致。你要小心，因为你的命运并不是你所想得那么条理清晰。$B$B如果你想要对你的未来有所了解，那么尽管告诉我。我会很乐意给你一张手写的占卜结果，当然，你的背包中必须留有足够的空间。这个结果是你回答我的问题时所表现出来的。"
D.Strings[7789]="我想要你说的这些塔罗牌！我有足够的空间来存放。"
D.Strings[7790]="$n，这是你的塔罗牌。愿你能好好利用它。"
D.Strings[7791]="暗月马戏团来了！所有的孩子都可以在这里找到好玩的东西！来吧，都来吧！"
D.Strings[7792]="快来吧，听说艾泽拉斯最盛大的集会——暗月马戏团开张啦！哈哈！"
D.Strings[7793]="男孩们女孩们——所有的孩子们——暗月马戏团已经到啦！哈哈！"
D.Strings[7794]="暗月马戏团会在哪儿开张呢？"
D.Strings[7795]="你是说暗月马戏团已经来了？它在哪里？"
D.Strings[7796]="暗月马戏团的下一站还没有决定，但是相信你和我都会在第一时间知道的！"
D.Strings[7797]="暗月马戏团到艾尔文森林来了，就在闪金镇的南边。走过路过不要错过！"
D.Strings[7798]="当暗月马戏团开始展览的时候，他们会出现在艾尔文森林。我们的帐篷将驻扎在闪金镇的南边！"
D.Strings[7799]="暗月马戏团到莫高雷的金色平原来了，就在雷霆崖的西南边。走过路过不要错过！"
D.Strings[7800]="暗月马戏团将会在莫高雷开张，我们就在雷霆崖的西南方安营扎寨！"
D.Strings[7801]="你好，朋友。"
D.Strings[7802]="这附近有很多乱扔垃圾的家伙。"
D.Strings[7803]="玩得开心吗？"
D.Strings[7804]="别忘记买点饮料和纪念品！"
D.Strings[7805]="暗月马戏团是全艾泽拉斯最华丽的！"
D.Strings[7806]="欢迎来到暗月马戏团，$c！$B$B我叫克莉·希克斯，我应该跟你握手致意的，但是恐怕我会把你的手捏碎，因为我是当今世上最强的女人！"
D.Strings[7807]="嗨，$n！感谢你对我的帮助！现在我什么都不缺啦，但是未来会怎样，又有谁知道呢？$B$B享受生活吧，别忘记跟你的朋友谈谈暗月马戏团的趣闻！"
D.Strings[7808]="到我这儿来吧，看看你的未来如何！"
D.Strings[7809]="过来跟我谈谈，我会为你拨开疑云的。"
D.Strings[7810]="别害怕！所有深谙此道的人都能洞察命运。"
D.Strings[7811]="你等得越久，我所能告诉关于你未来的信息就越少。"
D.Strings[7812]="便宜的啤酒！到这儿来买啊，物超所值！"
D.Strings[7813]="为给小费的好心人喝彩！往右边走，到那儿去品尝美味的冷饮吧！"
D.Strings[7814]="你！就是你！你看起来很口渴。来吧，我有你想要的东西！"
D.Strings[7815]="快来吧！来买热辣烤翅啊！"
D.Strings[7816]="现烤现卖的暗月热狗，新鲜热烫！大家赶快趁热来买啊！"
D.Strings[7817]="你有金钱，我们有食物。那么你还在等什么？！"
D.Strings[7818]="限时供应！暗月马戏团独家美味，脆青蛙肉！机会难得！"
D.Strings[7819]="你有完整的暗月套牌吗？快来我这儿兑换吧！"
D.Strings[7820]="如果你有暗月马戏团卡片的话，就来找我。"
D.Strings[7821]="暗月套牌！快来兑换暗月套牌了！"
D.Strings[7822]="你有暗月马戏团卡片吗？如果你有胆子的话，就来找我了解详情吧！"
D.Strings[7823]="我出售的每项物品都是我自己的劳动所得。我向你保证。"
D.Strings[7824]="暗月卡片？去找教授问问吧。"
D.Strings[7825]="趁现在还有机会，过来看看我的货物吧。我们要在这儿呆上一周，然后就要动身去远方啦。"
D.Strings[7826]="我历尽艰辛才将这些无价之宝带来此地销售，你知道吗？来看看吧。"
D.Strings[7827]="嗨，谁来帮我抓住这个东西！"
D.Strings[7828]="它跑开了！"
D.Strings[7829]="出售青蛙和皮球啦！"
D.Strings[7830]="奖券！快来兑换你的暗月马戏团奖券吧！新奇的奖品正在等着你！"
D.Strings[7831]="神秘的奖品在等你，冒险家们。快来啊，快来啊！"
D.Strings[7832]="不管你有五张奖券还是五百张奖券，朋友，这都没关系，人人都是赢家！"
D.Strings[7833]="奖品！到这儿来领取奖品啦！快来用暗月马戏团奖券兑换丰厚的奖品吧！"
D.Strings[7834]="每个人都还玩得开心吧？棒极了！欢迎来到暗月马戏团，艾泽拉斯最盛大的展览！当你在尼比盖尔的珍奇馆购物时记得跟亚布和他的朋友谈谈。"
D.Strings[7835]="来啊，大家都来啊。欢迎来到暗月马戏团！不要害羞。到兰拉这里购买来自遥远大陆的奇特东西。如果你是个拥有暗月卡片的幸运儿，那么就去找萨杜斯·帕雷教授吧。渴了？饿了？你很幸运！你可以从塞兰妮亚和斯塔姆那里获得让你倍感清新的食物和水。我建议你去尝尝暗月特殊储备那里的热辣烤翅，绝对不容错过！如果你想要了解自己的未来，那么快点去找塞格谈谈。"
D.Strings[7836]="欢迎所有人来到暗月马戏团，世界上最盛大的事件！我们拥有……可口的美食、烈性饮料、异地的神器、寻宝书、丰厚的奖品和无尽的刺激！别忘记将你的暗月马戏团奖券交给吉瓦斯·格里加特！只需要5张奖券你就可以领取一份艾泽拉斯最丰厚的奖品。每个人都是赢家！"
D.Strings[7837]="来吧！欢迎来到暗月马戏团！你想要冒险吗？你想找寻奇珍异宝吗？那就不要只是观看啦！我的朋友，你来对地方啦！来吧，亲身参与到狂欢节中来，尽情享受吧！我们这周都会呆在这儿，记得把这消息告诉你的朋友和爱人！"
D.Strings[7838]="唉……很抱歉，我现在还不能告诉你什么，你近来刚从我这儿获得了关于命运的信息。$B$B过几个小时你再来找我吧。命运的力量或许会有所改变，我会洞察你的未来。"
D.Strings[7839]="我们回来啦，感觉棒极了！暗月马戏团的朋友们，今儿是你们的幸运日！不要吝惜你的钱财，我们出售的都是来自世界各地的稀罕之物。无论你年方几何，无论你是贫穷还是富有，都能在暗月马戏团上买到称心如意的东西！请记得将你们的暗夜集市奖券交给吉瓦斯·格里加特，挑选一份丰厚的奖品！"
D.Strings[7840]="$n，很高兴再次见到你！你玩得开心吗？$B$B想要来掰手腕吗？不，当然不……你想要保护好自己的手臂！"
D.Strings[7841]="你好。我是克洛诺斯——记忆力天下第一的克洛诺斯。我是不会忘记任何微小的细节的。$B$B相信我。"
D.Strings[7842]="你好，$n。你认为我会忘记你？$B$B我知道你不会这么认为的。你是个聪明的$c，你所认识的我一看到任何人就可以立即认出他。"
D.Strings[7843]="你好！欢迎你！恐怕我的售货亭还不能开张……我得修理很多东西……$B$B但是我仍然受制于血的诅咒，求你啦，笑笑吧。如果你的脸上没有笑容的话，我就得砍下我的手，并且在手掌再生之前不得食用任何肉类……"
D.Strings[7844]="$n，你回来啦！我上次吃掉的那些灵魂说你会来看我的，而且我们还会谈谈生意。$B$B他们说对了吗？"
D.Strings[7845]="嗨，$n！很高兴见到你！暗月马戏团是一场盛大的展览，不是吗？$B$B有很多值得一看的东西！看吧！或许有一天会有更多的东西呈现在你面前……"
D.Strings[7846]="%s开怀畅饮啤酒！"
D.Strings[7847]="我找不到我的宠物青蛙加布加布啦。她爱喝黑铁啤酒，她总是喝这种酒，但是这种酒很不容易得到的！现在我没有黑铁啤酒了……加布加布一定是自己跑出去找酒喝啦！$B$B真希望她回到我身边……"
D.Strings[7848]="加布加布回来啦，我太高兴了！我希望我的黑铁啤酒不会很快被喝光，否则这家伙又会偷跑出去啦！"
D.Strings[7849]="嗨，加布加布。我很想你！"
D.Strings[7850]="加布加布？你在哪儿，加布加布？你这次又跑哪儿去了！"
D.Strings[7851]="%s听到了主人的声音！"
D.Strings[7852]="我们必须不惜一切代价保护这个营地的安全，$c！我们不能允许敌人再前进一步了！"
D.Strings[7853]="现在是危险时分，$r。远古的邪魔复活了，他可不管你是部落还是联盟。"
D.Strings[7854]="出售可口的饮料啦！暗月马戏团最好的酒，生津止渴！"
D.Strings[7855]="别害羞，请这儿的每个人喝上一杯吧！"
D.Strings[7856]="朋友，招待生总是乐意收到小费的。"
D.Strings[7857]="给我饮料！"
D.Strings[7858]="呱呱。"
D.Strings[7859]="吻我。"
D.Strings[7860]="孩子，给我更多的面包！"
D.Strings[7861]="您的面包，大人。"
D.Strings[7862]="嗯……食物。"
D.Strings[7863]="你想要出售青蛙？"
D.Strings[7864]="莫托尔知道一切，$r。"
D.Strings[7865]="你好，年轻的$c。就是在这里，你的酋长挑战了奥格瑞姆·毁灭之锤！虽然这事情已经过去了很久，但是在我的记忆中，它依然犹如刚刚发生过一样。"
D.Strings[7866]="我们的指挥官有多少还活着，德雷克塔尔？"
D.Strings[7867]="你是来学习的？嗯，我或许会给你一些事儿做的。"
D.Strings[7868]="<雷矛中士向你敬礼。>$B$B姓名，军阶和编号，士兵！这是你唯一需要提供给那些肮脏的霜狼走狗的信息！"
D.Strings[7869]="嗯……我觉得我需要更好的诱饵。我得去我父亲的货车中找找。"
D.Strings[7870]="野猪人的废弃物！这个应该可以。鱼喜欢野猪人。"
D.Strings[7871]="让我们试试吧……"
D.Strings[7872]="你饿了吗？我抓了一条鱼……"
D.Strings[7873]="$n突袭了兽栏！"
D.Strings[7874]="$n守住了兽栏！"
D.Strings[7875]="联盟夺取了兽栏！"
D.Strings[7876]="部落夺取了兽栏！"
D.Strings[7877]="抓住一个！不知道有没有守卫快要饿扁了。来吧，鱼儿！"
D.Strings[7878]="啊哈！乐意帮忙！"
D.Strings[7879]="我们的中尉有多少还活着，德雷克塔尔？"
D.Strings[7880]="还有多少雷矛军官活着，德雷克塔尔？"
D.Strings[7881]="$n突袭了铁匠铺！"
D.Strings[7882]="联盟夺取了铁匠铺！"
D.Strings[7883]="部落夺取了铁匠铺！"
D.Strings[7884]="$n守住了铁匠铺！"
D.Strings[7885]="$n突袭了农场！"
D.Strings[7886]="联盟夺取了农场！"
D.Strings[7887]="部落夺取了农场！"
D.Strings[7888]="$n守住了农场！"
D.Strings[7889]="干得好！你为部落带来了荣耀，我们感谢你！"
D.Strings[7890]="$n突袭了伐木场！"
D.Strings[7891]="联盟夺取了伐木场！"
D.Strings[7892]="部落夺取了伐木场！"
D.Strings[7893]="$n守住了伐木场！"
D.Strings[7894]="$n突袭了矿洞！"
D.Strings[7895]="$n守住了矿洞！"
D.Strings[7896]="我向你保证：这座峡谷必将是我们的囊中之物。"
D.Strings[7897]="我们有多少指挥官活着，范达尔？"
D.Strings[7898]="我们的中尉有多少还活着，范达尔？"
D.Strings[7899]="还有多少霜狼军官活着，范达尔？"
D.Strings[7900]="雷矛士兵，你们的将军受到攻击！我需要援助！快！快！杀死这些卑鄙的霜狼氏族的成员。"
D.Strings[7901]="雷矛的渣滓！在我的要塞？！杀光他们！"
D.Strings[7902]="嗯……我的鱼杆在哪儿呢？哦，在那儿。"
D.Strings[7903]="让我们看看鱼上钩了没有。"
D.Strings[7904]="特洛克你饿了吗？我在给我们俩做吃的！"
D.Strings[7905]="特洛克？为什么你像个胆小的人类一样跑来跑去？"
D.Strings[7906]="自己的事应该自己做！"
D.Strings[7907]="我在想那些猪是不是饿了……"
D.Strings[7908]="你饿了吗？我这儿有食物……"
D.Strings[7909]="我猜你一定饿啦！特洛克应该在早些时候喂过你的……他都在干什么？"
D.Strings[7910]="救命！一群蜜蜂在追我！"
D.Strings[7911]="我讨厌跑步，但是这些蜜蜂追个不停！"
D.Strings[7912]="为什么它们不喜欢火？"
D.Strings[7913]="卡鲁斯能不能帮我把这些蜜蜂赶走？它们在蜇我！"
D.Strings[7914]="啊……很好。嘘！"
D.Strings[7915]="如你所愿。"
D.Strings[7916]="遵命，长官。"
D.Strings[7917]="如果你是来拯救世界的，那么你来对地方了。无面者——血神哈卡——已经被带回到我们的世界来了！"
D.Strings[7918]="你决心的力量正在闪光，$n。你需要继续证明你对我们的人民来说是一笔宝贵的财产。有一天世界将会意识到你的所做所为是多么的重要。"
D.Strings[7919]="菜鸟英雄又回来啦！很高兴见到你，$n，欢迎回到我们村！"
D.Strings[7920]="我以前认识一个像你这样的……他叫沃金。你属于一个在这里很少见到的族群，我的朋友。"
D.Strings[7921]="真是漫长而艰辛的旅途啊。很少有谁能取得你这样的成就。你是赞达拉帝国的朋友，$n。$B$B传说中的，或许是……是的……或许。"
D.Strings[7922]="爸爸，我能出去收集更多的石头做条项链吗？"
D.Strings[7923]="当然，奥克拉。但是不要离家太远了。"
D.Strings[7924]="好的！我会小心的，爸爸！"
D.Strings[7925]="哦……这块漂亮的岩石。看看我能不能找到更多这样的石料……"
D.Strings[7926]="嗯……那块石头很不错，但是太小了一点。"
D.Strings[7927]="这是块相当不错的岩石，我得把它放到桶里去。好啦，我还需要一些……"
D.Strings[7928]="这石料很适合制作长矛，我敢打赌，我的朋友格鲁克会喜欢的！非常锋利……希望他喜欢。"
D.Strings[7929]="那儿……那儿的石头足够做一条项链啦。无论如何，我现在得回家啦。"
D.Strings[7930]="$n突袭了矿洞！如果不赶快采取行动的话，联盟将在1分钟内占据它！"
D.Strings[7931]="$n突袭了矿洞！如果不赶快采取行动的话，部落将在1分钟内占据它！"
D.Strings[7932]="$n突袭了伐木场！如果不赶快采取行动的话，联盟将在1分钟内占据它！"
D.Strings[7933]="$n突袭了伐木场！如果不赶快采取行动的话，部落将在1分钟内占据它！"
D.Strings[7934]="$n突袭了兽栏！如果不赶快采取行动的话，联盟将在1分钟内占据它！"
D.Strings[7935]="$n突袭了兽栏！如果不赶快采取行动的话，部落将在1分钟内占据它！"
D.Strings[7936]="$n突袭了农场！如果不赶快采取行动的话，联盟将在1分钟内占据它！"
D.Strings[7937]="$n突袭了农场！如果不赶快采取行动的话，部落会在1分钟内控制它！"
D.Strings[7938]="$n突袭了铁匠铺！如果不赶快采取行动的话，联盟将在1分钟内占据它！"
D.Strings[7939]="$n突袭了铁匠铺！如果不赶快采取行动的话，部落将在1分钟内占据它！"
D.Strings[7940]="嗯，我喜欢吃烤陆行鸟！"
D.Strings[7941]="我要开始训练，成为我父亲那样的战士！"
D.Strings[7942]="去找一个鹰身人！"
D.Strings[7943]="那儿！为了部落！"
D.Strings[7944]="看招，你们这些白痴鹰身人！哈哈！"
D.Strings[7945]="你是无法从部落战士手中逃脱的！看招！嘿哈！"
D.Strings[7946]="回到属于你们自己的地方去！"
D.Strings[7947]="啊……部落的又一次荣耀的胜利！"
D.Strings[7948]="莫戈恩，到里面去。你父亲不在了，外面可不太平。"
D.Strings[7949]="马上，妈妈！"
D.Strings[7950]="爸爸什么时候才能从战歌峡谷回来呢？他离开很久啦……"
D.Strings[7951]="不久之后，孩子……不久之后。"
D.Strings[7952]="我们的猪出什么事了？"
D.Strings[7953]="守卫，将囚犯带上来。把他带到禁锢法阵中。"
D.Strings[7954]="立刻就办。"
D.Strings[7955]="跪下，异教徒。"
D.Strings[7956]="奇怪。一个对哈卡莱一无所知的拉斯塔哈的仆从竟然不用古语交谈？"
D.Strings[7957]="跪下！"
D.Strings[7958]="你知道我是谁吗，狂热者？"
D.Strings[7959]="你是个蠢货，一个很快就要死掉的蠢货。不是吗？"
D.Strings[7960]="我只需要动动手指就让你知道我的厉害。不要惹我。"
D.Strings[7961]="真可悲。夺灵者的力量与我同在，除了哈卡神的愤怒，我一无所惧。我只效忠于我真正的主人。"
D.Strings[7962]="那么说来哈卡回来了？"
D.Strings[7963]="这还需要问吗？你感觉不到他吗？万能的拉斯塔哈派遣他的仆从来此是执行外交任务的吗？"
D.Strings[7964]="哦，老家伙，哈卡已经回来了。很快这个世界就会在他的强大力量下崩溃。毁灭。毁灭……"
D.Strings[7965]="我们不会让这种事发生的……我们以前曾经放逐过他，我们会再次放逐他的。"
D.Strings[7966]="%s发疯似的笑起来。"
D.Strings[7967]="愚蠢！你以为自己还拥有大暴动时期的哪怕十分之一的力量吗？所有的部族共同作战，却几乎全部被哈卡的阴影所吞噬。你是没有机会的。"
D.Strings[7968]="现在，那些曾与你们结为盟友的部族已经背弃了你们，与我们站在了一起……没错，老家伙，别那么惊讶。"
D.Strings[7969]="血顶、沙怒、劈颅、邪枝和枯木。他们都发誓效忠我们——他们的灵魂与哈卡同在。你已经输了。"
D.Strings[7970]="时代不同了。年轻的一代将会加入我们。你永远都无法成功。"
D.Strings[7971]="年轻的一代？婴儿？人类？兽人？矮人？你想要击败哈卡莱？你要击败一个神？"
D.Strings[7972]="绝不能发生这种事儿。我们是一支庞大的军团。我们团结一致。你的英雄在哪儿？沃金毫无知觉地陪在年轻的部落酋长身边。祖尔金失踪了，或许已经死了。"
D.Strings[7973]="嗯……你想要打败狂野之神吗？"
D.Strings[7974]="%s傻笑着。"
D.Strings[7975]="狂野之神？不可能！"
D.Strings[7976]="是吗？召唤他们出来啊？"
D.Strings[7977]="%s用食指在脖子上比划了一个砍头的动作。"
D.Strings[7978]="你的神在哪里？在哪里？！"
D.Strings[7979]="打倒我吧。我会重生的……变得更强大……"
D.Strings[7980]="%s垂下肩膀，伸出脖子。"
D.Strings[7981]="%s对着狂热者的尸体吐口水。"
D.Strings[7982]="我要输入10位电子兑换券号码，赢取我的奖品！"
D.Strings[7983]="魔兽世界和可口可乐(R)共同为您带来了这次可口可乐魔兽世界“要爽由自己，冰火暴风城II”夏季促销活动。请检查魔兽世界主题的可口可乐易拉罐底部或瓶装可口可乐的瓶盖内侧，您可以找到一串13位字符。在www.iCoke.cn上输入您得到的13位字符，就有机会赢得iCoke积分，从而得到可以换取魔兽世界幸运礼品的10位电子兑换券。最后，在这里输入您得到的电子兑换券上的10位号码，神秘大奖在等待着您！"
D.Strings[7984]="古斯加入战斗！让我们灭了雷矛的那帮渣子！"
D.Strings[7985]="就是现在，古斯。你要再次展翅高飞！"
D.Strings[7986]="杰斯托来了，雷矛的渣滓们！"
D.Strings[7987]="杰斯托还活着！指挥官，是照亮山谷的时候了。"
D.Strings[7988]="让我来对付他们，$n！只要一声令下，我就会冲出去攻击他们的大桥！"
D.Strings[7989]="我准备好了，先生！只要你一声令下，我将会把地狱火倾泻在他们的基地上！"
D.Strings[7990]="穆维里克，你感觉到了吗？需求？在我下达命令之前你就该有所需求了。我可没跟你开玩笑。滚出去！"
D.Strings[7991]="丹巴达尔来了增援的空中部队！"
D.Strings[7992]="我准备好飞行了，指挥官。只需要你一声令下，我就去把他们的基地夷为平地。"
D.Strings[7993]="拿下这座基地。我们要开始攻城。"
D.Strings[7994]="我会在去霜狼要塞的路上巡逻。只要你一声令下，我就起飞，指挥官。"
D.Strings[7995]="我要你进行外科手术式的精确打击，斯里多尔。把这条路炸平！"
D.Strings[7996]="指挥官，发号令吧。我会彻底粉碎他们的基地！"
D.Strings[7997]="需要战术性压制火力，维波里。火力再猛一些。"
D.Strings[7998]="你好，$c。你愿意帮助战歌峡谷的银翼哨兵作战吗？"
D.Strings[7999]="我想去战场。"
D.Strings[8000]="我来了，霜狼的渣滓们，这次让你们尝尝火焰的滋味！"
D.Strings[8001]="高级空军指挥官维波里，进攻。霜狼氏族，准备受死吧。"
D.Strings[8002]="德雷克塔尔，我来了！"
D.Strings[8003]=S[11745]
D.Strings[8004]="赞美月神！你在寻找我们的战歌峡谷军官？她的名字叫做伊萨拉斯，她就在战士训练师的旁边等着你。"
D.Strings[8005]="你要做的事情需要很大的勇气，$n。要进入战歌峡谷，你就得跟银翼哨兵的军官艾萨拉斯谈谈。她会为你指引方向的。愿女神的祝福与你同在！"
D.Strings[8006]="那么$g小伙子:小姑娘;，你认为你具有在奥特兰克山谷帮助联盟抵御部落的能力？非常好，那么你一定希望和铁炉堡的格罗杜姆·钢须谈谈。你可以在武器大厅的战略沙图之前找到他。"
D.Strings[8007]="啊，奥特兰克山谷，我的美好回忆啊。<叹息>嗯，我不能与你同行，但我同样感到骄傲！你得跟铁炉堡武器大厅的格罗杜姆·钢须谈谈。"
D.Strings[8008]="如果你想要去奥特兰克山谷，去和卡尔特拉·血喉谈谈。你可以在荣耀谷的勇者大厅去找她。"
D.Strings[8009]="我多想和你一起加入伟大的战斗，但是我不得不待在这里值勤。去奥格瑞玛荣誉谷的勇者大厅找卡尔特拉·血喉，她将会帮助你进入奥特兰克山谷。为部落带来荣耀，$n！"
D.Strings[8010]="我命令你把这些入侵者烧成灰烬！"
D.Strings[8011]="%s发出了刺耳的尖啸！"
D.Strings[8012]="请告诉我更多关于可口可乐魔兽世界夏季促销活动的细节。"
D.Strings[8013]="你们永远无法将我赶出我的工事！"
D.Strings[8014]="为什么你们不再试验一次你们那些低贱的手段，娘娘腔？！你们是不是一群懦夫？？"
D.Strings[8015]="可恶的霜狼懦夫！如果你们想要一战的话，就放马，不，放狼过来吧！"
D.Strings[8016]="雷矛的渣滓们，如果你们真的有这么大胆的话，就来我的堡垒中挑战我吧！"
D.Strings[8017]="你们想要把霜狼的将军引出他的要塞？可笑！"
D.Strings[8018]="我永远不会被你那点伎俩算计到，蠢货！如果你想要一战的话，那就到我的地盘来挑战我吧！"
D.Strings[8019]="我是击碎者金罗克，穆贾巴的特使，拉斯塔哈之拳！$B$B我通常只和战士以及异教徒打交道。"
D.Strings[8020]="我弄丢了我的饰物，能给我一个新的吗？"
D.Strings[8021]="我是全知者阿塔比姆，拉斯塔哈的特使。$B$B我通常只和牧师、法师和术士打交道。"
D.Strings[8022]="阿拉索联军发誓为激流堡和联盟夺回阿拉希。这将是一场恶战，但是是一场值得打的战争。"
D.Strings[8023]="要赢得这场战争，我们不能坐在这里，静待战争之潮将我们淹没。我们必须果断出击，否则阿拉希永远也不会成为我们的囊中之物。"
D.Strings[8024]="你应该去战士区找布洛冈·石盾，$c。"
D.Strings[8025]="雷矛卫队需要你的帮助，赶快去参加对抗霜狼氏族的战斗吧，$n！和战士区的布洛冈·石盾谈一谈，他会帮你抵达奥特兰克山谷。赞美艾露恩！"
D.Strings[8026]="有许多战场可供选择，你要去哪一个呢？"
D.Strings[8027]="奥特兰克山谷"
D.Strings[8028]="战歌峡谷"
D.Strings[8029]="银翼哨兵算不上是个可敬的对手，但是如果你对屠杀他们感兴趣，那么就去勇者大厅找布拉古尔吧。"
D.Strings[8030]="你要找哪个战场？"
D.Strings[8031]="你一定是在说泰姆·暴怒图腾。去猎人高地找他。"
D.Strings[8032]="我知道在雷霆崖有人可以帮助你进入奥特兰克山谷。去猎人高地找泰姆·暴怒图腾。希望你找到你希望找的人，$n。"
D.Strings[8033]="猎人大厅的克古尔·血斧将会帮助你进入战歌峡谷。"
D.Strings[8034]="真是无谓的攻击，但是如果银翼要塞的家伙不想要和我们和平相处的话，那么他们还能留给我们什么？去猎人大厅找克古尔·血斧，他将会帮助你进入战歌峡谷。"
D.Strings[8035]="你想要加入哪个战场？"
D.Strings[8036]="那里很冷！你应该去皇家区找格里兹尔谈谈。"
D.Strings[8037]="他的名字叫格里兹尔。他在皇家区和女妖之王和恐惧魔王在一起。"
D.Strings[8038]="小兽人库尔丁·血爪应该在皇家区。"
D.Strings[8039]="战歌峡谷中的精灵们会在你的打击下发出骨头碎裂的声音。去跟皇家区的库尔丁·血爪谈一谈吧。"
D.Strings[8040]="你想去哪个战场？"
D.Strings[8041]="战歌峡谷？好吧，你应该去跟武器大厅的莱兰迪斯谈一谈。"
D.Strings[8042]="任何与部落——特别是兽人——交战的机会都是不容错过的。你可以在战歌峡谷中得到充分的历练，到武器大厅去找莱兰迪斯谈一谈吧，她会送你去战歌峡谷的。"
D.Strings[8043]="嗯，你在找哪个战场？"
D.Strings[8044]="真希望与你同行，$n。去暴风要塞吧，跟国王觐见室的塞尔曼·岩拳谈谈，他会帮助你前往奥特兰克山谷的。"
D.Strings[8045]="银翼要塞需要你的援助。跟暴风要塞觐见室的艾弗拉兰谈谈。"
D.Strings[8046]="银翼哨兵运用一切援助对抗战歌前锋。$n，如果你想要帮助他们的话，就去暴风要塞找艾弗拉兰谈谈。"
D.Strings[8047]="你对哪个战场感兴趣？"
D.Strings[8048]="%s完全被烈焰吞噬了，他的双眼射出了疯狂的光芒！"
D.Strings[8049]="你想要什么？$B$B梅维克只跟德鲁伊和萨满祭司往来。"
D.Strings[8050]="梅维克，我把坠饰弄丢了，想再要一份。"
D.Strings[8051]="你好，$c。眼下正是收获节——感恩与追思的季节。我们举办盛宴感激所有我们应该感激的人，追忆我们的祖先和英雄，感谢他们给我们留下的宝贵遗产。$B$B请尽情享受这盛宴吧。我还会燃放焰火助兴。"
D.Strings[8052]="让我看看你的焰火。"
D.Strings[8053]="我们绝不能让联盟在阿拉希扩张势力！既便是小小的避难谷地，在将来也可能对我们形成威胁。"
D.Strings[8054]="阿拉希盆地的战斗是一场谋略战。木材、矿石、食物……所有这些物资对战斗来说都是必需品。$B$B销毁敌方的物资跟在战场上杀死他们一样重要。"
D.Strings[8055]="我眼睛瞎了，但是我还拥有洞察力。$B$B我主要跟猎人和潜行者打交道，$r。"
D.Strings[8056]="你很快就会没命了！"
D.Strings[8057]="我要把你的魔精抽干！"
D.Strings[8058]="你的头骨将用于装饰我们的祭坛！"
D.Strings[8059]="巨魔的魔精是最好的！"
D.Strings[8060]="尝尝巫毒的力量！"
D.Strings[8061]="冒险者，你好。我是赞达拉的商人林沃斯。我来自南海，从我的家乡带来了许多新奇的货物。$B$B如果你能证明自己的价值，我会乐意与你交换物品的。如果你有我们部族的荣誉勋章，我这里还有些更好的东西……"
D.Strings[8062]="林沃斯，让我看看你有什么货物！"
D.Strings[8063]="林沃斯，我需要修理服务。"
D.Strings[8064]="沙德拉，让我成为你的化身！"
D.Strings[8065]="我们不会失败的！"
D.Strings[8066]="%s完全成长了！"
D.Strings[8067]="投降吧，虫子。我将把你们献给哈卡！"
D.Strings[8068]="骄傲会将你送上绝路。来吧，凡人！品尝夺灵者的愤怒吧！"
D.Strings[8069]="来为我作战吧，我的孩子们！"
D.Strings[8070]="朋友，欢迎参加这场盛宴。来吧，狂欢至死吧！"
D.Strings[8071]="我终于摆脱了夺灵者的束缚！"
D.Strings[8072]="哈卡再也不能束缚我了！我终于可以安息了！"
D.Strings[8073]="必然的结局……死亡！诅咒你，哈卡！诅咒你！"
D.Strings[8074]="%s被附近的盟友复活了！"
D.Strings[8075]="西瓦尔拉，让我感受你的愤怒吧！"
D.Strings[8076]="这是真的，$n。厄运的车轮开始运转，一切都无可避免，哈卡将重返世间！"
D.Strings[8077]="鲜血和灵魂，为了哈卡而战！哈哈哈！"
D.Strings[8078]="贝蒂娜，我想要黎明之印的替代物品！"
D.Strings[8079]="我祝福你，凡人。你给了我自由……哈卡再也无法控制我了！"
D.Strings[8080]="宁静……终于来临了！"
D.Strings[8081]="贝瑟克，你的祭司在召唤你的力量！"
D.Strings[8082]="贝蒂娜，我想要黎明符文的替代物品！"
D.Strings[8083]="我是赞达拉的赞扎。我以灵体形态从赞达拉赶来帮助我的人民。哈卡不能控制我的灵魂。$B$B我是来帮助那些曾经有恩于赞达拉的朋友的。"
D.Strings[8084]="赞达拉的朋友！你已经去过了血神巢穴的深处，$c。你最好仔细听我说。$B$B数千年前，当祖拉曼帝国的巨魔与入侵的高等精灵异教徒作战时，高等精灵盗取了赞扎的强大魔法，在自己的武器和护甲上附魔，以此征服当地的巨魔。"
D.Strings[8085]="我想我听说过这种魔法。"
D.Strings[8086]="是吗？这么说你已经知道高等精灵所掌握的巨魔魔法有多么浅显了？$B$B高等精灵怎么都想不明白，作为一个与魔法密切相关的种族，他们为何无法驾驭巨魔巫毒的力量。对这些白皮肤的生灵而言，这简直难以置信。他们只好使用一种不纯的巨魔法术来增强他们的魔法力量。我想他们称其为“秘药”。"
D.Strings[8087]="秘药？听起来很耳熟呢。"
D.Strings[8088]="赞扎能制造古老的附魔物品。这种魔法可以帮助你打败哈卡和他的爪牙。$B$B我只要你帮我找3种东西。我承认有一样东西不是必需的，但是我想净化那些高等精灵的魔法。"
D.Strings[8089]="我需要些什么？"
D.Strings[8090]="首先，必须要有一个从最强大的哈卡莱信徒那里夺来的原始哈卡莱神像，去打败金度和血领主曼多基尔吧！$B$B然后，还要有一个打孔的巫毒人偶。你可以在这一带的垃圾堆中找到它们，多留意一下那些厄运巫毒堆。把这些东西都给我拿来，我就给你一种强大的附魔！"
D.Strings[8091]="很抱歉，$c，在你变得更加强大之前，我不能让你去战歌峡谷送死。"
D.Strings[8092]="吞噬$n的躯体吧！"
D.Strings[8093]="我们就要摆脱夺灵者的威胁了，只差最后一步……"
D.Strings[8094]="开始仪式，我的仆从们。我们必须把哈卡完全打回扭曲虚空中！"
D.Strings[8095]="欢迎参加藏宝海湾钓鱼比赛，每周我们都会向全艾泽拉斯最好的渔夫发放奖励。\n\n钓鱼比赛开始后，你在荆棘谷的任何渔点都可以钓到可口鱼。"
D.Strings[8096]="你好，$c。我是拉斯塔哈的仆从伊克萨尔。"
D.Strings[8097]="战斗将在1分钟后开始。"
D.Strings[8098]="战斗将在30秒后开始。"
D.Strings[8099]="不要误入凡人设下的陷阱。沐浴我的力量吧！恢复精力，消灭异教徒！"
D.Strings[8100]="很抱歉，$c，在你变得更加强大之前，我不能让你去奥特兰克山谷送死。"
D.Strings[8101]="权力珍宝是什么？"
D.Strings[8102]="权力珍宝是古代古拉巴什帝国的遗物。赞达拉部族正在寻找它们——它们不仅有着极大的收藏价值，而且我们相信它们还蕴藏着远古帝国的魔法。$B$B你可以在祖尔格拉布找到三种权力珍宝：硬币、珠宝和原始神灵的物品。收集到一定数量之后，把这些东西交给我们，我们就会送你一些赞达拉最好的工艺制品。"
D.Strings[8103]="石板上篆刻着古老的图案，上面的文字蕴涵着可怕的力量，但是你无法理解它们的意思。"
D.Strings[8104]="石板上篆刻着古老的图案，上面的文字蕴涵着可怕的力量，用来制造Gurubashi Mojo Madness……"
D.Strings[8105]="学习配方。"
D.Strings[8106]="石板上篆刻着古老的图案，上面的文字蕴涵着可怕的力量。$B$B你相信这是一份炼金术配方，但是以你的技能还无法学习……"
D.Strings[8107]="在我看来，钓鱼的美妙之处在于其缓慢的节奏。人们可以在钓鱼的过程中思考、回想过去和计划未来。$B$B哦，当然这也是大醉的托辞。"
D.Strings[8108]="再次感谢你找回了我的幸运卷尺，$n。这东西能帮我捕到更大的鱼呢！"
D.Strings[8109]="我要抓住加兹兰卡！告诉我怎么样才可以抓住它！"
D.Strings[8110]="你需要一种特殊的臭泥鱼诱饵来捕捉加兹兰卡，这些鱼饵是我亲自制作的！$B$B但是除了鱼饵之外，你还需要臭泥鱼……你得把臭泥鱼放入诱饵，让它充满臭味！$B$B将做好的诱饵放到祖尔格拉布中的帕格渔点……然后就坐下来喝酒等待……你无需等太久，因为加兹兰卡肯定会迫不及待地上钩！"
D.Strings[8111]="纳特，我想要购买一些臭泥鱼诱饵！"
D.Strings[8112]="*吱吱**叮当*\n\n我奉命收购肥美的稀有鱼类，用纳特·帕格的钓鱼用品来交换哦。收购鱼类啦。\n\n*砰**嗡嗡*"
D.Strings[8113]="%s开始释放强效治疗术！"
D.Strings[8114]="很抱歉，$c，在你变得更加强大之前，我不能让你去阿拉希盆地送死。"
D.Strings[8115]="钢铁之血格里雷克$B$B游荡者。愿他的力量和对战争的渴望生生不息。$B$B格里雷克正在遥远的地方徘徊。总有一天，他会回来的……"
D.Strings[8116]="阿拉希盆地"
D.Strings[8117]="去勇者大厅找污染者迪兹·斯诺班，他会帮助你进入阿拉希盆地的。"
D.Strings[8118]="你想要帮助阿拉希盆地的被遗忘者打败人类吗？那就去勇者大厅找迪兹·斯诺班谈谈。"
D.Strings[8119]="我要怎么样才能捕捉到鱼饵所需的臭泥鱼？"
D.Strings[8120]="臭泥鱼是一种散发着特殊臭味的鱼，它们生活在热带水域中。祖利安臭泥鱼则是其中最臭的一种，只有在祖尔格拉布的水域中才能找到。$B$B我想一定是祖利安臭泥鱼引来了加兹兰卡，尽管巨魔会告诉你它是巨魔膜拜的众多神灵之一，但是……$B$B相信自己——用祖利安臭泥鱼制成的诱饵去捕捉加兹兰卡吧，那家伙肯定会上钩的！"
D.Strings[8121]="去圣殿区找玛洛维尔爵士。"
D.Strings[8122]="阿拉希盆地是从人类手中夺来的。玛洛维尔爵士会把你送到那儿的。"
D.Strings[8123]="你的死亡就是我的力量！"
D.Strings[8124]="去灵魂高地下面的预见之池找马丁·林塞。他会帮助你前往阿拉希盆地。"
D.Strings[8125]="你想要帮助阿拉希盆地的污染者打败阿拉索联军吗？很好，去预见之池找马丁·林塞寻求帮助吧。"
D.Strings[8126]="在阿拉希盆地跟被遗忘者作战的人类需要你的帮助。去武器大厅找他们的代表杜纳尔·奥斯古德谈谈。"
D.Strings[8127]="阿拉索联军试图从被遗忘者手中夺回自己的失地。$n，如果你想要帮助他们的话，就跟武器大厅的杜纳尔·奥斯古德谈谈。"
D.Strings[8128]="你可以在国王的觐见室中找到赫塔希姆。她能帮助你前往阿拉希盆地，阿拉索联军需要援助来打败污染者。"
D.Strings[8129]="阿拉索联军在阿拉希盆地所做的一切令人敬佩。可惜亡灵憎恶和他们的部落盟友挡住了去路。去暴风要塞国王的觐见室找赫塔希姆吧，她会帮助你前往阿拉希盆地。"
D.Strings[8130]="阿拉希盆地的人类急需我们的帮助。你得找战士区的克拉斯·沃夫哈特谈谈，他会帮助你的。"
D.Strings[8131]="$c，如果那就是你的愿望，那么去战士区找克拉斯·沃夫哈特谈谈。他是阿拉索联军的代表，能帮助你到达阿拉希盆地。"
D.Strings[8132]="你好，$c！你准备参加战歌峡谷的战斗了吗？为了部落！"
D.Strings[8133]="你好，$n。让我帮你前往战歌峡谷，好吗？"
D.Strings[8134]="$n，必须消灭银翼哨兵！你做好进入战歌峡谷的准备了吗？"
D.Strings[8135]="你是来帮助我们在战歌峡谷作战的吗？为了部落，$c！"
D.Strings[8136]="$C，战歌峡谷需要援助。你能帮助我们攻打战歌前锋吗？"
D.Strings[8137]="$g小伙子:姑娘;，你准备好动身前往奥特兰克山谷了吗？让部落尝尝失败的滋味！"
D.Strings[8138]="$n，你对我们在奥特兰克山谷的处境有什么想法？你准备好跟霜狼氏族作战了吗？"
D.Strings[8139]="必须杀死雷矛卫兵！准备在奥特兰克山谷开战，准备好了吗，$c?"
D.Strings[8140]="为了部落，$c！奥特兰克山谷需要你。"
D.Strings[8141]="我们在奥特兰克山谷的军队需要运用谋略获胜，$c。你看起来是个不错的领导者。"
D.Strings[8142]="希望你是来奥特兰克山谷作战的，$n。我们会竭尽所能，利用一切援助。"
D.Strings[8143]="人类和他们所谓的阿拉索联军想把我们赶出阿拉希盆地。我可不这么想，$c！你得动身前往那儿，证明该离开阿拉希盆地的是他们而不是污染者，准备好了吗？"
D.Strings[8144]="阿拉希盆地曾经是我们的家园，有了你的帮助，我们会收复失地的！你愿意帮助我们吗，$c？"
D.Strings[8145]="希望你是来帮助我们从污染者手中夺回阿拉希盆地的，$n？"
D.Strings[8146]="我一直在盼着你呢，$n。我们在阿拉希盆地的战斗需要你的帮助，你准备好了吗？"
D.Strings[8147]="你认为你能摧毁阿拉索联军吗，$c？希望如此。你究竟是想要干些什么呢，还是根本就是来浪费我的时间的？"
D.Strings[8148]="看看四周，$c。你身边的朋友并不多，我想你需要证明自己的价值。嗯，或许我应该同意你帮助我们在阿拉希盆地作战。你愿意吗？"
D.Strings[8149]="向你致敬，$n，杀死哈卡的勇士，艾泽拉斯的英雄！"
D.Strings[8150]="钢铁之血格里雷克$B$B游荡者。愿他的力量和对战争的渴望生生不息。$B$B格里雷克就在疯狂之缘那边……"
D.Strings[8151]="织梦者哈扎拉尔。$B$B他他拥有噩梦的力量，愿他的敌人永远沉睡。$B$B哈扎拉尔正在遥远的地方徘徊。总有一天，他会回来的……"
D.Strings[8152]="织梦者哈扎拉尔。$B$B他拥有噩梦的力量，愿他的敌人永远沉睡。$B$B哈扎拉尔就在疯狂之缘那边。"
D.Strings[8153]="千刃之王雷纳塔基。$B$B痛苦是他的生命。恐怖是他的伙伴。愿他早日重返世间。$B$B雷纳塔基正在遥远的地方徘徊。总有一天，他会回来的……"
D.Strings[8154]="千刃之王雷纳塔基。$B$B痛苦是他的生命。恐怖是他的伙伴。愿他早日重返世间。$B$B雷纳塔基就在疯狂之缘那边。"
D.Strings[8155]="雷巫乌苏雷。$B$B她拥有天空、雨水和大地的力量。愿她再次统治古拉巴什。$B$B乌苏雷正在遥远的地方徘徊。总有一天，她会回来的……"
D.Strings[8156]="雷巫乌苏雷。$B$B她拥有天空、雨水和碎泥的力量。愿她再次统治古拉巴什。$B$B乌苏雷就在疯狂之缘那边。"
D.Strings[8157]="%s看到他的迅猛龙在战斗中丧命后勃然大怒！"
D.Strings[8158]="哈卡的仆从，听从主人的召唤！圣洁的神庙已经受到威胁。神圣的土地已经被入侵者占领！誓死保护血神祭坛，杀死所有的入侵者！"
D.Strings[8159]="嘿嘿嘿！我在这里是为了推广荆棘谷的超级无敌钓鱼锦标赛的。不过你首先得有足够的生存能力在这里活下去，然后还需要足够在这里钓鱼的精湛技巧。$B$B当你更符合以上条件的时候再回到这里来吧！"
D.Strings[8160]="嗨！嗨！嗨！如果你想要试试自己的钓鱼技能，那么你来对地方啦！本周日荆棘谷将举办一场钓鱼大赛！"
D.Strings[8161]="%s迅速逃窜至另一只老虎处寻求庇护。"
D.Strings[8162]="你对古拉巴什帝国至高无上的权力表现出的轻蔑态度已是臭名昭著。祖尔格拉布的居住者已经对你有所警惕了。"
D.Strings[8163]="你还不够强大，$C。继续努力吧。"
D.Strings[8164]="$n，阿拉希盆地急需增援。在这危急时刻，正是获得荣誉、提升声望的大好机会。我恳求你去城中寻找阿拉希盆地的军官。"
D.Strings[8165]="我想参加战斗！"
D.Strings[8166]="你能这么问我很高兴。你可以在黑暗女王所在的皇家区找到玛洛维尔爵士。"
D.Strings[8167]="当然，当然。$C，跟荣誉谷勇者大厅的迪兹·斯诺班谈谈吧。"
D.Strings[8168]="你一定能获得无上的荣耀。跟预见之池的马丁·林塞谈谈，就在灵魂高地旁的洞穴中。"
D.Strings[8169]="你需要变得更强大，才能帮助我们在奥特兰克山谷作战，$c。"
D.Strings[8170]="嗨，$C。眼下奥特兰克山谷急需援助，这是获得荣誉、提升声望的大好机会。你愿意加入我们，共同对抗雷矛卫队吗？"
D.Strings[8171]="向你的先祖致敬，$C！你可以去荣誉谷的勇士大厅找卡尔特拉·血喉。"
D.Strings[8172]="你的名字将世代相传，永垂不朽，$n。去猎人高地找泰姆·暴怒图腾，他会帮助你前往奥特兰克山谷。"
D.Strings[8173]="很好，$n。你可以在幽暗城的皇家区找到格里兹尔。愿你在奥特兰克山谷获得更多的荣耀。"
D.Strings[8174]="很不幸，你还很年轻，无法在战歌峡谷中存活，$C。"
D.Strings[8175]="$C，战歌峡谷急需增援，帮助我们对抗银翼哨兵吧。在那里你可以赢得战歌前锋部队的尊敬！你有勇气加入战斗吗？"
D.Strings[8176]="我要骄傲地告诉你，布拉古尔就在武器大厅，他可以帮助你前往战歌峡谷。去荣誉谷找他吧。"
D.Strings[8177]="你的选择很明智，$n。去猎人高地找克古尔·血斧。他会帮助你前往战歌峡谷的。"
D.Strings[8178]="$C，荣誉和荣耀都将属于你！去皇家区找库尔丁·血爪吧。"
D.Strings[8179]="恐怕你在奥特兰克山谷中活不了多久，$C。等你更加强大一些再回来吧。"
D.Strings[8180]="$n，眼下，奥特兰克山谷的雷矛卫队需要你助战，共同打败霜狼氏族。这是个获得荣誉、提升声望的大好机会！你想要参加战斗吗？"
D.Strings[8181]="$n，布洛冈·石盾在战士区，他能帮助你前往奥特兰克山谷。"
D.Strings[8182]="钓鱼大师巴斯贝特已经在这片水域中放入了美味的可口鱼，钓鱼比赛可以开始啦。\n\n一旦决出了获胜者，我就会按五条可口鱼换一银币的价格收购其余的可口鱼！"
D.Strings[8183]="你做出了正确的选择，$C。你可以在武器大厅找到军官格罗杜姆·钢须。祝你好运，$n！"
D.Strings[8184]="很好，$C！你可以去暴风要塞的皇家觐见室找军官塞尔曼·岩拳。他会帮助你前往奥特兰克山谷。"
D.Strings[8185]="感谢你的帮助，$C。不幸的是，你的经验不够丰富，无法承受阿拉希盆地的险恶环境。"
D.Strings[8186]="阿拉希盆地急需增援，你能帮助我们吗，$C？这是个获得荣誉、提升声望的大好机会。你的帮助定能扭转局势，帮助我们打败污染者。我们能将希望寄托到你身上吗？"
D.Strings[8187]="谢谢你，$n！你可以在战士区的训练师附近找到克拉斯·沃夫哈特。他会指引你前往阿拉希盆地。祝你好运，那会是一场荣誉之战。"
D.Strings[8188]="我们欠你一个人情，$C。去武器大厅找杜纳尔·奥斯古德，他会乐意帮助你前往阿拉希盆地的。"
D.Strings[8189]="太好了！在阿拉希盆地一役中，你将帮助阿拉索联军战胜污染者和部落那群乌合之众。去暴风要塞的皇家觐见室找赫塔希姆吧。她正等着你呢，$n。"
D.Strings[8190]="你让我获得了自由！为我复仇吧！"
D.Strings[8191]="四季轮回变幻，但是你年纪尚轻。当你经历更多之后再来找我们吧，$C。"
D.Strings[8192]="$C，战歌峡谷迫切需要增援。如果你愿意助我们一臂之力的话，你将获得前所未有的荣誉。银翼哨兵对你的所做所为也会表示敬意。你愿意加入战斗吗？"
D.Strings[8193]="愿月神之光照耀你，$n！你可以在战士区找到军官伊萨拉斯。她将帮助你前往战歌峡谷。"
D.Strings[8194]="你显示出与你的年龄不相符的智慧，$C。谢谢你。你可以在武器大厅找到军官莱兰迪斯，她能帮助你前往战歌峡谷。"
D.Strings[8195]="权力珍宝是古拉巴什帝国的遗物。赞达拉氏族正在寻找权力珍宝——它们不仅具富收藏价值，赞达拉氏族还相信它们含有远古帝国使用的强效魔精。$B$B你可以在祖尔格拉布找到三种权力珍宝：硬币、宝石和原始物品。一旦你收集到一定数量的权力珍宝，你将获得赞达拉氏族制作的最好的物品。$B$B奖励丰厚，值得一试！"
D.Strings[8196]="银翼哨兵欠你一份情，$C。你可以在暴风要塞的皇家觐见室找到军官艾弗拉兰。愿女神保佑你！"
D.Strings[8197]="你将遭遇恒久的痛苦，$R。"
D.Strings[8198]="哈卡将统治世界！"
D.Strings[8199]="你得做出适当的牺牲。"
D.Strings[8200]="交出你的灵魂吧，凡人。"
D.Strings[8201]="在我的统治下，这个世界将遭遇难以想象的惨剧。"
D.Strings[8202]="你的神现在救不了你了，$C。"
